defmodule OrbitalDynamics.CampaignPlanner do
  @moduledoc """
  Deterministic campaign planner for LEO constellation studies.

  The planner consumes propagated event products and emits a compact,
  reproducible plan artifact. V1 deliberately uses transparent greedy timeline
  selection over candidate observation and contact windows instead of hidden
  optimization machinery.

  V2 adds a rolling repair pass over a prior campaign artifact. It compares the
  prior plan against realized operations, preserves approved or executed work
  where policy allows, and repairs the remaining horizon from the prior
  candidate windows.

  V3 compares explicit future branches from a common mission-state snapshot,
  reuses V2 repair inside each branch, and recommends a strategy with
  campaign-level tradeoffs and approval boundaries.
  """

  alias OrbitalDynamics.Communications.{
    CommandWindow,
    ContactContention,
    ContactAllocation,
    ContactFilter,
    ContactIntent,
    LinkCapacity,
    StationCalendar
  }

  alias OrbitalDynamics.Constraints.CampaignLocal, as: CampaignLocalConstraint
  alias OrbitalDynamics.EventDetectors.Eclipses
  alias OrbitalDynamics.Study.Manifest

  alias OrbitalDynamics.{
    CandidateRefresh,
    CadenceImport,
    Optimizer,
    OperatorReview,
    OperationalReadiness,
    Policy,
    ResultSet,
    ResourceFilter,
    ResourceProjection,
    ResourceSummary,
    Schema,
    StudyRunner,
    Timeline,
    TimelineFeedback
  }

  @schema_version 1
  @repair_schema_version 2
  @strategy_schema_version 3
  @stable_id_regex ~r/^[A-Za-z0-9][A-Za-z0-9._:@-]*$/
  @realized_completion_statuses ~w(completed executed)
  @realized_preserved_executed_statuses @realized_completion_statuses ++ ~w(partial)
  @realized_failure_statuses ~w(missed failed canceled cancelled rejected)
  @realized_statuses @realized_preserved_executed_statuses ++
                       @realized_failure_statuses ++ ~w(delayed)
  @terminal_realized_statuses @realized_preserved_executed_statuses ++ @realized_failure_statuses
  @realized_feedback_match_statuses ~w(matched)
  @command_health_activity_types ~w(command health_check)
  @unavailable_station_tokens ~w(unavailable maintenance outage offline down)
  @resource_availability_true_tokens ~w(true 1 yes y available nominal operational enabled)
  @resource_availability_false_tokens ~w(false 0 no n unavailable offline down outage maintenance disabled)
  @provider_result_map_value_keys ~w(result results outcome outcomes status state disposition provider_result provider_results provider_outcome provider_outcomes provider_status provider_state provider_code code reason reasons message messages error errors details metadata provider diagnostics)
  @score_report_model_limits [
    "deterministic_score_explainability_only",
    "score_policy_supplied_by_request",
    "no_solver_execution",
    "not_calibrated_from_operational_outcomes"
  ]
  @objective_satisfaction_model_limits [
    "selected_activity_summary_only",
    "planned_not_executed",
    "no_solver_execution",
    "not_calibrated_from_operational_outcomes"
  ]
  @branch_comparison_model_limits [
    "deterministic_branch_score_explainability_only",
    "branch_probabilities_are_input_confidence_multipliers",
    "no_autonomous_execution",
    "score_terms_are_planning_heuristics"
  ]
  @realized_state_snapshot_model_limits [
    "provider_feedback_snapshot_only",
    "no_ground_truth_reconstruction",
    "no_schedule_mutation",
    "no_subsystem_state_estimation"
  ]

  @doc """
  Returns the declared model limits for score explanation reports.
  """
  def score_report_model_limits, do: @score_report_model_limits

  @doc """
  Returns the declared model limits for objective satisfaction reports.
  """
  def objective_satisfaction_model_limits, do: @objective_satisfaction_model_limits

  @doc """
  Returns the declared model limits for branch comparison reports.
  """
  def branch_comparison_model_limits, do: @branch_comparison_model_limits

  @doc """
  Returns the declared model limits for realized state snapshot reports.
  """
  def realized_state_snapshot_model_limits, do: @realized_state_snapshot_model_limits

  @event_timing_keys [
    :interpolation,
    :boundary_refinement,
    :start_boundary,
    :end_boundary,
    :start_boundary_detail,
    :end_boundary_detail,
    :event_timing_policy,
    :event_detector,
    :event_time_tolerance_s,
    :max_sample_step_s,
    :confidence
  ]

  defmodule RealizedActivity do
    @moduledoc """
    Realized operational outcome for one planned activity or contact.
    """

    @enforce_keys [:id, :status]
    defstruct [
      :id,
      :status,
      :actual_starts_at_s,
      :actual_ends_at_s,
      :completed_fraction,
      :reason,
      metadata: %{}
    ]
  end

  defmodule RepairPolicy do
    @moduledoc """
    Policy knobs for campaign-plan repair.
    """

    defstruct preserve_approved?: true,
              preserve_executed?: true,
              allow_locked_changes?: false,
              schedule_churn_cost_weight: 100.0,
              schedule_move_cost_weight: 0.01,
              degraded_payload_activity_types: ["observe"],
              command_health_activity_types: ["command", "health_check"]
  end

  defmodule PlanDelta do
    @moduledoc """
    Planned-vs-realized comparison row.
    """

    @enforce_keys [:activity_id, :activity_type, :status]
    defstruct [
      :activity_id,
      :activity_type,
      :status,
      :planned,
      :realized,
      :repair_action,
      :reason,
      :replacement_activity_id,
      :source_timeline_id,
      :replacement_timeline_id,
      :timeline_link,
      :source_activity_context,
      :replacement_activity_context,
      :realized_feedback_rows,
      :realized_feedback_count,
      :requires_approval
    ]
  end

  defmodule ReplanRequest do
    @moduledoc """
    Input object for rolling campaign repair.
    """

    @enforce_keys [:prior_plan, :realized_state, :current_epoch_s]
    defstruct [
      :prior_plan,
      :mission_state,
      :realized_state,
      :current_epoch_s,
      :remaining_horizon,
      :constraints,
      :scoring_policy,
      :repair_policy,
      :approval_policy,
      :candidate_refresh,
      :candidate_refresh_request,
      :ground_network,
      :generated_at,
      metadata: %{}
    ]
  end

  defmodule ReplanResult do
    @moduledoc """
    JSON-serializable V2 repair artifact wrapper.
    """

    @enforce_keys [:artifact]
    defstruct [:artifact]
  end

  defmodule MissionState do
    @moduledoc """
    Living constellation state snapshot used by V3 branch strategy evaluation.
    """

    @enforce_keys [:snapshot_id]
    defstruct [
      :snapshot_id,
      :captured_at,
      spacecraft_states: [],
      ground_network: [],
      ground_stations: [],
      targets: [],
      accepted_planning_state: nil,
      candidate_refresh_defaults: %{},
      resources: %{},
      resource_summaries: [],
      degradations: [],
      objectives: [],
      timeline_feedback_report: nil,
      operational_feedback: %{},
      prior_plan_history: [],
      operational_status: %{},
      assumptions: %{}
    ]
  end

  defmodule WhatIfScenario do
    @moduledoc """
    Explicit future assumptions for one V3 branch.
    """

    @enforce_keys [:id]
    defstruct [
      :id,
      :label,
      probability: 1.0,
      events: [],
      policy_overrides: %{},
      realized_state_overrides: %{},
      metadata: %{}
    ]
  end

  defmodule PlanBranch do
    @moduledoc """
    Evaluated V3 future branch.
    """

    @enforce_keys [:id, :repair_result, :score, :score_terms]
    defstruct [
      :id,
      :label,
      :probability,
      :repair_result,
      :score,
      :score_terms,
      events: [],
      candidate_plan: %{},
      warnings: [],
      risk_indicators: [],
      approval_status: "operator_review_required",
      approval_requirements: [],
      approval_rule_matches: [],
      policy_decision: %{},
      derived_source: nil,
      resource_impacts: %{},
      resource_projection_report: nil,
      feedback_adjustments: %{},
      objective_satisfaction: %{},
      feasibility_summary: %{},
      assumptions: %{},
      provenance: %{},
      tradeoffs: []
    ]
  end

  defmodule StrategyRecommendation do
    @moduledoc """
    Ranked branch recommendation with explicit tradeoffs and approval boundary.
    """

    @enforce_keys [:recommended_branch_id, :approval_status, :reason]
    defstruct [
      :recommended_branch_id,
      :approval_status,
      :reason,
      ranked_branch_ids: [],
      tradeoffs: [],
      explanation: [],
      risks_remaining: [],
      requires_approval: []
    ]
  end

  defmodule StrategicScoringPolicy do
    @moduledoc """
    Campaign-level scoring weights for V3 branch comparison.
    """

    defstruct mission_value_weight: 1.0,
              coverage_weight: 25.0,
              revisit_weight: 5.0,
              latency_weight: 0.01,
              downlink_completion_weight: 50.0,
              fuel_preservation_weight: 25.0,
              schedule_stability_weight: 1.0,
              asset_balance_weight: 10.0,
              priority_commitment_weight: 50.0,
              risk_weight: 100.0,
              approval_load_weight: 20.0,
              probability_weight: 1.0
  end

  defmodule ApprovalPolicy do
    @moduledoc """
    Human-approval boundary policy for V3 recommendations.
    """

    defstruct auto_approvable_risk_limit: 0,
              auto_approvable_approval_count_limit: 0,
              operator_review_risk_limit: 3,
              blocked_risk_types: [
                "spacecraft_degraded_unprotected",
                "no_viable_downlink",
                "storage_overflow",
                "downlink_shortfall"
              ],
              action_rules: []
  end

  defmodule OperationalFeedback do
    @moduledoc """
    Thin calibration inputs from prior operations.
    """

    defstruct contact_success_rate: %{},
              observation_success_rate: %{},
              image_quality_score: %{},
              image_quality_status: %{},
              image_quality_source: %{},
              cloud_cover_fraction: %{},
              blur_score: %{},
              maneuver_success_rate: %{},
              maneuver_execution_uncertainty: %{},
              command_success_rate: %{},
              station_throughput_factor: %{},
              downlink_demand_mb: %{},
              target_priority_overrides: %{},
              resource_margin_overrides: %{},
              resource_availability_overrides: %{},
              availability_overrides: %{}
  end

  @doc """
  Builds a campaign-plan artifact from a completed result set.
  """
  def build(%ResultSet{} = result_set, opts \\ []) do
    campaign = Keyword.fetch!(opts, :campaign)
    generated_at = Keyword.get_lazy(opts, :generated_at, &DateTime.utc_now/0)
    policy = Map.get(campaign, "scoring_policy", %{})
    constraints = Map.get(campaign, "constraints", %{})

    sorted_candidates =
      result_set.event_results
      |> candidate_activities(campaign, constraints, policy)
      |> Enum.sort_by(&{&1["scenario_id"], &1["starts_at_s"], &1["id"]})

    {calendar_candidates, station_calendar_report} =
      apply_station_calendar(sorted_candidates, campaign)

    {resource_candidates, resource_filter_report} =
      apply_campaign_resource_filters(calendar_candidates, campaign)

    {candidates, contact_contention_report} = annotate_contact_contention(resource_candidates)
    contact_allocation_report = contact_allocation_report(candidates, campaign)

    timelines =
      candidates
      |> Enum.group_by(& &1["scenario_id"])
      |> Enum.map(fn {scenario_id, scenario_candidates} ->
        ranked_timeline(scenario_id, scenario_candidates, constraints, policy)
      end)
      |> Enum.sort_by(&{-candidate_score(&1), &1["scenario_id"]})
      |> Enum.take(policy_count_value(policy, "rank_limit", 10))

    best_timeline = List.first(timelines)
    selected_activities = if best_timeline, do: best_timeline["activities"], else: []
    approval_policy = Map.get(campaign, "approval_policy") || Map.get(campaign, :approval_policy)
    contact_intents = ContactIntent.from_activities(candidates, approval_policy: approval_policy)
    plan_id = plan_id(result_set.study_id, generated_at)

    link_capacity_report =
      link_capacity_report(
        candidates,
        selected_activities,
        campaign_link_capacity_policy(campaign, policy),
        "campaign_plan.candidate_activities",
        approval_policy
      )

    resource_projection_report =
      campaign_resource_projection_report(selected_activities, campaign)

    resource_projection_flow_summary =
      resource_projection_flow_summary(resource_projection_report)

    timeline_activity_precondition_summaries =
      timeline_activity_precondition_summaries(selected_activities)

    timeline_integrity_report =
      timeline_integrity_report(selected_activities)

    optimizer_contract =
      Optimizer.greedy_timeline_contract(candidates, timelines,
        plan_id: plan_id,
        constraints: constraints,
        scoring_policy: policy
      )

    %{
      "schema_version" => @schema_version,
      "generated_at" => DateTime.to_iso8601(generated_at),
      "planner" => "OrbitalDynamics.CampaignPlanner.V1",
      "plan_id" => plan_id,
      "study_id" => encode_value(result_set.study_id),
      "planning_horizon" => Map.get(campaign, "planning_horizon", %{}),
      "activities" => selected_activities,
      "proposed_contacts" => proposed_contacts(candidates),
      "contact_intents" => contact_intents,
      "contact_filter_report" => contact_filter_report(candidates),
      "resource_filter_report" => resource_filter_report,
      "station_calendar_report" => station_calendar_report,
      "contact_contention_report" => contact_contention_report,
      "contact_contention_resolution_report" =>
        contact_contention_resolution_report(candidates, contact_contention_report, campaign),
      "contact_allocation_report" => contact_allocation_report,
      "link_capacity_report" => link_capacity_report,
      "resource_projection_report" => resource_projection_report,
      "resource_projection_flow_summary" => resource_projection_flow_summary,
      "timeline_activity_precondition_summaries" => timeline_activity_precondition_summaries,
      "timeline_integrity_report" => timeline_integrity_report,
      "target_commitments" => target_commitments(campaign, candidates, selected_activities),
      "objective_satisfaction_report" =>
        objective_satisfaction_report(campaign, candidates, selected_activities),
      "operational_timeline_report" => operational_timeline_report(selected_activities),
      "command_window_report" =>
        CommandWindow.report(selected_activities,
          source: "campaign_plan.activities",
          source_assumption: "selected campaign_plan.activities",
          approval_policy: approval_policy
        ),
      "candidate_activities" => candidates,
      "ranked_timelines" => timelines,
      "optimizer_contract" => optimizer_contract,
      "constraint_report" =>
        campaign_constraint_report(
          candidates,
          timelines,
          constraints,
          resource_projection_report,
          link_capacity_report
        ),
      "objective_tradeoff_report" => objective_tradeoff_report(timelines, policy),
      "score_term_report" => score_term_report(timelines, policy),
      "warnings" => warnings(campaign, candidates, timelines, result_set, resource_filter_report),
      "assumptions" => assumptions(campaign),
      "provenance" => provenance(result_set),
      "ranking_explanation" => ranking_explanation(policy)
    }
    |> then(fn artifact ->
      Map.put(
        artifact,
        "operator_review_package",
        OperatorReview.from_campaign_artifact(artifact)
      )
    end)
    |> then(fn artifact ->
      Map.put(
        artifact,
        "cadence_import_manifest",
        CadenceImport.from_campaign_artifact(artifact)
      )
    end)
    |> attach_operational_readiness_reports()
  end

  defp attach_operational_readiness_reports(%{} = artifact) do
    readiness_report = OperationalReadiness.report(artifact)

    artifact
    |> Map.put("operational_readiness_report", readiness_report)
    |> Map.put("quality_gate_report", OperationalReadiness.quality_gate_report(readiness_report))
  end

  @doc """
  Repairs a prior campaign plan against realized operations.

  The request may be a `%ReplanRequest{}` or a map with string or atom keys:

    * `prior_plan` / `"prior_plan"` - V1 campaign plan artifact.
    * `realized_state` / `"realized_state"` - realized activities plus optional
      spacecraft degraded-mode inputs.
    * `current_epoch_s` / `"current_epoch_s"` - repair epoch in seconds since
      the source plan epoch.
    * `remaining_horizon` / `"remaining_horizon"` - optional map containing
      `starts_at_s` and `ends_at_s`.
    * `constraints`, `scoring_policy`, `repair_policy`, and `approval_policy`
      override source plan defaults for the repair pass.
    * `candidate_refresh_request` / `"candidate_refresh_request"` - optional
      executable refresh manifest. When present and no prebuilt
      `candidate_refresh` is supplied, repair runs the refresh before selecting
      replacement candidates.
    * `ground_network` / `"ground_network"` or `station_calendar` /
      `"station_calendar"` - optional repair-time station availability and
      capacity intervals that annotate source contact candidates.
  """
  def repair(%ReplanRequest{} = request) do
    request
    |> normalize_replan_request()
    |> do_repair()
  end

  def repair(%{} = request) do
    request
    |> replan_request_from_map()
    |> repair()
  end

  def repair!(request) do
    case repair(request) do
      %{} = artifact -> artifact
    end
  end

  @doc """
  Loads a JSON V2 repair request file and returns a repair artifact.

  The request may contain either an inline `prior_plan` or a `source_plan_ref`
  object with `path` and optional `artifact_key`. Relative source paths are
  resolved from the current working directory first, then relative to the
  request file directory. This keeps checked-in example requests executable
  while preserving the artifact-only boundary.
  """
  def repair_from_file!(path, opts \\ []) when is_binary(path) do
    path
    |> load_json_request!()
    |> put_referenced_prior_plan!(path, opts)
    |> repair!()
  end

  @doc """
  Compares explicit future branches and returns a V3 strategy artifact.

  The strategy layer reuses V2 repair inside every branch. Branch events alter
  the prior plan, realized state, and policy inputs before repair; branch
  scoring then compares mission value, risk, approvals, schedule stability,
  downlink completion, fuel preservation, and asset balance.
  """
  def strategy(%{} = request) do
    request
    |> normalize_strategy_request()
    |> do_strategy()
  end

  def strategy!(request), do: strategy(request)

  @doc """
  Loads a JSON V3 strategy request file and returns a strategy artifact.

  The request may contain either an inline `prior_plan` or a `source_plan_ref`
  object with `path` and optional `artifact_key`. Relative source paths are
  resolved from the current working directory first, then relative to the
  request file directory.
  """
  def strategy_from_file!(path, opts \\ []) when is_binary(path) do
    path
    |> load_json_request!()
    |> put_referenced_prior_plan!(path, opts)
    |> strategy!()
  end

  @doc """
  Validates a JSON campaign repair or strategy request without running planning.

  The report checks the request file can be read and decoded as an object, that
  it matches the requested type when `request_type` is present, and that the
  prior campaign plan can be resolved either inline or through `source_plan_ref`.
  It intentionally does not run V2 repair, V3 strategy, candidate refresh, or
  write output artifacts.
  """
  def request_validation_report(type, path, opts \\ [])

  def request_validation_report(type, path, opts)
      when type in ["repair", "strategy"] and is_binary(path) do
    base_report = request_validation_report_base(type, path)

    case read_json_request_for_lint(path) do
      {:ok, request, request_metadata} ->
        {source_plan, errors} = lint_request_source_plan(request, path, opts)
        errors = lint_request_type(type, request) ++ errors

        base_report
        |> Map.put("request", request_metadata)
        |> Map.put("source_plan", source_plan)
        |> Map.put("errors", errors)
        |> Map.put("error_count", length(errors))
        |> Map.put("status", lint_status(errors))

      {:error, request_metadata, errors} ->
        base_report
        |> Map.put("request", request_metadata)
        |> Map.put("errors", errors)
        |> Map.put("error_count", length(errors))
        |> Map.put("status", "fail")
    end
  end

  def request_validation_report(type, path, _opts) when is_binary(path) do
    %{
      "schema_contract" => "campaign_request_lint.v1",
      "validation_mode" => "campaign_request_lint",
      "semantic_validator" => "OrbitalDynamics.CampaignPlanner.request_validation_report/3",
      "lint_task" => "mix orbital_dynamics.campaign.lint --type repair|strategy --request PATH",
      "type" => type,
      "request" => %{"path" => path, "sha256" => nil},
      "source_plan" => %{"status" => "not_checked"},
      "status" => "fail",
      "error_count" => 1,
      "errors" => [
        request_lint_error("unsupported_type", "$.type", "type must be repair or strategy")
      ]
    }
  end

  defp load_json_request!(path) do
    path
    |> File.read!()
    |> :json.decode()
    |> case do
      %{} = request -> request
      _value -> raise ArgumentError, "request JSON must decode to an object"
    end
  end

  defp put_referenced_prior_plan!(%{"prior_plan" => %{}} = request, _request_path, _opts),
    do: request

  defp put_referenced_prior_plan!(%{prior_plan: %{}} = request, _request_path, _opts),
    do: request

  defp put_referenced_prior_plan!(request, request_path, opts) do
    case get_key(request, :source_plan_ref) do
      nil ->
        request

      %{} = source_plan_ref ->
        request
        |> Map.delete("source_plan_ref")
        |> Map.delete(:source_plan_ref)
        |> Map.put("prior_plan", load_referenced_artifact!(source_plan_ref, request_path, opts))

      _source_plan_ref ->
        raise ArgumentError, "source_plan_ref must be an object"
    end
  end

  defp load_referenced_artifact!(source_plan_ref, request_path, opts) do
    source_path =
      source_plan_ref
      |> get_key(:path)
      |> case do
        path when is_binary(path) and path != "" -> path
        _path -> raise ArgumentError, "source_plan_ref.path is required"
      end

    request_dir = request_path |> Path.expand() |> Path.dirname()
    base_path = opts |> Keyword.get(:base_path, File.cwd!()) |> Path.expand()
    source_path = resolve_request_reference_path!(source_path, request_dir, base_path)

    artifact =
      source_path
      |> File.read!()
      |> :json.decode()

    case get_key(source_plan_ref, :artifact_key) do
      nil ->
        artifact

      artifact_key when is_binary(artifact_key) and artifact_key != "" ->
        Map.fetch!(artifact, artifact_key)

      _artifact_key ->
        raise ArgumentError, "source_plan_ref.artifact_key must be a string when supplied"
    end
  end

  defp resolve_request_reference_path!(path, request_dir, base_path) do
    candidates =
      if Path.type(path) == :absolute do
        [path]
      else
        [
          Path.expand(path, base_path),
          Path.expand(path, request_dir)
        ]
      end

    Enum.find(candidates, &File.exists?/1) ||
      raise ArgumentError, "source_plan_ref.path does not exist: #{path}"
  end

  defp request_validation_report_base(type, path) do
    %{
      "schema_contract" => "campaign_request_lint.v1",
      "validation_mode" => "campaign_request_lint",
      "semantic_validator" => "OrbitalDynamics.CampaignPlanner.request_validation_report/3",
      "lint_task" => "mix orbital_dynamics.campaign.lint --type #{type} --request PATH",
      "type" => type,
      "request" => %{"path" => path, "sha256" => nil},
      "source_plan" => %{"status" => "not_checked"},
      "status" => "pass",
      "error_count" => 0,
      "errors" => []
    }
  end

  defp read_json_request_for_lint(path) do
    case File.read(path) do
      {:ok, content} ->
        request_metadata = %{
          "path" => path,
          "sha256" => sha256(content)
        }

        case decode_json_object_for_lint(content) do
          {:ok, request} ->
            {:ok, request, request_metadata}

          {:error, message} ->
            {:error, request_metadata, [request_lint_error("invalid_json", "$", message)]}
        end

      {:error, reason} ->
        request_metadata = %{"path" => path, "sha256" => nil}

        {:error, request_metadata,
         [
           request_lint_error(
             "request_file_error",
             "$",
             "could not read request file: #{inspect(reason)}"
           )
         ]}
    end
  end

  defp decode_json_object_for_lint(content) do
    try do
      case :json.decode(content) do
        %{} = request -> {:ok, request}
        _value -> {:error, "request JSON must decode to an object"}
      end
    rescue
      exception -> {:error, Exception.message(exception)}
    end
  end

  defp lint_request_type(type, request) do
    case get_key(request, :request_type) do
      nil ->
        []

      request_type when type == "repair" and request_type == "campaign_plan_repair" ->
        []

      request_type when type == "strategy" and request_type == "campaign_strategy" ->
        []

      request_type when type == "strategy" and request_type == "campaign_strategy_v3" ->
        []

      request_type ->
        [
          request_lint_error(
            "request_type_mismatch",
            "$.request_type",
            "request_type #{inspect(request_type)} does not match campaign #{type}"
          )
        ]
    end
  end

  defp lint_request_source_plan(request, request_path, opts) do
    inline_prior_plan = inline_prior_plan(request)
    source_plan_ref = get_key(request, :source_plan_ref)

    cond do
      is_map(inline_prior_plan) and is_nil(source_plan_ref) ->
        validate_linted_source_plan(inline_prior_plan, %{
          "status" => "pass",
          "source" => "inline_prior_plan",
          "path" => nil,
          "artifact_key" => nil
        })

      is_map(inline_prior_plan) and not is_nil(source_plan_ref) ->
        {%{"status" => "fail", "source" => "ambiguous"},
         [
           request_lint_error(
             "ambiguous_prior_plan_source",
             "$",
             "request must use either prior_plan/campaign_plan/source_plan or source_plan_ref, not both"
           )
         ]}

      is_nil(source_plan_ref) ->
        {%{"status" => "fail", "source" => "missing"},
         [
           request_lint_error(
             "missing_prior_plan_source",
             "$.source_plan_ref",
             "source_plan_ref or inline prior_plan/campaign_plan/source_plan is required"
           )
         ]}

      is_map(source_plan_ref) ->
        lint_source_plan_ref(source_plan_ref, request_path, opts)

      true ->
        {%{"status" => "fail", "source" => "source_plan_ref"},
         [request_lint_error("invalid_source_plan_ref", "$.source_plan_ref", "must be an object")]}
    end
  end

  defp inline_prior_plan(request) do
    get_key(request, :prior_plan) || get_key(request, :campaign_plan) ||
      get_key(request, :source_plan)
  end

  defp lint_source_plan_ref(source_plan_ref, request_path, opts) do
    source_path = get_key(source_plan_ref, :path)
    artifact_key = get_key(source_plan_ref, :artifact_key)

    cond do
      not (is_binary(source_path) and source_path != "") ->
        {%{"status" => "fail", "source" => "source_plan_ref", "path" => source_path},
         [
           request_lint_error(
             "missing_source_plan_ref_path",
             "$.source_plan_ref.path",
             "source_plan_ref.path is required"
           )
         ]}

      not (is_nil(artifact_key) or (is_binary(artifact_key) and artifact_key != "")) ->
        {%{
           "status" => "fail",
           "source" => "source_plan_ref",
           "path" => source_path,
           "artifact_key" => artifact_key
         },
         [
           request_lint_error(
             "invalid_source_plan_ref_artifact_key",
             "$.source_plan_ref.artifact_key",
             "source_plan_ref.artifact_key must be a string when supplied"
           )
         ]}

      true ->
        do_lint_source_plan_ref(source_plan_ref, request_path, opts, source_path, artifact_key)
    end
  end

  defp do_lint_source_plan_ref(_source_plan_ref, request_path, opts, source_path, artifact_key) do
    request_dir = request_path |> Path.expand() |> Path.dirname()
    base_path = opts |> Keyword.get(:base_path, File.cwd!()) |> Path.expand()

    try do
      resolved_path = resolve_request_reference_path!(source_path, request_dir, base_path)
      artifact = resolved_path |> File.read!() |> :json.decode()

      source_artifact =
        if artifact_key do
          Map.fetch!(artifact, artifact_key)
        else
          artifact
        end

      validate_linted_source_plan(source_artifact, %{
        "status" => "pass",
        "source" => "source_plan_ref",
        "path" => resolved_path,
        "artifact_key" => artifact_key,
        "requested_path" => source_path,
        "sha256" => resolved_path |> File.read!() |> sha256()
      })
    rescue
      exception ->
        {%{
           "status" => "fail",
           "source" => "source_plan_ref",
           "path" => source_path,
           "artifact_key" => artifact_key
         },
         [
           request_lint_error(
             "source_plan_ref_error",
             "$.source_plan_ref",
             Exception.message(exception)
           )
         ]}
    end
  end

  defp validate_linted_source_plan(source_plan, source_metadata) do
    case Schema.validate_artifact(source_plan, contract: "campaign_plan.v1") do
      {:ok, _report} ->
        {source_metadata
         |> Map.put("status", "pass")
         |> Map.put("schema_contract", "campaign_plan.v1")
         |> Map.put("plan_id", source_plan_id(source_plan)), []}

      {:error, %{"errors" => errors}} ->
        message =
          errors
          |> List.first()
          |> case do
            %{"path" => path, "message" => message} -> "#{path}: #{message}"
            _error -> "source plan does not satisfy campaign_plan.v1"
          end

        {source_metadata
         |> Map.put("status", "fail")
         |> Map.put("schema_contract", "campaign_plan.v1"),
         [
           request_lint_error(
             "invalid_source_plan_contract",
             "$.source_plan_ref",
             message
           )
         ]}
    end
  end

  defp lint_status([]), do: "pass"
  defp lint_status(_errors), do: "fail"

  defp request_lint_error(code, path, message) do
    %{
      "code" => code,
      "path" => path,
      "message" => message
    }
  end

  defp sha256(content) do
    :crypto.hash(:sha256, content)
    |> Base.encode16(case: :lower)
  end

  defp replan_request_from_map(request) do
    %ReplanRequest{
      prior_plan:
        get_key(request, :prior_plan) || get_key(request, :campaign_plan) ||
          get_key(request, :source_plan),
      mission_state: get_key(request, :mission_state),
      realized_state: get_key(request, :realized_state) || %{},
      current_epoch_s: get_key(request, :current_epoch_s),
      remaining_horizon: get_key(request, :remaining_horizon),
      constraints: get_key(request, :constraints),
      scoring_policy: get_key(request, :scoring_policy),
      repair_policy: get_key(request, :repair_policy),
      approval_policy: get_key(request, :approval_policy),
      candidate_refresh:
        get_key(request, :candidate_refresh) || get_key(request, :refreshed_candidates),
      candidate_refresh_request:
        get_key(request, :candidate_refresh_request) || get_key(request, :refresh_request),
      ground_network: get_key(request, :ground_network) || get_key(request, :station_calendar),
      generated_at: get_key(request, :generated_at),
      metadata: get_key(request, :metadata) || %{}
    }
  end

  defp normalize_replan_request(%ReplanRequest{} = request) do
    prior_plan = stringify_keys(request.prior_plan || %{})
    mission_state = normalize_repair_mission_state(request.mission_state)
    realized_state = normalize_realized_state(request.realized_state || %{})
    current_epoch_s = numeric!(request.current_epoch_s, "current_epoch_s")
    remaining_horizon = remaining_horizon(prior_plan, request.remaining_horizon, current_epoch_s)
    generated_at = normalize_generated_at(request.generated_at || DateTime.utc_now())

    candidate_refresh_request =
      normalize_candidate_refresh_request(request.candidate_refresh_request)
      |> inherit_candidate_refresh_approval_policy(request.approval_policy)
      |> inherit_candidate_refresh_mission_state(mission_state, prior_plan)

    prebuilt_candidate_refresh = normalize_candidate_refresh(request.candidate_refresh)

    candidate_refresh =
      prebuilt_candidate_refresh ||
        execute_repair_candidate_refresh_request(
          prior_plan,
          current_epoch_s,
          candidate_refresh_request,
          generated_at
        )

    scoring_policy =
      prior_plan
      |> get_key("ranking_explanation")
      |> case do
        %{} = explanation -> get_key(explanation, "policy") || %{}
        _explanation -> %{}
      end
      |> Map.merge(stringify_keys(request.scoring_policy || %{}))

    repair_policy = normalize_repair_policy(request.repair_policy || %{})
    approval_policy = normalize_approval_policy(request.approval_policy || %{})
    ground_network = normalize_repair_ground_network(request.ground_network)

    %{
      prior_plan: prior_plan,
      mission_state: mission_state,
      realized_state: realized_state,
      current_epoch_s: current_epoch_s,
      remaining_horizon: remaining_horizon,
      constraints:
        Map.merge(
          stringify_keys(get_key(prior_plan, "assumptions") || %{}) |> get_key("constraints") ||
            %{},
          stringify_keys(request.constraints || %{})
        ),
      scoring_policy:
        scoring_policy
        |> Map.put_new("schedule_churn_cost_weight", repair_policy.schedule_churn_cost_weight)
        |> Map.put_new("schedule_move_cost_weight", repair_policy.schedule_move_cost_weight),
      repair_policy: repair_policy,
      approval_policy: approval_policy,
      candidate_refresh: candidate_refresh,
      candidate_refresh_request: candidate_refresh_request,
      candidate_source:
        repair_candidate_source(
          prior_plan,
          candidate_refresh,
          candidate_refresh_request
        ),
      ground_network: ground_network,
      generated_at: generated_at,
      metadata: stringify_keys(request.metadata || %{})
    }
  end

  defp normalize_repair_mission_state(nil), do: %{"objectives" => []}

  defp normalize_repair_mission_state(%{} = mission_state),
    do: normalize_mission_state(mission_state)

  defp do_repair(%{} = request) do
    prior_plan = request.prior_plan

    planned_activities =
      prior_plan
      |> Map.get("activities", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&normalize_downlink_activity/1)

    source_candidates = repair_candidates(prior_plan, request.candidate_refresh)

    {candidates, station_calendar_report} =
      apply_repair_station_calendar(source_candidates, request)

    realized_by_id = realized_activities_by_id(request.realized_state)
    degraded_modes = degraded_modes_by_scenario(request.realized_state, request.repair_policy)
    selected_activity_ids = selected_activity_ids(planned_activities)
    rejected_replacement_candidate_ids = repair_rejected_candidate_ids(request)

    initial = %{
      activities: [],
      deltas: [],
      approval_requirements: [],
      warnings: [],
      used_replacement_ids: MapSet.new(),
      delayed_maneuvers: []
    }

    repaired =
      planned_activities
      |> Enum.sort_by(&{activity_start(&1), activity_id(&1)})
      |> Enum.reduce(initial, fn activity, acc ->
        repair_activity(activity, acc, %{
          candidates: candidates,
          current_epoch_s: request.current_epoch_s,
          remaining_horizon: request.remaining_horizon,
          realized_by_id: realized_by_id,
          degraded_modes: degraded_modes,
          rejected_replacement_candidate_ids: rejected_replacement_candidate_ids,
          selected_activity_ids: selected_activity_ids,
          repair_policy: request.repair_policy,
          scoring_policy: request.scoring_policy,
          candidate_diff_replacements:
            repair_candidate_diff_replacements(request.candidate_refresh)
        })
      end)
      |> mark_downstream_maneuver_effects(request)

    activities = Enum.sort_by(repaired.activities, &{activity_start(&1), activity_id(&1)})
    deltas = Enum.sort_by(repaired.deltas, &{&1.activity_id, &1.status})
    approval_requirements = Enum.sort_by(repaired.approval_requirements, & &1["activity_id"])

    {approval_status, approval_requirements, approval_rule_matches, policy_decision} =
      repair_approval_decision(approval_requirements, request.approval_policy)

    warnings =
      repaired.warnings
      |> Kernel.++(repair_refresh_warnings(request.candidate_refresh))
      |> Enum.uniq()
      |> Enum.sort()

    score_terms = repair_score_terms(activities, deltas, request.scoring_policy)
    score = score(score_terms)
    repair_score_timeline = repair_score_timeline(prior_plan, activities, score_terms, score)
    source_resource_summaries = repair_resource_summaries(request.candidate_refresh)

    source_resource_projection_report =
      repair_resource_projection_report(
        activities,
        source_resource_summaries,
        approval_policy_to_map(request.approval_policy)
      )

    source_timeline_feedback_report =
      repair_timeline_feedback_report(planned_activities, request.realized_state)

    link_capacity_report =
      link_capacity_report(
        activities,
        activities,
        repair_link_capacity_policy(request),
        "campaign_repair.activities",
        request.approval_policy
      )

    timeline_protection = timeline_protection_summary(activities, deltas)

    timeline_transition_application_report =
      repair_timeline_transition_application_report(planned_activities, activities)

    artifact =
      %{
        "schema_version" => @repair_schema_version,
        "generated_at" => DateTime.to_iso8601(request.generated_at),
        "planner" => "OrbitalDynamics.CampaignPlanner.V2",
        "source_plan_id" => source_plan_id(prior_plan),
        "source_planner" => Map.get(prior_plan, "planner"),
        "study_id" => Map.get(prior_plan, "study_id"),
        "current_epoch_s" => request.current_epoch_s,
        "remaining_horizon" => request.remaining_horizon,
        "activities" => activities,
        "operational_timeline_report" =>
          Timeline.operational_report(activities,
            source: "campaign_repair.activities",
            source_assumption: "repaired campaign_repair.activities"
          ),
        "timeline_transition_application_report" => timeline_transition_application_report,
        "command_window_report" =>
          CommandWindow.report(activities,
            source: "campaign_repair.activities",
            source_assumption: "repaired campaign_repair.activities",
            approval_policy: request.approval_policy
          ),
        "source_candidate_activities" => candidates,
        "source_contact_intents" => repair_contact_intents(request.candidate_refresh),
        "source_resource_summaries" => source_resource_summaries,
        "preserved_activities" => preserved_activities(activities),
        "deltas" => Enum.map(deltas, &plan_delta_to_map/1),
        "change_summary" => change_summary(deltas),
        "approval_requirements" => approval_requirements,
        "approval_status" => approval_status,
        "approval_policy" => approval_policy_to_map(request.approval_policy),
        "approval_rule_matches" => approval_rule_matches,
        "policy_decision" => policy_decision,
        "warnings" => warnings,
        "realized_state_snapshot" => request.realized_state,
        "repair_policy" => repair_policy_to_map(request.repair_policy),
        "scoring_policy" => request.scoring_policy,
        "score" => score,
        "score_terms" => score_terms,
        "score_term_report" =>
          repair_score_term_report(repair_score_timeline, request.scoring_policy),
        "objective_tradeoff_report" =>
          repair_objective_tradeoff_report(repair_score_timeline, request.scoring_policy),
        "constraint_report" =>
          repair_constraint_report(
            activities,
            repair_score_timeline,
            request,
            source_resource_projection_report,
            link_capacity_report
          ),
        "link_capacity_report" => link_capacity_report,
        "contact_allocation_report" => repair_contact_allocation_report(activities, request),
        "assumptions" => repair_assumptions(prior_plan, request),
        "provenance" => repair_provenance(prior_plan, request.candidate_source),
        "repair_metadata" => %{
          "repair_id" =>
            repair_id(
              prior_plan,
              request.realized_state,
              request.current_epoch_s,
              request.candidate_source
            ),
          "source_plan_id" => source_plan_id(prior_plan),
          "delta_count" => length(deltas),
          "approval_required_count" => length(approval_requirements),
          "candidate_window_count" => length(candidates),
          "candidate_source" => request.candidate_source,
          "repaired_activity_count" => length(activities),
          "transition_selected_activity_count" =>
            length(
              Timeline.transition_selected_activities(timeline_transition_application_report)
            ),
          "transition_application_review_required_count" =>
            timeline_transition_application_report["review_required_count"],
          "timeline_protection" => timeline_protection
        }
      }
      |> maybe_put_source_report(
        "source_candidate_diff_report",
        repair_candidate_diff_report(request.candidate_refresh)
      )
      |> maybe_put_source_report(
        "source_candidate_rejection_report",
        repair_candidate_rejection_report(request)
      )
      |> maybe_put_source_report(
        "source_freshness_report",
        repair_freshness_report(request.candidate_refresh)
      )
      |> maybe_put_source_report(
        "source_refresh_budget_report",
        repair_refresh_budget_report(request.candidate_refresh)
      )
      |> maybe_put_source_report(
        "source_contact_filter_report",
        repair_contact_filter_report(request.candidate_refresh)
      )
      |> maybe_put_source_report(
        "source_contact_allocation_report",
        repair_contact_allocation_report(request.candidate_refresh)
      )
      |> maybe_put_source_report(
        "source_resource_filter_report",
        repair_resource_filter_report(request.candidate_refresh)
      )
      |> maybe_put_source_report(
        "source_resource_projection_report",
        source_resource_projection_report
      )
      |> maybe_put_source_report(
        "source_timeline_feedback_report",
        source_timeline_feedback_report
      )
      |> maybe_put_source_report("source_station_calendar_report", station_calendar_report)
      |> then(fn artifact ->
        Map.put(
          artifact,
          "operator_review_package",
          OperatorReview.from_repair_artifact(artifact)
        )
      end)
      |> then(fn artifact ->
        Map.put(
          artifact,
          "cadence_import_manifest",
          CadenceImport.from_repair_artifact(artifact)
        )
      end)

    artifact
  end

  defp normalize_strategy_request(request) do
    prior_plan =
      get_key(request, :prior_plan) || get_key(request, :campaign_plan) ||
        get_key(request, :source_plan)

    prior_plan = normalize_strategy_prior_plan(prior_plan)
    current_epoch_s = numeric!(get_key(request, :current_epoch_s), "current_epoch_s")

    mission_state =
      request
      |> get_key(:mission_state)
      |> normalize_mission_state()

    branches =
      request
      |> get_key(:branches)
      |> normalize_strategy_branches()

    branch_generation_policy =
      request
      |> branch_generation_policy()

    candidate_refresh =
      normalize_candidate_refresh(
        get_key(request, :candidate_refresh) || get_key(request, :refreshed_candidates)
      )

    explicit_operational_feedback = get_key(request, :operational_feedback)
    prior_operational_feedback = prior_plan_operational_feedback(prior_plan)

    candidate_refresh_operational_feedback =
      candidate_refresh_operational_feedback(candidate_refresh)

    realized_activities_operational_feedback =
      realized_activities_operational_feedback(mission_state, prior_plan)

    mission_state_operational_feedback =
      mission_state_operational_feedback(
        mission_state,
        prior_plan,
        realized_activities_operational_feedback
      )

    operational_feedback =
      prior_operational_feedback
      |> merge_operational_feedback(mission_state_operational_feedback)
      |> merge_operational_feedback(candidate_refresh_operational_feedback)
      |> merge_operational_feedback(normalize_operational_feedback(explicit_operational_feedback))

    operational_feedback_provenance =
      strategy_operational_feedback_provenance(
        prior_plan,
        mission_state,
        candidate_refresh,
        explicit_operational_feedback,
        realized_activities_operational_feedback,
        operational_feedback
      )

    branches =
      branches
      |> maybe_add_derived_branches(
        prior_plan,
        mission_state,
        operational_feedback,
        operational_feedback_provenance,
        branch_generation_policy
      )

    strategic_policy =
      request
      |> get_key(:strategy_policy)
      |> normalize_strategy_policy()

    approval_policy =
      request
      |> get_key(:approval_policy)
      |> normalize_approval_policy()

    raw_approval_policy = get_key(request, :approval_policy)
    approval_policy_supplied? = not is_nil(raw_approval_policy)

    repair_policy =
      request
      |> get_key(:repair_policy)
      |> normalize_repair_policy()

    %{
      prior_plan: prior_plan,
      mission_state: mission_state,
      realized_state: normalize_realized_state(get_key(request, :realized_state) || %{}),
      current_epoch_s: current_epoch_s,
      remaining_horizon:
        remaining_horizon(
          prior_plan,
          get_key(request, :remaining_horizon) || Map.get(mission_state, "remaining_horizon"),
          current_epoch_s
        ),
      branches: branches,
      branch_generation_policy: branch_generation_policy,
      strategy_policy: strategic_policy,
      approval_policy: approval_policy,
      approval_policy_source: stringify_keys(raw_approval_policy || %{}),
      approval_policy_supplied?: approval_policy_supplied?,
      repair_policy: repair_policy,
      scoring_policy: stringify_keys(get_key(request, :scoring_policy) || %{}),
      candidate_refresh: candidate_refresh,
      operational_feedback: operational_feedback,
      operational_feedback_provenance: operational_feedback_provenance,
      generated_at: normalize_generated_at(get_key(request, :generated_at) || DateTime.utc_now()),
      metadata: stringify_keys(get_key(request, :metadata) || %{})
    }
  end

  defp do_strategy(%{branches: branches} = request) do
    cond do
      length(branches) < 2 ->
        raise ArgumentError,
              "V3 strategy requires a baseline branch and at least one what-if branch"

      not Enum.any?(branches, &(&1["id"] == "baseline")) ->
        raise ArgumentError,
              "V3 strategy requires a baseline branch and at least one what-if branch"

      true ->
        do_strategy_with_baseline(request)
    end
  end

  defp do_strategy_with_baseline(%{} = request) do
    input_order_branches =
      request.branches
      |> Enum.map(&evaluate_branch(&1, request))

    branches =
      input_order_branches
      |> Enum.sort_by(&{-&1.score, &1.id})

    recommendation = strategy_recommendation(branches, request.approval_policy)
    branch_comparison = branch_comparison_report(branches, recommendation)
    branch_maps = Enum.map(branches, &plan_branch_to_map/1)

    score_term_report =
      strategy_score_term_report(branches, recommendation, request.strategy_policy)

    objective_tradeoff_report =
      strategy_objective_tradeoff_report(branches, recommendation, request.strategy_policy)

    %{
      "schema_version" => @strategy_schema_version,
      "generated_at" => DateTime.to_iso8601(request.generated_at),
      "planner" => "OrbitalDynamics.CampaignPlanner.V3",
      "source_plan_id" => source_plan_id(request.prior_plan),
      "source_repair_id" => get_in(request.prior_plan, ["repair_metadata", "repair_id"]),
      "mission_state_snapshot" => request.mission_state,
      "branches" => branch_maps,
      "recommendation" => strategy_recommendation_to_map(recommendation),
      "branch_comparison_report" => branch_comparison,
      "score_term_report" => score_term_report,
      "objective_tradeoff_report" => objective_tradeoff_report,
      "ranking_comparison_report" =>
        branch_ranking_comparison_report(input_order_branches, branches),
      "pareto_frontier_report" => branch_pareto_frontier_report(branch_comparison),
      "strategy_policy" => strategy_policy_to_map(request.strategy_policy),
      "approval_policy" => approval_policy_to_map(request.approval_policy),
      "operational_feedback" => request.operational_feedback,
      "operational_feedback_provenance" => request.operational_feedback_provenance,
      "assumptions" => strategy_assumptions(request),
      "provenance" => strategy_provenance(request.prior_plan),
      "strategy_metadata" => %{
        "strategy_id" => strategy_id(request, branch_maps),
        "branch_count" => length(branch_maps),
        "baseline_branch_id" => baseline_branch_id(branch_maps),
        "cadence_integration" => "artifact_only_no_api_or_database_writes"
      }
    }
    |> then(fn artifact ->
      Map.put(
        artifact,
        "operator_review_package",
        OperatorReview.from_strategy_artifact(artifact)
      )
    end)
    |> then(fn artifact ->
      Map.put(
        artifact,
        "cadence_import_manifest",
        CadenceImport.from_strategy_artifact(artifact)
      )
    end)
  end

  defp evaluate_branch(branch, request) do
    prior_plan = apply_branch_plan_events(request.prior_plan, branch, request)
    candidate_refresh_request = branch_candidate_refresh_request(branch, request)
    candidate_refresh = branch_candidate_refresh(branch, request, candidate_refresh_request)

    realized_state =
      request.realized_state
      |> merge_realized_state(mission_state_repair_state(request.mission_state))
      |> merge_realized_state(branch["realized_state_overrides"])
      |> apply_branch_realized_events(prior_plan, branch, request)

    policy_overrides = Map.get(branch, "policy_overrides", %{})

    repair_policy =
      request.repair_policy
      |> repair_policy_to_map()
      |> Map.merge(Map.get(policy_overrides, "repair_policy", %{}))
      |> normalize_repair_policy()

    scoring_policy =
      request.scoring_policy
      |> Map.merge(Map.get(policy_overrides, "scoring_policy", %{}))

    repair_result =
      repair(%ReplanRequest{
        prior_plan: prior_plan,
        realized_state: realized_state,
        current_epoch_s: request.current_epoch_s,
        remaining_horizon: request.remaining_horizon,
        repair_policy: repair_policy,
        approval_policy: request.approval_policy,
        scoring_policy: scoring_policy,
        candidate_refresh: candidate_refresh,
        candidate_refresh_request: candidate_refresh_request,
        mission_state: request.mission_state,
        generated_at: request.generated_at,
        metadata: %{"branch_id" => branch["id"]}
      })

    {candidate_plan, candidate_warnings} = branch_candidate_plan(repair_result, branch, request)

    resource_projection_report =
      branch_resource_projection_report(
        candidate_plan,
        repair_result,
        approval_policy_to_map(request.approval_policy)
      )

    resource_impacts = branch_resource_impacts(candidate_plan, branch, request)

    feedback_adjustments =
      branch_feedback_adjustments(candidate_plan, repair_result, branch, request)

    objective_satisfaction = branch_objective_satisfaction(candidate_plan, request)
    feasibility_summary = branch_feasibility_summary(candidate_plan)
    candidate_source = branch_candidate_source(branch, request, repair_result)

    risk_indicators =
      branch_risk_indicators(
        branch,
        repair_result,
        candidate_plan,
        request,
        resource_impacts,
        resource_projection_report,
        feedback_adjustments,
        candidate_source
      )

    approval_requirements = branch_approval_requirements(repair_result, candidate_plan)

    {approval_status, approval_requirements, approval_rule_matches, policy_decision} =
      approval_decision(
        approval_requirements,
        risk_indicators,
        branch,
        candidate_plan,
        request.approval_policy
      )

    score_terms =
      strategic_score_terms(
        candidate_plan,
        repair_result,
        risk_indicators,
        branch,
        request,
        resource_impacts,
        feedback_adjustments
      )

    score = Map.get(score_terms, "expected_score", 0.0)

    warnings =
      (Map.get(repair_result, "warnings", []) ++
         candidate_warnings ++
         branch_event_warnings(branch) ++
         Map.get(resource_impacts, "warnings", []))
      |> Enum.uniq()
      |> Enum.sort()

    %PlanBranch{
      id: branch["id"],
      label: branch["label"],
      probability: branch["probability"],
      events: branch["events"],
      candidate_plan: candidate_plan,
      repair_result: repair_result,
      score: score,
      score_terms: score_terms,
      warnings: warnings,
      risk_indicators: risk_indicators,
      approval_status: approval_status,
      approval_requirements: approval_requirements,
      approval_rule_matches: approval_rule_matches,
      policy_decision: policy_decision,
      derived_source: get_in(branch, ["metadata", "derived_source"]),
      resource_impacts: resource_impacts,
      resource_projection_report: resource_projection_report,
      feedback_adjustments: feedback_adjustments,
      objective_satisfaction: objective_satisfaction,
      feasibility_summary: feasibility_summary,
      assumptions:
        branch_assumptions(
          branch,
          request,
          repair_policy,
          scoring_policy,
          candidate_source
        ),
      provenance:
        branch_provenance(
          request.prior_plan,
          branch,
          candidate_source
        ),
      tradeoffs: []
    }
  end

  defp apply_branch_plan_events(prior_plan, branch, _request) do
    Enum.reduce(branch["events"], prior_plan, fn event, plan ->
      case event["type"] do
        type when type in ["ground_station_outage", "ground_station_reserved"] ->
          update_candidate_activities(plan, fn activities ->
            Enum.reject(activities, &ground_station_event_match?(&1, event))
          end)

        "reduced_downlink_capacity" ->
          update_candidate_activities(plan, fn activities ->
            Enum.map(activities, &apply_downlink_capacity(&1, event))
          end)

        _type ->
          plan
      end
    end)
  end

  defp apply_branch_realized_events(realized_state, prior_plan, branch, _request) do
    Enum.reduce(branch["events"], realized_state, fn event, state ->
      case event["type"] do
        type when type in ["ground_station_outage", "ground_station_reserved"] ->
          prior_plan
          |> prior_plan_activities()
          |> Enum.filter(&ground_station_event_match?(&1, event))
          |> Enum.reduce(state, fn activity, acc ->
            add_realized_activity(
              acc,
              %{
                "id" => activity_id(stringify_keys(activity)),
                "status" => "missed",
                "reason" => branch_ground_station_event_reason(type)
              }
              |> Map.merge(branch_ground_station_realized_context(event, type))
            )
          end)

        "degraded_spacecraft" ->
          add_spacecraft_state(state, %{
            "scenario_id" => branch_event_spacecraft_id(event),
            "mode" => degraded_event_mode(event),
            "incompatible_activity_types" =>
              event
              |> degradation_activity_types()
              |> normalize_incompatible_activity_types()
          })

        "missed_maneuver" ->
          add_realized_activity(state, %{
            "id" => event["activity_id"],
            "status" => "missed",
            "reason" => "branch_missed_maneuver"
          })

        "delayed_maneuver" ->
          add_realized_activity(state, %{
            "id" => event["activity_id"],
            "status" => "delayed",
            "actual_starts_at_s" => event["actual_starts_at_s"],
            "actual_ends_at_s" => event["actual_ends_at_s"] || event["actual_starts_at_s"],
            "reason" => "branch_delayed_maneuver"
          })

        _type ->
          state
      end
    end)
  end

  defp branch_event_warnings(branch) do
    branch
    |> Map.get("events", [])
    |> Enum.flat_map(fn event ->
      event
      |> Map.get("invalid_branch_event_input_reasons", [])
      |> List.wrap()
      |> Enum.map(fn reason ->
        field = String.replace_prefix(reason, "invalid_", "")
        value = get_in(event, ["invalid_branch_event_values", field])
        branch_id = Map.get(branch, "id")
        event_type = Map.get(event, "type", "branch_event")

        "branch #{branch_id} #{event_type} ignored invalid #{field} #{encode_value(value)}"
      end)
    end)
  end

  defp branch_event_invalid?(event, reason) do
    reason in List.wrap(Map.get(event, "invalid_branch_event_input_reasons", []))
  end

  defp branch_candidate_plan(repair_result, branch, request) do
    source_candidate_activities = Map.get(repair_result, "source_candidate_activities", [])

    candidate_diff_by_replacement_id =
      repair_result
      |> Map.get("source_candidate_diff_report")
      |> candidate_diff_replacements_by_replacement_id()

    initial = %{
      "activities" => Map.get(repair_result, "activities", []),
      "strategic_additions" => [],
      "removed_activity_ids" => [],
      "capacity_adjustments" => []
    }

    Enum.reduce(branch["events"], {initial, []}, fn event, {candidate_plan, warnings} ->
      case event["type"] do
        type
        when type in [
               "urgent_target",
               "observation_success_feedback",
               "target_priority_feedback"
             ] ->
          stage_urgent_target(
            candidate_plan,
            warnings,
            event,
            branch,
            request,
            source_candidate_activities,
            candidate_diff_by_replacement_id
          )

        "downlink_completion_gap" ->
          stage_downlink_completion(
            candidate_plan,
            warnings,
            event,
            request,
            source_candidate_activities,
            candidate_diff_by_replacement_id
          )

        "candidate_diff_replacement" ->
          stage_candidate_diff_replacement(
            candidate_plan,
            warnings,
            event,
            request,
            source_candidate_activities,
            candidate_diff_by_replacement_id
          )

        "reduced_downlink_capacity" ->
          if branch_event_invalid?(event, "invalid_capacity_fraction") do
            {candidate_plan, warnings}
          else
            capacity_fraction = ground_network_capacity_fraction(event)

            adjustment = %{
              "type" => "reduced_downlink_capacity",
              "ground_station_id" => event_ground_station_id(event),
              "capacity_fraction" => capacity_fraction,
              "starts_at_s" => event["starts_at_s"],
              "ends_at_s" => event["ends_at_s"]
            }

            {Map.update!(candidate_plan, "capacity_adjustments", &[adjustment | &1]), warnings}
          end

        _type ->
          {candidate_plan, warnings}
      end
    end)
    |> then(fn {candidate_plan, warnings} ->
      {
        candidate_plan
        |> Map.update!(
          "activities",
          &Enum.sort_by(&1, fn activity -> {activity_start(activity), activity_id(activity)} end)
        )
        |> Map.update!(
          "strategic_additions",
          &Enum.sort_by(&1, fn activity -> activity_id(activity) end)
        )
        |> Map.update!("capacity_adjustments", &Enum.reverse/1),
        warnings
      }
    end)
  end

  defp stage_candidate_diff_replacement(
         candidate_plan,
         warnings,
         event,
         request,
         source_candidate_activities,
         candidate_diff_by_replacement_id
       ) do
    replacement_id = event["replacement_candidate_id"]

    replacement =
      (source_candidate_activities ++ prior_plan_candidate_activities(request.prior_plan))
      |> Enum.map(&stringify_keys/1)
      |> dedupe_by_id()
      |> Enum.find(&(activity_id(&1) == replacement_id))

    cond do
      replacement_id in [nil, ""] ->
        {candidate_plan,
         ["candidate diff replacement not staged: missing replacement id" | warnings]}

      is_nil(replacement) ->
        {candidate_plan,
         [
           "candidate diff replacement #{replacement_id} not staged: no validated replacement candidate"
           | warnings
         ]}

      Enum.any?(candidate_plan["activities"], &(activity_id(&1) == replacement_id)) ->
        {candidate_plan, warnings}

      Enum.any?(candidate_plan["activities"], &overlaps?(replacement, &1)) ->
        {candidate_plan,
         [
           "candidate diff replacement #{replacement_id} not staged: overlaps existing activity"
           | warnings
         ]}

      true ->
        candidate_diff =
          case Map.get(event, "source_candidate_diff") do
            %{} = source ->
              source

            _source ->
              candidate_diff_for_replacement(replacement, candidate_diff_by_replacement_id)
          end

        addition =
          replacement
          |> put_repair_metadata(
            %{
              "action" => "strategic_addition",
              "reason" => "candidate_diff_replacement_inserted",
              "requires_approval" => true
            }
            |> maybe_put_candidate_diff(candidate_diff)
          )
          |> put_in(
            ["feasibility"],
            %{
              "status" => "validated_candidate_diff_replacement",
              "replacement_candidate_id" => replacement_id,
              "invalidated_candidate_id" => event["invalidated_candidate_id"],
              "source_window_id" => event["source_window_id"],
              "replacement_source_window_id" => event["replacement_source_window_id"],
              "source_target_id" => event["source_target_id"],
              "source_target" => event["source_target"],
              "target_latitude_deg" => event["target_latitude_deg"],
              "target_longitude_deg" => event["target_longitude_deg"],
              "target_minimum_elevation_deg" => event["target_minimum_elevation_deg"],
              "target_priority" => event["target_priority"],
              "target_priority_source" => event["target_priority_source"],
              "target_priority_objective_ids" => event["target_priority_objective_ids"],
              "target_priority_objective_type" => event["target_priority_objective_type"],
              "changed_fields" => event["changed_fields"] || candidate_diff["changed_fields"],
              "candidate_diff_changed_fields" =>
                event["candidate_diff_changed_fields"] ||
                  candidate_diff["candidate_diff_changed_fields"],
              "candidate_diff_changed_field_count" =>
                event["candidate_diff_changed_field_count"] ||
                  candidate_diff["candidate_diff_changed_field_count"],
              "requires_approval" => true,
              "feedback_source" => event["feedback_source"],
              "feedback_scope" => event["feedback_scope"],
              "source_candidate_diff" => candidate_diff
            }
            |> Map.merge(event_feasibility_context(event))
            |> compact_map()
          )

        candidate_plan =
          candidate_plan
          |> Map.update!("activities", &([addition] ++ &1))
          |> Map.update!("strategic_additions", &([addition] ++ &1))

        {candidate_plan, warnings}
    end
  end

  defp stage_urgent_target(
         candidate_plan,
         warnings,
         event,
         branch,
         request,
         source_candidate_activities,
         candidate_diff_by_replacement_id
       ) do
    target_id = event["target_id"] || event["id"] || "urgent_target"
    allow_placeholder? = Map.get(event, "allow_placeholder", true)
    required_observations = urgent_target_required_observations(event)
    planned_observations = scoped_target_observation_count(candidate_plan["activities"], event)
    needed_observations = max(required_observations - planned_observations, 0)

    cond do
      needed_observations == 0 ->
        {candidate_plan, warnings}

      true ->
        candidate_plan
        |> urgent_target_additions(
          event,
          branch,
          request,
          source_candidate_activities,
          %{
            "target_id" => target_id,
            "required_observations" => required_observations,
            "planned_observations" => planned_observations,
            "needed_observations" => needed_observations,
            "allow_placeholder" => allow_placeholder?,
            "candidate_diff_by_replacement_id" => candidate_diff_by_replacement_id
          }
        )
        |> apply_urgent_target_additions(candidate_plan, warnings)
    end
  end

  defp urgent_target_additions(
         candidate_plan,
         event,
         branch,
         request,
         source_candidate_activities,
         context
       ) do
    target_id = context["target_id"]
    priority = event_priority(event, 10.0)
    needed_observations = context["needed_observations"]

    selected =
      event
      |> urgent_target_candidate_windows(request, source_candidate_activities)
      |> Enum.filter(
        &within_remaining_horizon?(
          &1,
          request.remaining_horizon || default_strategy_horizon(request)
        )
      )
      |> Enum.reject(fn activity ->
        Enum.any?(candidate_plan["activities"], &overlaps?(activity, &1))
      end)
      |> Enum.filter(&urgent_target_spacecraft_match?(&1, event))
      |> sort_urgent_target_candidates(priority)
      |> select_non_overlapping_candidates(candidate_plan["activities"], needed_observations)

    additions =
      selected
      |> Enum.with_index(1)
      |> Enum.map(fn {candidate, index} ->
        urgent_target_validated_addition(
          candidate,
          event,
          branch,
          context,
          index,
          length(selected)
        )
      end)

    missing_count = needed_observations - length(additions)

    cond do
      missing_count <= 0 ->
        {:ok, additions, []}

      context["allow_placeholder"] ->
        placeholder_index = length(additions) + 1
        placeholder_count = if needed_observations == 1, do: 1, else: needed_observations

        placeholder =
          event
          |> urgent_target_placeholder(
            branch,
            request,
            context,
            placeholder_index,
            placeholder_count
          )
          |> urgent_target_placeholder_addition(
            event,
            context,
            placeholder_index,
            "no_validated_candidate_window"
          )

        warning =
          urgent_target_warning(target_id, missing_count, "staged as unvalidated placeholder")

        {:ok, additions ++ [placeholder], [warning]}

      true ->
        warning =
          urgent_target_warning(
            target_id,
            missing_count,
            "not staged: no_validated_candidate_window"
          )

        {:ok, additions, [warning]}
    end
  end

  defp apply_urgent_target_additions({:ok, [], extra_warnings}, candidate_plan, warnings),
    do: {candidate_plan, extra_warnings ++ warnings}

  defp apply_urgent_target_additions({:ok, additions, extra_warnings}, candidate_plan, warnings) do
    candidate_plan =
      candidate_plan
      |> Map.update!("activities", &(additions ++ &1))
      |> Map.update!("strategic_additions", &(additions ++ &1))

    {candidate_plan, extra_warnings ++ warnings}
  end

  defp urgent_target_validated_addition(candidate, event, branch, context, index, selected_count) do
    target_id = context["target_id"]
    priority = event_priority(event, 10.0)
    duration_s = activity_end(candidate) - activity_start(candidate)
    candidate_diff = candidate_diff_for_replacement(candidate, context)

    scoring_policy =
      Map.get(branch, "policy_overrides", %{}) |> Map.get("scoring_policy", %{})

    target_weight = numeric_policy_value(scoring_policy, "target_value_weight", 1.0)
    score = max(candidate_score(candidate), priority * duration_s * target_weight)
    source = Map.get(candidate, "source_window", %{"type" => "candidate_activity"})

    feasibility =
      %{
        "status" => "validated_candidate_window",
        "target_id" => target_id,
        "selected_scenario_id" => candidate["scenario_id"],
        "source_window" => source,
        "requires_approval" => true,
        "required_observations" => context["required_observations"],
        "planned_observations" => context["planned_observations"],
        "staged_observation_index" => index
      }
      |> Map.merge(event_feasibility_context(event))
      |> maybe_put_candidate_diff(candidate_diff)

    candidate
    |> Map.put("id", urgent_target_activity_id(event, branch, target_id, index, selected_count))
    |> Map.put("type", "observe")
    |> Map.put("target_id", target_id)
    |> Map.put("score", score)
    |> Map.put("score_terms", %{"urgent_target_value" => score})
    |> Map.put("metadata", urgent_target_metadata(event, priority, context, index))
    |> put_repair_metadata(
      %{
        "action" => "strategic_addition",
        "reason" => target_addition_reason(event),
        "requires_approval" => true
      }
      |> maybe_put_candidate_diff(candidate_diff)
    )
    |> put_in(["feasibility"], feasibility)
  end

  defp urgent_target_placeholder_addition(activity, event, context, index, reason) do
    activity
    |> put_repair_metadata(%{
      "action" => "strategic_addition",
      "reason" => reason,
      "requires_approval" => true
    })
    |> put_in(
      ["feasibility"],
      %{
        "status" => "unvalidated_placeholder",
        "target_id" => context["target_id"],
        "selected_scenario_id" => activity["scenario_id"],
        "source_window" => activity["source_window"],
        "requires_approval" => true,
        "reason" => reason,
        "required_observations" => context["required_observations"],
        "planned_observations" => context["planned_observations"],
        "staged_observation_index" => index
      }
      |> Map.merge(event_feasibility_context(event))
    )
  end

  defp target_addition_reason(%{"type" => "observation_success_feedback"}),
    do: "observation_success_feedback_candidate_inserted"

  defp target_addition_reason(%{"type" => "target_priority_feedback"}),
    do: "target_priority_feedback_candidate_inserted"

  defp target_addition_reason(%{"objective_type" => "target_coverage"}),
    do: "target_coverage_candidate_inserted"

  defp target_addition_reason(%{"objective_type" => "target_observation"}),
    do: "target_observation_candidate_inserted"

  defp target_addition_reason(%{"objective_type" => "target_revisit"}),
    do: "target_revisit_candidate_inserted"

  defp target_addition_reason(%{"objective_type" => "priority_commitment"}),
    do: "priority_commitment_candidate_inserted"

  defp target_addition_reason(_event), do: "urgent_high_priority_target_inserted"

  defp urgent_target_required_observations(event) do
    event
    |> Map.take(["required_observations", "required_revisits", "required_count"])
    |> Map.values()
    |> Enum.find(&is_number/1)
    |> case do
      nil -> 1
      count -> max(ceil_count(count), 1)
    end
  end

  defp scoped_target_observation_count(activities, event) do
    activities
    |> Enum.map(&stringify_keys/1)
    |> Enum.count(&target_objective_activity_match?(&1, event))
  end

  defp sort_urgent_target_candidates(candidates, priority) do
    Enum.sort_by(candidates, fn candidate ->
      overlap_s = numeric_or_nil(Map.get(candidate, "eclipse_overlap_s")) || 0.0

      {-priority, -candidate_score(candidate), overlap_s, activity_start(candidate),
       activity_id(candidate)}
    end)
  end

  defp urgent_target_activity_id(event, branch, target_id, index, selected_count) do
    cond do
      is_binary(event["activity_id"]) and selected_count == 1 ->
        event["activity_id"]

      is_binary(event["activity_id"]) ->
        "#{event["activity_id"]}_#{index}"

      selected_count == 1 ->
        "#{branch["id"]}_urgent_observe_#{target_id}"

      true ->
        "#{branch["id"]}_urgent_observe_#{target_id}_#{index}"
    end
  end

  defp urgent_target_metadata(event, priority, context, index) do
    %{
      "priority" => priority,
      "commitment_id" => event["commitment_id"],
      "what_if_event_id" => event["id"],
      "required_observations" => context["required_observations"],
      "planned_observations" => context["planned_observations"],
      "staged_observation_index" => index
    }
  end

  defp urgent_target_warning(target_id, missing_count, reason) do
    "urgent target #{target_id} missing #{missing_count} observation(s): #{reason}"
  end

  defp urgent_target_candidate_windows(event, request, source_candidate_activities) do
    target_id = event["target_id"] || event["id"] || "urgent_target"

    event_windows =
      event
      |> Map.get("candidate_windows", [])
      |> Enum.map(fn window ->
        window
        |> stringify_keys()
        |> Map.put_new("type", "observe")
        |> Map.put_new("target_id", target_id)
        |> Map.put_new(
          "id",
          "urgent_candidate_#{target_id}_#{Map.get(window, "starts_at_s", 0.0)}"
        )
        |> Map.put_new(
          "source_window",
          Map.put(stringify_keys(window), "type", "mission_state_candidate_window")
        )
        |> Map.put_new("duration_s", activity_end(window) - activity_start(window))
      end)

    plan_windows =
      request.prior_plan
      |> Map.get("candidate_activities", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.filter(&(&1["type"] == "observe" and &1["target_id"] == target_id))

    source_windows =
      source_candidate_activities
      |> Enum.map(&stringify_keys/1)
      |> Enum.filter(&(&1["type"] == "observe" and &1["target_id"] == target_id))

    (event_windows ++ plan_windows ++ source_windows)
    |> dedupe_by_id()
    |> Enum.filter(&target_event_window_match?(&1, event))
  end

  defp target_event_window_match?(candidate, event) do
    starts_at_s = Map.get(event, "starts_at_s") || Map.get(event, "start_s")
    ends_at_s = Map.get(event, "ends_at_s") || Map.get(event, "end_s")

    (not is_number(starts_at_s) or activity_start(candidate) >= starts_at_s) and
      (not is_number(ends_at_s) or activity_end(candidate) <= ends_at_s)
  end

  defp urgent_target_spacecraft_match?(activity, event) do
    allowed =
      event["spacecraft_constraints"] || event["allowed_scenario_ids"] ||
        event["allowed_spacecraft_ids"]

    scenario_id = event["scenario_id"]

    cond do
      is_binary(scenario_id) -> activity["scenario_id"] == scenario_id
      is_list(allowed) -> activity["scenario_id"] in allowed
      true -> true
    end
  end

  defp urgent_target_placeholder(event, branch, request, context, index, selected_count) do
    target_id = context["target_id"]
    priority = event_priority(event, 10.0)

    starts_at_s =
      numeric_or_nil(event["starts_at_s"]) ||
        Map.get(request.remaining_horizon, "starts_at_s", 0.0)

    ends_at_s =
      numeric_or_nil(event["ends_at_s"]) ||
        starts_at_s + (numeric_or_nil(Map.get(event, "duration_s")) || 60.0)

    duration_s = ends_at_s - starts_at_s
    scoring_policy = Map.get(branch, "policy_overrides", %{}) |> Map.get("scoring_policy", %{})
    target_weight = numeric_policy_value(scoring_policy, "target_value_weight", 1.0)
    score = priority * duration_s * target_weight

    %{
      "id" => urgent_target_activity_id(event, branch, target_id, index, selected_count),
      "type" => "observe",
      "scenario_id" => event["scenario_id"] || first_scenario_id(request),
      "target_id" => target_id,
      "starts_at_s" => starts_at_s,
      "ends_at_s" => ends_at_s,
      "duration_s" => duration_s,
      "score" => score,
      "score_terms" => %{"urgent_target_value" => score},
      "source_window" => %{"type" => "unvalidated_urgent_placeholder"},
      "metadata" => urgent_target_metadata(event, priority, context, index)
    }
  end

  defp stage_downlink_completion(
         candidate_plan,
         warnings,
         event,
         request,
         source_candidate_activities,
         candidate_diff_by_replacement_id
       ) do
    required_downlink_mb = event_required_downlink_mb(event, request)

    current_downlink_mb =
      case Map.get(event, "planned_downlink_mb") do
        value when is_number(value) -> value
        _value -> planned_downlink_mb(candidate_plan["activities"], event)
      end

    required_contacts =
      event
      |> Map.get(
        "required_contacts",
        required_downlink_contacts(request.mission_state, request.prior_plan)
      )
      |> ceil_count()

    current_contacts =
      case Map.get(event, "planned_contacts") do
        value when is_number(value) ->
          ceil_count(value)

        _value ->
          candidate_plan["activities"]
          |> Enum.map(&stringify_keys/1)
          |> Enum.count(&(downlink_activity?(&1) and downlink_completion_event_match?(&1, event)))
      end

    needed_contacts = max(required_contacts - current_contacts, 0)

    needed_downlink_mb =
      case required_downlink_mb do
        value when is_number(value) -> max(value - current_downlink_mb, 0.0)
        _value -> 0.0
      end

    if needed_contacts == 0 and needed_downlink_mb <= 0.0 do
      {candidate_plan, warnings}
    else
      selected =
        source_candidate_activities
        |> downlink_completion_candidates(event, request)
        |> select_downlink_completion_candidates(
          downlink_completion_occupied_activities(candidate_plan["activities"], event),
          needed_contacts,
          needed_downlink_mb
        )

      case selected do
        [] ->
          {candidate_plan,
           ["downlink completion gap not staged: no_validated_candidate_window" | warnings]}

        downlinks ->
          staged_downlink_mb = planned_downlink_mb(downlinks, event)

          additions =
            Enum.map(
              downlinks,
              &downlink_completion_addition(&1, event, candidate_diff_by_replacement_id, %{
                "required_downlink_mb" => required_downlink_mb,
                "planned_downlink_mb" => current_downlink_mb,
                "staged_downlink_mb" => staged_downlink_mb
              })
            )

          candidate_plan =
            candidate_plan
            |> Map.update!("activities", &(additions ++ &1))
            |> Map.update!("strategic_additions", &(additions ++ &1))

          {candidate_plan, warnings}
      end
    end
  end

  defp downlink_completion_occupied_activities(activities, event) do
    ignored_ids = provider_failed_downlink_activity_ids(event)

    if MapSet.size(ignored_ids) == 0 do
      activities
    else
      Enum.reject(activities, &MapSet.member?(ignored_ids, activity_id(&1)))
    end
  end

  defp provider_failed_downlink_activity_ids(%{"contact_result" => result} = event) do
    if provider_result_failure_value?(result) do
      [
        event["missed_downlink_activity_id"],
        event["missed_downlink_activity_ids"],
        event["source_activity_id"],
        event["source_activity_ids"],
        event["missed_downlink"],
        event["missed_downlinks"],
        event["source_contact"],
        event["source_contacts"]
      ]
      |> Enum.flat_map(&split_activity_ids/1)
      |> MapSet.new()
    else
      MapSet.new()
    end
  end

  defp provider_failed_downlink_activity_ids(_event), do: MapSet.new()

  defp split_activity_ids(value) when is_binary(value) do
    value
    |> String.split(",", trim: true)
    |> Enum.map(&String.trim/1)
    |> Enum.reject(&(&1 == ""))
  end

  defp split_activity_ids(values) when is_list(values) do
    Enum.flat_map(values, &split_activity_ids/1)
  end

  defp split_activity_ids(%{} = value) do
    value
    |> score_term_activity_id_values()
    |> Enum.flat_map(&split_activity_ids/1)
  end

  defp split_activity_ids(_value), do: []

  defp event_required_downlink_mb(%{} = event, request) do
    objective_required_downlink_mb(event) || mission_required_downlink_mb(request.mission_state)
  end

  defp downlink_completion_candidates(source_candidate_activities, event, request) do
    source_candidate_activities
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(&normalize_downlink_activity/1)
    |> Enum.filter(&downlink_activity?/1)
    |> Enum.filter(
      &within_remaining_horizon?(
        &1,
        request.remaining_horizon || default_strategy_horizon(request)
      )
    )
    |> Enum.filter(&downlink_completion_event_match?(&1, event))
    |> Enum.sort_by(fn candidate ->
      {-candidate_score(candidate), activity_start(candidate), activity_id(candidate)}
    end)
  end

  defp downlink_completion_event_match?(candidate, event) do
    station_id = event_ground_station_id(event)
    scenario_id = Map.get(event, "scenario_id")
    starts_at_s = Map.get(event, "starts_at_s") || Map.get(event, "start_s")
    ends_at_s = Map.get(event, "ends_at_s") || Map.get(event, "end_s")
    window_selector? = downlink_completion_event_window_selector?(event)

    (is_nil(station_id) or activity_ground_station_id(candidate) == station_id) and
      (is_nil(scenario_id) or candidate["scenario_id"] == scenario_id) and
      (not window_selector? or not is_number(starts_at_s) or
         activity_start(candidate) >= starts_at_s) and
      (not window_selector? or not is_number(ends_at_s) or activity_end(candidate) <= ends_at_s) and
      downlink_event_identity_match?(candidate, event)
  end

  defp downlink_completion_event_window_selector?(%{"feedback_scope" => "timeline_diff"}),
    do: false

  defp downlink_completion_event_window_selector?(_event), do: true

  defp downlink_event_identity_match?(candidate, event) do
    Enum.all?(
      [
        {collection_identity_keys(), collection_identity_keys()},
        {payload_identity_keys(), payload_identity_keys()},
        {instrument_identity_keys(), instrument_identity_keys()},
        {product_identity_keys(), product_identity_keys()}
      ],
      fn {event_keys, candidate_keys} ->
        event_values = identity_selector_values(event, event_keys)
        candidate_values = identity_selector_values(candidate, candidate_keys)

        event_values == [] or candidate_values == [] or
          Enum.any?(candidate_values, &(&1 in event_values))
      end
    )
  end

  defp proposed_contacts(candidates) do
    candidates
    |> Enum.map(&normalize_downlink_activity/1)
    |> Enum.filter(&downlink_activity?/1)
    |> Enum.filter(&valid_proposed_contact?/1)
    |> Enum.map(&proposed_contact_row/1)
  end

  defp proposed_contact_row(activity) do
    activity
    |> Map.put("type", "downlink")
    |> Map.put("direction", "downlink")
  end

  defp valid_proposed_contact?(activity) do
    not is_nil(Map.get(activity, "id")) and
      not is_nil(Map.get(activity, "scenario_id")) and
      not is_nil(Map.get(activity, "ground_station_id")) and
      is_number(Map.get(activity, "starts_at_s")) and
      is_number(Map.get(activity, "ends_at_s")) and
      is_number(Map.get(activity, "estimated_throughput_mb")) and
      is_map(Map.get(activity, "source_window")) and
      is_map(Map.get(activity, "cadence_import"))
  end

  defp normalize_downlink_activity(%{} = activity) do
    activity
    |> normalize_activity_type_alias()
    |> normalize_activity_station_id()
    |> normalize_activity_data_identity()
    |> normalize_activity_time("starts_at_s", "start_s")
    |> normalize_activity_time("ends_at_s", "end_s")
    |> normalize_activity_number("estimated_throughput_mb")
    |> normalize_activity_number("planned_throughput_mb")
    |> normalize_activity_number("capacity_adjusted_throughput_mb")
    |> normalize_activity_number("station_capacity_fraction")
    |> normalize_activity_number("score")
    |> normalize_activity_throughput_model()
    |> normalize_inferred_provider_downlink()
  end

  defp normalize_downlink_activity(activity), do: activity

  defp normalize_activity_station_id(%{"ground_station_id" => station_id} = activity)
       when not is_nil(station_id),
       do: activity

  defp normalize_activity_station_id(%{"station_id" => station_id} = activity)
       when not is_nil(station_id),
       do: Map.put(activity, "ground_station_id", station_id)

  defp normalize_activity_station_id(activity) do
    case nested_ground_station_id(activity) do
      nil -> activity
      station_id -> Map.put(activity, "ground_station_id", station_id)
    end
  end

  defp normalize_activity_data_identity(activity) do
    activity
    |> put_activity_identity_field("collection_id", collection_identity_keys())
    |> put_activity_identity_field("product_id", product_identity_keys())
    |> put_activity_product_ids()
    |> put_activity_identity_field("payload_id", payload_identity_keys())
    |> put_activity_identity_field("instrument_id", instrument_identity_keys())
  end

  defp put_activity_identity_field(activity, field, keys) do
    case Map.get(activity, field) do
      value when value not in [nil, ""] ->
        activity

      _value ->
        case identity_selector_values(activity, keys) do
          [] -> activity
          [value | _values] -> Map.put(activity, field, value)
        end
    end
  end

  defp put_activity_product_ids(activity) do
    if Map.has_key?(activity, "product_ids") do
      activity
    else
      values =
        identity_selector_values(activity, [
          "product_ids",
          "data_product_ids",
          "products",
          "data_products"
        ])

      case values do
        [] -> activity
        values -> Map.put(activity, "product_ids", values)
      end
    end
  end

  defp nested_ground_station_id(activity) do
    Enum.find_value(["ground_station", "station", :ground_station, :station], fn station_key ->
      case Map.get(activity, station_key) do
        %{} = station ->
          Enum.find_value(
            ["ground_station_id", "station_id", "id", :ground_station_id, :station_id, :id],
            fn identity_key -> Map.get(station, identity_key) end
          )

        _station ->
          nil
      end
    end)
  end

  defp normalize_activity_time(activity, canonical_key, alternate_key) do
    case {numeric_or_nil(Map.get(activity, canonical_key)),
          numeric_or_nil(Map.get(activity, alternate_key))} do
      {value, _alternate} when is_number(value) -> Map.put(activity, canonical_key, value)
      {nil, value} when is_number(value) -> Map.put(activity, canonical_key, value)
      _values -> activity
    end
  end

  defp normalize_activity_number(activity, key) do
    case numeric_or_nil(Map.get(activity, key)) do
      value when is_number(value) -> Map.put(activity, key, value)
      _value -> activity
    end
  end

  defp normalize_activity_throughput_model(
         %{"throughput_model" => %{} = throughput_model} = activity
       ) do
    throughput_model =
      throughput_model
      |> normalize_activity_number("estimated_throughput_mb")
      |> normalize_activity_number("planned_throughput_mb")
      |> normalize_activity_number("capacity_adjusted_throughput_mb")
      |> normalize_activity_number("station_capacity_fraction")
      |> normalize_activity_number("required_downlink_mb")

    Map.put(activity, "throughput_model", throughput_model)
  end

  defp normalize_activity_throughput_model(activity), do: activity

  defp normalize_inferred_provider_downlink(activity) do
    if provider_downlink_activity?(activity) do
      activity
      |> Map.put_new("type", "downlink")
      |> Map.put_new("direction", "downlink")
    else
      activity
    end
  end

  defp normalize_activity_type_alias(%{"type" => type} = activity) when not is_nil(type),
    do: activity

  defp normalize_activity_type_alias(%{"activity_type" => type} = activity)
       when is_binary(type) and type != "",
       do: Map.put(activity, "type", type)

  defp normalize_activity_type_alias(activity), do: activity

  defp provider_downlink_activity?(activity) do
    type = Map.get(activity, "type") || Map.get(activity, "activity_type")
    direction = activity_direction(activity)

    type in [nil, "contact", "planned_contact"] and
      direction in [nil, "downlink"] and
      not command_feedback_activity?(activity) and
      not is_nil(activity_ground_station_id(activity)) and
      is_number(activity_raw_start(activity)) and
      is_number(activity_raw_end(activity))
  end

  defp command_feedback_activity?(activity) do
    Map.has_key?(activity, "command_success") or Map.has_key?(activity, "command_result")
  end

  defp downlink_activity?(%{"type" => "downlink"}), do: true
  defp downlink_activity?(%{"type" => "planned_contact", "direction" => "downlink"}), do: true
  defp downlink_activity?(%{"type" => "contact", "direction" => "downlink"}), do: true
  defp downlink_activity?(activity), do: provider_downlink_activity?(activity)

  defp command_activity?(activity) do
    type = Map.get(activity, "type") || Map.get(activity, "activity_type")
    direction = activity_direction(activity)

    type in @command_health_activity_types or
      (type in ["planned_contact", "contact"] and
         direction in ["command", "uplink", "health_check"]) or
      Map.has_key?(activity, "command_success")
  end

  defp activity_direction(activity), do: normalized_status_token(Map.get(activity, "direction"))

  defp select_downlink_completion_candidates(
         candidates,
         occupied_activities,
         needed_count,
         needed_mb
       ) do
    candidates
    |> Enum.reduce_while({[], occupied_activities, 0.0}, fn candidate, {selected, occupied, mb} ->
      cond do
        downlink_completion_requirement_met?(selected, mb, needed_count, needed_mb) ->
          {:halt, {selected, occupied, mb}}

        Enum.any?(occupied, &overlaps?(&1, candidate)) ->
          {:cont, {selected, occupied, mb}}

        true ->
          {:cont,
           {
             [candidate | selected],
             [candidate | occupied],
             mb + downlink_activity_mb(candidate)
           }}
      end
    end)
    |> elem(0)
    |> Enum.reverse()
  end

  defp downlink_completion_requirement_met?(selected, mb, needed_count, needed_mb) do
    count_met? = needed_count <= 0 or length(selected) >= needed_count
    mb_met? = needed_mb <= 0.0 or mb >= needed_mb

    count_met? and mb_met?
  end

  defp select_non_overlapping_candidates(candidates, occupied_activities, needed_count) do
    candidates
    |> Enum.reduce_while({[], occupied_activities}, fn candidate, {selected, occupied} ->
      cond do
        length(selected) >= needed_count ->
          {:halt, {selected, occupied}}

        Enum.any?(occupied, &overlaps?(&1, candidate)) ->
          {:cont, {selected, occupied}}

        true ->
          {:cont, {[candidate | selected], [candidate | occupied]}}
      end
    end)
    |> elem(0)
    |> Enum.reverse()
  end

  defp downlink_completion_addition(
         candidate,
         event,
         candidate_diff_by_replacement_id,
         throughput_context
       ) do
    candidate_diff =
      candidate_diff_by_replacement_id
      |> Map.get(activity_id(candidate))
      |> candidate_diff_match("replacement")

    feasibility =
      %{
        "status" => "validated_candidate_window",
        "ground_station_id" => candidate["ground_station_id"],
        "selected_scenario_id" => candidate["scenario_id"],
        "source_window" => Map.get(candidate, "source_window", %{"type" => "candidate_activity"}),
        "required_contacts" => event["required_contacts"],
        "planned_contacts" => event["planned_contacts"],
        "required_downlink_mb" => throughput_context["required_downlink_mb"],
        "planned_downlink_mb" => throughput_context["planned_downlink_mb"],
        "staged_downlink_mb" => throughput_context["staged_downlink_mb"],
        "candidate_downlink_mb" => downlink_activity_mb(candidate),
        "requires_approval" => true
      }
      |> Map.merge(event_feasibility_context(event))
      |> compact_map()
      |> maybe_put_candidate_diff(candidate_diff)

    put_repair_metadata(
      candidate,
      %{
        "action" => "strategic_addition",
        "reason" => downlink_addition_reason(event),
        "requires_approval" => true
      }
      |> maybe_put_candidate_diff(candidate_diff)
    )
    |> put_in(["feasibility"], feasibility)
  end

  defp downlink_addition_reason(%{"objective_type" => "collection_latency"}),
    do: "collection_latency_downlink_candidate_inserted"

  defp downlink_addition_reason(%{"derivation_reasons" => reasons}) when is_list(reasons) do
    cond do
      "storage_margin_low" in reasons -> "storage_relief_downlink_candidate_inserted"
      "downlink_margin_low" in reasons -> "downlink_margin_candidate_inserted"
      true -> "downlink_completion_candidate_inserted"
    end
  end

  defp downlink_addition_reason(_event), do: "downlink_completion_candidate_inserted"

  defp event_feasibility_context(event) do
    %{
      "source_event_type" => event["type"],
      "source_event_id" => event["id"],
      "source_branch_id" => event["branch_id"],
      "source_activity_id" => event["source_activity_id"],
      "source_activity_ids" => event["source_activity_ids"],
      "source_window_id" => event["source_window_id"],
      "source_window_ids" => event["source_window_ids"],
      "source_timeline_id" => event["timeline_id"],
      "objective_id" => event["objective_id"],
      "objective_ids" => event["objective_ids"],
      "objective_type" => event["objective_type"],
      "target_id" => event["target_id"],
      "target_ids" => event["target_ids"],
      "collection_id" => event["collection_id"],
      "collection_ids" => event["collection_ids"],
      "product_id" => event["product_id"],
      "product_ids" => event["product_ids"],
      "payload_id" => event["payload_id"],
      "payload_ids" => event["payload_ids"],
      "instrument_id" => event["instrument_id"],
      "instrument_ids" => event["instrument_ids"],
      "contact_result" => event["contact_result"],
      "observation_result" => event["observation_result"],
      "command_result" => event["command_result"],
      "realized_status" => event["realized_status"],
      "status_transition" => event["status_transition"],
      "transition_type" => event["transition_type"],
      "transition_category" => event["transition_category"],
      "transition_reason" => event["transition_reason"],
      "requires_operator_review" => event["requires_operator_review"],
      "downlink_demand_sources" => event["downlink_demand_sources"],
      "downlink_completion_sources" => event["downlink_completion_sources"],
      "feedback_source" => event["feedback_source"],
      "feedback_scope" => event["feedback_scope"],
      "trust_boundary" =>
        event["trust_boundary"] || get_in(event, ["provenance", "trust_boundary"]),
      "source_event_provenance" => event["provenance"],
      "derivation_reason" => event["derivation_reason"],
      "derivation_reasons" => event["derivation_reasons"],
      "capacity_pack_group_id" => event["capacity_pack_group_id"],
      "capacity_pack_status" => event["capacity_pack_status"],
      "capacity_pack_capacity_fraction" => event["capacity_pack_capacity_fraction"],
      "capacity_pack_used_fraction" => event["capacity_pack_used_fraction"]
    }
    |> compact_map()
  end

  defp ceil_count(value) when is_integer(value), do: max(value, 0)
  defp ceil_count(value) when is_float(value), do: value |> Float.ceil() |> trunc() |> max(0)
  defp ceil_count(_value), do: 0

  defp strategic_score_terms(
         candidate_plan,
         repair_result,
         risk_indicators,
         branch,
         request,
         resource_impacts,
         feedback_adjustments
       ) do
    policy = request.strategy_policy
    activities = candidate_plan["activities"]
    repair_score_terms = Map.get(repair_result, "score_terms", %{})
    approval_count = length(branch_approval_requirements(repair_result, candidate_plan))
    risk_count = length(risk_indicators)
    contact_allocation_pressure_count = contact_allocation_pressure_risk_count(risk_indicators)
    link_capacity_pressure_count = link_capacity_pressure_risk_count(risk_indicators)
    contact_intent_pressure_count = contact_intent_pressure_risk_count(risk_indicators)
    contact_contention_pressure_count = contact_contention_pressure_risk_count(risk_indicators)
    contact_filter_pressure_count = contact_filter_pressure_risk_count(risk_indicators)

    operational_readiness_pressure_count =
      operational_readiness_pressure_risk_count(risk_indicators)

    operator_training_pressure_count =
      operator_training_pressure_risk_count(risk_indicators)

    import_readiness_pressure_count =
      import_readiness_pressure_risk_count(risk_indicators)

    quality_gate_pressure_count = quality_gate_pressure_risk_count(risk_indicators)
    approval_boundary_pressure_count = approval_boundary_pressure_risk_count(risk_indicators)
    timeline_integrity_pressure_count = timeline_integrity_pressure_risk_count(risk_indicators)

    timeline_dependency_impact_pressure_count =
      timeline_dependency_impact_pressure_risk_count(risk_indicators)

    timeline_publication_pressure_count =
      timeline_publication_pressure_risk_count(risk_indicators)

    timeline_lifecycle_pressure_count =
      timeline_lifecycle_pressure_risk_count(risk_indicators)

    timeline_precondition_pressure_count =
      timeline_precondition_pressure_risk_count(risk_indicators)

    timeline_preservation_pressure_count =
      timeline_preservation_pressure_risk_count(risk_indicators)

    timeline_pressure_count = timeline_pressure_risk_count(risk_indicators)
    storage_downlink_pressure_count = storage_downlink_pressure_risk_count(risk_indicators)

    resource_availability_pressure_count =
      resource_availability_pressure_risk_count(risk_indicators)

    resource_margin_pressure_count = resource_margin_pressure_risk_count(risk_indicators)
    battery_depletion_pressure_count = battery_depletion_pressure_risk_count(risk_indicators)

    station_calendar_pressure_count = station_calendar_pressure_risk_count(risk_indicators)
    candidate_rejection_pressure_count = candidate_rejection_pressure_risk_count(risk_indicators)

    provider_counteroffer_pressure_count =
      provider_counteroffer_pressure_risk_count(risk_indicators)

    validation_refresh_pressure_count =
      validation_refresh_pressure_risk_count(risk_indicators)

    relay_data_path_pressure_count =
      relay_data_path_pressure_risk_count(risk_indicators)

    execution_feedback_pressure_count =
      execution_feedback_pressure_risk_count(risk_indicators)

    generic_risk_count =
      max(
        risk_count - contact_allocation_pressure_count - approval_boundary_pressure_count -
          link_capacity_pressure_count - contact_intent_pressure_count -
          contact_contention_pressure_count -
          contact_filter_pressure_count -
          operational_readiness_pressure_count - operator_training_pressure_count -
          import_readiness_pressure_count - quality_gate_pressure_count -
          timeline_integrity_pressure_count - timeline_dependency_impact_pressure_count -
          timeline_publication_pressure_count - timeline_lifecycle_pressure_count -
          timeline_precondition_pressure_count - timeline_preservation_pressure_count -
          timeline_pressure_count - storage_downlink_pressure_count -
          resource_availability_pressure_count - resource_margin_pressure_count -
          battery_depletion_pressure_count - station_calendar_pressure_count -
          candidate_rejection_pressure_count - provider_counteroffer_pressure_count -
          validation_refresh_pressure_count -
          relay_data_path_pressure_count - execution_feedback_pressure_count,
        0
      )

    mission_value_score =
      activities
      |> Enum.map(&candidate_score/1)
      |> Enum.sum()
      |> Kernel.*(policy.mission_value_weight)

    coverage_score = target_count(activities) * policy.coverage_weight
    revisit_score = revisit_count(activities) * policy.revisit_weight
    latency_penalty = -collection_latency_s(activities) * policy.latency_weight

    downlink_completion_score =
      downlink_completion_ratio(activities, request) * policy.downlink_completion_weight

    fuel_preservation_score =
      fuel_preservation_score(branch, request) * policy.fuel_preservation_weight

    schedule_stability_penalty =
      schedule_stability_penalty(repair_score_terms) * policy.schedule_stability_weight

    asset_balance_score = asset_balance_score(activities) * policy.asset_balance_weight

    priority_commitment_score =
      priority_commitment_score(activities, request) * policy.priority_commitment_weight

    resource_score =
      numeric_or_nil(Map.get(resource_impacts, "score_adjustment")) || 0.0

    feedback_adjustment_score =
      numeric_or_nil(Map.get(feedback_adjustments, "score_adjustment")) || 0.0

    contact_allocation_pressure_penalty =
      -contact_allocation_pressure_count * policy.risk_weight

    link_capacity_pressure_penalty =
      -link_capacity_pressure_count * policy.risk_weight

    contact_intent_pressure_penalty =
      -contact_intent_pressure_count * policy.risk_weight

    contact_contention_pressure_penalty =
      -contact_contention_pressure_count * policy.risk_weight

    contact_filter_pressure_penalty =
      -contact_filter_pressure_count * policy.risk_weight

    operational_readiness_pressure_penalty =
      -operational_readiness_pressure_count * policy.risk_weight

    operator_training_pressure_penalty =
      -operator_training_pressure_count * policy.risk_weight

    import_readiness_pressure_penalty =
      -import_readiness_pressure_count * policy.risk_weight

    quality_gate_pressure_penalty =
      -quality_gate_pressure_count * policy.risk_weight

    approval_boundary_pressure_penalty =
      -approval_boundary_pressure_count * policy.risk_weight

    timeline_integrity_pressure_penalty =
      -timeline_integrity_pressure_count * policy.risk_weight

    timeline_dependency_impact_pressure_penalty =
      -timeline_dependency_impact_pressure_count * policy.risk_weight

    timeline_publication_pressure_penalty =
      -timeline_publication_pressure_count * policy.risk_weight

    timeline_lifecycle_pressure_penalty =
      -timeline_lifecycle_pressure_count * policy.risk_weight

    timeline_precondition_pressure_penalty =
      -timeline_precondition_pressure_count * policy.risk_weight

    timeline_preservation_pressure_penalty =
      -timeline_preservation_pressure_count * policy.risk_weight

    timeline_pressure_penalty =
      -timeline_pressure_count * policy.risk_weight

    storage_downlink_pressure_penalty =
      -storage_downlink_pressure_count * policy.risk_weight

    resource_availability_pressure_penalty =
      -resource_availability_pressure_count * policy.risk_weight

    resource_margin_pressure_penalty =
      -resource_margin_pressure_count * policy.risk_weight

    battery_depletion_pressure_penalty =
      -battery_depletion_pressure_count * policy.risk_weight

    station_calendar_pressure_penalty =
      -station_calendar_pressure_count * policy.risk_weight

    candidate_rejection_pressure_penalty =
      -candidate_rejection_pressure_count * policy.risk_weight

    provider_counteroffer_pressure_penalty =
      -provider_counteroffer_pressure_count * policy.risk_weight

    validation_refresh_pressure_penalty =
      -validation_refresh_pressure_count * policy.risk_weight

    relay_data_path_pressure_penalty =
      -relay_data_path_pressure_count * policy.risk_weight

    execution_feedback_pressure_penalty =
      -execution_feedback_pressure_count * policy.risk_weight

    risk_penalty = -generic_risk_count * policy.risk_weight
    approval_load_penalty = -approval_count * policy.approval_load_weight

    raw_score =
      mission_value_score + coverage_score + revisit_score + latency_penalty +
        downlink_completion_score + fuel_preservation_score + schedule_stability_penalty +
        asset_balance_score + priority_commitment_score + resource_score +
        feedback_adjustment_score + contact_allocation_pressure_penalty +
        link_capacity_pressure_penalty + contact_intent_pressure_penalty +
        contact_contention_pressure_penalty + operational_readiness_pressure_penalty +
        contact_filter_pressure_penalty + operator_training_pressure_penalty +
        import_readiness_pressure_penalty + quality_gate_pressure_penalty +
        approval_boundary_pressure_penalty +
        timeline_integrity_pressure_penalty + timeline_dependency_impact_pressure_penalty +
        timeline_publication_pressure_penalty + timeline_lifecycle_pressure_penalty +
        timeline_precondition_pressure_penalty + timeline_preservation_pressure_penalty +
        timeline_pressure_penalty + storage_downlink_pressure_penalty +
        resource_availability_pressure_penalty + resource_margin_pressure_penalty +
        battery_depletion_pressure_penalty + station_calendar_pressure_penalty +
        candidate_rejection_pressure_penalty + provider_counteroffer_pressure_penalty +
        validation_refresh_pressure_penalty +
        relay_data_path_pressure_penalty + execution_feedback_pressure_penalty +
        risk_penalty + approval_load_penalty

    probability = Map.get(branch, "probability", 1.0)
    expected_score = raw_score * probability * policy.probability_weight

    %{
      "mission_value_score" => mission_value_score,
      "coverage_score" => coverage_score,
      "revisit_score" => revisit_score,
      "latency_penalty" => latency_penalty,
      "downlink_completion_score" => downlink_completion_score,
      "fuel_preservation_score" => fuel_preservation_score,
      "schedule_stability_penalty" => schedule_stability_penalty,
      "asset_balance_score" => asset_balance_score,
      "priority_commitment_score" => priority_commitment_score,
      "resource_score" => resource_score,
      "feedback_adjustment_score" => feedback_adjustment_score,
      "contact_allocation_pressure_penalty" => contact_allocation_pressure_penalty,
      "link_capacity_pressure_penalty" => link_capacity_pressure_penalty,
      "contact_intent_pressure_penalty" => contact_intent_pressure_penalty,
      "contact_contention_pressure_penalty" => contact_contention_pressure_penalty,
      "contact_filter_pressure_penalty" => contact_filter_pressure_penalty,
      "operational_readiness_pressure_penalty" => operational_readiness_pressure_penalty,
      "operator_training_pressure_penalty" => operator_training_pressure_penalty,
      "import_readiness_pressure_penalty" => import_readiness_pressure_penalty,
      "quality_gate_pressure_penalty" => quality_gate_pressure_penalty,
      "approval_boundary_pressure_penalty" => approval_boundary_pressure_penalty,
      "timeline_integrity_pressure_penalty" => timeline_integrity_pressure_penalty,
      "timeline_dependency_impact_pressure_penalty" =>
        timeline_dependency_impact_pressure_penalty,
      "timeline_publication_pressure_penalty" => timeline_publication_pressure_penalty,
      "timeline_lifecycle_pressure_penalty" => timeline_lifecycle_pressure_penalty,
      "timeline_precondition_pressure_penalty" => timeline_precondition_pressure_penalty,
      "timeline_preservation_pressure_penalty" => timeline_preservation_pressure_penalty,
      "timeline_pressure_penalty" => timeline_pressure_penalty,
      "storage_downlink_pressure_penalty" => storage_downlink_pressure_penalty,
      "resource_availability_pressure_penalty" => resource_availability_pressure_penalty,
      "resource_margin_pressure_penalty" => resource_margin_pressure_penalty,
      "battery_depletion_pressure_penalty" => battery_depletion_pressure_penalty,
      "station_calendar_pressure_penalty" => station_calendar_pressure_penalty,
      "candidate_rejection_pressure_penalty" => candidate_rejection_pressure_penalty,
      "provider_counteroffer_pressure_penalty" => provider_counteroffer_pressure_penalty,
      "validation_refresh_pressure_penalty" => validation_refresh_pressure_penalty,
      "relay_data_path_pressure_penalty" => relay_data_path_pressure_penalty,
      "execution_feedback_pressure_penalty" => execution_feedback_pressure_penalty,
      "risk_penalty" => risk_penalty,
      "approval_load_penalty" => approval_load_penalty,
      "raw_score" => raw_score,
      "branch_probability" => probability,
      "expected_score" => expected_score
    }
  end

  defp contact_allocation_pressure_risk_count(risk_indicators) do
    Enum.count(risk_indicators, &contact_allocation_pressure_risk?/1)
  end

  defp contact_allocation_pressure_risk?(%{"type" => "provider_reservation_request_review"}),
    do: true

  defp contact_allocation_pressure_risk?(%{"type" => "downlink_completion_gap"} = risk) do
    risk["feedback_scope"] == "contact_allocation" or
      risk["feedback_scope"] == "contact_allocation_provider_reservation_request" or
      Enum.any?(List.wrap(risk["derivation_reasons"]), fn reason ->
        reason
        |> to_string()
        |> String.starts_with?("contact_allocation")
      end)
  end

  defp contact_allocation_pressure_risk?(_risk), do: false

