    schema_validation_quality_gate_pressure_risk?(risk)
  end

  defp validation_refresh_pressure_risk?(%{"type" => "operational_readiness_pressure"} = risk) do
    operational_readiness_schema_validation_pressure_risk?(risk)
  end

  defp validation_refresh_pressure_risk?(_risk), do: false

  defp schema_validation_quality_gate_pressure_risk?(%{"type" => "quality_gate_pressure"} = risk) do
    risk["schema_validation_import_blocked"] == true or
      is_map(risk["schema_validation_status_counts"]) or
      get_in(risk, ["source_quality_gate_report", "schema_contract"]) ==
        "operational_quality_gate_schema_validation_summary.v1"
  end

  defp schema_validation_quality_gate_pressure_risk?(_risk), do: false

  defp operational_readiness_schema_validation_pressure_risk?(
         %{"type" => "operational_readiness_pressure"} = risk
       ) do
    risk["schema_validation_import_blocked"] == true or
      numeric_or_nil(risk["schema_validation_row_count"]) not in [nil, 0.0] or
      numeric_or_nil(risk["schema_validation_fail_count"]) not in [nil, 0.0] or
      numeric_or_nil(risk["schema_validation_error_count"]) not in [nil, 0.0] or
      numeric_or_nil(risk["schema_validation_warning_count"]) not in [nil, 0.0] or
      numeric_or_nil(risk["schema_validation_remediation_count"]) not in [nil, 0.0] or
      is_map(risk["schema_validation_status_counts"]) or
      risk["failed_schema_validation_quality_gate_row_ids"] not in [nil, []]
  end

  defp operational_readiness_schema_validation_pressure_risk?(_risk), do: false

  defp relay_data_path_pressure_risk_count(risk_indicators) do
    Enum.count(risk_indicators, &relay_data_path_pressure_risk?/1)
  end

  defp relay_data_path_pressure_risk?(%{"type" => "relay_data_path_pressure"}), do: true
  defp relay_data_path_pressure_risk?(_risk), do: false

  defp execution_feedback_pressure_risk_count(risk_indicators) do
    Enum.count(risk_indicators, &execution_feedback_pressure_risk?/1)
  end

  defp execution_feedback_pressure_risk?(%{"type" => type})
       when type in [
              "contact_success_rate_low",
              "observation_success_rate_low",
              "station_throughput_factor_low",
              "command_success_rate_low",
              "maneuver_success_rate_low",
              "maneuver_execution_uncertainty_high",
              "maneuver_execution_uncertainty_missing"
            ],
       do: true

  defp execution_feedback_pressure_risk?(_risk), do: false

  defp branch_risk_indicators(
         branch,
         repair_result,
         candidate_plan,
         request,
         resource_impacts,
         resource_projection_report,
         feedback_adjustments,
         candidate_source
       ) do
    event_risks =
      branch["events"]
      |> Enum.flat_map(&event_risk_indicators/1)

    warning_risks =
      repair_result
      |> Map.get("warnings", [])
      |> Enum.map(fn warning ->
        %{"type" => "repair_warning", "severity" => "medium", "reason" => warning}
      end)

    objective_risks =
      []
      |> maybe_add_no_downlink_risk(candidate_plan, request)
      |> maybe_add_unmet_priority_commitment_risk(candidate_plan, request)

    resource_risks = Map.get(resource_impacts, "risk_indicators", [])
    resource_projection_risks = resource_projection_risk_indicators(resource_projection_report)
    feedback_risks = Map.get(feedback_adjustments, "risk_indicators", [])

    candidate_source_risks =
      candidate_source_risk_indicators(candidate_source, branch, event_risks)

    feasibility_risks =
      candidate_plan
      |> Map.get("strategic_additions", [])
      |> Enum.filter(&(get_in(&1, ["feasibility", "status"]) == "unvalidated_placeholder"))
      |> Enum.map(fn activity ->
        %{
          "type" => "urgent_target_unvalidated",
          "severity" => "medium",
          "reason" => "urgent target #{activity["target_id"]} has no validated candidate window",
          "target_id" => activity["target_id"]
        }
        |> compact_map()
      end)

    (event_risks ++
       warning_risks ++
       objective_risks ++
       resource_risks ++
       resource_projection_risks ++
       feedback_risks ++
       candidate_source_risks ++
       feasibility_risks)
    |> Enum.uniq()
    |> Enum.sort_by(&{&1["severity"], &1["type"], &1["reason"]})
  end

  defp candidate_source_risk_indicators(candidate_source, branch, event_risks) do
    if branch["events"] in [nil, []] do
      []
    else
      candidate_source_risk_indicators(candidate_source, event_risks)
    end
  end

  defp candidate_source_risk_indicators(%{"scope" => scope} = candidate_source, event_risks)
       when scope in ["branch", "branch_generated"] do
    contact_allocation_replay =
      CandidateRefresh.contact_allocation_replay_summary(candidate_source)

    operational_readiness_replay =
      CandidateRefresh.operational_readiness_replay_summary(candidate_source)

    quality_gate_replay =
      CandidateRefresh.quality_gate_replay_summary(candidate_source)

    lifecycle_replay =
      CandidateRefresh.timeline_lifecycle_state_replay_summary(candidate_source)

    activity_state_replay =
      CandidateRefresh.timeline_activity_state_replay_summary(candidate_source)

    publication_replay =
      CandidateRefresh.timeline_publication_replay_summary(candidate_source)

    []
    |> maybe_add_candidate_source_contact_allocation_risks(contact_allocation_replay, event_risks)
    |> maybe_add_candidate_source_operational_readiness_risks(
      operational_readiness_replay,
      event_risks
    )
    |> maybe_add_candidate_source_quality_gate_risks(quality_gate_replay, event_risks)
    |> maybe_add_candidate_source_timeline_activity_state_risks(
      activity_state_replay,
      event_risks
    )
    |> maybe_add_candidate_source_timeline_lifecycle_risks(lifecycle_replay, event_risks)
    |> maybe_add_candidate_source_timeline_publication_risks(publication_replay, event_risks)
  end

  defp candidate_source_risk_indicators(_candidate_source, _event_risks), do: []

  defp maybe_add_candidate_source_contact_allocation_risks(risks, replay_summary, event_risks) do
    if Enum.any?(event_risks, &contact_allocation_pressure_risk?/1) do
      risks
    else
      risks ++
        contact_allocation_replay_reservation_conflict_risks(replay_summary) ++
        contact_allocation_replay_provider_reservation_risks(replay_summary)
    end
  end

  defp maybe_add_candidate_source_operational_readiness_risks(
         risks,
         replay_summary,
         event_risks
       ) do
    if Enum.any?(event_risks, &operational_readiness_pressure_event_risk?/1) do
      risks
    else
      risks ++ operational_readiness_replay_pressure_risks(replay_summary)
    end
  end

  defp maybe_add_candidate_source_quality_gate_risks(risks, replay_summary, event_risks) do
    if Enum.any?(event_risks, &quality_gate_pressure_event_risk?/1) do
      risks
    else
      risks ++ quality_gate_replay_pressure_risks(replay_summary)
    end
  end

  defp maybe_add_candidate_source_timeline_lifecycle_risks(risks, replay_summary, event_risks) do
    if Enum.any?(event_risks, &timeline_lifecycle_state_review_risk?/1) do
      risks
    else
      risks ++ timeline_lifecycle_replay_review_risks(replay_summary)
    end
  end

  defp maybe_add_candidate_source_timeline_activity_state_risks(
         risks,
         replay_summary,
         event_risks
       ) do
    if Enum.any?(event_risks, &timeline_activity_lifecycle_state_review_risk?/1) do
      risks
    else
      risks ++ timeline_activity_state_replay_review_risks(replay_summary)
    end
  end

  defp maybe_add_candidate_source_timeline_publication_risks(risks, replay_summary, event_risks) do
    if Enum.any?(event_risks, &timeline_publication_pressure_risk?/1) do
      risks
    else
      risks ++ timeline_publication_replay_pressure_risks(replay_summary)
    end
  end

  defp contact_allocation_replay_reservation_conflict_risks(replay_summary) do
    reservation_ids_by_match_status =
      Map.get(replay_summary, "reservation_conflict_reservation_ids_by_match_status", %{})

    replay_summary
    |> Map.get("reservation_conflict_contact_ids_by_match_status", %{})
    |> Enum.flat_map(fn {match_status, contact_ids} ->
      reservation_ids = Map.get(reservation_ids_by_match_status, match_status, [])

      contact_ids
      |> List.wrap()
      |> Enum.with_index()
      |> Enum.map(fn {contact_id, index} ->
        reservation_id = Enum.at(reservation_ids, index) || List.first(reservation_ids)

        %{
          "type" => "downlink_completion_gap",
          "severity" => "medium",
          "reason" =>
            "candidate source contact allocation replay reports station reservation conflict for contact #{contact_id}",
          "contact_id" => contact_id,
          "source_activity_id" => contact_id,
          "source_activity_ids" => List.wrap(contact_id),
          "station_reservation_id" => reservation_id,
          "station_reservation_match_status" => match_status,
          "feedback_source" => "candidate_source.contact_allocation_replay_summary",
          "feedback_scope" => "contact_allocation",
          "derivation_reasons" => ["contact_allocation_reservation_conflict"]
        }
        |> compact_map()
      end)
    end)
  end

  defp contact_allocation_replay_provider_reservation_risks(replay_summary) do
    replay_summary
    |> Map.get("provider_reservation_review_contact_ids_by_match_status", %{})
    |> Enum.flat_map(fn {match_status, contact_ids} ->
      contact_ids
      |> List.wrap()
      |> Enum.map(fn contact_id ->
        %{
          "type" => "provider_reservation_request_review",
          "severity" => "high",
          "reason" =>
            "candidate source contact allocation replay reports provider reservation review for contact #{contact_id}",
          "contact_id" => contact_id,
          "source_activity_id" => contact_id,
          "source_activity_ids" => List.wrap(contact_id),
          "station_reservation_match_status" => match_status,
          "provider_reservation_request_status" => "review_required",
          "provider_reservation_row_scope" => "review",
          "feedback_source" => "candidate_source.contact_allocation_replay_summary",
          "feedback_scope" => "contact_allocation_provider_reservation_request"
        }
        |> compact_map()
      end)
    end)
  end

  defp operational_readiness_replay_pressure_risks(%{} = replay_summary) do
    if operational_readiness_replay_scoring_pressure?(replay_summary) do
      operational_readiness_replay_pressure_risk(replay_summary)
    else
      []
    end
  end

  defp operational_readiness_replay_pressure_risks(_replay_summary), do: []

  defp operational_readiness_replay_scoring_pressure?(replay_summary) do
    Map.get(replay_summary, "branch_local_review_pressure") == true or
      Map.get(replay_summary, "branch_local_import_pressure") == true or
      Map.get(replay_summary, "branch_local_execution_boundary_pressure") == true or
      summary_positive?(replay_summary, "review_gate_count") or
      summary_positive?(replay_summary, "blocked_gate_count") or
      summary_positive?(replay_summary, "non_passed_gate_count")
  end

  defp operational_readiness_replay_pressure_risk(replay_summary) do
    readiness_levels = replay_summary |> Map.get("readiness_level_counts", %{}) |> map_keys()

    import_classifications =
      replay_summary |> Map.get("import_classification_counts", %{}) |> map_keys()

    readiness_statuses = replay_summary |> Map.get("status_counts", %{}) |> map_keys()

    gate_statuses = replay_summary |> Map.get("gate_status_counts", %{}) |> map_keys()

    gate_classifications =
      replay_summary |> Map.get("gate_classification_counts", %{}) |> map_keys()

    [
      %{
        "type" => "operational_readiness_pressure",
        "severity" =>
          readiness_pressure_risk_severity(%{
            "readiness_level" => pressure_priority_value(readiness_levels),
            "import_classification" => pressure_priority_value(import_classifications),
            "operational_readiness_status" => pressure_priority_value(readiness_statuses)
          }),
        "reason" =>
          "candidate source operational-readiness replay reports review, blocked, analysis-only, or import-boundary pressure",
        "readiness_level" => pressure_priority_value(readiness_levels),
        "import_classification" => pressure_priority_value(import_classifications),
        "operational_readiness_status" => pressure_priority_value(readiness_statuses),
        "readiness_levels" => readiness_levels,
        "import_classifications" => import_classifications,
        "operational_readiness_statuses" => readiness_statuses,
        "source_report_paths" => Map.get(replay_summary, "source_report_paths"),
        "gate_count" => Map.get(replay_summary, "gate_count"),
        "passed_gate_count" => Map.get(replay_summary, "passed_gate_count"),
        "review_gate_count" => Map.get(replay_summary, "review_gate_count"),
        "analysis_gate_count" => Map.get(replay_summary, "analysis_gate_count"),
        "blocked_gate_count" => Map.get(replay_summary, "blocked_gate_count"),
        "non_passed_gate_count" => Map.get(replay_summary, "non_passed_gate_count"),
        "gate_status_counts" => Map.get(replay_summary, "gate_status_counts"),
        "gate_classification_counts" => Map.get(replay_summary, "gate_classification_counts"),
        "gate_statuses" => gate_statuses,
        "gate_classifications" => gate_classifications,
        "review_required_gate_ids" => Map.get(replay_summary, "review_required_gate_ids"),
        "analysis_only_gate_ids" => Map.get(replay_summary, "analysis_only_gate_ids"),
        "blocked_gate_ids" => Map.get(replay_summary, "blocked_gate_ids"),
        "non_passed_gate_ids" => Map.get(replay_summary, "non_passed_gate_ids"),
        "branch_local_review_pressure" => Map.get(replay_summary, "branch_local_review_pressure"),
        "branch_local_import_pressure" => Map.get(replay_summary, "branch_local_import_pressure"),
        "branch_local_execution_boundary_pressure" =>
          Map.get(replay_summary, "branch_local_execution_boundary_pressure"),
        "feedback_source" => "candidate_source.operational_readiness_replay_summary",
        "feedback_scope" => "operational_readiness",
        "trust_boundaries" => Map.get(replay_summary, "trust_boundaries")
      }
      |> compact_map()
    ]
  end

  defp pressure_priority_value(values) do
    priority = [
      "blocked",
      "blocked_by_policy",
      "review_blocked_operational_readiness",
      "review_required",
      "review_only",
      "operator_review",
      "analysis_only"
    ]

    Enum.find(priority, &(&1 in values)) || List.first(values)
  end

  defp summary_positive?(summary, field) do
    case numeric_or_nil(Map.get(summary, field)) do
      value when is_number(value) -> value > 0
      _value -> false
    end
  end

  defp quality_gate_replay_pressure_risks(%{} = replay_summary) do
    if quality_gate_replay_scoring_pressure?(replay_summary) do
      quality_gate_replay_pressure_risk(replay_summary)
    else
      []
    end
  end

  defp quality_gate_replay_pressure_risks(_replay_summary), do: []

  defp quality_gate_replay_scoring_pressure?(replay_summary) do
    Map.get(replay_summary, "branch_local_review_pressure") == true or
      Map.get(replay_summary, "branch_local_import_pressure") == true or
      summary_positive?(replay_summary, "review_gate_count") or
      summary_positive?(replay_summary, "blocked_gate_count") or
      summary_positive?(replay_summary, "non_passed_gate_count")
  end

