    gate_classifications =
      replay_summary |> Map.get("gate_classification_counts", %{}) |> map_keys()

    [
      %{
        "type" => "quality_gate_pressure",
        "severity" =>
          readiness_pressure_risk_severity(%{
            "readiness_level" => pressure_priority_value(readiness_levels),
            "import_classification" => pressure_priority_value(import_classifications),
            "gate_status" => pressure_priority_value(gate_statuses),
            "gate_classification" => pressure_priority_value(gate_classifications)
          }),
        "reason" =>
          "candidate source quality-gate replay reports review, blocked, analysis-only, or import-boundary pressure",
        "readiness_level" => pressure_priority_value(readiness_levels),
        "import_classification" => pressure_priority_value(import_classifications),
        "quality_gate_status" => pressure_priority_value(gate_statuses),
        "gate_classification" => pressure_priority_value(gate_classifications),
        "readiness_levels" => readiness_levels,
        "import_classifications" => import_classifications,
        "quality_gate_statuses" => gate_statuses,
        "gate_classifications" => gate_classifications,
        "source_report_paths" => Map.get(replay_summary, "source_report_paths"),
        "gate_count" => Map.get(replay_summary, "gate_count"),
        "passed_gate_count" => Map.get(replay_summary, "passed_gate_count"),
        "review_gate_count" => Map.get(replay_summary, "review_gate_count"),
        "analysis_gate_count" => Map.get(replay_summary, "analysis_gate_count"),
        "blocked_gate_count" => Map.get(replay_summary, "blocked_gate_count"),
        "non_passed_gate_count" => Map.get(replay_summary, "non_passed_gate_count"),
        "gate_status_counts" => Map.get(replay_summary, "gate_status_counts"),
        "gate_classification_counts" => Map.get(replay_summary, "gate_classification_counts"),
        "review_required_gate_ids" => Map.get(replay_summary, "review_required_gate_ids"),
        "analysis_only_gate_ids" => Map.get(replay_summary, "analysis_only_gate_ids"),
        "blocked_gate_ids" => Map.get(replay_summary, "blocked_gate_ids"),
        "non_passed_gate_ids" => Map.get(replay_summary, "non_passed_gate_ids"),
        "review_required_quality_gate_row_ids" =>
          Map.get(replay_summary, "review_required_quality_gate_row_ids"),
        "analysis_only_quality_gate_row_ids" =>
          Map.get(replay_summary, "analysis_only_quality_gate_row_ids"),
        "blocked_quality_gate_row_ids" => Map.get(replay_summary, "blocked_quality_gate_row_ids"),
        "non_passed_quality_gate_row_ids" =>
          Map.get(replay_summary, "non_passed_quality_gate_row_ids"),
        "branch_local_review_pressure" => Map.get(replay_summary, "branch_local_review_pressure"),
        "branch_local_import_pressure" => Map.get(replay_summary, "branch_local_import_pressure"),
        "feedback_source" => "candidate_source.quality_gate_replay_summary",
        "feedback_scope" => "quality_gate",
        "trust_boundaries" => Map.get(replay_summary, "trust_boundaries")
      }
      |> compact_map()
    ]
  end

  defp timeline_lifecycle_replay_review_risks(
         %{"branch_local_lifecycle_review_pressure" => true} = replay_summary
       ) do
    [
      %{
        "type" => "timeline_lifecycle_state_review",
        "severity" => "high",
        "reason" =>
          "candidate source timeline lifecycle replay reports review, duplicate identity, or invalid activity pressure",
        "review_required_count" => Map.get(replay_summary, "review_required_count"),
        "duplicate_timeline_identity_count" =>
          Map.get(replay_summary, "duplicate_timeline_identity_count"),
        "invalid_activity_input_count" => Map.get(replay_summary, "invalid_activity_input_count"),
        "review_timeline_ids" => Map.get(replay_summary, "review_timeline_ids"),
        "review_activity_ids" => Map.get(replay_summary, "review_activity_ids"),
        "invalid_activity_input_ids" => Map.get(replay_summary, "invalid_activity_input_ids"),
        "required_operator_action_counts" =>
          Map.get(replay_summary, "required_operator_action_counts"),
        "import_action_counts" => Map.get(replay_summary, "import_action_counts"),
        "feedback_source" => "candidate_source.timeline_lifecycle_state_replay_summary",
        "feedback_scope" => "timeline_lifecycle_state",
        "trust_boundaries" => Map.get(replay_summary, "trust_boundaries")
      }
      |> compact_map()
    ]
  end

  defp timeline_lifecycle_replay_review_risks(_replay_summary), do: []

  defp timeline_activity_state_replay_review_risks(%{} = replay_summary) do
    if timeline_activity_state_replay_scoring_pressure?(replay_summary) do
      timeline_activity_state_replay_review_risk(replay_summary)
    else
      []
    end
  end

  defp timeline_activity_state_replay_review_risks(_replay_summary), do: []

  defp timeline_activity_state_replay_scoring_pressure?(replay_summary) do
    Map.get(replay_summary, "branch_local_activity_state_review_pressure") == true or
      Map.get(replay_summary, "branch_local_activity_state_action_pressure") == true or
      map_size(Map.get(replay_summary, "transition_decision_counts", %{})) > 0 or
      map_size(Map.get(replay_summary, "required_operator_action_counts", %{})) > 0 or
      map_size(Map.get(replay_summary, "import_action_counts", %{})) > 0
  end

  defp timeline_activity_state_replay_review_risk(replay_summary) do
    activity_ids =
      replay_summary
      |> Map.get("activity_id_counts", %{})
      |> map_keys()

    timeline_ids =
      replay_summary
      |> Map.get("timeline_id_counts", %{})
      |> map_keys()

    required_operator_actions =
      replay_summary
      |> Map.get("required_operator_action_counts", %{})
      |> map_keys()

    import_actions =
      replay_summary
      |> Map.get("import_action_counts", %{})
      |> map_keys()

    transition_decisions =
      replay_summary
      |> Map.get("transition_decision_counts", %{})
      |> map_keys()

    [
      %{
        "type" => "timeline_activity_lifecycle_state_review",
        "severity" => "high",
        "reason" =>
          "candidate source timeline activity-state replay reports review, action, routing, or state-transition pressure",
        "source_report_row_count" => Map.get(replay_summary, "source_report_row_count"),
        "review_required_count" => Map.get(replay_summary, "review_required_count"),
        "state_status_counts" => Map.get(replay_summary, "state_status_counts"),
        "transition_decision_counts" => Map.get(replay_summary, "transition_decision_counts"),
        "transition_decisions" => transition_decisions,
        "required_operator_action_counts" =>
          Map.get(replay_summary, "required_operator_action_counts"),
        "required_operator_actions" => required_operator_actions,
        "import_action_counts" => Map.get(replay_summary, "import_action_counts"),
        "import_actions" => import_actions,
        "activity_ids" => activity_ids,
        "timeline_ids" => timeline_ids,
        "review_activity_ids" =>
          replay_summary
          |> Map.get("review_activity_id_counts", %{})
          |> map_keys(),
        "action_routing_activity_ids" =>
          timeline_activity_state_replay_action_routing_values(replay_summary, "activity_ids"),
        "action_routing_timeline_ids" =>
          timeline_activity_state_replay_action_routing_values(replay_summary, "timeline_ids"),
        "status_transition_categories" =>
          timeline_activity_state_replay_action_routing_values(
            replay_summary,
            "status_transition_categories"
          ),
        "approval_transition_categories" =>
          timeline_activity_state_replay_action_routing_values(
            replay_summary,
            "approval_transition_categories"
          ),
        "feedback_source" => "candidate_source.timeline_activity_state_replay_summary",
        "feedback_scope" => "timeline_activity_state",
        "trust_boundaries" => Map.get(replay_summary, "trust_boundaries")
      }
      |> compact_map()
    ]
  end

  defp timeline_activity_state_replay_action_routing_values(replay_summary, field) do
    replay_summary
    |> Map.get("action_routing", %{})
    |> Map.values()
    |> Enum.flat_map(fn
      %{} = route -> List.wrap(Map.get(route, field))
      _route -> []
    end)
    |> sorted_encoded_values()
  end

  defp map_keys(%{} = map), do: map |> Map.keys() |> sorted_encoded_values()
  defp map_keys(_map), do: []

  defp sorted_encoded_values(values) do
    values
    |> List.wrap()
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp timeline_publication_replay_pressure_risks(
         %{"branch_local_timeline_publication_pressure" => true} = replay_summary
       ) do
