  defp relay_data_path_pressure_severity(event) do
    if event["risk_status"] in ["high", "critical"] or
         event["custody_status"] in ["missing_ack", "missing", "failed"] or
         event["latency_status"] in ["exceeds_limit", "late"] do
      "high"
    else
      "medium"
    end
  end

  defp relay_data_path_pressure_reason(event) do
    [
      if(event["route_id"] not in [nil, ""], do: "relay route #{event["route_id"]}"),
      if(event["ground_station_id"] not in [nil, ""],
        do: "ground station #{event["ground_station_id"]}"
      ),
      if(event["custody_status"] not in [nil, ""], do: "custody #{event["custody_status"]}"),
      if(event["latency_status"] not in [nil, ""], do: "latency #{event["latency_status"]}"),
      if(event["risk_status"] not in [nil, ""], do: "risk #{event["risk_status"]}")
    ]
    |> Enum.reject(&is_nil/1)
    |> case do
      [] -> "relay data path pressure"
      parts -> Enum.join(parts, "; ")
    end
  end

  defp readiness_pressure_risk_severity(event) do
    blocked_values = ["blocked", "blocked_by_policy", "review_blocked_operational_readiness"]

    if Enum.any?(
         [
           event["readiness_level"],
           event["import_classification"],
           event["operational_readiness_status"],
           event["readiness_gate_status"],
           event["readiness_gate_classification"],
           event["quality_gate_status"],
           event["gate_status"],
           event["gate_classification"],
           event["required_operator_action"]
         ],
         &(&1 in blocked_values)
       ) do
      "high"
    else
      "medium"
    end
  end

  defp validation_refresh_pressure_risk_severity(event) do
    high_values = [
      "blocked",
      "fail",
      "error",
      "invalid",
      "review_blocked_validation_safety_case"
    ]

    if Enum.any?(
         [
           event["validation_status"],
           event["issue_severity"],
           event["model_acceptance_status"],
           event["model_status"],
           event["validation_safety_case_status"],
           event["evidence_status"],
           event["freshness_status"],
           event["state_quality_status"],
           event["refresh_budget_status"],
           event["candidate_limit_status"],
           event["required_operator_action"]
         ],
         &(&1 in high_values)
       ) do
      "high"
    else
      "medium"
    end
  end

