  defp degraded_spacecraft_activity_type_risks(event, spacecraft_id) do
    event
    |> Map.get("derivation_reasons", [])
    |> List.wrap()
    |> Enum.filter(&(&1 in projected_activity_type_constraint_reasons()))
    |> Enum.map(fn reason ->
      type = String.replace_prefix(reason, "projected_", "")

      %{
        "type" => type,
        "severity" => "high",
        "reason" =>
          "resource projection for #{spacecraft_id} constrains activity types #{Enum.join(Map.get(event, "incompatible_activity_types", []), ", ")}",
        "spacecraft_id" => spacecraft_id,
        "incompatible_activity_types" => event["incompatible_activity_types"],
        "source_activity_id" => event["source_activity_id"],
        "source_activity_ids" => event["source_activity_ids"],
        "feedback_source" => event["feedback_source"],
        "feedback_scope" => event["feedback_scope"],
        "trust_boundary" => event["trust_boundary"]
      }
      |> compact_map()
    end)
  end

  defp projected_activity_type_constraint_reasons do
    ~w(projected_activity_type_suppressed_by_resource_summary projected_activity_type_incompatible_with_resource_summary)
  end

  defp downlink_completion_gap_reason(event) do
    reason =
      [
        if(downlink_contact_gap?(event), do: downlink_contact_gap_reason(event)),
        if(downlink_volume_gap?(event), do: downlink_volume_gap_reason(event))
      ]
      |> Enum.reject(&is_nil/1)
      |> case do
        [] -> [downlink_contact_gap_reason(event)]
        reasons -> reasons
      end
      |> Enum.join("; ")

    if "storage_margin_low" in Map.get(event, "derivation_reasons", []) do
      "storage margin #{event["storage_margin"]} below threshold #{event["storage_margin_threshold"]}; " <>
        reason
    else
      reason
    end
  end

  defp downlink_contact_gap?(event) do
    is_number(event["required_contacts"]) and is_number(event["planned_contacts"]) and
      event["planned_contacts"] < event["required_contacts"]
  end

  defp downlink_volume_gap?(event) do
    is_number(event["required_downlink_mb"]) and is_number(event["planned_downlink_mb"]) and
      event["planned_downlink_mb"] < event["required_downlink_mb"]
  end

  defp downlink_volume_gap_reason(event) do
    "planned downlink volume #{event["planned_downlink_mb"]} MB below required #{event["required_downlink_mb"]} MB"
  end

  defp downlink_contact_gap_reason(event) do
    "planned downlinks #{event["planned_contacts"] || 0} below required #{event["required_contacts"] || 0}"
  end

  defp branch_approval_requirements(repair_result, candidate_plan) do
    repair_requirements = Map.get(repair_result, "approval_requirements", [])

    strategic_requirements =
      candidate_plan
      |> Map.get("strategic_additions", [])
      |> Enum.map(fn activity ->
        requirement =
          %{
            "schema_contract" => "approval_requirement.v1",
            "activity_id" => activity_id(activity),
            "activity_type" => activity["type"],
            "requirement_type" =>
              approval_requirement_type("approve_strategic_addition", activity),
            "action" => "approve_strategic_addition",
            "reason" => get_in(activity, ["repair", "reason"]) || "strategic_branch_change",
            "activity_context" => strategic_addition_activity_context(activity)
          }

        requirement
        |> maybe_put_candidate_diff(
          get_in(activity, ["repair", "candidate_diff"]) ||
            get_in(activity, ["feasibility", "candidate_diff"])
        )
      end)

    (repair_requirements ++ strategic_requirements)
    |> Enum.uniq()
    |> Enum.sort_by(&{&1["activity_id"], &1["action"]})
  end

