  defp approval_decision(
         approval_requirements,
         risk_indicators,
         branch,
         candidate_plan,
         %ApprovalPolicy{} = policy
       ) do
    Policy.decide(
      approval_requirements,
      risk_indicators,
      branch,
      candidate_plan,
      approval_policy_to_map(policy)
    )
  end

  defp repair_approval_decision(approval_requirements, %ApprovalPolicy{} = policy) do
    Policy.decide(
      approval_requirements,
      [],
      %{"id" => "repair", "events" => []},
      %{},
      approval_policy_to_map(policy)
    )
  end

  defp strategy_recommendation(branches, _approval_policy) do
    selectable = Enum.reject(branches, &(&1.approval_status == "blocked_by_policy"))
    ranked = if selectable == [], do: branches, else: selectable
    recommended = List.first(ranked)
    baseline = Enum.find(branches, &(&1.id == "baseline")) || List.last(branches)
    tradeoffs = recommendation_tradeoffs(recommended, baseline)
    explanation = recommendation_explanation(recommended, baseline)

    reason =
      case recommended.approval_status do
        "auto_approvable" -> "best_expected_score_within_auto_approval_policy"
        "operator_review_required" -> "best_expected_score_requiring_operator_review"
        "blocked_by_policy" -> "all_branches_blocked_highest_score_reported_for_review"
      end

    %StrategyRecommendation{
      recommended_branch_id: recommended.id,
      approval_status: recommended.approval_status,
      reason: reason,
      ranked_branch_ids: Enum.map(ranked, & &1.id),
      tradeoffs: tradeoffs,
      explanation: explanation,
      risks_remaining: recommended.risk_indicators,
      requires_approval: recommended.approval_requirements
    }
  end

  defp recommendation_tradeoffs(recommended, baseline) do
    [
      %{
        "dimension" => "expected_score",
        "baseline" => baseline.score,
        "recommended" => recommended.score,
        "delta" => recommended.score - baseline.score
      },
      %{
        "dimension" => "mission_value",
        "baseline" => baseline.score_terms["mission_value_score"],
        "recommended" => recommended.score_terms["mission_value_score"],
        "delta" =>
          recommended.score_terms["mission_value_score"] -
            baseline.score_terms["mission_value_score"]
      }
    ] ++
      score_term_tradeoffs(recommended, baseline, [
        {"coverage", "coverage_score"},
        {"revisit", "revisit_score"},
        {"latency", "latency_penalty"},
        {"downlink_completion", "downlink_completion_score"},
        {"fuel_preservation", "fuel_preservation_score"},
        {"asset_balance", "asset_balance_score"},
        {"resource_score", "resource_score"},
        {"feedback_adjustment", "feedback_adjustment_score"},
        {"contact_allocation_pressure", "contact_allocation_pressure_penalty"},
        {"link_capacity_pressure", "link_capacity_pressure_penalty"},
        {"contact_intent_pressure", "contact_intent_pressure_penalty"},
        {"contact_contention_pressure", "contact_contention_pressure_penalty"},
        {"contact_filter_pressure", "contact_filter_pressure_penalty"},
        {"operational_readiness_pressure", "operational_readiness_pressure_penalty"},
        {"operator_training_pressure", "operator_training_pressure_penalty"},
        {"import_readiness_pressure", "import_readiness_pressure_penalty"},
        {"quality_gate_pressure", "quality_gate_pressure_penalty"},
        {"approval_boundary_pressure", "approval_boundary_pressure_penalty"},
        {"timeline_integrity_pressure", "timeline_integrity_pressure_penalty"},
        {"timeline_dependency_impact_pressure", "timeline_dependency_impact_pressure_penalty"},
        {"timeline_publication_pressure", "timeline_publication_pressure_penalty"},
        {"timeline_lifecycle_pressure", "timeline_lifecycle_pressure_penalty"},
        {"timeline_precondition_pressure", "timeline_precondition_pressure_penalty"},
        {"timeline_preservation_pressure", "timeline_preservation_pressure_penalty"},
        {"timeline_pressure", "timeline_pressure_penalty"},
        {"storage_downlink_pressure", "storage_downlink_pressure_penalty"},
        {"resource_availability_pressure", "resource_availability_pressure_penalty"},
        {"resource_margin_pressure", "resource_margin_pressure_penalty"},
        {"battery_depletion_pressure", "battery_depletion_pressure_penalty"},
        {"station_calendar_pressure", "station_calendar_pressure_penalty"},
        {"candidate_rejection_pressure", "candidate_rejection_pressure_penalty"},
        {"provider_counteroffer_pressure", "provider_counteroffer_pressure_penalty"},
        {"validation_refresh_pressure", "validation_refresh_pressure_penalty"},
        {"relay_data_path_pressure", "relay_data_path_pressure_penalty"},
        {"execution_feedback_pressure", "execution_feedback_pressure_penalty"}
      ]) ++
      [
        %{
          "dimension" => "risk_count",
          "baseline" => length(baseline.risk_indicators),
          "recommended" => length(recommended.risk_indicators),
          "delta" => length(recommended.risk_indicators) - length(baseline.risk_indicators)
        },
        %{
          "dimension" => "approval_count",
          "baseline" => length(baseline.approval_requirements),
          "recommended" => length(recommended.approval_requirements),
          "delta" =>
            length(recommended.approval_requirements) - length(baseline.approval_requirements)
        },
        %{
          "dimension" => "schedule_stability",
          "baseline" => baseline.score_terms["schedule_stability_penalty"],
          "recommended" => recommended.score_terms["schedule_stability_penalty"],
          "delta" =>
            recommended.score_terms["schedule_stability_penalty"] -
              baseline.score_terms["schedule_stability_penalty"]
        }
      ]
  end

  defp score_term_tradeoffs(recommended, baseline, dimensions) do
    Enum.map(dimensions, fn {dimension, score_key} ->
      baseline_score = numeric_score_term(baseline, score_key)
      recommended_score = numeric_score_term(recommended, score_key)

      %{
        "dimension" => dimension,
        "baseline" => baseline_score,
        "recommended" => recommended_score,
        "delta" => recommended_score - baseline_score
      }
    end)
  end

  defp numeric_score_term(branch, score_key) do
    case get_in(branch.score_terms, [score_key]) do
      value when is_number(value) -> value
      _value -> 0.0
    end
  end

  defp recommendation_explanation(recommended, baseline) do
    changed =
      recommended.repair_result
      |> Map.get("deltas", [])
      |> Enum.reject(&(&1["repair_action"] == "preserved"))
      |> Enum.map(fn delta ->
        %{
          "type" => "plan_delta",
          "activity_id" => delta["activity_id"],
          "activity_type" => delta["activity_type"],
          "action" => delta["repair_action"],
          "reason" => delta["reason"]
        }
      end)

    additions =
      recommended.candidate_plan
      |> Map.get("strategic_additions", [])
      |> Enum.map(fn activity ->
        %{
          "type" => "strategic_addition",
          "activity_id" => activity_id(activity),
          "target_id" => activity["target_id"],
          "reason" => get_in(activity, ["repair", "reason"]),
          "feasibility_status" => get_in(activity, ["feasibility", "status"]),
          "feedback_source" => get_in(activity, ["feasibility", "feedback_source"]),
          "feedback_scope" => get_in(activity, ["feasibility", "feedback_scope"]),
          "trust_boundary" => get_in(activity, ["feasibility", "trust_boundary"]),
          "source_event_type" => get_in(activity, ["feasibility", "source_event_type"]),
          "source_event_id" => get_in(activity, ["feasibility", "source_event_id"]),
          "objective_id" => get_in(activity, ["feasibility", "objective_id"]),
          "objective_ids" => get_in(activity, ["feasibility", "objective_ids"]),
          "objective_type" => get_in(activity, ["feasibility", "objective_type"]),
          "target_ids" => get_in(activity, ["feasibility", "target_ids"]),
          "collection_id" => get_in(activity, ["feasibility", "collection_id"]),
          "collection_ids" => get_in(activity, ["feasibility", "collection_ids"]),
          "product_id" => get_in(activity, ["feasibility", "product_id"]),
          "product_ids" => get_in(activity, ["feasibility", "product_ids"]),
          "payload_id" => get_in(activity, ["feasibility", "payload_id"]),
          "payload_ids" => get_in(activity, ["feasibility", "payload_ids"]),
          "instrument_id" => get_in(activity, ["feasibility", "instrument_id"]),
          "instrument_ids" => get_in(activity, ["feasibility", "instrument_ids"]),
          "requires_approval" => get_in(activity, ["repair", "requires_approval"]) || false
        }
        |> compact_map()
        |> maybe_put_candidate_diff(
          get_in(activity, ["repair", "candidate_diff"]) ||
            get_in(activity, ["feasibility", "candidate_diff"])
        )
      end)

    objective_rows = recommendation_objective_rows(recommended)

    risk_rows =
      Enum.map(recommended.risk_indicators, fn risk ->
        %{
          "type" => "risk_driver",
          "risk_type" => risk["type"],
          "severity" => risk["severity"],
          "reason" => risk["reason"],
          "value" => risk["value"],
          "activity_id" => risk["activity_id"],
          "ground_station_id" => risk["ground_station_id"],
          "scenario_id" => risk["scenario_id"],
          "spacecraft_id" => risk["spacecraft_id"],
          "target_id" => risk["target_id"],
          "collection_id" => risk["collection_id"],
          "collection_ids" => risk["collection_ids"],
          "product_id" => risk["product_id"],
          "product_ids" => risk["product_ids"],
          "payload_id" => risk["payload_id"],
          "payload_ids" => risk["payload_ids"],
          "instrument_id" => risk["instrument_id"],
          "instrument_ids" => risk["instrument_ids"],
          "objective_id" => risk["objective_id"],
          "objective_type" => risk["objective_type"],
          "objective_status" => risk["objective_status"],
          "source_objective_status" => risk["source_objective_status"],
          "latency_objective" => risk["latency_objective"],
          "max_latency_s" => risk["max_latency_s"],
          "planned_latency_s" => risk["planned_latency_s"],
          "required_contacts" => risk["required_contacts"],
          "planned_contacts" => risk["planned_contacts"],
          "required_downlink_mb" => risk["required_downlink_mb"],
          "planned_downlink_mb" => risk["planned_downlink_mb"],
          "contact_result" => risk["contact_result"],
          "realized_status" => risk["realized_status"],
          "source_activity_ids" => risk["source_activity_ids"],
          "timeline_id" => risk["timeline_id"],
          "maneuver_id" => risk["maneuver_id"],
          "execution_uncertainty_status" => risk["execution_uncertainty_status"],
          "execution_uncertainty_source" => risk["execution_uncertainty_source"],
          "execution_uncertainty" => risk["execution_uncertainty"],
          "timing_3sigma_s" => risk["timing_3sigma_s"],
          "timing_3sigma_threshold_s" => risk["timing_3sigma_threshold_s"],
          "delta_v_3sigma_km_s" => risk["delta_v_3sigma_km_s"],
          "delta_v_3sigma_magnitude_km_s" => risk["delta_v_3sigma_magnitude_km_s"],
          "delta_v_3sigma_magnitude_threshold_km_s" =>
            risk["delta_v_3sigma_magnitude_threshold_km_s"],
          "missing_dependency_activity_ids" => risk["missing_dependency_activity_ids"],
          "missing_dependency_timeline_ids" => risk["missing_dependency_timeline_ids"],
          "dependency_cycle_activity_ids" => risk["dependency_cycle_activity_ids"],
          "dependency_cycle_timeline_ids" => risk["dependency_cycle_timeline_ids"],
          "dependency_order_violation_activity_ids" =>
            risk["dependency_order_violation_activity_ids"],
          "dependency_order_violation_timeline_ids" =>
            risk["dependency_order_violation_timeline_ids"],
          "exclusivity_violation_activity_ids" => risk["exclusivity_violation_activity_ids"],
          "exclusivity_violation_timeline_ids" => risk["exclusivity_violation_timeline_ids"],
          "exclusivity_violation_group" => risk["exclusivity_violation_group"],
          "missed_downlink_activity_id" => risk["missed_downlink_activity_id"],
          "missed_downlink_activity_ids" => risk["missed_downlink_activity_ids"],
          "feedback_source" => risk["feedback_source"],
          "feedback_scope" => risk["feedback_scope"],
          "trust_boundary" => risk["trust_boundary"],
          "derivation_reasons" => risk["derivation_reasons"],
          "direction" => risk["direction"],
          "station_calendar_entry_id" => risk["station_calendar_entry_id"],
          "station_calendar_provider_id" => risk["station_calendar_provider_id"],
          "station_calendar_provider_entry_id" => risk["station_calendar_provider_entry_id"],
          "station_calendar_directions" => risk["station_calendar_directions"],
          "first_resource_pressure_activity_id" => risk["first_resource_pressure_activity_id"],
          "first_resource_pressure_activity_type" =>
            risk["first_resource_pressure_activity_type"],
          "first_resource_pressure_kind" => risk["first_resource_pressure_kind"],
          "first_resource_pressure_starts_at_s" => risk["first_resource_pressure_starts_at_s"],
          "first_resource_pressure_direction" => risk["first_resource_pressure_direction"],
          "first_resource_pressure_ground_station_id" =>
            risk["first_resource_pressure_ground_station_id"],
          "first_resource_pressure_station_calendar_entry_id" =>
            risk["first_resource_pressure_station_calendar_entry_id"],
          "first_resource_pressure_station_calendar_provider_id" =>
            risk["first_resource_pressure_station_calendar_provider_id"],
          "first_resource_pressure_station_calendar_provider_entry_id" =>
            risk["first_resource_pressure_station_calendar_provider_entry_id"],
          "first_resource_pressure_station_calendar_directions" =>
            risk["first_resource_pressure_station_calendar_directions"],
          "resource_pressure_status" => risk["resource_pressure_status"],
          "resource_pressure_types" => risk["resource_pressure_types"]
        }
        |> Map.merge(recommendation_pressure_risk_context(risk))
        |> compact_map()
      end)

    repair_link_rows = recommendation_repair_link_rows(recommended)
    resource_pressure_rows = recommendation_resource_pressure_rows(recommended)
    readiness_pressure_rows = recommendation_operational_readiness_pressure_rows(recommended)
    quality_gate_pressure_rows = recommendation_quality_gate_pressure_rows(recommended)
    feedback_rows = recommendation_feedback_rows(recommended)
    branch_event_rows = recommendation_branch_event_rows(recommended)

    approval_rows =
      Enum.map(recommended.approval_requirements, fn requirement ->
        %{
          "type" => "approval_driver",
          "activity_id" => requirement["activity_id"],
          "action" => requirement["action"],
          "classification" => requirement["policy_classification"] || recommended.approval_status,
          "reason" => requirement["reason"]
        }
      end)

    tradeoff_rows =
      [
        %{
          "type" => "branch_tradeoff",
          "summary" => branch_tradeoff_summary(recommended, baseline),
          "recommended_branch_id" => recommended.id,
          "baseline_branch_id" => baseline.id
        }
      ]

    changed ++
      additions ++
      objective_rows ++
      risk_rows ++
      repair_link_rows ++
      resource_pressure_rows ++
      readiness_pressure_rows ++
      quality_gate_pressure_rows ++
      feedback_rows ++
      branch_event_rows ++
      approval_rows ++
      tradeoff_rows
  end

  defp recommendation_branch_event_rows(%PlanBranch{} = recommended) do
    case branch_comparison_event_fields(recommended) do
      %{"branch_event_count" => 0} ->
        []

      %{} = event_fields ->
        [
          event_fields
          |> Map.put("type", "branch_event_summary")
          |> Map.put("recommended_branch_id", recommended.id)
          |> Map.put("reason", "recommended branch includes strategy branch events")
        ]
    end
  end

  defp recommendation_repair_link_rows(%PlanBranch{} = recommended) do
    link_capacity_report =
      recommended.repair_result
      |> Map.get("link_capacity_report", %{})
      |> stringify_keys()

    shortfall = Map.get(link_capacity_report, "selected_downlink_shortfall_mb")

    if positive_number?(shortfall) do
      required = Map.get(link_capacity_report, "required_downlink_mb")
      selected = Map.get(link_capacity_report, "selected_capacity_adjusted_throughput_mb")

      [
        %{
          "type" => "repair_link_capacity",
          "recommended_branch_id" => recommended.id,
          "required_downlink_mb" => required,
          "selected_capacity_adjusted_throughput_mb" => selected,
          "selected_downlink_shortfall_mb" => shortfall,
          "downlink_requirement_status" =>
            Map.get(link_capacity_report, "downlink_requirement_status"),
          "selected_contact_count" => Map.get(link_capacity_report, "selected_contact_count"),
          "selected_contact_ids" => Map.get(link_capacity_report, "selected_contact_ids"),
          "reason" =>
            "selected repaired downlink capacity #{selected} MB below required #{required} MB by #{shortfall} MB"
        }
        |> compact_map()
      ]
    else
      []
    end
  end

  defp recommendation_objective_rows(%PlanBranch{
         id: branch_id,
         objective_satisfaction: objective_satisfaction
       }) do
    objective_satisfaction = stringify_keys(objective_satisfaction || %{})

    priority_rows =
      objective_satisfaction
      |> Map.get("priority_commitments", %{})
      |> then(fn commitments ->
        [
          %{
            "type" => "objective_satisfaction",
            "objective" => "priority_commitments",
            "recommended_branch_id" => branch_id,
            "satisfied_target_ids" => Map.get(commitments, "satisfied_target_ids", []),
            "missed_target_ids" => Map.get(commitments, "missed_target_ids", [])
          }
          |> Map.merge(branch_comparison_priority_commitment_fields(objective_satisfaction))
          |> compact_map()
        ]
      end)

    downlink_completion_rows =
      case Map.get(objective_satisfaction, "downlink_completion") do
        %{} ->
          [
            %{
              "type" => "objective_satisfaction",
              "objective" => "downlink_completion",
              "recommended_branch_id" => branch_id
            }
            |> Map.merge(branch_comparison_downlink_completion_fields(objective_satisfaction))
            |> compact_map()
          ]

        _other ->
          []
      end

    coverage_rows =
      case Map.get(objective_satisfaction, "coverage") do
        %{} ->
          [
            %{
              "type" => "objective_satisfaction",
              "objective" => "coverage",
              "recommended_branch_id" => branch_id
            }
            |> Map.merge(branch_comparison_coverage_fields(objective_satisfaction))
            |> compact_map()
          ]

        _other ->
          []
      end

    revisit_rows =
      case Map.get(objective_satisfaction, "revisit") do
        %{} ->
          [
            %{
              "type" => "objective_satisfaction",
              "objective" => "revisit",
              "recommended_branch_id" => branch_id
            }
            |> Map.merge(branch_comparison_revisit_fields(objective_satisfaction))
            |> compact_map()
          ]

        _other ->
          []
      end

    collection_latency_rows =
      case Map.get(objective_satisfaction, "collection_latency") do
        %{} = collection_latency ->
          [
            %{
              "type" => "objective_satisfaction",
              "objective" => "collection_latency",
              "recommended_branch_id" => branch_id,
              "ratio" => Map.get(collection_latency, "ratio"),
              "observation_count" => Map.get(collection_latency, "observation_count"),
              "satisfied_observation_count" =>
                Map.get(collection_latency, "satisfied_observation_count"),
              "unsatisfied_observation_count" =>
                Map.get(collection_latency, "unsatisfied_observation_count")
            }
            |> Map.merge(branch_comparison_collection_latency_fields(objective_satisfaction))
            |> compact_map()
          ]

        _other ->
          []
      end

    priority_rows ++
      downlink_completion_rows ++
      coverage_rows ++
      revisit_rows ++
      collection_latency_rows
  end

  defp recommendation_resource_pressure_rows(%PlanBranch{
         id: branch_id,
         resource_projection_report: %{} = report
       }) do
    rows = Map.get(report, "projected_resources", [])
    pressure = first_resource_projection_pressure(rows)
    pressure_kind = resource_projection_pressure_kind(pressure)
    pressure_row = resource_projection_pressure_parent_row(rows, pressure)

    cond do
      pressure_kind ->
        [
          %{
            "type" => "resource_pressure",
            "recommended_branch_id" => branch_id,
            "spacecraft_id" => pressure_row["spacecraft_id"] || pressure_row["scenario_id"],
            "activity_id" => pressure["activity_id"],
            "activity_type" => pressure["activity_type"],
            "pressure_kind" => pressure_kind,
            "starts_at_s" => pressure["starts_at_s"],
            "storage_overflow_mb" => pressure["storage_overflow_mb"],
            "downlink_shortfall_mb" => pressure["downlink_shortfall_mb"],
            "battery_overuse_wh" => pressure["battery_overuse_wh"],
            "payload_available" => pressure_row["payload_available"],
            "antenna_available" => pressure_row["antenna_available"],
            "degraded" => pressure_row["degraded"],
            "resource_pressure_status" => pressure_row["resource_pressure_status"],
            "resource_pressure_types" => pressure_row["resource_pressure_types"],
            "peak_storage_overflow_mb" =>
              peak_resource_projection_flow_value(rows, "storage_overflow_mb"),
            "peak_downlink_shortfall_mb" =>
              peak_resource_projection_flow_value(rows, "downlink_shortfall_mb"),
            "peak_battery_overuse_wh" =>
              peak_resource_projection_flow_value(rows, "battery_overuse_wh"),
            "reason" =>
              "recommended branch resource projection shows #{pressure_kind} at #{pressure["activity_id"]}"
          }
          |> Map.merge(recommendation_resource_pressure_context(pressure, pressure_kind))
          |> compact_map()
        ]

      unavailable = first_resource_projection_spacecraft_unavailable(rows) ->
        [
          %{
            "type" => "resource_pressure",
            "recommended_branch_id" => branch_id,
            "spacecraft_id" => unavailable["spacecraft_id"],
            "pressure_kind" => "spacecraft_unavailable",
            "resource_pressure_status" => unavailable["resource_pressure_status"],
            "resource_pressure_types" => unavailable["resource_pressure_types"],
            "payload_available" => unavailable["payload_available"],
            "antenna_available" => unavailable["antenna_available"],
            "degraded" => unavailable["degraded"],
            "reason" =>
              "recommended branch resource projection declares spacecraft unavailable for #{unavailable["spacecraft_id"]}"
          }
          |> compact_map()
        ]

      true ->
        []
    end
  end

  defp recommendation_resource_pressure_rows(_branch), do: []

  defp recommendation_operational_readiness_pressure_rows(%PlanBranch{
         id: branch_id,
         events: events
       }) do
    events
    |> Enum.filter(&(&1["type"] == "operational_readiness_pressure"))
    |> Enum.map(fn event ->
      event
      |> Map.take([
        "report_id",
        "source_artifact_type",
        "source_artifact_id",
        "readiness_level",
        "import_classification",
        "operational_readiness_status",
        "gate_count",
        "passed_gate_count",
        "review_gate_count",
