  defp feedback_adjustment_row?(adjustments) do
    Enum.any?(
      [
        "contact_success_factor",
        "observation_success_factor",
        "maneuver_success_factor",
        "command_success_factor",
        "station_throughput_factor"
      ],
      &is_number(Map.get(adjustments, &1))
    )
  end

  defp branch_tradeoff_summary(recommended, baseline) do
    score_delta = recommended.score - baseline.score
    risk_delta = length(recommended.risk_indicators) - length(baseline.risk_indicators)

    approval_delta =
      length(recommended.approval_requirements) - length(baseline.approval_requirements)

    cond do
      score_delta >= 0 and risk_delta <= 0 ->
        "recommended branch improves expected score without increasing risk count"

      score_delta < 0 and risk_delta < 0 ->
        "recommended branch accepts lower expected score to reduce risk"

      approval_delta < 0 ->
        "recommended branch reduces approval burden"

      true ->
        "recommended branch has the best selectable expected score under policy"
    end
  end

  defp normalize_strategy_prior_plan(prior_plan) do
    prior_plan = stringify_keys(prior_plan || %{})

    if v2_repair_artifact?(prior_plan) do
      source_candidates = prior_plan_source_candidate_activities(prior_plan)

      if source_candidates in [nil, []] do
        raise ArgumentError,
              "V3 strategy with a V2 repair artifact requires source_candidate_activities"
      end

      Map.put(prior_plan, "candidate_activities", source_candidates)
    else
      prior_plan
    end
  end

  defp prior_plan_source_candidate_activities(prior_plan) do
    prior_plan_candidate_activity_rows(prior_plan, [
      "source_candidate_activities",
      "candidate_activities"
    ])
  end

  defp prior_plan_candidate_activities(prior_plan) do
    prior_plan_candidate_activity_rows(prior_plan, [
      "candidate_activities",
      "source_candidate_activities"
    ])
  end

  defp prior_plan_candidate_activity_rows(prior_plan, fields) do
    prior_plan = stringify_keys(prior_plan || %{})

    case first_candidate_activity_rows(prior_plan, fields) do
      [] -> prior_plan_result_artifact_candidate_activity_rows(prior_plan, fields)
      rows -> normalize_candidate_activity_rows(rows)
    end
  end

  defp prior_plan_result_artifact_candidate_activity_rows(prior_plan, fields) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, _source_path} ->
      artifact
      |> first_candidate_activity_rows(fields)
      |> normalize_candidate_activity_rows()
      |> Enum.map(&put_inherited_result_artifact_trust_boundary(&1, artifact))
    end)
  end

  defp first_candidate_activity_rows(source, fields) do
    Enum.find_value(fields, [], fn field ->
      rows = candidate_activity_rows(Map.get(source, field))

      if rows == [] do
        nil
      else
        rows
      end
    end)
  end

  defp candidate_activity_rows(rows) when is_list(rows), do: rows
  defp candidate_activity_rows(_rows), do: []

  defp normalize_candidate_activity_rows(rows) do
    Enum.map(rows, &stringify_keys/1)
  end

  defp v2_repair_artifact?(prior_plan) do
    Map.get(prior_plan, "schema_version") == 2 or
      Map.get(prior_plan, "planner") == "OrbitalDynamics.CampaignPlanner.V2"
  end

