  defp prior_plan_station_calendar_reports(prior_plan) do
    direct_reports =
      [
        {"source_station_calendar_report", "prior_plan.source_station_calendar_report"},
        {"station_calendar_report", "prior_plan.station_calendar_report"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        case Map.get(prior_plan, field) do
          %{} = report -> [{stringify_keys(report), source_path}]
          _report -> []
        end
      end)

    direct_reports ++ prior_plan_result_artifact_station_calendar_reports(prior_plan)
  end

  defp prior_plan_result_artifact_station_calendar_reports(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      ["source_station_calendar_report", "station_calendar_report"]
      |> Enum.flat_map(fn report_key ->
        case Map.get(artifact, report_key) do
          %{} = report ->
            report =
              report
              |> stringify_keys()
              |> put_inherited_result_artifact_trust_boundary(artifact)

            [{report, "#{source_path}.#{report_key}"}]

          _report ->
            []
        end
      end)
    end)
  end

  defp station_calendar_pressure_branch(row, source_path) do
    event = station_calendar_pressure_event(row, source_path)
    station_id = event && event_ground_station_id(event)

    if is_nil(event) or station_id in [nil, ""] do
      []
    else
      station_availability =
        Map.get(event, "station_availability") || Map.get(event, "availability")

      contact_id =
        Map.get(row, "contact_id") || Map.get(row, "activity_id") ||
          Map.get(row, "id") || station_id

      [
        %{
          "id" =>
            "derived_station_calendar_pressure_#{branch_id_fragment(station_availability || event["type"])}_#{branch_id_fragment(contact_id)}",
          "label" => "Derived station-calendar pressure #{contact_id}",
          "events" => [event],
          "metadata" =>
            %{
              "derived_source" => source_path,
              "station_calendar_entry_id" => row["station_calendar_entry_id"],
              "station_calendar_availability" => station_availability,
              "station_calendar_trust_boundary_status" =>
                row["station_calendar_trust_boundary_status"]
            }
            |> compact_map()
        }
      ]
    end
  end

  defp station_calendar_provider_contention_pressure_branch(group, source_path) do
    events = station_calendar_provider_contention_pressure_events(group, source_path)

    station_id =
      group["ground_station_id"] || Enum.find_value(events, &event_ground_station_id/1)

    if events == [] or station_id in [nil, ""] do
      []
    else
      [
        %{
          "id" =>
            "derived_station_calendar_provider_contention_#{branch_id_fragment(group["id"] || station_id)}",
          "label" => "Derived station-calendar provider contention #{group["id"] || station_id}",
          "events" => events,
          "metadata" =>
            %{
              "derived_source" => source_path,
              "provider_calendar_contention_group_id" => group["id"],
              "provider_calendar_contention_entry_ids" => group["entry_ids"],
              "provider_calendar_contention_status" =>
                group["provider_calendar_contention_status"],
              "station_calendar_trust_boundary_statuses" => group["trust_boundary_statuses"]
            }
            |> compact_map()
        }
      ]
    end
  end

  defp station_calendar_provider_contention_pressure_events(group, source_path) do
    group
    |> Map.get("source_station_calendar_entries", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(&station_calendar_provider_contention_pressure_row(group, &1))
    |> Enum.map(&station_calendar_pressure_event(&1, source_path))
    |> Enum.reject(&is_nil/1)
  end

  defp station_calendar_provider_contention_pressure_row(group, entry) do
    entry_id = entry["id"] || entry["station_calendar_entry_id"]

    %{
      "ground_station_id" =>
        group["ground_station_id"] || station_calendar_pressure_station_id(entry),
      "starts_at_s" => group["starts_at_s"] || entry["starts_at_s"],
      "ends_at_s" => group["ends_at_s"] || entry["ends_at_s"],
      "station_calendar_entry_id" => entry_id,
      "station_calendar_provider_id" =>
        entry["provider_id"] || entry["station_calendar_provider_id"] ||
          first_string(group["provider_ids"]),
      "station_calendar_provider_entry_id" =>
        entry["provider_entry_id"] || entry["station_calendar_provider_entry_id"] || entry_id,
      "station_calendar_directions" => entry["directions"] || group["directions"],
      "station_calendar_status" => entry["status"] || entry["availability"],
      "station_availability" => entry["availability"] || entry["status"],
      "capacity_fraction" => entry["capacity_fraction"],
      "station_reservation_id" => entry["reservation_id"],
      "station_reserved_by" => entry["reserved_by"],
      "station_reservation_status" => entry["reservation_status"],
      "station_calendar_trust_boundary_status" =>
        station_calendar_provider_contention_trust_boundary_status(group, entry),
      "trust_boundary" =>
        station_calendar_pressure_trust_boundary(entry) || group["trust_boundary"] ||
          group["_source_report_trust_boundary"],
      "source_station_calendar_entry" => entry,
      "source_station_calendar_provider_contention" => group,
      "provider_calendar_contention_group_id" => group["id"],
      "provider_calendar_contention_status" => group["provider_calendar_contention_status"],
      "provider_calendar_contention_entry_ids" => group["entry_ids"],
      "provider_calendar_contention_provider_ids" => group["provider_ids"],
      "provider_calendar_contention_provider_entry_ids" => group["provider_entry_ids"],
      "provider_calendar_contention_availabilities" => group["availabilities"],
      "provider_calendar_contention_directions" => group["directions"],
      "provider_calendar_contention_reservation_ids" => group["reservation_ids"],
      "provider_calendar_contention_reserved_by" => group["reserved_by"],
      "provider_calendar_contention_reservation_statuses" => group["reservation_statuses"],
      "provider_calendar_contention_trust_boundary_statuses" => group["trust_boundary_statuses"],
      "provider_calendar_contention_overlap_pairs" => group["overlap_pairs"]
    }
    |> compact_map()
  end

  defp station_calendar_provider_contention_trust_boundary_status(group, entry) do
    if station_calendar_pressure_trust_boundary(entry) in [nil, ""] do
      single_string(group["trust_boundary_statuses"])
    else
      "declared"
    end
  end

  defp first_string(values) do
    values
    |> List.wrap()
    |> List.flatten()
    |> Enum.find(&(is_binary(&1) and &1 != ""))
  end

  defp first_numeric(values) do
    values
    |> List.wrap()
    |> List.flatten()
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
  end

  defp single_string(values) do
    case values |> List.wrap() |> Enum.filter(&(is_binary(&1) and &1 != "")) |> Enum.uniq() do
      [value] -> value
      _values -> nil
    end
  end

  defp station_calendar_pressure_event(row, source_path) do
    row
    |> station_calendar_pressure_event_type()
    |> case do
      nil ->
        nil

      type ->
        row
        |> Map.take([
          "scenario_id",
          "station_calendar_entry_id",
          "station_calendar_provider_id",
          "station_calendar_provider_entry_id",
          "station_calendar_directions",
          "station_calendar_status",
          "station_calendar_overlap_count",
          "station_calendar_overlap_entry_ids",
          "station_calendar_overlap_availabilities",
          "station_calendar_entry_ambiguous",
          "station_calendar_ambiguous_entry_count",
          "station_calendar_ambiguous_entry_ids",
          "station_calendar_reservation_overlap_count",
          "station_calendar_reservation_ids",
          "station_calendar_reserved_by",
          "station_calendar_reservation_statuses",
          "station_calendar_trust_boundary_status",
          "station_contention_status",
          "station_reservation_match_status",
          "station_reservation_id",
          "station_reserved_by",
          "station_reservation_status",
          "station_reservation_expires_at_s",
          "station_reservation_expiration_status",
          "required_operator_action",
          "trust_boundary",
          "source_station_reservation_review",
          "source_station_calendar_entry",
          "source_station_calendar_overlaps",
          "source_station_calendar_provider_contention",
          "provider_calendar_contention_group_id",
          "provider_calendar_contention_status",
          "provider_calendar_contention_entry_ids",
          "provider_calendar_contention_provider_ids",
          "provider_calendar_contention_provider_entry_ids",
          "provider_calendar_contention_availabilities",
          "provider_calendar_contention_directions",
          "provider_calendar_contention_reservation_ids",
          "provider_calendar_contention_reserved_by",
          "provider_calendar_contention_reservation_statuses",
          "provider_calendar_contention_trust_boundary_statuses",
          "provider_calendar_contention_overlap_pairs"
        ])
        |> Map.merge(%{
          "type" => type,
          "ground_station_id" => station_calendar_pressure_station_id(row),
          "starts_at_s" =>
            activity_raw_start(row) ||
              numeric_or_nil(row["overlap_starts_at_s"]) ||
              numeric_or_nil(get_in(row, ["source_station_calendar_entry", "starts_at_s"])),
          "ends_at_s" =>
            activity_raw_end(row) ||
              numeric_or_nil(row["overlap_ends_at_s"]) ||
              numeric_or_nil(get_in(row, ["source_station_calendar_entry", "ends_at_s"])),
          "capacity_fraction" => station_calendar_pressure_capacity_fraction(row),
          "reservation_id" => row["station_reservation_id"],
          "reserved_by" => row["station_reserved_by"],
          "reservation_status" => row["station_reservation_status"],
          "station_reservation_expires_at_s" => row["station_reservation_expires_at_s"],
          "station_reservation_expiration_status" => row["station_reservation_expiration_status"],
          "required_operator_action" => row["required_operator_action"],
          "station_calendar_status" =>
            normalized_station_availability_token(
              Map.get(row, "station_calendar_status") || Map.get(row, "status")
            ),
          "station_availability" => station_calendar_pressure_availability(row),
          "feedback_source" => source_path,
          "feedback_scope" => "station_calendar",
          "derivation_reasons" => station_calendar_pressure_reasons(row, type),
          "trust_boundary" => station_calendar_pressure_trust_boundary(row)
        })
        |> compact_map()
    end
  end

  defp station_calendar_pressure_event_type(row) do
    availability = station_calendar_pressure_availability(row)

    status =
      normalized_station_availability_token(
        Map.get(row, "station_calendar_status") || Map.get(row, "status")
      )

    capacity_fraction = station_calendar_pressure_capacity_fraction(row)

    cond do
      Map.get(row, "station_contention_status") == "reserved_overlap" or
          availability == "reserved" ->
        "ground_station_reserved"

      availability in @unavailable_station_tokens or status in @unavailable_station_tokens ->
        "ground_station_outage"

      availability == "reduced_capacity" or
          (is_number(capacity_fraction) and capacity_fraction < 1.0) ->
        "reduced_downlink_capacity"

      true ->
        nil
    end
  end

  defp station_calendar_pressure_availability(row) do
    [
      Map.get(row, "station_availability"),
      Map.get(row, "availability"),
      get_in(row, ["source_station_calendar_entry", "availability"])
    ]
    |> Enum.map(&normalized_station_availability_token/1)
    |> Enum.find(&(&1 not in [nil, ""]))
  end

  defp station_calendar_pressure_station_id(row) do
    Map.get(row, "ground_station_id") ||
      Map.get(row, "station_id") ||
      get_in(row, ["source_station_calendar_entry", "ground_station_id"]) ||
      get_in(row, ["source_station_calendar_entry", "station_id"])
  end

  defp station_calendar_pressure_capacity_fraction(row) do
    numeric_or_nil(Map.get(row, "capacity_fraction")) ||
      numeric_or_nil(Map.get(row, "station_availability")) ||
      numeric_or_nil(Map.get(row, "availability")) ||
      numeric_or_nil(get_in(row, ["source_station_calendar_entry", "capacity_fraction"]))
  end

  defp normalized_station_availability_token(value) when is_number(value) do
    if value < 1.0, do: "reduced_capacity", else: "available"
  end

  defp normalized_station_availability_token(value) do
    case encode_value(value) do
      value when is_binary(value) ->
        value
        |> String.trim()
        |> String.downcase()
        |> String.replace(~r/[\s-]+/, "_")
        |> canonical_station_availability_token()

      value ->
        value
    end
  end

  defp canonical_station_availability_token(value) when value in ["outage", "offline", "down"],
    do: "unavailable"

  defp canonical_station_availability_token(value), do: value

  defp station_calendar_pressure_trust_boundary(row) do
    row["trust_boundary"] ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      get_in(row, ["source_station_calendar_entry", "trust_boundary"]) ||
      get_in(row, ["source_station_calendar_entry", "provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp station_calendar_pressure_reasons(row, type) do
    [
      "station_calendar_#{station_calendar_pressure_availability(row) || type}",
      row["station_contention_status"],
      row["provider_calendar_contention_status"],
      row["station_reservation_expiration_status"],
      row["required_operator_action"],
      if(row["station_calendar_entry_ambiguous"], do: "ambiguous_station_calendar_entry")
    ]
    |> Enum.map(&encode_value/1)
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
  end

  defp derived_operational_feedback_branches(
         mission_state,
         prior_plan,
         operational_feedback,
         operational_feedback_provenance,
         policy
       ) do
    horizon_end_s = get_in(prior_plan, ["planning_horizon", "duration_s"]) || 0.0
    station_ids = planning_ground_station_ids(mission_state, prior_plan)
    target_ids = planning_target_ids(mission_state, prior_plan)
    target_priorities = planning_target_priorities(mission_state, prior_plan)
    maneuver_activities = planning_maneuver_activities(prior_plan)
    command_activities = planning_command_activities(prior_plan)
    trust_boundary = operational_feedback_trust_boundary_context(operational_feedback_provenance)

    throughput_events =
      operational_feedback
      |> Map.get("station_throughput_factor", %{})
      |> low_station_throughput_feedback_events(
        station_ids,
        policy["station_throughput_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    contact_success_events =
      operational_feedback
      |> Map.get("contact_success_rate", %{})
      |> low_contact_success_feedback_events(
        station_ids,
        policy["contact_success_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    observation_success_events =
      operational_feedback
      |> Map.get("observation_success_rate", %{})
      |> low_observation_success_feedback_events(
        target_ids,
        target_priorities,
        policy["observation_success_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    observation_quality_events =
      operational_feedback
      |> Map.get("image_quality_score", %{})
      |> low_observation_quality_feedback_events(
        Map.get(operational_feedback, "image_quality_status", %{}),
        Map.get(operational_feedback, "image_quality_source", %{}),
        Map.get(operational_feedback, "cloud_cover_fraction", %{}),
        Map.get(operational_feedback, "blur_score", %{}),
        target_ids,
        target_priorities,
        policy["observation_success_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    maneuver_success_events =
      operational_feedback
      |> Map.get("maneuver_success_rate", %{})
      |> low_maneuver_success_feedback_events(
        maneuver_activities,
        policy["maneuver_success_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    maneuver_execution_uncertainty_events =
      operational_feedback
      |> Map.get("maneuver_execution_uncertainty", %{})
      |> maneuver_execution_uncertainty_feedback_events(
        maneuver_activities,
        policy,
        horizon_end_s,
        trust_boundary
      )

    command_success_events =
      operational_feedback
      |> Map.get("command_success_rate", %{})
      |> low_command_success_feedback_events(
        command_activities,
        policy["command_success_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    downlink_demand_events =
      operational_feedback
      |> Map.get("downlink_demand_mb", %{})
      |> downlink_demand_feedback_events(
        Map.get(operational_feedback, "downlink_demand_sources", %{}),
        station_ids,
        policy["downlink_demand_feedback_threshold_mb"],
        horizon_end_s,
        trust_boundary
      )

    target_priority_events =
      operational_feedback
      |> Map.get("target_priority_overrides", %{})
      |> high_target_priority_feedback_events(
        target_ids,
        policy["target_priority_feedback_threshold"],
        horizon_end_s,
        trust_boundary
      )

    resource_margin_events =
      operational_feedback
      |> Map.get("resource_margin_overrides", %{})
      |> low_resource_margin_feedback_events(policy, horizon_end_s, trust_boundary)

    resource_availability_events =
      operational_feedback
      |> Map.get("resource_availability_overrides", %{})
      |> resource_availability_feedback_events(horizon_end_s, trust_boundary)

    [
      feedback_branch(
        "derived_station_throughput_feedback",
        "Derived station throughput feedback",
        throughput_events,
        "operational_feedback.station_throughput_factor"
      ),
      feedback_branch(
        "derived_contact_success_feedback",
        "Derived contact success feedback",
        contact_success_events,
        "operational_feedback.contact_success_rate"
      ),
      feedback_branch(
        "derived_observation_success_feedback",
        "Derived observation success feedback",
        observation_success_events,
        "operational_feedback.observation_success_rate"
      ),
      feedback_branch(
        "derived_observation_quality_feedback",
        "Derived observation quality feedback",
        observation_quality_events,
        "operational_feedback.image_quality_score"
      ),
      feedback_branch(
        "derived_maneuver_success_feedback",
        "Derived maneuver success feedback",
        maneuver_success_events,
        "operational_feedback.maneuver_success_rate"
      ),
      feedback_branch(
        "derived_maneuver_execution_uncertainty_feedback",
        "Derived maneuver execution uncertainty feedback",
        maneuver_execution_uncertainty_events,
        "operational_feedback.maneuver_execution_uncertainty"
      ),
      feedback_branch(
        "derived_command_success_feedback",
        "Derived command success feedback",
        command_success_events,
        "operational_feedback.command_success_rate"
      ),
      feedback_branch(
        "derived_downlink_demand_feedback",
        "Derived downlink demand feedback",
        downlink_demand_events,
        "operational_feedback.downlink_demand_mb"
      ),
      feedback_branch(
        "derived_target_priority_feedback",
        "Derived target priority feedback",
        target_priority_events,
        "operational_feedback.target_priority_overrides"
      ),
      feedback_branch(
        "derived_resource_margin_feedback",
        "Derived resource margin feedback",
        resource_margin_events,
        "operational_feedback.resource_margin_overrides"
      ),
      feedback_branch(
        "derived_resource_availability_feedback",
        "Derived resource availability feedback",
        resource_availability_events,
        "operational_feedback.resource_availability_overrides"
      )
    ]
    |> Enum.reject(&is_nil/1)
  end

  defp feedback_branch(_id, _label, [], _derived_source), do: nil

  defp feedback_branch(id, label, events, derived_source) do
    %{
      "id" => id,
      "label" => label,
      "events" => events,
      "metadata" => %{"derived_source" => derived_source}
    }
  end

  defp low_station_throughput_feedback_events(
         factors,
         station_ids,
         threshold,
         horizon_end_s,
         trust_boundary
       )
       when is_map(factors) do
    low_station_feedback_events(
      factors,
      station_ids,
      threshold,
      horizon_end_s,
      trust_boundary,
      &station_throughput_feedback_event/5
    )
    |> Enum.sort_by(&{Map.get(&1, "ground_station_id", ""), &1["station_throughput_factor"]})
  end

  defp low_station_throughput_feedback_events(
         _factors,
         _station_ids,
         _threshold,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp low_contact_success_feedback_events(
         factors,
         station_ids,
         threshold,
         horizon_end_s,
         trust_boundary
       )
       when is_map(factors) do
    low_station_feedback_events(
      factors,
      station_ids,
      threshold,
      horizon_end_s,
      trust_boundary,
      &contact_success_feedback_event/5
    )
    |> Enum.sort_by(&{Map.get(&1, "ground_station_id", ""), &1["contact_success_factor"]})
  end

  defp low_contact_success_feedback_events(
         _factors,
         _station_ids,
         _threshold,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp low_observation_success_feedback_events(
         factors,
         target_ids,
         target_priorities,
         threshold,
         horizon_end_s,
         trust_boundary
       )
       when is_map(factors) do
    factors
    |> Enum.flat_map(fn
      {"default", factor} ->
        if low_feedback_factor?(factor, threshold) do
          Enum.map(target_ids, fn target_id ->
            observation_success_feedback_event(
              target_id,
              factor,
              "default",
              horizon_end_s,
              Map.get(target_priorities, target_id),
              trust_boundary
            )
          end)
        else
          []
        end

      {target_id, factor} ->
        if target_id in target_ids and low_feedback_factor?(factor, threshold) do
          [
            observation_success_feedback_event(
              target_id,
              factor,
              "target",
              horizon_end_s,
              Map.get(target_priorities, target_id),
              trust_boundary
            )
          ]
        else
          []
        end
    end)
    |> Enum.sort_by(&{&1["target_id"], &1["observation_success_factor"]})
  end

  defp low_observation_success_feedback_events(
         _factors,
         _target_ids,
         _target_priorities,
         _threshold,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp low_observation_quality_feedback_events(
         scores,
         statuses,
         sources,
         cloud_cover_fractions,
         blur_scores,
         target_ids,
         target_priorities,
         threshold,
         horizon_end_s,
         trust_boundary
       )
       when is_map(scores) do
    statuses = if is_map(statuses), do: statuses, else: %{}
    sources = if is_map(sources), do: sources, else: %{}
    cloud_cover_fractions = if is_map(cloud_cover_fractions), do: cloud_cover_fractions, else: %{}
    blur_scores = if is_map(blur_scores), do: blur_scores, else: %{}

    [scores, statuses, cloud_cover_fractions, blur_scores]
    |> feedback_event_keys()
    |> Enum.flat_map(fn
      "default" ->
        target_ids
        |> Enum.map(fn target_id ->
          observation_quality_feedback_event(
            target_id,
            "default",
            horizon_end_s,
            Map.get(target_priorities, target_id),
            trust_boundary,
            scores,
            statuses,
            sources,
            cloud_cover_fractions,
            blur_scores
          )
        end)
        |> Enum.filter(&low_feedback_factor?(&1["observation_success_factor"], threshold))

      target_id ->
        if target_id in target_ids do
          [
            observation_quality_feedback_event(
              target_id,
              "target",
              horizon_end_s,
              Map.get(target_priorities, target_id),
              trust_boundary,
              scores,
              statuses,
              sources,
              cloud_cover_fractions,
              blur_scores
            )
          ]
          |> Enum.filter(&low_feedback_factor?(&1["observation_success_factor"], threshold))
        else
          []
        end
    end)
    |> Enum.sort_by(&{&1["target_id"], &1["image_quality_score"]})
  end

  defp low_observation_quality_feedback_events(
         _scores,
         _statuses,
         _sources,
         _cloud_cover_fractions,
         _blur_scores,
         _target_ids,
         _target_priorities,
         _threshold,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp feedback_event_keys(maps) do
    maps
    |> Enum.flat_map(fn
      %{} = map -> Map.keys(map)
      _map -> []
    end)
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp low_maneuver_success_feedback_events(
         factors,
         maneuver_activities,
         threshold,
         horizon_end_s,
         trust_boundary
       )
       when is_map(factors) do
    factors
    |> Enum.flat_map(fn
      {"default", factor} ->
        if low_feedback_factor?(factor, threshold) do
          Enum.map(maneuver_activities, fn activity ->
            maneuver_success_feedback_event(
              activity,
              factor,
              "default",
              "default",
              horizon_end_s,
              trust_boundary
            )
          end)
        else
          []
        end

      {feedback_key, factor} ->
        if low_feedback_factor?(factor, threshold) do
          maneuver_activities
          |> Enum.filter(&(feedback_key in maneuver_feedback_keys(&1)))
          |> Enum.map(fn activity ->
            maneuver_success_feedback_event(
              activity,
              factor,
              maneuver_feedback_scope(activity, feedback_key),
              feedback_key,
              horizon_end_s,
              trust_boundary
            )
          end)
        else
          []
        end
    end)
    |> Enum.sort_by(&{&1["activity_id"], &1["feedback_key"], &1["maneuver_success_factor"]})
  end

  defp low_maneuver_success_feedback_events(
         _factors,
         _maneuver_activities,
         _threshold,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp maneuver_execution_uncertainty_feedback_events(
         feedback,
         maneuver_activities,
         policy,
         horizon_end_s,
         trust_boundary
       )
       when is_map(feedback) do
    feedback
    |> Enum.flat_map(fn
      {"default", %{} = uncertainty} ->
        if maneuver_execution_uncertainty_relevant?(uncertainty, policy) do
          Enum.map(maneuver_activities, fn activity ->
            maneuver_execution_uncertainty_feedback_event(
              activity,
              uncertainty,
              "default",
              "default",
              policy,
              horizon_end_s,
              trust_boundary
            )
          end)
        else
          []
        end

      {feedback_key, %{} = uncertainty} ->
        if maneuver_execution_uncertainty_relevant?(uncertainty, policy) do
          maneuver_activities
          |> Enum.filter(&(feedback_key in maneuver_feedback_keys(&1)))
          |> Enum.map(fn activity ->
            maneuver_execution_uncertainty_feedback_event(
              activity,
              uncertainty,
              maneuver_feedback_scope(activity, feedback_key),
              feedback_key,
              policy,
              horizon_end_s,
              trust_boundary
            )
          end)
        else
          []
        end

      {_feedback_key, _uncertainty} ->
        []
    end)
    |> Enum.sort_by(&{&1["activity_id"], &1["feedback_key"]})
  end

  defp maneuver_execution_uncertainty_feedback_events(
         _feedback,
         _maneuver_activities,
         _policy,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp maneuver_execution_uncertainty_relevant?(%{} = uncertainty, policy) do
    uncertainty["execution_uncertainty_status"] == "missing" or
      uncertainty_over_threshold?(
        uncertainty["timing_3sigma_s"],
        policy["maneuver_execution_timing_3sigma_threshold_s"]
      ) or
      uncertainty_over_threshold?(
        uncertainty["delta_v_3sigma_magnitude_km_s"],
        policy["maneuver_execution_delta_v_3sigma_threshold_km_s"]
      )
  end

  defp uncertainty_over_threshold?(value, threshold)
       when is_number(value) and is_number(threshold),
       do: value > threshold

  defp uncertainty_over_threshold?(_value, _threshold), do: false

  defp low_command_success_feedback_events(
         factors,
         command_activities,
         threshold,
         horizon_end_s,
         trust_boundary
       )
       when is_map(factors) do
    factors
    |> Enum.flat_map(fn
      {"default", factor} ->
        if low_feedback_factor?(factor, threshold) do
          Enum.map(command_activities, fn activity ->
            command_success_feedback_event(
              activity,
              factor,
              "default",
              "default",
              horizon_end_s,
              trust_boundary
            )
          end)
        else
          []
        end

      {feedback_key, factor} ->
        if low_feedback_factor?(factor, threshold) do
          command_activities
          |> Enum.filter(&(feedback_key in command_feedback_keys(&1)))
          |> Enum.map(fn activity ->
            command_success_feedback_event(
              activity,
              factor,
              command_feedback_scope(activity, feedback_key),
              feedback_key,
              horizon_end_s,
              trust_boundary
            )
          end)
        else
          []
        end
    end)
    |> Enum.sort_by(&{&1["activity_id"], &1["feedback_key"], &1["command_success_factor"]})
  end

  defp low_command_success_feedback_events(
         _factors,
         _command_activities,
         _threshold,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp downlink_demand_feedback_events(
         demands,
         demand_sources,
         station_ids,
         threshold_mb,
         horizon_end_s,
         trust_boundary
       )
       when is_map(demands) do
    demands
    |> Enum.flat_map(fn
      {"default", required_downlink_mb} ->
        if downlink_demand_relevant?(required_downlink_mb, threshold_mb) do
          [
            downlink_demand_feedback_event(
              nil,
              required_downlink_mb,
              "default",
              demand_sources_for(demand_sources, "default"),
              horizon_end_s,
              trust_boundary
            )
          ]
        else
          []
        end

      {station_id, required_downlink_mb} ->
        if station_id in station_ids and
             downlink_demand_relevant?(required_downlink_mb, threshold_mb) do
          [
            downlink_demand_feedback_event(
              station_id,
              required_downlink_mb,
              "station",
              demand_sources_for(demand_sources, station_id),
              horizon_end_s,
              trust_boundary
            )
          ]
        else
          []
        end
    end)
    |> Enum.sort_by(&{Map.get(&1, "ground_station_id", ""), &1["required_downlink_mb"]})
  end

  defp downlink_demand_feedback_events(
         _demands,
         _demand_sources,
         _station_ids,
         _threshold_mb,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp demand_sources_for(%{} = demand_sources, key) do
    encoded_key = encode_value(key)

    Map.get(demand_sources, encoded_key, Map.get(demand_sources, key, []))
  end

  defp demand_sources_for(_demand_sources, _key), do: []

  defp downlink_demand_source_list(sources) do
    sources
    |> List.wrap()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      source_list -> source_list
    end
  end

  defp high_target_priority_feedback_events(
         priorities,
         target_ids,
         threshold,
         horizon_end_s,
         trust_boundary
       )
       when is_map(priorities) do
    priorities
    |> Enum.flat_map(fn
      {"default", priority} ->
        if high_feedback_priority?(priority, threshold) do
          Enum.map(
            target_ids,
            &target_priority_feedback_event(
              &1,
              priority,
              "default",
              horizon_end_s,
              trust_boundary
            )
          )
        else
          []
        end

      {target_id, priority} ->
        if target_id in target_ids and high_feedback_priority?(priority, threshold) do
          [
            target_priority_feedback_event(
              target_id,
              priority,
              "target",
              horizon_end_s,
              trust_boundary
            )
          ]
        else
          []
        end
    end)
    |> Enum.sort_by(&{&1["target_id"], -&1["priority"]})
  end

  defp high_target_priority_feedback_events(
         _priorities,
         _target_ids,
         _threshold,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp low_resource_margin_feedback_events(overrides, policy, horizon_end_s, trust_boundary)
       when is_map(overrides) do
    overrides
    |> Enum.flat_map(fn {spacecraft_id, margins} ->
      margins
      |> stringify_keys()
      |> low_spacecraft_resource_margin_feedback_events(
        to_string(spacecraft_id),
        policy,
        horizon_end_s,
        trust_boundary
      )
    end)
    |> Enum.sort_by(&{&1["spacecraft_id"], &1["resource_field"]})
  end

  defp low_resource_margin_feedback_events(_overrides, _policy, _horizon_end_s, _trust_boundary),
    do: []

  defp resource_availability_feedback_events(overrides, horizon_end_s, trust_boundary)
       when is_map(overrides) do
    overrides
    |> Enum.flat_map(fn {spacecraft_id, availability} ->
      availability
      |> stringify_keys()
      |> spacecraft_resource_availability_feedback_events(
        to_string(spacecraft_id),
        horizon_end_s,
        trust_boundary
      )
    end)
    |> Enum.sort_by(&{&1["spacecraft_id"], &1["resource_field"]})
  end

  defp resource_availability_feedback_events(_overrides, _horizon_end_s, _trust_boundary),
    do: []

  defp spacecraft_resource_availability_feedback_events(
         availability,
         spacecraft_id,
         horizon_end_s,
         trust_boundary
       )
       when is_map(availability) and spacecraft_id not in ["", "nil"] do
    degraded_events =
      if spacecraft_degraded_availability_feedback?(availability) do
        [
          degraded_spacecraft_feedback_event(
            spacecraft_id,
            availability,
            horizon_end_s,
            trust_boundary
          )
        ]
      else
        []
      end

    resource_events =
      ["payload_available", "antenna_available"]
      |> Enum.flat_map(fn field ->
        case Map.get(availability, field) do
          false ->
            [
              resource_availability_feedback_event(
                spacecraft_id,
                field,
                availability_feedback_reason(field),
                horizon_end_s,
                trust_boundary
              )
            ]

          _value ->
            []
        end
      end)

    degraded_events ++ resource_events
  end

  defp spacecraft_resource_availability_feedback_events(
         _availability,
         _spacecraft_id,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp low_spacecraft_resource_margin_feedback_events(
         margins,
         spacecraft_id,
         policy,
         horizon_end_s,
         trust_boundary
       )
       when is_map(margins) and spacecraft_id not in ["", "nil"] do
    ["fuel_margin", "power_margin", "storage_margin", "downlink_margin", "thermal_margin_c"]
    |> Enum.flat_map(fn field ->
      value = Map.get(margins, field)
      threshold = resource_margin_feedback_threshold(policy, field)

      if is_number(value) and is_number(threshold) and value <= threshold do
        [
          resource_margin_feedback_event(
            spacecraft_id,
            field,
            value,
            threshold,
            horizon_end_s,
            trust_boundary
          )
        ]
      else
        []
      end
    end)
  end

  defp low_spacecraft_resource_margin_feedback_events(
         _margins,
         _spacecraft_id,
         _policy,
         _horizon_end_s,
         _trust_boundary
       ),
       do: []

  defp resource_margin_feedback_threshold(policy, "thermal_margin_c"),
    do: Map.get(policy, "thermal_margin_c_threshold")

  defp resource_margin_feedback_threshold(policy, field),
    do: Map.get(policy, "#{field}_threshold")

  defp low_station_feedback_events(
         factors,
         station_ids,
         threshold,
         horizon_end_s,
         trust_boundary,
         event_fun
       ) do
    Enum.flat_map(factors, fn
      {"default", factor} ->
        if low_feedback_factor?(factor, threshold) do
          [event_fun.(nil, factor, "default", horizon_end_s, trust_boundary)]
        else
          []
        end

      {station_id, factor} ->
        if station_id in station_ids and low_feedback_factor?(factor, threshold) do
          [event_fun.(station_id, factor, "station", horizon_end_s, trust_boundary)]
        else
          []
        end
    end)
  end

  defp low_feedback_factor?(factor, threshold) when is_number(factor) and is_number(threshold),
    do: factor < threshold

  defp low_feedback_factor?(_factor, _threshold), do: false

  defp high_feedback_priority?(priority, threshold)
       when is_number(priority) and is_number(threshold),
       do: priority >= threshold

  defp high_feedback_priority?(_priority, _threshold), do: false

  defp downlink_demand_relevant?(required_downlink_mb, threshold_mb)
       when is_number(required_downlink_mb) and is_number(threshold_mb),
       do: required_downlink_mb > threshold_mb

  defp downlink_demand_relevant?(required_downlink_mb, _threshold_mb)
       when is_number(required_downlink_mb),
       do: required_downlink_mb > 0.0

  defp downlink_demand_relevant?(_required_downlink_mb, _threshold_mb), do: false

  defp station_throughput_feedback_event(
         station_id,
         factor,
         source_scope,
         horizon_end_s,
         trust_boundary
       ) do
    %{
      "type" => "station_throughput_feedback",
      "station_throughput_factor" => factor |> max(0.0) |> min(1.0),
      "feedback_source" => "operational_feedback.station_throughput_factor",
      "feedback_scope" => source_scope,
      "starts_at_s" => 0.0,
      "ends_at_s" => horizon_end_s,
      "ground_station_id" => station_id,
      "trust_boundary" =>
        feedback_event_trust_boundary(
          trust_boundary,
          "station_throughput_factor",
          station_id || "default"
        )
    }
    |> compact_map()
  end

  defp numeric_policy_value(policy, key, default) do
    case numeric_or_nil(Map.get(policy, key)) do
      value when is_number(value) -> value
      _value -> default
    end
  end

  defp policy_count_value(policy, key, default) do
    case numeric_policy_value(policy, key, default) do
      value when is_number(value) -> max(trunc(value), 0)
      _value -> default
    end
  end

  defp boolean_policy_value(policy, key, default) do
    case json_boolean_value(Map.get(policy, key, default)) do
      value when is_boolean(value) -> value
      _value -> default
    end
  end

  defp json_boolean_value(value) when is_boolean(value), do: value

  defp json_boolean_value(value) when is_number(value) do
    cond do
      value == 1 -> true
      value == 0 -> false
      true -> nil
    end
  end

  defp json_boolean_value(value) when is_binary(value) do
    case String.downcase(String.trim(value)) do
      "true" -> true
      "1" -> true
      "false" -> false
      "0" -> false
      _value -> nil
    end
  end

  defp json_boolean_value(_value), do: nil

