  defp availability_feedback_reason("payload_available"),
    do: "payload_availability_feedback_false"

  defp availability_feedback_reason("antenna_available"),
    do: "antenna_availability_feedback_false"

  defp spacecraft_degraded_availability_feedback?(availability) do
    truthy?(Map.get(availability, "degraded")) or
      Map.get(availability, "mode") in ["degraded", "degraded_mode", "safe"] or
      Map.get(availability, "spacecraft_available") == false or
      Map.get(availability, "spacecraft_availability") == false
  end

  defp degraded_spacecraft_feedback_event(
         spacecraft_id,
         availability,
         horizon_end_s,
         trust_boundary
       ) do
    %{
      "type" => "degraded_spacecraft",
      "scenario_id" => spacecraft_id,
      "spacecraft_id" => spacecraft_id,
      "mode" => Map.get(availability, "mode", "degraded"),
      "incompatible_activity_types" => availability_incompatible_activity_types(availability),
      "derivation_reasons" => degraded_availability_feedback_reasons(availability),
      "feedback_source" => "operational_feedback.resource_availability_overrides",
      "feedback_scope" => "spacecraft",
      "starts_at_s" => 0.0,
      "ends_at_s" => horizon_end_s,
      "trust_boundary" =>
        feedback_event_trust_boundary(
          trust_boundary,
          "resource_availability_overrides",
          spacecraft_id || "default"
        )
    }
    |> compact_map()
  end

  defp availability_incompatible_activity_types(availability) do
    explicit =
      Map.get(availability, "incompatible_activity_types") ||
        Map.get(availability, "suppressed_activity_types")

    cond do
      explicit not in [nil, []] ->
        normalize_incompatible_activity_types(explicit)

      Map.get(availability, "spacecraft_available") == false or
          Map.get(availability, "spacecraft_availability") == false ->
        ["downlink", "observe", "planned_contact"]

      true ->
        degradation_incompatible_activity_types(availability)
    end
  end

  defp degraded_availability_feedback_reasons(availability) do
    [
      if(truthy?(Map.get(availability, "degraded")), do: "spacecraft_degraded_feedback_true"),
      if(Map.get(availability, "mode") in ["degraded", "degraded_mode", "safe"],
        do: "spacecraft_mode_feedback_#{Map.get(availability, "mode")}"
      ),
      if(Map.get(availability, "spacecraft_available") == false,
        do: "spacecraft_available_feedback_false"
      ),
      if(Map.get(availability, "spacecraft_availability") == false,
        do: "spacecraft_availability_feedback_false"
      )
    ]
    |> Enum.reject(&is_nil/1)
  end

  defp planning_ground_station_ids(mission_state, prior_plan) do
    mission_state_ids =
      [
        Map.get(mission_state, "ground_stations", []),
        Map.get(mission_state, "ground_network", [])
      ]
      |> List.flatten()
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&ground_network_station_id/1)

    plan_ids =
      [
        prior_plan_activities(prior_plan),
        prior_plan_candidate_activities(prior_plan),
        prior_plan_proposed_contacts(prior_plan)
      ]
      |> List.flatten()
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&Map.get(&1, "ground_station_id"))

    (mission_state_ids ++ plan_ids)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp planning_command_activities(prior_plan) do
    prior_plan
    |> prior_plan_activities()
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(&command_activity?/1)
    |> Enum.sort_by(fn activity ->
      {Map.get(activity, "id") || Map.get(activity, "activity_id") || "",
       Map.get(activity, "scenario_id") || ""}
    end)
  end

  defp planning_maneuver_activities(prior_plan) do
    prior_plan
    |> prior_plan_activities()
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(&maneuver_activity?/1)
    |> Enum.sort_by(fn activity ->
      {Map.get(activity, "id") || Map.get(activity, "activity_id") || "",
       Map.get(activity, "scenario_id") || ""}
    end)
  end

  defp maneuver_feedback_keys(activity) do
    [
      Map.get(activity, "id"),
      Map.get(activity, "activity_id"),
      Map.get(activity, "planned_activity_id"),
      explicit_timeline_id(activity),
      Map.get(activity, "scenario_id")
    ]
    |> feedback_identity_keys()
  end

  defp maneuver_feedback_scope(activity, feedback_key) do
    cond do
      feedback_key == Map.get(activity, "id") -> "activity"
      feedback_key == Map.get(activity, "activity_id") -> "activity"
      feedback_key == Map.get(activity, "planned_activity_id") -> "planned_activity"
      feedback_key == explicit_timeline_id(activity) -> "timeline"
      feedback_key == Map.get(activity, "scenario_id") -> "scenario"
      true -> "unknown"
    end
  end

  defp command_feedback_keys(activity) do
    [
      Map.get(activity, "id"),
      Map.get(activity, "activity_id"),
      Map.get(activity, "planned_activity_id"),
      explicit_timeline_id(activity),
      Map.get(activity, "scenario_id")
    ]
    |> feedback_identity_keys()
  end

  defp command_feedback_scope(activity, feedback_key) do
    cond do
      feedback_key == explicit_timeline_id(activity) ->
        "timeline"

      feedback_key == Map.get(activity, "scenario_id") ->
        "scenario"

      true ->
        "activity"
    end
  end

  defp planning_target_ids(mission_state, prior_plan) do
    mission_target_ids =
      [
        Map.get(mission_state, "targets", []),
        Map.get(mission_state, "objectives", [])
      ]
      |> List.flatten()
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&(Map.get(&1, "target_id") || Map.get(&1, "id")))

    plan_target_ids =
      [
        prior_plan_activities(prior_plan),
        prior_plan_candidate_activities(prior_plan)
      ]
      |> List.flatten()
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&Map.get(&1, "target_id"))

    (mission_target_ids ++ plan_target_ids)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp planning_target_priorities(mission_state, prior_plan) do
    [
      Map.get(mission_state, "targets", []),
      Map.get(mission_state, "objectives", []),
      prior_plan_candidate_activities(prior_plan),
      prior_plan_activities(prior_plan)
    ]
    |> List.flatten()
    |> Enum.map(&stringify_keys/1)
    |> Enum.reduce(%{}, fn item, acc ->
      target_id = Map.get(item, "target_id") || Map.get(item, "id")
      priority = numeric_or_nil(Map.get(item, "priority") || Map.get(item, "target_priority"))

      if target_id in [nil, ""] or not is_number(priority) do
        acc
      else
        Map.put_new(acc, target_id, priority)
      end
    end)
  end

  defp derived_fuel_preservation_branches(mission_state, policy) do
    resources =
      mission_state
      |> Map.get("resources", %{})
      |> stringify_keys()

    fuel_sources = mission_state_resource_margin_sources(mission_state, "fuel_margin")
    fuel_source = List.first(fuel_sources)
    fuel_margin = fuel_source && fuel_source["fuel_margin"]
    requested? = truthy?(Map.get(resources, "fuel_preservation_requested"))
    low_fuel? = is_number(fuel_margin) and fuel_margin <= policy["fuel_margin_threshold"]

    objective_requested? =
      mission_state
      |> Map.get("objectives", [])
      |> Enum.any?(&(Map.get(&1, "type") == "fuel_preservation"))

    if requested? or objective_requested? or low_fuel? do
      [
        %{
          "id" => "derived_fuel_preservation",
          "label" => "Derived fuel preservation",
          "events" =>
            [%{"type" => "fuel_preservation_mode"}] ++
              resource_margin_pressure_events(
                mission_state,
                fuel_sources,
                policy,
                "fuel_margin",
                "fuel_margin_threshold",
                "fuel_margin_low"
              ),
          "metadata" => %{
            "derived_source" => mission_state_resource_source_path(mission_state, "fuel_margin")
          }
        }
      ]
    else
      []
    end
  end

  defp resource_margin_pressure_events(
         mission_state,
         sources,
         policy,
         field,
         threshold_key,
         reason
       ) do
    sources
    |> Enum.filter(fn source ->
      is_number(source[field]) and source[field] <= policy[threshold_key]
    end)
    |> case do
      [] ->
        []

      sources ->
        sources
    end
    |> Enum.map(fn source ->
      %{
        "type" => "resource_margin_pressure",
        "spacecraft_id" =>
          Map.get(source || %{}, "spacecraft_id") ||
            mission_state_resource_spacecraft_id(mission_state),
        "resource_field" => field,
        field => source[field],
        threshold_key => policy[threshold_key],
        "derivation_reasons" => [reason],
        "source_quality" => source && source["source_quality"]
      }
      |> compact_map()
    end)
  end

  defp derived_power_constrained_branches(mission_state, policy) do
    mission_state
    |> mission_state_resource_margin_sources("power_margin")
    |> Enum.filter(fn source ->
      is_number(source["power_margin"]) and
        source["power_margin"] <= policy["power_margin_threshold"]
    end)
    |> Enum.map(fn source ->
      spacecraft_id = source["spacecraft_id"]

      %{
        "id" => "derived_power_constrained_#{spacecraft_id}",
        "label" => "Derived power constrained #{spacecraft_id}",
        "events" => [
          %{
            "type" => "resource_margin_pressure",
            "spacecraft_id" => spacecraft_id,
            "resource_field" => "power_margin",
            "power_margin" => source["power_margin"],
            "power_margin_threshold" => policy["power_margin_threshold"],
            "derivation_reasons" => ["power_margin_low"],
            "source_quality" => source["source_quality"]
          }
          |> compact_map()
        ],
        "metadata" => %{
          "derived_source" => mission_state_resource_source_path(mission_state, "power_margin")
        }
      }
    end)
  end

  defp derived_thermal_constrained_branches(mission_state, %{
         "thermal_margin_c_threshold" => threshold
       })
       when is_number(threshold) do
    mission_state
    |> mission_state_resource_metric_sources()
    |> Enum.filter(fn source ->
      is_number(source["thermal_margin_c"]) and source["thermal_margin_c"] <= threshold and
        source["spacecraft_id"] not in [nil, ""]
    end)
    |> Enum.sort_by(& &1["spacecraft_id"])
    |> Enum.map(fn source ->
      spacecraft_id = source["spacecraft_id"]

      %{
        "id" => "derived_thermal_constrained_#{spacecraft_id}",
        "label" => "Derived thermal constrained #{spacecraft_id}",
        "events" => [
          %{
            "type" => "resource_margin_pressure",
            "spacecraft_id" => spacecraft_id,
            "resource_field" => "thermal_margin_c",
            "thermal_margin_c" => source["thermal_margin_c"],
            "thermal_margin_c_threshold" => threshold,
            "derivation_reasons" => ["thermal_margin_low"],
            "source_quality" => source["source_quality"]
          }
          |> compact_map()
        ],
        "metadata" => %{
          "derived_source" =>
            mission_state_resource_source_path(mission_state, "thermal_margin_c")
        }
      }
    end)
  end

  defp derived_thermal_constrained_branches(_mission_state, _policy), do: []

