  defp resource_availability_constraint_event(spacecraft_id, field, reason, source) do
    %{
      "type" => "resource_availability_constraint",
      "spacecraft_id" => spacecraft_id,
      "resource_field" => field,
      "available" => false,
      "derivation_reasons" => [reason],
      "source_quality" => source["source_quality"]
    }
    |> compact_map()
  end

  defp disambiguate_mission_state_resource_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if mission_state_resource_branch_id?(branch_id) and Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> mission_state_resource_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("mission_state_resource_branch_base_id", branch_id)
          |> Map.put("mission_state_resource_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_mission_state_resource_suffixes()
  end

  defp mission_state_resource_branch_id?(id) when is_binary(id) do
    Enum.any?(
      [
        "derived_power_constrained_",
        "derived_thermal_constrained_",
        "derived_payload_constrained_",
        "derived_antenna_constrained_"
      ],
      &String.starts_with?(id, &1)
    )
  end

  defp mission_state_resource_branch_id?(_id), do: false

  defp disambiguate_duplicate_mission_state_resource_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "mission_state_resource_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["mission_state_resource_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["mission_state_resource_branch_base_id"]}_#{suffix}")
        |> Map.update(
          "metadata",
          %{},
          &Map.put(&1, "mission_state_resource_branch_identity", suffix)
        )
      else
        branch
      end
    end)
  end

  defp mission_state_resource_branch_identity(branch, index) do
    metadata = Map.get(branch, "metadata", %{})

    branch
    |> Map.get("events", [])
    |> List.wrap()
    |> Enum.flat_map(fn event ->
      [
        metadata["derived_source"],
        event["type"],
        event["spacecraft_id"],
        event["resource_field"],
        event["power_margin"],
        event["power_margin_threshold"],
        event["thermal_margin_c"],
        event["thermal_margin_c_threshold"],
        event["available"],
        event["derivation_reasons"],
        event["source_quality"],
        event["trust_boundary"]
      ]
    end)
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp derived_resource_projection_pressure_branches(prior_plan, policy) do
    prior_plan
    |> prior_plan_resource_projection_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> Map.get("projected_resources", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&Map.put(&1, "_source_report_trust_boundary", trust_boundary))
      |> Enum.flat_map(&resource_projection_pressure_branch(&1, source_path, policy))
    end)
  end

  defp prior_plan_resource_projection_reports(prior_plan) do
    direct_reports =
      [
        {"source_resource_projection_report", "prior_plan.source_resource_projection_report"},
        {"resource_projection_report", "prior_plan.resource_projection_report"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        case Map.get(prior_plan, field) do
          %{} = report -> [{stringify_keys(report), source_path}]
          _report -> []
        end
      end)

    direct_reports ++ prior_plan_result_artifact_resource_projection_reports(prior_plan)
  end

