  defp mission_state_result_artifact_resource_projection_reports(mission_state, report_key) do
    mission_state
    |> mission_state_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      case Map.get(artifact, report_key) do
        %{} = report ->
          report =
            report
            |> stringify_keys()
            |> put_inherited_result_artifact_trust_boundary(artifact)

          [{report, "#{source_path}.#{report_key}"}]

        _report ->
          []
      end
    end)
  end

  defp prior_plan_result_artifact_resource_projection_reports(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      ["source_resource_projection_report", "resource_projection_report"]
      |> Enum.flat_map(fn report_key ->
        case Map.get(artifact, report_key) do
          %{} = report ->
            report =
              report
              |> stringify_keys()
              |> put_inherited_result_artifact_trust_boundary(artifact)

            [{report, "#{source_path}.#{report_key}"}]

          _report ->
            []
        end
      end)
    end)
  end

  defp resource_projection_pressure_branch(row, source_path, policy) do
    spacecraft_id = Map.get(row, "spacecraft_id") || Map.get(row, "scenario_id")
    events = resource_projection_pressure_events(row, source_path, policy)

    if spacecraft_id in [nil, ""] or events == [] do
      []
    else
      [
        %{
          "id" => "derived_projected_resource_pressure_#{branch_id_fragment(spacecraft_id)}",
          "label" => "Derived projected resource pressure #{spacecraft_id}",
          "events" => events,
          "metadata" =>
            %{
              "derived_source" => source_path,
              "resource_projection_source_quality" => row["resource_source_quality"],
              "resource_projection_trust_boundary_status" => row["resource_trust_boundary_status"]
            }
            |> compact_map()
        }
      ]
    end
  end

  defp disambiguate_resource_projection_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if resource_projection_pressure_branch_id?(branch_id) and
           Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> resource_projection_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("resource_projection_branch_base_id", branch_id)
          |> Map.put("resource_projection_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_resource_projection_suffixes()
  end

  defp resource_projection_pressure_branch_id?(id) when is_binary(id),
    do: String.starts_with?(id, "derived_projected_resource_pressure_")

  defp resource_projection_pressure_branch_id?(_id), do: false

  defp disambiguate_duplicate_resource_projection_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "resource_projection_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["resource_projection_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["resource_projection_branch_base_id"]}_#{suffix}")
        |> Map.update(
          "metadata",
          %{},
          &Map.put(&1, "resource_projection_branch_identity", suffix)
        )
      else
        branch
      end
    end)
  end

  defp resource_projection_pressure_branch_identity(branch, index) do
    branch
    |> Map.get("events", [])
    |> List.wrap()
    |> Enum.flat_map(fn event ->
      [
        event["source_window_id"],
        event["source_window_ids"],
        event["source_activity_id"],
        event["source_activity_ids"],
        event["downlink_completion_source"],
        event["downlink_completion_sources"],
        event["downlink_demand_source"],
        event["downlink_demand_sources"]
      ]
    end)
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp resource_projection_pressure_events(row, source_path, policy) do
    []
    |> Kernel.++(resource_projection_storage_pressure_events(row, source_path, policy))
    |> Kernel.++(resource_projection_downlink_pressure_events(row, source_path, policy))
    |> Kernel.++(resource_projection_battery_pressure_events(row, source_path, policy))
    |> Kernel.++(resource_projection_thermal_pressure_events(row, source_path))
    |> Kernel.++(resource_projection_availability_pressure_events(row, source_path))
    |> Kernel.++(resource_projection_activity_type_constraint_events(row, source_path))
  end

  defp resource_projection_trust_boundary(row) do
    row["resource_trust_boundary"] ||
      row["trust_boundary"] ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp resource_projection_storage_pressure_events(row, source_path, policy) do
    case numeric_or_nil(row["projected_storage_overflow_mb"]) do
      value when is_number(value) and value > 0.0 ->
        [
          resource_projection_downlink_gap_event(
            row,
            source_path,
            "projected_storage_overflow",
            value
          ),
          resource_projection_margin_pressure_event(
            row,
            source_path,
            "storage_margin",
            policy["storage_margin_threshold"],
            "projected_storage_overflow",
            %{"projected_storage_overflow_mb" => value}
          )
        ]

      _value ->
        []
    end
  end

  defp resource_projection_downlink_pressure_events(row, source_path, policy) do
    case numeric_or_nil(row["projected_downlink_shortfall_mb"]) do
      value when is_number(value) and value > 0.0 ->
        [
          resource_projection_downlink_gap_event(
            row,
            source_path,
            "projected_downlink_shortfall",
            value
          ),
          resource_projection_margin_pressure_event(
            row,
            source_path,
            "downlink_margin",
            policy["downlink_margin_threshold"],
            "projected_downlink_shortfall",
            %{"projected_downlink_shortfall_mb" => value}
          )
        ]

      _value ->
        []
    end
  end

  defp resource_projection_battery_pressure_events(row, source_path, policy) do
    case numeric_or_nil(row["projected_battery_overuse_wh"]) do
      value when is_number(value) and value > 0.0 ->
        [
          resource_projection_margin_pressure_event(
            row,
            source_path,
            "power_margin",
            policy["power_margin_threshold"],
            "projected_battery_depletion",
            %{"projected_battery_overuse_wh" => value}
          )
        ]

      _value ->
        []
    end
  end

  defp resource_projection_thermal_pressure_events(row, source_path) do
    pressure_types = row |> Map.get("resource_pressure_types", []) |> List.wrap()
    thermal_margin = numeric_or_nil(row["thermal_margin_c"])

    cond do
      is_number(thermal_margin) and thermal_margin < 0.0 ->
        [
          resource_projection_margin_pressure_event(
            row,
            source_path,
            "thermal_margin_c",
            0.0,
            "projected_thermal_margin_below_limit",
            %{"thermal_margin_c" => thermal_margin}
          )
        ]

      "thermal_margin_below_limit" in pressure_types ->
        [
          resource_projection_margin_pressure_event(
            row,
            source_path,
            "thermal_margin_c",
            0.0,
            "projected_thermal_margin_below_limit",
            %{}
          )
        ]

      true ->
        []
    end
  end

  defp resource_projection_availability_pressure_events(row, source_path) do
    row
    |> Map.get("resource_pressure_types", [])
    |> List.wrap()
    |> Enum.filter(&(&1 in resource_projection_boolean_availability_pressure_types()))
    |> Enum.map(&resource_projection_availability_pressure_event(row, source_path, &1))
  end

  defp resource_projection_availability_pressure_event(row, source_path, type) do
    pressure = resource_projection_pressure(row, type)
    resource_field = resource_projection_availability_resource_field(type)

    %{
      "type" => "resource_availability_constraint",
      "spacecraft_id" => resource_projection_scenario_id(row),
      "resource_field" => resource_field,
      "available" => false,
      resource_field => false,
      "degraded" => if(type == "spacecraft_degraded_payload_unavailable", do: true),
      "source_activity_id" => resource_projection_source_activity_id(row, pressure),
      "source_activity_ids" => resource_projection_source_activity_ids(row, type),
      "derivation_reasons" => ["projected_#{type}"],
      "feedback_source" => source_path,
      "feedback_scope" => "resource_projection",
      "trust_boundary" => resource_projection_trust_boundary(row)
    }
    |> compact_map()
  end

  defp resource_projection_availability_resource_field("spacecraft_unavailable"),
    do: "spacecraft_available"

  defp resource_projection_availability_resource_field("antenna_unavailable"),
    do: "antenna_available"

  defp resource_projection_availability_resource_field(_type), do: "payload_available"

  defp resource_projection_activity_type_constraint_events(row, source_path) do
    row
    |> Map.get("resource_pressure_types", [])
    |> List.wrap()
    |> Enum.filter(&(&1 in resource_projection_activity_type_constraint_pressure_types()))
    |> Enum.map(&resource_projection_activity_type_constraint_event(row, source_path, &1))
  end

  defp resource_projection_activity_type_constraint_event(row, source_path, type) do
    pressure = resource_projection_pressure(row, type)
    incompatible_types = resource_projection_activity_constraint_types(row, pressure)

    %{
      "type" => "degraded_spacecraft",
      "scenario_id" => resource_projection_scenario_id(row),
      "spacecraft_id" => resource_projection_scenario_id(row),
      "mode" => "resource_activity_type_constraint",
      "incompatible_activity_types" => incompatible_types,
      "source_activity_id" => resource_projection_source_activity_id(row, pressure),
      "source_activity_ids" => resource_projection_source_activity_ids(row, type),
      "derivation_reasons" => ["projected_#{type}"],
      "feedback_source" => source_path,
      "feedback_scope" => "resource_projection",
      "trust_boundary" => resource_projection_trust_boundary(row)
    }
    |> compact_map()
  end

  defp resource_projection_activity_constraint_types(row, pressure) do
    [
      row["incompatible_activity_types"],
      row["suppressed_activity_types"],
      pressure["incompatible_activity_types"],
      pressure["suppressed_activity_types"],
      pressure["activity_type"]
    ]
    |> List.flatten()
    |> normalize_incompatible_activity_types()
    |> case do
      [] -> ["observe"]
      types -> types
    end
  end

  defp resource_projection_downlink_gap_event(row, source_path, reason, required_downlink_mb) do
    pressure = resource_projection_pressure(row, reason)

    %{
      "type" => "downlink_completion_gap",
      "scenario_id" => resource_projection_scenario_id(row),
      "ground_station_id" => resource_projection_ground_station_id(row, reason),
      "required_contacts" => 1,
      "planned_contacts" => 0,
      "required_downlink_mb" =>
        resource_projection_required_downlink_mb(row, reason, required_downlink_mb),
      "planned_downlink_mb" => resource_projection_planned_downlink_mb(row, reason),
      "starts_at_s" => 0.0,
      "ends_at_s" => resource_projection_pressure_end_s(row, pressure),
      "source_activity_id" => stable_source_activity_id(pressure),
      "source_activity_ids" => resource_projection_pressure_activity_ids(row, reason),
      "downlink_demand_sources" => resource_projection_downlink_sources(row, reason),
      "downlink_completion_sources" => resource_projection_downlink_sources(row, reason),
      "derivation_reasons" => [reason],
      "feedback_source" => source_path,
      "feedback_scope" => "resource_projection",
      "trust_boundary" => resource_projection_trust_boundary(row)
    }
    |> compact_map()
  end

  defp resource_projection_ground_station_id(row, reason) do
    pressure = resource_projection_pressure(row, reason)

    [
      pressure["ground_station_id"],
      pressure["station_id"],
      score_term_entity_id(pressure["ground_station"], ["ground_station_id", "station_id", "id"]),
      score_term_entity_id(pressure["station"], ["ground_station_id", "station_id", "id"]),
      row["ground_station_id"],
      row["station_id"],
      score_term_entity_id(row["ground_station"], ["ground_station_id", "station_id", "id"]),
      score_term_entity_id(row["station"], ["ground_station_id", "station_id", "id"])
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp resource_projection_planned_downlink_mb(row, reason) do
    pressure = resource_projection_pressure(row, reason)

    [
      pressure["planned_downlink_mb"],
      pressure["selected_downlink_mb"],
      pressure["actual_downlink_mb"],
      get_in(pressure, ["throughput_model", "planned_downlink_mb"]),
      get_in(pressure, ["throughput_model", "selected_downlink_mb"]),
      get_in(pressure, ["throughput_model", "actual_downlink_mb"]),
      get_in(pressure, ["activity_context", "planned_downlink_mb"]),
      get_in(pressure, ["activity_context", "selected_downlink_mb"]),
      get_in(pressure, ["activity_context", "actual_downlink_mb"]),
      row["planned_downlink_mb"],
      row["selected_downlink_mb"],
      row["actual_downlink_mb"],
      get_in(row, ["throughput_model", "planned_downlink_mb"]),
      get_in(row, ["throughput_model", "selected_downlink_mb"]),
      get_in(row, ["throughput_model", "actual_downlink_mb"]),
      get_in(row, ["activity_context", "planned_downlink_mb"]),
      get_in(row, ["activity_context", "selected_downlink_mb"]),
      get_in(row, ["activity_context", "actual_downlink_mb"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) -> max(value, 0.0)
      _value -> 0.0
    end
  end

  defp resource_projection_required_downlink_mb(row, reason, fallback_gap_mb) do
    pressure = resource_projection_pressure(row, reason)

    [
      pressure["required_downlink_mb"],
      pressure["target_downlink_mb"],
      pressure["downlink_requirement_mb"],
      get_in(pressure, ["throughput_model", "required_downlink_mb"]),
      get_in(pressure, ["throughput_model", "target_downlink_mb"]),
      get_in(pressure, ["throughput_model", "downlink_requirement_mb"]),
      get_in(pressure, ["activity_context", "required_downlink_mb"]),
      get_in(pressure, ["activity_context", "target_downlink_mb"]),
      get_in(pressure, ["activity_context", "downlink_requirement_mb"]),
      row["required_downlink_mb"],
      row["target_downlink_mb"],
      row["downlink_requirement_mb"],
      get_in(row, ["throughput_model", "required_downlink_mb"]),
      get_in(row, ["throughput_model", "target_downlink_mb"]),
      get_in(row, ["throughput_model", "downlink_requirement_mb"]),
      get_in(row, ["activity_context", "required_downlink_mb"]),
      get_in(row, ["activity_context", "target_downlink_mb"]),
      get_in(row, ["activity_context", "downlink_requirement_mb"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) ->
        max(value, 0.0)

      _value ->
        planned_downlink_mb = resource_projection_planned_downlink_mb(row, reason)
        max(planned_downlink_mb + fallback_gap_mb, fallback_gap_mb)
    end
  end

  defp resource_projection_downlink_sources(row, reason) do
    explicit =
      [
        row["downlink_demand_source"],
        row["downlink_demand_sources"],
        row["downlink_completion_source"],
        row["downlink_completion_sources"]
      ]
      |> Kernel.++(
        row
        |> resource_projection_pressure_flow_rows(reason)
        |> Enum.flat_map(fn flow ->
          [
            flow["downlink_demand_source"],
            flow["downlink_demand_sources"],
            flow["downlink_completion_source"],
            flow["downlink_completion_sources"],
            get_in(flow, ["throughput_model", "downlink_demand_source"]),
            get_in(flow, ["throughput_model", "downlink_demand_sources"]),
            get_in(flow, ["throughput_model", "downlink_completion_source"]),
            get_in(flow, ["throughput_model", "downlink_completion_sources"]),
            get_in(flow, ["activity_context", "downlink_demand_source"]),
            get_in(flow, ["activity_context", "downlink_demand_sources"]),
            get_in(flow, ["activity_context", "downlink_completion_source"]),
            get_in(flow, ["activity_context", "downlink_completion_sources"])
          ]
        end)
      )
      |> List.flatten()
      |> Enum.map(&encode_value/1)
      |> Enum.reject(&(&1 in [nil, ""]))

    sources =
      case explicit do
        [] ->
          row
          |> resource_projection_pressure_activity_ids(reason)
          |> List.wrap()
          |> Enum.map(&"resource_projection.#{reason}:#{&1}")

        sources ->
          sources
      end

    sources
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp resource_projection_margin_pressure_event(
         row,
         source_path,
         field,
         threshold,
         reason,
         extra
       ) do
    pressure = resource_projection_pressure(row, reason)

    %{
      "type" => "resource_margin_pressure",
      "spacecraft_id" => Map.get(row, "spacecraft_id") || Map.get(row, "scenario_id"),
      "scenario_id" => resource_projection_scenario_id(row),
      "resource_field" => field,
      field => 0.0,
      "#{field}_threshold" => threshold,
      "starts_at_s" => 0.0,
      "ends_at_s" => resource_projection_pressure_end_s(row, pressure),
      "source_activity_id" => stable_source_activity_id(pressure),
      "source_activity_ids" => resource_projection_pressure_activity_ids(row, reason),
      "derivation_reasons" => [reason],
      "feedback_source" => source_path,
      "feedback_scope" => "resource_projection",
      "trust_boundary" => resource_projection_trust_boundary(row),
      "source_quality" => row["resource_source_quality"]
    }
    |> Map.merge(extra)
    |> compact_map()
  end

  defp resource_projection_pressure(row, "projected_storage_overflow"),
    do: first_resource_projection_pressure([row], "storage_overflow")

  defp resource_projection_pressure(row, "projected_downlink_shortfall"),
    do: first_resource_projection_pressure([row], "downlink_shortfall")

  defp resource_projection_pressure(row, "projected_battery_depletion"),
    do: first_resource_projection_pressure([row], "battery_depletion")

  defp resource_projection_pressure(row, type)
       when type in [
              "spacecraft_unavailable",
              "payload_unavailable",
              "spacecraft_degraded_payload_unavailable",
              "activity_type_suppressed_by_resource_summary",
              "activity_type_incompatible_with_resource_summary",
              "antenna_unavailable"
            ],
       do: first_resource_projection_pressure([row], type)

  defp resource_projection_pressure(_row, _reason), do: %{}

  defp resource_projection_pressure_activity_ids(row, reason) do
    row
    |> resource_projection_pressure_flow_rows(reason)
    |> Enum.map(&Map.get(&1, "activity_id"))
    |> Enum.filter(&stable_id_string?/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp resource_projection_source_activity_id(row, pressure) do
    stable_source_activity_id(pressure) ||
      List.first(resource_projection_row_activity_ids(row))
  end

  defp resource_projection_source_activity_ids(row, reason) do
    resource_projection_pressure_activity_ids(row, reason) ||
      case resource_projection_row_activity_ids(row) do
        [] -> nil
        ids -> ids
      end
  end

  defp resource_projection_row_activity_ids(row) do
    [
      row["source_activity_ids"],
      row["source_activity_id"],
      row["activity_ids"],
      row["activity_id"],
      row["source_activity"],
      row["source_activities"]
    ]
    |> Enum.flat_map(&List.wrap/1)
    |> Enum.map(&resource_projection_activity_id_value/1)
    |> Enum.filter(&stable_id_string?/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp resource_projection_activity_id_value(%{} = activity) do
    Map.get(activity, "activity_id") || Map.get(activity, "id")
  end

  defp resource_projection_activity_id_value(value), do: value

  defp resource_projection_pressure_flow_rows(row, "projected_storage_overflow") do
    row
    |> resource_projection_flow_rows()
    |> Enum.filter(&positive_number?(&1["storage_overflow_mb"]))
  end

  defp resource_projection_pressure_flow_rows(row, "projected_downlink_shortfall") do
    row
    |> resource_projection_flow_rows()
    |> Enum.filter(&positive_number?(&1["downlink_shortfall_mb"]))
  end

  defp resource_projection_pressure_flow_rows(row, "projected_battery_depletion") do
    row
    |> resource_projection_flow_rows()
    |> Enum.filter(&positive_number?(&1["battery_overuse_wh"]))
  end

  defp resource_projection_pressure_flow_rows(row, reason)
       when reason in [
              "spacecraft_unavailable",
              "payload_unavailable",
              "spacecraft_degraded_payload_unavailable",
              "activity_type_suppressed_by_resource_summary",
              "activity_type_incompatible_with_resource_summary",
              "antenna_unavailable"
            ] do
    row
    |> resource_projection_flow_rows()
    |> Enum.filter(&(Map.get(&1, "resource_effect_reason") == reason))
  end

  defp resource_projection_pressure_flow_rows(_row, _reason), do: []

  defp resource_projection_pressure_end_s(row, pressure) do
    [Map.get(pressure, "ends_at_s"), Map.get(pressure, "starts_at_s"), Map.get(row, "ends_at_s")]
    |> Enum.find(&is_number/1)
  end

  defp resource_projection_scenario_id(row) do
    Map.get(row, "scenario_id") || Map.get(row, "spacecraft_id")
  end

  defp stable_source_activity_id(%{"activity_id" => activity_id}) do
    if stable_id_string?(activity_id), do: activity_id
  end

  defp stable_source_activity_id(_pressure), do: nil

  defp derived_resource_filter_pressure_branches(prior_plan) do
    prior_plan
    |> prior_plan_resource_filter_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> Map.get("suppressed_candidates", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.flat_map(fn row ->
        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> Map.put("_source_report_policy", Map.get(report, "policy") || %{})
        |> resource_filter_pressure_branch(source_path)
      end)
    end)
  end

  defp prior_plan_resource_filter_reports(prior_plan) do
    direct_reports =
      [
        {"source_resource_filter_report", "prior_plan.source_resource_filter_report"},
        {"resource_filter_report", "prior_plan.resource_filter_report"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        case Map.get(prior_plan, field) do
          %{} = report -> [{stringify_keys(report), source_path}]
          _report -> []
        end
      end)

    direct_reports ++ prior_plan_result_artifact_resource_filter_reports(prior_plan)
  end

  defp derived_mission_state_resource_filter_pressure_branches(mission_state) do
    mission_state
    |> mission_state_resource_filter_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> Map.get("suppressed_candidates", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.flat_map(fn row ->
        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> Map.put("_source_report_policy", Map.get(report, "policy") || %{})
        |> resource_filter_pressure_branch(source_path)
      end)
    end)
  end

  defp mission_state_resource_filter_reports(mission_state) do
    mission_state = stringify_keys(mission_state || %{})

    mission_state_resource_filter_reports(mission_state, [
      {"source_resource_filter_report", "mission_state.source_resource_filter_report"},
      {"resource_filter_report", "mission_state.resource_filter_report"}
    ]) ++
      mission_state_result_artifact_resource_filter_reports(
        mission_state,
        "source_resource_filter_report"
      ) ++
      mission_state_result_artifact_resource_filter_reports(
        mission_state,
        "resource_filter_report"
      )
  end

  defp mission_state_source_resource_filter_reports(mission_state) do
    mission_state_resource_filter_reports(mission_state, [
      {"source_resource_filter_report", "mission_state.source_resource_filter_report"}
    ])
  end

  defp mission_state_canonical_resource_filter_reports(mission_state) do
    mission_state_resource_filter_reports(mission_state, [
      {"resource_filter_report", "mission_state.resource_filter_report"}
    ])
  end

  defp mission_state_resource_filter_reports(mission_state, fields) do
    mission_state = stringify_keys(mission_state || %{})

    fields
    |> Enum.flat_map(fn {field, source_path} ->
      mission_state
      |> Map.get(field)
      |> mission_state_source_report_entries(source_path)
    end)
  end

  defp mission_state_source_resource_filter_summaries(mission_state) do
    mission_state_resource_filter_summaries(mission_state, [
      {"source_resource_filter_summary", "mission_state.source_resource_filter_summary"}
    ])
  end

  defp mission_state_canonical_resource_filter_summaries(mission_state) do
    mission_state_resource_filter_summaries(mission_state, [
      {"resource_filter_summary", "mission_state.resource_filter_summary"}
    ])
  end

  defp mission_state_resource_filter_summaries(mission_state, fields) do
    mission_state = stringify_keys(mission_state || %{})

    fields
    |> Enum.flat_map(fn {field, source_path} ->
      mission_state
      |> Map.get(field)
      |> mission_state_source_report_entries(source_path)
    end)
  end

  defp mission_state_result_artifact_resource_filter_reports(mission_state, report_key) do
    mission_state
    |> mission_state_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      case Map.get(artifact, report_key) do
        %{} = report ->
          report =
            report
            |> stringify_keys()
            |> put_inherited_result_artifact_trust_boundary(artifact)

          [{report, "#{source_path}.#{report_key}"}]

        _report ->
          []
      end
    end)
  end

  defp prior_plan_result_artifact_resource_filter_reports(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      ["source_resource_filter_report", "resource_filter_report"]
      |> Enum.flat_map(fn report_key ->
        case Map.get(artifact, report_key) do
          %{} = report ->
            report =
              report
              |> stringify_keys()
              |> put_inherited_result_artifact_trust_boundary(artifact)

            [{report, "#{source_path}.#{report_key}"}]

          _report ->
            []
        end
      end)
    end)
  end

  defp resource_filter_pressure_branch(row, source_path) do
    event = resource_filter_pressure_event(row, source_path)
    candidate_id = resource_filter_candidate_id(row)

    if is_nil(event) or not stable_id_string?(candidate_id) do
      []
    else
      reason =
        row
        |> Map.get("suppressed_reason", "suppressed")
        |> branch_id_fragment()

      [
        %{
          "id" =>
            "derived_resource_filter_pressure_#{reason}_#{branch_id_fragment(candidate_id)}",
          "label" => "Derived resource filter pressure #{candidate_id}",
          "events" => [event],
          "metadata" =>
            %{
              "derived_source" => source_path,
              "suppressed_reason" => row["suppressed_reason"],
              "resource_source_quality" => row["resource_source_quality"],
              "resource_trust_boundary_status" => row["resource_trust_boundary_status"]
            }
            |> compact_map()
        }
      ]
    end
  end

  defp disambiguate_resource_filter_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if resource_filter_pressure_branch_id?(branch_id) and Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> resource_filter_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("resource_filter_branch_base_id", branch_id)
          |> Map.put("resource_filter_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_resource_filter_suffixes()
  end

  defp resource_filter_pressure_branch_id?(id) when is_binary(id),
    do: String.starts_with?(id, "derived_resource_filter_pressure_")

  defp resource_filter_pressure_branch_id?(_id), do: false

  defp disambiguate_duplicate_resource_filter_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "resource_filter_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["resource_filter_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["resource_filter_branch_base_id"]}_#{suffix}")
        |> Map.update("metadata", %{}, &Map.put(&1, "resource_filter_branch_identity", suffix))
      else
        branch
      end
    end)
  end

  defp resource_filter_pressure_branch_identity(branch, index) do
    branch
    |> Map.get("events", [])
    |> List.wrap()
    |> Enum.flat_map(fn event ->
      [
        event["feedback_source"],
        event["source_activity_id"],
        event["source_activity_ids"],
        event["resource_field"],
        event["starts_at_s"],
        event["ends_at_s"],
        event["trust_boundary"]
      ]
    end)
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp resource_filter_pressure_event(row, source_path) do
    case resource_filter_pressure(row) do
      {:availability, field} -> resource_filter_availability_event(row, source_path, field)
      {:margin, field} -> resource_filter_margin_event(row, source_path, field)
      nil -> nil
    end
  end

  defp resource_filter_pressure(%{"suppressed_reason" => "spacecraft_unavailable"}),
    do: {:availability, "spacecraft_available"}

  defp resource_filter_pressure(%{"suppressed_reason" => "fuel_margin_below_policy"}),
    do: {:margin, "fuel_margin"}

  defp resource_filter_pressure(%{"suppressed_reason" => "payload_unavailable"}),
    do: {:availability, "payload_available"}

  defp resource_filter_pressure(%{
         "suppressed_reason" => "spacecraft_degraded_payload_unavailable"
       }),
       do: {:availability, "payload_available"}

  defp resource_filter_pressure(%{"suppressed_reason" => "power_margin_below_observe_policy"}),
    do: {:margin, "power_margin"}

  defp resource_filter_pressure(%{"suppressed_reason" => "storage_margin_below_observe_policy"}),
    do: {:margin, "storage_margin"}

  defp resource_filter_pressure(%{"suppressed_reason" => "antenna_unavailable"}),
    do: {:availability, "antenna_available"}

  defp resource_filter_pressure(%{"suppressed_reason" => "power_margin_below_downlink_policy"}),
    do: {:margin, "power_margin"}

  defp resource_filter_pressure(%{"suppressed_reason" => "downlink_margin_below_policy"}),
    do: {:margin, "downlink_margin"}

  defp resource_filter_pressure(%{"suppressed_reason" => "thermal_margin_below_policy"}),
    do: {:margin, "thermal_margin_c"}

  defp resource_filter_pressure(_row), do: nil

  defp resource_filter_availability_event(row, source_path, field) do
    %{
      "type" => "resource_availability_constraint",
      "scenario_id" => row["scenario_id"] || row["spacecraft_id"],
      "spacecraft_id" => row["spacecraft_id"] || row["scenario_id"],
      "resource_field" => field,
      "available" => false,
      "starts_at_s" => numeric_or_nil(row["starts_at_s"] || row["start_s"]),
      "ends_at_s" => numeric_or_nil(row["ends_at_s"] || row["end_s"]),
      "source_activity_id" => resource_filter_candidate_id(row),
      "source_activity_ids" => List.wrap(resource_filter_candidate_id(row)),
      "suppressed_reason" => row["suppressed_reason"],
      "source_quality" => row["resource_source_quality"],
      "resource_trust_boundary_status" => row["resource_trust_boundary_status"],
      "derivation_reasons" => resource_filter_pressure_reasons(row),
      "feedback_source" => source_path,
      "feedback_scope" => "resource_filter",
      "trust_boundary" => resource_filter_trust_boundary(row)
    }
    |> compact_map()
  end

  defp resource_filter_margin_event(row, source_path, field) do
    value = resource_filter_margin_value(row, field)

    if is_nil(value) do
      nil
    else
      %{
        "type" => "resource_margin_pressure",
        "scenario_id" => row["scenario_id"] || row["spacecraft_id"],
        "spacecraft_id" => row["spacecraft_id"] || row["scenario_id"],
        "resource_field" => field,
        field => value,
        "#{field}_threshold" => resource_filter_margin_threshold(row, field),
        "starts_at_s" => numeric_or_nil(row["starts_at_s"] || row["start_s"]),
        "ends_at_s" => numeric_or_nil(row["ends_at_s"] || row["end_s"]),
        "source_activity_id" => resource_filter_candidate_id(row),
        "source_activity_ids" => List.wrap(resource_filter_candidate_id(row)),
        "suppressed_reason" => row["suppressed_reason"],
        "source_quality" => row["resource_source_quality"],
        "resource_trust_boundary_status" => row["resource_trust_boundary_status"],
        "derivation_reasons" => resource_filter_pressure_reasons(row),
        "feedback_source" => source_path,
        "feedback_scope" => "resource_filter",
        "trust_boundary" => resource_filter_trust_boundary(row)
      }
      |> Map.merge(operational_readiness_operator_training_context(row))
      |> compact_map()
    end
  end

  defp resource_filter_candidate_id(row) do
    row["activity_id"] || row["contact_id"] || row["id"]
  end

  defp resource_filter_margin_value(row, field) do
    [
      row[field],
      get_in(row, ["source_resource_summary", field]),
      get_in(row, ["resource_summary", field])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
  end

  defp resource_filter_margin_threshold(row, "fuel_margin"),
    do:
      numeric_or_nil(
        row["min_activity_fuel_margin"] ||
          get_in(row, ["_source_report_policy", "min_activity_fuel_margin"]) ||
          row["fuel_margin_threshold"]
      )

  defp resource_filter_margin_threshold(row, "power_margin") do
    numeric_or_nil(
      row["min_observe_power_margin"] || row["min_downlink_power_margin"] ||
        get_in(row, ["_source_report_policy", "min_observe_power_margin"]) ||
        get_in(row, ["_source_report_policy", "min_downlink_power_margin"]) ||
        row["power_margin_threshold"]
    )
  end

  defp resource_filter_margin_threshold(row, "storage_margin"),
    do:
      numeric_or_nil(
        row["min_observe_storage_margin"] ||
          get_in(row, ["_source_report_policy", "min_observe_storage_margin"]) ||
          row["storage_margin_threshold"]
      )

  defp resource_filter_margin_threshold(row, "downlink_margin"),
    do:
      numeric_or_nil(
        row["min_downlink_margin"] ||
          get_in(row, ["_source_report_policy", "min_downlink_margin"]) ||
          row["downlink_margin_threshold"]
      )

  defp resource_filter_margin_threshold(row, "thermal_margin_c"),
    do:
      numeric_or_nil(
        row["min_activity_thermal_margin_c"] ||
          get_in(row, ["_source_report_policy", "min_activity_thermal_margin_c"]) ||
          row["thermal_margin_c_threshold"]
      )

  defp resource_filter_pressure_reasons(row) do
    [
      "resource_filter_suppressed",
      row["suppressed_reason"]
    ]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
  end

  defp resource_filter_trust_boundary(row) do
    Map.get(row, "trust_boundary") ||
      Map.get(row, "resource_trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      get_in(row, ["resource_provenance", "trust_boundary"]) ||
      get_in(row, ["source_resource_summary", "resource_trust_boundary"]) ||
      get_in(row, ["source_resource_summary", "provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp derived_contact_allocation_pressure_branches(prior_plan) do
    prior_plan
    |> prior_plan_contact_allocation_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.flat_map(fn row ->
        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> contact_allocation_pressure_branch(source_path)
      end)
    end)
  end

  defp derived_contact_allocation_summary_pressure_branches(prior_plan) do
    prior_plan
    |> prior_plan_contact_allocation_pressure_summaries()
    |> Enum.flat_map(fn {summary, source_path} ->
      trust_boundary =
        Map.get(summary, "trust_boundary") || get_in(summary, ["provenance", "trust_boundary"])

      summary
      |> contact_allocation_summary_pressure_rows()
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&Map.put(&1, "_source_report_trust_boundary", trust_boundary))
      |> Enum.flat_map(&contact_allocation_pressure_branch(&1, source_path))
    end)
  end

  defp derived_mission_state_contact_allocation_pressure_branches(mission_state) do
    mission_state
    |> mission_state_contact_allocation_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.flat_map(fn row ->
        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> contact_allocation_pressure_branch(source_path)
      end)
    end)
  end

  defp derived_mission_state_contact_allocation_summary_pressure_branches(mission_state) do
    mission_state
    |> mission_state_contact_allocation_pressure_summaries()
    |> Enum.flat_map(fn {summary, source_path} ->
      trust_boundary =
        Map.get(summary, "trust_boundary") || get_in(summary, ["provenance", "trust_boundary"])

      summary
      |> contact_allocation_summary_pressure_rows()
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&Map.put(&1, "_source_report_trust_boundary", trust_boundary))
      |> Enum.flat_map(&contact_allocation_pressure_branch(&1, source_path))
    end)
  end

  defp mission_state_contact_allocation_pressure_summaries(mission_state) do
    mission_state_source_contact_allocation_summaries(mission_state) ++
      mission_state_canonical_contact_allocation_summaries(mission_state) ++
      mission_state_source_contact_allocation_station_pressure_summaries(mission_state) ++
      mission_state_canonical_contact_allocation_station_pressure_summaries(mission_state) ++
      mission_state_source_contact_allocation_reservation_conflict_summaries(mission_state) ++
      mission_state_canonical_contact_allocation_reservation_conflict_summaries(mission_state) ++
      mission_state_source_contact_allocation_capacity_pack_summaries(mission_state) ++
      mission_state_canonical_contact_allocation_capacity_pack_summaries(mission_state) ++
      mission_state_source_contact_allocation_provider_reservation_request_summaries(
        mission_state
      ) ++
      mission_state_canonical_contact_allocation_provider_reservation_request_summaries(
        mission_state
      )
  end

  defp contact_allocation_summary_pressure_rows(summary) do
    summary_trust_boundary = contact_allocation_trust_boundary(summary)

    [
      "rows",
      "review_rows",
      "reservation_conflict_rows",
      "reservation_review_rows",
      "provider_reservation_request_rows",
      "provider_reservation_review_rows"
    ]
    |> Enum.flat_map(fn field ->
      summary
      |> Map.get(field, [])
      |> List.wrap()
      |> Enum.filter(&is_map/1)
      |> Enum.map(fn row ->
        provider_scope = contact_allocation_provider_reservation_row_scope(field)

        row
        |> Map.put_new("_source_report_trust_boundary", summary_trust_boundary)
        |> maybe_put_provider_reservation_request_status(
          provider_scope,
          summary["provider_reservation_request_status"]
        )
      end)
    end)
    |> Enum.uniq()
