  defp mission_state_contact_contention_reports(mission_state) do
    mission_state_contact_contention_reports(mission_state, [
      {"source_contact_contention_report", "mission_state.source_contact_contention_report"},
      {"contact_contention_report", "mission_state.contact_contention_report"}
    ]) ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "source_contact_contention_report"
      ) ++
      mission_state_result_artifact_embedded_reports(mission_state, "contact_contention_report")
  end

  defp mission_state_source_contact_contention_reports(mission_state) do
    mission_state_contact_contention_reports(mission_state, [
      {"source_contact_contention_report", "mission_state.source_contact_contention_report"}
    ])
  end

  defp mission_state_canonical_contact_contention_reports(mission_state) do
    mission_state_contact_contention_reports(mission_state, [
      {"contact_contention_report", "mission_state.contact_contention_report"}
    ])
  end

  defp mission_state_contact_contention_reports(mission_state, fields) do
    mission_state = stringify_keys(mission_state || %{})

    fields
    |> Enum.flat_map(fn {field, source_path} ->
      mission_state
      |> Map.get(field)
      |> mission_state_source_report_entries(source_path)
    end)
  end

  defp derived_mission_state_contact_contention_pressure_branches(mission_state) do
    mission_state
    |> mission_state_contact_contention_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> Map.get("conflict_groups", [])
      |> List.wrap()
      |> Enum.map(&stringify_keys/1)
      |> Enum.flat_map(fn group ->
        group
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> contact_contention_conflict_pressure_branches("#{source_path}.conflict_groups")
      end)
    end)
  end

  defp prior_plan_contact_contention_resolution_reports(prior_plan) do
    direct_reports =
      [
        {"source_contact_contention_resolution_report",
         "prior_plan.source_contact_contention_resolution_report"},
        {"contact_contention_resolution_report",
         "prior_plan.contact_contention_resolution_report"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        case Map.get(prior_plan, field) do
          %{} = report -> [{stringify_keys(report), source_path}]
          _report -> []
        end
      end)

    direct_reports ++ prior_plan_result_artifact_contact_contention_resolution_reports(prior_plan)
  end

  defp prior_plan_result_artifact_contact_contention_resolution_reports(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      ["source_contact_contention_resolution_report", "contact_contention_resolution_report"]
      |> Enum.flat_map(fn report_key ->
        case Map.get(artifact, report_key) do
          %{} = report ->
            report =
              report
              |> stringify_keys()
              |> put_inherited_result_artifact_trust_boundary(artifact)

            [{report, "#{source_path}.#{report_key}"}]

          _report ->
            []
        end
      end)
    end)
  end

  defp contact_contention_resolution_pressure_branches(recommendation, source_path) do
    recommendation
    |> Map.get("deferred_contact_ids", [])
    |> List.wrap()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.flat_map(fn contact_id ->
      case contact_contention_resolution_pressure_event(recommendation, contact_id, source_path) do
        nil ->
          []

        event ->
          [
            %{
              "id" =>
                "derived_contact_contention_pressure_deferred_#{branch_id_fragment(contact_id)}",
              "label" => "Derived contact contention pressure #{contact_id}",
              "events" => [event],
              "metadata" =>
                %{
                  "derived_source" => source_path,
                  "contention_group_id" => recommendation["group_id"],
                  "selected_contact_id" => recommendation["selected_contact_id"],
                  "selection_reason" => recommendation["selection_reason"],
                  "resolution_selection_rule" => recommendation["resolution_selection_rule"],
                  "selected_priority_source" => recommendation["selected_priority_source"]
                }
                |> compact_map()
            }
          ]
      end
    end)
  end

  defp contact_contention_conflict_pressure_branches(group, source_path) do
    group
    |> contact_contention_conflict_contacts()
    |> Enum.flat_map(fn source_contact ->
      case contact_contention_conflict_pressure_event(group, source_contact, source_path) do
        nil ->
          []

        event ->
          contact_id = event["contact_id"]
          group_id = event["contention_group_id"] || "conflict"

          [
            %{
              "id" =>
                "derived_contact_contention_pressure_conflict_#{branch_id_fragment(group_id)}_#{branch_id_fragment(contact_id)}",
              "label" => "Derived contact contention conflict #{contact_id}",
              "events" => [event],
              "metadata" =>
                %{
                  "derived_source" => source_path,
                  "contention_group_id" => group["id"],
                  "resource_scope" => group["resource_scope"],
                  "operator_action_reason" => group["operator_action_reason"]
                }
                |> compact_map()
            }
          ]
      end
    end)
  end

  defp contact_contention_conflict_pressure_event(group, source_contact, source_path) do
    contact_id = contact_allocation_contact_identity(source_contact)

    if stable_id_string?(contact_id) and
         contact_contention_deferred_downlink?(group, source_contact) do
      %{
        "type" => "downlink_completion_gap",
        "scenario_id" => source_contact["scenario_id"] || first_stable_id(group["scenario_ids"]),
        "spacecraft_id" =>
          source_contact["spacecraft_id"] || source_contact["scenario_id"] ||
            group["spacecraft_id"] || first_stable_id(group["spacecraft_ids"]),
        "ground_station_id" => contact_contention_ground_station_id(group, source_contact),
        "required_contacts" => 1,
        "planned_contacts" => 0,
        "required_downlink_mb" => contact_contention_required_downlink_mb(source_contact),
        "planned_downlink_mb" => 0.0,
        "starts_at_s" => activity_raw_start(source_contact) || group["starts_at_s"],
        "ends_at_s" => activity_raw_end(source_contact) || group["ends_at_s"],
        "contact_id" => contact_id,
        "source_activity_id" => contact_id,
        "source_activity_ids" => [contact_id],
        "source_window_id" => contact_contention_source_window_id(source_contact),
        "source_window_ids" => group["source_window_ids"],
        "contention_group_id" => group["id"],
        "contention_resource_scope" => group["resource_scope"],
        "contention_contact_count" => group["contact_count"],
        "contention_contact_ids" => group["contact_ids"],
        "contention_duplicate_contact_ids" => group["duplicate_contact_ids"],
        "contention_duplicate_contact_id_count" => group["duplicate_contact_id_count"],
        "required_operator_action" => group["required_operator_action"],
        "approval_status" => group["approval_status"],
        "review_status" => group["review_status"] || group["approval_status"],
        "operator_action_reason" => group["operator_action_reason"],
        "station_calendar_entry_ids" => group["station_calendar_entry_ids"],
        "station_calendar_provider_ids" => group["station_calendar_provider_ids"],
        "station_calendar_provider_entry_ids" => group["station_calendar_provider_entry_ids"],
        "station_calendar_overlap_entry_ids" => group["station_calendar_overlap_entry_ids"],
        "station_calendar_directions" => group["station_calendar_directions"],
        "station_calendar_reservation_ids" => group["station_calendar_reservation_ids"],
        "station_calendar_reserved_by" => group["station_calendar_reserved_by"],
        "station_calendar_reservation_statuses" => group["station_calendar_reservation_statuses"],
        "station_calendar_trust_boundary_statuses" =>
          group["station_calendar_trust_boundary_statuses"],
        "downlink_completion_sources" =>
          contact_contention_downlink_completion_sources(source_contact),
        "downlink_demand_sources" => contact_contention_downlink_demand_sources(source_contact),
        "derivation_reasons" => contact_contention_conflict_pressure_reasons(group),
        "feedback_source" => source_path,
        "feedback_scope" => "contact_contention",
        "trust_boundary" => contact_contention_trust_boundary(group, source_contact),
        "source_contact_candidate" => source_contact
      }
      |> compact_map()
    end
  end

  defp contact_contention_conflict_contacts(group) do
    source_contacts =
      group
      |> Map.get("source_contact_candidates", [])
      |> List.wrap()
      |> Enum.filter(&is_map/1)
      |> Enum.map(&stringify_keys/1)

    case source_contacts do
      [] ->
        group
        |> Map.get("contact_ids", [])
        |> List.wrap()
        |> Enum.map(&encode_value/1)
        |> Enum.filter(&stable_id_string?/1)
        |> Enum.map(fn contact_id ->
          %{
            "id" => contact_id,
            "contact_id" => contact_id,
            "type" => contact_contention_group_activity_type(group),
            "direction" => group["direction"],
            "scenario_id" => first_stable_id(group["scenario_ids"]),
            "spacecraft_id" => group["spacecraft_id"] || first_stable_id(group["spacecraft_ids"]),
            "ground_station_id" => group["ground_station_id"],
            "starts_at_s" => group["starts_at_s"],
            "ends_at_s" => group["ends_at_s"]
          }
          |> compact_map()
        end)

      contacts ->
        contacts
    end
  end

  defp contact_contention_group_activity_type(group) do
    cond do
      group["direction"] == "downlink" -> "downlink"
      "downlink" in List.wrap(group["directions"]) -> "downlink"
      true -> "planned_contact"
    end
  end

  defp first_stable_id(values) do
    values
    |> List.wrap()
    |> Enum.find(&stable_id_string?/1)
  end

  defp contact_contention_conflict_pressure_reasons(group) do
    [
      "contact_contention_conflict",
      group["operator_action_reason"],
      group["resource_scope"],
      group["approval_status"]
    ]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
  end

  defp disambiguate_contact_contention_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if contact_contention_pressure_branch_id?(branch_id) and
           Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> contact_contention_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("contact_contention_branch_base_id", branch_id)
          |> Map.put("contact_contention_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_contact_contention_suffixes()
  end

  defp contact_contention_pressure_branch_id?(id) when is_binary(id),
    do: String.starts_with?(id, "derived_contact_contention_pressure_")

  defp contact_contention_pressure_branch_id?(_id), do: false

  defp disambiguate_duplicate_contact_contention_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "contact_contention_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["contact_contention_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["contact_contention_branch_base_id"]}_#{suffix}")
        |> Map.update(
          "metadata",
          %{},
          &Map.put(&1, "contact_contention_branch_identity", suffix)
        )
      else
        branch
      end
    end)
  end

  defp contact_contention_pressure_branch_identity(branch, index) do
    branch
    |> Map.get("events", [])
    |> List.wrap()
    |> Enum.flat_map(fn event ->
      [
        event["source_window_id"],
        event["source_window_ids"],
        event["feedback_source"],
        event["contention_group_id"],
        event["selected_contact_id"],
        event["source_activity_id"],
        event["source_activity_ids"],
        event["ground_station_id"],
        event["required_downlink_mb"],
        event["starts_at_s"],
        event["ends_at_s"]
      ]
    end)
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp contact_contention_resolution_pressure_event(recommendation, contact_id, source_path) do
    source_contact = contact_contention_source_contact(recommendation, contact_id)
    capacity_requirement = contact_contention_capacity_requirement(recommendation, contact_id)

    if stable_id_string?(contact_id) and
         contact_contention_deferred_downlink?(recommendation, source_contact) do
      %{
        "type" => "downlink_completion_gap",
        "scenario_id" => source_contact["scenario_id"] || recommendation["selected_scenario_id"],
        "spacecraft_id" => source_contact["spacecraft_id"] || source_contact["scenario_id"],
        "ground_station_id" =>
          contact_contention_ground_station_id(recommendation, source_contact),
        "required_contacts" => 1,
        "planned_contacts" => 0,
        "required_downlink_mb" => contact_contention_required_downlink_mb(source_contact),
        "planned_downlink_mb" => 0.0,
        "starts_at_s" => activity_raw_start(source_contact) || recommendation["starts_at_s"],
        "ends_at_s" => activity_raw_end(source_contact) || recommendation["ends_at_s"],
        "contact_id" => contact_id,
        "source_activity_id" => contact_id,
        "source_activity_ids" => [contact_id],
        "source_window_id" => contact_contention_source_window_id(source_contact),
        "contention_group_id" => recommendation["group_id"],
        "selected_contact_id" => recommendation["selected_contact_id"],
        "selected_priority" => recommendation["selected_priority"],
        "selected_priority_source" => recommendation["selected_priority_source"],
        "selection_reason" => recommendation["selection_reason"],
        "resolution_selection_rule" => recommendation["resolution_selection_rule"],
        "resolution_priority_override_count" =>
          recommendation["resolution_priority_override_count"],
        "resolution_priority_override_contact_ids" =>
          recommendation["resolution_priority_override_contact_ids"],
        "capacity_pack_group_id" => recommendation["capacity_pack_group_id"],
        "capacity_pack_status" => recommendation["capacity_pack_status"],
        "capacity_pack_capacity_fraction" => recommendation["capacity_pack_capacity_fraction"],
        "capacity_pack_used_fraction" => recommendation["capacity_pack_used_fraction"],
        "capacity_pack_unused_fraction" => recommendation["capacity_pack_unused_fraction"],
        "required_capacity_fraction" => capacity_requirement["required_capacity_fraction"],
        "required_capacity_fraction_source" =>
          capacity_requirement["required_capacity_fraction_source"],
        "review_status" => recommendation["review_status"],
        "approval_status" => recommendation["approval_status"],
        "downlink_completion_sources" =>
          contact_contention_downlink_completion_sources(source_contact),
        "downlink_demand_sources" => contact_contention_downlink_demand_sources(source_contact),
        "derivation_reasons" => contact_contention_pressure_reasons(recommendation),
        "feedback_source" => source_path,
        "feedback_scope" => "contact_contention_resolution",
        "trust_boundary" => contact_contention_trust_boundary(recommendation, source_contact)
      }
      |> compact_map()
    end
  end

  defp contact_contention_capacity_requirement(recommendation, contact_id) do
    recommendation
    |> Map.get("capacity_requirement_rows", [])
    |> List.wrap()
    |> Enum.filter(&is_map/1)
    |> Enum.map(&stringify_keys/1)
    |> Enum.find(%{}, &(contact_allocation_contact_identity(&1) == contact_id))
  end

  defp contact_contention_source_contact(recommendation, contact_id) do
    recommendation
    |> Map.get("source_contact_candidates", [])
    |> List.wrap()
    |> Enum.filter(&is_map/1)
    |> Enum.map(&stringify_keys/1)
    |> Enum.find(%{}, &(contact_allocation_contact_identity(&1) == contact_id))
  end

  defp contact_contention_deferred_downlink?(recommendation, source_contact) do
    downlink_activity?(source_contact) or recommendation["direction"] == "downlink" or
      "downlink" in List.wrap(recommendation["directions"])
  end

  defp contact_contention_ground_station_id(recommendation, source_contact) do
    [
      source_contact["ground_station_id"],
      source_contact["station_id"],
      nested_ground_station_id(source_contact),
      recommendation["ground_station_id"]
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp contact_contention_required_downlink_mb(source_contact) do
    [
      source_contact["required_downlink_mb"],
      source_contact["estimated_throughput_mb"],
      source_contact["planned_throughput_mb"],
      get_in(source_contact, ["throughput_model", "required_downlink_mb"]),
      get_in(source_contact, ["throughput_model", "estimated_throughput_mb"]),
      get_in(source_contact, ["throughput_model", "planned_throughput_mb"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(fn value -> is_number(value) and value > 0.0 end)
  end

  defp contact_contention_source_window_id(source_contact) do
    [
      source_contact["source_window_id"],
      get_in(source_contact, ["source_window", "id"]),
      get_in(source_contact, ["activity_context", "source_window_id"])
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp contact_contention_downlink_demand_sources(source_contact) do
    [
      source_contact["downlink_demand_source"],
      source_contact["downlink_demand_sources"],
      get_in(source_contact, ["throughput_model", "downlink_demand_source"]),
      get_in(source_contact, ["throughput_model", "downlink_demand_sources"]),
      get_in(source_contact, ["activity_context", "downlink_demand_source"]),
      get_in(source_contact, ["activity_context", "downlink_demand_sources"])
    ]
    |> normalize_downlink_source_list()
    |> case do
      [] -> contact_contention_downlink_completion_sources(source_contact)
      sources -> sources
    end
  end

  defp contact_contention_downlink_completion_sources(source_contact) do
    [
      source_contact["downlink_completion_source"],
      source_contact["downlink_completion_sources"],
      get_in(source_contact, ["throughput_model", "downlink_completion_source"]),
      get_in(source_contact, ["throughput_model", "downlink_completion_sources"]),
      get_in(source_contact, ["activity_context", "downlink_completion_source"]),
      get_in(source_contact, ["activity_context", "downlink_completion_sources"])
    ]
    |> normalize_downlink_source_list()
    |> case do
      [] -> nil
      sources -> sources
    end
  end

  defp contact_contention_pressure_reasons(recommendation) do
    [
      "contact_contention_deferred",
      recommendation["selection_reason"],
      recommendation["resolution_selection_rule"],
      recommendation["capacity_pack_status"]
    ]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
  end

  defp contact_contention_trust_boundary(recommendation, source_contact) do
    Map.get(recommendation, "trust_boundary") ||
      get_in(recommendation, ["provenance", "trust_boundary"]) ||
      Map.get(source_contact, "trust_boundary") ||
      get_in(source_contact, ["provenance", "trust_boundary"]) ||
      recommendation["_source_report_trust_boundary"]
  end

  defp contact_allocation_capacity_pack_pressure_branches(row, source_path) do
    row
    |> contact_allocation_capacity_pack_recommendation()
    |> contact_contention_resolution_pressure_branches(source_path)
  end

  defp contact_allocation_capacity_pack_recommendation(row) do
    source_recommendation =
      row
      |> Map.get("source_contention_recommendation", %{})
      |> stringify_keys()

    source_recommendation
    |> put_default_if_present("group_id", row["contention_group_id"] || row["group_id"])
    |> put_default_if_present(
      "contention_group_id",
      row["contention_group_id"] || row["group_id"]
    )
    |> put_default_if_present("ground_station_id", row["ground_station_id"])
    |> put_default_if_present(
      "selected_contact_id",
      first_present_id(row["selected_contact_ids"])
    )
    |> put_default_if_present("deferred_contact_ids", row["deferred_contact_ids"])
    |> put_default_if_present(
      "capacity_pack_group_id",
      row["contention_group_id"] || row["group_id"]
    )
    |> put_default_if_present("capacity_pack_status", row["pack_status"])
    |> put_default_if_present("capacity_pack_capacity_fraction", row["capacity_fraction"])
    |> put_default_if_present("capacity_pack_used_fraction", row["used_capacity_fraction"])
    |> put_default_if_present("capacity_pack_unused_fraction", row["unused_capacity_fraction"])
    |> put_default_if_present("capacity_requirement_rows", row["capacity_requirement_rows"])
    |> put_default_if_present("trust_boundary", row["trust_boundary"])
    |> put_default_if_present("provenance", row["provenance"])
    |> put_default_if_present(
      "_source_report_trust_boundary",
      row["_source_report_trust_boundary"]
    )
  end

  defp first_present_id(values) do
    values
    |> List.wrap()
    |> Enum.find(&stable_id_string?/1)
  end

  defp contact_intent_pressure_branch(row, source_path) do
    event = contact_intent_pressure_event(row, source_path)
    contact_id = contact_intent_contact_id(row)

    if is_nil(event) or contact_id in [nil, ""] do
      []
    else
      [
        %{
          "id" =>
            "derived_contact_intent_pressure_#{branch_id_fragment(contact_intent_pressure_status(row))}_#{branch_id_fragment(contact_id)}",
          "label" => "Derived contact-intent pressure #{contact_id}",
          "events" => [event],
          "metadata" =>
            %{
              "derived_source" => source_path,
              "contact_intent_gate_status" => contact_intent_pressure_status(row),
              "cadence_import_status" => row["cadence_import_status"],
              "contact_approval_status" => row["approval_status"]
            }
            |> compact_map()
        }
      ]
    end
  end

  defp contact_intent_pressure_event(row, source_path) do
    pressure_status = contact_intent_pressure_status(row)

    cond do
      is_nil(pressure_status) ->
        nil

      not downlink_activity?(row) ->
        nil

      true ->
        contact_id = contact_intent_contact_id(row)

        %{
          "type" => "downlink_completion_gap",
          "scenario_id" => row["scenario_id"] || row["spacecraft_id"],
          "spacecraft_id" => row["spacecraft_id"] || row["scenario_id"],
          "ground_station_id" => contact_intent_ground_station_id(row),
          "required_contacts" => 1,
          "planned_contacts" => 0,
          "required_downlink_mb" => contact_intent_required_downlink_mb(row),
          "planned_downlink_mb" => 0.0,
          "starts_at_s" => activity_raw_start(row),
          "ends_at_s" => activity_raw_end(row),
          "contact_id" => contact_id,
          "source_activity_id" => contact_id,
          "source_activity_ids" => List.wrap(contact_id),
          "source_window_id" => row["source_window_id"] || get_in(row, ["source_window", "id"]),
          "timeline_id" => explicit_timeline_id(row),
          "approval_status" => normalized_optional_status(row["approval_status"]),
          "required_operator_action" => row["required_operator_action"],
          "cadence_import_status" => normalized_optional_status(row["cadence_import_status"]),
          "invalid_cadence_import" => row["invalid_cadence_import"],
          "invalid_cadence_import_reason" => row["invalid_cadence_import_reason"],
          "invalid_activity_input" => row["invalid_activity_input"],
          "invalid_activity_input_reason" => row["invalid_activity_input_reason"],
          "contact_intent_gate_status" => pressure_status,
          "policy_classification" => get_in(row, ["source_policy_decision", "classification"]),
          "policy_bundle_id" => get_in(row, ["source_policy_decision", "policy_bundle_id"]),
          "station_availability" => row["station_availability"],
          "station_contention_status" => row["station_contention_status"],
          "station_calendar_entry_id" => row["station_calendar_entry_id"],
          "station_calendar_provider_id" => row["station_calendar_provider_id"],
          "station_calendar_provider_entry_id" => row["station_calendar_provider_entry_id"],
          "station_calendar_directions" => row["station_calendar_directions"],
          "station_calendar_status" => row["station_calendar_status"],
          "station_calendar_trust_boundary_status" =>
            row["station_calendar_trust_boundary_status"],
          "station_reservation_id" => row["station_reservation_id"],
          "station_reserved_by" => row["station_reserved_by"],
          "station_reservation_status" => row["station_reservation_status"],
          "station_reservation_match_status" => row["station_reservation_match_status"],
          "derivation_reasons" => contact_intent_pressure_reasons(row, pressure_status),
          "feedback_source" => source_path,
          "feedback_scope" => "contact_intent",
          "trust_boundary" => contact_intent_trust_boundary(row)
        }
        |> compact_map()
    end
  end

  defp contact_intent_pressure_status(row) do
    approval_status = normalized_optional_status(row["approval_status"])
    cadence_import_status = normalized_optional_status(row["cadence_import_status"])

    cond do
      approval_status == "blocked_by_policy" ->
        "blocked_by_policy"

      cadence_import_status in ["missing", "invalid"] ->
        "cadence_import_#{cadence_import_status}"

      row["invalid_activity_input"] == true ->
        "invalid_activity_input"

      true ->
        nil
    end
  end

  defp normalized_optional_status(nil), do: nil
  defp normalized_optional_status(value), do: normalized_status_token(value)

  defp contact_intent_contact_id(row) do
    row["contact_id"] || row["activity_id"] || row["id"]
  end

  defp contact_intent_ground_station_id(row) do
    [
      row["ground_station_id"],
      row["station_id"],
      nested_ground_station_id(row)
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp contact_intent_required_downlink_mb(row) do
    [
      row["required_downlink_mb"],
      row["estimated_throughput_mb"],
      row["planned_throughput_mb"],
      get_in(row, ["activity_context", "required_downlink_mb"]),
      get_in(row, ["activity_context", "estimated_throughput_mb"]),
      get_in(row, ["activity_context", "planned_throughput_mb"]),
      get_in(row, ["throughput_model", "required_downlink_mb"]),
      get_in(row, ["throughput_model", "estimated_throughput_mb"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(fn value -> is_number(value) and value > 0.0 end)
  end

  defp contact_intent_pressure_reasons(row, pressure_status) do
    [
      "contact_intent_#{pressure_status}",
      row["required_operator_action"],
      row["invalid_cadence_import_reason"],
      row["invalid_activity_input_reason"],
      row["station_availability"],
      row["station_calendar_status"],
      row["station_reservation_match_status"],
      get_in(row, ["source_policy_decision", "classification"])
    ]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
  end

  defp contact_intent_trust_boundary(row) do
    Map.get(row, "trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      get_in(row, ["source_contact_intent", "trust_boundary"]) ||
      get_in(row, ["source_contact_intent", "provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp direct_contact_intent_pressure_row(row) do
    row = stringify_keys(row)

    row
    |> contact_intent_review_row(row)
    |> put_default_if_present("source_policy_decision", row["policy_decision"])
    |> put_default_if_present("cadence_import_status", nested_cadence_import_status(row))
  end

  defp nested_cadence_import_status(row) do
    case Map.get(row, "cadence_import") do
      %{} = cadence_import ->
        cadence_import
        |> stringify_keys()
        |> Map.get("status")
        |> normalized_optional_status()

      _cadence_import ->
        nil
    end
  end

  defp contact_allocation_pressure_branch(row, source_path) do
    row = normalize_contact_allocation_row(row)

    contact_allocation_completion_pressure_branch(row, source_path) ++
      contact_allocation_provider_reservation_pressure_branch(row, source_path) ++
      contact_allocation_contact_filter_pressure_branches(row, source_path) ++
      contact_allocation_resource_filter_pressure_branches(row, source_path)
  end

  defp contact_allocation_completion_pressure_branch(row, source_path) do
    event = contact_allocation_pressure_event(row, source_path)
    contact_id = Map.get(row, "contact_id")

    if is_nil(event) or contact_id in [nil, ""] do
      []
    else
      status =
        row
        |> contact_allocation_effective_status()
        |> branch_id_fragment()

      [
        %{
          "id" =>
            "derived_contact_allocation_pressure_#{status}_#{branch_id_fragment(contact_id)}",
          "label" => "Derived contact allocation pressure #{contact_id}",
          "events" => [event],
          "metadata" =>
            %{
              "derived_source" => source_path,
              "contact_allocation_status" => row["allocation_status"],
              "contact_effective_allocation_status" => row["effective_allocation_status"],
              "contact_allocation_reason" => row["allocation_reason"],
              "contact_review_status" => row["review_status"],
              "contact_approval_status" => row["approval_status"],
              "capacity_pack_group_id" => row["capacity_pack_group_id"],
              "capacity_pack_status" => row["capacity_pack_status"],
              "capacity_pack_capacity_fraction" => row["capacity_pack_capacity_fraction"],
              "capacity_pack_used_fraction" => row["capacity_pack_used_fraction"],
              "contact_policy_classification" =>
                get_in(row, ["policy_decision", "classification"])
            }
            |> compact_map()
        }
      ]
    end
  end

  defp disambiguate_contact_allocation_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if contact_allocation_pressure_branch_id?(branch_id) and
           Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> contact_allocation_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("contact_allocation_branch_base_id", branch_id)
          |> Map.put("contact_allocation_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_contact_allocation_suffixes()
  end

  defp contact_allocation_pressure_branch_id?(id) when is_binary(id),
    do: String.starts_with?(id, "derived_contact_allocation_pressure_")

  defp contact_allocation_pressure_branch_id?(_id), do: false

  defp disambiguate_duplicate_contact_allocation_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "contact_allocation_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["contact_allocation_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["contact_allocation_branch_base_id"]}_#{suffix}")
        |> Map.update(
          "metadata",
          %{},
          &Map.put(&1, "contact_allocation_branch_identity", suffix)
        )
      else
        branch
      end
    end)
  end

  defp contact_allocation_pressure_branch_identity(branch, index) do
    branch
    |> Map.get("events", [])
    |> List.wrap()
    |> Enum.flat_map(fn event ->
      [
        event["source_window_id"],
        event["source_window_ids"],
        event["source_activity_id"],
        event["source_activity_ids"],
        event["downlink_completion_source"],
        event["downlink_completion_sources"],
        event["downlink_demand_source"],
        event["downlink_demand_sources"],
        event["ground_station_id"],
        event["station_reservation_id"],
        event["station_reserved_by"],
        event["station_reservation_status"],
        event["station_reservation_match_status"],
        event["station_calendar_entry_id"],
        event["station_calendar_entry_status"],
        event["feedback_source"],
        event["required_downlink_mb"],
        event["starts_at_s"],
        event["ends_at_s"]
      ]
    end)
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp contact_allocation_provider_reservation_pressure_branch(row, source_path) do
    event = contact_allocation_provider_reservation_pressure_event(row, source_path)
    contact_id = Map.get(row, "contact_id")

    if is_nil(event) or contact_id in [nil, ""] do
      []
    else
      status =
        event
        |> Map.get("provider_reservation_request_status", "review_required")
        |> branch_id_fragment()

      [
        %{
          "id" =>
            "derived_contact_allocation_pressure_provider_reservation_#{status}_#{branch_id_fragment(contact_id)}",
          "label" => "Derived provider reservation request pressure #{contact_id}",
          "events" => [event],
          "metadata" =>
            %{
              "derived_source" => source_path,
              "contact_id" => contact_id,
              "provider_reservation_request_status" =>
                event["provider_reservation_request_status"],
              "provider_reservation_row_scope" => event["provider_reservation_row_scope"],
              "station_reservation_id" => event["station_reservation_id"],
              "station_reservation_match_status" => event["station_reservation_match_status"]
            }
            |> compact_map()
        }
      ]
    end
  end

  defp contact_allocation_provider_reservation_pressure_event(row, source_path) do
    row_scope = row["_provider_reservation_row_scope"]
    request_status = normalized_status_token(row["_provider_reservation_request_status"])
    match_status = normalized_status_token(row["station_reservation_match_status"])

    cond do
      row_scope not in ["request", "review"] ->
        nil

      not contact_allocation_provider_reservation_pressure?(
        row_scope,
        request_status,
        match_status
      ) ->
        nil

      true ->
        contact_id = row["contact_id"]

        %{
          "type" => "provider_reservation_request_pressure",
          "contact_id" => contact_id,
          "source_activity_id" => contact_id,
          "source_activity_ids" => List.wrap(contact_id),
          "ground_station_id" => row["ground_station_id"] || row["station_id"],
          "direction" => row["direction"],
          "station_reservation_id" => row["station_reservation_id"],
          "station_reserved_by" => row["station_reserved_by"],
          "station_reservation_status" =>
            normalized_status_token(row["station_reservation_status"]),
          "station_reservation_match_status" => match_status,
          "provider_reservation_request_status" => request_status,
          "provider_reservation_row_scope" => row_scope,
          "required_operator_action" =>
            row["required_operator_action"] || "review_provider_reservation_request",
          "derivation_reasons" =>
            contact_allocation_provider_reservation_pressure_reasons(
              row_scope,
              request_status,
              match_status
            ),
          "feedback_source" => source_path,
          "feedback_scope" => "contact_allocation_provider_reservation_request",
          "trust_boundary" => contact_allocation_trust_boundary(row),
          "assumptions" => %{
            "provider_reservation_execution" => "not_performed_by_strategy_branch",
            "schedule_mutation" => "not_performed_by_strategy_branch",
            "operator_authority" => "not_granted_by_strategy_branch"
          }
        }
        |> compact_map()
    end
  end

  defp contact_allocation_provider_reservation_pressure?(
         "review",
         _request_status,
         _match_status
       ),
       do: true

  defp contact_allocation_provider_reservation_pressure?(
         "request",
         _request_status,
         match_status
       ),
       do: match_status in ["overlap", "conflict", "unmatched", "owner_mismatch"]

  defp contact_allocation_provider_reservation_pressure?(
         _row_scope,
         _request_status,
         _match_status
       ),
       do: false

  defp contact_allocation_provider_reservation_pressure_reasons(
         row_scope,
         request_status,
         match_status
       ) do
    [
      "provider_reservation_#{row_scope}",
      request_status && "provider_reservation_#{request_status}",
      match_status && "provider_reservation_match_#{match_status}"
    ]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
  end

  defp contact_allocation_resource_filter_pressure_branches(
         %{"source_resource_suppression" => %{} = source} = row,
         source_path
       )
       when map_size(source) > 0 do
    source
    |> stringify_keys()
    |> put_contact_allocation_resource_suppression_fallbacks(row)
    |> Map.put_new("approval_status", row["approval_status"])
    |> Map.put("_source_report_trust_boundary", contact_allocation_trust_boundary(row))
    |> resource_filter_pressure_branch("#{source_path}.source_resource_suppression")
  end

  defp contact_allocation_resource_filter_pressure_branches(_row, _source_path), do: []

  defp contact_allocation_contact_filter_pressure_branches(
         %{"source_contact_suppression" => %{} = source} = row,
         source_path
       )
       when map_size(source) > 0 do
    source
    |> stringify_keys()
    |> put_contact_allocation_contact_suppression_fallbacks(row)
    |> Map.put_new("approval_status", row["approval_status"])
    |> Map.put("_source_report_trust_boundary", contact_allocation_trust_boundary(row))
    |> contact_filter_pressure_branch("#{source_path}.source_contact_suppression")
  end

  defp contact_allocation_contact_filter_pressure_branches(_row, _source_path), do: []

  defp put_contact_allocation_contact_suppression_fallbacks(source, row) do
    source
    |> put_if_absent("id", row["contact_id"])
    |> put_if_absent("contact_id", row["contact_id"])
    |> put_if_absent("activity_id", row["activity_id"])
    |> put_if_absent("type", row["type"])
    |> put_if_absent("activity_type", row["activity_type"])
    |> put_if_absent("direction", row["direction"])
    |> put_if_absent("scenario_id", row["scenario_id"])
    |> put_if_absent("spacecraft_id", row["spacecraft_id"])
    |> put_if_absent("ground_station_id", row["ground_station_id"] || row["station_id"])
    |> put_if_absent("starts_at_s", row["starts_at_s"] || row["start_s"])
    |> put_if_absent("ends_at_s", row["ends_at_s"] || row["end_s"])
    |> put_if_absent("suppressed_reason", row["suppressed_reason"])
    |> put_if_absent("station_reservation_id", row["station_reservation_id"])
    |> put_if_absent("station_reserved_by", row["station_reserved_by"])
    |> put_if_absent("station_reservation_status", row["station_reservation_status"])
    |> put_if_absent(
      "station_reservation_match_status",
      row["station_reservation_match_status"]
    )
    |> put_if_absent("station_calendar_entry_status", row["station_calendar_entry_status"])
    |> put_if_absent("station_calendar_entry_id", row["station_calendar_entry_id"])
    |> put_if_absent("required_downlink_mb", row["required_downlink_mb"])
    |> put_if_absent("estimated_throughput_mb", row["estimated_throughput_mb"])
    |> put_if_absent("planned_throughput_mb", row["planned_throughput_mb"])
    |> put_if_absent("throughput_model", row["throughput_model"])
    |> put_if_absent("activity_context", row["activity_context"])
    |> put_if_absent("source_window_id", row["source_window_id"])
    |> put_if_absent("source_window", row["source_window"])
  end

  defp put_contact_allocation_resource_suppression_fallbacks(source, row) do
    source
    |> put_if_absent("id", row["contact_id"])
    |> put_if_absent("contact_id", row["contact_id"])
    |> put_if_absent("activity_id", row["activity_id"])
    |> put_if_absent("type", row["type"])
    |> put_if_absent("activity_type", row["activity_type"])
    |> put_if_absent("direction", row["direction"])
    |> put_if_absent("scenario_id", row["scenario_id"])
    |> put_if_absent("spacecraft_id", row["spacecraft_id"])
    |> put_if_absent("ground_station_id", row["ground_station_id"] || row["station_id"])
    |> put_if_absent("starts_at_s", row["starts_at_s"] || row["start_s"])
    |> put_if_absent("ends_at_s", row["ends_at_s"] || row["end_s"])
    |> put_if_absent("suppressed_reason", row["suppressed_reason"])
    |> put_if_absent("resource_source_quality", row["resource_source_quality"])
    |> put_if_absent("resource_trust_boundary", row["resource_trust_boundary"])
    |> put_if_absent("resource_trust_boundary_status", row["resource_trust_boundary_status"])
    |> put_if_absent("fuel_margin", row["fuel_margin"])
    |> put_if_absent("power_margin", row["power_margin"])
    |> put_if_absent("storage_margin", row["storage_margin"])
    |> put_if_absent("downlink_margin", row["downlink_margin"])
    |> put_if_absent("thermal_margin_c", row["thermal_margin_c"])
    |> put_if_absent("spacecraft_available", row["spacecraft_available"])
    |> put_if_absent("payload_available", row["payload_available"])
    |> put_if_absent("antenna_available", row["antenna_available"])
    |> put_if_absent("source_resource_summary", row["source_resource_summary"])
  end

  defp normalize_contact_allocation_row(row) do
    row
    |> normalize_contact_allocation_status_field("allocation_status")
    |> normalize_contact_allocation_status_field("effective_allocation_status")
    |> normalize_contact_allocation_status_field("review_status")
    |> normalize_contact_allocation_status_field("approval_status")
    |> normalize_contact_allocation_policy_decision()
  end

  defp normalize_contact_allocation_status_field(row, field) do
    case Map.get(row, field) do
      value when value in [nil, ""] -> row
      value -> Map.put(row, field, normalized_status_token(value))
    end
  end

  defp normalize_contact_allocation_policy_decision(%{"policy_decision" => %{} = decision} = row) do
    decision =
      decision
      |> stringify_keys()
      |> normalize_contact_allocation_status_field("classification")

    Map.put(row, "policy_decision", decision)
  end

  defp normalize_contact_allocation_policy_decision(row), do: row

  defp normalized_status_token(nil), do: nil

  defp normalized_status_token(status) when is_atom(status) do
    status
    |> Atom.to_string()
    |> normalized_status_token()
  end

  defp normalized_status_token(status) when is_binary(status) do
    status
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
  end

  defp normalized_status_token(status), do: status

  defp contact_allocation_pressure_event(row, source_path) do
    status = contact_allocation_effective_status(row)

    cond do
      status not in ["deferred", "blocked", "policy_blocked"] ->
        nil

      not downlink_allocation_row?(row) ->
        nil

      true ->
        source_contact = contact_allocation_source_contact(row)
        required_downlink_mb = contact_allocation_required_downlink_mb(row, source_contact)
        contact_id = row["contact_id"]
        ground_station_id = contact_allocation_ground_station_id(row, source_contact)

        %{
          "type" => "downlink_completion_gap",
          "scenario_id" => row["scenario_id"] || row["spacecraft_id"],
          "spacecraft_id" => row["spacecraft_id"] || row["scenario_id"],
          "ground_station_id" => ground_station_id,
          "required_contacts" => 1,
          "planned_contacts" => 0,
          "required_downlink_mb" => required_downlink_mb,
          "planned_downlink_mb" => 0.0,
          "starts_at_s" => contact_allocation_start_s(row, source_contact),
          "ends_at_s" => contact_allocation_end_s(row, source_contact),
          "contact_id" => contact_id,
          "source_activity_id" => contact_id,
          "source_activity_ids" => List.wrap(contact_id),
          "source_window_id" => contact_allocation_source_window_id(row, source_contact),
          "realized_status" => status,
          "contact_result" => row["allocation_reason"],
          "allocation_status" => row["allocation_status"],
          "effective_allocation_status" => row["effective_allocation_status"],
          "allocation_reason" => row["allocation_reason"],
          "capacity_pack_group_id" => row["capacity_pack_group_id"],
          "capacity_pack_status" => row["capacity_pack_status"],
          "capacity_pack_capacity_fraction" => row["capacity_pack_capacity_fraction"],
          "capacity_pack_used_fraction" => row["capacity_pack_used_fraction"],
          "station_reservation_id" =>
            row["station_reservation_id"] || source_contact["station_reservation_id"],
          "station_reserved_by" =>
            row["station_reserved_by"] || source_contact["station_reserved_by"],
          "station_reservation_status" =>
            row["station_reservation_status"] || source_contact["station_reservation_status"],
          "station_reservation_match_status" =>
            row["station_reservation_match_status"] ||
              source_contact["station_reservation_match_status"],
          "station_calendar_entry_id" =>
            row["station_calendar_entry_id"] || source_contact["station_calendar_entry_id"],
          "station_calendar_entry_status" =>
            row["station_calendar_entry_status"] ||
              source_contact["station_calendar_entry_status"],
          "station_calendar_directions" =>
            row["station_calendar_directions"] || source_contact["station_calendar_directions"],
          "review_status" => row["review_status"],
          "approval_status" => row["approval_status"],
          "policy_decision" => row["policy_decision"],
          "policy_classification" => get_in(row, ["policy_decision", "classification"]),
          "policy_bundle_id" => get_in(row, ["policy_decision", "policy_bundle_id"]),
          "downlink_completion_source" =>
            row["downlink_completion_source"] ||
              source_contact["downlink_completion_source"] ||
              get_in(source_contact, ["throughput_model", "downlink_completion_source"]) ||
              get_in(source_contact, ["activity_context", "downlink_completion_source"]),
          "downlink_demand_sources" =>
            contact_allocation_downlink_demand_sources(row, source_contact),
          "downlink_completion_sources" =>
            contact_allocation_downlink_completion_sources(row, source_contact),
          "derivation_reasons" => contact_allocation_pressure_reasons(row, status),
          "feedback_source" => source_path,
          "feedback_scope" => "contact_allocation",
          "trust_boundary" => contact_allocation_trust_boundary(row)
        }
        |> compact_map()
    end
  end

  defp contact_allocation_ground_station_id(row, source_contact) do
    [
      row["ground_station_id"],
      row["station_id"],
      nested_ground_station_id(row),
      source_contact["ground_station_id"],
      source_contact["station_id"],
      nested_ground_station_id(source_contact)
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp contact_allocation_start_s(row, source_contact) do
    activity_raw_start(row) || activity_raw_start(source_contact)
  end

  defp contact_allocation_end_s(row, source_contact) do
    activity_raw_end(row) || activity_raw_end(source_contact)
  end

  defp contact_allocation_source_window_id(row, source_contact) do
    [
      row["source_window_id"],
      get_in(row, ["source_window", "id"]),
      get_in(row, ["activity_context", "source_window_id"]),
      source_contact["source_window_id"],
      get_in(source_contact, ["source_window", "id"]),
      get_in(source_contact, ["activity_context", "source_window_id"])
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp contact_allocation_effective_status(row) do
    Map.get(row, "effective_allocation_status") || Map.get(row, "allocation_status")
  end

  defp downlink_allocation_row?(row) do
    downlink_activity?(row) or downlink_activity?(contact_allocation_source_contact(row))
  end

  defp contact_allocation_source_contact(row) do
    contact_id = row["contact_id"]

    cond do
      is_map(row["source_contact_candidate"]) ->
        stringify_keys(row["source_contact_candidate"])

      source_contact = contact_allocation_direct_source_contact(row, contact_id) ->
        source_contact

      is_list(get_in(row, ["source_contention_recommendation", "source_contact_candidates"])) ->
        row
        |> get_in(["source_contention_recommendation", "source_contact_candidates"])
        |> Enum.map(&stringify_keys/1)
        |> Enum.find(%{}, &contact_allocation_contact_match?(&1, contact_id))

      true ->
        %{}
    end
  end

  defp contact_allocation_direct_source_contact(row, contact_id) do
    [
      row["source_contact"],
      row["contact_candidate"],
      row["contact"],
      row["source_contacts"],
      row["contact_candidates"],
      row["contacts"]
    ]
    |> List.flatten()
    |> Enum.filter(&is_map/1)
    |> Enum.map(&stringify_keys/1)
    |> Enum.find(&contact_allocation_contact_match?(&1, contact_id))
  end

  defp contact_allocation_contact_match?(contact, contact_id) do
    contact_id in [nil, ""] or contact_allocation_contact_identity(contact) == contact_id
  end

  defp contact_allocation_contact_identity(contact) do
    Map.get(contact, "id") || Map.get(contact, "contact_id") ||
      Map.get(contact, "activity_id") || Map.get(contact, "source_activity_id") ||
      Map.get(contact, "downlink_activity_id")
  end

  defp contact_allocation_required_downlink_mb(row, source_contact) do
    [
      row["required_downlink_mb"],
      row["estimated_throughput_mb"],
      row["planned_throughput_mb"],
      get_in(row, ["throughput_model", "required_downlink_mb"]),
      get_in(row, ["throughput_model", "estimated_throughput_mb"]),
      get_in(row, ["throughput_model", "planned_throughput_mb"]),
      source_contact["required_downlink_mb"],
      source_contact["estimated_throughput_mb"],
      source_contact["planned_throughput_mb"],
      get_in(source_contact, ["throughput_model", "required_downlink_mb"]),
      get_in(source_contact, ["throughput_model", "estimated_throughput_mb"]),
      get_in(source_contact, ["throughput_model", "planned_throughput_mb"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(fn value -> is_number(value) and value > 0.0 end)
  end

  defp contact_allocation_downlink_demand_sources(row, source_contact) do
    [
      row["downlink_demand_source"],
      row["downlink_demand_sources"],
      get_in(row, ["throughput_model", "downlink_demand_source"]),
      get_in(row, ["throughput_model", "downlink_demand_sources"]),
      get_in(row, ["activity_context", "downlink_demand_source"]),
      get_in(row, ["activity_context", "downlink_demand_sources"]),
      source_contact["downlink_demand_source"],
      source_contact["downlink_demand_sources"],
      get_in(source_contact, ["throughput_model", "downlink_demand_source"]),
      get_in(source_contact, ["throughput_model", "downlink_demand_sources"]),
      get_in(source_contact, ["activity_context", "downlink_demand_source"]),
      get_in(source_contact, ["activity_context", "downlink_demand_sources"])
    ]
    |> normalize_downlink_source_list()
    |> case do
      [] -> contact_allocation_downlink_completion_sources(row, source_contact)
      sources -> sources
    end
  end

  defp contact_allocation_downlink_completion_sources(row, source_contact) do
    [
      row["downlink_completion_source"],
      row["downlink_completion_sources"],
      get_in(row, ["throughput_model", "downlink_completion_source"]),
      get_in(row, ["throughput_model", "downlink_completion_sources"]),
      get_in(row, ["activity_context", "downlink_completion_source"]),
      get_in(row, ["activity_context", "downlink_completion_sources"]),
      source_contact["downlink_completion_source"],
      source_contact["downlink_completion_sources"],
      get_in(source_contact, ["throughput_model", "downlink_completion_source"]),
      get_in(source_contact, ["throughput_model", "downlink_completion_sources"]),
      get_in(source_contact, ["activity_context", "downlink_completion_source"]),
      get_in(source_contact, ["activity_context", "downlink_completion_sources"])
    ]
    |> normalize_downlink_source_list()
    |> case do
      [] -> nil
      sources -> sources
    end
  end

  defp contact_allocation_pressure_reasons(row, status) do
    [
      "contact_allocation_#{status}",
      row["allocation_reason"],
      row["capacity_pack_status"],
      row["suppressed_reason"],
      row["station_reservation_match_status"],
      row["station_calendar_entry_status"]
    ]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
  end

  defp contact_allocation_trust_boundary(row) do
    Map.get(row, "trust_boundary") ||
      Map.get(row, "resource_trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      get_in(row, ["source_resource_suppression", "resource_trust_boundary"]) ||
      get_in(row, ["source_resource_suppression", "resource_provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp derived_link_capacity_pressure_branches(prior_plan) do
    prior_plan
    |> prior_plan_link_capacity_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> link_capacity_pressure_rows()
      |> Enum.map(&Map.put(&1, "_source_report_trust_boundary", trust_boundary))
      |> Enum.flat_map(&link_capacity_pressure_branch(&1, source_path))
    end)
    |> disambiguate_link_capacity_pressure_branch_ids()
  end

  defp prior_plan_link_capacity_reports(prior_plan) do
    direct_reports =
      [
        {"source_link_capacity_report", "prior_plan.source_link_capacity_report"},
        {"link_capacity_report", "prior_plan.link_capacity_report"},
        {"source_relay_data_path_summary", "prior_plan.source_relay_data_path_summary"},
        {"relay_data_path_summary", "prior_plan.relay_data_path_summary"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        case Map.get(prior_plan, field) do
          %{} = report -> [{stringify_keys(report), source_path}]
          _report -> []
        end
      end)

    direct_reports ++ prior_plan_result_artifact_link_capacity_reports(prior_plan)
  end

  defp derived_mission_state_link_capacity_pressure_branches(mission_state) do
    mission_state
    |> mission_state_link_capacity_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> link_capacity_pressure_rows()
      |> Enum.map(&Map.put(&1, "_source_report_trust_boundary", trust_boundary))
      |> Enum.flat_map(&link_capacity_pressure_branch(&1, source_path))
    end)
    |> disambiguate_link_capacity_pressure_branch_ids()
  end

  defp mission_state_link_capacity_reports(mission_state) do
    mission_state = stringify_keys(mission_state || %{})

    mission_state_link_capacity_reports(mission_state, [
      {"source_link_capacity_report", "mission_state.source_link_capacity_report"},
      {"link_capacity_report", "mission_state.link_capacity_report"},
      {"source_relay_data_path_summary", "mission_state.source_relay_data_path_summary"},
      {"relay_data_path_summary", "mission_state.relay_data_path_summary"}
    ]) ++
      mission_state_result_artifact_embedded_reports(mission_state, "source_link_capacity_report") ++
      mission_state_result_artifact_embedded_reports(mission_state, "link_capacity_report") ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "source_relay_data_path_summary"
      ) ++
      mission_state_result_artifact_embedded_reports(mission_state, "relay_data_path_summary")
  end

  defp mission_state_source_link_capacity_reports(mission_state) do
    mission_state_link_capacity_reports(mission_state, [
      {"source_link_capacity_report", "mission_state.source_link_capacity_report"}
    ])
  end

  defp mission_state_canonical_link_capacity_reports(mission_state) do
    mission_state_link_capacity_reports(mission_state, [
      {"link_capacity_report", "mission_state.link_capacity_report"}
    ])
  end

  defp mission_state_link_capacity_reports(mission_state, fields) do
    mission_state = stringify_keys(mission_state || %{})

    fields
    |> Enum.flat_map(fn {field, source_path} ->
      mission_state
      |> Map.get(field)
      |> mission_state_source_report_entries(source_path)
    end)
  end

  defp mission_state_source_link_capacity_summaries(mission_state) do
    mission_state_link_capacity_summaries(mission_state, [
      {"source_link_capacity_summary", "mission_state.source_link_capacity_summary"}
    ])
  end

  defp mission_state_canonical_link_capacity_summaries(mission_state) do
    mission_state_link_capacity_summaries(mission_state, [
      {"link_capacity_summary", "mission_state.link_capacity_summary"}
    ])
  end

  defp mission_state_link_capacity_summaries(mission_state, fields) do
    mission_state = stringify_keys(mission_state || %{})

    fields
    |> Enum.flat_map(fn {field, source_path} ->
      mission_state
      |> Map.get(field)
      |> mission_state_source_report_entries(source_path)
    end)
  end

  defp prior_plan_result_artifact_link_capacity_reports(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      [
        "source_link_capacity_report",
        "link_capacity_report",
        "source_relay_data_path_summary",
        "relay_data_path_summary"
      ]
      |> Enum.flat_map(fn report_key ->
        case Map.get(artifact, report_key) do
          %{} = report ->
            report =
              report
              |> stringify_keys()
              |> put_inherited_result_artifact_trust_boundary(artifact)

            [{report, "#{source_path}.#{report_key}"}]

          _report ->
            []
        end
      end)
    end)
  end

  defp link_capacity_pressure_rows(%{"rows" => rows} = report) when is_list(rows) do
    if relay_data_path_summary_source?(report) do
      relay_data_path_pressure_rows(report)
    else
      rows =
        rows
        |> Enum.map(&stringify_keys/1)
        |> Enum.map(&Map.put_new(&1, "source_report", "rows"))

      if Enum.any?(rows, &link_capacity_pressure_row?/1) do
        rows
      else
        [Map.put(report, "source_report", "top_level")]
      end
    end
  end

  defp link_capacity_pressure_rows(%{} = report) do
    if relay_data_path_summary_source?(report) do
      relay_data_path_pressure_rows(report)
    else
      [Map.put(report, "source_report", "top_level")]
    end
  end

  defp relay_data_path_pressure_rows(%{} = report) do
    report = stringify_keys(report)

    rows =
      report
      |> Map.get("rows", [])
      |> List.wrap()
      |> Enum.map(&stringify_keys/1)
      |> Enum.filter(&relay_data_path_pressure_row?/1)
      |> Enum.map(&relay_data_path_pressure_row(&1, report))

    if rows == [] and relay_data_path_pressure_row?(report) do
      [relay_data_path_pressure_row(report, report)]
    else
      rows
    end
  end

  defp relay_data_path_pressure_row(row, report) do
    row
    |> Map.put_new("source_report", "relay_data_path_summary.rows")
    |> Map.put("_relay_data_path_summary", true)
    |> Map.put("_relay_data_path_summary_assumptions", Map.get(report, "assumptions"))
    |> Map.put("_relay_data_path_summary_route_count", Map.get(report, "route_count"))
    |> Map.put("_relay_data_path_summary_relay_route_count", Map.get(report, "relay_route_count"))
    |> Map.put(
      "_relay_data_path_summary_direct_downlink_route_count",
      Map.get(report, "direct_downlink_route_count")
    )
    |> Map.put(
      "_relay_data_path_summary_custody_status_counts",
      Map.get(report, "custody_status_counts")
    )
    |> Map.put(
      "_relay_data_path_summary_latency_status_counts",
      Map.get(report, "latency_status_counts")
    )
    |> Map.put(
      "_relay_data_path_summary_risk_status_counts",
      Map.get(report, "risk_status_counts")
    )
    |> Map.put(
      "_relay_data_path_summary_route_ids_by_custody_status",
      Map.get(report, "route_ids_by_custody_status")
    )
    |> Map.put(
      "_relay_data_path_summary_route_ids_by_latency_status",
      Map.get(report, "route_ids_by_latency_status")
    )
    |> Map.put(
      "_relay_data_path_summary_route_ids_by_risk_status",
      Map.get(report, "route_ids_by_risk_status")
    )
    |> Map.put(
      "_relay_data_path_summary_route_ids_by_ground_station_id",
      Map.get(report, "route_ids_by_ground_station_id")
    )
  end

  defp relay_data_path_summary_source?(%{} = report) do
    Map.get(report, "schema_contract") == "relay_data_path_summary.v1" or
      Map.get(report, "source_summary_schema_contract") == "relay_data_path_summary.v1" or
      Map.get(report, "model") == "artifact_only_relay_data_path_summary" or
      Map.get(report, "source_summary_model") == "artifact_only_relay_data_path_summary"
  end

  defp link_capacity_pressure_branch(row, source_path) do
    event = link_capacity_pressure_event(row, source_path)

    if is_nil(event) do
      []
    else
      station_id = link_capacity_pressure_ground_station_id(row) || "all_stations"

      [
        %{
          "id" => "derived_link_capacity_pressure_#{branch_id_fragment(station_id)}",
          "label" => "Derived link capacity pressure #{station_id}",
          "events" => [event],
          "metadata" =>
            %{
              "derived_source" => source_path,
              "link_capacity_source_report" => row["source_report"],
              "downlink_requirement_status" => row["downlink_requirement_status"],
              "actual_downlink_completion_ratio" => row["actual_downlink_completion_ratio"],
              "actual_downlink_requirement_status" => row["actual_downlink_requirement_status"]
            }
            |> compact_map()
        }
      ]
    end
  end

  defp disambiguate_link_capacity_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if Map.get(id_counts, branch_id, 0) <= 1 do
        branch
      else
        suffix =
          branch
          |> link_capacity_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("link_capacity_branch_base_id", branch_id)
          |> Map.put("link_capacity_branch_identity", suffix)
        end)
      end
    end)
  end

  defp link_capacity_pressure_branch_identity(branch, index) do
    event = branch |> Map.get("events", []) |> List.wrap() |> List.first() || %{}

    [
      event["source_window_id"],
      event["source_window_ids"],
      event["source_activity_ids"],
      event["route_id"],
      event["ground_downlink_contact_id"],
      event["downlink_completion_source"],
      event["downlink_completion_sources"],
      event["required_downlink_mb"],
      index
    ]
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.find(&stable_id_string?/1)
  end

  defp link_capacity_pressure_event(%{"_relay_data_path_summary" => true} = row, source_path) do
    %{
      "type" => "relay_data_path_pressure",
      "ground_station_id" => link_capacity_pressure_ground_station_id(row),
      "route_id" => row["route_id"],
      "route_ids" => relay_data_path_pressure_route_ids(row),
      "source_spacecraft_id" => row["source_spacecraft_id"],
      "source_spacecraft_ids" => relay_data_path_pressure_source_spacecraft_ids(row),
      "relay_spacecraft_ids" => relay_data_path_pressure_relay_spacecraft_ids(row),
      "relay_chain_spacecraft_ids" => relay_data_path_pressure_relay_chain_spacecraft_ids(row),
      "relay_hop_count" => numeric_or_nil(row["relay_hop_count"]),
      "ground_downlink_contact_id" => row["ground_downlink_contact_id"],
      "ground_downlink_contact_ids" => relay_data_path_pressure_ground_downlink_contact_ids(row),
      "custody_status" => row["custody_status"],
      "latency_s" => numeric_or_nil(row["latency_s"]),
      "latency_limit_s" => numeric_or_nil(row["latency_limit_s"]),
      "latency_status" => row["latency_status"],
      "risk_status" => row["risk_status"],
      "risk_reasons" => relay_data_path_pressure_risk_reasons(row),
      "product_ids" => relay_data_path_pressure_values(row, ["product_id", "product_ids"]),
      "collection_ids" =>
        relay_data_path_pressure_values(row, ["collection_id", "collection_ids"]),
      "route_count" => numeric_or_nil(row["_relay_data_path_summary_route_count"]),
      "relay_route_count" => numeric_or_nil(row["_relay_data_path_summary_relay_route_count"]),
      "direct_downlink_route_count" =>
        numeric_or_nil(row["_relay_data_path_summary_direct_downlink_route_count"]),
      "custody_status_counts" => row["_relay_data_path_summary_custody_status_counts"],
      "latency_status_counts" => row["_relay_data_path_summary_latency_status_counts"],
      "risk_status_counts" => row["_relay_data_path_summary_risk_status_counts"],
      "route_ids_by_custody_status" =>
        row["_relay_data_path_summary_route_ids_by_custody_status"],
      "route_ids_by_latency_status" =>
        row["_relay_data_path_summary_route_ids_by_latency_status"],
      "route_ids_by_risk_status" => row["_relay_data_path_summary_route_ids_by_risk_status"],
      "route_ids_by_ground_station_id" =>
        row["_relay_data_path_summary_route_ids_by_ground_station_id"],
      "derivation_reasons" => relay_data_path_pressure_reasons(row),
      "feedback_source" => source_path,
      "feedback_scope" => "link_capacity",
      "feedback_key" => row["route_id"] || row["ground_downlink_contact_id"],
      "trust_boundary" => link_capacity_pressure_trust_boundary(row),
      "assumptions" => row["_relay_data_path_summary_assumptions"]
    }
    |> compact_map()
  end

  defp link_capacity_pressure_event(row, source_path) do
    shortfall = link_capacity_pressure_shortfall_mb(row)

    if not (is_number(shortfall) and shortfall > 0.0) do
      nil
    else
      ground_station_id = link_capacity_pressure_ground_station_id(row)

      %{
        "type" => "downlink_completion_gap",
        "ground_station_id" => ground_station_id,
        "required_contacts" => 1,
        "planned_contacts" => link_capacity_pressure_planned_contacts(row),
        "required_downlink_mb" => shortfall,
        "planned_downlink_mb" => 0.0,
        "starts_at_s" => link_capacity_pressure_start_s(row),
        "ends_at_s" => link_capacity_pressure_end_s(row),
        "source_activity_ids" => link_capacity_pressure_source_contact_ids(row),
        "source_window_id" => link_capacity_pressure_source_window_id(row),
        "source_window_ids" => link_capacity_pressure_source_window_ids(row),
        "derivation_reasons" => link_capacity_pressure_reasons(row),
        "feedback_source" => source_path,
        "feedback_scope" => "link_capacity",
        "trust_boundary" => link_capacity_pressure_trust_boundary(row),
        "selected_capacity_adjusted_throughput_mb" =>
          row["selected_capacity_adjusted_throughput_mb"],
        "selected_downlink_shortfall_mb" => row["selected_downlink_shortfall_mb"],
        "actual_throughput_mb" => row["actual_throughput_mb"],
        "actual_downlink_completion_ratio" => row["actual_downlink_completion_ratio"],
        "actual_downlink_shortfall_mb" => row["actual_downlink_shortfall_mb"],
        "downlink_requirement_status" => row["downlink_requirement_status"],
        "actual_downlink_requirement_status" => row["actual_downlink_requirement_status"],
        "downlink_completion_source" => row["downlink_completion_source"],
        "downlink_demand_sources" => link_capacity_pressure_downlink_demand_sources(row),
        "downlink_completion_sources" => link_capacity_pressure_downlink_completion_sources(row)
      }
      |> compact_map()
    end
  end

  defp link_capacity_pressure_ground_station_id(row) do
    [
      row["ground_station_id"],
      row["station_id"],
      nested_ground_station_id(row)
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp link_capacity_pressure_start_s(row), do: activity_raw_start(row) || 0.0
  defp link_capacity_pressure_end_s(row), do: activity_raw_end(row)

  defp link_capacity_pressure_row?(row) do
    row
    |> link_capacity_pressure_shortfall_mb()
    |> positive_number?()
  end

  defp relay_data_path_pressure_row?(row) do
    custody_status = row["custody_status"]
    latency_status = row["latency_status"]
    risk_status = row["risk_status"]

    Enum.any?([
      custody_status not in [nil, "", "confirmed", "acknowledged", "delivered", "nominal"],
      latency_status not in [nil, "", "within_limit", "nominal", "on_time"],
      risk_status not in [nil, "", "nominal", "low"]
    ])
  end

  defp link_capacity_pressure_shortfall_mb(row) do
    [
      row["selected_downlink_shortfall_mb"],
      row["actual_downlink_shortfall_mb"]
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&positive_number?/1)
  end

  defp link_capacity_pressure_source_contact_ids(row) do
    row
    |> link_capacity_pressure_source_contact_values()
    |> Enum.map(&link_capacity_pressure_source_contact_id/1)
    |> Enum.filter(&stable_id_string?/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp link_capacity_pressure_planned_contacts(row) do
    case numeric_or_nil(row["selected_contact_count"]) do
      value when is_number(value) ->
        value

      _value ->
        row
        |> link_capacity_pressure_selected_contact_values()
        |> Enum.map(&link_capacity_pressure_source_contact_id/1)
        |> Enum.filter(&stable_id_string?/1)
        |> Enum.uniq()
        |> length()
    end
  end

  defp link_capacity_pressure_selected_contact_values(row) do
    [
      row["selected_contact_ids"],
      row["selected_contact_id"],
      row["selected_contacts"],
      row["selected_contact"]
    ]
    |> List.flatten()
  end

  defp link_capacity_pressure_source_contact_values(row) do
    [
      row["selected_contact_ids"],
      row["selected_contact_id"],
      row["actual_throughput_contact_ids"],
      row["actual_throughput_contact_id"],
      row["actual_completion_contact_ids"],
      row["actual_completion_contact_id"],
      row["required_downlink_contact_ids"],
      row["required_downlink_contact_id"],
      row["contact_ids"],
      row["contact_id"],
      row["selected_contacts"],
      row["selected_contact"],
      row["actual_throughput_contacts"],
      row["actual_throughput_contact"],
      row["actual_completion_contacts"],
      row["actual_completion_contact"],
      row["required_downlink_contacts"],
      row["required_downlink_contact"],
      row["source_contacts"],
      row["source_contact"],
      row["contacts"],
      row["contact"]
    ]
    |> List.flatten()
  end

  defp link_capacity_pressure_source_contact_id(%{} = contact) do
    contact
    |> stringify_keys()
    |> contact_allocation_contact_identity()
  end

  defp link_capacity_pressure_source_contact_id(value), do: value

  defp link_capacity_pressure_source_window_id(row) do
    case link_capacity_pressure_source_window_ids(row) do
      [source_window_id] -> source_window_id
      _source_window_ids -> nil
    end
  end

  defp link_capacity_pressure_source_window_ids(row) do
    [
      row["source_window_id"],
      row["source_window_ids"],
      get_in(row, ["source_window", "id"]),
      get_in(row, ["activity_context", "source_window_id"]),
      link_capacity_pressure_source_contact_window_ids(row)
    ]
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.filter(&stable_id_string?/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      source_window_ids -> source_window_ids
    end
  end

  defp link_capacity_pressure_source_contact_window_ids(row) do
    row
    |> link_capacity_pressure_source_contact_values()
    |> Enum.filter(&is_map/1)
    |> Enum.map(&stringify_keys/1)
    |> Enum.flat_map(fn contact ->
      [
        activity_source_window_id(contact),
        get_in(contact, ["activity_context", "source_window_id"])
      ]
    end)
  end

  defp link_capacity_pressure_downlink_demand_sources(row) do
    [
      row["downlink_demand_source"],
      row["downlink_demand_sources"],
      link_capacity_pressure_source_contact_downlink_demand_sources(row)
    ]
    |> normalize_downlink_source_list()
    |> case do
      [] -> link_capacity_pressure_downlink_completion_sources(row)
      sources -> sources
    end
  end

  defp link_capacity_pressure_downlink_completion_sources(row) do
    [
      row["downlink_completion_source"],
      row["downlink_completion_sources"],
      link_capacity_pressure_source_contact_downlink_completion_sources(row)
    ]
    |> normalize_downlink_source_list()
    |> case do
      [] -> nil
      sources -> sources
    end
  end

  defp link_capacity_pressure_source_contact_downlink_demand_sources(row) do
    row
    |> link_capacity_pressure_source_contact_values()
    |> link_capacity_pressure_source_contact_downlink_sources([
      "downlink_demand_source",
      "downlink_demand_sources"
    ])
  end

  defp link_capacity_pressure_source_contact_downlink_completion_sources(row) do
    row
    |> link_capacity_pressure_source_contact_values()
    |> link_capacity_pressure_source_contact_downlink_sources([
      "downlink_completion_source",
      "downlink_completion_sources"
    ])
  end

  defp link_capacity_pressure_source_contact_downlink_sources(values, fields) do
    values
    |> Enum.filter(&is_map/1)
    |> Enum.map(&stringify_keys/1)
    |> Enum.flat_map(fn contact ->
      Enum.flat_map(fields, fn field ->
        [
          contact[field],
          get_in(contact, ["throughput_model", field]),
          get_in(contact, ["activity_context", field])
        ]
      end)
    end)
  end

  defp normalize_downlink_source_list(values) do
    values
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp link_capacity_pressure_reasons(row) do
    []
    |> maybe_append_reason(
      positive_number?(numeric_or_nil(row["selected_downlink_shortfall_mb"])),
      "link_capacity_selected_downlink_shortfall"
    )
    |> maybe_append_reason(
      positive_number?(numeric_or_nil(row["actual_downlink_shortfall_mb"])),
      "link_capacity_actual_downlink_shortfall"
    )
    |> Enum.reverse()
  end

  defp relay_data_path_pressure_reasons(row) do
    []
    |> maybe_append_reason(
      row["custody_status"] not in [nil, "", "confirmed", "acknowledged", "delivered", "nominal"],
      "relay_data_path_custody_#{row["custody_status"]}"
    )
    |> maybe_append_reason(
      row["latency_status"] not in [nil, "", "within_limit", "nominal", "on_time"],
      "relay_data_path_latency_#{row["latency_status"]}"
    )
    |> maybe_append_reason(
      row["risk_status"] not in [nil, "", "nominal", "low"],
      "relay_data_path_risk_#{row["risk_status"]}"
    )
    |> Enum.reverse()
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Kernel.++(relay_data_path_pressure_risk_reasons(row) || [])
    |> Enum.uniq()
  end

  defp relay_data_path_pressure_route_ids(row),
    do: relay_data_path_pressure_values(row, ["route_id", "route_ids"])

  defp relay_data_path_pressure_source_spacecraft_ids(row),
    do: relay_data_path_pressure_values(row, ["source_spacecraft_id", "source_spacecraft_ids"])

  defp relay_data_path_pressure_relay_spacecraft_ids(row) do
    relay_data_path_pressure_values(row, [
      "relay_spacecraft_id",
      "relay_spacecraft_ids",
      "relay_chain_spacecraft_ids"
    ])
  end

  defp relay_data_path_pressure_relay_chain_spacecraft_ids(row),
    do: relay_data_path_pressure_values(row, ["relay_chain_spacecraft_ids"])

  defp relay_data_path_pressure_ground_downlink_contact_ids(row) do
    relay_data_path_pressure_values(row, [
      "ground_downlink_contact_id",
      "ground_downlink_contact_ids"
    ])
  end

  defp relay_data_path_pressure_risk_reasons(row),
    do: relay_data_path_pressure_values(row, ["risk_reason", "risk_reasons"])

  defp relay_data_path_pressure_values(row, fields) do
    fields
    |> Enum.flat_map(fn field -> row |> Map.get(field) |> List.wrap() end)
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      values -> values
    end
  end

  defp link_capacity_pressure_trust_boundary(row) do
    Map.get(row, "trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      get_in(row, ["source_link_capacity", "trust_boundary"]) ||
      get_in(row, ["source_link_capacity", "provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp derived_score_term_pressure_branches(prior_plan) do
    prior_plan
    |> prior_plan_score_term_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {row, index} ->
        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> score_term_pressure_branch(source_path, index)
      end)
    end)
  end

  defp prior_plan_score_term_reports(prior_plan) do
    direct_reports =
      [
        {"source_score_term_report", "prior_plan.source_score_term_report"},
        {"score_term_report", "prior_plan.score_term_report"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        case Map.get(prior_plan, field) do
          %{} = report -> [{stringify_keys(report), source_path}]
          _report -> []
        end
      end)

    direct_reports ++ prior_plan_result_artifact_score_term_reports(prior_plan)
  end

  defp derived_mission_state_score_term_pressure_branches(mission_state) do
    mission_state
    |> mission_state_score_term_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {row, index} ->
        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> score_term_pressure_branch(source_path, index)
      end)
    end)
  end

  defp mission_state_score_term_reports(mission_state) do
    mission_state = stringify_keys(mission_state || %{})

    mission_state_score_term_reports(mission_state, [
      {"source_score_term_report", "mission_state.source_score_term_report"},
      {"score_term_report", "mission_state.score_term_report"}
    ]) ++
      mission_state_result_artifact_embedded_reports(mission_state, "source_score_term_report") ++
      mission_state_result_artifact_embedded_reports(mission_state, "score_term_report")
  end

  defp mission_state_source_score_term_reports(mission_state) do
    mission_state_score_term_reports(mission_state, [
      {"source_score_term_report", "mission_state.source_score_term_report"}
    ])
  end

  defp mission_state_canonical_score_term_reports(mission_state) do
    mission_state_score_term_reports(mission_state, [
      {"score_term_report", "mission_state.score_term_report"}
    ])
  end

  defp mission_state_score_term_reports(mission_state, fields) do
    mission_state = stringify_keys(mission_state || %{})

    fields
    |> Enum.flat_map(fn {field, source_path} ->
      mission_state
      |> Map.get(field)
      |> mission_state_source_report_entries(source_path)
    end)
  end

  defp prior_plan_result_artifact_score_term_reports(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      ["source_score_term_report", "score_term_report"]
      |> Enum.flat_map(fn report_key ->
        case Map.get(artifact, report_key) do
          %{} = report ->
            report =
              report
              |> stringify_keys()
              |> put_inherited_result_artifact_trust_boundary(artifact)

            [{report, "#{source_path}.#{report_key}"}]

          _report ->
            []
        end
      end)
    end)
  end

  defp score_term_pressure_branch(row, source_path, index) do
    row = normalize_score_term_pressure_row(row)

    row
    |> score_term_pressure_events(source_path)
    |> case do
      [] ->
        []

      events ->
        identity =
          row["id"] || row["branch_id"] || row["scenario_id"] ||
            score_term_pressure_event_identity(events) || index

        [
          %{
            "id" => "derived_score_term_pressure_#{branch_id_fragment(identity)}",
            "label" => "Derived score-term pressure #{identity}",
            "events" => events,
            "metadata" =>
              %{
                "derived_source" => source_path,
                "score_term_key" => row["term_key"],
                "score_term_value" => score_term_value(row),
                "score_term_selected" => row["selected"]
              }
              |> compact_map()
          }
        ]
    end
  end

  defp disambiguate_score_term_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if score_term_pressure_branch_id?(branch_id) and Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> score_term_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("score_term_branch_base_id", branch_id)
          |> Map.put("score_term_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_score_term_suffixes()
  end

  defp score_term_pressure_branch_id?(id) when is_binary(id),
    do: String.starts_with?(id, "derived_score_term_pressure_")

  defp score_term_pressure_branch_id?(_id), do: false

  defp disambiguate_duplicate_score_term_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "score_term_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["score_term_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["score_term_branch_base_id"]}_#{suffix}")
        |> Map.update("metadata", %{}, &Map.put(&1, "score_term_branch_identity", suffix))
      else
        branch
      end
    end)
  end

  defp score_term_pressure_branch_identity(branch, index) do
    branch
    |> Map.get("events", [])
    |> List.wrap()
    |> Enum.flat_map(fn event ->
      [
        event["feedback_source"],
        event["ground_station_id"],
        event["target_id"],
        event["objective_id"],
        event["score_term_key"],
        event["source_activity_id"],
        event["source_activity_ids"],
        event["downlink_demand_source"],
        event["downlink_demand_sources"],
        event["downlink_completion_source"],
        event["downlink_completion_sources"],
        event["required_downlink_mb"],
        event["required_contacts"],
        event["required_observations"],
        event["starts_at_s"],
        event["ends_at_s"],
        event["trust_boundary"]
      ]
    end)
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp normalize_score_term_pressure_row(row) do
    row
    |> normalize_score_term_pressure_field("term_key")
    |> normalize_objective_pressure_row()
  end

  defp normalize_score_term_pressure_field(row, field) do
    case Map.get(row, field) do
      value when value in [nil, ""] -> row
      value -> Map.put(row, field, score_term_key(value))
    end
  end

  defp score_term_key(key) when is_atom(key) do
    key
    |> Atom.to_string()
    |> score_term_key()
  end

  defp score_term_key(key) when is_binary(key) do
    key
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
  end

  defp score_term_key(key), do: key

  defp score_term_pressure_event_identity(events) do
    Enum.find_value(events, fn event ->
      event["ground_station_id"] || event["target_id"] || event["objective_id"]
    end)
  end

  defp score_term_pressure_events(row, source_path) do
    []
    |> Kernel.++(score_term_collection_latency_gap_events(row, source_path))
    |> Kernel.++(score_term_downlink_gap_events(row, source_path))
    |> Kernel.++(score_term_target_gap_events(row, source_path))
  end

  defp score_term_collection_latency_gap_events(row, source_path) do
    max_latency_s = score_term_max_latency_s(row)
    planned_latency_s = score_term_planned_latency_s(row)
    latency_gap = score_term_latency_gap(row)

    latency_gap? =
      score_term_collection_latency_objective?(row) and
        (positive_number?(latency_gap) or
           (is_number(max_latency_s) and
              (is_nil(planned_latency_s) or planned_latency_s > max_latency_s)))

    if latency_gap? and score_term_collection_latency_routed?(row) do
      planned_downlink_mb = score_term_planned_downlink_mb(row)
      downlink_gap = score_term_downlink_gap(row)

      [
        %{
          "type" => "downlink_completion_gap",
          "objective_id" => row["objective_id"] || row["id"],
          "objective_type" => row["objective"] || row["objective_type"] || "collection_latency",
          "latency_objective" => true,
          "target_id" => score_term_primary_target_id(row),
          "scenario_id" => objective_pressure_scenario_id(row),
          "branch_id" => row["branch_id"],
          "ground_station_id" => score_term_station_id(row),
          "collection_id" => score_term_collection_id(row),
          "collection_ids" => score_term_collection_ids(row),
          "product_id" => score_term_product_id(row),
          "product_ids" => score_term_product_ids(row),
          "payload_id" => score_term_payload_id(row),
          "payload_ids" => score_term_payload_ids(row),
          "instrument_id" => score_term_instrument_id(row),
          "instrument_ids" => score_term_instrument_ids(row),
          "starts_at_s" => score_term_latency_window_start_s(row),
          "ends_at_s" => score_term_latency_window_end_s(row),
          "required_contacts" => score_term_required_contacts(row, score_term_contact_gap(row)),
          "planned_contacts" => score_term_planned_contacts(row),
          "required_downlink_mb" => score_term_required_downlink_mb(row, downlink_gap),
          "planned_downlink_mb" => planned_downlink_mb,
          "max_latency_s" => max_latency_s,
          "planned_latency_s" => planned_latency_s,
          "source_activity_id" => score_term_source_activity_id(row),
          "source_activity_ids" => score_term_source_activity_ids(row),
          "score_term_key" => row["term_key"],
          "score_term_value" => score_term_value(row),
          "timeline_score" => numeric_or_nil(row["timeline_score"]),
          "score_terms" => row["score_terms"],
          "downlink_demand_sources" => [score_term_downlink_source(row)],
          "downlink_completion_sources" => [score_term_downlink_source(row)],
          "derivation_reasons" => score_term_latency_reasons(row, latency_gap),
          "feedback_source" => source_path,
          "feedback_scope" => "score_term",
          "trust_boundary" => score_term_trust_boundary(row)
        }
        |> compact_map()
      ]
    else
      []
    end
  end

  defp score_term_downlink_gap_events(row, source_path) do
    station_id = score_term_station_id(row)
    downlink_gap = score_term_downlink_gap(row)
    contact_gap = score_term_contact_gap(row)

    cond do
      not stable_id_string?(station_id) ->
        []

      not (positive_number?(downlink_gap) or positive_number?(contact_gap)) ->
        []

      true ->
        planned_downlink_mb = score_term_planned_downlink_mb(row)
        planned_contacts = score_term_planned_contacts(row)

        [
          %{
            "type" => "downlink_completion_gap",
            "objective_id" => row["objective_id"] || row["id"],
            "objective_type" => row["objective"] || row["objective_type"] || "score_term_gap",
            "scenario_id" => objective_pressure_scenario_id(row),
            "branch_id" => row["branch_id"],
            "ground_station_id" => station_id,
            "collection_id" => score_term_collection_id(row),
            "collection_ids" => score_term_collection_ids(row),
            "product_id" => score_term_product_id(row),
            "product_ids" => score_term_product_ids(row),
            "payload_id" => score_term_payload_id(row),
            "payload_ids" => score_term_payload_ids(row),
            "instrument_id" => score_term_instrument_id(row),
            "instrument_ids" => score_term_instrument_ids(row),
            "starts_at_s" => score_term_window_start_s(row),
            "ends_at_s" => score_term_window_end_s(row),
            "required_contacts" => score_term_required_contacts(row, contact_gap),
            "planned_contacts" => planned_contacts,
            "required_downlink_mb" => score_term_required_downlink_mb(row, downlink_gap),
            "planned_downlink_mb" => planned_downlink_mb,
            "source_activity_ids" => score_term_source_activity_ids(row),
            "score_term_key" => row["term_key"],
            "score_term_value" => score_term_value(row),
            "timeline_score" => numeric_or_nil(row["timeline_score"]),
            "score_terms" => row["score_terms"],
            "downlink_demand_sources" => [score_term_downlink_source(row)],
            "downlink_completion_sources" => [score_term_downlink_source(row)],
            "derivation_reasons" => score_term_downlink_reasons(row, contact_gap, downlink_gap),
            "feedback_source" => source_path,
            "feedback_scope" => "score_term",
            "trust_boundary" => score_term_trust_boundary(row)
          }
          |> compact_map()
        ]
    end
  end

  defp score_term_target_gap_events(row, source_path) do
    target_gap = score_term_target_gap(row)

    if positive_number?(target_gap) do
      row
      |> score_term_gap_target_ids()
      |> Enum.map(fn target_id ->
        target_spec = score_term_target_spec(row, target_id)

        %{
          "type" => "urgent_target",
          "objective_id" => row["objective_id"] || row["id"],
          "objective_type" =>
            row["objective"] || row["objective_type"] || "score_term_target_gap",
          "target_id" => target_id,
          "scenario_id" => objective_pressure_scenario_id(row),
          "branch_id" => row["branch_id"],
          "starts_at_s" => score_term_window_start_s(row),
          "ends_at_s" => score_term_window_end_s(row),
          "priority" => score_term_target_priority(row, target_spec),
          "latitude_deg" => score_term_target_number(row, target_spec, "latitude_deg"),
          "longitude_deg" => score_term_target_number(row, target_spec, "longitude_deg"),
          "minimum_elevation_deg" =>
            score_term_target_number(row, target_spec, "minimum_elevation_deg"),
          "required_observations" => score_term_required_observations(row, target_gap),
          "planned_observations" => score_term_planned_observations(row),
          "source_activity_ids" => score_term_source_activity_ids(row),
          "score_term_key" => row["term_key"],
          "score_term_value" => score_term_value(row),
          "timeline_score" => numeric_or_nil(row["timeline_score"]),
          "score_terms" => row["score_terms"],
          "derivation_reason" => "score_term_target_gap",
          "derivation_reasons" => score_term_target_reasons(row),
          "feedback_source" => source_path,
          "feedback_scope" => "score_term",
          "trust_boundary" => score_term_trust_boundary(row)
        }
        |> compact_map()
      end)
    else
      []
    end
  end

  defp score_term_downlink_gap(row) do
    score_term_gap_value(row, [
      "downlink_shortfall_mb",
      "selected_downlink_shortfall_mb",
      "missing_downlink_mb",
      "downlink_completion_gap_mb",
      "required_downlink_gap_mb"
    ])
  end

  defp score_term_contact_gap(row) do
    score_term_gap_value(row, [
      "contact_count_gap",
      "downlink_contact_gap",
      "missing_contact_count",
      "downlink_contact_shortfall_count"
    ])
  end

  defp score_term_target_gap(row) do
    score_term_gap_value(row, [
      "observation_count_gap",
      "missing_observation_count",
      "target_observation_gap_count",
      "missed_target_count",
      "target_gap_count",
      "target_coverage_gap_count",
      "coverage_gap_count",
      "observation_shortfall_count",
      "revisit_gap_count",
      "missing_revisit_count",
      "target_revisit_gap_count",
      "revisit_shortfall_count",
      "coverage_shortfall_count"
    ])
  end

  defp score_term_latency_gap(row) do
    score_term_gap_value(row, [
      "collection_latency_gap_s",
      "latency_gap_s",
      "delivery_latency_gap_s",
      "collection_latency_shortfall_s",
      "late_delivery_s"
    ])
  end

  defp score_term_collection_latency_objective?(row) do
    row["objective"] == "collection_latency" or row["objective_type"] == "collection_latency" or
      row["term_key"] in [
        "collection_latency_gap_s",
        "latency_gap_s",
        "delivery_latency_gap_s",
        "collection_latency_shortfall_s",
        "late_delivery_s"
      ] or
      is_number(
        score_terms_number(row, [
          "collection_latency_gap_s",
          "latency_gap_s",
          "delivery_latency_gap_s",
          "collection_latency_shortfall_s",
          "late_delivery_s"
        ])
      )
  end

  defp score_term_collection_latency_routed?(row) do
    stable_id_string?(score_term_source_activity_id(row)) or
      stable_id_string?(score_term_station_id(row)) or
      stable_id_string?(score_term_primary_target_id(row)) or
      stable_id_string?(score_term_collection_id(row)) or
      stable_id_string?(score_term_product_id(row)) or
      stable_id_string?(score_term_payload_id(row)) or
      stable_id_string?(score_term_instrument_id(row))
  end

  defp score_term_gap_value(row, keys) do
    cond do
      row["term_key"] in keys ->
        score_term_value(row)

      is_map(row["score_terms"]) ->
        score_terms_number(row, keys)

      true ->
        nil
    end
  end

  defp score_term_value(row), do: numeric_or_nil(row["value"])

  defp score_term_keyed_map(score_terms) when is_map(score_terms) do
    Map.new(score_terms, fn {key, value} -> {score_term_key(key), value} end)
  end

  defp score_term_keyed_map(_score_terms), do: %{}

  defp score_term_station_id(row) do
