    |> Enum.map(&Map.get(entity, &1))
    |> Enum.find(&stable_id_string?/1)
  end

  defp score_term_entity_id(_entity, _keys), do: nil

  defp score_terms_number(row, keys) do
    score_terms =
      row
      |> Map.get("score_terms", %{})
      |> score_term_keyed_map()

    keys
    |> Enum.map(&numeric_or_nil(Map.get(score_terms, &1)))
    |> Enum.find(&is_number/1)
  end

