          "min_downlink_mb"
        ])
      ]
      |> Enum.map(&numeric_or_nil/1)
      |> Enum.find(&is_number/1)

    cond do
      is_number(explicit) -> explicit
      positive_number?(downlink_gap) -> score_term_planned_downlink_mb(row) + downlink_gap
      true -> nil
    end
  end

