      ]
      |> Enum.map(&numeric_or_nil/1)
      |> Enum.find(&is_number/1)

    cond do
      is_number(explicit) ->
        max(ceil_count(explicit), 1)

      positive_number?(target_gap) ->
        max(ceil_count(score_term_planned_observations(row) + target_gap), 1)

      true ->
        1
    end
  end

