  defp score_term_downlink_reasons(row, contact_gap, downlink_gap) do
    []
    |> maybe_append_reason(positive_number?(downlink_gap), "score_term_downlink_volume_gap")
    |> maybe_append_reason(positive_number?(contact_gap), "score_term_contact_count_gap")
    |> maybe_append_reason(row["term_key"] not in [nil, ""], "score_term_#{row["term_key"]}")
    |> Enum.reverse()
    |> Enum.uniq()
