    []
    |> maybe_append_reason(true, "collection_latency_gap")
    |> maybe_append_reason(true, "score_term_collection_latency_gap")
    |> maybe_append_reason(positive_number?(latency_gap), "score_term_latency_gap")
    |> maybe_append_reason(row["term_key"] not in [nil, ""], "score_term_#{row["term_key"]}")
    |> Enum.reverse()
    |> Enum.uniq()
