  defp score_term_trust_boundary(row) do
    Map.get(row, "trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp derived_objective_satisfaction_pressure_branches(prior_plan) do
    prior_plan
    |> prior_plan_objective_satisfaction_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {row, index} ->
        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> objective_satisfaction_pressure_branch(source_path, index)
      end)
    end)
  end

  defp prior_plan_objective_satisfaction_reports(prior_plan) do
    direct_reports =
      [
        {"source_objective_satisfaction_report",
         "prior_plan.source_objective_satisfaction_report"},
        {"objective_satisfaction_report", "prior_plan.objective_satisfaction_report"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        case Map.get(prior_plan, field) do
          %{} = report -> [{stringify_keys(report), source_path}]
          _report -> []
        end
      end)

    direct_reports ++ prior_plan_result_artifact_objective_satisfaction_reports(prior_plan)
  end

  defp derived_mission_state_objective_satisfaction_pressure_branches(mission_state) do
    mission_state
    |> mission_state_objective_satisfaction_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {row, index} ->
        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> objective_satisfaction_pressure_branch(source_path, index)
      end)
    end)
  end

  defp mission_state_objective_satisfaction_reports(mission_state) do
    mission_state = stringify_keys(mission_state || %{})

    mission_state_objective_satisfaction_reports(mission_state, [
      {"source_objective_satisfaction_report",
       "mission_state.source_objective_satisfaction_report"},
      {"objective_satisfaction_report", "mission_state.objective_satisfaction_report"}
    ]) ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "source_objective_satisfaction_report"
      ) ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "objective_satisfaction_report"
      )
  end

  defp mission_state_source_objective_satisfaction_reports(mission_state) do
    mission_state_objective_satisfaction_reports(mission_state, [
      {"source_objective_satisfaction_report",
       "mission_state.source_objective_satisfaction_report"}
    ])
  end

  defp mission_state_canonical_objective_satisfaction_reports(mission_state) do
    mission_state_objective_satisfaction_reports(mission_state, [
      {"objective_satisfaction_report", "mission_state.objective_satisfaction_report"}
    ])
  end

  defp mission_state_objective_satisfaction_reports(mission_state, fields) do
    mission_state = stringify_keys(mission_state || %{})

    fields
    |> Enum.flat_map(fn {field, source_path} ->
      mission_state
      |> Map.get(field)
      |> mission_state_source_report_entries(source_path)
    end)
  end

  defp prior_plan_result_artifact_objective_satisfaction_reports(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      ["source_objective_satisfaction_report", "objective_satisfaction_report"]
      |> Enum.flat_map(fn report_key ->
        case Map.get(artifact, report_key) do
          %{} = report ->
            report =
              report
              |> stringify_keys()
              |> put_inherited_result_artifact_trust_boundary(artifact)

            [{report, "#{source_path}.#{report_key}"}]

          _report ->
            []
        end
      end)
    end)
  end

  defp objective_satisfaction_pressure_branch(row, source_path, index) do
    row =
      row
      |> normalize_objective_satisfaction_row_status()
      |> normalize_objective_pressure_row()

    row
    |> objective_satisfaction_pressure_events(source_path)
    |> Enum.map(fn event ->
      objective_id = objective_satisfaction_branch_identity(row, event, index)

      %{
        "id" => "derived_objective_satisfaction_#{branch_id_fragment(objective_id)}",
        "label" => "Derived objective satisfaction pressure #{objective_id}",
        "events" => [event],
        "metadata" =>
          %{
            "derived_source" => source_path,
            "objective" => row["objective"],
            "objective_status" => row["status"],
            "source_objective_status" => row["_source_objective_status"]
          }
          |> compact_map()
      }
    end)
  end

  defp disambiguate_objective_satisfaction_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if objective_satisfaction_pressure_branch_id?(branch_id) and
           Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> objective_satisfaction_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("objective_satisfaction_branch_base_id", branch_id)
          |> Map.put("objective_satisfaction_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_objective_satisfaction_suffixes()
  end

  defp objective_satisfaction_pressure_branch_id?(id) when is_binary(id),
    do: String.starts_with?(id, "derived_objective_satisfaction_")

  defp objective_satisfaction_pressure_branch_id?(_id), do: false

  defp disambiguate_duplicate_objective_satisfaction_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "objective_satisfaction_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["objective_satisfaction_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["objective_satisfaction_branch_base_id"]}_#{suffix}")
        |> Map.update(
          "metadata",
          %{},
          &Map.put(&1, "objective_satisfaction_branch_identity", suffix)
        )
      else
        branch
      end
    end)
  end

  defp objective_satisfaction_pressure_branch_identity(branch, index) do
    branch
    |> Map.get("events", [])
    |> List.wrap()
    |> Enum.flat_map(fn event ->
      [
        event["feedback_source"],
        event["objective_id"],
        event["objective_type"],
        event["ground_station_id"],
        event["target_id"],
        event["source_activity_id"],
        event["source_activity_ids"],
        event["missed_downlink_activity_id"],
        event["missed_downlink_activity_ids"],
        event["required_downlink_mb"],
        event["required_contacts"],
        event["required_observations"],
        event["starts_at_s"],
        event["ends_at_s"],
        event["trust_boundary"]
      ]
    end)
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp objective_satisfaction_branch_identity(row, event, index) do
    base = Map.get(row, "id") || Map.get(row, "objective") || index

    case {row["objective"], event["target_id"], event["source_activity_id"]} do
      {objective, target_id, _source_activity_id}
      when objective in ["target_coverage", "coverage"] and target_id not in [nil, ""] ->
        "#{base}:#{target_id}"

      {"collection_latency", _target_id, source_activity_id}
      when source_activity_id not in [nil, ""] ->
        "#{base}:#{source_activity_id}"

      {objective, target_id, _source_activity_id}
      when objective in ["observation_success", "observation_quality", "image_quality"] and
             target_id not in [nil, ""] ->
        "#{base}:#{target_id}"

      {_objective, _target_id, _source_activity_id} ->
        base
    end
  end

  defp objective_satisfaction_pressure_events(%{"objective" => objective} = row, source_path)
       when objective in ["downlink_completion", "required_downlink_completion"] do
    required_contacts = objective_satisfaction_required_contacts(row)
    planned_contacts = objective_satisfaction_planned_contacts(row)
    required_downlink_mb = objective_satisfaction_required_downlink_mb(row)
    planned_downlink_mb = objective_satisfaction_planned_downlink_mb(row)

    contact_gap? =
      is_number(required_contacts) and required_contacts > planned_contacts

    volume_gap? =
      is_number(required_downlink_mb) and required_downlink_mb > planned_downlink_mb

    if objective_satisfaction_gap_status?(row["status"]) and (contact_gap? or volume_gap?) do
      [
        %{
          "type" => "downlink_completion_gap",
          "objective_id" => row["id"],
          "objective_type" => row["objective"],
          "scenario_id" => objective_pressure_scenario_id(row),
          "ground_station_id" => objective_pressure_station_id(row),
          "collection_id" => objective_pressure_collection_id(row),
          "collection_ids" => objective_pressure_collection_ids(row),
          "product_id" => objective_pressure_product_id(row),
          "product_ids" => objective_pressure_product_ids(row),
          "payload_id" => objective_pressure_payload_id(row),
          "payload_ids" => objective_pressure_payload_ids(row),
          "instrument_id" => objective_pressure_instrument_id(row),
          "instrument_ids" => objective_pressure_instrument_ids(row),
          "starts_at_s" => objective_satisfaction_window_start_s(row),
          "ends_at_s" => objective_satisfaction_window_end_s(row),
          "required_contacts" => required_contacts,
          "planned_contacts" => planned_contacts,
          "required_downlink_mb" => required_downlink_mb,
          "planned_downlink_mb" => planned_downlink_mb,
          "source_activity_ids" => objective_satisfaction_source_contact_ids(row),
          "derivation_reasons" =>
            objective_satisfaction_pressure_reasons(row, contact_gap?, volume_gap?),
          "feedback_source" => source_path,
          "feedback_scope" => "objective_satisfaction",
          "objective_status" => row["status"],
          "source_objective_status" => row["_source_objective_status"],
          "trust_boundary" => objective_satisfaction_trust_boundary(row)
        }
        |> compact_map()
      ]
    else
      []
    end
  end

  defp objective_satisfaction_pressure_events(%{"objective" => objective} = row, source_path)
       when objective in [
              "target_coverage",
              "coverage",
              "target_commitment",
              "priority_commitment",
              "target_observation",
              "target_revisit"
            ] do
    if objective_satisfaction_gap_status?(row["status"]) do
      row
      |> objective_satisfaction_gap_target_ids()
      |> Enum.map(&objective_satisfaction_target_event(row, source_path, &1))
    else
      []
    end
  end

  defp objective_satisfaction_pressure_events(
         %{"objective" => "collection_latency"} = row,
         source_path
       ) do
    if objective_satisfaction_gap_status?(row["status"]) do
      [
        row
        |> objective_satisfaction_collection_latency_event(source_path)
        |> compact_map()
      ]
    else
      []
    end
  end

  defp objective_satisfaction_pressure_events(%{"objective" => objective} = row, source_path)
       when objective in ["observation_success", "observation_quality", "image_quality"] do
    if objective_satisfaction_gap_status?(row["status"]) do
      row
      |> objective_satisfaction_observation_quality_event(source_path)
      |> case do
        nil -> []
        event -> [event]
      end
    else
      []
    end
  end

  defp objective_satisfaction_pressure_events(_row, _source_path), do: []

  defp objective_satisfaction_observation_quality_event(row, source_path) do
    target_id = objective_satisfaction_primary_target_id(row)
    explicit_factor = objective_satisfaction_observation_success_factor(row)
    image_quality_score = image_quality_score_value(row)
    image_quality_status = image_quality_status_value(row)
    image_quality_source = image_quality_source_value(row)
    cloud_cover_fraction = cloud_cover_fraction_value(row)
    blur_score = blur_score_value(row)

    quality_evidence? =
      is_number(image_quality_score) or image_quality_status not in [nil, ""] or
        is_number(cloud_cover_fraction) or is_number(blur_score)

    {quality_factor, quality_feedback_source} =
      observation_quality_feedback_factor(
        image_quality_score,
        image_quality_status,
        cloud_cover_fraction,
        blur_score
      )

    factor = explicit_factor || if(quality_evidence?, do: quality_factor)

    if stable_id_string?(target_id) and is_number(factor) do
      %{
        "type" => "observation_success_feedback",
        "objective_id" => row["id"] || row["objective_id"],
        "objective_type" => row["objective"],
        "target_id" => target_id,
        "scenario_id" => objective_pressure_scenario_id(row),
        "spacecraft_id" => objective_pressure_spacecraft_id(row),
        "starts_at_s" => objective_satisfaction_window_start_s(row),
        "ends_at_s" => objective_satisfaction_window_end_s(row),
        "priority" => objective_satisfaction_target_priority(row, %{}),
        "required_observations" => objective_satisfaction_required_target_observations(row),
        "observation_success_factor" => factor,
        "image_quality_score" => image_quality_score,
        "image_quality_status" => image_quality_status,
        "image_quality_source" => image_quality_source,
        "cloud_cover_fraction" => cloud_cover_fraction,
        "blur_score" => blur_score,
        "source_activity_id" => objective_satisfaction_source_activity_id(row),
        "source_activity_ids" => objective_satisfaction_source_activity_ids(row),
        "derivation_reasons" =>
          objective_satisfaction_observation_quality_reasons(
            row,
            explicit_factor,
            image_quality_score,
            image_quality_status,
            cloud_cover_fraction,
            blur_score
          ),
        "feedback_source" => source_path,
        "feedback_scope" => "objective_satisfaction",
        "quality_feedback_source" =>
          objective_satisfaction_quality_feedback_source(quality_feedback_source),
        "objective_status" => row["status"],
        "source_objective_status" => row["_source_objective_status"],
        "trust_boundary" => objective_satisfaction_trust_boundary(row)
      }
      |> compact_map()
    end
  end

  defp objective_satisfaction_observation_success_factor(row) do
    first_unit_interval_activity_value(row, [
      "observation_success_factor",
      "observation_success_rate",
      "observation_success",
      "success_factor",
      "success_rate",
      "realized_success_factor",
      "planned_success_factor",
      ["quality", "observation_success_factor"],
      ["metadata", "observation_success_factor"]
    ])
  end

  defp objective_satisfaction_observation_quality_reasons(
         row,
         explicit_factor,
         image_quality_score,
         image_quality_status,
         cloud_cover_fraction,
         blur_score
       ) do
    []
    |> maybe_append_reason(is_number(explicit_factor), "objective_satisfaction_success_factor")
    |> maybe_append_reason(is_number(image_quality_score), "objective_satisfaction_image_quality")
    |> maybe_append_reason(
      image_quality_status not in [nil, ""],
      "objective_satisfaction_image_quality_status"
    )
    |> maybe_append_reason(is_number(cloud_cover_fraction), "objective_satisfaction_cloud_cover")
    |> maybe_append_reason(is_number(blur_score), "objective_satisfaction_blur")
    |> maybe_append_reason(row["status"] not in [nil, ""], "objective_status_#{row["status"]}")
    |> Enum.reverse()
  end

  defp objective_satisfaction_quality_feedback_source(source) when is_binary(source) do
    String.replace_prefix(source, "operational_feedback.", "objective_satisfaction.")
  end

  defp objective_satisfaction_quality_feedback_source(_source), do: nil

  defp objective_satisfaction_collection_latency_event(row, source_path) do
    required_downlink_mb = objective_satisfaction_required_downlink_mb(row)
    planned_downlink_mb = objective_satisfaction_planned_downlink_mb(row)

    %{
      "type" => "downlink_completion_gap",
      "objective_id" => row["id"] || row["objective_id"],
      "objective_type" => "collection_latency",
      "latency_objective" => true,
      "target_id" => objective_satisfaction_primary_target_id(row),
      "scenario_id" => objective_pressure_scenario_id(row),
      "ground_station_id" => objective_pressure_station_id(row),
      "collection_id" => objective_pressure_collection_id(row),
      "collection_ids" => objective_pressure_collection_ids(row),
      "product_id" => objective_pressure_product_id(row),
      "product_ids" => objective_pressure_product_ids(row),
      "payload_id" => objective_pressure_payload_id(row),
      "payload_ids" => objective_pressure_payload_ids(row),
      "instrument_id" => objective_pressure_instrument_id(row),
      "instrument_ids" => objective_pressure_instrument_ids(row),
      "starts_at_s" => objective_satisfaction_latency_window_start_s(row),
      "ends_at_s" => objective_satisfaction_latency_window_end_s(row),
      "required_contacts" => objective_satisfaction_required_collection_latency_contacts(row),
      "planned_contacts" => objective_satisfaction_planned_contacts(row),
      "required_downlink_mb" => required_downlink_mb,
      "planned_downlink_mb" => planned_downlink_mb,
      "max_latency_s" => objective_satisfaction_max_latency_s(row),
      "planned_latency_s" => objective_satisfaction_planned_latency_s(row),
      "source_activity_id" => objective_satisfaction_source_activity_id(row),
      "source_activity_ids" => objective_satisfaction_source_activity_ids(row),
      "missed_downlink_activity_id" => objective_satisfaction_missed_downlink_activity_id(row),
      "missed_downlink_activity_ids" => objective_satisfaction_missed_downlink_activity_ids(row),
      "realized_status" => row["realized_status"],
      "contact_result" => provider_result_artifact_value(row["contact_result"]),
      "derivation_reasons" => objective_satisfaction_collection_latency_reasons(row),
      "feedback_source" => source_path,
      "feedback_scope" => "objective_satisfaction",
      "objective_status" => row["status"],
      "source_objective_status" => row["_source_objective_status"],
      "trust_boundary" => objective_satisfaction_trust_boundary(row)
    }
  end

  defp objective_satisfaction_target_event(row, source_path, target_id) do
    target_spec = objective_satisfaction_target_spec(row, target_id)

    %{
      "type" => "urgent_target",
      "objective_id" => row["id"],
      "objective_type" => objective_satisfaction_target_objective_type(row["objective"]),
      "target_id" => target_id,
      "scenario_id" => objective_pressure_scenario_id(row),
      "spacecraft_id" => objective_pressure_spacecraft_id(row),
      "starts_at_s" => objective_satisfaction_window_start_s(row),
      "ends_at_s" => objective_satisfaction_window_end_s(row),
      "priority" => objective_satisfaction_target_priority(row, target_spec),
      "latitude_deg" => objective_satisfaction_target_number(row, target_spec, "latitude_deg"),
      "longitude_deg" => objective_satisfaction_target_number(row, target_spec, "longitude_deg"),
      "minimum_elevation_deg" =>
        objective_satisfaction_target_number(row, target_spec, "minimum_elevation_deg"),
      "candidate_windows" => objective_satisfaction_candidate_windows(row),
      "allowed_scenario_ids" => objective_satisfaction_allowed_scenario_ids(row),
      "spacecraft_constraints" => objective_satisfaction_allowed_scenario_ids(row),
      "coverage_objective_id" => objective_satisfaction_coverage_objective_id(row),
      "planned_observations" =>
        objective_satisfaction_planned_target_observations(row, target_id),
      "required_observations" => objective_satisfaction_required_target_observations(row),
      "source_activity_ids" => objective_satisfaction_source_observation_ids(row),
      "derivation_reason" => "objective_satisfaction_#{row["status"]}",
      "derivation_reasons" => objective_satisfaction_target_reasons(row),
      "feedback_source" => source_path,
      "feedback_scope" => "objective_satisfaction",
      "objective_status" => row["status"],
      "source_objective_status" => row["_source_objective_status"],
      "trust_boundary" => objective_satisfaction_trust_boundary(row)
    }
    |> compact_map()
  end

  defp objective_satisfaction_target_objective_type("coverage"), do: "target_coverage"
  defp objective_satisfaction_target_objective_type("target_commitment"), do: "target_observation"
  defp objective_satisfaction_target_objective_type(objective), do: objective

  defp objective_satisfaction_target_reasons(row) do
    []
    |> maybe_append_reason(true, "objective_satisfaction_target_gap")
    |> maybe_append_reason(
      objective_satisfaction_score_term_target_gap?(row),
      "objective_satisfaction_score_term_target_gap"
    )
    |> maybe_append_reason(row["status"] not in [nil, ""], "objective_status_#{row["status"]}")
    |> Enum.reverse()
  end

  defp objective_satisfaction_target_priority(row, target_spec) do
    [
      target_spec["priority"],
      target_spec["target_priority"],
      row["priority"],
      row["target_priority"],
      row["objective_priority"]
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
  end

  defp objective_satisfaction_target_number(row, target_spec, field) do
    numeric_or_nil(Map.get(target_spec, field) || Map.get(row, field))
  end

