    [
      row["spacecraft_id"],
      objective_satisfaction_observation_context_value(row, [
        "spacecraft_id",
        "satellite_id",
        "scenario_id"
      ]),
      row["satellite_id"],
      row["scenario_id"]
    ]
    |> Enum.find(&stable_id_string?/1)
  end

