      score_term_entity_id(row["ground_station"], ["ground_station_id", "station_id", "id"]),
      score_term_entity_id(row["station"], ["ground_station_id", "station_id", "id"]),
      objective_satisfaction_observation_context_value(row, [
        "ground_station_id",
        "station_id"
      ]),
      objective_pressure_observation_context_entity_id(
        row,
        [
          "ground_station",
          "station"
        ],
        [
          "ground_station_id",
          "station_id",
          "id"
        ]
      )
