  defp objective_satisfaction_primary_target_id(row) do
    [
      row["target_id"],
      score_term_entity_id(row["target"], ["target_id", "id"]),
      objective_satisfaction_observation_context_value(row, ["target_id", "id"])
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp objective_satisfaction_observation_context_value(row, fields) do
    row
    |> objective_satisfaction_observation_contexts()
    |> Enum.find_value(fn context ->
      Enum.find_value(fields, fn field -> Map.get(context, field) end)
    end)
  end

  defp objective_pressure_observation_context_entity_id(row, fields, entity_keys) do
    row
    |> objective_satisfaction_observation_contexts()
    |> Enum.find_value(fn context ->
      Enum.find_value(fields, fn field ->
        context
        |> Map.get(field)
        |> score_term_entity_id(entity_keys)
      end)
    end)
  end

  defp objective_pressure_observation_context_number(row, fields) do
    row
    |> objective_satisfaction_observation_context_value(fields)
    |> numeric_or_nil()
  end

  defp objective_satisfaction_observation_contexts(row) do
    [
      row["source_observation"],
      row["source_observations"],
      row["observation"],
      row["observations"],
      row["selected_observation"],
      row["selected_observations"],
      row["satisfied_observation"],
      row["satisfied_observations"],
