  defp objective_satisfaction_required_target_observations(row) do
    explicit = objective_satisfaction_required_observations(row)
    score_term_requirement = objective_satisfaction_required_observations_from_score_terms(row)
    target_count_requirement = objective_satisfaction_required_target_count(row)

    cond do
      is_number(explicit) ->
        max(ceil_count(explicit), 1)

      is_number(score_term_requirement) ->
        max(ceil_count(score_term_requirement), 1)

      is_number(target_count_requirement) ->
        max(ceil_count(target_count_requirement), 1)

      is_nil(row["target_id"]) and row["objective"] in ["target_coverage", "coverage"] ->
        1

      true ->
        row
        |> objective_satisfaction_required_contacts()
        |> case do
          value when is_number(value) -> max(ceil_count(value), 1)
          _value -> 1
        end
    end
  end

  defp objective_satisfaction_planned_target_observations(row, target_id) do
    explicit = objective_satisfaction_planned_observations(row)
    selected_target_count = objective_satisfaction_selected_target_count(row)
    universe_targets = objective_satisfaction_requirement_universe_target_ids(row)

    selected_targets =
      row
      |> objective_satisfaction_target_id_values([
        "selected_targets",
        "satisfied_targets",
        "selected_revisit_targets",
        "satisfied_revisit_targets",
        "selected_coverage_targets",
        "satisfied_coverage_targets",
        "selected_target_ids",
        "satisfied_target_ids",
        "selected_revisit_target_ids",
        "satisfied_revisit_target_ids",
        "selected_coverage_target_ids",
        "satisfied_coverage_target_ids"
      ])
      |> MapSet.new()

    cond do
      is_number(explicit) and target_id in objective_satisfaction_gap_target_ids(row) ->
        explicit

      is_number(explicit) and row["target_id"] == target_id ->
        explicit

      is_number(selected_target_count) and target_id in objective_satisfaction_gap_target_ids(row) and
          universe_targets != [] ->
        selected_target_count

      MapSet.member?(selected_targets, target_id) ->
        1

      row["target_id"] == target_id ->
        row
        |> objective_satisfaction_planned_contacts()
        |> ceil_count()

      true ->
        0
    end
  end

