      row["coverage_requirement_status"],
      row["target_requirement_status"],
      row["target_coverage_status"],
      row["latency_status"],
      row["collection_latency_status"],
      row["delivery_status"],
      row["delivery_requirement_status"],
      row["source_objective_status"]
    ]
    |> Enum.find(fn value -> value not in [nil, ""] end)
    |> case do
      nil -> objective_satisfaction_boolean_status(row)
      status -> status
    end
  end

  defp objective_satisfaction_boolean_status(row) do
    [
      row["satisfied"],
      row["satisfied?"],
      row["objective_satisfied"],
      row["objective_satisfied?"],
      row["requirement_satisfied"],
      row["requirement_satisfied?"],
      row["downlink_requirement_satisfied"],
      row["downlink_requirement_satisfied?"],
      row["contact_requirement_satisfied"],
      row["contact_requirement_satisfied?"],
      row["data_volume_requirement_satisfied"],
      row["data_volume_requirement_satisfied?"],
      row["coverage_satisfied"],
      row["coverage_satisfied?"],
      row["target_satisfied"],
      row["target_satisfied?"],
      row["latency_satisfied"],
      row["latency_satisfied?"],
      row["delivery_satisfied"],
      row["delivery_satisfied?"],
      row["met"],
      row["met?"],
      row["objective_met"],
      row["objective_met?"]
    ]
    |> Enum.find_value(fn value ->
      case json_boolean_value(value) do
        true -> "met"
        false -> "unmet"
        nil -> nil
      end
    end)
  end

  defp normalize_objective_pressure_row(row) do
    row
    |> normalize_objective_pressure_field("objective")
    |> normalize_objective_pressure_field("objective_type")
  end

  defp normalize_objective_pressure_field(row, field) do
    case Map.get(row, field) do
      value when value in [nil, ""] -> row
      value -> Map.put(row, field, objective_pressure_label(value))
    end
  end

  defp objective_pressure_label(label) when is_atom(label) do
    label
    |> Atom.to_string()
    |> objective_pressure_label()
  end

  defp objective_pressure_label(label) when is_binary(label) do
    label
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
  end

  defp objective_pressure_label(label), do: label

  defp objective_satisfaction_status(status) when is_boolean(status),
    do: if(status, do: "met", else: "unmet")

  defp objective_satisfaction_status(status) when is_atom(status),
    do: status |> objective_satisfaction_status_label() |> objective_satisfaction_status()

  defp objective_satisfaction_status(status) when is_binary(status) do
    case objective_satisfaction_status_label(status) do
      status when status in ["satisfied", "complete", "completed"] ->
        "met"

      status when status in ["unsatisfied", "not_satisfied", "not_met", "missing"] ->
        "unmet"

      status when status in ["missed", "failed", "late", "overdue", "violated", "breached"] ->
        "unmet"

      status
      when status in [
             "shortfall",
             "insufficient",
             "below_target",
             "below_threshold",
             "under_target",
             "under_threshold",
             "gap",
             "has_gap",
             "at_risk",
             "needs_replan",
             "needs_refresh",
             "requires_attention",
             "degraded",
             "behind_plan"
           ] ->
        "partial"

      status
      when status in ["candidate_found", "candidate_window_available", "viable_candidate"] ->
        "candidate_available"

      status when status in ["no_candidate", "no_window", "no_viable_candidate"] ->
        "no_candidate_window"

      status ->
        status
    end
  end

  defp objective_satisfaction_status(status), do: status

  defp objective_satisfaction_status_label(status) when is_boolean(status),
    do: if(status, do: "met", else: "unmet")

  defp objective_satisfaction_status_label(status) when is_atom(status) do
    status
    |> Atom.to_string()
    |> objective_satisfaction_status_label()
  end

  defp objective_satisfaction_status_label(status) when is_binary(status) do
    status
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
  end

  defp objective_satisfaction_status_label(status), do: status

  defp objective_satisfaction_required_collection_latency_contacts(row) do
    row
    |> objective_satisfaction_required_contacts()
    |> case do
      value when is_number(value) -> max(ceil_count(value), 1)
      _value -> 1
    end
  end

  defp objective_satisfaction_required_contacts(row) do
    explicit =
      [
        row["required_contacts"],
        row["required_count"],
        row["required_contact_count"]
      ]
      |> Enum.map(&numeric_or_nil/1)
      |> Enum.find(&is_number/1)

    explicit ||
      objective_satisfaction_contact_count(row, [
        "required_contact_ids",
        "required_contact_id",
        "required_contacts",
        "required_contact",
        "required_downlink_contact_ids",
        "required_downlink_contact_id",
        "required_downlink_contacts",
        "required_downlink_contact",
        "candidate_contact_ids",
        "candidate_contact_id",
        "candidate_contacts",
        "candidate_contact"
      ]) ||
      objective_satisfaction_required_contacts_from_score_terms(row)
  end

  defp objective_satisfaction_planned_contacts(row) do
    [
      row["planned_contacts"],
      row["selected_count"],
      row["satisfied_count"],
      row["selected_contact_count"],
      row["satisfied_contact_count"],
      row["planned_contact_count"]
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) ->
        value

      _value ->
        objective_satisfaction_contact_count(row, [
          "planned_contact_ids",
          "planned_contact_id",
          "planned_contacts",
          "planned_contact",
          "selected_contact_ids",
          "selected_contact_id",
          "selected_contacts",
          "selected_contact",
          "satisfied_contact_ids",
          "satisfied_contact_id",
          "satisfied_contacts",
          "satisfied_contact"
        ]) || 0
    end
  end

  defp objective_satisfaction_planned_downlink_mb(row) do
    [
      row["planned_downlink_mb"],
      row["selected_downlink_mb"],
      row["satisfied_downlink_mb"],
      row["planned_data_volume_mb"],
      row["selected_data_volume_mb"],
      row["satisfied_data_volume_mb"],
      row["actual_data_volume_mb"],
      row["delivered_data_volume_mb"],
      row["received_data_volume_mb"],
      row["planned_volume_mb"],
      row["selected_volume_mb"],
      row["satisfied_volume_mb"],
      row["actual_volume_mb"],
      objective_pressure_observation_context_number(row, [
        "planned_downlink_mb",
        "selected_downlink_mb",
        "satisfied_downlink_mb",
        "planned_data_volume_mb",
        "selected_data_volume_mb",
        "satisfied_data_volume_mb",
        "actual_data_volume_mb",
        "delivered_data_volume_mb",
        "received_data_volume_mb",
        "planned_volume_mb",
        "selected_volume_mb",
        "satisfied_volume_mb",
        "actual_volume_mb"
      ])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) -> value
      _value -> 0.0
    end
  end

  defp objective_satisfaction_required_downlink_mb(row) do
    explicit =
      [
        row["required_downlink_mb"],
        row["target_downlink_mb"],
        row["downlink_requirement_mb"],
        row["required_volume_mb"],
        row["required_data_volume_mb"],
        row["target_volume_mb"],
        row["target_data_volume_mb"],
        row["min_downlink_mb"],
        row["missing_downlink_mb"],
        objective_pressure_observation_context_number(row, [
          "required_downlink_mb",
          "target_downlink_mb",
          "downlink_requirement_mb",
          "required_volume_mb",
          "required_data_volume_mb",
          "target_volume_mb",
          "target_data_volume_mb",
          "min_downlink_mb",
