    ]
    |> List.flatten()
    |> Enum.map(&objective_satisfaction_contact_id/1)
    |> Enum.filter(&stable_id_string?/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
