  defp objective_satisfaction_contact_count(row, fields) do
    ids =
      row
      |> objective_satisfaction_contact_values(fields)
      |> Enum.map(&objective_satisfaction_contact_id/1)
      |> Enum.filter(&stable_id_string?/1)
      |> Enum.uniq()

    case ids do
      [] -> nil
      ids -> length(ids)
    end
  end

  defp objective_satisfaction_contact_values(row, fields) do
    fields
    |> Enum.flat_map(fn field -> List.flatten([Map.get(row, field)]) end)
    |> Enum.reject(&is_nil/1)
  end

  defp objective_satisfaction_contact_id(%{} = contact) do
    contact
    |> stringify_keys()
    |> contact_allocation_contact_identity()
  end

  defp objective_satisfaction_contact_id(value), do: encode_value(value)

  defp objective_satisfaction_pressure_reasons(row, contact_gap?, volume_gap?) do
    []
    |> maybe_append_reason(contact_gap?, "objective_satisfaction_contact_gap")
    |> maybe_append_reason(volume_gap?, "objective_satisfaction_downlink_volume_gap")
    |> maybe_append_reason(
      objective_satisfaction_score_term_downlink_gap?(row),
      "objective_satisfaction_score_term_downlink_gap"
    )
    |> maybe_append_reason(
      objective_satisfaction_score_term_contact_gap?(row),
      "objective_satisfaction_score_term_contact_gap"
    )
    |> maybe_append_reason(row["status"] not in [nil, ""], "objective_status_#{row["status"]}")
    |> Enum.reverse()
  end

  defp objective_satisfaction_collection_latency_reasons(row) do
    required_downlink_mb = objective_satisfaction_required_downlink_mb(row)
    planned_downlink_mb = objective_satisfaction_planned_downlink_mb(row)
    planned_latency_s = objective_satisfaction_planned_latency_s(row)
    max_latency_s = objective_satisfaction_max_latency_s(row)

    []
    |> maybe_append_reason(true, "collection_latency_gap")
    |> maybe_append_reason(row["status"] not in [nil, ""], "objective_status_#{row["status"]}")
    |> maybe_append_reason(
      is_number(max_latency_s) and
        (is_nil(planned_latency_s) or planned_latency_s > max_latency_s),
      "objective_satisfaction_latency_gap"
    )
    |> maybe_append_reason(
      is_number(required_downlink_mb) and required_downlink_mb > planned_downlink_mb,
      "objective_satisfaction_downlink_volume_gap"
    )
    |> maybe_append_reason(
      objective_satisfaction_score_term_downlink_gap?(row),
      "objective_satisfaction_score_term_downlink_gap"
    )
    |> maybe_append_reason(
      objective_satisfaction_score_term_contact_gap?(row),
      "objective_satisfaction_score_term_contact_gap"
    )
    |> maybe_append_reason(
      row["realized_status"] not in [nil, ""],
      "realized_downlink_#{row["realized_status"]}"
    )
    |> maybe_append_reason(
      row["contact_result"] not in [nil, ""],
      "realized_downlink_contact_result_#{row["contact_result"]}"
    )
    |> Enum.reverse()
  end

  defp objective_satisfaction_required_downlink_mb_from_score_terms(row) do
    case objective_satisfaction_score_term_downlink_gap(row) do
      gap when is_number(gap) and gap > 0.0 ->
        objective_satisfaction_planned_downlink_mb(row) + gap

      _gap ->
        nil
    end
  end

  defp objective_satisfaction_required_contacts_from_score_terms(row) do
    case objective_satisfaction_score_term_contact_gap(row) do
      gap when is_number(gap) and gap > 0.0 ->
        objective_satisfaction_planned_contacts(row) + gap

      _gap ->
        nil
    end
  end

  defp objective_satisfaction_required_observations_from_score_terms(row) do
    case objective_satisfaction_score_term_target_gap(row) do
      gap when is_number(gap) and gap > 0.0 ->
        planned_observations = objective_satisfaction_planned_observations(row)
        planned_count = planned_observations || objective_satisfaction_planned_contacts(row)

        planned_count + gap

      _gap ->
        nil
    end
  end

  defp objective_satisfaction_required_observations_from_direct_gap(row) do
    case objective_satisfaction_direct_target_gap(row) do
      gap when is_number(gap) and gap > 0.0 ->
        planned_observations = objective_satisfaction_planned_observations(row)
        planned_count = planned_observations || objective_satisfaction_planned_contacts(row)

        planned_count + gap

      _gap ->
        nil
    end
  end

  defp objective_satisfaction_score_term_downlink_gap?(row),
    do: positive_number?(objective_satisfaction_score_term_downlink_gap(row))

  defp objective_satisfaction_score_term_contact_gap?(row),
    do: positive_number?(objective_satisfaction_score_term_contact_gap(row))

  defp objective_satisfaction_score_term_target_gap?(row),
    do: positive_number?(objective_satisfaction_score_term_target_gap(row))

  defp objective_satisfaction_score_term_downlink_gap(row) do
    objective_score_term_number(row, [
      "downlink_shortfall_mb",
      "selected_downlink_shortfall_mb",
      "missing_downlink_mb",
      "downlink_completion_gap_mb",
      "required_downlink_gap_mb"
    ])
  end

  defp objective_satisfaction_score_term_contact_gap(row) do
