  defp objective_tradeoff_target_reasons(row) do
    []
    |> maybe_append_reason(true, "objective_tradeoff_target_gap")
    |> maybe_append_reason(
      objective_tradeoff_has_missed_targets?(row),
      "objective_tradeoff_missed_targets"
    )
    |> maybe_append_reason(
      objective_tradeoff_score_term_target_gap?(row),
      "objective_tradeoff_score_term_target_gap"
    )
    |> maybe_append_reason(row["selected"] == false, "objective_tradeoff_unselected")
    |> Enum.reverse()
  end

  defp objective_tradeoff_required_downlink_mb_from_score_terms(row) do
    case objective_tradeoff_score_term_downlink_gap(row) do
      gap when is_number(gap) and gap > 0.0 ->
        objective_tradeoff_planned_downlink_mb(row) + gap

      _gap ->
        nil
    end
  end

  defp objective_tradeoff_required_contacts_from_score_terms(row) do
    case objective_tradeoff_score_term_contact_gap(row) do
      gap when is_number(gap) and gap > 0.0 ->
        objective_tradeoff_planned_contacts(row) + gap

      _gap ->
        nil
    end
  end

  defp objective_tradeoff_required_observations_from_score_terms(row) do
    case objective_tradeoff_score_term_target_gap(row) do
      gap when is_number(gap) and gap > 0.0 ->
        objective_tradeoff_planned_observations(row) + gap

      _gap ->
        nil
    end
