  defp objective_tradeoff_required_observations_from_direct_gap(row) do
    case objective_tradeoff_direct_target_gap(row) do
      gap when is_number(gap) and gap > 0.0 ->
        objective_tradeoff_planned_observations(row) + gap

      _gap ->
        nil
    end
