  defp objective_tradeoff_score_term_downlink_gap?(row),
    do: positive_number?(objective_tradeoff_score_term_downlink_gap(row))

  defp objective_tradeoff_score_term_contact_gap?(row),
    do: positive_number?(objective_tradeoff_score_term_contact_gap(row))

  defp objective_tradeoff_score_term_target_gap?(row),
    do: positive_number?(objective_tradeoff_score_term_target_gap(row))

  defp objective_tradeoff_score_term_downlink_gap(row) do
    objective_tradeoff_score_term_number(row, [
      "downlink_shortfall_mb",
      "selected_downlink_shortfall_mb",
      "missing_downlink_mb",
      "downlink_completion_gap_mb",
      "required_downlink_gap_mb"
    ])
