  end

  defp objective_tradeoff_trust_boundary(row) do
    Map.get(row, "trust_boundary") ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp derived_constraint_pressure_branches(prior_plan) do
    prior_plan
    |> prior_plan_constraint_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {row, index} ->
        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> constraint_pressure_branch(source_path, index)
      end)
    end)
  end

  defp prior_plan_constraint_reports(prior_plan) do
    direct_reports =
      [
        {"source_constraint_report", "prior_plan.source_constraint_report"},
        {"constraint_report", "prior_plan.constraint_report"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        case Map.get(prior_plan, field) do
          %{} = report -> [{stringify_keys(report), source_path}]
          _report -> []
        end
      end)

    direct_reports ++ prior_plan_result_artifact_constraint_reports(prior_plan)
  end

  defp derived_mission_state_constraint_pressure_branches(mission_state) do
    mission_state
    |> mission_state_constraint_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {row, index} ->
        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> constraint_pressure_branch(source_path, index)
      end)
    end)
  end

  defp mission_state_constraint_reports(mission_state) do
    mission_state = stringify_keys(mission_state || %{})

    mission_state_constraint_reports(mission_state, [
      {"source_constraint_report", "mission_state.source_constraint_report"},
      {"constraint_report", "mission_state.constraint_report"}
    ]) ++
      mission_state_result_artifact_embedded_reports(mission_state, "source_constraint_report") ++
      mission_state_result_artifact_embedded_reports(mission_state, "constraint_report")
  end

  defp mission_state_source_constraint_reports(mission_state) do
    mission_state_constraint_reports(mission_state, [
      {"source_constraint_report", "mission_state.source_constraint_report"}
    ])
  end

  defp mission_state_canonical_constraint_reports(mission_state) do
    mission_state_constraint_reports(mission_state, [
      {"constraint_report", "mission_state.constraint_report"}
    ])
  end

  defp mission_state_constraint_reports(mission_state, fields) do
    mission_state = stringify_keys(mission_state || %{})

    fields
    |> Enum.flat_map(fn {field, source_path} ->
      mission_state
      |> Map.get(field)
      |> mission_state_source_report_entries(source_path)
    end)
  end

  defp prior_plan_result_artifact_constraint_reports(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      ["source_constraint_report", "constraint_report"]
      |> Enum.flat_map(fn report_key ->
        case Map.get(artifact, report_key) do
          %{} = report ->
            report =
              report
              |> stringify_keys()
              |> put_inherited_result_artifact_trust_boundary(artifact)

            [{report, "#{source_path}.#{report_key}"}]

          _report ->
            []
        end
      end)
    end)
  end

  defp constraint_pressure_branch(row, source_path, index) do
    row = normalize_constraint_pressure_row(row)

    row
    |> constraint_pressure_events(source_path)
    |> Enum.map(fn event ->
      identity = row["constraint_id"] || event["resource_field"] || event["type"] || index

      %{
        "id" => "derived_constraint_pressure_#{branch_id_fragment(identity)}",
        "label" => "Derived constraint pressure #{identity}",
        "events" => [event],
        "metadata" =>
          %{
            "derived_source" => source_path,
            "constraint_id" => row["constraint_id"],
            "constraint_status" => row["status"]
          }
          |> compact_map()
      }
    end)
  end

  defp disambiguate_constraint_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if constraint_pressure_branch_id?(branch_id) and Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> constraint_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("constraint_branch_base_id", branch_id)
          |> Map.put("constraint_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_constraint_suffixes()
  end

  defp constraint_pressure_branch_id?(id) when is_binary(id),
    do: String.starts_with?(id, "derived_constraint_pressure_")

  defp constraint_pressure_branch_id?(_id), do: false

  defp disambiguate_duplicate_constraint_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "constraint_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["constraint_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["constraint_branch_base_id"]}_#{suffix}")
        |> Map.update("metadata", %{}, &Map.put(&1, "constraint_branch_identity", suffix))
      else
        branch
      end
    end)
  end

  defp constraint_pressure_branch_identity(branch, index) do
    branch
    |> Map.get("events", [])
    |> List.wrap()
    |> Enum.flat_map(fn event ->
      [
        event["feedback_source"],
        event["constraint_id"],
        event["constraint_metric"],
        event["type"],
        event["spacecraft_id"],
        event["scenario_id"],
        event["resource_field"],
        event["activity_id"],
        event["source_activity_ids"],
        event["ground_station_id"],
        event["downlink_demand_sources"],
        event["downlink_completion_sources"],
        event["required_downlink_mb"],
        event["required_contacts"],
        event["starts_at_s"],
        event["ends_at_s"],
        event["trust_boundary"]
      ]
    end)
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp normalize_constraint_pressure_row(row) do
    row
    |> normalize_constraint_pressure_field("status")
    |> normalize_constraint_pressure_field("violation_severity")
    |> normalize_constraint_pressure_field("metric")
  end

  defp normalize_constraint_pressure_field(row, field) do
    case Map.get(row, field) do
      value when value in [nil, ""] -> row
      value -> Map.put(row, field, normalized_status_token(value))
    end
  end

  defp constraint_pressure_events(row, source_path) do
    cond do
      row["status"] not in ["fail", "warning"] ->
        []

      field = constraint_resource_margin_field(row["metric"]) ->
        value = constraint_resource_margin_value(row, field)

        if is_number(value) do
          [
            %{
              "type" => "resource_margin_pressure",
              "spacecraft_id" => row["spacecraft_id"] || constraint_scenario_id(row),
              "scenario_id" => constraint_scenario_id(row),
              "resource_field" => field,
              field => value,
              "#{field}_threshold" => numeric_or_nil(row["threshold"]),
              "activity_id" => row["activity_id"],
              "source_activity_ids" => constraint_source_activity_ids(row),
              "constraint_id" => row["constraint_id"],
              "constraint_metric" => row["metric"],
              "constraint_status" => row["status"],
              "violation_severity" => row["violation_severity"],
              "derivation_reasons" => [
                "constraint_report_#{row["status"]}",
                "constraint_resource_margin_pressure"
              ],
              "feedback_source" => source_path,
              "feedback_scope" => "constraint_report",
              "trust_boundary" => constraint_trust_boundary(row)
            }
            |> compact_map()
          ]
        else
          []
        end

      constraint_downlink_shortfall_metric?(row["metric"]) ->
        shortfall = constraint_downlink_shortfall(row)
        station_id = constraint_ground_station_id(row)

        if is_number(shortfall) and shortfall > 0.0 and stable_id_string?(station_id) do
          planned_downlink_mb = constraint_planned_downlink_mb(row)

          [
            %{
              "type" => "downlink_completion_gap",
              "required_downlink_mb" => constraint_required_downlink_mb(row, shortfall),
              "planned_downlink_mb" => planned_downlink_mb,
              "scenario_id" => constraint_scenario_id(row),
              "ground_station_id" => station_id,
              "starts_at_s" => constraint_window_start_s(row),
              "ends_at_s" => constraint_window_end_s(row),
              "required_contacts" => constraint_required_contacts(row),
              "planned_contacts" => constraint_planned_contacts(row),
              "source_activity_ids" => constraint_source_activity_ids(row),
              "downlink_demand_sources" => constraint_downlink_sources(row),
              "downlink_completion_sources" => constraint_downlink_sources(row),
              "constraint_id" => row["constraint_id"],
              "constraint_metric" => row["metric"],
              "constraint_status" => row["status"],
              "violation_severity" => row["violation_severity"],
              "derivation_reasons" => [
                "constraint_report_#{row["status"]}",
                "constraint_downlink_shortfall"
              ],
              "feedback_source" => source_path,
              "feedback_scope" => "constraint_report",
              "trust_boundary" => constraint_trust_boundary(row)
            }
            |> compact_map()
          ]
        else
          []
        end

      true ->
        []
    end
  end

  defp constraint_resource_margin_field("projected_storage_margin"), do: "storage_margin"
  defp constraint_resource_margin_field("min_projected_storage_margin"), do: "storage_margin"
  defp constraint_resource_margin_field("storage_margin"), do: "storage_margin"
  defp constraint_resource_margin_field("projected_fuel_margin"), do: "fuel_margin"
  defp constraint_resource_margin_field("min_projected_fuel_margin"), do: "fuel_margin"
  defp constraint_resource_margin_field("fuel_margin"), do: "fuel_margin"
  defp constraint_resource_margin_field("projected_downlink_margin"), do: "downlink_margin"
  defp constraint_resource_margin_field("min_projected_downlink_margin"), do: "downlink_margin"
  defp constraint_resource_margin_field("downlink_margin"), do: "downlink_margin"
  defp constraint_resource_margin_field("projected_power_margin"), do: "power_margin"
  defp constraint_resource_margin_field("min_projected_power_margin"), do: "power_margin"
  defp constraint_resource_margin_field("power_margin"), do: "power_margin"
  defp constraint_resource_margin_field("projected_thermal_margin_c"), do: "thermal_margin_c"
  defp constraint_resource_margin_field("min_projected_thermal_margin_c"), do: "thermal_margin_c"
  defp constraint_resource_margin_field("thermal_margin_c"), do: "thermal_margin_c"
  defp constraint_resource_margin_field(_metric), do: nil

  defp constraint_resource_margin_value(row, field) do
    [
      row["value"],
      row[field],
      row["projected_#{field}"]
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
  end

  defp constraint_downlink_shortfall_metric?(metric)
       when metric in [
              "selected_downlink_shortfall_mb",
              "max_selected_downlink_shortfall_mb",
              "downlink_shortfall_mb",
              "actual_downlink_shortfall_mb",
              "selected_data_volume_shortfall_mb",
              "max_selected_data_volume_shortfall_mb",
              "data_volume_shortfall_mb",
              "actual_data_volume_shortfall_mb",
              "missing_data_volume_mb",
              "required_data_volume_gap_mb"
            ],
       do: true

  defp constraint_downlink_shortfall_metric?(_metric), do: false

  defp constraint_downlink_shortfall(row) do
    [
      row["value"],
      row["selected_downlink_shortfall_mb"],
      row["downlink_shortfall_mb"],
      row["actual_downlink_shortfall_mb"],
      row["selected_data_volume_shortfall_mb"],
      row["data_volume_shortfall_mb"],
      row["actual_data_volume_shortfall_mb"],
      row["missing_data_volume_mb"],
      row["required_data_volume_gap_mb"],
      get_in(row, ["throughput_model", "selected_downlink_shortfall_mb"]),
      get_in(row, ["throughput_model", "downlink_shortfall_mb"]),
      get_in(row, ["throughput_model", "actual_downlink_shortfall_mb"]),
      get_in(row, ["throughput_model", "selected_data_volume_shortfall_mb"]),
      get_in(row, ["throughput_model", "data_volume_shortfall_mb"]),
      get_in(row, ["throughput_model", "actual_data_volume_shortfall_mb"]),
      get_in(row, ["throughput_model", "missing_data_volume_mb"]),
      get_in(row, ["throughput_model", "required_data_volume_gap_mb"]),
      get_in(row, ["activity_context", "selected_downlink_shortfall_mb"]),
      get_in(row, ["activity_context", "downlink_shortfall_mb"]),
      get_in(row, ["activity_context", "actual_downlink_shortfall_mb"]),
      get_in(row, ["activity_context", "selected_data_volume_shortfall_mb"]),
      get_in(row, ["activity_context", "data_volume_shortfall_mb"]),
      get_in(row, ["activity_context", "actual_data_volume_shortfall_mb"]),
      get_in(row, ["activity_context", "missing_data_volume_mb"]),
      get_in(row, ["activity_context", "required_data_volume_gap_mb"]),
      get_in(row, ["source_contact", "selected_downlink_shortfall_mb"]),
      get_in(row, ["source_contact", "downlink_shortfall_mb"]),
      get_in(row, ["source_contact", "actual_downlink_shortfall_mb"]),
      get_in(row, ["source_contact", "selected_data_volume_shortfall_mb"]),
      get_in(row, ["source_contact", "data_volume_shortfall_mb"]),
      get_in(row, ["source_contact", "actual_data_volume_shortfall_mb"]),
      get_in(row, ["source_contact", "missing_data_volume_mb"]),
      get_in(row, ["source_contact", "required_data_volume_gap_mb"]),
      get_in(row, ["source_contact", "throughput_model", "selected_downlink_shortfall_mb"]),
      get_in(row, ["source_contact", "throughput_model", "downlink_shortfall_mb"]),
      get_in(row, ["source_contact", "throughput_model", "actual_downlink_shortfall_mb"]),
