        "duplicate_exclusivity_timeline_ids" => summary["duplicate_exclusivity_timeline_ids"],
        "allow_overlap" => summary["allow_overlap"],
        "invalid_activity_input" => summary["invalid_activity_input"],
        "invalid_activity_input_reason" => summary["invalid_activity_input_reason"],
        "feedback_source" => source_path,
        "feedback_scope" => "timeline_activity_precondition",
        "feedback_key" => activity_id || timeline_id,
        "trust_boundary" => operator_review_trust_boundary(summary),
        "requires_operator_review" =>
          summary["precondition_status"] in ["blocked", "review_required"] or
            summary["invalid_activity_input"] == true,
        "required_operator_action" => timeline_activity_precondition_required_action(summary),
        "derivation_reasons" => ["timeline_activity_precondition_summary_pressure"],
        "assumptions" => %{
          "activity_precondition_evaluation" => "not_performed_by_strategy_branch",
          "timeline_mutation" => "not_performed_by_strategy_branch",
          "operator_authority" => "not_granted_by_strategy_branch",
          "resource_authority" => "not_reserved_by_strategy_branch",
          "cadence_import" => "not_performed_by_strategy_branch",
          "command_execution" => "not_performed_by_strategy_branch"
        }
      }
      |> Map.merge(context)
      |> compact_map()
    end
  end

  defp put_row_derived_timeline_activity_precondition_pressure(summary) do
    rows = timeline_activity_precondition_summary_rows(summary)

    if rows == [] do
      summary
    else
      blocked_count =
        timeline_activity_precondition_rows_pressure_count(
          rows,
          "blocked"
        )

      review_count =
        timeline_activity_precondition_rows_pressure_count(
          rows,
          "review_required"
        )

      summary
      |> Map.put(
        "precondition_status",
        timeline_activity_precondition_rows_status(summary, blocked_count, review_count)
      )
      |> Map.put("blocked_precondition_count", blocked_count)
      |> Map.put("review_precondition_count", review_count)
      |> Map.put(
        "blocked_precondition_types",
        timeline_activity_precondition_rows_pressure_types(
          rows,
          "blocked"
        )
      )
      |> Map.put(
        "review_precondition_types",
        timeline_activity_precondition_rows_pressure_types(
          rows,
          "review_required"
        )
      )
    end
  end

  defp timeline_activity_precondition_summary_rows(%{"preconditions" => rows})
       when is_list(rows) do
    timeline_activity_precondition_rows(rows)
  end

  defp timeline_activity_precondition_summary_rows(%{"rows" => rows}) when is_list(rows) do
    rows = timeline_activity_precondition_rows(rows)

    precondition_rows =
      rows
      |> Enum.flat_map(&List.wrap(&1["preconditions"]))
      |> timeline_activity_precondition_rows()

    if precondition_rows == [], do: rows, else: precondition_rows
  end

  defp timeline_activity_precondition_summary_rows(_summary), do: []

  defp timeline_activity_precondition_rows(rows) do
    rows
    |> Enum.filter(&is_map/1)
    |> Enum.map(&stringify_keys/1)
  end

  defp timeline_activity_precondition_rows_pressure_count(rows, status) do
    rows
    |> Enum.count(&(timeline_activity_precondition_row_status(&1) == status))
  end

  defp timeline_activity_precondition_rows_pressure_types(rows, status) do
    rows
    |> Enum.filter(&(timeline_activity_precondition_row_status(&1) == status))
    |> Enum.map(& &1["type"])
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp timeline_activity_precondition_row_status(row),
    do: row["status"] || row["precondition_status"]

  defp timeline_activity_precondition_rows_status(summary, blocked_count, review_count) do
    cond do
      blocked_count > 0 -> "blocked"
      review_count > 0 or summary["invalid_activity_input"] == true -> "review_required"
      true -> "clear"
    end
  end

  defp timeline_activity_precondition_pressure?(summary) do
    summary["precondition_status"] in ["blocked", "review_required"] or
      positive_count?(summary["blocked_precondition_count"]) or
      positive_count?(summary["review_precondition_count"]) or
      summary["invalid_activity_input"] == true or
      nonempty_pressure_value?(summary["blocked_precondition_types"]) or
      nonempty_pressure_value?(summary["review_precondition_types"]) or
      nonempty_pressure_value?(summary["dependency_activity_ids"]) or
      nonempty_pressure_value?(summary["dependency_timeline_ids"]) or
      nonempty_pressure_value?(summary["exclusive_with_activity_ids"]) or
      nonempty_pressure_value?(summary["exclusive_with_timeline_ids"]) or
      nonempty_pressure_value?(summary["duplicate_dependency_activity_ids"]) or
      nonempty_pressure_value?(summary["duplicate_dependency_timeline_ids"]) or
      nonempty_pressure_value?(summary["duplicate_exclusivity_activity_ids"]) or
      nonempty_pressure_value?(summary["duplicate_exclusivity_timeline_ids"]) or
      summary["allow_overlap"] == true
  end

  defp timeline_activity_precondition_required_action(%{
         "invalid_activity_input" => true
       }),
       do: "review_invalid_activity_input"

  defp timeline_activity_precondition_required_action(%{"precondition_status" => "blocked"}),
    do: "review_blocked_activity_precondition"

  defp timeline_activity_precondition_required_action(%{
         "precondition_status" => "review_required"
       }),
       do: "review_activity_precondition"

  defp timeline_activity_precondition_required_action(_summary),
    do: "record_activity_precondition"

  defp timeline_activity_precondition_pressure_context(summary) do
    %{
      "timeline_identity" => summary["timeline_identity"],
      "activity_context" => summary["activity_context"],
      "preconditions" => summary["preconditions"],
      "dependency_activity_ids" => summary["dependency_activity_ids"],
      "dependency_timeline_ids" => summary["dependency_timeline_ids"],
      "exclusive_with_activity_ids" => summary["exclusive_with_activity_ids"],
      "exclusive_with_timeline_ids" => summary["exclusive_with_timeline_ids"],
      "duplicate_dependency_activity_ids" => summary["duplicate_dependency_activity_ids"],
      "duplicate_dependency_timeline_ids" => summary["duplicate_dependency_timeline_ids"],
      "duplicate_exclusivity_activity_ids" => summary["duplicate_exclusivity_activity_ids"],
      "duplicate_exclusivity_timeline_ids" => summary["duplicate_exclusivity_timeline_ids"],
      "allow_overlap" => summary["allow_overlap"],
      "source_activity" => summary["source_activity"]
    }
    |> reject_empty_values()
  end

  defp timeline_preservation_pressure_branch(row, source_path, index) do
    case timeline_preservation_pressure_event(row, source_path) do
      nil ->
        []

      event ->
        identity = row["activity_id"] || row["timeline_id"] || event["feedback_key"] || index

        [
          %{
            "id" => "derived_timeline_preservation_pressure_#{branch_id_fragment(identity)}",
            "label" => "Derived timeline preservation pressure #{identity}",
            "events" => [event],
            "metadata" =>
              %{
                "derived_source" => source_path,
                "activity_id" => event["activity_id"],
                "timeline_id" => event["timeline_id"],
                "timeline_preservation_status" => event["timeline_preservation_status"],
                "protection_decision" => event["protection_decision"],
                "protection_category" => event["protection_category"],
                "protection_reason" => event["protection_reason"]
              }
              |> compact_map()
          }
        ]
    end
  end

  defp timeline_preservation_pressure_event(row, source_path) do
    row = stringify_keys(row)
    context = timeline_preservation_pressure_context(row)
    activity_id = row["activity_id"] || get_in(row, ["timeline_identity", "activity_id"])
    timeline_id = row["timeline_id"] || get_in(row, ["timeline_identity", "timeline_id"])
    timeline_preservation_status = timeline_preservation_effective_status(row)

    requires_preservation =
      timeline_preservation_requires_preservation?(row, timeline_preservation_status)

    requires_operator_review =
      timeline_preservation_requires_operator_review?(row, timeline_preservation_status)

    if context == %{} or not timeline_preservation_pressure?(row) do
      nil
    else
      %{
        "type" => "timeline_preservation_pressure",
        "activity_id" => activity_id,
        "timeline_id" => timeline_id,
        "timeline_preservation_status" => timeline_preservation_status,
        "requires_preservation" => requires_preservation,
        "requires_operator_review" => requires_operator_review,
        "status" => row["status"],
        "approval_status" => row["approval_status"],
        "locked" => row["locked"],
        "approved" => row["approved"],
        "protection_decision" => row["protection_decision"],
        "protection_category" => row["protection_category"],
        "protection_reason" => row["protection_reason"] || row["reason"],
        "activity_count" => row["activity_count"],
        "preserve_activity_count" => row["preserve_activity_count"],
        "review_change_activity_count" => row["review_change_activity_count"],
        "preservation_sensitive_activity_count" => row["preservation_sensitive_activity_count"],
        "preserve_activity_ids" => row["preserve_activity_ids"],
        "preserve_timeline_ids" => row["preserve_timeline_ids"],
        "review_change_activity_ids" => row["review_change_activity_ids"],
        "review_change_timeline_ids" => row["review_change_timeline_ids"],
        "preservation_sensitive_activity_ids" => row["preservation_sensitive_activity_ids"],
        "preservation_sensitive_timeline_ids" => row["preservation_sensitive_timeline_ids"],
        "invalid_activity_input" => row["invalid_activity_input"],
        "invalid_activity_input_reason" => row["invalid_activity_input_reason"],
        "feedback_source" => source_path,
        "feedback_scope" => "timeline_preservation",
        "feedback_key" => activity_id || timeline_id || row["source"],
        "trust_boundary" => operator_review_trust_boundary(row),
        "required_operator_action" =>
          timeline_preservation_required_action(
            Map.merge(row, %{
              "timeline_preservation_status" => timeline_preservation_status,
              "requires_preservation" => requires_preservation,
              "requires_operator_review" => requires_operator_review
            })
          ),
        "derivation_reasons" => ["timeline_preservation_pressure"],
        "assumptions" => %{
          "timeline_preservation_application" => "not_performed_by_strategy_branch",
          "timeline_mutation" => "not_performed_by_strategy_branch",
          "operator_authority" => "not_granted_by_strategy_branch",
          "cadence_import" => "not_performed_by_strategy_branch",
          "command_execution" => "not_performed_by_strategy_branch"
        }
      }
      |> Map.merge(context)
      |> compact_map()
    end
  end

  defp timeline_preservation_effective_status(%{"invalid_activity_input" => true}),
    do: "review_required"

  defp timeline_preservation_effective_status(%{"requires_operator_review" => true}),
    do: "review_required"

  defp timeline_preservation_effective_status(%{"protection_decision" => "review_change"}),
    do: "review_required"

  defp timeline_preservation_effective_status(%{
         "timeline_preservation_status" => status
       })
       when status in ["review_required", "preservation_required"],
       do: status

  defp timeline_preservation_effective_status(%{"requires_preservation" => true}),
    do: "preservation_required"

  defp timeline_preservation_effective_status(%{"protection_decision" => "preserve"}),
    do: "preservation_required"

  defp timeline_preservation_effective_status(%{"timeline_preservation_status" => status}),
    do: status

  defp timeline_preservation_effective_status(_row), do: nil

  defp timeline_preservation_requires_preservation?(row, timeline_preservation_status) do
    row["requires_preservation"] == true or
      timeline_preservation_status == "preservation_required"
  end

  defp timeline_preservation_requires_operator_review?(row, timeline_preservation_status) do
    row["requires_operator_review"] == true or
      timeline_preservation_status == "review_required" or
      row["protection_decision"] == "review_change" or
      row["invalid_activity_input"] == true
  end

  defp timeline_preservation_pressure?(row) do
    row["timeline_preservation_status"] in ["review_required", "preservation_required"] or
      row["requires_preservation"] == true or
      row["requires_operator_review"] == true or
      row["protection_decision"] in ["preserve", "review_change"] or
      row["invalid_activity_input"] == true or
      positive_count?(row["preserve_activity_count"]) or
      positive_count?(row["review_change_activity_count"]) or
      positive_count?(row["preservation_sensitive_activity_count"]) or
      pressure_count_map?(row["protection_decision_counts"], ["mutable"]) or
      nonempty_pressure_value?(row["preserve_activity_ids"]) or
      nonempty_pressure_value?(row["preserve_timeline_ids"]) or
      nonempty_pressure_value?(row["review_change_activity_ids"]) or
      nonempty_pressure_value?(row["review_change_timeline_ids"]) or
      nonempty_pressure_value?(row["preservation_sensitive_activity_ids"]) or
      nonempty_pressure_value?(row["preservation_sensitive_timeline_ids"])
  end

  defp timeline_preservation_required_action(%{"invalid_activity_input" => true}),
    do: "review_invalid_activity_input"

  defp timeline_preservation_required_action(%{"requires_operator_review" => true}),
    do: "review_timeline_preservation"

  defp timeline_preservation_required_action(%{
         "timeline_preservation_status" => "review_required"
       }),
       do: "review_timeline_preservation"

  defp timeline_preservation_required_action(%{"protection_decision" => "review_change"}),
    do: "review_timeline_preservation"

  defp timeline_preservation_required_action(_row), do: "record_timeline_preservation"

  defp timeline_preservation_pressure_context(row) do
    %{
      "timeline_identity" => row["timeline_identity"],
      "protection_decision_counts" => stringify_keys(row["protection_decision_counts"] || %{}),
      "protection_category_counts" => stringify_keys(row["protection_category_counts"] || %{}),
      "protection_reason_counts" => stringify_keys(row["protection_reason_counts"] || %{}),
      "activity_id_sets_by_protection_decision" => row["activity_id_sets_by_protection_decision"],
      "timeline_id_sets_by_protection_decision" => row["timeline_id_sets_by_protection_decision"],
      "activity_id_sets_by_protection_category" => row["activity_id_sets_by_protection_category"],
      "timeline_id_sets_by_protection_category" => row["timeline_id_sets_by_protection_category"],
      "activity_id_sets_by_protection_reason" => row["activity_id_sets_by_protection_reason"],
      "timeline_id_sets_by_protection_reason" => row["timeline_id_sets_by_protection_reason"],
      "assumptions" => row["assumptions"],
      "source" => row["source"]
    }
    |> reject_empty_values()
  end

  defp pressure_count_map?(counts, ignored_keys) do
    (counts || %{})
    |> stringify_keys()
    |> Enum.any?(fn {key, value} -> key not in ignored_keys and positive_count?(value) end)
  end

  defp nonempty_pressure_actions?(actions, ignored_actions) do
    actions
    |> List.wrap()
    |> Enum.map(&encode_value/1)
    |> Enum.any?(&(is_binary(&1) and &1 != "" and &1 not in ignored_actions))
  end

  defp positive_count?(value) do
    case numeric_or_nil(value) do
      count when is_number(count) -> count > 0
      _count -> false
    end
  end

  defp nonempty_pressure_value?(value) when is_list(value), do: value != []
  defp nonempty_pressure_value?(%{} = value), do: map_size(value) > 0
  defp nonempty_pressure_value?(_value), do: false

  defp timeline_diff_pressure_branch(row, source_path, index, policy \\ %{}) do
    row = normalize_timeline_diff_pressure_row(row)

    row
    |> timeline_diff_pressure_events(source_path, policy)
    |> Enum.map(fn event ->
      status = row["diff_status"] || "review"

      identity =
        row["source_activity_id"] || row["timeline_id"] || event["target_id"] || event["type"] ||
          index

      %{
        "id" =>
          "derived_timeline_diff_#{branch_id_fragment(status)}_#{branch_id_fragment(identity)}",
        "label" => "Derived timeline diff #{status} #{identity}",
        "events" => [event],
        "metadata" =>
          %{
            "derived_source" => source_path,
            "timeline_id" => row["timeline_id"],
            "diff_status" => row["diff_status"],
            "application_status" => row["application_status"],
            "selected_activity_source" => row["selected_activity_source"]
          }
          |> compact_map()
      }
    end)
  end

  defp disambiguate_timeline_diff_pressure_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if timeline_diff_pressure_branch_id?(branch_id) and Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> timeline_diff_pressure_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("timeline_diff_branch_base_id", branch_id)
          |> Map.put("timeline_diff_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_timeline_diff_suffixes()
  end

  defp timeline_diff_pressure_branch_id?(id) when is_binary(id),
    do: String.starts_with?(id, "derived_timeline_diff_")

  defp timeline_diff_pressure_branch_id?(_id), do: false

