  defp normalize_timeline_diff_pressure_row(row) do
    row
    |> normalize_timeline_diff_pressure_field("diff_status")
    |> normalize_timeline_diff_pressure_field("source_status")
    |> normalize_timeline_diff_pressure_field("replacement_status")
    |> normalize_timeline_diff_pressure_field("source_activity_type")
    |> normalize_timeline_diff_pressure_field("replacement_activity_type")
    |> normalize_timeline_diff_pressure_field("source_direction")
    |> normalize_timeline_diff_pressure_field("replacement_direction")
    |> normalize_timeline_diff_changed_fields()
    |> normalize_timeline_diff_activity_context("source_activity_context")
    |> normalize_timeline_diff_activity_context("replacement_activity_context")
  end

  defp normalize_timeline_diff_pressure_field(row, field) do
    case Map.get(row, field) do
      value when value in [nil, ""] -> row
      value -> Map.put(row, field, normalized_status_token(value))
    end
  end

  defp normalize_timeline_diff_changed_fields(%{"changed_fields" => fields} = row)
       when is_list(fields) do
    fields =
      fields
      |> Enum.map(&normalized_status_token/1)
      |> Enum.reject(&(&1 in [nil, ""]))

    Map.put(row, "changed_fields", fields)
  end

  defp normalize_timeline_diff_changed_fields(row), do: row

  defp normalize_timeline_diff_activity_context(row, field) do
    case Map.get(row, field) do
      %{} = context ->
        context =
          context
          |> stringify_keys()
          |> normalize_timeline_diff_pressure_field("type")
          |> normalize_timeline_diff_pressure_field("activity_type")
          |> normalize_timeline_diff_pressure_field("direction")
          |> normalize_timeline_diff_pressure_field("status")

        Map.put(row, field, context)

      _context ->
        row
    end
  end

  defp timeline_diff_pressure_events(row, source_path, policy) do
    cond do
      timeline_diff_removed_pressure_row?(row) ->
        row
        |> timeline_diff_removed_activity_type()
        |> case do
          "observe" ->
            [timeline_diff_removed_observation_event(row, source_path)]

          type
          when type in [
                 "downlink",
                 "tracking",
                 "command",
                 "health_check",
                 "maneuver",
                 "impulsive_burn",
                 "planned_contact",
                 "contact"
               ] ->
            cond do
              timeline_diff_removed_downlink?(row) ->
                [timeline_diff_removed_downlink_event(row, source_path)]

              timeline_diff_removed_command?(row) ->
                [timeline_diff_removed_command_event(row, source_path)]

              timeline_diff_removed_contact?(row) ->
                [timeline_diff_removed_contact_event(row, source_path)]

              timeline_diff_removed_maneuver?(row) ->
                [timeline_diff_removed_maneuver_event(row, source_path)]

              true ->
                []
            end

          _type ->
            []
        end

      timeline_diff_changed_downlink_pressure_row?(row) ->
        [timeline_diff_changed_downlink_event(row, source_path)] ++
          timeline_diff_changed_contact_identity_events(row, source_path) ++
          timeline_diff_changed_resource_identity_events(row, source_path) ++
          timeline_diff_changed_station_throughput_events(row, source_path, policy) ++
          timeline_diff_changed_link_quality_events(row, source_path) ++
          timeline_diff_changed_collection_latency_events(row, source_path) ++
          timeline_diff_changed_resource_margin_events(row, source_path, policy) ++
          timeline_diff_changed_resource_availability_events(row, source_path)

      timeline_diff_changed_contact_pressure_row?(row) ->
        [timeline_diff_changed_contact_event(row, source_path)] ++
          timeline_diff_changed_contact_identity_events(row, source_path) ++
          timeline_diff_changed_resource_identity_events(row, source_path) ++
          timeline_diff_changed_station_throughput_events(row, source_path, policy) ++
          timeline_diff_changed_link_quality_events(row, source_path) ++
          timeline_diff_changed_collection_latency_events(row, source_path) ++
          timeline_diff_changed_resource_margin_events(row, source_path, policy) ++
          timeline_diff_changed_resource_availability_events(row, source_path)

      timeline_diff_changed_observation_pressure_row?(row, policy) ->
        timeline_diff_changed_observation_events(row, source_path, policy) ++
          timeline_diff_changed_resource_identity_events(row, source_path) ++
          timeline_diff_changed_collection_latency_events(row, source_path) ++
          timeline_diff_changed_resource_margin_events(row, source_path, policy) ++
          timeline_diff_changed_resource_availability_events(row, source_path)

      timeline_diff_changed_command_pressure_row?(row) ->
        [timeline_diff_changed_command_event(row, source_path)] ++
          timeline_diff_changed_command_identity_events(row, source_path) ++
          timeline_diff_changed_resource_identity_events(row, source_path) ++
          timeline_diff_changed_resource_margin_events(row, source_path, policy) ++
          timeline_diff_changed_resource_availability_events(row, source_path)

      timeline_diff_changed_maneuver_pressure_row?(row) ->
        timeline_diff_changed_maneuver_events(row, source_path) ++
          timeline_diff_changed_resource_identity_events(row, source_path) ++
          timeline_diff_changed_resource_margin_events(row, source_path, policy) ++
          timeline_diff_changed_resource_availability_events(row, source_path)

      timeline_diff_changed_resource_margin_pressure_row?(row, policy) ->
        timeline_diff_changed_resource_margin_events(row, source_path, policy)

      timeline_diff_changed_resource_availability_pressure_row?(row) ->
        timeline_diff_changed_resource_availability_events(row, source_path)

      timeline_diff_changed_command_identity_pressure_row?(row) ->
        timeline_diff_changed_command_identity_events(row, source_path) ++
          timeline_diff_changed_resource_identity_events(row, source_path)

      timeline_diff_changed_resource_identity_pressure_row?(row) ->
        timeline_diff_changed_resource_identity_events(row, source_path)

      timeline_diff_changed_station_throughput_pressure_row?(row, policy) ->
        timeline_diff_changed_station_throughput_events(row, source_path, policy)

      timeline_diff_changed_link_quality_pressure_row?(row) ->
        timeline_diff_changed_link_quality_events(row, source_path)

      timeline_diff_changed_contact_identity_pressure_row?(row) ->
        timeline_diff_changed_contact_identity_events(row, source_path)

      timeline_diff_changed_collection_latency_pressure_row?(row) ->
        timeline_diff_changed_collection_latency_events(row, source_path)

      true ->
        []
    end
    |> Enum.map(&Map.merge(&1, timeline_diff_application_context(row)))
    |> Enum.map(&compact_map/1)
  end

  defp timeline_diff_application_context(row) do
    %{
      "approval_status" => row["approval_status"],
      "application_status" => row["application_status"],
      "selected_activity_source" => row["selected_activity_source"],
      "selected_activity" => row["selected_activity"],
      "source_timeline_application" => row["source_timeline_application"],
      "timeline_identity_collision" => row["timeline_identity_collision"],
      "duplicate_timeline_identity_scope" => row["duplicate_timeline_identity_scope"],
      "source_duplicate_activity_count" => row["source_duplicate_activity_count"],
      "replacement_duplicate_activity_count" => row["replacement_duplicate_activity_count"],
      "source_duplicate_activity_ids" => row["source_duplicate_activity_ids"],
      "replacement_duplicate_activity_ids" => row["replacement_duplicate_activity_ids"],
      "source_duplicate_activities" => row["source_duplicate_activities"],
      "replacement_duplicate_activities" => row["replacement_duplicate_activities"],
      "policy_classification" => row["policy_classification"],
      "policy_bundle_id" => row["policy_bundle_id"],
      "source_policy_decision" => row["source_policy_decision"],
      "approval_requirements" => row["approval_requirements"],
      "approval_rule_matches" => row["approval_rule_matches"]
    }
    |> compact_map()
  end

  defp timeline_diff_removed_pressure_row?(row) do
    row["diff_status"] == "removed" and row["source_status"] not in @realized_completion_statuses
  end

  defp timeline_diff_removed_activity_type(row) do
    row["source_activity_type"] ||
      get_in(row, ["source_activity_context", "activity_type"]) ||
      get_in(row, ["source_activity_context", "type"])
  end

  defp timeline_diff_removed_downlink?(row) do
    type = timeline_diff_removed_activity_type(row)
    direction = row["source_direction"] || get_in(row, ["source_activity_context", "direction"])

    type == "downlink" or (type in ["planned_contact", "contact"] and direction == "downlink")
  end

  defp timeline_diff_removed_contact?(row) do
    type = timeline_diff_removed_activity_type(row)
    direction = row["source_direction"] || get_in(row, ["source_activity_context", "direction"])

    type == "tracking" or (type in ["planned_contact", "contact"] and direction == "tracking")
  end

  defp timeline_diff_removed_command?(row) do
    type = timeline_diff_removed_activity_type(row)
    direction = row["source_direction"] || get_in(row, ["source_activity_context", "direction"])

    type in ["command", "health_check"] or
      (type in ["planned_contact", "contact"] and
         direction in ["command", "uplink", "health_check"])
  end

  defp timeline_diff_removed_maneuver?(row) do
    type = timeline_diff_removed_activity_type(row)

    operational_kind =
      row["source_operational_kind"] ||
        get_in(row, ["source_activity_context", "operational_kind"])

    type in ["maneuver", "impulsive_burn"] or operational_kind == "maneuver"
  end

  defp timeline_diff_changed_resource_margin_pressure_row?(row, policy) do
    row["diff_status"] == "changed" and
      timeline_diff_changed_resource_margin_events(row, "timeline_diff", policy) != []
  end

  defp timeline_diff_changed_resource_margin_events(row, source_path, policy) do
    evidence = timeline_diff_changed_resource_margin_evidence(row)
    spacecraft_id = timeline_diff_changed_resource_spacecraft_id(row, evidence)

    ["fuel_margin", "power_margin", "storage_margin", "downlink_margin", "thermal_margin_c"]
    |> Enum.flat_map(fn field ->
      value = numeric_or_nil(evidence[field])
      threshold = timeline_diff_changed_resource_margin_threshold(evidence, policy, field)

      if is_number(value) and is_number(threshold) and value <= threshold do
        [
          timeline_diff_changed_resource_margin_event(
            row,
            source_path,
            evidence,
            spacecraft_id,
            field,
            value,
            threshold
          )
        ]
      else
        []
      end
    end)
  end

  defp timeline_diff_changed_resource_margin_evidence(row) do
    [
      timeline_diff_changed_side_resource_margin_evidence(row, "source"),
      row,
      timeline_diff_changed_side_resource_margin_evidence(row, "replacement")
    ]
    |> Enum.reduce(%{}, fn evidence, merged ->
      evidence =
        evidence
        |> stringify_keys()
        |> normalize_resource_margin_aliases()
        |> compact_map()

      Map.merge(merged, evidence)
    end)
  end

  defp timeline_diff_changed_side_resource_margin_evidence(row, side) do
    context = stringify_keys(row["#{side}_activity_context"] || %{})

    context
    |> put_default_if_present("spacecraft_id", row["#{side}_spacecraft_id"])
    |> put_default_if_present("fuel_margin", row["#{side}_fuel_margin"])
    |> put_default_if_present("fuel_margin_threshold", row["#{side}_fuel_margin_threshold"])
    |> put_default_if_present("power_margin", row["#{side}_power_margin"])
    |> put_default_if_present("battery_state_of_charge", row["#{side}_battery_state_of_charge"])
    |> put_default_if_present("power_margin_threshold", row["#{side}_power_margin_threshold"])
    |> put_default_if_present("storage_margin", row["#{side}_storage_margin"])
    |> put_default_if_present("storage_margin_threshold", row["#{side}_storage_margin_threshold"])
    |> put_default_if_present("downlink_margin", row["#{side}_downlink_margin"])
    |> put_default_if_present("downlink_capacity_margin", row["#{side}_downlink_capacity_margin"])
    |> put_default_if_present(
      "downlink_margin_threshold",
      row["#{side}_downlink_margin_threshold"]
    )
    |> put_default_if_present(
      "downlink_capacity_margin_threshold",
      row["#{side}_downlink_capacity_margin_threshold"]
    )
    |> put_default_if_present("thermal_margin_c", row["#{side}_thermal_margin_c"])
    |> put_default_if_present(
      "thermal_margin_c_threshold",
      row["#{side}_thermal_margin_c_threshold"]
    )
    |> put_default_if_present("thermal_margin_threshold", row["#{side}_thermal_margin_threshold"])
    |> put_default_if_present("temperature_c", row["#{side}_temperature_c"])
    |> put_default_if_present("actual_temperature_c", row["#{side}_actual_temperature_c"])
    |> put_default_if_present("measured_temperature_c", row["#{side}_measured_temperature_c"])
    |> put_default_if_present("planned_temperature_c", row["#{side}_planned_temperature_c"])
    |> put_default_if_present(
      "min_operating_temperature_c",
      row["#{side}_min_operating_temperature_c"]
    )
    |> put_default_if_present(
      "max_operating_temperature_c",
      row["#{side}_max_operating_temperature_c"]
    )
    |> put_default_if_present(
      "minimum_operating_temperature_c",
      row["#{side}_minimum_operating_temperature_c"]
    )
    |> put_default_if_present(
      "maximum_operating_temperature_c",
      row["#{side}_maximum_operating_temperature_c"]
    )
    |> put_default_if_present("min_temperature_c", row["#{side}_min_temperature_c"])
    |> put_default_if_present("max_temperature_c", row["#{side}_max_temperature_c"])
    |> put_default_if_present("thermal_status", row["#{side}_thermal_status"])
    |> put_default_if_present("thermal_model", row["#{side}_thermal_model"])
    |> put_default_if_present("thermal_source", row["#{side}_thermal_source"])
    |> put_default_if_present("thermal_confidence", row["#{side}_thermal_confidence"])
  end

  defp timeline_diff_changed_resource_margin_threshold(evidence, policy, field) do
    field
    |> timeline_diff_changed_resource_margin_threshold_keys()
    |> Enum.map(&(numeric_or_nil(evidence[&1]) || numeric_or_nil(policy[&1])))
    |> Enum.find(&is_number/1)
  end

  defp timeline_diff_changed_resource_margin_threshold_keys("thermal_margin_c"),
    do: ["thermal_margin_c_threshold", "thermal_margin_threshold"]

  defp timeline_diff_changed_resource_margin_threshold_keys(field),
    do: ["#{field}_threshold"]

  defp timeline_diff_changed_resource_spacecraft_id(row, evidence) do
    evidence["spacecraft_id"] ||
      row["spacecraft_id"] ||
      row["scenario_id"] ||
      get_in(row, ["replacement_activity_context", "spacecraft_id"]) ||
      get_in(row, ["replacement_activity_context", "scenario_id"]) ||
      get_in(row, ["source_activity_context", "spacecraft_id"]) ||
      get_in(row, ["source_activity_context", "scenario_id"])
  end

  defp timeline_diff_changed_resource_margin_event(
         row,
         source_path,
         evidence,
         spacecraft_id,
         field,
         value,
         threshold
       ) do
    %{
      "type" => "resource_margin_pressure",
      "scenario_id" => row["scenario_id"],
      "spacecraft_id" => spacecraft_id,
      "resource_field" => field,
      field => value * 1.0,
      "#{field}_threshold" => threshold,
      "temperature_c" => evidence["temperature_c"],
      "actual_temperature_c" => evidence["actual_temperature_c"],
      "measured_temperature_c" => evidence["measured_temperature_c"],
      "planned_temperature_c" => evidence["planned_temperature_c"],
      "min_operating_temperature_c" => evidence["min_operating_temperature_c"],
      "max_operating_temperature_c" => evidence["max_operating_temperature_c"],
      "thermal_status" => evidence["thermal_status"],
      "thermal_model" => evidence["thermal_model"],
      "thermal_source" => evidence["thermal_source"],
      "thermal_confidence" => evidence["thermal_confidence"],
      "starts_at_s" => timeline_diff_changed_window_start_s(row),
      "ends_at_s" => timeline_diff_changed_window_end_s(row),
      "source_activity_id" => row["source_activity_id"],
      "replacement_activity_id" => row["replacement_activity_id"],
      "source_activity_ids" => timeline_diff_changed_source_activity_ids(row),
      "timeline_id" => row["timeline_id"],
      "diff_status" => row["diff_status"],
      "changed_fields" => row["changed_fields"],
      "required_operator_action" => row["required_operator_action"],
      "status_transition" => timeline_diff_changed_status_transition(row),
      "transition_type" => timeline_diff_changed_transition_field(row, "transition_type"),
      "transition_category" => timeline_diff_changed_transition_field(row, "transition_category"),
      "transition_reason" => timeline_diff_changed_transition_reason(row),
      "requires_operator_review" =>
        timeline_diff_changed_transition_field(row, "requires_operator_review"),
      "derivation_reasons" => [
        "timeline_diff_changed_activity",
        "timeline_diff_changed_resource_margin",
        "#{field}_timeline_diff_low"
      ],
      "feedback_source" => source_path,
      "feedback_scope" => "timeline_diff",
      "feedback_key" => spacecraft_id,
      "trust_boundary" => timeline_diff_trust_boundary(row)
    }
    |> compact_map()
  end

  defp timeline_diff_changed_resource_availability_pressure_row?(row) do
    row["diff_status"] == "changed" and
      timeline_diff_changed_resource_availability_events(row, "timeline_diff") != []
  end

  defp timeline_diff_changed_resource_availability_events(row, source_path) do
    evidence = timeline_diff_changed_resource_availability_evidence(row)
    spacecraft_id = timeline_diff_changed_resource_availability_spacecraft_id(row, evidence)

    ["spacecraft_available", "payload_available", "antenna_available"]
    |> Enum.filter(&(Map.get(evidence, &1) == false))
    |> Enum.map(fn field ->
      timeline_diff_changed_resource_availability_event(
        row,
        source_path,
        evidence,
        spacecraft_id,
        field
      )
    end)
  end

  defp timeline_diff_changed_resource_availability_evidence(row) do
    [
      timeline_diff_changed_side_resource_availability_evidence(row, "source"),
      row,
      timeline_diff_changed_side_resource_availability_evidence(row, "replacement")
    ]
    |> Enum.reduce(%{}, fn evidence, merged ->
      evidence =
        evidence
        |> stringify_keys()
        |> normalize_resource_availability_aliases()
        |> compact_map()

      Map.merge(merged, evidence)
    end)
  end

  defp timeline_diff_changed_side_resource_availability_evidence(row, side) do
    context = stringify_keys(row["#{side}_activity_context"] || %{})

    context
    |> put_default_if_present("spacecraft_id", row["#{side}_spacecraft_id"])
    |> put_default_if_present("spacecraft_available", row["#{side}_spacecraft_available"])
    |> put_default_if_present("spacecraft_available?", row["#{side}_spacecraft_available?"])
    |> put_default_if_present("spacecraft_availability", row["#{side}_spacecraft_availability"])
    |> put_default_if_present("payload_available", row["#{side}_payload_available"])
    |> put_default_if_present("payload_available?", row["#{side}_payload_available?"])
    |> put_default_if_present("payload_status", row["#{side}_payload_status"])
    |> put_default_if_present("antenna_available", row["#{side}_antenna_available"])
    |> put_default_if_present("antenna_available?", row["#{side}_antenna_available?"])
    |> put_default_if_present("antenna_status", row["#{side}_antenna_status"])
    |> put_default_if_present("degraded", row["#{side}_degraded"])
    |> put_default_if_present("degraded?", row["#{side}_degraded?"])
    |> put_default_if_present("mode", row["#{side}_mode"])
    |> put_default_if_present(
      "incompatible_activity_types",
      row["#{side}_incompatible_activity_types"]
    )
    |> put_default_if_present(
      "suppressed_activity_types",
      row["#{side}_suppressed_activity_types"]
    )
  end

  defp timeline_diff_changed_resource_availability_spacecraft_id(row, evidence) do
    evidence["spacecraft_id"] ||
      row["spacecraft_id"] ||
      row["scenario_id"] ||
      get_in(row, ["replacement_activity_context", "spacecraft_id"]) ||
      get_in(row, ["replacement_activity_context", "scenario_id"]) ||
      get_in(row, ["source_activity_context", "spacecraft_id"]) ||
      get_in(row, ["source_activity_context", "scenario_id"])
  end

  defp timeline_diff_changed_resource_availability_event(
         row,
         source_path,
         evidence,
         spacecraft_id,
         field
       ) do
    %{
      "type" => "resource_availability_constraint",
      "scenario_id" => row["scenario_id"],
      "spacecraft_id" => spacecraft_id,
      "resource_field" => field,
      field => false,
      "available" => false,
      "starts_at_s" => timeline_diff_changed_window_start_s(row),
      "ends_at_s" => timeline_diff_changed_window_end_s(row),
      "source_activity_id" => row["source_activity_id"],
      "replacement_activity_id" => row["replacement_activity_id"],
      "source_activity_ids" => timeline_diff_changed_source_activity_ids(row),
      "timeline_id" => row["timeline_id"],
      "diff_status" => row["diff_status"],
      "changed_fields" => row["changed_fields"],
      "required_operator_action" => row["required_operator_action"],
      "status_transition" => timeline_diff_changed_status_transition(row),
      "transition_type" => timeline_diff_changed_transition_field(row, "transition_type"),
      "transition_category" => timeline_diff_changed_transition_field(row, "transition_category"),
      "transition_reason" => timeline_diff_changed_transition_reason(row),
      "requires_operator_review" =>
        timeline_diff_changed_transition_field(row, "requires_operator_review"),
      "degraded" => evidence["degraded"],
      "mode" => evidence["mode"],
      "incompatible_activity_types" =>
        evidence["incompatible_activity_types"] || evidence["suppressed_activity_types"],
      "derivation_reasons" => [
        "timeline_diff_changed_activity",
        "timeline_diff_changed_resource_availability",
        "#{field}_timeline_diff_false"
      ],
      "feedback_source" => source_path,
      "feedback_scope" => "timeline_diff",
      "feedback_key" => spacecraft_id,
      "trust_boundary" => timeline_diff_trust_boundary(row)
    }
    |> compact_map()
  end

  defp timeline_diff_changed_resource_identity_pressure_row?(row) do
    row["diff_status"] == "changed" and timeline_diff_changed_resource_identity_mismatch?(row) and
      timeline_diff_changed_resource_identity_field(row) not in [nil, ""]
  end

  defp timeline_diff_changed_resource_identity_events(row, source_path) do
    if timeline_diff_changed_resource_identity_pressure_row?(row) do
      [timeline_diff_changed_resource_identity_event(row, source_path)]
    else
      []
    end
  end

  defp timeline_diff_changed_resource_identity_event(row, source_path) do
    field = timeline_diff_changed_resource_identity_field(row)
    spacecraft_id = timeline_diff_changed_resource_identity_spacecraft_id(row)
    planned_resource_id = timeline_diff_changed_planned_resource_id(row)
    realized_resource_id = timeline_diff_changed_realized_resource_id(row)

    %{
      "type" => "resource_availability_constraint",
      "scenario_id" => timeline_diff_changed_scenario_id(row),
      "spacecraft_id" => spacecraft_id,
      "resource_field" => field,
      field => false,
      "available" => false,
      "resource_id" => planned_resource_id || realized_resource_id,
      "planned_resource_id" => planned_resource_id,
      "realized_resource_id" => realized_resource_id,
      "resource_match_status" => "mismatch",
      "resource_identity_mismatch_fields" => ["resource"],
      "starts_at_s" => timeline_diff_changed_window_start_s(row),
      "ends_at_s" => timeline_diff_changed_window_end_s(row),
      "source_activity_id" => row["source_activity_id"],
      "replacement_activity_id" => row["replacement_activity_id"],
      "source_activity_ids" => timeline_diff_changed_source_activity_ids(row),
      "timeline_id" => row["timeline_id"],
      "diff_status" => row["diff_status"],
      "changed_fields" => row["changed_fields"],
      "required_operator_action" => row["required_operator_action"],
      "status_transition" => timeline_diff_changed_status_transition(row),
      "transition_type" => timeline_diff_changed_transition_field(row, "transition_type"),
      "transition_category" => timeline_diff_changed_transition_field(row, "transition_category"),
      "transition_reason" => timeline_diff_changed_transition_reason(row),
      "requires_operator_review" =>
