  defp timeline_diff_changed_resource_identity_mismatch?(row) do
    case timeline_diff_changed_resource_identity_match_status(row) do
      "mismatch" -> true
      _status -> false
    end
  end

  defp timeline_diff_changed_resource_identity_match_status(row) do
    explicit =
      timeline_diff_first_string(row, [
        "resource_match_status",
        "source_resource_match_status",
        "replacement_resource_match_status",
        ["source_activity_context", "resource_match_status"],
        ["replacement_activity_context", "resource_match_status"]
      ])
      |> normalized_status_token()

    if explicit in ["matched", "mismatch", "planned_only", "realized_only"] do
      explicit
    else
      timeline_diff_match_status(
        timeline_diff_changed_planned_resource_id(row),
        timeline_diff_changed_realized_resource_id(row)
      )
    end
  end

  defp timeline_diff_changed_planned_resource_id(row) do
    timeline_diff_first_stable_id(row, [
      "planned_resource_id",
      "source_planned_resource_id",
      "source_resource_id",
      ["source_activity_context", "planned_resource_id"],
      ["source_activity_context", "resource_id"],
      ["source_activity_context", "resource", "resource_id"],
      ["source_activity_context", "resource", "id"]
    ])
  end

  defp timeline_diff_changed_realized_resource_id(row) do
    timeline_diff_first_stable_id(row, [
      "realized_resource_id",
      "replacement_realized_resource_id",
