      ["replacement_activity_context", "realized_resource_id"],
      ["replacement_activity_context", "resource_id"],
      ["replacement_activity_context", "resource", "resource_id"],
      ["replacement_activity_context", "resource", "id"]
    ])
  end

  defp timeline_diff_changed_resource_identity_field(row) do
    cond do
      timeline_diff_changed_observation?(row) ->
        "payload_available"

      timeline_diff_changed_downlink?(row) or timeline_diff_changed_contact?(row) or
          timeline_diff_changed_command?(row) ->
        "antenna_available"

      timeline_diff_changed_maneuver?(row) ->
        "spacecraft_available"

      true ->
        nil
    end
  end

