  defp timeline_diff_changed_downlink_pressure_row?(row) do
    row["diff_status"] == "changed" and timeline_diff_changed_downlink?(row) and
      timeline_diff_changed_downlink_gap?(row)
  end

  defp timeline_diff_changed_downlink?(row) do
    type =
      row["replacement_activity_type"] || row["source_activity_type"] ||
        get_in(row, ["replacement_activity_context", "activity_type"]) ||
        get_in(row, ["replacement_activity_context", "type"]) ||
        get_in(row, ["source_activity_context", "activity_type"]) ||
        get_in(row, ["source_activity_context", "type"])

    direction =
      row["replacement_direction"] || row["source_direction"] ||
        get_in(row, ["replacement_activity_context", "direction"]) ||
        get_in(row, ["source_activity_context", "direction"])

    type == "downlink" or (type in ["planned_contact", "contact"] and direction == "downlink")
  end

  defp timeline_diff_changed_downlink_gap?(row) do
    planned = timeline_diff_changed_planned_downlink_mb(row)
    required = timeline_diff_changed_required_downlink_mb(row)
    shortfall = timeline_diff_changed_downlink_shortfall_mb(row)

    positive_number?(shortfall) or
      (is_number(required) and is_number(planned) and planned < required)
  end

  defp timeline_diff_changed_downlink_event(row, source_path) do
    planned_downlink_mb = timeline_diff_changed_planned_downlink_mb(row)
    required_downlink_mb = timeline_diff_changed_required_downlink_mb(row)
    shortfall = timeline_diff_changed_downlink_shortfall_mb(row)

    required_downlink_mb =
      case {required_downlink_mb, planned_downlink_mb, shortfall} do
        {value, _planned, _shortfall} when is_number(value) ->
          value

        {_required, planned, value} when is_number(planned) and is_number(value) ->
          planned + value

        {_required, _planned, value} ->
          value
      end

    %{
      "type" => "downlink_completion_gap",
      "scenario_id" => timeline_diff_changed_scenario_id(row),
      "ground_station_id" => timeline_diff_changed_ground_station_id(row),
