      "replacement_activity_id" => row["replacement_activity_id"],
      "source_activity_ids" => timeline_diff_changed_source_activity_ids(row),
      "timeline_id" => row["timeline_id"],
      "diff_status" => row["diff_status"],
      "changed_fields" => row["changed_fields"],
      "required_operator_action" => row["required_operator_action"],
      "status_transition" => timeline_diff_changed_status_transition(row),
      "transition_type" => timeline_diff_changed_transition_field(row, "transition_type"),
      "transition_category" => timeline_diff_changed_transition_field(row, "transition_category"),
      "transition_reason" => timeline_diff_changed_transition_reason(row),
      "requires_operator_review" =>
        timeline_diff_changed_transition_field(row, "requires_operator_review"),
      "derivation_reasons" => timeline_diff_changed_link_quality_reasons(row),
      "feedback_source" => source_path,
      "feedback_scope" => "timeline_diff",
      "feedback_key" => timeline_diff_changed_ground_station_id(row),
      "trust_boundary" => timeline_diff_trust_boundary(row)
    }
    |> compact_map()
  end

  defp timeline_diff_changed_link_quality_reasons(row) do
    []
    |> maybe_append_reason(true, "timeline_diff_changed_activity")
    |> maybe_append_reason(true, "timeline_diff_changed_link_quality")
    |> maybe_append_reason(
      timeline_diff_changed_carrier_lock(row) == false,
      "carrier_lock_lost"
    )
    |> maybe_append_reason(
      timeline_diff_changed_symbol_lock(row) == false,
      "symbol_lock_lost"
    )
    |> maybe_append_reason(
      negative_link_margin?(timeline_diff_changed_link_margin_db(row)),
      "negative_link_margin"
    )
    |> maybe_append_reason(
      timeline_diff_changed_link_quality_failure_status?(
        timeline_diff_changed_link_quality_status(row)
      ),
      "link_quality_status_#{timeline_diff_changed_link_quality_status(row)}"
    )
    |> maybe_append_reason(
      timeline_diff_changed_link_profile_mismatch?(row),
      "link_profile_mismatch"
    )
    |> Kernel.++(
      Enum.map(
        timeline_diff_changed_link_profile_mismatch_fields(row),
        &"#{&1}_mismatch"
      )
    )
    |> Enum.reverse()
  end

  defp timeline_diff_changed_link_profile_mismatch?(row) do
    timeline_diff_changed_link_profile_mismatch_fields(row) != []
  end

  defp timeline_diff_changed_link_profile_mismatch_fields(row) do
    string_mismatches =
      ["link_protocol", "frequency_band", "modulation", "coding_scheme", "polarization"]
      |> Enum.filter(&(timeline_diff_changed_link_profile_match_status(row, &1) == "mismatch"))

    if timeline_diff_changed_data_rate_match_status(row) == "mismatch" do
      string_mismatches ++ ["data_rate"]
    else
      string_mismatches
    end
  end

  defp timeline_diff_changed_link_profile_value(row, field) do
    timeline_diff_changed_realized_link_profile_value(row, field) ||
      timeline_diff_changed_planned_link_profile_value(row, field)
  end

  defp timeline_diff_changed_planned_link_profile_value(row, field) do
    timeline_diff_first_string(row, [
      "planned_#{field}",
      "source_planned_#{field}",
      "source_#{field}",
      ["source_activity_context", "planned_#{field}"],
      ["source_activity_context", field],
      ["source_activity_context", "link", field],
      ["source_activity_context", "communications", field],
      ["source_activity_context", "throughput_model", field]
    ])
  end

  defp timeline_diff_changed_realized_link_profile_value(row, field) do
    timeline_diff_first_string(row, [
