  end

  defp timeline_diff_changed_link_profile_match_status(row, field) do
    timeline_diff_match_status(
      timeline_diff_changed_planned_link_profile_value(row, field),
      timeline_diff_changed_realized_link_profile_value(row, field)
    )
  end

