  defp timeline_diff_changed_link_profile_data_rate_mbps(row) do
    timeline_diff_changed_realized_data_rate_mbps(row) ||
      timeline_diff_changed_planned_data_rate_mbps(row)
  end

  defp timeline_diff_changed_data_rate_delta_mbps(row) do
    planned = timeline_diff_changed_planned_data_rate_mbps(row)
    realized = timeline_diff_changed_realized_data_rate_mbps(row)

    if is_number(planned) and is_number(realized), do: realized - planned
  end

  defp timeline_diff_changed_data_rate_match_status(row) do
    planned = timeline_diff_changed_planned_data_rate_mbps(row)
    realized = timeline_diff_changed_realized_data_rate_mbps(row)

    cond do
      not is_number(planned) and not is_number(realized) -> nil
      not is_number(planned) -> "realized_only"
      not is_number(realized) -> "planned_only"
      abs(realized - planned) <= 1.0e-9 -> "matched"
      true -> "mismatch"
    end
  end

  defp timeline_diff_first_data_rate_mbps(row, opts) do
    case timeline_diff_first_number(row, Keyword.fetch!(opts, :mbps_fields)) do
      value when is_number(value) ->
        value

      _value ->
        row
        |> timeline_diff_first_number(Keyword.fetch!(opts, :mb_s_fields))
        |> case do
          value when is_number(value) -> value * 8.0
          _value -> nil
        end
    end
  end

  defp timeline_diff_match_status(planned, realized)
       when planned in [nil, ""] and realized in [nil, ""],
       do: nil

  defp timeline_diff_match_status(planned, _realized) when planned in [nil, ""],
    do: "realized_only"

  defp timeline_diff_match_status(_planned, realized) when realized in [nil, ""],
    do: "planned_only"

  defp timeline_diff_match_status(value, value), do: "matched"
  defp timeline_diff_match_status(_planned, _realized), do: "mismatch"

