  defp timeline_diff_changed_link_quality_failure_status?(status) when is_binary(status) do
    status in [
      "below_threshold",
      "degraded",
      "failed",
      "failure",
      "link_failed",
      "lock_lost",
      "low_margin",
      "lost_lock",
      "no_lock",
      "poor",
      "unusable"
    ]
  end

  defp timeline_diff_changed_link_quality_failure_status?(_status), do: false

  defp timeline_diff_first_boolean(row, fields) do
    fields
    |> Enum.map(&timeline_diff_field_value(row, &1))
    |> Enum.map(&json_boolean_value/1)
    |> Enum.find(&is_boolean/1)
  end

  defp negative_link_margin?(value), do: is_number(value) and value < 0.0

  defp timeline_diff_changed_station_throughput_pressure_row?(row, policy) do
    row["diff_status"] == "changed" and
      (timeline_diff_changed_downlink?(row) or timeline_diff_changed_contact?(row)) and
      timeline_diff_changed_station_throughput_events(row, "timeline_diff", policy) != []
  end

  defp timeline_diff_changed_station_throughput_events(row, source_path, policy) do
    factor = timeline_diff_changed_station_throughput_factor(row)
    threshold = timeline_diff_changed_station_throughput_threshold(row, policy)

    if low_feedback_factor?(factor, threshold) do
      [timeline_diff_changed_station_throughput_event(row, source_path, factor)]
    else
      []
    end
  end

  defp timeline_diff_changed_station_throughput_threshold(row, policy) do
    [
      row["station_throughput_feedback_threshold"],
      row["replacement_station_throughput_feedback_threshold"],
      get_in(row, ["replacement_activity_context", "station_throughput_feedback_threshold"]),
      get_in(row, [
        "replacement_activity_context",
        "throughput_model",
        "station_throughput_feedback_threshold"
      ]),
      row["source_station_throughput_feedback_threshold"],
      get_in(row, ["source_activity_context", "station_throughput_feedback_threshold"]),
      get_in(row, [
        "source_activity_context",
        "throughput_model",
        "station_throughput_feedback_threshold"
      ])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) -> value
      _value -> numeric_policy_value(policy, "station_throughput_feedback_threshold", 0.8)
    end
  end

  defp timeline_diff_changed_station_throughput_factor(row) do
    [
      row["station_throughput_factor"],
      row["replacement_station_throughput_factor"],
      get_in(row, ["replacement_activity_context", "station_throughput_factor"]),
      get_in(row, [
        "replacement_activity_context",
        "throughput_model",
        "station_throughput_factor"
      ]),
      row["source_station_throughput_factor"],
      get_in(row, ["source_activity_context", "station_throughput_factor"]),
      get_in(row, ["source_activity_context", "throughput_model", "station_throughput_factor"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) ->
        clamp_unit_interval(value)

      _value ->
        actual = timeline_diff_changed_actual_throughput_mb(row)
        expected = timeline_diff_changed_expected_throughput_mb(row)

        if is_number(actual) and is_number(expected) and expected > 0.0 do
          actual
          |> Kernel./(expected)
          |> clamp_unit_interval()
        end
    end
  end

  defp timeline_diff_changed_actual_throughput_mb(row) do
    [
      row["actual_throughput_mb"],
      row["replacement_actual_throughput_mb"],
      get_in(row, ["replacement_activity_context", "actual_throughput_mb"]),
      get_in(row, ["replacement_activity_context", "throughput_model", "actual_throughput_mb"]),
      row["source_actual_throughput_mb"],
      get_in(row, ["source_activity_context", "actual_throughput_mb"]),
      get_in(row, ["source_activity_context", "throughput_model", "actual_throughput_mb"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) ->
        value

      _value ->
        row
        |> timeline_diff_changed_station_throughput_evidence()
        |> actual_data_rate_contact_throughput_mb()
    end
  end

