      get_in(row, ["source_activity_context", "throughput_model", "estimated_throughput_mb"]),
      get_in(row, ["source_activity_context", "throughput_model", "planned_throughput_mb"]),
      get_in(row, [
        "source_activity_context",
        "throughput_model",
        "planned_estimated_throughput_mb"
      ]),
      get_in(row, ["source_activity_context", "throughput_model", "estimated_downlink_mb"]),
      get_in(row, ["source_activity_context", "throughput_model", "planned_downlink_mb"]),
      get_in(row, ["source_activity_context", "throughput_model", "required_downlink_mb"]),
      get_in(row, ["source_activity_context", "throughput_model", "required_data_volume_mb"])
    ]
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) ->
        value

      _value ->
        row
        |> timeline_diff_changed_station_throughput_evidence()
        |> expected_contact_throughput_mb()
    end
  end

  defp timeline_diff_changed_station_throughput_evidence(row) do
    [
      row["source_activity_context"],
      row,
      row["replacement_activity_context"]
    ]
    |> Enum.reduce(%{}, fn evidence, merged ->
      Map.merge(merged, stringify_keys(evidence || %{}))
    end)
  end

  defp timeline_diff_changed_station_throughput_event(row, source_path, factor) do
    %{
      "type" => "station_throughput_feedback",
      "scenario_id" => timeline_diff_changed_scenario_id(row),
      "ground_station_id" => timeline_diff_changed_ground_station_id(row),
      "starts_at_s" => timeline_diff_changed_window_start_s(row),
      "ends_at_s" => timeline_diff_changed_window_end_s(row),
      "station_throughput_factor" => factor,
      "actual_throughput_mb" => timeline_diff_changed_actual_throughput_mb(row),
      "estimated_throughput_mb" => timeline_diff_changed_expected_throughput_mb(row),
      "expected_throughput_mb" => timeline_diff_changed_expected_throughput_mb(row),
      "source_activity_id" => row["source_activity_id"],
      "replacement_activity_id" => row["replacement_activity_id"],
      "source_activity_ids" => timeline_diff_changed_source_activity_ids(row),
      "timeline_id" => row["timeline_id"],
      "diff_status" => row["diff_status"],
      "changed_fields" => row["changed_fields"],
      "required_operator_action" => row["required_operator_action"],
      "status_transition" => timeline_diff_changed_status_transition(row),
      "transition_type" => timeline_diff_changed_transition_field(row, "transition_type"),
      "transition_category" => timeline_diff_changed_transition_field(row, "transition_category"),
      "transition_reason" => timeline_diff_changed_transition_reason(row),
      "requires_operator_review" =>
        timeline_diff_changed_transition_field(row, "requires_operator_review"),
      "derivation_reasons" => [
        "timeline_diff_changed_activity",
        "timeline_diff_changed_station_throughput"
      ],
      "feedback_source" => source_path,
      "feedback_scope" => "timeline_diff",
      "feedback_key" => timeline_diff_changed_ground_station_id(row),
      "trust_boundary" => timeline_diff_trust_boundary(row)
    }
    |> compact_map()
  end

  defp timeline_diff_changed_collection_latency_pressure_row?(row) do
    row["diff_status"] == "changed" and
      timeline_diff_changed_collection_latency_events(row, "timeline_diff") != []
  end

  defp timeline_diff_changed_collection_latency_events(row, source_path) do
    if timeline_diff_changed_collection_latency_gap?(row) and
         timeline_diff_changed_collection_latency_routed?(row) do
      [timeline_diff_changed_collection_latency_event(row, source_path)]
    else
      []
    end
  end

  defp timeline_diff_changed_collection_latency_gap?(row) do
    latency_gap = timeline_diff_changed_collection_latency_gap_s(row)
    max_latency_s = timeline_diff_changed_collection_latency_max_s(row)
    planned_latency_s = timeline_diff_changed_collection_latency_planned_s(row)
    status = timeline_diff_changed_collection_latency_status(row)

    positive_number?(latency_gap) or
      (is_number(max_latency_s) and is_number(planned_latency_s) and
         planned_latency_s > max_latency_s) or
      status in ["late", "missed", "failed", "unmet", "unsatisfied", "violated", "breached"]
  end

  defp timeline_diff_changed_collection_latency_routed?(row) do
    evidence = timeline_diff_changed_collection_latency_evidence(row)

    [
      timeline_diff_changed_collection_latency_source_activity_id(row),
      timeline_diff_changed_target_id(row),
      score_term_primary_target_id(evidence),
      timeline_diff_changed_ground_station_id(row),
      score_term_station_id(evidence),
      score_term_collection_id(evidence),
      score_term_product_id(evidence),
      score_term_payload_id(evidence),
      score_term_instrument_id(evidence)
    ]
    |> Enum.any?(&stable_id_string?/1)
  end

  defp timeline_diff_changed_collection_latency_event(row, source_path) do
    evidence = timeline_diff_changed_collection_latency_evidence(row)
    max_latency_s = timeline_diff_changed_collection_latency_max_s(row)
    planned_latency_s = timeline_diff_changed_collection_latency_planned_s(row)
    latency_gap_s = timeline_diff_changed_collection_latency_gap_s(row)
    starts_at_s = timeline_diff_changed_collection_latency_window_start_s(row)

    ends_at_s =
      timeline_diff_changed_collection_latency_deadline_s(row) ||
        if(is_number(starts_at_s) and is_number(max_latency_s), do: starts_at_s + max_latency_s) ||
        timeline_diff_changed_window_end_s(row)

    %{
      "type" => "downlink_completion_gap",
      "objective_id" => timeline_diff_changed_collection_latency_objective_id(row),
      "objective_type" => "collection_latency",
      "latency_objective" => true,
      "target_id" =>
        timeline_diff_changed_target_id(row) || score_term_primary_target_id(evidence),
      "scenario_id" => timeline_diff_changed_scenario_id(row),
      "ground_station_id" =>
        timeline_diff_changed_ground_station_id(row) || score_term_station_id(evidence),
      "collection_id" => score_term_collection_id(evidence),
      "collection_ids" => score_term_collection_ids(evidence),
      "product_id" => score_term_product_id(evidence),
      "product_ids" => score_term_product_ids(evidence),
      "payload_id" => score_term_payload_id(evidence),
      "payload_ids" => score_term_payload_ids(evidence),
      "instrument_id" => score_term_instrument_id(evidence),
      "instrument_ids" => score_term_instrument_ids(evidence),
      "starts_at_s" => starts_at_s,
      "ends_at_s" => ends_at_s,
      "required_contacts" => timeline_diff_changed_required_contacts(row),
      "planned_contacts" => timeline_diff_changed_planned_contacts(row),
      "required_downlink_mb" => timeline_diff_changed_required_downlink_mb(row),
      "planned_downlink_mb" => timeline_diff_changed_planned_downlink_mb(row),
      "max_latency_s" => max_latency_s,
      "planned_latency_s" => planned_latency_s,
      "latency_gap_s" => latency_gap_s,
      "source_activity_id" => timeline_diff_changed_collection_latency_source_activity_id(row),
      "source_activity_ids" => timeline_diff_changed_source_activity_ids(row),
      "missed_downlink_activity_id" =>
        timeline_diff_changed_collection_latency_downlink_activity_id(row),
      "missed_downlink_activity_ids" =>
        timeline_diff_changed_collection_latency_downlink_activity_ids(row),
      "realized_status" => timeline_diff_changed_realized_status(row),
      "contact_result" => timeline_diff_changed_contact_result(row),
      "timeline_id" => row["timeline_id"],
      "diff_status" => row["diff_status"],
      "changed_fields" => row["changed_fields"],
      "required_operator_action" => row["required_operator_action"],
      "status_transition" => timeline_diff_changed_status_transition(row),
      "transition_type" => timeline_diff_changed_transition_field(row, "transition_type"),
      "transition_category" => timeline_diff_changed_transition_field(row, "transition_category"),
      "transition_reason" => timeline_diff_changed_transition_reason(row),
      "requires_operator_review" =>
        timeline_diff_changed_transition_field(row, "requires_operator_review"),
      "derivation_reasons" => timeline_diff_changed_collection_latency_reasons(row),
      "feedback_source" => source_path,
      "feedback_scope" => "timeline_diff",
      "feedback_key" =>
        timeline_diff_changed_collection_latency_source_activity_id(row) ||
          score_term_collection_id(evidence) ||
          timeline_diff_changed_target_id(row),
      "trust_boundary" => timeline_diff_trust_boundary(row)
    }
    |> compact_map()
  end

  defp timeline_diff_changed_collection_latency_evidence(row) do
    [
      row["source_activity_context"],
      row["source_observation"],
      row,
      row["replacement_activity_context"],
      row["replacement_observation"]
    ]
    |> Enum.reduce(%{}, fn evidence, merged ->
      Map.merge(merged, stringify_keys(evidence || %{}))
    end)
  end

  defp timeline_diff_changed_collection_latency_max_s(row) do
    timeline_diff_first_number(row, [
      "max_latency_s",
      "required_latency_s",
      "target_latency_s",
      "target_delivery_latency_s",
      "latency_limit_s",
      "max_delivery_latency_s",
      "required_delivery_latency_s",
      "replacement_max_latency_s",
      "replacement_required_latency_s",
      "replacement_target_latency_s",
      "replacement_target_delivery_latency_s",
      "replacement_latency_limit_s",
      "replacement_max_delivery_latency_s",
      "replacement_required_delivery_latency_s",
      ["replacement_activity_context", "max_latency_s"],
      ["replacement_activity_context", "required_latency_s"],
      ["replacement_activity_context", "target_latency_s"],
      ["replacement_activity_context", "target_delivery_latency_s"],
      ["replacement_activity_context", "latency_limit_s"],
      ["replacement_activity_context", "max_delivery_latency_s"],
      ["replacement_activity_context", "required_delivery_latency_s"],
      "source_max_latency_s",
      "source_required_latency_s",
      "source_target_latency_s",
      "source_target_delivery_latency_s",
      "source_latency_limit_s",
      "source_max_delivery_latency_s",
      "source_required_delivery_latency_s",
      ["source_activity_context", "max_latency_s"],
      ["source_activity_context", "required_latency_s"],
      ["source_activity_context", "target_latency_s"],
      ["source_activity_context", "target_delivery_latency_s"],
      ["source_activity_context", "latency_limit_s"],
      ["source_activity_context", "max_delivery_latency_s"],
      ["source_activity_context", "required_delivery_latency_s"]
    ])
  end

  defp timeline_diff_changed_collection_latency_planned_s(row) do
    timeline_diff_first_number(row, [
      "planned_latency_s",
      "actual_latency_s",
      "delivery_latency_s",
      "planned_delivery_latency_s",
      "actual_delivery_latency_s",
      "replacement_planned_latency_s",
      "replacement_actual_latency_s",
      "replacement_delivery_latency_s",
      "replacement_planned_delivery_latency_s",
      "replacement_actual_delivery_latency_s",
      ["replacement_activity_context", "planned_latency_s"],
      ["replacement_activity_context", "actual_latency_s"],
      ["replacement_activity_context", "delivery_latency_s"],
      ["replacement_activity_context", "planned_delivery_latency_s"],
      ["replacement_activity_context", "actual_delivery_latency_s"],
      "source_planned_latency_s",
      "source_actual_latency_s",
      "source_delivery_latency_s",
      "source_planned_delivery_latency_s",
      "source_actual_delivery_latency_s",
      ["source_activity_context", "planned_latency_s"],
      ["source_activity_context", "actual_latency_s"],
      ["source_activity_context", "delivery_latency_s"],
      ["source_activity_context", "planned_delivery_latency_s"],
      ["source_activity_context", "actual_delivery_latency_s"]
    ])
  end

  defp timeline_diff_changed_collection_latency_gap_s(row) do
    explicit =
      timeline_diff_first_number(row, [
        "collection_latency_gap_s",
        "latency_gap_s",
        "delivery_latency_gap_s",
        "collection_latency_shortfall_s",
        "late_delivery_s",
        "replacement_collection_latency_gap_s",
        "replacement_latency_gap_s",
        "replacement_delivery_latency_gap_s",
        "replacement_collection_latency_shortfall_s",
        "replacement_late_delivery_s",
        ["replacement_activity_context", "collection_latency_gap_s"],
        ["replacement_activity_context", "latency_gap_s"],
        ["replacement_activity_context", "delivery_latency_gap_s"],
        ["replacement_activity_context", "collection_latency_shortfall_s"],
        ["replacement_activity_context", "late_delivery_s"],
        "source_collection_latency_gap_s",
        "source_latency_gap_s",
        "source_delivery_latency_gap_s",
        "source_collection_latency_shortfall_s",
        "source_late_delivery_s",
        ["source_activity_context", "collection_latency_gap_s"],
        ["source_activity_context", "latency_gap_s"],
        ["source_activity_context", "delivery_latency_gap_s"],
        ["source_activity_context", "collection_latency_shortfall_s"],
        ["source_activity_context", "late_delivery_s"]
      ])

    case {explicit, timeline_diff_changed_collection_latency_planned_s(row),
          timeline_diff_changed_collection_latency_max_s(row)} do
      {value, _planned, _max} when is_number(value) ->
        value

      {_missing, planned, max_latency_s} when is_number(planned) and is_number(max_latency_s) ->
        max(planned - max_latency_s, 0.0)

      _other ->
        nil
    end
  end

  defp timeline_diff_changed_collection_latency_status(row) do
    [
      row["collection_latency_status"],
      row["latency_status"],
      row["delivery_status"],
      row["replacement_collection_latency_status"],
      row["replacement_latency_status"],
      row["replacement_delivery_status"],
      get_in(row, ["replacement_activity_context", "collection_latency_status"]),
      get_in(row, ["replacement_activity_context", "latency_status"]),
      get_in(row, ["replacement_activity_context", "delivery_status"]),
      row["source_collection_latency_status"],
      row["source_latency_status"],
      row["source_delivery_status"],
      get_in(row, ["source_activity_context", "collection_latency_status"]),
      get_in(row, ["source_activity_context", "latency_status"]),
      get_in(row, ["source_activity_context", "delivery_status"])
    ]
    |> Enum.map(&normalized_status_token/1)
    |> Enum.find(&(is_binary(&1) and &1 != ""))
  end

  defp timeline_diff_changed_collection_latency_window_start_s(row) do
    timeline_diff_first_number(row, [
      "collection_end_s",
      "collection_ends_at_s",
      "observation_end_s",
      "observation_ends_at_s",
      "replacement_collection_end_s",
      "replacement_collection_ends_at_s",
      "replacement_observation_end_s",
      "replacement_observation_ends_at_s",
      ["replacement_activity_context", "collection_end_s"],
      ["replacement_activity_context", "collection_ends_at_s"],
      ["replacement_activity_context", "observation_end_s"],
      ["replacement_activity_context", "observation_ends_at_s"],
      "source_collection_end_s",
      "source_collection_ends_at_s",
      "source_observation_end_s",
      "source_observation_ends_at_s",
      ["source_activity_context", "collection_end_s"],
      ["source_activity_context", "collection_ends_at_s"],
      ["source_activity_context", "observation_end_s"],
      ["source_activity_context", "observation_ends_at_s"]
    ]) || timeline_diff_changed_window_end_s(row)
  end

  defp timeline_diff_changed_collection_latency_deadline_s(row) do
    timeline_diff_first_number(row, [
      "delivery_deadline_s",
      "deadline_s",
      "required_delivery_at_s",
      "target_delivery_at_s",
      "replacement_delivery_deadline_s",
      "replacement_deadline_s",
      "replacement_required_delivery_at_s",
      "replacement_target_delivery_at_s",
      ["replacement_activity_context", "delivery_deadline_s"],
      ["replacement_activity_context", "deadline_s"],
      ["replacement_activity_context", "required_delivery_at_s"],
      ["replacement_activity_context", "target_delivery_at_s"],
      "source_delivery_deadline_s",
      "source_deadline_s",
      "source_required_delivery_at_s",
      "source_target_delivery_at_s",
      ["source_activity_context", "delivery_deadline_s"],
      ["source_activity_context", "deadline_s"],
      ["source_activity_context", "required_delivery_at_s"],
      ["source_activity_context", "target_delivery_at_s"]
    ])
  end

  defp timeline_diff_changed_collection_latency_objective_id(row) do
    [
      row["objective_id"],
      row["collection_latency_objective_id"],
      row["replacement_objective_id"],
      row["replacement_collection_latency_objective_id"],
      get_in(row, ["replacement_activity_context", "objective_id"]),
      get_in(row, ["replacement_activity_context", "collection_latency_objective_id"]),
      row["source_objective_id"],
      row["source_collection_latency_objective_id"],
      get_in(row, ["source_activity_context", "objective_id"]),
      get_in(row, ["source_activity_context", "collection_latency_objective_id"])
    ]
    |> Enum.map(&encode_value/1)
    |> Enum.find(&stable_id_string?/1)
  end

  defp timeline_diff_changed_collection_latency_source_activity_id(row) do
    [
      row["source_observation_activity_id"],
      row["observation_activity_id"],
      row["source_activity_id"],
      get_in(row, ["source_activity_context", "activity_id"]),
      get_in(row, ["source_activity_context", "id"]),
      get_in(row, ["replacement_activity_context", "observation_activity_id"])
    ]
    |> Enum.map(&encode_value/1)
    |> Enum.find(&stable_id_string?/1)
  end

  defp timeline_diff_changed_collection_latency_downlink_activity_id(row) do
    row
    |> timeline_diff_changed_collection_latency_downlink_activity_ids()
    |> List.wrap()
    |> List.first()
  end

  defp timeline_diff_changed_collection_latency_downlink_activity_ids(row) do
    [
      row["missed_downlink_activity_ids"],
      row["missed_downlink_activity_id"],
      row["downlink_activity_ids"],
      row["downlink_activity_id"],
      row["replacement_activity_id"],
      get_in(row, ["replacement_activity_context", "downlink_activity_id"]),
      get_in(row, ["replacement_activity_context", "activity_id"])
    ]
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.filter(&stable_id_string?/1)
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      ids -> ids
    end
  end

  defp timeline_diff_changed_collection_latency_reasons(row) do
    latency_gap_s = timeline_diff_changed_collection_latency_gap_s(row)
    max_latency_s = timeline_diff_changed_collection_latency_max_s(row)
    planned_latency_s = timeline_diff_changed_collection_latency_planned_s(row)
    status = timeline_diff_changed_collection_latency_status(row)

    []
    |> maybe_append_reason(true, "timeline_diff_changed_activity")
    |> maybe_append_reason(true, "timeline_diff_changed_collection_latency")
    |> maybe_append_reason(positive_number?(latency_gap_s), "collection_latency_gap")
    |> maybe_append_reason(
      is_number(max_latency_s) and is_number(planned_latency_s) and
        planned_latency_s > max_latency_s,
      "timeline_diff_collection_latency_limit_exceeded"
    )
    |> maybe_append_reason(status not in [nil, ""], "collection_latency_status_#{status}")
    |> Enum.reverse()
  end

  defp timeline_diff_changed_realized_status(row) do
    [
      row["replacement_realized_status"],
      get_in(row, ["replacement_activity_context", "realized_status"]),
      row["realized_status"],
      row["replacement_status"],
      get_in(row, ["replacement_activity_context", "status"]),
      get_in(row, ["status_transition", "to"]),
      row["status"]
    ]
    |> Enum.map(&normalize_realized_status_value/1)
    |> Enum.find(&(&1 in @realized_statuses))
  end

  defp timeline_diff_changed_status_transition(row) do
    case row["status_transition"] do
      %{} = transition -> stringify_keys(transition)
      _transition -> nil
    end
  end

  defp timeline_diff_changed_transition_field(row, field) do
    row[field] || get_in(row, ["status_transition", field])
  end

  defp timeline_diff_changed_transition_reason(row) do
    timeline_diff_changed_transition_field(row, "transition_reason") ||
      timeline_diff_changed_transition_field(row, "reason")
  end

  defp timeline_diff_changed_observation_pressure_row?(row, policy) do
    row["diff_status"] == "changed" and timeline_diff_changed_observation?(row) and
      (timeline_diff_changed_observation_gap?(row) or
         timeline_diff_changed_observation_target_identity_gap?(row) or
         timeline_diff_changed_observation_product_identity_gap?(row) or
         timeline_diff_changed_observation_quality_gap?(row) or
         timeline_diff_changed_observation_pointing_gap?(row) or
         timeline_diff_changed_observation_lighting_gap?(row) or
         timeline_diff_changed_observation_target_priority_gap?(row, policy))
  end

  defp timeline_diff_changed_observation?(row) do
    type =
      row["replacement_activity_type"] || row["source_activity_type"] ||
        get_in(row, ["replacement_activity_context", "activity_type"]) ||
        get_in(row, ["replacement_activity_context", "type"]) ||
        get_in(row, ["source_activity_context", "activity_type"]) ||
        get_in(row, ["source_activity_context", "type"])

    type in ["observe", "observation", "target_visibility", "imaging"]
  end

  defp timeline_diff_changed_observation_gap?(row) do
    case timeline_diff_changed_observation_success_factor(row) do
      value when is_number(value) -> value < 1.0
      _value -> false
    end
  end

  defp timeline_diff_changed_observation_quality_gap?(row) do
    score = timeline_diff_changed_observation_image_quality_score(row)
    status = timeline_diff_changed_observation_image_quality_status(row)
    cloud_cover_fraction = timeline_diff_changed_observation_cloud_cover_fraction(row)
    blur_score = timeline_diff_changed_observation_blur_score(row)

    {factor, _source} =
      observation_quality_feedback_factor(score, status, cloud_cover_fraction, blur_score)

    timeline_diff_changed_target_id(row) not in [nil, ""] and factor < 1.0 and
      (is_number(score) or is_number(cloud_cover_fraction) or is_number(blur_score) or
         status not in [nil, ""])
  end

  defp timeline_diff_changed_observation_events(row, source_path, policy) do
    [
      if(timeline_diff_changed_observation_gap?(row),
        do: timeline_diff_changed_observation_event(row, source_path)
      ),
      if(timeline_diff_changed_observation_target_identity_gap?(row),
        do: timeline_diff_changed_observation_target_identity_event(row, source_path)
      ),
      if(timeline_diff_changed_observation_product_identity_gap?(row),
        do: timeline_diff_changed_observation_product_identity_event(row, source_path)
      ),
      if(timeline_diff_changed_observation_quality_gap?(row),
        do: timeline_diff_changed_observation_quality_event(row, source_path)
      ),
      if(timeline_diff_changed_observation_pointing_gap?(row),
        do: timeline_diff_changed_observation_pointing_event(row, source_path)
      ),
      if(timeline_diff_changed_observation_lighting_gap?(row),
