  defp timeline_diff_changed_observation_pointing_factor(row) do
    cond do
      timeline_diff_changed_pointing_mismatch?(row) ->
        0.0

      timeline_diff_changed_pointing_failure_status?(timeline_diff_changed_pointing_status(row)) or
          timeline_diff_changed_pointing_failure_status?(
            timeline_diff_changed_attitude_status(row)
          ) ->
        0.0

      timeline_diff_changed_pointing_degraded_status?(timeline_diff_changed_pointing_status(row)) or
          timeline_diff_changed_pointing_degraded_status?(
            timeline_diff_changed_attitude_status(row)
          ) ->
        0.5

      true ->
        1.0
    end
  end

  defp timeline_diff_changed_pointing_mismatch?(row) do
    Enum.any?(
      [
        timeline_diff_changed_pointing_match_status(row, "pointing_target_match_status"),
        timeline_diff_changed_pointing_match_status(row, "pointing_mode_match_status"),
        timeline_diff_changed_pointing_match_status(row, "attitude_target_match_status"),
        timeline_diff_changed_pointing_match_status(row, "attitude_mode_match_status")
      ],
      &(&1 == "mismatch")
    )
