    pointing_status = timeline_diff_changed_pointing_status(row)
    attitude_status = timeline_diff_changed_attitude_status(row)

    []
    |> maybe_append_reason(true, "timeline_diff_changed_activity")
    |> maybe_append_reason(true, "timeline_diff_changed_observation_pointing")
    |> maybe_append_reason(
      timeline_diff_changed_pointing_match_status(row, "pointing_target_match_status") ==
        "mismatch",
      "pointing_target_mismatch"
    )
    |> maybe_append_reason(
      timeline_diff_changed_pointing_match_status(row, "pointing_mode_match_status") ==
        "mismatch",
      "pointing_mode_mismatch"
    )
    |> maybe_append_reason(
      timeline_diff_changed_pointing_match_status(row, "attitude_target_match_status") ==
        "mismatch",
      "attitude_target_mismatch"
    )
