  defp timeline_diff_changed_observation_lighting_gap?(row) do
    stable_id_string?(timeline_diff_changed_target_id(row)) and
      timeline_diff_changed_observation_lighting_factor(row) < 1.0 and
      timeline_diff_changed_observation_lighting_evidence?(row)
  end

  defp timeline_diff_changed_observation_lighting_event(row, source_path) do
    %{
      "type" => "observation_success_feedback",
      "target_id" => timeline_diff_changed_target_id(row),
      "scenario_id" => timeline_diff_changed_scenario_id(row),
      "source_starts_at_s" => timeline_diff_changed_window_start_s(row),
      "source_ends_at_s" => timeline_diff_changed_window_end_s(row),
      "observation_success_factor" => timeline_diff_changed_observation_lighting_factor(row),
      "source_activity_id" => row["source_activity_id"],
      "replacement_activity_id" => row["replacement_activity_id"],
      "source_activity_ids" => timeline_diff_changed_source_activity_ids(row),
      "timeline_id" => row["timeline_id"],
      "diff_status" => row["diff_status"],
      "changed_fields" => row["changed_fields"],
      "required_operator_action" => row["required_operator_action"],
      "status_transition" => timeline_diff_changed_status_transition(row),
      "transition_type" => timeline_diff_changed_transition_field(row, "transition_type"),
      "transition_category" => timeline_diff_changed_transition_field(row, "transition_category"),
      "transition_reason" => timeline_diff_changed_transition_reason(row),
      "requires_operator_review" =>
        timeline_diff_changed_transition_field(row, "requires_operator_review"),
      "derivation_reasons" => timeline_diff_changed_observation_lighting_reasons(row),
      "feedback_source" => source_path,
      "feedback_scope" => "timeline_diff",
      "feedback_key" => timeline_diff_changed_target_id(row),
      "trust_boundary" => timeline_diff_trust_boundary(row)
    }
    |> put_optional_string(
      "lighting_condition_match_status",
      timeline_diff_changed_lighting_condition_match_status(row)
    )
    |> put_optional_string(
      "planned_lighting_condition",
      timeline_diff_planned_lighting_condition(row)
    )
    |> put_optional_string(
      "realized_lighting_condition",
      timeline_diff_realized_lighting_condition(row)
    )
    |> put_optional_string(
      "lighting_condition_detail",
      timeline_diff_lighting_condition_detail(row)
    )
    |> put_optional_string(
      "lighting_condition_model",
      timeline_diff_lighting_condition_model(row)
    )
    |> put_optional_string("lighting_detail_model", timeline_diff_lighting_detail_model(row))
    |> put_optional_string("lighting_confidence", timeline_diff_lighting_confidence(row))
    |> put_optional_number(
      "eclipse_overlap_fraction",
      timeline_diff_eclipse_overlap_fraction(row)
    )
    |> put_optional_number("eclipse_overlap_s", timeline_diff_eclipse_overlap_s(row))
  end

  defp timeline_diff_changed_observation_lighting_factor(row) do
    overlap_fraction = timeline_diff_eclipse_overlap_fraction(row)

    cond do
      is_number(overlap_fraction) and overlap_fraction > 0.0 ->
        1.0 - clamp_unit_interval(overlap_fraction)

      positive_number?(timeline_diff_eclipse_overlap_s(row)) ->
        timeline_diff_lighting_condition_factor(timeline_diff_realized_lighting_condition(row)) ||
          timeline_diff_lighting_condition_factor(timeline_diff_lighting_condition_detail(row)) ||
          0.5

      factor =
          timeline_diff_lighting_condition_factor(timeline_diff_realized_lighting_condition(row)) ->
        factor

      factor =
          timeline_diff_lighting_condition_factor(timeline_diff_lighting_condition_detail(row)) ->
        factor

      true ->
        1.0
    end
    |> clamp_unit_interval()
  end

  defp timeline_diff_changed_observation_lighting_evidence?(row) do
    is_number(timeline_diff_eclipse_overlap_fraction(row)) or
      is_number(timeline_diff_eclipse_overlap_s(row)) or
      timeline_diff_realized_lighting_condition(row) not in [nil, ""] or
      timeline_diff_lighting_condition_detail(row) not in [nil, ""]
  end

  defp timeline_diff_lighting_condition_factor(status) when is_binary(status) do
    case normalized_status_token(status) do
      status when status in ["eclipsed", "full_eclipse", "umbra", "dark", "unlit"] ->
        0.0

      "mostly_eclipsed" ->
        0.25

      status when status in ["penumbra", "partial_eclipse", "partial", "mixed_lighting"] ->
        0.5

      _status ->
        nil
    end
  end

  defp timeline_diff_lighting_condition_factor(_status), do: nil

  defp timeline_diff_changed_observation_lighting_reasons(row) do
    overlap_fraction = timeline_diff_eclipse_overlap_fraction(row)
    overlap_s = timeline_diff_eclipse_overlap_s(row)
    realized_condition = timeline_diff_realized_lighting_condition(row)
    detail = timeline_diff_lighting_condition_detail(row)

    []
    |> maybe_append_reason(true, "timeline_diff_changed_activity")
    |> maybe_append_reason(true, "timeline_diff_changed_observation_lighting")
    |> maybe_append_reason(
      timeline_diff_changed_lighting_condition_match_status(row) == "mismatch",
      "lighting_condition_mismatch"
    )
    |> maybe_append_reason(
      is_number(overlap_fraction) and overlap_fraction > 0.0,
      "eclipse_overlap_fraction_positive"
    )
    |> maybe_append_reason(positive_number?(overlap_s), "eclipse_overlap_duration_positive")
    |> maybe_append_reason(
      timeline_diff_lighting_condition_factor(realized_condition) not in [nil, 1.0],
      "lighting_condition_#{realized_condition}"
    )
    |> maybe_append_reason(
      timeline_diff_lighting_condition_factor(detail) not in [nil, 1.0],
      "lighting_detail_#{detail}"
    )
    |> Enum.reverse()
  end

