      timeline_diff_changed_maneuver_uncertainty_evidence(row, "source")
    ]
    |> Enum.map(&maneuver_review_execution_uncertainty_entry/1)
    |> Enum.find(&(&1 != %{}))
    |> case do
      nil -> %{}
      entry -> entry
    end
  end

  defp timeline_diff_changed_maneuver_uncertainty_evidence(row, nil), do: row

  defp timeline_diff_changed_maneuver_uncertainty_evidence(row, side) do
    context = stringify_keys(row["#{side}_activity_context"] || %{})

    row
    |> Map.merge(context)
    |> put_default_if_present("execution_uncertainty", row["#{side}_execution_uncertainty"])
    |> put_default_if_present(
      "execution_uncertainty_status",
      row["#{side}_execution_uncertainty_status"]
    )
    |> put_default_if_present("timing_3sigma_s", row["#{side}_timing_3sigma_s"])
    |> put_default_if_present("delta_v_3sigma_km_s", row["#{side}_delta_v_3sigma_km_s"])
    |> put_default_if_present(
      "delta_v_3sigma_magnitude_km_s",
      row["#{side}_delta_v_3sigma_magnitude_km_s"]
    )
    |> put_default_if_present(
      "execution_uncertainty_source",
      row["#{side}_execution_uncertainty_source"]
    )
  end

  defp timeline_diff_changed_replacement_evidence(row) do
    row_context = stringify_keys(row)
    replacement_context = stringify_keys(row["replacement_activity_context"] || %{})

    Map.merge(row_context, replacement_context)
    |> put_timeline_diff_changed_replacement_status(row_context)
  end

  defp put_timeline_diff_changed_replacement_status(evidence, row_context) do
    cond do
      is_binary(evidence["status"]) and evidence["status"] != "" ->
        evidence

      is_binary(row_context["replacement_status"]) and row_context["replacement_status"] != "" ->
        Map.put(evidence, "status", row_context["replacement_status"])

      is_binary(get_in(row_context, ["status_transition", "to"])) and
          get_in(row_context, ["status_transition", "to"]) != "" ->
        Map.put(evidence, "status", get_in(row_context, ["status_transition", "to"]))

      true ->
        evidence
    end
  end

  defp timeline_diff_changed_scenario_id(row) do
    row["scenario_id"] ||
      get_in(row, ["replacement_activity_context", "scenario_id"]) ||
      get_in(row, ["source_activity_context", "scenario_id"])
  end

  defp timeline_diff_changed_ground_station_id(row) do
    replacement_context = Map.get(row, "replacement_activity_context", %{})
    source_context = Map.get(row, "source_activity_context", %{})

    [
      row["replacement_ground_station_id"],
      row["source_ground_station_id"],
      score_term_entity_id(row["replacement_ground_station"], [
        "ground_station_id",
        "station_id",
        "id"
      ]),
      score_term_entity_id(row["source_ground_station"], ["ground_station_id", "station_id", "id"]),
      get_in(row, ["replacement_activity_context", "ground_station_id"]),
      get_in(row, ["replacement_activity_context", "station_id"]),
      get_in(row, ["source_activity_context", "ground_station_id"]),
      get_in(row, ["source_activity_context", "station_id"]),
      score_term_entity_id(replacement_context["ground_station"], [
        "ground_station_id",
        "station_id",
        "id"
      ]),
      score_term_entity_id(replacement_context["station"], [
        "ground_station_id",
        "station_id",
        "id"
      ]),
      score_term_entity_id(source_context["ground_station"], [
        "ground_station_id",
        "station_id",
        "id"
      ]),
      score_term_entity_id(source_context["station"], ["ground_station_id", "station_id", "id"])
    ]
    |> Enum.find(&stable_id_string?/1)
  end

  defp timeline_diff_changed_window_start_s(row) do
    [
      row["replacement_starts_at_s"],
      row["starts_at_s"],
      get_in(row, ["replacement_activity_context", "starts_at_s"]),
      get_in(row, ["replacement_activity_context", "start_s"]),
      row["source_starts_at_s"],
      get_in(row, ["source_activity_context", "starts_at_s"]),
      get_in(row, ["source_activity_context", "start_s"])
    ]
