  defp provider_counteroffer_pressure_branch(row, source_path, index) do
    case provider_counteroffer_pressure_event(row, source_path) do
      nil ->
        []

      event ->
        identity = provider_counteroffer_pressure_identity(row, index)

        [
          %{
            "id" => "derived_provider_counteroffer_pressure_#{identity}",
