  defp derived_mission_state_operational_readiness_pressure_branches(mission_state) do
    mission_state
    |> mission_state_operational_readiness_pressure_sources()
    |> operational_readiness_pressure_branches_from_sources()
  end

  defp operational_readiness_pressure_branches_from_sources(sources) do
    sources
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> operational_readiness_pressure_rows()
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {row, index} ->
        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> operational_readiness_pressure_branch(
          operational_readiness_pressure_row_source(row, source_path),
          index
        )
      end)
    end)
  end

  defp operational_readiness_pressure_row_source(row, source_path) do
    row_source = Map.get(row, "source", "operational_readiness_report")

    cond do
      String.starts_with?(row_source, "operational_readiness_report") ->
        String.replace_prefix(row_source, "operational_readiness_report", source_path)

      String.starts_with?(row_source, "operational_readiness_gate_summary") ->
        String.replace_prefix(row_source, "operational_readiness_gate_summary", source_path)

      true ->
        source_path
    end
  end

  defp mission_state_operational_readiness_pressure_sources(mission_state) do
    mission_state_operational_readiness_reports(mission_state) ++
      mission_state_operational_readiness_gate_summaries(mission_state)
  end

  defp prior_plan_operational_readiness_pressure_sources(prior_plan) do
    prior_plan_operational_readiness_reports(prior_plan) ++
      prior_plan_operational_readiness_gate_summaries(prior_plan)
  end

  defp prior_plan_operational_readiness_reports(prior_plan) do
    prior_plan = stringify_keys(prior_plan || %{})

    direct_reports =
      [
        {"source_operational_readiness_report", "prior_plan.source_operational_readiness_report"},
        {"operational_readiness_report", "prior_plan.operational_readiness_report"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        prior_plan
        |> Map.get(field)
        |> mission_state_source_report_entries(source_path)
      end)

    direct_reports ++
      prior_plan_result_artifact_operational_readiness_reports(prior_plan)
  end

  defp prior_plan_operational_readiness_gate_summaries(prior_plan) do
    prior_plan = stringify_keys(prior_plan || %{})

    direct_summaries =
      [
        {"source_operational_readiness_gate_summary",
         "prior_plan.source_operational_readiness_gate_summary"},
        {"operational_readiness_gate_summary", "prior_plan.operational_readiness_gate_summary"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        prior_plan
        |> Map.get(field)
        |> mission_state_source_report_entries(source_path)
      end)

    direct_summaries ++
      prior_plan_result_artifact_operational_readiness_gate_summaries(prior_plan)
  end

  defp prior_plan_result_artifact_operational_readiness_gate_summaries(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      result_artifact_operational_readiness_gate_summaries(artifact, source_path)
    end)
  end

  defp prior_plan_result_artifact_operational_readiness_reports(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      result_artifact_operational_readiness_reports(artifact, source_path)
    end)
  end

  defp result_artifact_operational_readiness_reports(artifact, source_path) do
    artifact = stringify_keys(artifact)

    if artifact["schema_contract"] == "operational_readiness_report.v1" do
      [{put_inherited_result_artifact_trust_boundary(artifact, artifact), source_path}]
    else
      ["source_operational_readiness_report", "operational_readiness_report"]
      |> Enum.flat_map(fn report_key ->
        result_artifact_embedded_report_entries(
          Map.get(artifact, report_key),
          artifact,
          "#{source_path}.#{report_key}"
        )
      end)
    end
  end

  defp operational_readiness_pressure_rows(report) do
    report = stringify_keys(report || %{})

    if report["schema_contract"] == "operational_readiness_gate_summary.v1" do
      operational_readiness_gate_summary_pressure_rows(report)
    else
      operational_readiness_report_pressure_rows(report)
    end
  end

  defp operational_readiness_report_pressure_rows(report) do
    classification = report["import_classification"] || "review_only"

    summary_row =
      %{
        "source" => "operational_readiness_report",
        "report_id" => report["report_id"],
        "source_artifact_type" => report["source_artifact_type"],
        "source_artifact_id" => report["source_artifact_id"],
        "readiness_level" => report["readiness_level"],
        "import_classification" => classification,
        "operational_readiness_status" => report["status"],
        "gate_count" => report["gate_count"],
        "passed_gate_count" => report["passed_gate_count"],
        "review_gate_count" => report["review_gate_count"],
        "analysis_gate_count" => report["analysis_gate_count"],
        "blocked_gate_count" => report["blocked_gate_count"],
        "evidence" => report["evidence"],
        "required_operator_action" => operational_readiness_pressure_action(classification),
        "source_operational_readiness_report" => report
      }
      |> Map.merge(operational_readiness_import_readiness_context(report))
      |> Map.merge(operational_readiness_schema_validation_context(report))
      |> Map.merge(operational_readiness_resource_availability_context(report))
      |> compact_map()

    gate_rows =
      report
      |> Map.get("gates", [])
      |> List.wrap()
      |> Enum.map(&stringify_keys/1)
      |> Enum.filter(&(Map.get(&1, "status") not in [nil, "passed"]))
      |> Enum.map(fn gate ->
        classification = operational_readiness_gate_pressure_classification(gate)
        gate_status = gate["status"] || "review_required"

        %{
          "source" => "operational_readiness_report.gates",
          "report_id" => report["report_id"],
          "source_artifact_type" => report["source_artifact_type"],
          "source_artifact_id" => report["source_artifact_id"],
          "readiness_level" => operational_readiness_pressure_level(classification),
          "import_classification" => classification,
          "operational_readiness_status" => gate_status,
          "readiness_gate_id" => gate["id"] || "operational_gate",
          "readiness_gate_status" => gate_status,
          "readiness_gate_classification" => classification,
          "readiness_gate_reason" => gate["reason"],
          "analysis_mode" => gate["analysis_mode"],
          "analysis_mode_source" => gate["analysis_mode_source"],
          "required_operator_action" => operational_readiness_pressure_action(classification),
          "source_operational_readiness_gate" => gate,
          "source_operational_readiness_report" => report
        }
        |> Map.merge(operational_readiness_operator_training_context(gate))
        |> Map.merge(operational_readiness_import_readiness_context(gate))
        |> Map.merge(operational_readiness_schema_validation_context(gate))
        |> Map.merge(operational_readiness_resource_availability_context(gate))
        |> compact_map()
      end)

    [summary_row | gate_rows]
  end

  defp operational_readiness_gate_summary_pressure_rows(summary) do
    summary = stringify_keys(summary || %{})
    classification = summary["import_classification"] || "review_only"

    summary_row =
      %{
        "source" => "operational_readiness_gate_summary",
        "source_artifact_type" => summary["source_artifact_type"],
        "source_artifact_id" => summary["source_artifact_id"],
        "readiness_level" => summary["readiness_level"],
        "import_classification" => classification,
        "operational_readiness_status" => summary["status"],
        "gate_count" => summary["gate_count"],
        "passed_gate_count" => summary["passed_gate_count"],
        "review_gate_count" => summary["review_gate_count"],
        "analysis_gate_count" => summary["analysis_gate_count"],
        "blocked_gate_count" => summary["blocked_gate_count"],
        "gate_status_counts" => summary["gate_status_counts"],
        "gate_classification_counts" => summary["gate_classification_counts"],
        "passed_gate_ids" => summary["passed_gate_ids"],
        "review_required_gate_ids" => summary["review_required_gate_ids"],
        "analysis_only_gate_ids" => summary["analysis_only_gate_ids"],
        "blocked_gate_ids" => summary["blocked_gate_ids"],
        "non_passed_gate_ids" => summary["non_passed_gate_ids"],
        "assumptions" => summary["assumptions"],
        "required_operator_action" => operational_readiness_pressure_action(classification)
      }
      |> Map.merge(operational_readiness_import_readiness_context(summary))
      |> Map.merge(operational_readiness_schema_validation_context(summary))
      |> Map.merge(operational_readiness_resource_availability_context(summary))
      |> compact_map()

    gate_rows =
      summary
      |> Map.get("non_passed_gates", [])
      |> List.wrap()
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(fn gate ->
        classification = operational_readiness_gate_pressure_classification(gate)
        gate_status = gate["status"] || "review_required"

        %{
          "source" => "operational_readiness_gate_summary.non_passed_gates",
          "source_artifact_type" => summary["source_artifact_type"],
          "source_artifact_id" => summary["source_artifact_id"],
          "readiness_level" => operational_readiness_pressure_level(classification),
          "import_classification" => classification,
          "operational_readiness_status" => gate_status,
          "readiness_gate_id" => gate["id"] || "operational_gate",
          "readiness_gate_status" => gate_status,
          "readiness_gate_classification" => classification,
          "readiness_gate_reason" => gate["reason"],
          "analysis_mode" => gate["analysis_mode"],
          "analysis_mode_source" => gate["analysis_mode_source"],
          "gate_status_counts" => summary["gate_status_counts"],
          "gate_classification_counts" => summary["gate_classification_counts"],
          "passed_gate_ids" => summary["passed_gate_ids"],
          "review_required_gate_ids" => summary["review_required_gate_ids"],
          "analysis_only_gate_ids" => summary["analysis_only_gate_ids"],
          "blocked_gate_ids" => summary["blocked_gate_ids"],
          "non_passed_gate_ids" => summary["non_passed_gate_ids"],
          "assumptions" => summary["assumptions"],
          "required_operator_action" => operational_readiness_pressure_action(classification),
          "source_operational_readiness_gate" => gate
        }
        |> Map.merge(operational_readiness_operator_training_context(gate))
        |> Map.merge(operational_readiness_import_readiness_context(gate))
        |> Map.merge(operational_readiness_schema_validation_context(gate))
        |> Map.merge(operational_readiness_resource_availability_context(gate))
        |> compact_map()
      end)

    [summary_row | gate_rows]
  end

  defp operational_readiness_gate_pressure_classification(%{"status" => "blocked"}),
    do: "blocked"

  defp operational_readiness_gate_pressure_classification(%{"status" => "analysis_only"}),
    do: "analysis_only"

  defp operational_readiness_gate_pressure_classification(%{"classification" => classification})
       when classification not in [nil, ""],
       do: classification

  defp operational_readiness_gate_pressure_classification(_gate), do: "review_only"

  defp operational_readiness_pressure_action("analysis_only"),
    do: "record_operational_readiness_analysis_only"

  defp operational_readiness_pressure_action("blocked"),
    do: "review_blocked_operational_readiness"

  defp operational_readiness_pressure_action(_classification),
    do: "review_operational_readiness"

  defp operational_readiness_pressure_level("analysis_only"), do: "analysis_only"
  defp operational_readiness_pressure_level("blocked"), do: "blocked"
  defp operational_readiness_pressure_level("importable"), do: "import_eligible"
  defp operational_readiness_pressure_level(_classification), do: "operator_review"

  defp mission_state_quality_gate_reports(mission_state) do
    mission_state = stringify_keys(mission_state || %{})

    direct_reports =
      [
        {"source_quality_gate_report", "mission_state.source_quality_gate_report"},
        {"quality_gate_report", "mission_state.quality_gate_report"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        mission_state
        |> Map.get(field)
        |> mission_state_source_report_entries(source_path)
      end)

    direct_reports ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "source_quality_gate_report"
      ) ++
      mission_state_result_artifact_embedded_reports(mission_state, "quality_gate_report")
  end

  defp mission_state_quality_gate_summary_reports(mission_state) do
    mission_state = stringify_keys(mission_state || %{})

    direct_reports =
      [
        {"source_operational_quality_gate_summary",
         "mission_state.source_operational_quality_gate_summary"},
        {"operational_quality_gate_summary", "mission_state.operational_quality_gate_summary"},
        {"source_operational_quality_gate_unavailable_resource_summary",
         "mission_state.source_operational_quality_gate_unavailable_resource_summary"},
        {"operational_quality_gate_unavailable_resource_summary",
         "mission_state.operational_quality_gate_unavailable_resource_summary"},
        {"source_operational_quality_gate_operator_training_summary",
         "mission_state.source_operational_quality_gate_operator_training_summary"},
        {"operational_quality_gate_operator_training_summary",
         "mission_state.operational_quality_gate_operator_training_summary"},
        {"source_operational_quality_gate_schema_validation_summary",
         "mission_state.source_operational_quality_gate_schema_validation_summary"},
        {"operational_quality_gate_schema_validation_summary",
         "mission_state.operational_quality_gate_schema_validation_summary"},
        {"source_operational_quality_gate_import_readiness_summary",
         "mission_state.source_operational_quality_gate_import_readiness_summary"},
        {"operational_quality_gate_import_readiness_summary",
         "mission_state.operational_quality_gate_import_readiness_summary"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        mission_state
        |> Map.get(field)
        |> mission_state_source_report_entries(source_path)
      end)

    direct_reports ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "source_operational_quality_gate_summary"
      ) ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "operational_quality_gate_summary"
      ) ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "source_operational_quality_gate_unavailable_resource_summary"
      ) ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "operational_quality_gate_unavailable_resource_summary"
      ) ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "source_operational_quality_gate_operator_training_summary"
      ) ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "operational_quality_gate_operator_training_summary"
      ) ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "source_operational_quality_gate_schema_validation_summary"
      ) ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "operational_quality_gate_schema_validation_summary"
      ) ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "source_operational_quality_gate_import_readiness_summary"
      ) ++
      mission_state_result_artifact_embedded_reports(
        mission_state,
        "operational_quality_gate_import_readiness_summary"
      )
  end

  defp mission_state_quality_gate_pressure_sources(mission_state) do
    mission_state_quality_gate_reports(mission_state) ++
      mission_state_quality_gate_summary_reports(mission_state)
  end

  defp prior_plan_quality_gate_pressure_sources(prior_plan) do
    prior_plan_quality_gate_reports(prior_plan) ++
      prior_plan_quality_gate_summary_reports(prior_plan)
  end

  defp prior_plan_quality_gate_reports(prior_plan) do
    prior_plan = stringify_keys(prior_plan || %{})

    direct_reports =
      [
        {"source_quality_gate_report", "prior_plan.source_quality_gate_report"},
        {"quality_gate_report", "prior_plan.quality_gate_report"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        prior_plan
        |> Map.get(field)
        |> mission_state_source_report_entries(source_path)
      end)

    direct_reports ++ prior_plan_result_artifact_quality_gate_reports(prior_plan)
  end

  defp prior_plan_quality_gate_summary_reports(prior_plan) do
    prior_plan = stringify_keys(prior_plan || %{})

    direct_reports =
      [
        {"source_operational_quality_gate_summary",
         "prior_plan.source_operational_quality_gate_summary"},
        {"operational_quality_gate_summary", "prior_plan.operational_quality_gate_summary"},
        {"source_operational_quality_gate_unavailable_resource_summary",
         "prior_plan.source_operational_quality_gate_unavailable_resource_summary"},
        {"operational_quality_gate_unavailable_resource_summary",
         "prior_plan.operational_quality_gate_unavailable_resource_summary"},
        {"source_operational_quality_gate_operator_training_summary",
         "prior_plan.source_operational_quality_gate_operator_training_summary"},
        {"operational_quality_gate_operator_training_summary",
         "prior_plan.operational_quality_gate_operator_training_summary"},
        {"source_operational_quality_gate_schema_validation_summary",
         "prior_plan.source_operational_quality_gate_schema_validation_summary"},
        {"operational_quality_gate_schema_validation_summary",
         "prior_plan.operational_quality_gate_schema_validation_summary"},
        {"source_operational_quality_gate_import_readiness_summary",
         "prior_plan.source_operational_quality_gate_import_readiness_summary"},
        {"operational_quality_gate_import_readiness_summary",
         "prior_plan.operational_quality_gate_import_readiness_summary"}
      ]
      |> Enum.flat_map(fn {field, source_path} ->
        prior_plan
        |> Map.get(field)
        |> mission_state_source_report_entries(source_path)
      end)

    direct_reports ++ prior_plan_result_artifact_quality_gate_summary_reports(prior_plan)
  end

  defp prior_plan_result_artifact_quality_gate_reports(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, source_path} ->
      result_artifact_quality_gate_reports(artifact, source_path)
    end)
  end

  defp result_artifact_quality_gate_reports(artifact, source_path) do
    artifact = stringify_keys(artifact)

    if artifact["schema_contract"] == "quality_gate_report.v1" do
      [{put_inherited_result_artifact_trust_boundary(artifact, artifact), source_path}]
    else
      ["source_quality_gate_report", "quality_gate_report"]
      |> Enum.flat_map(fn report_key ->
        result_artifact_embedded_report_entries(
          Map.get(artifact, report_key),
          artifact,
          "#{source_path}.#{report_key}"
        )
      end)
    end
  end

  defp prior_plan_result_artifact_quality_gate_summary_reports(prior_plan) do
    prior_plan_result_artifact_embedded_reports(prior_plan, [
      "source_operational_quality_gate_summary",
      "operational_quality_gate_summary",
      "source_operational_quality_gate_unavailable_resource_summary",
      "operational_quality_gate_unavailable_resource_summary",
      "source_operational_quality_gate_operator_training_summary",
      "operational_quality_gate_operator_training_summary",
      "source_operational_quality_gate_schema_validation_summary",
      "operational_quality_gate_schema_validation_summary",
      "source_operational_quality_gate_import_readiness_summary",
      "operational_quality_gate_import_readiness_summary"
    ])
  end

  defp mission_state_source_quality_gate_reports(mission_state) do
    mission_state_quality_gate_reports(mission_state, [
      {"source_quality_gate_report", "mission_state.source_quality_gate_report"}
    ])
  end

  defp mission_state_canonical_quality_gate_reports(mission_state) do
    mission_state_quality_gate_reports(mission_state, [
      {"quality_gate_report", "mission_state.quality_gate_report"}
    ])
  end

  defp mission_state_quality_gate_reports(mission_state, fields) do
    mission_state = stringify_keys(mission_state || %{})

    fields
    |> Enum.flat_map(fn {field, source_path} ->
      mission_state
      |> Map.get(field)
      |> mission_state_source_report_entries(source_path)
    end)
  end

  defp quality_gate_pressure_branch(row, source_path, index) do
    case quality_gate_pressure_event(row, source_path) do
      nil ->
        []

      event ->
        identity = quality_gate_pressure_identity(row, index)

        [
          %{
            "id" => "derived_quality_gate_pressure_#{identity}",
            "label" => "Derived quality-gate review #{identity}",
            "events" => [event],
            "metadata" => %{"derived_source" => source_path}
          }
        ]
    end
  end

  defp quality_gate_pressure_event(row, source_path) do
    if quality_gate_reviewable?(row) do
      %{
        "type" => "quality_gate_pressure",
        "report_id" => row["report_id"],
        "source_artifact_type" => row["source_artifact_type"],
        "source_artifact_id" => row["source_artifact_id"],
        "source_readiness_report_id" => row["source_readiness_report_id"],
        "readiness_level" => row["readiness_level"],
        "import_classification" => row["import_classification"],
        "quality_gate_status" => row["quality_gate_status"],
        "gate_count" => row["gate_count"],
        "passed_gate_count" => row["passed_gate_count"],
        "review_gate_count" => row["review_gate_count"],
        "analysis_gate_count" => row["analysis_gate_count"],
        "blocked_gate_count" => row["blocked_gate_count"],
        "gate_id" => row["gate_id"],
        "gate_status" => row["gate_status"],
        "gate_classification" => row["gate_classification"],
        "gate_reason" => row["gate_reason"],
        "analysis_mode" => row["analysis_mode"],
        "analysis_mode_source" => row["analysis_mode_source"],
        "required_operator_action" => quality_gate_pressure_action(row["gate_classification"]),
        "derivation_reasons" => ["quality_gate_review"],
        "feedback_source" => source_path,
        "feedback_scope" => "quality_gate",
        "feedback_key" => row["gate_id"] || row["report_id"] || "quality_gate",
        "trust_boundary" => operator_review_trust_boundary(row),
        "assumptions" => row["assumptions"],
        "source_quality_gate_row" => row["source_quality_gate_row"],
        "source_quality_gate_report" => row["source_quality_gate_report"]
      }
      |> Map.merge(operational_readiness_operator_training_context(row))
      |> Map.merge(quality_gate_import_readiness_context(row))
      |> Map.merge(quality_gate_schema_validation_context(row))
      |> Map.merge(quality_gate_resource_context(row))
      |> compact_map()
    end
  end

  defp quality_gate_reviewable?(row), do: row["gate_status"] not in [nil, "passed"]

  defp quality_gate_pressure_identity(row, index) do
    [
      row["gate_id"],
      row["report_id"],
      row["source_artifact_id"],
      row["gate_status"],
      index
    ]
    |> Enum.find(&(&1 not in [nil, ""]))
    |> branch_id_fragment()
  end

  defp derived_quality_gate_pressure_branches(prior_plan) do
    prior_plan
    |> prior_plan_quality_gate_pressure_sources()
    |> quality_gate_pressure_branches_from_sources()
  end

  defp derived_mission_state_quality_gate_pressure_branches(mission_state) do
    mission_state
    |> mission_state_quality_gate_pressure_sources()
    |> quality_gate_pressure_branches_from_sources()
  end

  defp quality_gate_pressure_branches_from_sources(sources) do
    sources
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> quality_gate_pressure_rows()
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {row, index} ->
        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> quality_gate_pressure_branch(quality_gate_pressure_row_source(row, source_path), index)
      end)
    end)
  end

  defp quality_gate_pressure_row_source(row, source_path) do
    row_source = Map.get(row, "source", "quality_gate_report")

    cond do
      String.starts_with?(row_source, "quality_gate_report") ->
        String.replace_prefix(row_source, "quality_gate_report", source_path)

      String.starts_with?(row_source, "operational_quality_gate_summary") ->
        String.replace_prefix(row_source, "operational_quality_gate_summary", source_path)

      String.starts_with?(row_source, "operational_quality_gate_unavailable_resource_summary") ->
        String.replace_prefix(
          row_source,
          "operational_quality_gate_unavailable_resource_summary",
          source_path
        )

      String.starts_with?(row_source, "operational_quality_gate_operator_training_summary") ->
        String.replace_prefix(
          row_source,
          "operational_quality_gate_operator_training_summary",
          source_path
        )

      String.starts_with?(row_source, "operational_quality_gate_schema_validation_summary") ->
        String.replace_prefix(
          row_source,
          "operational_quality_gate_schema_validation_summary",
          source_path
        )

      String.starts_with?(row_source, "operational_quality_gate_import_readiness_summary") ->
        String.replace_prefix(
          row_source,
          "operational_quality_gate_import_readiness_summary",
          source_path
        )

      true ->
        source_path
    end
  end

