  defp quality_gate_status_row_ids(summary, status) do
    status = to_string(status)

    case quality_gate_status_row_ids_by_status(summary) do
      {:ok, ids_by_status} ->
        Map.get(ids_by_status, status, [])

      :missing ->
        summary
        |> Map.get(quality_gate_status_row_ids_field(status))
        |> import_readiness_string_ids()
    end
  end

  defp quality_gate_status_scoped_row_ids(summary, field, statuses) do
    row_ids = import_readiness_string_ids(Map.get(summary, field))

    case quality_gate_status_row_ids_by_status(summary) do
      {:ok, ids_by_status} ->
        allowed_ids =
          statuses
          |> Enum.flat_map(&Map.get(ids_by_status, to_string(&1), []))
          |> MapSet.new()

        Enum.filter(row_ids, &MapSet.member?(allowed_ids, &1))

      :missing ->
        row_ids
    end
  end

  defp import_readiness_summary_flag(summary, field, row_ids) do
    case quality_gate_status_row_ids_by_status(summary) do
      {:ok, _ids_by_status} -> length(row_ids) > 0
      :missing -> summary[field]
    end
  end

  defp quality_gate_status_row_ids_by_status(summary) do
    case Map.fetch(summary, "quality_gate_row_ids_by_status") do
      {:ok, %{} = ids_by_status} ->
        {:ok,
         ids_by_status
         |> stringify_keys()
         |> Enum.map(fn {status, ids} -> {status, import_readiness_string_ids(ids)} end)
         |> Map.new()}

      _value ->
        :missing
    end
  end

  defp quality_gate_status_row_ids_field("analysis_only"),
    do: "analysis_only_quality_gate_row_ids"

  defp quality_gate_status_row_ids_field("blocked"), do: "blocked_quality_gate_row_ids"

  defp quality_gate_status_row_ids_field(_status),
    do: "review_required_quality_gate_row_ids"

  defp import_readiness_string_ids(values) do
    values
    |> List.wrap()
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
  end

  defp unavailable_resource_summary_resource_availability_reason_counts(summary) do
    [
      summary["unavailable_resource_reason_counts"],
      summary["station_availability_reason_counts"]
    ]
    |> Enum.filter(&is_map/1)
    |> Enum.reduce(%{}, fn counts, merged ->
      counts
      |> stringify_keys()
      |> Enum.reduce(merged, fn {key, value}, acc ->
        case numeric_or_nil(value) do
          number when is_number(number) and number > 0 ->
            Map.update(acc, key, number, &(&1 + number))

          _value ->
            acc
        end
      end)
    end)
  end

  defp count_map_value_sum(counts) when is_map(counts) do
    counts
    |> Map.values()
    |> Enum.map(&numeric_or_nil/1)
    |> Enum.filter(&is_number/1)
    |> Enum.sum()
  end

  defp count_map_value_sum(_counts), do: 0

  defp sorted_count_map_keys(counts) when is_map(counts) do
    counts
    |> Enum.filter(fn {_key, value} ->
      case numeric_or_nil(value) do
        number when is_number(number) -> number > 0
        _value -> false
      end
    end)
    |> Enum.map(fn {key, _value} -> encode_value(key) end)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp sorted_count_map_keys(_counts), do: []

