  defp model_acceptance_pressure_branch(row, source_path, index) do
    case model_acceptance_pressure_event(row, source_path) do
      nil ->
        []

      event ->
        identity = model_acceptance_pressure_identity(row, index)

        [
          %{
            "id" => "derived_model_acceptance_pressure_#{identity}",
            "label" => "Derived model-acceptance review #{identity}",
            "events" => [event],
            "metadata" => %{"derived_source" => source_path}
          }
        ]
    end
  end

  defp model_acceptance_pressure_event(row, source_path) do
    if model_acceptance_reviewable?(row) do
      %{
        "type" => "model_acceptance_pressure",
        "report_id" => row["report_id"],
        "intended_use" => row["intended_use"],
        "model_acceptance_status" => row["model_acceptance_status"],
        "model_count" => row["model_count"],
        "accepted_count" => row["accepted_count"],
        "review_required_count" => row["review_required_count"],
        "blocked_count" => row["blocked_count"],
        "unknown_model_count" => row["unknown_model_count"],
        "status_counts" => row["status_counts"],
        "validation_level_counts" => row["validation_level_counts"],
        "model_ids_by_status" => row["model_ids_by_status"],
        "model_ids_by_validation_level" => row["model_ids_by_validation_level"],
        "model_ids_by_intended_use" => row["model_ids_by_intended_use"],
        "model_id" => row["model_id"],
        "validation_level" => row["validation_level"],
        "model_status" => row["model_status"],
        "model_reason" => row["model_reason"],
        "required_operator_action" => model_acceptance_pressure_action(row),
        "derivation_reasons" => ["model_acceptance_review"],
        "feedback_source" => source_path,
        "feedback_scope" => "model_acceptance",
        "feedback_key" => row["model_id"] || row["report_id"] || "model_acceptance",
        "trust_boundary" => operator_review_trust_boundary(row),
        "source_model_acceptance_row" => row["source_model_acceptance_row"],
        "source_model_acceptance_report" => row["source_model_acceptance_report"]
      }
      |> compact_map()
    end
  end

  defp model_acceptance_reviewable?(row),
    do:
      row["model_status"] in ["review_required", "blocked"] or
        row["validation_level"] == "unknown"

  defp model_acceptance_pressure_identity(row, index) do
    [
      row["model_id"],
      row["report_id"],
      row["intended_use"],
      row["model_status"],
      index
    ]
    |> Enum.find(&(&1 not in [nil, ""]))
    |> branch_id_fragment()
  end

  defp derived_mission_state_model_acceptance_pressure_branches(mission_state) do
    mission_state
    |> mission_state_model_acceptance_reports()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> model_acceptance_pressure_rows()
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {row, index} ->
        row_source =
          row
          |> Map.get("source", "model_acceptance_report")
          |> String.replace_prefix("model_acceptance_report", source_path)

        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> model_acceptance_pressure_branch(row_source, index)
      end)
    end)
  end

  defp model_acceptance_pressure_rows(report) do
    report = stringify_keys(report || %{})

    report
    |> Map.get("rows", [])
    |> List.wrap()
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(fn row ->
      %{
        "source" => "model_acceptance_report.rows",
        "report_id" => report["report_id"],
        "intended_use" => report["intended_use"],
        "model_acceptance_status" => report["status"],
        "model_count" => report["model_count"],
        "accepted_count" => report["accepted_count"],
        "review_required_count" => report["review_required_count"],
        "blocked_count" => report["blocked_count"],
        "unknown_model_count" => report["unknown_model_count"],
        "status_counts" => report["status_counts"],
        "validation_level_counts" => report["validation_level_counts"],
        "model_ids_by_status" => report["model_ids_by_status"],
        "model_ids_by_validation_level" => report["model_ids_by_validation_level"],
        "model_ids_by_intended_use" => report["model_ids_by_intended_use"],
        "model_id" => row["model_id"],
        "validation_level" => row["validation_level"],
        "model_status" => row["status"],
        "model_reason" => row["reason"],
        "source_model_acceptance_row" => row,
        "source_model_acceptance_report" => report
      }
      |> compact_map()
    end)
  end

