        "review_required_evidence_count" => row["review_required_evidence_count"],
        "blocked_evidence_count" => row["blocked_evidence_count"],
        "schema_error_count" => row["schema_error_count"],
        "schema_warning_count" => row["schema_warning_count"],
        "model_blocked_count" => row["model_blocked_count"],
        "quality_gate_review_count" => row["quality_gate_review_count"],
        "quality_gate_blocked_count" => row["quality_gate_blocked_count"],
        "evidence_status_counts" => row["evidence_status_counts"],
        "evidence_refs_by_status" => row["evidence_refs_by_status"],
        "evidence_refs_by_contract" => row["evidence_refs_by_contract"],
        "required_operator_action" => validation_safety_case_pressure_action(row),
        "derivation_reasons" => ["validation_safety_case_review"],
        "feedback_source" => source_path,
        "feedback_scope" => "validation_safety_case",
        "feedback_key" =>
          row["evidence_ref"] || row["input_contract"] || row["report_id"] ||
            "validation_safety_case",
        "trust_boundary" => operator_review_trust_boundary(row),
        "source_validation_safety_case_evidence" => row["source_validation_safety_case_evidence"],
        "source_validation_safety_case_summary" => row["source_validation_safety_case_summary"]
      }
      |> compact_map()
    end
  end

  defp validation_safety_case_reviewable?(row),
    do:
      row["evidence_status"] in ["review_required", "blocked"] or
        row["validation_safety_case_status"] in ["review_required", "blocked"]

  defp validation_safety_case_pressure_identity(row, index) do
    [
      row["evidence_ref"],
      row["input_contract"],
      row["report_id"],
      row["evidence_status"],
      index
    ]
    |> Enum.find(&(&1 not in [nil, ""]))
    |> branch_id_fragment()
  end

  defp derived_mission_state_validation_safety_case_pressure_branches(mission_state) do
    mission_state
    |> mission_state_validation_safety_case_summaries()
    |> Enum.flat_map(fn {report, source_path} ->
      trust_boundary =
        Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

      report
      |> validation_safety_case_pressure_rows()
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {row, index} ->
        row_source =
          row
          |> Map.get("source", "validation_safety_case_summary")
          |> String.replace_prefix("validation_safety_case_summary", source_path)

        row
        |> Map.put("_source_report_trust_boundary", trust_boundary)
        |> validation_safety_case_pressure_branch(row_source, index)
      end)
    end)
  end

  defp validation_safety_case_pressure_rows(report) do
    report = stringify_keys(report || %{})

    evidence_rows =
      report
      |> Map.get("evidence", [])
      |> List.wrap()
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(fn evidence ->
        %{
          "source" => "validation_safety_case_summary.evidence",
          "report_id" => report["report_id"],
          "validation_safety_case_status" => report["status"],
          "evidence_status" => evidence["status"],
          "input_contract" => evidence["input_contract"] || evidence["contract"],
          "input_contracts" => report["input_contracts"],
          "evidence_ref" => evidence["ref"] || evidence["evidence_ref"] || evidence["id"],
          "evidence_count" => report["evidence_count"] || length(List.wrap(report["evidence"])),
          "accepted_evidence_count" => report["accepted_evidence_count"],
          "review_required_evidence_count" => report["review_required_evidence_count"],
          "blocked_evidence_count" => report["blocked_evidence_count"],
          "schema_error_count" => report["schema_error_count"],
          "schema_warning_count" => report["schema_warning_count"],
          "model_blocked_count" => report["model_blocked_count"],
          "quality_gate_review_count" => report["quality_gate_review_count"],
          "quality_gate_blocked_count" => report["quality_gate_blocked_count"],
          "evidence_status_counts" => report["evidence_status_counts"],
          "evidence_refs_by_status" => report["evidence_refs_by_status"],
          "evidence_refs_by_contract" => report["evidence_refs_by_contract"],
          "source_validation_safety_case_evidence" => evidence,
          "source_validation_safety_case_summary" => report
        }
        |> compact_map()
      end)

    if evidence_rows == [] do
      [
        %{
          "source" => "validation_safety_case_summary",
          "report_id" => report["report_id"],
          "validation_safety_case_status" => report["status"],
          "input_contracts" => report["input_contracts"],
          "evidence_count" => report["evidence_count"],
          "accepted_evidence_count" => report["accepted_evidence_count"],
          "review_required_evidence_count" => report["review_required_evidence_count"],
          "blocked_evidence_count" => report["blocked_evidence_count"],
          "schema_error_count" => report["schema_error_count"],
          "schema_warning_count" => report["schema_warning_count"],
          "model_blocked_count" => report["model_blocked_count"],
          "quality_gate_review_count" => report["quality_gate_review_count"],
          "quality_gate_blocked_count" => report["quality_gate_blocked_count"],
          "evidence_status_counts" => report["evidence_status_counts"],
          "evidence_refs_by_status" => report["evidence_refs_by_status"],
          "evidence_refs_by_contract" => report["evidence_refs_by_contract"],
          "source_validation_safety_case_summary" => report
        }
        |> compact_map()
      ]
    else
      evidence_rows
    end
  end

  defp validation_safety_case_pressure_action(%{"evidence_status" => "blocked"}),
    do: "review_blocked_validation_safety_case"

  defp validation_safety_case_pressure_action(%{
         "validation_safety_case_status" => "blocked"
       }),
       do: "review_blocked_validation_safety_case"

