  defp put_feedback_weight_fields(event, source) do
    [
      "feedback_weight",
      "feedback_weight_source",
      "feedback_sample_weight",
      "feedback_sample_weight_source",
      "sample_weight",
      "sample_weight_source",
      "confidence_weight",
      "confidence_weight_source"
    ]
    |> Enum.reduce(event, fn field, acc -> put_if_present(acc, field, source[field]) end)
  end

  defp put_observation_quality_feedback_fields(event, source) do
    event
    |> put_if_present("image_quality_score", image_quality_score_value(source))
    |> put_if_present("image_quality_status", image_quality_status_value(source))
    |> put_if_present("image_quality_source", image_quality_source_value(source))
    |> put_if_present("cloud_cover_fraction", cloud_cover_fraction_value(source))
    |> put_if_present("blur_score", blur_score_value(source))
  end

  defp put_default_if_present(map, _field, value) when value in [nil, "", [], %{}], do: map

  defp put_default_if_present(map, field, value) do
    case Map.get(map, field) do
      existing when existing in [nil, ""] -> Map.put(map, field, value)
      _existing -> map
    end
  end

  defp resource_projection_review_source(%{"source_resource_projection" => %{} = source})
       when map_size(source) > 0,
       do: {source, "source_resource_projection"}

  defp resource_projection_review_source(row), do: {row, "resource_projection_review"}

  defp resource_projection_review_row?(row) do
    resource_projection_review_like?(row) and
      resource_projection_review_pressure_row?(row)
  end

  defp resource_projection_review_like?(row) do
    row["source_review_type"] == "resource_projection_review" or
      row["review_type"] == "resource_projection_review" or
      row["import_action"] == "review_resource_projection"
  end

  defp resource_projection_review_pressure_row?(row) do
    pressure_types = row |> Map.get("resource_pressure_types", []) |> List.wrap()

    Enum.any?(
      [
        row["projected_storage_overflow_mb"],
        row["projected_downlink_shortfall_mb"],
        row["projected_battery_overuse_wh"]
      ],
      &(numeric_or_nil(&1) |> positive_number?())
    ) or
      resource_projection_thermal_pressure_row?(row, pressure_types) or
      Enum.any?(pressure_types, &(&1 in resource_projection_availability_pressure_types()))
  end

  defp resource_projection_thermal_pressure_row?(row, pressure_types) do
    case numeric_or_nil(row["thermal_margin_c"]) do
      value when is_number(value) and value < 0.0 -> true
      _value -> "thermal_margin_below_limit" in pressure_types
    end
  end

  defp link_capacity_review_source(%{"source_link_capacity" => %{} = source})
