  defp derived_urgent_target_branches(mission_state, prior_plan, policy) do
    scheduled_target_counts =
      effective_scheduled_target_counts(prior_plan, mission_state)

    objectives =
      mission_state
      |> Map.get("objectives", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.reject(&coverage_objective?/1)
      |> Enum.flat_map(&expand_target_selector_objective/1)
      |> Kernel.++(target_coverage_objectives(mission_state))
      |> Kernel.++(realized_observation_revisit_objectives(mission_state, prior_plan))

    objectives
    |> Enum.map(fn objective ->
      planned_count =
        effective_scheduled_target_count(
          objective,
          prior_plan,
          mission_state,
          scheduled_target_counts
        )

      {objective, planned_count}
    end)
    |> Enum.filter(fn {objective, planned_count} ->
      target_id = Map.get(objective, "target_id") || Map.get(objective, "id")

      target_id not in [nil, ""] and
        target_objective_needs_branch?(objective, planned_count, policy)
    end)
    |> Enum.map(fn {objective, planned_count} ->
      target_id = Map.get(objective, "target_id") || Map.get(objective, "id")
      objective_type = objective["type"]

      event =
        objective
        |> Map.take([
          "objective_id",
          "target_id",
          "scenario_id",
          "priority",
          "latitude_deg",
          "longitude_deg",
          "minimum_elevation_deg",
          "starts_at_s",
          "ends_at_s",
          "candidate_windows",
          "spacecraft_constraints",
          "commitment_id",
          "coverage_objective_id",
          "required_count",
          "required_observations",
          "required_revisits",
          "source_activity_id",
          "source_activity_ids",
          "realized_status",
          "derivation_reason"
        ])
        |> Map.put("type", "urgent_target")
        |> Map.put("target_id", target_id)
        |> Map.put("objective_type", objective_type)
        |> Map.put("planned_observations", planned_count)
        |> maybe_put_required_observations(objective)
        |> Map.put("allow_placeholder", policy["allow_urgent_placeholder"])

      %{
        "id" => derived_target_branch_id(objective_type, target_id),
        "label" => derived_target_branch_label(objective_type, target_id),
        "events" => [event],
        "metadata" =>
          %{
            "derived_source" => "mission_state.objectives",
            "target_objective_branch_suffix" =>
              target_objective_branch_suffix(objective, target_id)
          }
          |> compact_map()
      }
    end)
    |> disambiguate_derived_target_branch_ids()
  end

  defp effective_scheduled_target_counts(prior_plan, mission_state) do
    missed_by_target =
      mission_state
      |> realized_observation_events(prior_plan)
      |> Enum.map(& &1["target_id"])
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.frequencies()

    prior_plan
    |> Map.get("activities", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(&(&1["type"] == "observe"))
    |> Enum.map(& &1["target_id"])
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.frequencies()
    |> Map.new(fn {target_id, count} ->
      {target_id, max(count - Map.get(missed_by_target, target_id, 0), 0)}
    end)
  end

  defp effective_scheduled_target_count(
         objective,
         prior_plan,
         mission_state,
         scheduled_target_counts
       ) do
    target_id = Map.get(objective, "target_id") || Map.get(objective, "id")

    if scoped_target_objective?(objective) do
      missed_ids =
        mission_state
        |> realized_observation_events(prior_plan)
        |> Enum.filter(&target_objective_activity_match?(&1, objective))
        |> Enum.map(& &1["id"])
        |> Enum.reject(&(&1 in [nil, ""]))
        |> MapSet.new()

      prior_plan
      |> prior_plan_activities()
      |> Enum.map(&stringify_keys/1)
      |> Enum.reject(&MapSet.member?(missed_ids, &1["id"]))
      |> Enum.count(&target_objective_activity_match?(&1, objective))
    else
      Map.get(scheduled_target_counts, target_id, 0)
    end
  end

  defp scoped_target_objective?(objective) do
    Enum.any?(
      ["scenario_id", "starts_at_s", "start_s", "ends_at_s", "end_s"],
      &Map.has_key?(objective, &1)
    )
  end

  defp target_objective_activity_match?(activity, objective) do
    target_id = Map.get(objective, "target_id") || Map.get(objective, "id")

    activity["type"] == "observe" and
      (is_nil(target_id) or activity["target_id"] == target_id) and
      urgent_target_spacecraft_match?(activity, objective) and
      target_event_window_match?(activity, objective)
  end

  defp realized_observation_revisit_objectives(mission_state, prior_plan) do
    mission_state
    |> realized_observation_events(prior_plan)
    |> Enum.map(fn realized ->
      %{
        "type" => "target_revisit",
        "target_id" => realized["target_id"],
        "required_observations" => 1,
        "priority" => numeric_or_nil(Map.get(realized, "priority")) || 1.0,
        "source_activity_id" => realized["id"],
        "realized_status" => realized["status"],
        "derivation_reason" => "realized_observation_#{realized["status"]}"
      }
    end)
    |> Enum.reject(&(&1["target_id"] in [nil, ""]))
    |> dedupe_realized_revisit_objectives()
  end

  defp expand_target_selector_objective(%{"type" => type} = objective)
       when type in ["priority_commitment", "target_revisit", "target_observation"] do
    case target_selector_target_ids(objective) do
      [] ->
        [objective]

      target_ids ->
        target_specs = coverage_target_specs(objective)

        Enum.map(target_ids, fn target_id ->
          objective
          |> Map.put("target_id", target_id)
          |> maybe_put_objective_id()
          |> maybe_put_commitment_id()
          |> put_inline_target_spec(target_specs[target_id])
        end)
    end
  end

  defp expand_target_selector_objective(objective), do: [objective]

  defp maybe_put_objective_id(%{"id" => id} = objective) when id not in [nil, ""],
    do: Map.put_new(objective, "objective_id", id)

  defp maybe_put_objective_id(objective), do: objective

  defp maybe_put_commitment_id(%{"type" => "priority_commitment"} = objective) do
    Map.put_new(objective, "commitment_id", Map.get(objective, "id"))
  end

  defp maybe_put_commitment_id(objective), do: objective

  defp put_inline_target_spec(objective, nil), do: objective

  defp put_inline_target_spec(objective, target) do
    target
    |> Map.take(["latitude_deg", "longitude_deg", "minimum_elevation_deg", "priority"])
    |> Enum.reduce(objective, fn {key, value}, acc -> Map.put_new(acc, key, value) end)
  end

  defp target_selector_target_ids(objective) do
    [
      Map.get(objective, "target_id"),
      Map.get(objective, "target_ids"),
      Map.get(objective, "required_target_ids"),
      Map.get(objective, "targets"),
      Map.get(objective, "target_specs"),
      Map.get(objective, "required_targets"),
      Map.get(objective, "committed_targets"),
      Map.get(objective, "priority_targets")
    ]
    |> Enum.flat_map(fn
      values when is_list(values) -> Enum.map(values, &coverage_target_id/1)
      value -> [coverage_target_id(value)]
    end)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp disambiguate_derived_target_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.map_reduce(%{}, fn branch, seen ->
      branch_id = branch["id"]

      if Map.get(id_counts, branch_id, 0) <= 1 do
        {delete_target_branch_suffix(branch), seen}
      else
        suffix = get_in(branch, ["metadata", "target_objective_branch_suffix"]) || "duplicate"
        candidate_id = "#{branch_id}_#{suffix}"
        occurrence = Map.get(seen, candidate_id, 0) + 1
        next_seen = Map.put(seen, candidate_id, occurrence)

        disambiguated_id =
          if occurrence == 1 do
            candidate_id
          else
            "#{candidate_id}_#{occurrence}"
          end

        {
          branch
          |> Map.put("id", disambiguated_id)
          |> Map.put("label", "#{branch["label"]} #{suffix}")
          |> Map.update("metadata", %{}, fn metadata ->
            metadata
            |> Map.put("target_branch_base_id", branch_id)
            |> Map.put("target_branch_identity", suffix)
            |> Map.delete("target_objective_branch_suffix")
          end),
          next_seen
        }
      end
    end)
    |> elem(0)
  end

  defp delete_target_branch_suffix(branch) do
    Map.update(branch, "metadata", %{}, &Map.delete(&1, "target_objective_branch_suffix"))
  end

  defp target_objective_branch_suffix(objective, target_id) do
    stable_identity =
      [
        Map.get(objective, "objective_id"),
        Map.get(objective, "id"),
        Map.get(objective, "commitment_id"),
        Map.get(objective, "coverage_objective_id"),
        Map.get(objective, "source_activity_id")
      ]
      |> Enum.find(&(&1 not in [nil, ""]))

    case stable_identity do
      value when value not in [nil, ""] ->
        branch_id_fragment(value)

      _missing ->
        [
          Map.get(objective, "scenario_id"),
          objective_window_start(objective, nil),
          objective_window_end(objective, nil),
          target_id
        ]
        |> Enum.reject(&(&1 in [nil, ""]))
        |> Enum.map(&branch_id_fragment/1)
        |> Enum.join("_")
    end
  end

  defp branch_id_fragment(value) do
    value
    |> encode_value()
    |> to_string()
    |> String.replace(~r/[^A-Za-z0-9._:@-]+/, "_")
    |> String.trim("_")
    |> case do
      "" -> "unnamed"
      fragment -> fragment
    end
  end

  defp dedupe_realized_revisit_objectives(objectives) do
    objectives
    |> Enum.reduce(%{}, fn objective, acc ->
      Map.update(acc, objective["target_id"], objective, fn existing ->
        source_activity_ids =
          [
            existing["source_activity_ids"] || existing["source_activity_id"],
            objective["source_activity_ids"] || objective["source_activity_id"]
          ]
          |> List.flatten()
          |> Enum.reject(&(&1 in [nil, ""]))
          |> Enum.uniq()
          |> Enum.sort()

        existing
        |> Map.update("priority", objective["priority"], &max(&1, objective["priority"]))
        |> Map.put("source_activity_id", List.first(source_activity_ids))
        |> Map.put("source_activity_ids", source_activity_ids)
      end)
    end)
    |> Map.values()
    |> Enum.sort_by(& &1["target_id"])
  end

  defp realized_observation_events(mission_state, prior_plan) do
    planned_by_id = planned_activities_grouped_by_id(prior_plan)

    mission_state
    |> Map.get("realized_activities", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(&(Map.get(&1, "status") in @realized_failure_statuses))
    |> Enum.map(fn realized ->
      planned = unique_planned_activity_for_realized(realized, planned_by_id, "observe") || %{}
      type = Map.get(realized, "type") || Map.get(realized, "activity_type") || planned["type"]

      if type == "observe" do
        realized
        |> Map.put_new("type", "observe")
        |> Map.put_new("target_id", planned["target_id"])
        |> Map.put_new("priority", Map.get(planned, "score"))
        |> Map.put_new("scenario_id", planned["scenario_id"])
        |> Map.put_new("starts_at_s", planned["starts_at_s"])
        |> Map.put_new("ends_at_s", planned["ends_at_s"])
      else
        nil
      end
    end)
    |> Enum.reject(&is_nil/1)
  end

  defp target_objective_needs_branch?(objective, planned_count, policy) do
    objective_type = objective["type"]
    priority = objective_number(objective, "priority", 0.0)

    cond do
      objective_type in ["urgent_target", "priority_commitment"] ->
        planned_count < required_target_observation_count(objective)

      objective_type in ["target_revisit", "target_observation"] ->
        planned_count < required_target_observation_count(objective)

      objective_type == "target_coverage" ->
        planned_count < required_target_observation_count(objective)

      is_number(priority) and priority >= policy["urgent_priority_threshold"] ->
        planned_count < required_target_observation_count(objective)

      truthy?(Map.get(objective, "urgent")) ->
        planned_count < required_target_observation_count(objective)

      true ->
        false
    end
  end

  defp required_target_observation_count(objective) do
    objective
    |> Map.take(["required_observations", "required_revisits", "required_count"])
    |> Map.values()
    |> Enum.find_value(&numeric_or_nil/1)
    |> case do
      nil -> 1
      count -> max(trunc(count), 1)
    end
  end

  defp objective_number(objective, field, default) do
    case numeric_or_nil(Map.get(objective, field)) do
      value when is_number(value) -> value
      _value -> default
    end
  end

  defp objective_number_from_fields(objective, fields) do
    Enum.find_value(fields, fn field ->
      case numeric_or_nil(Map.get(objective, field)) do
        value when is_number(value) -> value
        _value -> nil
      end
    end)
  end

  defp maybe_put_required_observations(event, objective) do
    required_count = required_target_observation_count(objective)

    if objective["type"] in ["target_revisit", "target_observation", "target_coverage"] or
         required_count > 1 do
      Map.put(event, "required_observations", required_count)
    else
      event
    end
  end

  defp target_coverage_objectives(mission_state) do
    target_catalog = mission_state_target_catalog(mission_state)

    mission_state
    |> Map.get("objectives", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(&coverage_objective?/1)
    |> Enum.flat_map(&target_coverage_objective_targets(&1, target_catalog))
  end

  defp coverage_objective?(%{"type" => type}), do: type in ["target_coverage", "coverage"]
  defp coverage_objective?(_objective), do: false

  defp target_coverage_objective_targets(objective, target_catalog) do
    inline_targets = coverage_target_specs(objective)

    target_ids =
      case coverage_target_ids(objective) do
        [] -> Map.keys(inline_targets) ++ Map.keys(target_catalog)
        ids -> ids
      end

    target_ids
    |> Enum.uniq()
    |> Enum.sort()
    |> Enum.map(fn target_id ->
      target = Map.get(inline_targets, target_id) || Map.get(target_catalog, target_id, %{})

      %{
        "type" => "target_coverage",
        "target_id" => target_id,
        "scenario_id" => Map.get(objective, "scenario_id"),
        "priority" => Map.get(objective, "priority") || Map.get(target, "priority"),
        "required_observations" => required_target_observation_count(objective),
        "coverage_objective_id" => Map.get(objective, "id"),
        "starts_at_s" => objective_window_start(objective, nil),
        "ends_at_s" => objective_window_end(objective, nil),
        "candidate_windows" => Map.get(objective, "candidate_windows"),
        "spacecraft_constraints" => Map.get(objective, "spacecraft_constraints"),
        "latitude_deg" => Map.get(target, "latitude_deg"),
        "longitude_deg" => Map.get(target, "longitude_deg"),
        "minimum_elevation_deg" => Map.get(target, "minimum_elevation_deg")
      }
      |> compact_map()
    end)
  end

  defp coverage_target_specs(objective) do
    [
      Map.get(objective, "targets"),
      Map.get(objective, "target_specs"),
      Map.get(objective, "required_targets"),
      Map.get(objective, "committed_targets"),
      Map.get(objective, "priority_targets")
    ]
    |> Enum.flat_map(fn
      targets when is_list(targets) -> targets
      _other -> []
    end)
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(&normalize_target_spec/1)
    |> Enum.filter(&target_spec?/1)
    |> unique_items_by_id()
    |> Map.new(&{Map.get(&1, "id"), &1})
  end

  defp coverage_target_ids(objective) do
    singular_ids =
      [Map.get(objective, "target_id")]
      |> Enum.map(&coverage_target_id/1)
      |> Enum.reject(&(&1 in [nil, ""]))

    list_ids =
      [
        Map.get(objective, "target_ids"),
        Map.get(objective, "required_target_ids"),
        Map.get(objective, "targets"),
        Map.get(objective, "target_specs"),
        Map.get(objective, "required_targets"),
        Map.get(objective, "committed_targets"),
        Map.get(objective, "priority_targets")
      ]
      |> Enum.flat_map(fn
        ids when is_list(ids) ->
          ids
          |> Enum.map(&coverage_target_id/1)
          |> Enum.reject(&(&1 in [nil, ""]))

        _other ->
          []
      end)

    (singular_ids ++ list_ids)
    |> Enum.uniq()
  end

  defp coverage_target_id(%{} = target) do
    target = stringify_keys(target)
    Map.get(target, "target_id") || Map.get(target, "id")
  end

  defp coverage_target_id(target_id), do: encode_value(target_id)

  defp mission_state_target_catalog(mission_state) do
    mission_state
    |> Map.get("targets", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(&normalize_target_spec/1)
    |> unique_items_by_id()
    |> Map.new(&{Map.get(&1, "id"), &1})
  end

  defp derived_target_branch_id(objective_type, target_id)
       when objective_type == "target_revisit",
       do: "derived_target_revisit_#{target_id}"

  defp derived_target_branch_id("target_observation", target_id),
    do: "derived_target_observation_#{target_id}"

  defp derived_target_branch_id("target_coverage", target_id),
    do: "derived_target_coverage_#{target_id}"

  defp derived_target_branch_id(_objective_type, target_id),
    do: "derived_urgent_target_#{target_id}"

  defp derived_target_branch_label(objective_type, target_id)
       when objective_type == "target_revisit",
       do: "Derived target revisit #{target_id}"

  defp derived_target_branch_label("target_observation", target_id),
    do: "Derived target observation #{target_id}"

  defp derived_target_branch_label("target_coverage", target_id),
    do: "Derived target coverage #{target_id}"

  defp derived_target_branch_label(_objective_type, target_id),
    do: "Derived urgent target #{target_id}"

  defp derived_collection_latency_branches(mission_state, prior_plan) do
    activities =
      prior_plan
      |> prior_plan_activities()
      |> Enum.map(&stringify_keys/1)

    mission_state
    |> Map.get("objectives", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(&collection_latency_objective?/1)
    |> Enum.flat_map(fn objective ->
      objective
      |> collection_latency_gaps(activities, mission_state, prior_plan)
      |> Enum.map(fn gap ->
        %{
          "id" => collection_latency_branch_id(gap),
          "label" => collection_latency_branch_label(gap),
          "events" => [gap],
          "metadata" => %{"derived_source" => "mission_state.objectives"}
        }
      end)
    end)
  end

  defp collection_latency_branch_id(%{"objective_id" => objective_id} = gap)
       when is_binary(objective_id) and objective_id != "" do
    "derived_collection_latency_#{objective_id}_#{gap["source_activity_id"]}"
  end

  defp collection_latency_branch_id(gap),
    do: "derived_collection_latency_#{gap["source_activity_id"]}"

  defp collection_latency_branch_label(%{"objective_id" => objective_id} = gap)
       when is_binary(objective_id) and objective_id != "" do
    "Derived collection latency #{objective_id} #{gap["source_activity_id"]}"
  end

  defp collection_latency_branch_label(gap),
    do: "Derived collection latency #{gap["source_activity_id"]}"

  defp collection_latency_objective?(%{"type" => type} = objective)
       when type in ["collection_latency", "max_collection_latency", "collection_latency_limit"] do
    is_number(collection_latency_limit_s(objective))
  end

  defp collection_latency_objective?(_objective), do: false

  defp collection_latency_gaps(objective, activities, mission_state, prior_plan) do
    max_latency_s = collection_latency_limit_s(objective)
    required_downlink_mb = objective_required_downlink_mb(objective)

    no_data_observation_ids =
      realized_observation_without_collected_data_ids(mission_state, prior_plan)

    realized_downlinks =
      mission_state
      |> realized_downlink_events(prior_plan)
      |> Enum.filter(&collection_latency_downlink_match?(&1, objective))

    downlinks =
      activities
      |> Enum.filter(&downlink_activity?/1)

    activities
    |> Enum.filter(&collection_latency_observation_match?(&1, objective))
    |> Enum.reject(&MapSet.member?(no_data_observation_ids, &1["id"]))
    |> Enum.map(fn observation ->
      feedback =
        collection_latency_downlink_feedback(
          objective,
          observation,
          max_latency_s,
          realized_downlinks
        )

      missed_ids = MapSet.new(feedback["source_activity_ids"])
      available_downlinks = Enum.reject(downlinks, &MapSet.member?(missed_ids, &1["id"]))
      latency = next_downlink_latency_s(observation, available_downlinks, objective)

      planned_latency_downlinks =
        collection_latency_planned_downlinks(
          observation,
          available_downlinks,
          objective,
          max_latency_s
        )

      planned_downlink_mb =
        planned_latency_downlinks
        |> Enum.map(&downlink_activity_mb/1)
        |> Enum.sum()

      if is_nil(latency) or latency > max_latency_s or
           collection_latency_downlink_volume_gap?(planned_downlink_mb, required_downlink_mb) do
        collection_latency_gap_event(
          objective,
          observation,
          max_latency_s,
          latency,
          feedback,
          planned_downlink_mb,
          length(planned_latency_downlinks),
          required_downlink_mb
        )
      end
    end)
    |> Enum.reject(&is_nil/1)
    |> Enum.sort_by(&{&1["ends_at_s"], &1["source_activity_id"]})
  end

  defp realized_observation_without_collected_data_ids(mission_state, prior_plan) do
    failure_ids =
      mission_state
      |> realized_observation_events(prior_plan)
      |> Enum.map(& &1["id"])

    no_data_ids =
      mission_state
      |> Map.get("realized_activities", [])
      |> Enum.map(&stringify_keys/1)
      |> enrich_realized_activities_with_planned_context(prior_plan)
      |> Enum.filter(&realized_observation_without_collected_data?/1)
      |> Enum.map(& &1["id"])

    (failure_ids ++ no_data_ids)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> MapSet.new()
  end

  defp realized_observation_without_collected_data?(activity) do
    type = Map.get(activity, "type") || Map.get(activity, "activity_type")
    demand_mb = observation_downlink_demand_mb(activity)

    type == "observe" and observation_success_value(activity) == 0.0 and
      (is_nil(demand_mb) or demand_mb <= 0.0)
  end

  defp collection_latency_observation_match?(activity, objective) do
    target_id = Map.get(objective, "target_id") || Map.get(objective, "id")
    scenario_id = Map.get(objective, "scenario_id")

    activity["type"] == "observe" and
      (is_nil(target_id) or activity["target_id"] == target_id) and
      (is_nil(scenario_id) or activity["scenario_id"] == scenario_id) and
      collection_latency_identity_match?(activity, objective)
  end

  defp collection_latency_identity_match?(activity, objective) do
    Enum.all?(
      [
        {collection_identity_keys(), collection_identity_keys()},
        {payload_identity_keys(), payload_identity_keys()},
        {instrument_identity_keys(), instrument_identity_keys()},
        {product_identity_keys(), product_identity_keys()}
      ],
      fn {objective_keys, activity_keys} ->
        objective_values = identity_selector_values(objective, objective_keys)

        objective_values == [] or
          Enum.any?(identity_selector_values(activity, activity_keys), &(&1 in objective_values))
      end
    )
  end

  defp identity_selector_values(row, keys) when is_map(row) do
    keys
    |> Enum.flat_map(fn key ->
      identity_selector_value(key, Map.get(row, key))
    end)
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp identity_selector_values(_row, _keys), do: []

  defp identity_selector_value(_key, nil), do: []

  defp identity_selector_value(key, values) when is_list(values) do
    Enum.flat_map(values, &identity_selector_value(key, &1))
  end

  defp identity_selector_value(key, %{} = value) do
    keys =
      key
      |> encode_value()
      |> identity_selector_nested_keys()

    values =
      keys
      |> Enum.flat_map(fn nested_key ->
        identity_selector_value(nested_key, Map.get(value, nested_key))
      end)

    if values == [], do: identity_selector_value("id", Map.get(value, "id")), else: values
  end

  defp identity_selector_value(_key, value), do: [value]

  defp identity_selector_nested_keys(key)
       when key in ["collection", "collections", "collection_id", "collection_ids"],
       do: ["collection_id", "id"]

  defp identity_selector_nested_keys(key)
       when key in [
              "product",
              "products",
              "data_product",
              "data_products",
              "product_id",
              "product_ids",
              "data_product_id",
              "data_product_ids"
            ],
       do: ["product_id", "data_product_id", "id"]

  defp identity_selector_nested_keys(key)
       when key in ["payload", "payloads", "payload_id", "payload_ids"],
       do: ["payload_id", "id"]

  defp identity_selector_nested_keys(key)
       when key in ["instrument", "instruments", "instrument_id", "instrument_ids"],
       do: ["instrument_id", "id"]

  defp identity_selector_nested_keys(_key), do: ["id"]

  defp collection_latency_downlink_feedback(
         objective,
         observation,
         max_latency_s,
         realized_downlinks
       ) do
    event = collection_latency_downlink_event(objective, observation)

    realized =
      realized_downlinks
      |> Enum.filter(&downlink_completion_event_match?(&1, event))
      |> Enum.filter(
        &collection_latency_downlink_satisfies_observation?(&1, observation, max_latency_s)
      )

    %{
      "source_activity_ids" =>
        realized
        |> Enum.map(& &1["id"])
        |> Enum.reject(&(&1 in [nil, ""]))
        |> Enum.uniq()
        |> Enum.sort(),
      "statuses" =>
        realized
        |> Enum.map(& &1["status"])
        |> Enum.reject(&(&1 in [nil, ""]))
        |> Enum.uniq()
        |> Enum.sort(),
      "contact_results" =>
        realized
        |> Enum.flat_map(&provider_result_values(&1["contact_result"]))
        |> Enum.uniq()
        |> Enum.sort()
    }
  end

  defp collection_latency_downlink_match?(downlink, objective) do
    station_id = objective_ground_station_id(objective)
    scenario_id = Map.get(objective, "scenario_id")

    downlink_activity?(downlink) and
      (is_nil(station_id) or activity_ground_station_id(downlink) == station_id) and
      (is_nil(scenario_id) or downlink["scenario_id"] == scenario_id)
  end

  defp collection_latency_downlink_satisfies_observation?(downlink, observation, max_latency_s) do
    latency_s = activity_start(downlink) - activity_end(observation)
    latency_s >= 0.0 and latency_s <= max_latency_s
  end

  defp next_downlink_latency_s(observation, downlinks, objective) do
    event = collection_latency_downlink_event(objective, observation)

    downlinks
    |> Enum.filter(&downlink_completion_event_match?(&1, event))
    |> Enum.map(&(activity_start(&1) - activity_end(observation)))
    |> Enum.reject(&(&1 < 0.0))
    |> Enum.min(fn -> nil end)
  end

  defp collection_latency_planned_downlinks(
         observation,
         downlinks,
         objective,
         max_latency_s
       ) do
    event = collection_latency_downlink_event(objective, observation, max_latency_s)

    downlinks
    |> Enum.filter(&downlink_completion_event_match?(&1, event))
  end

  defp collection_latency_downlink_event(objective, observation) do
    collection_latency_downlink_event(objective, observation, nil)
  end

  defp collection_latency_downlink_event(objective, observation, max_latency_s) do
    compact_map(%{
      "scenario_id" => Map.get(objective, "scenario_id") || observation["scenario_id"],
      "ground_station_id" => objective_ground_station_id(objective),
      "starts_at_s" => activity_end(observation),
      "ends_at_s" => if(is_number(max_latency_s), do: activity_end(observation) + max_latency_s),
      "collection_id" =>
        collection_latency_identity_value(objective, observation, "collection_id"),
      "product_id" => collection_latency_identity_value(objective, observation, "product_id"),
      "product_ids" => collection_latency_product_ids(objective, observation),
      "payload_id" => collection_latency_identity_value(objective, observation, "payload_id"),
      "instrument_id" =>
        collection_latency_identity_value(objective, observation, "instrument_id")
    })
  end

  defp collection_latency_downlink_volume_gap?(planned_downlink_mb, required_downlink_mb)
       when is_number(required_downlink_mb) and required_downlink_mb > 0.0 do
    planned_downlink_mb < required_downlink_mb
  end

  defp collection_latency_downlink_volume_gap?(_planned_downlink_mb, _required_downlink_mb),
    do: false

  defp collection_latency_gap_event(
         objective,
         observation,
         max_latency_s,
         planned_latency_s,
         feedback,
         planned_downlink_mb,
         planned_contacts,
         required_downlink_mb
       ) do
    compact_map(%{
      "type" => "downlink_completion_gap",
      "objective_type" => objective["type"],
      "objective_id" => objective["id"],
      "latency_objective" => true,
      "target_id" => observation["target_id"],
      "scenario_id" => Map.get(objective, "scenario_id") || observation["scenario_id"],
      "ground_station_id" => objective_ground_station_id(objective),
      "collection_id" =>
        collection_latency_identity_value(objective, observation, "collection_id"),
      "product_id" => collection_latency_identity_value(objective, observation, "product_id"),
      "product_ids" => collection_latency_product_ids(objective, observation),
      "payload_id" => collection_latency_identity_value(objective, observation, "payload_id"),
      "instrument_id" =>
        collection_latency_identity_value(objective, observation, "instrument_id"),
      "starts_at_s" => activity_end(observation),
      "ends_at_s" => activity_end(observation) + max_latency_s,
      "required_contacts" => 1,
      "planned_contacts" => planned_contacts,
      "required_downlink_mb" => required_downlink_mb,
      "planned_downlink_mb" => planned_downlink_mb,
      "max_latency_s" => max_latency_s,
      "planned_latency_s" => planned_latency_s,
      "source_activity_id" => observation["id"],
      "source_activity_ids" => [observation["id"]],
      "realized_status" => join_or_nil(feedback["statuses"]),
      "contact_result" => join_or_nil(feedback["contact_results"]),
      "missed_downlink_activity_id" => List.first(feedback["source_activity_ids"]),
      "missed_downlink_activity_ids" => feedback["source_activity_ids"],
      "derivation_reasons" =>
        ["collection_latency_gap"] ++
          Enum.map(feedback["statuses"], &"realized_downlink_#{&1}") ++
          Enum.map(feedback["contact_results"], &"realized_downlink_contact_result_#{&1}")
    })
  end

  defp collection_latency_identity_value(objective, observation, field) do
    aliases = identity_keys_for_field(field)

    objective_values = identity_selector_values(objective, aliases)
    observation_values = identity_selector_values(observation, aliases)

    cond do
      objective_values != [] and observation_values != [] ->
        Enum.find(observation_values, &(&1 in objective_values)) || List.first(objective_values)

      objective_values != [] ->
        List.first(objective_values)

      true ->
        List.first(observation_values)
    end
  end

  defp objective_only_identity_value(objective, field) do
    objective
    |> identity_selector_values(identity_keys_for_field(field))
    |> case do
      [value] -> value
      _values -> nil
    end
  end

  defp objective_only_identity_values(objective, field) do
    objective
    |> identity_selector_values(identity_keys_for_field(field))
    |> case do
      [] -> nil
      values -> values
    end
  end

  defp collection_latency_product_ids(objective, observation) do
    values =
      [objective, observation]
      |> Enum.flat_map(&identity_selector_values(&1, product_identity_keys()))
      |> Enum.uniq()
      |> Enum.sort()

    if values == [], do: nil, else: values
  end

  defp identity_keys_for_field("collection_id"), do: collection_identity_keys()
  defp identity_keys_for_field("product_id"), do: product_identity_keys()
  defp identity_keys_for_field("payload_id"), do: payload_identity_keys()
  defp identity_keys_for_field("instrument_id"), do: instrument_identity_keys()

  defp collection_identity_keys,
    do: ["collection_id", "collection_ids", "collection", "collections"]

  defp product_identity_keys,
    do: [
      "product_id",
      "data_product_id",
      "product_ids",
      "data_product_ids",
      "product",
      "data_product",
      "products",
      "data_products"
    ]

  defp payload_identity_keys, do: ["payload_id", "payload_ids", "payload", "payloads"]

  defp instrument_identity_keys,
    do: ["instrument_id", "instrument_ids", "instrument", "instruments"]

  defp collection_latency_limit_s(objective) do
    objective
    |> objective_number_from_fields([
      "max_latency_s",
      "required_latency_s",
      "target_latency_s",
      "latency_limit_s",
      "max_delivery_latency_s",
      "required_delivery_latency_s",
      "target_delivery_latency_s"
    ])
  end

  defp derived_downlink_constrained_branches(mission_state, prior_plan, policy) do
    objectives = downlink_completion_objectives(mission_state)
    multiple_objectives? = length(objectives) > 1

    branch_objectives =
      case objectives do
        [] -> [nil]
        objectives -> objectives
      end

    branch_objectives
    |> Enum.with_index(1)
    |> Enum.map(fn {objective, index} ->
      derived_downlink_constrained_branch(
        mission_state,
        prior_plan,
        policy,
        objective,
        multiple_objectives?,
        index
      )
    end)
    |> Enum.reject(&is_nil/1)
    |> disambiguate_downlink_constrained_branch_ids()
  end

  defp derived_downlink_constrained_branch(
         mission_state,
         prior_plan,
         policy,
         objective,
         multiple_objectives?,
         index
       ) do
    required_contacts = required_downlink_contacts(objective, prior_plan)
    planned_contacts = effective_planned_downlink_count(prior_plan, mission_state, objective)
    realized_downlink_gap = realized_downlink_gap(mission_state, prior_plan, objective)

    downlink_sources = mission_state_resource_margin_sources(mission_state, "downlink_margin")
    storage_sources = mission_state_resource_margin_sources(mission_state, "storage_margin")
    downlink_source = List.first(downlink_sources)
    storage_source = List.first(storage_sources)

    downlink_margin = downlink_source && downlink_source["downlink_margin"]
    storage_margin = storage_source && storage_source["storage_margin"]
    required_downlink_mb = objective_required_downlink_mb(objective || %{})
    planned_downlink_mb = effective_planned_downlink_mb(prior_plan, mission_state, objective)

    completion_gap? =
      planned_contacts < required_contacts or
        (is_number(required_downlink_mb) and planned_downlink_mb < required_downlink_mb)

    capacity_constrained? =
      is_number(downlink_margin) and downlink_margin <= policy["downlink_margin_threshold"]

    storage_constrained? =
      is_number(storage_margin) and storage_margin <= policy["storage_margin_threshold"]

    event_required_contacts =
      if storage_constrained? do
        max(required_contacts, planned_contacts + 1)
      else
        required_contacts
      end

    base_events =
      []
      |> maybe_append_branch_event(
        completion_gap? or storage_constrained?,
        %{
          "type" => "downlink_completion_gap",
          "objective_id" => objective && objective["id"],
          "objective_type" => objective && objective["type"],
          "required_contacts" => event_required_contacts,
          "planned_contacts" => planned_contacts,
          "required_downlink_mb" => required_downlink_mb,
          "planned_downlink_mb" => planned_downlink_mb,
          "scenario_id" => objective && objective["scenario_id"],
          "ground_station_id" => objective && objective_ground_station_id(objective),
          "collection_id" => objective_only_identity_value(objective, "collection_id"),
          "collection_ids" => objective_only_identity_values(objective, "collection_id"),
          "product_id" => objective_only_identity_value(objective, "product_id"),
          "product_ids" => collection_latency_product_ids(objective || %{}, %{}),
          "payload_id" => objective_only_identity_value(objective, "payload_id"),
          "payload_ids" => objective_only_identity_values(objective, "payload_id"),
          "instrument_id" => objective_only_identity_value(objective, "instrument_id"),
          "instrument_ids" => objective_only_identity_values(objective, "instrument_id"),
          "starts_at_s" => objective_window_start(objective, 0.0),
          "ends_at_s" =>
            objective_window_end(
              objective,
              planning_horizon_duration_s(prior_plan, 0.0)
            ),
          "derivation_reasons" =>
            downlink_constraint_derivation_reasons(
              completion_gap?,
              storage_constrained?,
              capacity_constrained?,
              realized_downlink_gap["statuses"],
              realized_downlink_gap["contact_results"]
            ),
          "storage_margin" => storage_margin,
          "storage_margin_threshold" => policy["storage_margin_threshold"],
          "source_activity_id" => realized_downlink_gap["source_activity_id"],
          "source_activity_ids" => realized_downlink_gap["source_activity_ids"],
          "realized_status" => realized_downlink_gap["realized_status"],
          "contact_result" => realized_downlink_gap["contact_result"]
        }
        |> compact_map()
      )
      |> maybe_append_branch_event(capacity_constrained?, %{
        "type" => "reduced_downlink_capacity",
        "capacity_fraction" => min(downlink_margin || 0.5, 1.0),
        "starts_at_s" => 0.0,
        "ends_at_s" => planning_horizon_duration_s(prior_plan, 0.0)
      })
      |> Enum.reverse()

    events =
      base_events ++
        resource_margin_pressure_events(
          mission_state,
          downlink_sources,
          policy,
          "downlink_margin",
          "downlink_margin_threshold",
          "downlink_margin_low"
        ) ++
        resource_margin_pressure_events(
          mission_state,
          storage_sources,
          policy,
          "storage_margin",
          "storage_margin_threshold",
          "storage_margin_low"
        )

    if events != [] do
      %{
        "id" => downlink_constrained_branch_id(objective, multiple_objectives?, index),
        "label" => downlink_constrained_branch_label(objective, multiple_objectives?, index),
        "events" => events,
        "metadata" => %{
          "derived_source" => mission_state_resource_source_path(mission_state, "downlink_margin")
        }
      }
    else
      nil
    end
  end

  defp objective_satisfaction_max_latency_s(row) do
    numeric_or_nil(
      row["max_latency_s"] || row["required_latency_s"] || row["target_latency_s"] ||
        row["latency_limit_s"] || row["max_delivery_latency_s"] ||
        row["required_delivery_latency_s"] ||
        objective_pressure_observation_context_number(row, [
          "max_latency_s",
          "required_latency_s",
          "target_latency_s",
          "latency_limit_s",
          "max_delivery_latency_s",
          "required_delivery_latency_s"
        ])
    )
  end

  defp objective_satisfaction_planned_latency_s(row) do
    numeric_or_nil(
      row["planned_latency_s"] || row["actual_latency_s"] || row["delivery_latency_s"] ||
        row["planned_delivery_latency_s"] || row["actual_delivery_latency_s"] ||
        objective_pressure_observation_context_number(row, [
          "planned_latency_s",
          "actual_latency_s",
          "delivery_latency_s",
          "planned_delivery_latency_s",
          "actual_delivery_latency_s"
        ])
    )
  end

  defp downlink_constrained_branch_id(_objective, false, _index),
    do: "derived_downlink_constrained"

  defp downlink_constrained_branch_id(%{"id" => objective_id}, true, _index)
       when is_binary(objective_id) and objective_id != "" do
    "derived_downlink_constrained_#{objective_id}"
  end

  defp downlink_constrained_branch_id(%{} = objective, true, index) do
    [
      Map.get(objective, "scenario_id"),
      objective_ground_station_id(objective),
      index
    ]
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.map(&encode_value/1)
    |> Enum.join("_")
    |> case do
      "" -> "derived_downlink_constrained_#{index}"
      suffix -> "derived_downlink_constrained_#{suffix}"
    end
  end

  defp downlink_constrained_branch_id(_objective, true, index),
    do: "derived_downlink_constrained_#{index}"

  defp disambiguate_downlink_constrained_branch_ids(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      branch_id = branch["id"]

      if Map.get(id_counts, branch_id, 0) > 1 do
        suffix =
          branch
          |> downlink_constrained_branch_identity(index)
          |> branch_id_fragment()

        branch
        |> Map.put("id", "#{branch_id}_#{suffix}")
        |> Map.update("metadata", %{}, fn metadata ->
          metadata
          |> Map.put("downlink_constrained_branch_base_id", branch_id)
          |> Map.put("downlink_constrained_branch_identity", suffix)
        end)
      else
        branch
      end
    end)
    |> disambiguate_duplicate_downlink_constrained_suffixes()
  end

  defp disambiguate_duplicate_downlink_constrained_suffixes(branches) do
    id_counts = Enum.frequencies_by(branches, & &1["id"])

    branches
    |> Enum.with_index(1)
    |> Enum.map(fn {branch, index} ->
      metadata = Map.get(branch, "metadata", %{})

      if Map.has_key?(metadata, "downlink_constrained_branch_base_id") and
           Map.get(id_counts, branch["id"], 0) > 1 do
        suffix = "#{metadata["downlink_constrained_branch_identity"]}_#{index}"

        branch
        |> Map.put("id", "#{metadata["downlink_constrained_branch_base_id"]}_#{suffix}")
        |> Map.update(
          "metadata",
          %{},
          &Map.put(&1, "downlink_constrained_branch_identity", suffix)
        )
      else
        branch
      end
    end)
  end

  defp downlink_constrained_branch_identity(branch, index) do
    events =
      branch
      |> Map.get("events", [])
      |> List.wrap()

    event =
      Enum.find(events, &(&1["type"] == "downlink_completion_gap")) ||
        List.first(events) || %{}

    [
      event["ground_station_id"],
      event["scenario_id"],
      event["collection_id"],
      event["collection_ids"],
      event["product_id"],
      event["product_ids"],
      event["payload_id"],
      event["payload_ids"],
      event["instrument_id"],
      event["instrument_ids"],
      event["starts_at_s"],
      event["ends_at_s"],
      event["source_activity_id"],
      event["source_activity_ids"],
      index
    ]
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> index
      identifiers -> Enum.join(identifiers, "_")
    end
  end

  defp downlink_constrained_branch_label(_objective, false, _index),
    do: "Derived downlink constrained"

  defp downlink_constrained_branch_label(%{"id" => objective_id}, true, _index)
       when is_binary(objective_id) and objective_id != "" do
    "Derived downlink constrained #{objective_id}"
  end

  defp downlink_constrained_branch_label(_objective, true, index),
    do: "Derived downlink constrained #{index}"

  defp objective_window_start(nil, default), do: default

  defp objective_window_start(%{"starts_at_s" => starts_at_s}, default),
    do: numeric_or_nil(starts_at_s) || default

  defp objective_window_start(%{"start_s" => start_s}, default),
    do: numeric_or_nil(start_s) || default

  defp objective_window_start(_objective, default), do: default

  defp objective_window_end(nil, default), do: default

  defp objective_window_end(%{"ends_at_s" => ends_at_s}, default),
    do: numeric_or_nil(ends_at_s) || default

  defp objective_window_end(%{"end_s" => end_s}, default),
    do: numeric_or_nil(end_s) || default

  defp objective_window_end(_objective, default), do: default

  defp maybe_append_branch_event(events, true, event), do: [event | events]
  defp maybe_append_branch_event(events, false, _event), do: events

  defp downlink_constraint_derivation_reasons(
         completion_gap?,
         storage_constrained?,
         capacity_constrained?,
         statuses,
         contact_results
       ) do
    []
    |> maybe_append_reason(completion_gap?, "downlink_completion_gap")
    |> maybe_append_reason(storage_constrained?, "storage_margin_low")
    |> maybe_append_reason(capacity_constrained?, "downlink_margin_low")
    |> Enum.reverse()
    |> Kernel.++(Enum.map(statuses, &"realized_downlink_#{&1}"))
    |> Kernel.++(Enum.map(contact_results, &"realized_downlink_contact_result_#{&1}"))
  end

  defp effective_planned_downlink_count(prior_plan, mission_state, objective) do
    missed_count =
      mission_state
      |> realized_downlink_events(prior_plan)
      |> Enum.filter(&downlink_completion_event_match?(&1, objective || %{}))
      |> Enum.map(& &1["id"])
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.uniq()
      |> length()

    prior_plan
    |> planned_downlink_count(objective)
    |> Kernel.-(missed_count)
    |> max(0)
  end

  defp effective_planned_downlink_mb(prior_plan, mission_state, objective) do
    missed_ids =
      mission_state
      |> realized_downlink_events(prior_plan)
      |> Enum.filter(&downlink_completion_event_match?(&1, objective || %{}))
      |> Enum.map(& &1["id"])
      |> Enum.reject(&(&1 in [nil, ""]))
      |> MapSet.new()

    prior_plan
    |> prior_plan_activities()
    |> Enum.map(&stringify_keys/1)
    |> Enum.reject(&MapSet.member?(missed_ids, &1["id"]))
    |> planned_downlink_mb(objective)
  end

  defp realized_downlink_gap(mission_state, prior_plan, objective) do
    realized =
      mission_state
      |> realized_downlink_events(prior_plan)
      |> Enum.filter(&downlink_completion_event_match?(&1, objective || %{}))

    source_activity_ids =
      realized
      |> Enum.map(& &1["id"])
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.uniq()
      |> Enum.sort()

    statuses =
      realized
      |> Enum.map(& &1["status"])
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.uniq()
      |> Enum.sort()

    contact_results =
      realized
      |> Enum.flat_map(&provider_result_values(&1["contact_result"]))
      |> Enum.uniq()
      |> Enum.sort()

    %{
      "source_activity_id" => List.first(source_activity_ids),
      "source_activity_ids" => source_activity_ids,
      "realized_status" => join_or_nil(statuses),
      "statuses" => statuses,
      "contact_result" => join_or_nil(contact_results),
      "contact_results" => contact_results
    }
  end

  defp join_or_nil([]), do: nil
  defp join_or_nil(values), do: Enum.join(values, ",")

  defp realized_downlink_events(mission_state, prior_plan) do
    planned_by_id = planned_activities_grouped_by_id(prior_plan)

    mission_state
    |> Map.get("realized_activities", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(fn realized ->
      planned = unique_planned_downlink_activity_for_realized(realized, planned_by_id) || %{}

      realized =
        planned
        |> Map.merge(realized)
        |> normalize_realized_downlink_event_status()

      if downlink_activity?(realized) and realized_downlink_gap_feedback?(realized) do
        realized
      end
    end)
    |> Enum.reject(&is_nil/1)
  end

  defp normalize_realized_downlink_event_status(%{} = realized) do
    status =
      realized
      |> Map.get("status")
      |> encode_value()
      |> normalize_realized_status_value()

    raw_realized_status =
      realized
      |> Map.get("realized_status")
      |> encode_value()
      |> normalize_realized_status_value()

    {status, feedback_status, realized_status} =
      normalize_realized_activity_status(status, raw_realized_status)

    realized
    |> put_if_present("status", status)
    |> put_if_present("feedback_status", feedback_status)
    |> put_if_present("realized_status", realized_status)
  end

  defp realized_downlink_gap_feedback?(%{"contact_result" => result} = realized) do
    case provider_result_success_value(result) do
      :failure -> true
      :success -> false
      :unknown -> realized |> Map.delete("contact_result") |> realized_downlink_gap_feedback?()
    end
  end

  defp realized_downlink_gap_feedback?(%{"realized_status" => status})
       when status in @realized_failure_statuses,
       do: true

  defp realized_downlink_gap_feedback?(%{"realized_status" => status})
       when status in @realized_completion_statuses,
       do: false

  defp realized_downlink_gap_feedback?(%{"status" => status})
       when status in @realized_failure_statuses,
       do: true

  defp realized_downlink_gap_feedback?(_realized), do: false

  defp unique_planned_downlink_activity_for_realized(realized, planned_by_id) do
    realized_type = Map.get(realized, "type") || Map.get(realized, "activity_type")
    matches = Map.get(planned_by_id, realized["id"], [])
    downlink_matches = Enum.filter(matches, &downlink_activity?/1)

    cond do
      realized_type in ["downlink", "planned_contact", "contact"] ->
        single_planned_activity(downlink_matches)

      is_nil(realized_type) ->
        case matches do
          [planned] -> if downlink_activity?(planned), do: planned
          _matches -> nil
        end

      true ->
        nil
    end
  end

  defp planned_activities_grouped_by_id(prior_plan) do
    prior_plan
    |> Map.get("activities", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.group_by(& &1["id"])
  end

  defp unique_planned_activity_for_realized(realized, planned_by_id, type) do
    realized_type = Map.get(realized, "type") || Map.get(realized, "activity_type")
    matches = Map.get(planned_by_id, realized["id"], [])

    typed_matches = Enum.filter(matches, &(&1["type"] == type))

    cond do
      realized_type == type ->
        single_planned_activity(typed_matches)

      is_nil(realized_type) ->
        case matches do
          [%{"type" => ^type} = planned] -> planned
          _matches -> nil
        end

      true ->
        nil
    end
  end

  defp single_planned_activity([planned]), do: planned
  defp single_planned_activity(_matches), do: nil

  defp maybe_append_reason(reasons, true, reason), do: [reason | reasons]
  defp maybe_append_reason(reasons, false, _reason), do: reasons

  defp derived_combined_branch(individual_derived, %{"combine_derived_branches" => true}) do
    combined_events =
      individual_derived
      |> Enum.flat_map(&combined_branch_events/1)
      |> normalize_branch_events()

    combined_branch_ids =
      individual_derived
      |> Enum.map(& &1["id"])
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.sort()

    if length(combined_branch_ids) >= 2 and combined_events != [] do
      [
        %{
          "id" => "derived_combined_mission_state",
          "label" => "Derived combined mission-state future",
          "events" => combined_events,
          "metadata" => %{
            "derived_source" => "branch_generation.combined_derived",
            "combined_branch_ids" => combined_branch_ids
          }
        }
      ]
    else
      []
    end
  end

  defp derived_combined_branch(_individual_derived, _policy), do: []

  defp combined_branch_events(%{"id" => branch_id} = branch) do
    branch
    |> Map.get("events", [])
    |> Enum.map(fn event ->
      event
      |> Map.put_new("source_branch_id", branch_id)
      |> Map.update("source_branch_ids", [branch_id], fn
        branch_ids when is_list(branch_ids) -> Enum.uniq(branch_ids ++ [branch_id])
        _value -> [branch_id]
      end)
    end)
  end

  defp combined_branch_events(_branch), do: []

  defp normalize_strategy_branches(nil), do: []

  defp normalize_strategy_branches(branches) when is_list(branches) do
    branches
    |> Enum.map(&normalize_strategy_branch/1)
    |> Enum.sort_by(& &1["id"])
  end

  defp normalize_strategy_branch(%WhatIfScenario{} = branch) do
    branch
    |> Map.from_struct()
    |> normalize_strategy_branch()
  end

  defp normalize_strategy_branch(branch) do
    branch = stringify_keys(branch || %{})
    branch_id = encode_value(Map.fetch!(branch, "id"))

    %{
      "id" => branch_id,
      "label" => Map.get(branch, "label") || branch_id,
      "probability" =>
        normalize_branch_probability(Map.get(branch, "probability", 1.0), branch_id),
      "events" => normalize_branch_events(Map.get(branch, "events", [])),
      "policy_overrides" => Map.get(branch, "policy_overrides", %{}),
      "realized_state_overrides" => Map.get(branch, "realized_state_overrides", %{}),
      "candidate_refresh" =>
        normalize_candidate_refresh(
          Map.get(branch, "candidate_refresh") || Map.get(branch, "refreshed_candidates")
        ),
      "candidate_refresh_request" =>
        normalize_candidate_refresh_request(
          Map.get(branch, "candidate_refresh_request") || Map.get(branch, "refresh_request")
        ),
      "metadata" => Map.get(branch, "metadata", %{})
    }
  end

  defp normalize_branch_probability(value, branch_id) do
    probability = numeric!(value, "branch #{branch_id} probability") * 1.0

    if probability >= 0.0 and probability <= 1.0 do
      probability
    else
      raise ArgumentError, "branch #{branch_id} probability must be between 0.0 and 1.0"
    end
  end

  defp normalize_branch_events(events) do
    events
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(&normalize_branch_event_aliases/1)
    |> Enum.map(&normalize_branch_event_lineage/1)
    |> Enum.map(&normalize_branch_event_trust_boundary/1)
    |> Enum.map(&normalize_branch_event_station_identity/1)
    |> Enum.map(&normalize_branch_event_scalar_identities/1)
    |> Enum.map(&normalize_branch_event_string_fields/1)
    |> Enum.map(&normalize_branch_event_identity_lists/1)
    |> Enum.map(&normalize_branch_event_time_fields/1)
    |> Enum.map(&normalize_branch_event_unit_interval_numbers/1)
    |> Enum.map(&normalize_branch_event_boolean_fields/1)
    |> Enum.map(&normalize_branch_event_feedback_factor/1)
    |> Enum.map(&normalize_branch_event_nonnegative_numbers/1)
    |> Enum.sort_by(
      &{Map.get(&1, "starts_at_s", 0.0), Map.get(&1, "type", ""), Map.get(&1, "id", "")}
    )
  end

  defp normalize_branch_event_aliases(%{"type" => "resource_margin_pressure"} = event) do
    event = normalize_resource_margin_aliases(event)

    field =
      canonical_resource_margin_field(event["resource_field"]) ||
        resource_margin_event_field(event)

    if field do
      event
      |> Map.put("resource_field", field)
      |> normalize_resource_margin_threshold_alias(field)
    else
      event
    end
  end

  defp normalize_branch_event_aliases(%{"type" => "resource_availability_constraint"} = event) do
    event = normalize_resource_availability_aliases(event)

    field =
      canonical_resource_availability_field(event["resource_field"]) ||
        resource_availability_event_field(event)

    if field do
      event
      |> Map.put("resource_field", field)
      |> normalize_resource_availability_event_value(field)
    else
      event
    end
  end

  defp normalize_branch_event_aliases(%{"type" => "degraded_spacecraft"} = event) do
    event = normalize_resource_availability_aliases(event)

    event
    |> Map.put("mode", degraded_event_mode(event))
    |> Map.put(
      "incompatible_activity_types",
      normalize_incompatible_activity_types(degradation_activity_types(event))
    )
    |> Map.delete("suppressed_activity_types")
  end

  defp normalize_branch_event_aliases(%{"type" => "observation_success_feedback"} = event) do
    event
    |> normalize_observation_quality_event_fields()
    |> put_observation_success_factor_from_quality()
  end

  defp normalize_branch_event_aliases(event), do: event

  defp normalize_observation_quality_event_fields(event) do
    image_quality_score =
      first_numeric_field(event, [
        "image_quality_score",
        "product_quality_score",
        "quality_score"
      ])

    image_quality_status =
      first_encoded_field(event, [
        "image_quality_status",
        "product_quality_status",
        "quality_status"
      ])

    image_quality_source =
      first_encoded_field(event, [
        "image_quality_source",
        "product_quality_source",
        "quality_source"
      ])

    cloud_cover_fraction =
      first_numeric_field(event, [
        "cloud_cover_fraction",
        "cloud_fraction",
        "cloud_cover"
      ])

    blur_score =
      first_numeric_field(event, [
        "blur_score",
        "image_blur_score",
        "sharpness_loss_fraction"
      ])

    event
    |> drop_fields([
      "product_quality_score",
      "quality_score",
      "product_quality_status",
      "quality_status",
      "product_quality_source",
      "quality_source",
      "cloud_fraction",
      "cloud_cover",
      "image_blur_score",
      "sharpness_loss_fraction"
    ])
    |> put_optional_number("image_quality_score", image_quality_score)
    |> put_optional_string("image_quality_status", image_quality_status)
    |> put_optional_string("image_quality_source", image_quality_source)
    |> put_optional_number("cloud_cover_fraction", cloud_cover_fraction)
    |> put_optional_number("blur_score", blur_score)
  end

  defp put_observation_success_factor_from_quality(event) do
    cond do
      is_number(numeric_or_nil(event["observation_success_factor"])) ->
        event

      is_number(event["image_quality_score"]) ->
        event
        |> Map.put("observation_success_factor", event["image_quality_score"])
        |> Map.put_new("feedback_source", "branch_event.image_quality_score")

      true ->
        event
    end
  end

  defp first_numeric_field(map, fields) do
    fields
    |> Enum.map(&numeric_or_nil(Map.get(map, &1)))
    |> Enum.find(&is_number/1)
  end

  defp first_encoded_field(map, fields) do
    fields
    |> Enum.map(&(map |> Map.get(&1) |> encode_value()))
    |> Enum.find(&(is_binary(&1) and &1 != ""))
  end

  defp drop_fields(map, fields), do: Enum.reduce(fields, map, &Map.delete(&2, &1))

  defp put_optional_number(map, _field, value) when not is_number(value), do: map
  defp put_optional_number(map, field, value), do: Map.put(map, field, value)

  defp put_optional_string(map, _field, value) when value in [nil, ""], do: map
  defp put_optional_string(map, field, value), do: Map.put(map, field, value)

  defp normalize_branch_event_lineage(event) do
    source_branch_id =
      case encode_value(Map.get(event, "source_branch_id")) do
        value when value in [nil, ""] -> nil
        value -> value
      end

    source_branch_ids =
      event
      |> Map.get("source_branch_ids", [])
      |> List.wrap()
      |> Kernel.++(List.wrap(source_branch_id))
      |> Enum.map(&encode_value/1)
      |> Enum.filter(&(is_binary(&1) and &1 != ""))
      |> Enum.uniq()
      |> Enum.sort()

    event =
      if is_nil(source_branch_id) do
        Map.delete(event, "source_branch_id")
      else
        Map.put(event, "source_branch_id", source_branch_id)
      end

    case source_branch_ids do
      [] -> Map.delete(event, "source_branch_ids")
      ids -> Map.put(event, "source_branch_ids", ids)
    end
  end

  defp normalize_branch_event_trust_boundary(event) do
    trust_boundary =
      event
      |> branch_event_trust_boundary()
      |> encode_value()

    case trust_boundary do
      value when is_binary(value) and value != "" -> Map.put(event, "trust_boundary", value)
      _value -> Map.delete(event, "trust_boundary")
    end
  end

  defp normalize_branch_event_station_identity(event) do
    case event_ground_station_id(event) do
      nil ->
        event
        |> Map.delete("ground_station_id")
        |> Map.delete("station_id")

      station_id ->
        event
        |> Map.put("ground_station_id", station_id)
        |> Map.delete("station_id")
    end
  end

