    |> Enum.reduce(event, fn field, acc ->
      case normalize_branch_event_identity_list(Map.get(acc, field)) do
        [] -> Map.delete(acc, field)
        values -> Map.put(acc, field, values)
      end
    end)
  end

  defp normalize_branch_event_identity_list(values) do
    values
    |> List.wrap()
    |> Enum.map(&encode_value/1)
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
  end

  defp normalize_branch_event_time_fields(event) do
    event
    |> normalize_branch_event_time_field("starts_at_s", "start_s")
    |> normalize_branch_event_time_field("ends_at_s", "end_s")
    |> normalize_branch_event_time_field("actual_starts_at_s", "actual_start_s")
    |> normalize_branch_event_time_field("actual_ends_at_s", "actual_end_s")
    |> normalize_branch_event_time_interval("starts_at_s", "ends_at_s")
    |> normalize_branch_event_time_interval("actual_starts_at_s", "actual_ends_at_s")
  end

  defp normalize_branch_event_time_field(event, canonical_field, alias_field) do
    value =
      numeric_or_nil(Map.get(event, canonical_field)) ||
        numeric_or_nil(Map.get(event, alias_field))

    event = Map.delete(event, alias_field)

    if is_number(value) do
      Map.put(event, canonical_field, value)
    else
      Map.delete(event, canonical_field)
    end
  end

  defp normalize_branch_event_time_interval(event, start_field, end_field) do
    start_s = Map.get(event, start_field)
    end_s = Map.get(event, end_field)

    if is_number(start_s) and is_number(end_s) and end_s < start_s do
      Map.put(event, end_field, start_s)
    else
      event
    end
  end

  defp normalize_branch_event_feedback_factor(
         %{"type" => "station_throughput_feedback", "station_throughput_factor" => factor} =
           event
       )
       when is_number(factor) do
    Map.put(event, "station_throughput_factor", clamp_unit_interval(factor))
  end

  defp normalize_branch_event_feedback_factor(
         %{"type" => "contact_success_feedback", "contact_success_factor" => factor} = event
       )
       when is_number(factor) do
    Map.put(event, "contact_success_factor", clamp_unit_interval(factor))
  end

  defp normalize_branch_event_feedback_factor(
         %{"type" => "observation_success_feedback", "observation_success_factor" => factor} =
           event
       )
       when is_number(factor) do
    Map.put(event, "observation_success_factor", clamp_unit_interval(factor))
  end

  defp normalize_branch_event_feedback_factor(
         %{"type" => "maneuver_success_feedback", "maneuver_success_factor" => factor} = event
       )
       when is_number(factor) do
    Map.put(event, "maneuver_success_factor", clamp_unit_interval(factor))
  end

  defp normalize_branch_event_feedback_factor(
         %{"type" => "command_success_feedback", "command_success_factor" => factor} = event
       )
       when is_number(factor) do
    Map.put(event, "command_success_factor", clamp_unit_interval(factor))
  end

  defp normalize_branch_event_feedback_factor(event), do: event

  defp normalize_branch_event_unit_interval_numbers(event) do
    [
      "capacity_fraction",
      "station_throughput_factor",
      "contact_success_factor",
      "observation_success_factor",
      "maneuver_success_factor",
      "command_success_factor",
      "image_quality_score",
      "cloud_cover_fraction",
      "blur_score"
    ]
    |> Enum.reduce(event, fn field, acc ->
      case numeric_or_nil(Map.get(acc, field)) do
        value when is_number(value) and value >= 0.0 and value <= 1.0 ->
          Map.put(acc, field, value)

        value when is_number(value) ->
          acc
          |> put_invalid_branch_event_input(field, value)
          |> Map.delete(field)

        _value ->
          Map.delete(acc, field)
      end
    end)
  end

  defp put_invalid_branch_event_input(event, field, value) do
    reason = "invalid_#{field}"

    event
    |> Map.put("invalid_branch_event_input", true)
    |> Map.put_new("invalid_branch_event_input_reasons", [])
    |> Map.update!("invalid_branch_event_input_reasons", fn reasons ->
      reasons
      |> List.wrap()
      |> Kernel.++([reason])
      |> Enum.uniq()
      |> Enum.sort()
    end)
    |> Map.put_new("source_branch_event", event)
    |> Map.update("invalid_branch_event_fields", [field], fn fields ->
      fields
      |> List.wrap()
      |> Kernel.++([field])
      |> Enum.uniq()
      |> Enum.sort()
    end)
    |> Map.update("invalid_branch_event_values", %{field => value}, fn values ->
      values
      |> stringify_keys()
      |> Map.put(field, value)
    end)
  end

  defp normalize_branch_event_boolean_fields(event) do
    ["allow_placeholder"]
    |> Enum.reduce(event, fn field, acc ->
      case Map.fetch(acc, field) do
        {:ok, value} ->
          case json_boolean_value(value) do
            bool when is_boolean(bool) -> Map.put(acc, field, bool)
            nil -> Map.delete(acc, field)
          end

        :error ->
          acc
      end
    end)
  end

  defp normalize_branch_event_nonnegative_numbers(event) do
    event
    |> normalize_branch_event_nonnegative_number("priority")
    |> normalize_branch_event_nonnegative_number("required_downlink_mb")
    |> normalize_branch_event_nonnegative_number("feedback_weight")
    |> normalize_branch_event_nonnegative_number("feedback_sample_weight")
    |> normalize_branch_event_nonnegative_number("sample_weight")
    |> normalize_branch_event_nonnegative_number("confidence_weight")
    |> normalize_branch_event_nonnegative_number("fuel_margin")
    |> normalize_branch_event_nonnegative_number("power_margin")
    |> normalize_branch_event_nonnegative_number("storage_margin")
    |> normalize_branch_event_nonnegative_number("downlink_margin")
    |> normalize_branch_event_number("thermal_margin_c")
    |> normalize_branch_event_nonnegative_number("battery_capacity_wh")
    |> normalize_branch_event_nonnegative_number("battery_energy_used_wh")
    |> normalize_branch_event_nonnegative_number("battery_state_of_charge")
    |> normalize_branch_event_nonnegative_number("fuel_margin_threshold")
    |> normalize_branch_event_nonnegative_number("power_margin_threshold")
    |> normalize_branch_event_nonnegative_number("storage_margin_threshold")
    |> normalize_branch_event_nonnegative_number("downlink_margin_threshold")
    |> normalize_branch_event_number("thermal_margin_c_threshold")
    |> normalize_branch_event_nonnegative_number("timing_3sigma_s")
    |> normalize_branch_event_nonnegative_number("timing_3sigma_threshold_s")
    |> normalize_branch_event_nonnegative_number("delta_v_3sigma_magnitude_km_s")
    |> normalize_branch_event_nonnegative_number("delta_v_3sigma_magnitude_threshold_km_s")
  end

  defp normalize_branch_event_number(event, field) do
    case numeric_or_nil(Map.get(event, field)) do
      value when is_number(value) -> Map.put(event, field, value)
      _value -> Map.delete(event, field)
    end
  end

  defp normalize_branch_event_nonnegative_number(event, field) do
    case numeric_or_nil(Map.get(event, field)) do
      value when is_number(value) and value >= 0.0 ->
        Map.put(event, field, value)

      value when is_number(value) ->
        event
        |> put_invalid_branch_event_input(field, value)
        |> Map.delete(field)

      _value ->
        Map.delete(event, field)
    end
  end

  defp canonical_resource_margin_field("downlink_capacity_margin"), do: "downlink_margin"
  defp canonical_resource_margin_field("battery_state_of_charge"), do: "power_margin"
  defp canonical_resource_margin_field("storage_capacity_margin"), do: "storage_margin"
  defp canonical_resource_margin_field("battery_soc"), do: "power_margin"

  defp canonical_resource_margin_field(field)
       when field in [
              "fuel_margin",
              "power_margin",
              "storage_margin",
              "downlink_margin",
              "thermal_margin_c"
            ],
       do: field

  defp canonical_resource_margin_field(_field), do: nil

  defp resource_margin_event_field(event) do
    Enum.find(
      ["fuel_margin", "power_margin", "storage_margin", "downlink_margin", "thermal_margin_c"],
      &(event |> Map.get(&1) |> numeric_or_nil() |> is_number())
    )
  end

  defp normalize_resource_margin_threshold_alias(event, "downlink_margin") do
    if Map.has_key?(event, "downlink_margin_threshold") or
         not Map.has_key?(event, "downlink_capacity_margin_threshold") do
      event
    else
      event
      |> Map.put("downlink_margin_threshold", event["downlink_capacity_margin_threshold"])
      |> Map.delete("downlink_capacity_margin_threshold")
    end
  end

  defp normalize_resource_margin_threshold_alias(event, "storage_margin") do
    if Map.has_key?(event, "storage_margin_threshold") or
         not Map.has_key?(event, "storage_capacity_margin_threshold") do
      event
    else
      event
      |> Map.put("storage_margin_threshold", event["storage_capacity_margin_threshold"])
      |> Map.delete("storage_capacity_margin_threshold")
    end
  end

  defp normalize_resource_margin_threshold_alias(event, "power_margin") do
    battery_threshold =
      cond do
        Map.has_key?(event, "battery_state_of_charge_threshold") ->
          {"battery_state_of_charge_threshold", event["battery_state_of_charge_threshold"]}

        Map.has_key?(event, "battery_soc_threshold") ->
          {"battery_soc_threshold", event["battery_soc_threshold"]}

        true ->
          nil
      end

    if Map.has_key?(event, "power_margin_threshold") or is_nil(battery_threshold) do
      event
    else
      {alias_key, value} = battery_threshold

      event
      |> Map.put("power_margin_threshold", value)
      |> Map.delete(alias_key)
    end
  end

  defp normalize_resource_margin_threshold_alias(event, _field), do: event

  defp canonical_resource_availability_field("payload_available?"), do: "payload_available"
  defp canonical_resource_availability_field("antenna_available?"), do: "antenna_available"
  defp canonical_resource_availability_field("spacecraft_available?"), do: "spacecraft_available"

  defp canonical_resource_availability_field("spacecraft_availability"),
    do: "spacecraft_available"

  defp canonical_resource_availability_field(field)
       when field in ["payload_available", "antenna_available", "spacecraft_available"],
       do: field

  defp canonical_resource_availability_field(_field), do: nil

  defp resource_availability_event_field(event) do
    Enum.find(
      ["payload_available", "antenna_available", "spacecraft_available"],
      &is_boolean(event[&1])
    )
  end

  defp normalize_resource_availability_event_value(event, field) do
    case resource_availability_boolean_value(event["available"]) do
      value when is_boolean(value) ->
        Map.put(event, "available", value)

      nil ->
        case event[field] do
          value when is_boolean(value) -> Map.put(event, "available", value)
          _value -> event
        end
    end
  end

  defp normalize_strategy_policy(%StrategicScoringPolicy{} = policy), do: policy

  defp normalize_strategy_policy(policy) do
    policy = stringify_keys(policy || %{})

    %StrategicScoringPolicy{
      mission_value_weight: strategy_policy_number!(policy, "mission_value_weight", 1.0),
      coverage_weight: strategy_policy_number!(policy, "coverage_weight", 25.0),
      revisit_weight: strategy_policy_number!(policy, "revisit_weight", 5.0),
      latency_weight: strategy_policy_number!(policy, "latency_weight", 0.01),
      downlink_completion_weight:
        strategy_policy_number!(policy, "downlink_completion_weight", 50.0),
      fuel_preservation_weight: strategy_policy_number!(policy, "fuel_preservation_weight", 25.0),
      schedule_stability_weight:
        strategy_policy_number!(policy, "schedule_stability_weight", 1.0),
      asset_balance_weight: strategy_policy_number!(policy, "asset_balance_weight", 10.0),
      priority_commitment_weight:
        strategy_policy_number!(policy, "priority_commitment_weight", 50.0),
      risk_weight: strategy_policy_number!(policy, "risk_weight", 100.0),
      approval_load_weight: strategy_policy_number!(policy, "approval_load_weight", 20.0),
      probability_weight: strategy_policy_number!(policy, "probability_weight", 1.0)
    }
  end

  defp strategy_policy_number!(policy, field, default) do
    policy
    |> Map.get(field, default)
    |> numeric!("strategy_policy.#{field}")
  end

  defp normalize_approval_policy(%ApprovalPolicy{} = policy), do: policy

  defp normalize_approval_policy(policy) do
    raw_policy = stringify_keys(policy || %{})
    policy = Policy.normalize_approval_policy(policy)
    default_policy = %ApprovalPolicy{}

    blocked_risk_types =
      if Map.has_key?(raw_policy, "blocked_risk_types") or Map.has_key?(raw_policy, "bundle") or
           Map.has_key?(raw_policy, "policy_bundle_id") do
        Map.get(policy, "blocked_risk_types", default_policy.blocked_risk_types)
      else
        default_policy.blocked_risk_types
      end

    %ApprovalPolicy{
      auto_approvable_risk_limit: Map.get(policy, "auto_approvable_risk_limit", 0),
      auto_approvable_approval_count_limit:
        Map.get(policy, "auto_approvable_approval_count_limit", 0),
      operator_review_risk_limit: Map.get(policy, "operator_review_risk_limit", 3),
      blocked_risk_types: blocked_risk_types,
      action_rules: Map.get(policy, "action_rules", [])
    }
  end

  defp normalize_operational_feedback(%OperationalFeedback{} = feedback) do
    feedback
    |> Map.from_struct()
    |> normalize_operational_feedback()
  end

  defp normalize_operational_feedback(feedback) when not is_map(feedback) do
    normalize_operational_feedback(%{})
  end

  defp normalize_operational_feedback(feedback) do
    feedback = stringify_keys(feedback)

    %{
      "contact_success_rate" =>
        normalize_feedback_factor_map(Map.get(feedback, "contact_success_rate", %{})),
      "observation_success_rate" =>
        normalize_feedback_factor_map(Map.get(feedback, "observation_success_rate", %{})),
      "image_quality_score" =>
        normalize_feedback_factor_map(Map.get(feedback, "image_quality_score", %{})),
      "image_quality_status" =>
        normalize_string_map(Map.get(feedback, "image_quality_status", %{})),
      "image_quality_source" =>
        normalize_string_map(Map.get(feedback, "image_quality_source", %{})),
      "cloud_cover_fraction" =>
        normalize_feedback_factor_map(Map.get(feedback, "cloud_cover_fraction", %{})),
      "blur_score" => normalize_feedback_factor_map(Map.get(feedback, "blur_score", %{})),
      "maneuver_success_rate" =>
        normalize_feedback_factor_map(Map.get(feedback, "maneuver_success_rate", %{})),
      "maneuver_execution_uncertainty" =>
        normalize_maneuver_execution_uncertainty_feedback_map(
          Map.get(feedback, "maneuver_execution_uncertainty", %{})
        ),
      "command_success_rate" =>
        normalize_feedback_factor_map(Map.get(feedback, "command_success_rate", %{})),
      "station_throughput_factor" =>
        normalize_feedback_factor_map(Map.get(feedback, "station_throughput_factor", %{})),
      "downlink_demand_mb" =>
        normalize_nonnegative_number_map(Map.get(feedback, "downlink_demand_mb", %{})),
      "downlink_demand_sources" =>
        normalize_string_list_map(Map.get(feedback, "downlink_demand_sources", %{})),
      "downlink_demand_context" =>
        normalize_object_map(Map.get(feedback, "downlink_demand_context", %{})),
      "target_priority_overrides" =>
        normalize_nonnegative_number_map(Map.get(feedback, "target_priority_overrides", %{})),
      "resource_margin_overrides" =>
        normalize_resource_margin_feedback_map(
          Map.get(feedback, "resource_margin_overrides", %{})
        ),
      "resource_availability_overrides" =>
        feedback
        |> availability_override_feedback()
        |> normalize_resource_availability_feedback_map()
    }
  end

  defp availability_override_feedback(feedback) do
    alias_overrides =
      case Map.get(feedback, "availability_overrides") do
        %{} = overrides -> overrides
        _other -> %{}
      end

    canonical_overrides =
      case Map.get(feedback, "resource_availability_overrides") do
        %{} = overrides -> overrides
        _other -> %{}
      end

    Map.merge(alias_overrides, canonical_overrides)
  end

  defp normalize_feedback_factor_map(%{} = factors) do
    factors
    |> stringify_keys()
    |> Enum.reduce(%{}, fn {key, value}, normalized ->
      case numeric_or_nil(value) do
        number when is_number(number) and number >= 0.0 and number <= 1.0 ->
          put_operational_feedback_entry(normalized, key, number)

        _value ->
          normalized
      end
    end)
  end

  defp normalize_feedback_factor_map(_factors), do: %{}

  defp normalize_nonnegative_number_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn {key, value}, normalized ->
      case numeric_or_nil(value) do
        number when is_number(number) and number >= 0.0 ->
          put_operational_feedback_entry(normalized, key, number)

        _value ->
          normalized
      end
    end)
  end

  defp normalize_nonnegative_number_map(_values), do: %{}

  defp normalize_string_list_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn {key, value}, normalized ->
      if operational_feedback_key?(key) and is_list(value) and
           Enum.all?(value, &valid_feedback_source_string?/1) do
        sources =
          value
          |> Enum.map(&feedback_source_string/1)
          |> Enum.reject(&is_nil/1)
          |> Enum.uniq()
          |> Enum.sort()

        if sources == [] do
          normalized
        else
          Map.put(normalized, key, sources)
        end
      else
        normalized
      end
    end)
  end

  defp normalize_string_list_map(_values), do: %{}

  defp normalize_object_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn {key, value}, normalized ->
      if operational_feedback_key?(key) and is_map(value) do
        put_operational_feedback_entry(
          normalized,
          key,
          value |> stringify_keys() |> compact_map()
        )
      else
        normalized
      end
    end)
  end

  defp normalize_object_map(_values), do: %{}

  defp normalize_string_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn {key, value}, normalized ->
      case feedback_source_string(value) do
        value when is_binary(value) and value != "" ->
          put_operational_feedback_entry(normalized, key, value)

        _value ->
          normalized
      end
    end)
  end

  defp normalize_string_map(_values), do: %{}

  defp feedback_source_string(value) when is_binary(value) and value != "", do: value

  defp feedback_source_string(value) when is_atom(value) and not is_nil(value),
    do: Atom.to_string(value)

  defp feedback_source_string(_value), do: nil

  defp normalize_maneuver_execution_uncertainty_feedback_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn
      {key, %{} = value}, normalized ->
        put_operational_feedback_entry(
          normalized,
          key,
          normalize_maneuver_execution_uncertainty_feedback(value)
        )

      {_key, _value}, normalized ->
        normalized
    end)
  end

  defp normalize_maneuver_execution_uncertainty_feedback_map(_values), do: %{}

  defp normalize_maneuver_execution_uncertainty_feedback(%{} = value) do
    value = stringify_keys(value)

    %{
      "execution_uncertainty_status" => Map.get(value, "execution_uncertainty_status"),
      "execution_uncertainty" => stringify_map_or_nil(Map.get(value, "execution_uncertainty")),
      "timing_3sigma_s" => numeric_or_nil(Map.get(value, "timing_3sigma_s")),
      "delta_v_3sigma_km_s" => numeric_triplet_or_nil(Map.get(value, "delta_v_3sigma_km_s")),
      "delta_v_3sigma_magnitude_km_s" =>
        numeric_or_nil(Map.get(value, "delta_v_3sigma_magnitude_km_s")),
      "execution_uncertainty_source" => Map.get(value, "execution_uncertainty_source")
    }
    |> compact_map()
  end

  defp stringify_map_or_nil(%{} = value), do: stringify_keys(value)
  defp stringify_map_or_nil(_value), do: nil

  defp numeric_triplet_or_nil(values) when is_list(values) and length(values) == 3 do
    triplet = Enum.map(values, &numeric_or_nil/1)

    if Enum.all?(triplet, &is_number/1), do: triplet, else: nil
  end

  defp numeric_triplet_or_nil(_values), do: nil

  defp normalize_resource_margin_feedback_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn
      {key, %{} = value}, normalized ->
        put_operational_feedback_entry(normalized, key, normalize_resource_margin_aliases(value))

      {_key, _value}, normalized ->
        normalized
    end)
  end

  defp normalize_resource_margin_feedback_map(_values), do: %{}

  defp normalize_resource_margin_aliases(%{} = value) do
    value
    |> stringify_keys()
    |> copy_resource_margin_alias("storage_margin", "storage_capacity_margin")
    |> copy_resource_margin_alias("downlink_margin", "downlink_capacity_margin")
    |> copy_resource_margin_alias("battery_state_of_charge", "battery_soc")
    |> copy_resource_margin_alias(
      "min_operating_temperature_c",
      "minimum_operating_temperature_c"
    )
    |> copy_resource_margin_alias(
      "max_operating_temperature_c",
      "maximum_operating_temperature_c"
    )
    |> copy_resource_margin_alias("min_operating_temperature_c", "min_temperature_c")
    |> copy_resource_margin_alias("max_operating_temperature_c", "max_temperature_c")
    |> put_power_margin_from_battery_state_of_charge()
    |> put_thermal_margin_from_temperature_bounds()
    |> normalize_resource_margin_numbers()
  end

  defp normalize_resource_margin_aliases(value), do: value

  defp normalize_resource_margin_numbers(value) do
    [
      "fuel_margin",
      "power_margin",
      "storage_margin",
      "downlink_margin",
      "thermal_margin_c",
      "temperature_c",
      "actual_temperature_c",
      "measured_temperature_c",
      "planned_temperature_c",
      "min_operating_temperature_c",
      "max_operating_temperature_c",
      "thermal_confidence",
      "battery_capacity_wh",
      "battery_energy_used_wh",
      "battery_state_of_charge"
    ]
    |> Enum.reduce(value, fn field, acc ->
      if Map.has_key?(acc, field) do
        case numeric_or_nil(Map.get(acc, field)) do
          number when is_number(number) -> Map.put(acc, field, number * 1.0)
          _value -> Map.delete(acc, field)
        end
      else
        acc
      end
    end)
  end

  defp copy_resource_margin_alias(value, canonical_key, alias_key) do
    value =
      if Map.has_key?(value, canonical_key) or not Map.has_key?(value, alias_key) do
        value
      else
        Map.put(value, canonical_key, Map.get(value, alias_key))
      end

    Map.delete(value, alias_key)
  end

  defp put_power_margin_from_battery_state_of_charge(value) do
    case {Map.get(value, "power_margin"),
          numeric_or_nil(Map.get(value, "battery_state_of_charge"))} do
      {nil, state_of_charge} when is_number(state_of_charge) ->
        Map.put(value, "power_margin", state_of_charge)

      _values ->
        value
    end
  end

  defp put_thermal_margin_from_temperature_bounds(value) do
    with nil <- numeric_or_nil(Map.get(value, "thermal_margin_c")),
         temperature when is_number(temperature) <- resource_margin_temperature_c(value),
         margin when is_number(margin) <-
           resource_margin_thermal_bound_margin_c(value, temperature) do
      value
      |> Map.put("thermal_margin_c", margin)
      |> Map.put_new("temperature_c", temperature)
    else
      _value -> value
    end
  end

  defp resource_margin_temperature_c(value) do
    [
      "actual_temperature_c",
      "measured_temperature_c",
      "temperature_c",
      "planned_temperature_c"
    ]
    |> Enum.map(&(value |> Map.get(&1) |> numeric_or_nil()))
    |> Enum.find(&is_number/1)
  end

  defp resource_margin_thermal_bound_margin_c(value, temperature) do
    min_temperature = numeric_or_nil(Map.get(value, "min_operating_temperature_c"))
    max_temperature = numeric_or_nil(Map.get(value, "max_operating_temperature_c"))

    case {min_temperature, max_temperature} do
      {min_c, max_c} when is_number(min_c) and is_number(max_c) ->
        min(temperature - min_c, max_c - temperature)

      {min_c, nil} when is_number(min_c) ->
        temperature - min_c

      {nil, max_c} when is_number(max_c) ->
        max_c - temperature

      _bounds ->
        nil
    end
  end

  defp normalize_resource_availability_feedback_map(%{} = values) do
    values
    |> stringify_keys()
    |> Enum.reduce(%{}, fn
      {key, %{} = value}, normalized ->
        put_operational_feedback_entry(
          normalized,
          key,
          normalize_resource_availability_aliases(value)
        )

      {_key, _value}, normalized ->
        normalized
    end)
  end

  defp normalize_resource_availability_feedback_map(_values), do: %{}

  defp normalize_resource_availability_aliases(%{} = value) do
    value
    |> stringify_keys()
    |> copy_resource_availability_alias("payload_available", "payload_available?")
    |> copy_resource_availability_alias("antenna_available", "antenna_available?")
    |> copy_resource_availability_alias("spacecraft_available", "spacecraft_available?")
    |> copy_boolean_resource_availability_alias("spacecraft_available", "spacecraft_availability")
    |> copy_resource_availability_status_alias("payload_available", "payload_status")
    |> copy_resource_availability_status_alias("antenna_available", "antenna_status")
    |> copy_resource_availability_status_alias("spacecraft_available", "spacecraft_status")
    |> copy_resource_availability_alias("degraded", "degraded?")
    |> normalize_resource_availability_boolean_values()
  end

  defp normalize_resource_availability_aliases(value), do: value

  defp put_operational_feedback_entry(map, key, value) do
    if operational_feedback_key?(key), do: Map.put(map, key, value), else: map
  end

  defp operational_feedback_key?(key), do: stable_id_string?(key)

  defp normalize_resource_availability_boolean_values(value) do
    Enum.reduce(
      ["payload_available", "antenna_available", "spacecraft_available", "degraded"],
      value,
      fn field, normalized ->
        case resource_availability_boolean_value(Map.get(normalized, field)) do
          bool when is_boolean(bool) -> Map.put(normalized, field, bool)
          nil -> normalized
        end
      end
    )
  end

  defp copy_resource_availability_alias(value, canonical_key, alias_key) do
    value =
      if Map.has_key?(value, canonical_key) or not Map.has_key?(value, alias_key) do
        value
      else
        Map.put(value, canonical_key, Map.get(value, alias_key))
      end

    Map.delete(value, alias_key)
  end

  defp copy_boolean_resource_availability_alias(value, canonical_key, alias_key) do
    alias_value = resource_availability_boolean_value(Map.get(value, alias_key))

    if Map.has_key?(value, canonical_key) or not is_boolean(alias_value) do
      value
    else
      value
      |> Map.put(canonical_key, alias_value)
      |> Map.delete(alias_key)
    end
  end

  defp copy_resource_availability_status_alias(value, canonical_key, alias_key) do
    alias_value = resource_availability_boolean_value(Map.get(value, alias_key))

    if Map.has_key?(value, canonical_key) or not is_boolean(alias_value) do
      value
    else
      Map.put(value, canonical_key, alias_value)
    end
  end

  defp resource_availability_boolean_value(value) when is_boolean(value), do: value

  defp resource_availability_boolean_value(value) when is_number(value) do
    cond do
      value == 1 -> true
      value == 0 -> false
      true -> nil
    end
  end

  defp resource_availability_boolean_value(value) when is_binary(value) do
    case String.downcase(String.trim(value)) do
      value when value in @resource_availability_true_tokens -> true
      value when value in @resource_availability_false_tokens -> false
      _value -> nil
    end
  end

  defp resource_availability_boolean_value(_value), do: nil

  defp prior_plan_operational_feedback(prior_plan) do
    source_feedback = prior_plan_timeline_feedback_operational_feedback(prior_plan)

    planned_activity_feedback =
      prior_plan_planned_activity_operational_feedback(prior_plan)

    proposed_contact_feedback =
      prior_plan_proposed_contact_operational_feedback(prior_plan)

    realized_activity_feedback =
      prior_plan_realized_activity_operational_feedback(prior_plan)

    operational_timeline_feedback =
      prior_plan_operational_timeline_operational_feedback(prior_plan)

    command_window_feedback = prior_plan_command_window_operational_feedback(prior_plan)
    maneuver_review_feedback = prior_plan_maneuver_review_operational_feedback(prior_plan)

    cadence_import_source_feedback =
      prior_plan_cadence_import_source_operational_feedback(prior_plan)

    cadence_import_feedback = prior_plan_cadence_import_operational_feedback(prior_plan)

    operator_review_source_feedback =
      prior_plan_operator_review_source_operational_feedback(prior_plan)

    operator_review_feedback = prior_plan_operator_review_operational_feedback(prior_plan)

    prior_plan
    |> prior_plan_direct_operational_feedback()
    |> normalize_operational_feedback()
    |> then(&merge_operational_feedback(operator_review_feedback, &1))
    |> then(&merge_operational_feedback(operator_review_source_feedback, &1))
    |> then(&merge_operational_feedback(cadence_import_feedback, &1))
    |> then(&merge_operational_feedback(cadence_import_source_feedback, &1))
    |> then(&merge_operational_feedback(maneuver_review_feedback, &1))
    |> then(&merge_operational_feedback(command_window_feedback, &1))
    |> then(&merge_operational_feedback(operational_timeline_feedback, &1))
    |> then(&merge_operational_feedback(realized_activity_feedback, &1))
    |> then(&merge_operational_feedback(proposed_contact_feedback, &1))
    |> then(&merge_operational_feedback(planned_activity_feedback, &1))
    |> then(&merge_operational_feedback(source_feedback, &1))
  end

  defp prior_plan_direct_operational_feedback(prior_plan) do
    sources = prior_plan_direct_operational_feedback_sources(prior_plan)

    sources
    |> Enum.filter(fn {feedback, _source_path} -> is_map(feedback) end)
    |> Enum.map(fn {feedback, _source_path} -> feedback end)
    |> case do
      [] ->
        sources
        |> Enum.map(fn {feedback, _source_path} -> feedback end)
        |> Enum.find(%{}, &(not is_nil(&1)))

      feedback_maps ->
        Enum.reduce(feedback_maps, normalize_operational_feedback(%{}), fn feedback, merged ->
          merge_operational_feedback(merged, feedback)
        end)
    end
  end

  defp prior_plan_direct_operational_feedback_metadata(prior_plan) do
    sources = prior_plan_direct_operational_feedback_sources(prior_plan)

    source_paths =
      sources
      |> Enum.map(fn {_feedback, source_path} -> source_path end)
      |> Enum.uniq()

    feedback_maps =
      sources
      |> Enum.map(fn {feedback, _source_path} -> feedback end)
      |> Enum.filter(&is_map/1)

    trust_boundaries =
      feedback_maps
      |> Enum.flat_map(fn feedback ->
        summary = trust_boundary_summary(feedback)
        summary |> Map.get("trust_boundaries") |> List.wrap()
      end)
      |> Enum.uniq()
      |> Enum.sort()

    feedback_trust_boundaries =
      feedback_maps
      |> Enum.flat_map(fn feedback ->
        summary = trust_boundary_summary(feedback)

        [
          Map.get(summary, "feedback_trust_boundaries"),
          inferred_feedback_trust_boundaries(feedback)
        ]
      end)
      |> merge_feedback_trust_boundary_maps()
      |> case do
        boundaries when boundaries == %{} -> nil
        boundaries -> boundaries
      end

    %{
      "source_report_paths" => if(source_paths == [], do: nil, else: source_paths),
      "trust_boundary_status" => if(trust_boundaries == [], do: nil, else: "declared"),
      "trust_boundaries" => if(trust_boundaries == [], do: nil, else: trust_boundaries),
      "feedback_trust_boundaries" => feedback_trust_boundaries
    }
    |> compact_map()
  end

  defp prior_plan_direct_operational_feedback_sources(prior_plan) do
    prior_plan = stringify_keys(prior_plan || %{})

    direct_sources =
      case Map.fetch(prior_plan, "operational_feedback") do
        {:ok, feedback} -> [{feedback, "prior_plan.operational_feedback"}]
        :error -> []
      end

    result_artifact_sources =
      prior_plan
      |> prior_plan_result_artifacts_with_source()
      |> Enum.flat_map(fn {artifact, source_path} ->
        case Map.fetch(artifact, "operational_feedback") do
          {:ok, feedback} -> [{feedback, "#{source_path}.operational_feedback"}]
          :error -> []
        end
      end)

    direct_sources ++ result_artifact_sources
  end

