  defp command_window_feedback_trust_boundaries(rows) do
    command_boundaries =
      rows
      |> Enum.reduce(%{}, fn row, boundaries ->
        activity_id = realized_feedback_activity_id(row)
        trust_boundary = command_window_feedback_trust_boundary(row)

        if activity_id in [nil, ""] or trust_boundary in [nil, ""] do
          boundaries
        else
          put_feedback_trust_boundary(
            boundaries,
            "command_success_rate",
            activity_id,
            [trust_boundary]
          )
        end
      end)
      |> Map.get("command_success_rate")

    case command_boundaries do
      %{} = boundaries -> %{"command_success_rate" => boundaries}
      _boundaries -> nil
    end
  end

  defp command_window_feedback_trust_boundary(row) do
    row["trust_boundary"] ||
      get_in(row, ["provenance", "trust_boundary"]) ||
      row["_source_report_trust_boundary"]
  end

  defp command_window_report_trust_boundaries(reports) do
    reports
    |> Enum.flat_map(fn report ->
      [
        Map.get(report, "trust_boundary"),
        get_in(report, ["provenance", "trust_boundary"])
      ]
    end)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      boundaries -> boundaries
    end
  end

  defp command_window_feedback_row?(row) do
    command_activity?(row) and realized_feedback_activity_id(row) not in [nil, ""] and
      not is_nil(command_window_row_success_value(row))
  end

  defp command_window_row_success_value(row) do
    case unit_interval_number_or_nil(row["command_success_factor"]) do
      value when is_number(value) -> value
      _value -> command_success_value(row)
    end
  end

