  defp mission_state_source_report_entries(nil, _source_path), do: []

  defp mission_state_source_report_entries(reports, source_path) when is_list(reports) do
    reports
    |> Enum.with_index()
    |> Enum.flat_map(fn {report, index} ->
      mission_state_source_report_entries(report, "#{source_path}[#{index}]")
    end)
  end

  defp mission_state_source_report_entries(%{} = report, source_path),
