  defp result_artifact_embedded_report_entries(reports, artifact, source_path)
       when is_list(reports) do
    reports
    |> Enum.with_index()
    |> Enum.flat_map(fn {report, index} ->
      result_artifact_embedded_report_entries(report, artifact, "#{source_path}[#{index}]")
    end)
  end

  defp result_artifact_embedded_report_entries(%{} = report, artifact, source_path) do
    report =
      report
      |> stringify_keys()
      |> put_inherited_result_artifact_trust_boundary(artifact)

    [{report, source_path}]
  end

  defp result_artifact_embedded_report_entries(_report, _artifact, _source_path), do: []

  defp put_inherited_result_artifact_trust_boundary(report, artifact) do
    trust_boundary =
      Map.get(report, "trust_boundary") ||
        get_in(report, ["provenance", "trust_boundary"]) ||
        Map.get(artifact, "trust_boundary") ||
        get_in(artifact, ["provenance", "trust_boundary"]) ||
        get_in(artifact, ["metadata", "trust_boundary"])

    if trust_boundary in [nil, ""] do
      report
    else
      Map.put_new(report, "trust_boundary", trust_boundary)
    end
  end

  defp result_artifact_maneuver_review_rows_with_source(artifact, source_path) do
    artifact = stringify_keys(artifact)

    review_rows =
      [
        "source_maneuver_review_report",
        "maneuver_review_report"
      ]
      |> Enum.flat_map(fn report_key ->
        report = Map.get(artifact, report_key)

        report
        |> result_artifact_maneuver_review_report_rows(artifact)
        |> Enum.map(fn row -> {row, "#{source_path}.#{report_key}.rows"} end)
      end)

    review_keys =
      review_rows
      |> Enum.map(fn {row, _row_source_path} -> row end)
      |> MapSet.new(&maneuver_review_replay_identity/1)

    recommendation_rows =
      artifact
      |> result_artifact_maneuver_recommendation_review_rows()
      |> Enum.map(fn row ->
        row =
          row
          |> stringify_keys()
          |> put_inherited_result_artifact_trust_boundary(artifact)
          |> Map.put_new(
            "_source_report_trust_boundary",
            Map.get(row, "trust_boundary") || get_in(row, ["provenance", "trust_boundary"])
          )

        {row, "#{source_path}.maneuver_recommendations"}
      end)

    review_rows ++
      Enum.reject(recommendation_rows, fn {row, _row_source_path} ->
        MapSet.member?(review_keys, maneuver_review_replay_identity(row))
      end)
  end

  defp result_artifact_maneuver_review_report_rows(%{} = report, artifact) do
    report = stringify_keys(report)

    report_trust_boundary =
      Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

    report
    |> Map.get("rows", [])
    |> List.wrap()
    |> Enum.map(fn row ->
      row
      |> stringify_keys()
      |> put_inherited_result_artifact_trust_boundary(report)
      |> put_inherited_result_artifact_trust_boundary(artifact)
      |> Map.put_new("_source_report_trust_boundary", report_trust_boundary)
    end)
  end

  defp result_artifact_maneuver_review_report_rows(_report, _artifact), do: []

  defp result_artifact_maneuver_recommendation_review_rows(artifact) do
    case Map.get(artifact, "maneuver_recommendations", []) do
      [] ->
        []

      recommendations ->
        recommendations
        |> OrbitalDynamics.ManeuverReview.report(
          source: "result_artifact.maneuver_recommendations",
          source_artifact_id: result_artifact_source_id(artifact)
        )
        |> Map.get("rows", [])
        |> List.wrap()
    end
  end

  defp result_artifact_source_id(artifact) do
    Enum.find_value(
      [
        Map.get(artifact, "id"),
        Map.get(artifact, "study_id"),
        get_in(artifact, ["run", "id"]),
        get_in(artifact, ["execution_report", "run_id"])
      ],
      &encode_value/1
    )
  end

  defp maneuver_review_replay_identity(row) do
    row = stringify_keys(row)

    [
      row["maneuver_id"] || row["activity_id"],
      row["scenario_id"],
      row["epoch_s"],
      row["delta_v_km_s"],
      row["required_operator_action"] || row["action"]
    ]
    |> encode_value()
  end

  defp put_feedback_map(feedback, _field, values) when values in [%{}, nil], do: feedback

  defp put_feedback_map(feedback, field, %{} = values), do: Map.put(feedback, field, values)

  defp normalize_maneuver_review_feedback_row(row) do
    row =
      if Map.has_key?(row, "activity_id") or row["maneuver_id"] in [nil, ""] do
        row
      else
        Map.put(row, "activity_id", row["maneuver_id"])
      end

    if Map.has_key?(row, "type") or row["maneuver_type"] in [nil, ""] do
      row
    else
      Map.put(row, "type", row["maneuver_type"])
    end
  end

  defp maneuver_review_feedback_row?(row) do
    maneuver_activity?(row) and realized_feedback_activity_id(row) not in [nil, ""] and
      not is_nil(maneuver_review_row_success_value(row))
  end

  defp maneuver_review_row_success_value(row) do
    case unit_interval_number_or_nil(row["maneuver_success_factor"]) do
      value when is_number(value) -> value
      _value -> maneuver_success_value(row)
    end
  end

  defp maneuver_review_execution_uncertainty_feedback(rows) do
    rows
    |> Enum.map(fn row ->
      {realized_feedback_activity_id(row), maneuver_review_execution_uncertainty_entry(row)}
    end)
    |> Enum.filter(fn {activity_id, entry} ->
      operational_feedback_key?(activity_id) and entry != %{}
    end)
    |> Enum.group_by(fn {activity_id, _entry} -> activity_id end, fn {_activity_id, entry} ->
      entry
    end)
    |> Map.new(fn {activity_id, entries} ->
      {activity_id, Enum.max_by(entries, &maneuver_execution_uncertainty_entry_rank/1)}
    end)
  end

  defp maneuver_review_execution_uncertainty_entry(row) do
    raw_uncertainty =
      case Map.get(row, "execution_uncertainty") do
        %{} = uncertainty -> stringify_keys(uncertainty)
        _uncertainty -> nil
      end

    delta_v_3sigma_km_s =
      numeric_triplet_or_nil(row["delta_v_3sigma_km_s"]) ||
        numeric_triplet_or_nil(raw_uncertainty && raw_uncertainty["delta_v_3sigma_km_s"])

    entry =
      %{
        "execution_uncertainty_status" =>
          row["execution_uncertainty_status"] ||
            if(is_map(raw_uncertainty), do: "declared"),
        "execution_uncertainty" => raw_uncertainty,
        "timing_3sigma_s" =>
          numeric_or_nil(row["timing_3sigma_s"]) ||
            numeric_or_nil(raw_uncertainty && raw_uncertainty["timing_3sigma_s"]),
        "delta_v_3sigma_km_s" => delta_v_3sigma_km_s,
        "delta_v_3sigma_magnitude_km_s" =>
          numeric_or_nil(row["delta_v_3sigma_magnitude_km_s"]) ||
            numeric_or_nil(raw_uncertainty && raw_uncertainty["delta_v_3sigma_magnitude_km_s"]) ||
            vector_magnitude_or_nil(delta_v_3sigma_km_s),
        "execution_uncertainty_source" =>
          row["execution_uncertainty_source"] ||
            (raw_uncertainty && (raw_uncertainty["source"] || raw_uncertainty["model"]))
      }
      |> compact_map()

    case entry do
      %{"execution_uncertainty_status" => status} when status in ["declared", "missing"] ->
        entry

      _entry ->
        %{}
    end
  end

  defp maneuver_execution_uncertainty_entry_rank(entry) do
    {
      if(entry["execution_uncertainty_status"] == "missing", do: 1, else: 0),
      entry["timing_3sigma_s"] || -1.0,
      entry["delta_v_3sigma_magnitude_km_s"] || -1.0,
      entry["execution_uncertainty_source"] || ""
    }
  end

  defp vector_magnitude_or_nil(values) when is_list(values) do
    if Enum.all?(values, &is_number/1) do
      values
      |> Enum.reduce(0.0, fn value, sum -> sum + value * value end)
      |> :math.sqrt()
    end
  end

  defp vector_magnitude_or_nil(_values), do: nil

  defp source_execution_uncertainty_status_count(rows, status) do
    count =
      Enum.count(rows, fn row ->
        row
        |> maneuver_review_execution_uncertainty_entry()
        |> Map.get("execution_uncertainty_status")
        |> Kernel.==(status)
      end)

    if count > 0, do: count
  end

