  defp operator_review_rows_operational_feedback(rows) do
    operational_timeline_rows = operator_review_operational_timeline_rows(rows)
    realized_feedback_rows = operator_review_realized_feedback_rows(rows)

    contact_rows =
      (operational_timeline_rows ++ realized_feedback_rows)
      |> Enum.filter(&operator_review_contact_feedback_row?/1)

    observation_rows =
      (operational_timeline_rows ++ realized_feedback_rows)
      |> Enum.filter(&operator_review_observation_feedback_row?/1)

    command_rows =
      rows
      |> operator_review_command_window_rows()
      |> Kernel.++(
        Enum.filter(operational_timeline_rows, &operator_review_command_feedback_row?/1)
      )
      |> Kernel.++(Enum.filter(realized_feedback_rows, &operator_review_command_feedback_row?/1))

    maneuver_rows =
      rows
      |> operator_review_maneuver_review_rows()
      |> Kernel.++(
        Enum.filter(operational_timeline_rows, &operator_review_maneuver_feedback_row?/1)
      )
      |> Kernel.++(Enum.filter(realized_feedback_rows, &operator_review_maneuver_feedback_row?/1))

    command_rates =
      command_rows
      |> activity_feedback_average(&command_window_row_success_value/1)

    maneuver_rates =
      maneuver_rows
      |> activity_feedback_average(&maneuver_review_row_success_value/1)

    maneuver_uncertainties = maneuver_review_execution_uncertainty_feedback(maneuver_rows)

    %{
      "contact_success_rate" =>
        station_feedback_average(
          contact_rows,
          &operator_review_operational_timeline_contact_success_value/1
        ),
      "observation_success_rate" =>
        target_feedback_average(
          observation_rows,
          &operator_review_operational_timeline_observation_success_value/1
        ),
      "image_quality_score" =>
        target_feedback_average(observation_rows, &image_quality_score_value/1),
      "image_quality_status" =>
        target_feedback_text(observation_rows, &image_quality_status_value/1),
      "image_quality_source" =>
        target_feedback_text(observation_rows, &image_quality_source_value/1),
      "cloud_cover_fraction" =>
        target_feedback_average(observation_rows, &cloud_cover_fraction_value/1),
      "blur_score" => target_feedback_average(observation_rows, &blur_score_value/1),
      "command_success_rate" => command_rates,
      "maneuver_success_rate" => maneuver_rates,
      "maneuver_execution_uncertainty" => maneuver_uncertainties,
      "station_throughput_factor" =>
        station_feedback_average(contact_rows, &station_throughput_value/1),
      "downlink_demand_mb" => station_downlink_demand_feedback(contact_rows)
    }
  end

