  defp prior_plan_cadence_import_rows_with_source(prior_plan) do
    prior_plan
    |> prior_plan_cadence_import_manifests()
    |> Enum.flat_map(fn {manifest, source_path} ->
      manifest_trust_boundary =
        Map.get(manifest, "trust_boundary") || get_in(manifest, ["provenance", "trust_boundary"])

      manifest
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(fn row ->
        row =
          row
          |> Map.put(
            "_source_report_trust_boundary",
            cadence_import_trust_boundary(row, manifest_trust_boundary)
          )
          |> Map.put("_source_path", "#{source_path}.rows")

        {row, source_path}
      end)
    end)
  end

  defp mission_state_cadence_import_rows_with_source(mission_state) do
    mission_state
    |> mission_state_cadence_import_manifests()
    |> Enum.flat_map(fn {manifest, source_path} ->
      manifest_trust_boundary =
        Map.get(manifest, "trust_boundary") || get_in(manifest, ["provenance", "trust_boundary"])

      manifest
      |> Map.get("rows", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(fn row ->
        row =
          row
          |> Map.put(
            "_source_report_trust_boundary",
            cadence_import_trust_boundary(row, manifest_trust_boundary)
          )
          |> Map.put("_source_path", "#{source_path}.rows")

        {row, source_path}
      end)
    end)
