  defp prior_plan_cadence_import_manifests(prior_plan) do
    direct_manifests =
      source_artifact_entries(
        Map.get(prior_plan, "cadence_import_manifest"),
        "prior_plan.cadence_import_manifest"
      )

    direct_manifests ++ prior_plan_result_artifact_cadence_import_manifests(prior_plan)
  end

  defp mission_state_cadence_import_manifests(mission_state) do
    direct_manifests =
      mission_state_direct_cadence_import_manifests(mission_state, [
        {"source_cadence_import_manifest", "mission_state.source_cadence_import_manifest"},
        {"cadence_import_manifest", "mission_state.cadence_import_manifest"}
      ])

    direct_manifests ++ mission_state_result_artifact_cadence_import_manifests(mission_state)
  end

  defp mission_state_source_cadence_import_manifests(mission_state) do
    mission_state_direct_cadence_import_manifests(mission_state, [
      {"source_cadence_import_manifest", "mission_state.source_cadence_import_manifest"}
    ])
