  defp operator_review_realized_feedback_rows(rows) do
    rows
    |> Enum.filter(&(&1["review_type"] == "realized_feedback"))
    |> Enum.map(fn row ->
      source =
        row
        |> Map.get("source_feedback", row)
        |> stringify_keys()

