      realized_status = row["realized_status"] || source["realized_status"] || row["status"]

      source
      |> put_if_present("feedback_status", feedback_status)
      |> put_if_present("status", realized_status)
      |> put_operator_review_row_fallback(row, "activity_id")
      |> put_operator_review_row_fallback(row, "id", "activity_id")
