  defp timeline_feedback_report_row_count(report) do
    Map.get(report, "row_count") || length(Map.get(report, "rows", []))
  end

  defp merge_report_count_maps(reports, field) do
    reports
    |> Enum.map(&Map.get(&1, field))
    |> Enum.filter(&is_map/1)
    |> Enum.reduce(%{}, fn counts, merged ->
      counts
      |> stringify_keys()
      |> Enum.reduce(merged, fn {key, value}, merged ->
        case numeric_or_nil(value) do
          number when is_number(number) ->
            Map.update(merged, key, number, &(&1 + number))

          _value ->
            merged
        end
      end)
    end)
    |> case do
      counts when counts == %{} -> nil
      counts -> counts
    end
  end

  defp timeline_feedback_report_trust_boundary_status(reports) do
    case timeline_feedback_report_trust_boundaries(reports) do
      boundaries when is_list(boundaries) and boundaries != [] -> "declared"
      _boundaries -> nil
    end
  end

  defp timeline_feedback_report_trust_boundaries(reports) do
    reports
    |> Enum.flat_map(fn report ->
      [
        Map.get(report, "trust_boundary"),
        get_in(report, ["provenance", "trust_boundary"]),
        source_report_operational_feedback_trust_boundaries(report)
      ]
    end)
    |> List.flatten()
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      boundaries -> boundaries
    end
  end

  defp timeline_feedback_reports_feedback_trust_boundaries(reports) do
    reports
    |> Enum.reduce(%{}, fn report, boundaries ->
      report_boundaries =
        case source_report_operational_feedback_trust_boundaries(report) do
          values when is_list(values) and values != [] ->
            source_feedback_trust_boundaries(%{
              "source_operational_feedback_provenance" =>
                source_report_operational_feedback_provenance(report)
            })
            |> merge_feedback_trust_boundary_maps()

          _values ->
            timeline_feedback_report_feedback_trust_boundaries(report)
        end

      merge_feedback_trust_boundary_maps([boundaries, report_boundaries])
    end)
    |> case do
      boundaries when boundaries == %{} -> nil
      boundaries -> boundaries
    end
  end

  defp timeline_feedback_report_feedback_trust_boundaries(report) do
    trust_boundary =
      Map.get(report, "trust_boundary") || get_in(report, ["provenance", "trust_boundary"])

    if trust_boundary in [nil, ""] do
      %{}
    else
      report
      |> Map.get("operational_feedback", %{})
      |> normalize_operational_feedback()
      |> Enum.reduce(%{}, fn {field, values}, boundaries ->
        values
        |> Enum.reduce(boundaries, fn {key, value}, boundaries ->
          if operational_feedback_value_present?(%{key => value}) do
            put_feedback_trust_boundary(boundaries, field, key, [trust_boundary])
          else
            boundaries
          end
        end)
      end)
    end
  end

  defp merge_feedback_trust_boundary_maps(boundary_maps) do
    boundary_maps
    |> List.wrap()
    |> Enum.filter(&is_map/1)
    |> Enum.reduce(%{}, fn boundaries, merged ->
      boundaries
      |> stringify_keys()
      |> Enum.reduce(merged, fn {field, key_boundaries}, merged ->
        if is_map(key_boundaries) do
          Enum.reduce(key_boundaries, merged, fn {key, trust_boundaries}, merged ->
            put_feedback_trust_boundary(merged, field, key, List.wrap(trust_boundaries))
          end)
        else
          merged
        end
      end)
    end)
  end

