    source_report_paths = operator_review_rows_source_paths(rows)

    %{
      "source_report_contract" => "cadence_import_manifest.v1",
      "source_report_count" =>
        replay_source_report_count(rows, source_report_paths, fn ->
          if(rows == [], do: 0, else: 1)
        end),
      "source_report_paths" => if(source_report_paths == [], do: nil, else: source_report_paths),
      "source_report_row_count" => length(rows),
      "source_import_action_counts" => count_present_values(rows, "import_action"),
      "source_review_type_counts" => count_present_values(rows, "source_review_type"),
      "source_operational_feedback_provenance" =>
        cadence_import_operational_feedback_source_provenance(rows),
      "trust_boundary_status" => cadence_import_operational_feedback_trust_status(rows),
      "trust_boundaries" => cadence_import_operational_feedback_trust_boundaries(rows)
    }
    |> compact_map()
  end

  defp replay_source_report_count([], _source_report_paths, _fallback_count_fun), do: 0

  defp replay_source_report_count(_rows, source_report_paths, _fallback_count_fun)
       when source_report_paths != [],
       do: length(source_report_paths)

  defp replay_source_report_count(_rows, _source_report_paths, fallback_count_fun),
    do: fallback_count_fun.()

  defp cadence_import_operational_feedback_source_provenance(rows) do
    rows
    |> Enum.map(&Map.get(&1, "source_operational_feedback_provenance"))
    |> Enum.filter(&is_map/1)
    |> case do
      [] -> nil
      [provenance] -> provenance
      provenances -> %{"sources" => provenances, "source_count" => length(provenances)}
    end
  end

  defp operator_review_operational_feedback_source_provenance(rows) do
    rows
    |> Enum.map(&Map.get(&1, "source_operational_feedback_provenance"))
    |> Enum.filter(&is_map/1)
    |> case do
      [] -> nil
      [provenance] -> provenance
      provenances -> %{"sources" => provenances, "source_count" => length(provenances)}
    end
  end

  defp operator_review_operational_feedback_trust_status(rows) do
    case operator_review_operational_feedback_trust_boundaries(rows) do
      [] -> nil
      _boundaries -> "declared"
    end
  end

  defp operator_review_operational_feedback_trust_boundaries(rows) do
    rows
    |> Enum.flat_map(fn row ->
      [
        row["operational_feedback_trust_boundary"],
        row["trust_boundary"],
        get_in(row, ["provenance", "trust_boundary"]),
        operational_feedback_provenance_trust_boundaries(
          row["source_operational_feedback_provenance"]
        )
      ]
      |> List.flatten()
    end)
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp cadence_import_operational_feedback_trust_status(rows) do
    case cadence_import_operational_feedback_trust_boundaries(rows) do
      [] -> nil
      _boundaries -> "declared"
    end
  end

  defp cadence_import_operational_feedback_trust_boundaries(rows) do
    rows
    |> Enum.flat_map(fn row ->
      [
        row["operational_feedback_trust_boundary"],
        row["trust_boundary"],
        get_in(row, ["provenance", "trust_boundary"]),
        operational_feedback_provenance_trust_boundaries(
          row["source_operational_feedback_provenance"]
        )
      ]
      |> List.flatten()
    end)
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp operational_feedback_provenance_trust_boundaries(%{} = provenance) do
    provenance = stringify_keys(provenance)

    direct_boundaries = [
      Map.get(provenance, "trust_boundary"),
      Map.get(provenance, "trust_boundaries")
    ]

    nested_boundaries =
      provenance
      |> Map.get("sources", [])
      |> List.wrap()
      |> Enum.flat_map(fn
        %{} = source ->
          source = stringify_keys(source)

          [
            source["trust_boundary"],
            source["trust_boundaries"]
          ]
          |> List.flatten()

        _source ->
          []
      end)

    (direct_boundaries ++ nested_boundaries)
    |> List.flatten()
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp operational_feedback_provenance_trust_boundaries(_provenance), do: []

  defp operator_review_rows_source_metadata(rows, source_report_contract) do
    feedback_weight_rows = Enum.map(rows, &operator_review_feedback_weight_evidence/1)
    weighted_feedback_row_count = weighted_realized_feedback_row_count(feedback_weight_rows)
    feedback_weight_sources = realized_feedback_weight_sources(feedback_weight_rows)
    invalid_sections = operator_review_rows_invalid_unit_interval_feedback_sections(rows)
    source_report_paths = operator_review_rows_source_paths(rows)

    %{
      "source_report_contract" => source_report_contract,
      "source_report_count" =>
        cond do
          rows == [] -> 0
          source_report_paths == [] -> 1
          true -> length(source_report_paths)
        end,
      "source_report_paths" => if(source_report_paths == [], do: nil, else: source_report_paths),
      "source_report_row_count" => length(rows),
      "source_review_type_counts" => count_present_values(rows, "review_type"),
      "source_review_action_counts" =>
        count_present_values(rows, ["action", "required_operator_action"]),
      "source_review_queue_counts" =>
        count_present_values(rows, ["review_queue_key", "review_queue"]),
      "weighted_feedback_row_count" =>
        if(weighted_feedback_row_count > 0, do: weighted_feedback_row_count),
      "feedback_weight_sources" =>
        if(feedback_weight_sources == [], do: nil, else: feedback_weight_sources),
      "invalid_operational_feedback_sections" =>
        if(invalid_sections == [], do: nil, else: invalid_sections),
      "trust_boundary_status" => operator_review_rows_trust_boundary_status(rows),
      "trust_boundaries" => operator_review_rows_trust_boundaries(rows)
    }
    |> compact_map()
  end

  defp operator_review_rows_source_paths(rows) do
    rows
    |> Enum.map(&Map.get(&1, "_source_path"))
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp operator_review_rows_trust_boundary_status(rows) do
    case operator_review_rows_trust_boundaries(rows) do
      boundaries when is_list(boundaries) and boundaries != [] -> "declared"
      _boundaries -> nil
    end
  end

  defp operator_review_rows_trust_boundaries(rows) do
    rows
    |> Enum.flat_map(fn row ->
      [
        row["trust_boundary"],
        get_in(row, ["provenance", "trust_boundary"]),
        row["_source_report_trust_boundary"]
      ]
    end)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      boundaries -> boundaries
    end
  end

  defp operator_review_feedback_weight_evidence(row) do
    row = stringify_keys(row)

    source =
      [
        "source_feedback",
        "source_operational_timeline",
        "source_command_window",
        "source_maneuver_review"
      ]
      |> Enum.find_value(fn field ->
        case Map.get(row, field) do
          %{} = source -> stringify_keys(source)
          _source -> nil
        end
      end)

    Map.merge(row, source || %{})
  end

  defp operator_review_rows_invalid_unit_interval_feedback_sections(rows) do
    rows
    |> Enum.map(&operator_review_feedback_weight_evidence/1)
    |> Enum.with_index(1)
    |> Enum.flat_map(fn {row, row_index} ->
      row
      |> operator_review_unit_interval_feedback_values()
      |> Enum.flat_map(fn {field, value} ->
        case unit_interval_number_status(value) do
          {:ok, _value} ->
            []

          :missing ->
            []

          {:invalid_number, number} ->
            [
              operator_review_invalid_unit_interval_section(
                row,
                row_index,
                field,
                "value_must_be_between_0_and_1",
                "invalid_feedback_value",
                number
              )
            ]

          {:invalid_shape, shape} ->
            [
              operator_review_invalid_unit_interval_section(
                row,
                row_index,
                field,
                "entry_must_be_unit_interval_number",
                "invalid_feedback_shape",
                stringify_keys(shape)
              )
            ]
        end
      end)
    end)
    |> Enum.uniq()
  end

  defp operator_review_invalid_unit_interval_section(
         row,
         row_index,
         field,
         reason,
         invalid_key,
         invalid_value
       ) do
    %{
      "field" => "operator_review.rows.#{field}",
      "reason" => reason,
      invalid_key => invalid_value,
      "row_id" => row["id"] || row["activity_id"] || row["timeline_id"],
      "row_index" => row_index
    }
    |> compact_map()
  end

