  defp mission_state_report_from_reports([{report, _source_path}]), do: report

  defp mission_state_report_from_reports(reports) when is_list(reports) and reports != [],
    do: merge_mission_state_source_reports(reports)

  defp mission_state_report_from_reports(_reports), do: %{}

  defp merge_mission_state_source_reports(reports_with_sources) do
    reports = Enum.map(reports_with_sources, fn {report, _source_path} -> report end)

    reports
    |> List.first(%{})
    |> Map.put("rows", Enum.flat_map(reports, &(Map.get(&1, "rows", []) || [])))
    |> Map.put("row_count", Enum.sum(Enum.map(reports, &timeline_feedback_report_row_count/1)))
  end

