      {"image_quality_score", activity["image_quality_score"]},
      {"product_quality_score", activity["product_quality_score"]},
      {"quality_score", activity["quality_score"]},
      {"cloud_cover_fraction", activity["cloud_cover_fraction"]},
      {"cloud_fraction", activity["cloud_fraction"]},
      {"cloud_cover", activity["cloud_cover"]},
      {"blur_score", activity["blur_score"]},
      {"image_blur_score", activity["image_blur_score"]},
      {"sharpness_loss_fraction", activity["sharpness_loss_fraction"]},
      {"quality.image_quality_score", get_in(activity, ["quality", "image_quality_score"])},
      {"quality.product_quality_score", get_in(activity, ["quality", "product_quality_score"])},
      {"quality.score", get_in(activity, ["quality", "score"])},
      {"quality.cloud_cover_fraction", get_in(activity, ["quality", "cloud_cover_fraction"])},
      {"quality.cloud_fraction", get_in(activity, ["quality", "cloud_fraction"])},
      {"quality.cloud_cover", get_in(activity, ["quality", "cloud_cover"])},
      {"quality.blur_score", get_in(activity, ["quality", "blur_score"])},
      {"quality.image_blur_score", get_in(activity, ["quality", "image_blur_score"])},
      {"quality.sharpness_loss_fraction",
       get_in(activity, ["quality", "sharpness_loss_fraction"])},
      {"metadata.image_quality_score", get_in(activity, ["metadata", "image_quality_score"])},
      {"metadata.product_quality_score", get_in(activity, ["metadata", "product_quality_score"])},
      {"metadata.quality_score", get_in(activity, ["metadata", "quality_score"])},
      {"metadata.cloud_cover_fraction", get_in(activity, ["metadata", "cloud_cover_fraction"])},
      {"metadata.cloud_fraction", get_in(activity, ["metadata", "cloud_fraction"])},
      {"metadata.cloud_cover", get_in(activity, ["metadata", "cloud_cover"])},
      {"metadata.blur_score", get_in(activity, ["metadata", "blur_score"])},
      {"metadata.image_blur_score", get_in(activity, ["metadata", "image_blur_score"])},
      {"metadata.sharpness_loss_fraction",
       get_in(activity, ["metadata", "sharpness_loss_fraction"])}
    ]
    |> Enum.reject(fn {_field, value} -> feedback_value_missing?(value) end)
  end

  defp feedback_value_missing?(nil), do: true
  defp feedback_value_missing?(""), do: true
  defp feedback_value_missing?(_value), do: false

  defp invalid_realized_activity_feedback_identity_sections(activity) do
    activity
    |> realized_activity_feedback_identity_values()
    |> Enum.flat_map(fn {field, value} ->
      case raw_feedback_identifier(value) do
        nil ->
          []

        identifier ->
          if stable_id_string?(identifier) do
            []
          else
            [
              %{
                "field" => "realized_activities.#{field}",
                "key" => identifier,
                "reason" => "key_must_be_stable_id",
                "row_id" =>
                  raw_feedback_identifier(activity["id"]) ||
                    raw_feedback_identifier(activity["realized_activity_id"]) ||
                    raw_feedback_identifier(activity["activity_id"])
              }
              |> compact_map()
            ]
          end
      end
    end)
  end

  defp realized_activity_feedback_identity_values(activity) do
    [
      {"id", activity["id"]},
      {"realized_activity_id", activity["realized_activity_id"]},
      {"planned_activity_id", activity["planned_activity_id"]},
      {"activity_id", activity["activity_id"]},
      {"timeline_id", activity["timeline_id"]},
      {"metadata.timeline_id", get_in(activity, ["metadata", "timeline_id"])},
      {"scenario_id", activity["scenario_id"]},
      {"metadata.scenario_id", get_in(activity, ["metadata", "scenario_id"])},
      {"ground_station_id", activity["ground_station_id"]},
      {"station_id", activity["station_id"]},
      {"metadata.ground_station_id", get_in(activity, ["metadata", "ground_station_id"])},
      {"metadata.station_id", get_in(activity, ["metadata", "station_id"])},
      {"target_id", activity["target_id"]},
      {"metadata.target_id", get_in(activity, ["metadata", "target_id"])},
      {"spacecraft_id", activity["spacecraft_id"]},
      {"satellite_id", activity["satellite_id"]},
      {"metadata.spacecraft_id", get_in(activity, ["metadata", "spacecraft_id"])},
      {"resource_id", activity["resource_id"]},
      {"source_window_id", activity["source_window_id"]},
      {"metadata.source_window_id", get_in(activity, ["metadata", "source_window_id"])},
      {"target.id", nested_feedback_identifier(activity, "target", ["target_id", "id"])},
      {"station.id", nested_feedback_identifier(activity, "station", ["station_id", "id"])},
      {"ground_station.id",
       nested_feedback_identifier(activity, "ground_station", [
         "ground_station_id",
         "station_id",
         "id"
       ])},
      {"spacecraft.id",
       nested_feedback_identifier(activity, "spacecraft", ["spacecraft_id", "id"])},
      {"satellite.id", nested_feedback_identifier(activity, "satellite", ["satellite_id", "id"])},
      {"source_window.id",
       nested_feedback_identifier(activity, "source_window", ["source_window_id", "id"])}
    ]
  end

  defp nested_feedback_identifier(activity, object_key, identity_keys) do
    case Map.get(activity, object_key) do
      %{} = object -> Enum.find_value(identity_keys, &Map.get(object, &1))
      _value -> nil
    end
  end

  defp raw_feedback_identifier(nil), do: nil
  defp raw_feedback_identifier(value) when is_binary(value) and value != "", do: value
  defp raw_feedback_identifier(value) when is_atom(value), do: Atom.to_string(value)
  defp raw_feedback_identifier(value) when is_integer(value), do: Integer.to_string(value)
  defp raw_feedback_identifier(_value), do: nil

  defp realized_resource_margin_feedback(realized_activities) do
    realized_activities
    |> Enum.reduce(%{}, fn activity, feedback ->
      spacecraft_id = resource_feedback_spacecraft_id(activity)
      margins = realized_activity_resource_margins(activity)

      if spacecraft_id in [nil, ""] or margins == %{} do
        feedback
      else
        Map.update(feedback, spacecraft_id, margins, &merge_resource_margin_feedback(&1, margins))
      end
    end)
  end

  defp realized_activity_resource_margins(activity) do
    activity
    |> normalize_resource_margin_aliases()
    |> Map.take([
      "fuel_margin",
      "power_margin",
      "storage_margin",
      "downlink_margin",
      "thermal_margin_c",
      "battery_capacity_wh",
      "battery_energy_used_wh",
      "battery_state_of_charge"
    ])
    |> Enum.filter(fn {_field, value} -> is_number(value) end)
    |> Map.new(fn {field, value} -> {field, value * 1.0} end)
  end

  defp merge_resource_margin_feedback(existing, incoming) do
    Map.merge(existing, incoming, fn field, current, candidate ->
      merge_resource_margin_value(field, current, candidate)
    end)
  end

  defp merge_resource_margin_value("battery_energy_used_wh", current, candidate),
    do: max(current, candidate)

  defp merge_resource_margin_value(_field, current, candidate), do: min(current, candidate)

  defp realized_resource_availability_feedback(realized_activities) do
    realized_activities
    |> Enum.reduce(%{}, fn activity, feedback ->
      spacecraft_id = resource_feedback_spacecraft_id(activity)
      availability = realized_activity_resource_availability(activity)

      if spacecraft_id in [nil, ""] or availability == %{} do
        feedback
      else
        Map.update(
          feedback,
          spacecraft_id,
          availability,
          &merge_resource_availability_feedback(&1, availability)
        )
      end
    end)
  end

  defp realized_activity_resource_availability(activity) do
    activity
    |> normalize_resource_availability_aliases()
    |> Map.take([
      "payload_available",
      "antenna_available",
      "degraded",
      "spacecraft_available",
      "spacecraft_availability",
      "mode",
      "incompatible_activity_types",
      "suppressed_activity_types"
    ])
    |> Enum.reject(fn
      {_field, nil} -> true
      {_field, ""} -> true
      {_field, []} -> true
      {_field, _value} -> false
    end)
    |> Map.new()
  end

  defp merge_resource_availability_feedback(existing, incoming) do
    Map.merge(existing, incoming, fn
      field, current, candidate when field in ["payload_available", "antenna_available"] ->
        current != false and candidate != false

      field, current, candidate
      when field in ["spacecraft_available", "spacecraft_availability"] ->
        current != false and candidate != false

      "degraded", current, candidate ->
        truthy?(current) or truthy?(candidate)

      field, current, candidate
      when field in ["incompatible_activity_types", "suppressed_activity_types"] ->
        merge_string_lists(current, candidate)

      "mode", current, candidate ->
        degraded_mode_preference(current, candidate)

      _field, _current, candidate ->
        candidate
    end)
  end

  defp merge_string_lists(current, candidate) do
    [current, candidate]
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp degraded_mode_preference(current, candidate) do
    Enum.find([current, candidate], &(encode_value(&1) in ["safe", "degraded", "degraded_mode"])) ||
      candidate ||
      current
  end

  defp resource_feedback_spacecraft_id(activity) do
    [
      Map.get(activity, "spacecraft_id"),
      Map.get(activity, "scenario_id"),
      Map.get(activity, "resource_id"),
      get_in(activity, ["metadata", "spacecraft_id"]),
      get_in(activity, ["provenance", "spacecraft_id"])
    ]
    |> Enum.map(&encode_value/1)
    |> Enum.find(&(&1 not in [nil, ""]))
  end

  defp enrich_realized_activities_with_planned_context(realized_activities, prior_plan) do
    planned_by_feedback_key =
      prior_plan
      |> prior_activity_context_rows()
      |> Enum.flat_map(fn planned ->
        planned
        |> planned_feedback_context_keys()
        |> Enum.map(&{&1, planned})
      end)
      |> Enum.group_by(fn {key, _planned} -> key end, fn {_key, planned} -> planned end)
      |> Map.delete(nil)
      |> Map.delete("")

    Enum.map(realized_activities, fn realized ->
      planned = realized_feedback_context(realized, planned_by_feedback_key)

      planned
      |> Map.merge(realized)
      |> put_planned_feedback_activity_id(planned)
      |> put_realized_target_priority(realized)
    end)
  end

  defp put_realized_target_priority(activity, realized) do
    case declared_realized_target_priority(realized) do
      value when is_number(value) -> Map.put(activity, "__realized_target_priority", value)
      _value -> activity
    end
  end

  defp declared_realized_target_priority(activity) do
    [
      Map.get(activity, "realized_target_priority"),
      Map.get(activity, "target_priority"),
      get_in(activity, ["metadata", "target_priority"])
    ]
    |> Enum.find_value(&numeric_or_nil/1)
  end

  defp unique_prior_activity_context([planned]), do: planned
  defp unique_prior_activity_context(_matches), do: %{}

  defp realized_feedback_context(realized, planned_by_feedback_key) do
    realized
    |> realized_feedback_context_keys()
    |> Enum.find_value(%{}, fn key ->
      planned =
        planned_by_feedback_key
        |> Map.get(key, [])
        |> unique_prior_activity_context()

      if planned == %{}, do: nil, else: planned
    end)
  end

  defp put_planned_feedback_activity_id(activity, planned) when planned == %{}, do: activity

  defp put_planned_feedback_activity_id(activity, planned) do
    case planned_feedback_activity_id(planned) do
      nil -> activity
      id -> Map.put(activity, "__planned_feedback_activity_id", id)
    end
  end

  defp prior_activity_context_rows(prior_plan) do
    [
      prior_plan_activities(prior_plan),
      prior_plan_candidate_activities(prior_plan),
      prior_plan_proposed_contacts(prior_plan)
    ]
    |> List.flatten()
    |> Enum.map(&stringify_keys/1)
  end

  defp planned_feedback_context_keys(activity) do
    [
      Map.get(activity, "id"),
      Map.get(activity, "activity_id"),
      Map.get(activity, "planned_activity_id"),
      explicit_timeline_id(activity)
    ]
    |> feedback_identity_keys()
  end

  defp realized_feedback_context_keys(activity) do
    [
      Map.get(activity, "planned_activity_id"),
      Map.get(activity, "activity_id"),
      Map.get(activity, "id"),
      Map.get(activity, "realized_activity_id"),
      explicit_timeline_id(activity)
    ]
    |> feedback_identity_keys()
  end

  defp realized_feedback_activity_id(activity) do
    Map.get(activity, "__planned_feedback_activity_id") ||
      activity
      |> realized_feedback_context_keys()
      |> List.first()
  end

  defp planned_feedback_activity_id(activity) do
    activity
    |> planned_feedback_context_keys()
    |> List.first()
  end

  defp explicit_timeline_id(activity) do
    Map.get(activity, "timeline_id") || get_in(activity, ["metadata", "timeline_id"])
  end

  defp feedback_identity_keys(values) do
    values
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
  end

  defp realized_contact_feedback?(activity) do
    type = Map.get(activity, "type") || Map.get(activity, "activity_type")

    (type in ["downlink", "contact", "planned_contact"] or downlink_activity?(activity) or
       Map.has_key?(activity, "ground_station_id") or Map.has_key?(activity, "station_id")) and
      (not is_nil(contact_success_value(activity)) or
         not is_nil(station_throughput_value(activity)))
  end

  defp realized_observation_feedback?(activity) do
    type = Map.get(activity, "type") || Map.get(activity, "activity_type")

    type == "observe" and
      (Map.get(activity, "target_id") || Map.get(activity, "id")) not in [nil, ""] and
      (not is_nil(observation_success_value(activity)) or
         not is_nil(image_quality_score_value(activity)) or
         not is_nil(image_quality_status_value(activity)) or
         not is_nil(image_quality_source_value(activity)) or
         not is_nil(cloud_cover_fraction_value(activity)) or
         not is_nil(blur_score_value(activity)) or
         not is_nil(observation_downlink_demand_mb(activity)) or
         not is_nil(target_priority_override_value(activity)))
  end

  defp realized_maneuver_feedback?(activity) do
    type = Map.get(activity, "type") || Map.get(activity, "activity_type")

    (type in ["maneuver", "impulsive_burn"] or Map.has_key?(activity, "maneuver_success") or
       Map.has_key?(activity, "maneuver_result")) and
      realized_feedback_activity_id(activity) not in [nil, ""] and
      not is_nil(maneuver_success_value(activity))
  end

  defp realized_command_feedback?(activity) do
    command_activity?(activity) and
      realized_feedback_activity_id(activity) not in [nil, ""] and
      not is_nil(command_success_value(activity))
  end

  defp station_feedback_average(activities, value_fun) do
    activities
    |> Enum.group_by(&(Map.get(&1, "ground_station_id") || Map.get(&1, "station_id")))
    |> Enum.reject(fn {station_id, _activities} -> station_id in [nil, ""] end)
    |> Map.new(fn {station_id, station_activities} ->
      values =
        station_activities
        |> Enum.map(&weighted_feedback_value(&1, value_fun))
        |> Enum.reject(&is_nil/1)

      {station_id, average_feedback_value(values)}
    end)
    |> Enum.reject(fn {_station_id, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp target_feedback_average(activities, value_fun) do
    activities
    |> Enum.group_by(&Map.get(&1, "target_id"))
    |> Enum.reject(fn {target_id, _activities} -> target_id in [nil, ""] end)
    |> Map.new(fn {target_id, target_activities} ->
      values =
        target_activities
        |> Enum.map(&weighted_feedback_value(&1, value_fun))
        |> Enum.reject(&is_nil/1)

      {target_id, average_feedback_value(values)}
    end)
    |> Enum.reject(fn {_target_id, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp target_feedback_text(activities, value_fun) do
    activities
    |> Enum.group_by(&Map.get(&1, "target_id"))
    |> Enum.reject(fn {target_id, _activities} -> target_id in [nil, ""] end)
    |> Map.new(fn {target_id, target_activities} ->
      value =
        target_activities
        |> Enum.map(value_fun)
        |> Enum.map(&encode_value/1)
        |> Enum.reject(&(&1 in [nil, ""]))
        |> Enum.uniq()
        |> Enum.sort()
        |> List.first()

      {target_id, value}
    end)
    |> Enum.reject(fn {_target_id, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp target_priority_feedback_average(activities) do
    activities
    |> Enum.group_by(&Map.get(&1, "target_id"))
    |> Enum.reject(fn {target_id, _activities} -> target_id in [nil, ""] end)
    |> Map.new(fn {target_id, target_activities} ->
      values =
        target_activities
        |> Enum.map(fn activity ->
          weighted_feedback_value(activity, &target_priority_override_value/1)
        end)
        |> Enum.reject(&is_nil/1)

      {target_id, average_nonnegative_value(values)}
    end)
    |> Enum.reject(fn {_target_id, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp activity_feedback_average(activities, value_fun) do
    activities
    |> Enum.group_by(&realized_feedback_activity_id/1)
    |> Enum.reject(fn {activity_id, _activities} -> activity_id in [nil, ""] end)
    |> Map.new(fn {activity_id, activity_rows} ->
      values =
        activity_rows
        |> Enum.map(&weighted_feedback_value(&1, value_fun))
        |> Enum.reject(&is_nil/1)

      {activity_id, average_feedback_value(values)}
    end)
    |> Enum.reject(fn {_activity_id, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp average_feedback_value([]), do: nil

  defp average_feedback_value(weighted_values) do
    weighted_values
    |> weighted_average()
    |> clamp_unit_interval()
  end

  defp average_nonnegative_value([]), do: nil

  defp average_nonnegative_value(weighted_values) do
    weighted_values
    |> weighted_average()
    |> max(0.0)
  end

  defp weighted_feedback_value(activity, value_fun) do
    case {value_fun.(activity), usable_feedback_weight(activity)} do
      {value, weight} when is_number(value) and is_number(weight) and weight > 0.0 ->
        {value, weight}

      _value ->
        nil
    end
  end

  defp weighted_average(weighted_values) do
    {weighted_sum, total_weight} =
      Enum.reduce(weighted_values, {0.0, 0.0}, fn {value, weight}, {sum, total} ->
        {sum + value * weight, total + weight}
      end)

    weighted_sum / total_weight
  end

  defp feedback_weight(activity) do
    case declared_feedback_weight(activity) do
      {:ok, weight} -> weight
      :missing -> 1.0
    end
  end

  defp declared_feedback_weight(activity) do
    realized_feedback_weight_fields()
    |> Enum.find_value(:missing, fn field ->
      case nonnegative_number_status(Map.get(activity, field)) do
        {:ok, weight} -> {:ok, weight}
        _status -> false
      end
    end)
  end

  defp usable_feedback_weight(activity) do
    if invalid_realized_feedback_weight?(activity) do
      nil
    else
      feedback_weight(activity)
    end
  end

  defp invalid_realized_feedback_weight?(activity) do
    realized_feedback_weight_fields()
    |> Enum.any?(fn field ->
      case nonnegative_number_status(Map.get(activity, field)) do
        {:invalid_number, _number} -> true
        {:invalid_shape, _shape} -> true
        _status -> false
      end
    end)
  end

  defp contact_success_value(%{"contact_success" => value} = activity) do
