  defp observation_success_value(%{"realized_status" => status} = activity)
       when status in @realized_completion_statuses,
       do: completed_fraction_success_value(activity, 1.0)

  defp observation_success_value(%{"status" => status})
       when status in @realized_failure_statuses,
