  defp provider_result_success_value(result) do
    outcomes =
      result
      |> provider_result_values()
      |> Enum.map(&provider_result_token_success_value/1)
      |> Enum.reject(&(&1 == :unknown))

    cond do
      Enum.member?(outcomes, :failure) -> :failure
      Enum.member?(outcomes, :success) -> :success
      true -> :unknown
    end
  end

  defp provider_result_values(result) when is_binary(result) do
    result
    |> String.split(",", trim: true)
    |> Enum.map(&String.trim/1)
    |> Enum.reject(&(&1 == ""))
  end

  defp provider_result_values(values) when is_list(values) do
    Enum.flat_map(values, &provider_result_values/1)
  end

  defp provider_result_values(%{} = result) do
    Enum.flat_map(@provider_result_map_value_keys, fn key ->
      result
      |> Map.get(key)
      |> provider_result_values()
    end)
  end

  defp provider_result_values(nil), do: []

  defp provider_result_values(result) when is_atom(result) do
    result
    |> Atom.to_string()
    |> provider_result_values()
  end

  defp provider_result_values(_result), do: []

  defp provider_result_artifact_value(nil), do: nil

  defp provider_result_artifact_value(result) when is_binary(result) do
    case String.trim(result) do
      "" -> nil
      _value -> result
    end
  end

  defp provider_result_artifact_value(results) when is_list(results) do
    results
    |> provider_result_values()
    |> join_or_nil()
  end

  defp provider_result_artifact_value(%{} = result) do
    result
    |> provider_result_values()
    |> join_or_nil()
  end

  defp provider_result_artifact_value(result) when is_integer(result),
    do: Integer.to_string(result)

  defp provider_result_artifact_value(result) when is_float(result), do: Float.to_string(result)
  defp provider_result_artifact_value(result) when is_boolean(result), do: Atom.to_string(result)

  defp provider_result_artifact_value(result) when is_atom(result) do
    result
    |> Atom.to_string()
    |> provider_result_artifact_value()
  end

  defp provider_result_artifact_value(_result), do: nil

  defp provider_result_token_success_value(result) when is_binary(result) do
    case provider_result_token(result) do
      value
      when value in [
             "rejected",
             "failed",
             "failure",
             "timeout",
             "timed_out",
             "aborted",
             "error",
             "dropped",
             "lost",
             "missed",
             "canceled",
             "cancelled",
             "no_contact"
           ] ->
        :failure

      value
      when value in [
             "accepted",
             "acknowledged",
             "completed",
             "executed",
             "succeeded",
             "success",
             "ok",
             "acquired",
             "established",
             "delivered"
           ] ->
        :success

      _value ->
        :unknown
    end
  end

  defp provider_result_token(result) when is_binary(result) do
    result
    |> String.trim()
    |> String.downcase()
    |> String.replace(~r/[\s-]+/, "_")
  end

  defp completed_fraction_success_value(activity, default) do
    case unit_interval_number_status(Map.get(activity, "completed_fraction")) do
      {:ok, value} -> value
      :missing -> default
      _invalid -> nil
    end
  end

  defp station_throughput_value(activity) do
    actual = actual_contact_throughput_mb(activity)
    expected = expected_contact_throughput_mb(activity)

    if is_number(actual) and is_number(expected) and expected > 0 do
      actual
      |> Kernel./(expected)
      |> clamp_unit_interval()
    end
  end

  defp actual_contact_throughput_mb(activity) do
    first_numeric_activity_value(activity, [
      "actual_throughput_mb",
      "actual_downlink_mb",
      "actual_data_volume_mb",
      "delivered_data_mb",
      "received_data_mb",
      ["throughput_model", "actual_throughput_mb"],
      ["throughput_model", "actual_downlink_mb"],
      ["throughput_model", "actual_data_volume_mb"],
      ["throughput_model", "delivered_data_mb"],
      ["throughput_model", "received_data_mb"]
    ]) || actual_data_rate_contact_throughput_mb(activity)
  end

  defp actual_data_rate_contact_throughput_mb(activity) do
    duration_s = actual_contact_duration_s(activity)

    cond do
      not is_number(duration_s) or duration_s <= 0.0 ->
        nil

      rate_mb_s = actual_contact_data_rate_mb_s(activity) ->
        rate_mb_s * duration_s

      rate_mbps = actual_contact_data_rate_mbps(activity) ->
        rate_mbps * duration_s / 8.0

      true ->
        nil
    end
  end

  defp actual_contact_data_rate_mb_s(activity) do
    first_numeric_activity_value(activity, [
      "actual_data_rate_mb_s",
      "actual_downlink_rate_mb_s",
      "delivered_rate_mb_s",
      "received_rate_mb_s",
      ["throughput_model", "actual_data_rate_mb_s"],
      ["throughput_model", "actual_downlink_rate_mb_s"],
      ["throughput_model", "delivered_rate_mb_s"],
      ["throughput_model", "received_rate_mb_s"]
    ])
  end

  defp actual_contact_data_rate_mbps(activity) do
    first_numeric_activity_value(activity, [
      "actual_data_rate_mbps",
      "actual_downlink_rate_mbps",
      "delivered_rate_mbps",
      "received_rate_mbps",
      ["throughput_model", "actual_data_rate_mbps"],
      ["throughput_model", "actual_downlink_rate_mbps"],
      ["throughput_model", "delivered_rate_mbps"],
      ["throughput_model", "received_rate_mbps"]
    ])
  end

  defp actual_contact_duration_s(activity) do
    first_numeric_activity_value(activity, [
      "actual_duration_s",
      "actual_contact_duration_s",
      "contact_duration_s",
      "duration_s",
      ["throughput_model", "actual_duration_s"],
      ["throughput_model", "actual_contact_duration_s"],
      ["throughput_model", "contact_duration_s"],
      ["throughput_model", "duration_s"]
    ]) || actual_contact_interval_duration_s(activity)
  end

  defp actual_contact_interval_duration_s(activity) do
    start_s =
      first_numeric_activity_value(activity, [
        "actual_starts_at_s",
        "actual_start_s",
        "starts_at_s",
        "start_s"
      ])

    end_s =
      first_numeric_activity_value(activity, [
        "actual_ends_at_s",
        "actual_end_s",
        "ends_at_s",
        "end_s"
      ])

    if is_number(start_s) and is_number(end_s) and end_s > start_s do
      end_s - start_s
    end
  end

  defp expected_contact_throughput_mb(activity) do
    first_numeric_activity_value(activity, [
      "estimated_throughput_mb",
      "planned_throughput_mb",
      "estimated_downlink_mb",
      "required_downlink_mb",
      ["throughput_model", "estimated_throughput_mb"],
      ["throughput_model", "planned_throughput_mb"],
      ["throughput_model", "estimated_downlink_mb"],
      ["throughput_model", "required_downlink_mb"]
    ])
  end

  defp observation_downlink_demand_feedback(activities) do
    demand_mb =
      activities
      |> Enum.map(fn activity ->
        case {observation_downlink_demand_mb(activity), usable_feedback_weight(activity)} do
          {value, weight} when is_number(value) and value > 0.0 and is_number(weight) ->
            value * weight

          _value ->
            nil
        end
      end)
      |> Enum.reject(&is_nil/1)
      |> Enum.sum()

    if demand_mb > 0.0, do: %{"default" => demand_mb}, else: %{}
  end

  defp observation_downlink_demand_sources(activities) do
    activities
    |> Enum.reduce(%{}, fn activity, sources ->
      case {observation_downlink_demand_mb(activity), usable_feedback_weight(activity)} do
        {value, weight} when is_number(value) and value > 0.0 and is_number(weight) ->
          weighted_value = value * weight
          activity_sources = realized_downlink_demand_sources(activity, "observation")

          if weighted_value > 0.0 and activity_sources != [] do
            Map.update(sources, "default", activity_sources, fn existing ->
              merge_downlink_demand_source_values(existing, activity_sources)
            end)
          else
            sources
          end

        _value ->
          sources
      end
    end)
  end

  defp observation_downlink_demand_mb(activity) do
    actual_data_volume_mb =
      first_numeric_activity_value(activity, [
        "actual_data_volume_mb",
        "actual_storage_mb",
        "actual_downlink_mb",
        "delivered_data_mb",
        "received_data_mb"
      ])

    planned_data_volume_mb =
      first_numeric_activity_value(activity, [
        "planned_data_volume_mb",
        "data_volume_mb",
        "estimated_data_volume_mb",
        "estimated_storage_mb",
        "estimated_downlink_mb"
      ])

    completed_fraction = unit_interval_number_or_nil(activity["completed_fraction"])

    cond do
      is_number(actual_data_volume_mb) ->
        max(actual_data_volume_mb, 0.0)

      is_number(planned_data_volume_mb) and is_number(completed_fraction) ->
        max(planned_data_volume_mb, 0.0) * completed_fraction

      true ->
        nil
    end
  end

  defp first_numeric_activity_value(activity, keys) do
    Enum.find_value(keys, fn key ->
      value =
        case key do
          path when is_list(path) -> get_in(activity, path)
          key -> Map.get(activity, key)
        end

      case numeric_or_nil(value) do
        value when is_number(value) -> value
        _value -> nil
      end
    end)
  end

  defp first_unit_interval_activity_value(activity, keys) do
    Enum.find_value(keys, fn key ->
      value =
        case key do
          path when is_list(path) -> get_in(activity, path)
          key -> Map.get(activity, key)
        end

      unit_interval_number_or_nil(value)
    end)
  end

  defp unit_interval_number_or_nil(value) do
    case unit_interval_number_status(value) do
      {:ok, number} -> number
      _value -> nil
    end
  end

  defp unit_interval_number_status(value) do
    case numeric_or_nil(value) do
      number when is_number(number) and number >= 0.0 and number <= 1.0 ->
        {:ok, number * 1.0}

      number when is_number(number) ->
        {:invalid_number, number}

      _value ->
        if feedback_value_missing?(value), do: :missing, else: {:invalid_shape, value}
    end
  end

  defp nonnegative_number_status(value) do
    case numeric_or_nil(value) do
      number when is_number(number) and number >= 0.0 ->
        {:ok, number * 1.0}

      number when is_number(number) ->
        {:invalid_number, number}

      _value ->
        if feedback_value_missing?(value), do: :missing, else: {:invalid_shape, value}
    end
  end

  defp first_string_activity_value(activity, keys) do
    Enum.find_value(keys, fn key ->
      value =
        case key do
          path when is_list(path) -> get_in(activity, path)
          key -> Map.get(activity, key)
        end

      case encode_value(value) do
        value when is_binary(value) and value != "" -> value
        _value -> nil
      end
    end)
  end

  defp station_downlink_demand_feedback(activities) do
    activities
    |> Enum.reduce(%{}, fn activity, demands ->
      if downlink_activity?(activity) do
        station_id = Map.get(activity, "ground_station_id") || Map.get(activity, "station_id")

        case {realized_downlink_demand_mb(activity), usable_feedback_weight(activity)} do
          {demand_mb, weight}
          when is_number(demand_mb) and demand_mb > 0.0 and is_number(weight) ->
            weighted_demand_mb = demand_mb * weight

            if weighted_demand_mb > 0.0 do
              Map.update(
                demands,
                station_id || "default",
                weighted_demand_mb,
                &(&1 + weighted_demand_mb)
              )
            else
              demands
            end

          _demand ->
            demands
        end
      else
        demands
      end
    end)
    |> Enum.sort_by(fn {station_id, _demand_mb} -> station_id end)
    |> Map.new()
  end

  defp station_downlink_demand_sources(activities) do
    activities
    |> Enum.reduce(%{}, fn activity, sources ->
      if downlink_activity?(activity) do
        station_id = Map.get(activity, "ground_station_id") || Map.get(activity, "station_id")

        case {realized_downlink_demand_mb(activity), usable_feedback_weight(activity)} do
          {demand_mb, weight}
          when is_number(demand_mb) and demand_mb > 0.0 and is_number(weight) ->
            weighted_demand_mb = demand_mb * weight
            activity_sources = realized_downlink_demand_sources(activity, "contact")

            if weighted_demand_mb > 0.0 and activity_sources != [] do
              Map.update(sources, station_id || "default", activity_sources, fn existing ->
                merge_downlink_demand_source_values(existing, activity_sources)
              end)
            else
              sources
            end

          _demand ->
            sources
        end
      else
        sources
      end
    end)
    |> Enum.sort_by(fn {station_id, _sources} -> station_id end)
    |> Map.new()
  end

  defp realized_downlink_demand_sources(activity, kind) do
    [
      realized_downlink_demand_primary_source(activity, kind),
      activity["realized_activity_id"] &&
        "mission_state.realized_activities.realized_activity:#{activity["realized_activity_id"]}"
    ]
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp realized_downlink_demand_primary_source(activity, kind) do
    case activity["id"] || activity["activity_id"] do
      id when id not in [nil, ""] ->
        "mission_state.realized_activities.#{kind}.required_downlink_mb:#{id}"

      _id ->
        nil
    end
  end

  defp realized_downlink_demand_mb(
         %{"required_downlink_mb" => raw_required_downlink_mb} = activity
       ) do
    case numeric_or_nil(raw_required_downlink_mb) do
      required_downlink_mb when is_number(required_downlink_mb) and required_downlink_mb > 0.0 ->
        actual_throughput_mb = actual_contact_throughput_mb(activity)
        completed_fraction = unit_interval_number_or_nil(activity["completed_fraction"])

        cond do
          is_number(actual_throughput_mb) ->
            max(required_downlink_mb - actual_throughput_mb, 0.0)

          is_number(completed_fraction) ->
            required_downlink_mb * (1.0 - completed_fraction)

          provider_downlink_failure_result?(activity) ->
            required_downlink_mb

          provider_downlink_success_result?(activity) ->
            nil

          activity["realized_status"] in ["delayed", "partial" | @realized_failure_statuses] ->
            required_downlink_mb

          activity["realized_status"] in @realized_completion_statuses ->
            nil

          activity["status"] in ["delayed", "partial" | @realized_failure_statuses] ->
            required_downlink_mb

          activity["contact_success"] == false ->
            required_downlink_mb

          true ->
            nil
        end

      _required_downlink_mb ->
        nil
    end
  end

  defp realized_downlink_demand_mb(_activity), do: nil

  defp provider_downlink_failure_result?(%{"contact_result" => result}),
    do: provider_result_failure_value?(result)

  defp provider_downlink_failure_result?(_activity), do: false

  defp provider_downlink_success_result?(%{"contact_result" => result}),
    do: provider_result_success_value(result) == :success

  defp provider_downlink_success_result?(_activity), do: false

  defp provider_result_failure_value?(result),
    do: provider_result_success_value(result) == :failure

  defp merge_downlink_demand_feedback(left, right) do
    Map.merge(left, right, fn _key, left_value, right_value -> left_value + right_value end)
  end

  defp merge_downlink_demand_source_feedback(left, right) do
    Map.merge(left, right, fn _key, left_sources, right_sources ->
      merge_downlink_demand_source_values(left_sources, right_sources)
    end)
  end

  defp merge_downlink_demand_source_values(left, right) do
    left
    |> List.wrap()
    |> Kernel.++(List.wrap(right))
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp merge_operational_feedback(derived, explicit) do
    derived = normalize_operational_feedback(derived)
    explicit = normalize_operational_feedback(explicit)

    Map.new(derived, fn {key, derived_values} ->
      {key, Map.merge(derived_values, Map.get(explicit, key, %{}))}
    end)
  end

  defp clamp_unit_interval(value), do: value |> max(0.0) |> min(1.0)

  defp strategy_policy_to_map(%StrategicScoringPolicy{} = policy) do
    policy
    |> Map.from_struct()
    |> Map.new(fn {key, value} -> {to_string(key), value} end)
  end

  defp approval_policy_to_map(%ApprovalPolicy{} = policy) do
    policy
    |> Map.from_struct()
    |> Map.new(fn {key, value} -> {to_string(key), value} end)
  end

  defp plan_branch_to_map(%PlanBranch{} = branch) do
    branch_map = %{
      "branch_id" => branch.id,
      "label" => branch.label,
      "probability" => branch.probability,
      "events" => branch.events,
      "candidate_plan" => branch.candidate_plan,
      "repair_result" => branch.repair_result,
      "score" => branch.score,
      "score_terms" => branch.score_terms,
      "warnings" => branch.warnings,
      "risk_indicators" => branch.risk_indicators,
      "approval_status" => branch.approval_status,
      "approval_requirements" => branch.approval_requirements,
      "approval_rule_matches" => branch.approval_rule_matches,
      "policy_decision" => branch.policy_decision,
      "derived_source" => branch.derived_source,
      "resource_impacts" => branch.resource_impacts,
      "feedback_adjustments" => branch.feedback_adjustments,
      "objective_satisfaction" => branch.objective_satisfaction,
      "feasibility_summary" => branch.feasibility_summary,
      "assumptions" => branch.assumptions,
      "provenance" => branch.provenance,
      "tradeoffs" => branch.tradeoffs
    }

    case branch.resource_projection_report do
      nil -> branch_map
      report -> Map.put(branch_map, "resource_projection_report", report)
    end
  end

  defp strategy_recommendation_to_map(%StrategyRecommendation{} = recommendation) do
    %{
      "schema_contract" => "strategy_recommendation.v1",
      "status" => "pass",
      "recommended_branch_id" => recommendation.recommended_branch_id,
      "approval_status" => recommendation.approval_status,
      "reason" => recommendation.reason,
      "ranked_branch_ids" => recommendation.ranked_branch_ids,
      "tradeoffs" => recommendation.tradeoffs,
      "explanation" => recommendation.explanation,
      "risks_remaining" => recommendation.risks_remaining,
      "requires_approval" => recommendation.requires_approval
    }
  end

  defp branch_comparison_report(branches, %StrategyRecommendation{} = recommendation) do
    recommended_score =
      branches
      |> Enum.find(&(&1.id == recommendation.recommended_branch_id))
      |> case do
        nil -> 0.0
        branch -> branch.score
      end

    rows =
      branches
      |> Enum.with_index(1)
      |> Enum.map(fn {branch, rank} ->
        %{
          "id" => "branch_comparison:#{branch.id}",
          "rank" => rank,
          "branch_id" => branch.id,
          "score" => branch.score,
          "score_delta_from_recommended" => branch.score - recommended_score,
          "raw_score" => Map.get(branch.score_terms, "raw_score"),
          "branch_probability" => branch.probability,
          "expected_score" => Map.get(branch.score_terms, "expected_score", branch.score),
          "selected" => branch.id == recommendation.recommended_branch_id,
          "approval_status" => branch.approval_status,
          "risk_count" => length(branch.risk_indicators),
          "risk_types" => branch_risk_types(branch.risk_indicators),
          "high_risk_types" => branch_risk_types(branch.risk_indicators, "high"),
          "approval_requirement_count" => length(branch.approval_requirements),
          "candidate_activity_count" =>
            branch.candidate_plan |> Map.get("strategic_additions", []) |> length(),
          "repair_delta_count" => branch.repair_result |> Map.get("deltas", []) |> length(),
          "score_terms" => branch.score_terms
        }
        |> Map.merge(branch_comparison_objective_fields(branch.objective_satisfaction))
        |> Map.merge(branch_comparison_feedback_fields(branch.feedback_adjustments))
        |> Map.merge(branch_comparison_resource_fields(branch.resource_impacts))
        |> Map.merge(branch_comparison_repair_fields(branch.repair_result))
        |> Map.merge(branch_comparison_event_fields(branch))
        |> Map.merge(branch_comparison_risk_fields(branch.risk_indicators))
        |> Map.merge(branch_comparison_target_branch_fields(branch))
        |> Map.merge(
          branch_comparison_resource_projection_fields(branch.resource_projection_report)
        )
      end)

    %{
      "schema_contract" => "branch_comparison_report.v1",
      "model" => "deterministic_strategy_branch_score_comparison",
      "source" => "campaign_strategy.branches",
      "branch_count" => length(branches),
      "recommended_branch_id" => recommendation.recommended_branch_id,
      "model_limits" => @branch_comparison_model_limits,
      "rows" => rows,
      "assumptions" => %{
        "branch_order" => "score_descending_then_branch_id",
        "score_delta_from_recommended" => "row_score_minus_recommended_branch_score",
        "score" => "probability_weighted_expected_score",
        "raw_score" => "score_before_branch_probability_multiplier",
        "branch_probability" => "independent branch likelihood or confidence multiplier in [0,1]",
        "expected_score" => "raw_score_times_branch_probability_times_probability_weight",
        "blocked_branches_remain_visible" => true
      }
    }
  end

  defp branch_risk_types(risk_indicators, severity \\ nil) do
    risk_indicators
    |> List.wrap()
    |> Enum.filter(fn risk -> is_nil(severity) or Map.get(risk, "severity") == severity end)
    |> Enum.map(&Map.get(&1, "type"))
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp branch_comparison_event_fields(%PlanBranch{events: events}) do
    event_types =
      events
      |> Enum.map(&Map.get(&1, "type"))
      |> Enum.map(&encode_value/1)
      |> Enum.filter(&(is_binary(&1) and &1 != ""))
      |> Enum.uniq()
      |> Enum.sort()

    source_branch_ids =
      events
      |> Enum.flat_map(fn event ->
        event
        |> Map.get("source_branch_ids", List.wrap(Map.get(event, "source_branch_id")))
        |> List.wrap()
      end)
      |> Enum.map(&encode_value/1)
      |> Enum.filter(&(is_binary(&1) and &1 != ""))
      |> Enum.uniq()
      |> Enum.sort()

    fields = %{
      "branch_event_count" => length(events),
      "branch_event_types" => event_types,
      "branch_event_trust_boundary_status_counts" =>
        branch_event_trust_boundary_status_counts(events),
      "branch_station_availabilities" => branch_event_station_availabilities(events),
      "branch_station_contention_statuses" =>
        branch_event_unique_values(events, ["station_contention_status", "contention_status"]),
      "branch_ground_station_ids" =>
        branch_event_unique_values(events, ["ground_station_id", "station_id"]),
      "branch_scenario_ids" => branch_event_unique_values(events, "scenario_id"),
      "branch_target_ids" => branch_event_unique_values(events, "target_id"),
      "branch_collection_ids" =>
        branch_event_unique_values(events, ["collection_id", "collection_ids"]),
      "branch_product_ids" => branch_event_unique_values(events, ["product_id", "product_ids"]),
      "branch_payload_ids" => branch_event_unique_values(events, ["payload_id", "payload_ids"]),
      "branch_instrument_ids" =>
        branch_event_unique_values(events, ["instrument_id", "instrument_ids"]),
      "branch_objective_ids" =>
        branch_event_unique_values(events, ["objective_id", "objective_ids"]),
      "branch_objective_types" => branch_event_unique_values(events, "objective_type"),
      "branch_objective_statuses" => branch_event_unique_values(events, "objective_status"),
      "branch_source_objective_statuses" =>
        branch_event_unique_values(events, "source_objective_status"),
      "branch_feedback_sources" => branch_event_unique_values(events, "feedback_source"),
      "branch_feedback_scopes" => branch_event_unique_values(events, "feedback_scope"),
      "branch_contact_results" => branch_event_unique_values(events, "contact_result"),
      "branch_contact_allocation_statuses" =>
        branch_event_unique_values(events, "allocation_status"),
      "branch_contact_allocation_effective_statuses" =>
        branch_event_unique_values(events, "effective_allocation_status"),
      "branch_contact_allocation_reasons" =>
        branch_event_unique_values(events, "allocation_reason"),
      "branch_contact_allocation_review_statuses" =>
        branch_event_unique_values(events, "review_status"),
      "branch_contact_allocation_approval_statuses" =>
        branch_event_unique_values(events, "approval_status"),
      "branch_contact_allocation_policy_classifications" =>
        branch_event_unique_values(events, "policy_classification"),
      "branch_realized_statuses" => branch_event_unique_values(events, "realized_status"),
      "branch_transition_types" => branch_event_transition_values(events, "transition_type"),
      "branch_transition_categories" =>
        branch_event_transition_values(events, "transition_category"),
      "branch_transition_reasons" => branch_event_transition_values(events, "transition_reason"),
      "branch_requires_operator_review" => branch_event_requires_operator_review(events),
      "branch_requires_operator_review_count" => branch_event_operator_review_count(events),
      "branch_operational_readiness_levels" =>
        branch_operational_readiness_unique_values(events, "readiness_level"),
      "branch_operational_readiness_import_classifications" =>
        branch_operational_readiness_unique_values(events, "import_classification"),
      "branch_operational_readiness_statuses" =>
        branch_operational_readiness_unique_values(events, "operational_readiness_status"),
      "branch_operational_readiness_gate_ids" =>
        branch_operational_readiness_unique_values(events, "readiness_gate_id"),
      "branch_operational_readiness_gate_statuses" =>
        branch_operational_readiness_unique_values(events, "readiness_gate_status"),
      "branch_operational_readiness_gate_classifications" =>
        branch_operational_readiness_unique_values(events, "readiness_gate_classification"),
      "branch_operational_readiness_review_required_gate_ids" =>
        branch_operational_readiness_unique_values(events, "review_required_gate_ids"),
      "branch_operational_readiness_analysis_only_gate_ids" =>
        branch_operational_readiness_unique_values(events, "analysis_only_gate_ids"),
      "branch_operational_readiness_blocked_gate_ids" =>
        branch_operational_readiness_unique_values(events, "blocked_gate_ids"),
      "branch_operational_readiness_non_passed_gate_ids" =>
        branch_operational_readiness_unique_values(events, "non_passed_gate_ids"),
      "branch_missed_downlink_activity_ids" =>
        branch_event_unique_values(events, [
          "missed_downlink_activity_id",
          "missed_downlink_activity_ids"
        ]),
      "branch_maneuver_execution_uncertainty_activity_ids" =>
        branch_maneuver_execution_uncertainty_unique_values(events, "activity_id"),
      "branch_maneuver_execution_uncertainty_timeline_ids" =>
        branch_maneuver_execution_uncertainty_unique_values(events, "timeline_id"),
      "branch_maneuver_execution_uncertainty_maneuver_ids" =>
        branch_maneuver_execution_uncertainty_unique_values(events, "maneuver_id"),
      "branch_maneuver_execution_uncertainty_statuses" =>
        branch_maneuver_execution_uncertainty_unique_values(
          events,
          "execution_uncertainty_status"
        ),
      "branch_maneuver_execution_uncertainty_sources" =>
        branch_maneuver_execution_uncertainty_unique_values(
          events,
          "execution_uncertainty_source"
        ),
      "branch_maneuver_execution_uncertainty_max_timing_3sigma_s" =>
        branch_maneuver_execution_uncertainty_maximum_present(events, "timing_3sigma_s"),
      "branch_maneuver_execution_uncertainty_max_delta_v_3sigma_magnitude_km_s" =>
        branch_maneuver_execution_uncertainty_maximum_present(
          events,
          "delta_v_3sigma_magnitude_km_s"
        ),
