  defp branch_comparison_target_branch_fields(%PlanBranch{provenance: provenance}) do
    metadata = get_in(provenance, ["branch_metadata"]) || %{}

    %{
      "target_branch_base_id" => Map.get(metadata, "target_branch_base_id"),
      "target_branch_identity" => Map.get(metadata, "target_branch_identity")
    }
    |> compact_map()
  end

  defp branch_event_trust_boundary_status_counts([]), do: %{}

  defp branch_event_trust_boundary_status_counts(events) do
    events
    |> Enum.map(&branch_event_trust_boundary_status/1)
    |> Enum.frequencies()
  end

  defp branch_event_trust_boundary_status(%{} = event) do
    case branch_event_trust_boundary(event) do
      trust_boundary when is_binary(trust_boundary) and trust_boundary != "" -> "declared"
      _trust_boundary -> "missing"
    end
  end

  defp branch_event_trust_boundary_status(_event), do: "missing"

  defp branch_event_trust_boundary(%{} = event) do
    [Map.get(event, "trust_boundary"), get_in(event, ["provenance", "trust_boundary"])]
    |> Enum.map(&encode_value/1)
    |> Enum.find(&(is_binary(&1) and &1 != ""))
  end

  defp branch_event_trust_boundary(_event), do: nil

  defp branch_event_unique_values(events, field) when is_binary(field) do
    branch_event_unique_values(events, [field])
  end

  defp branch_event_unique_values(events, fields) when is_list(fields) do
    events
    |> Enum.flat_map(fn event ->
      Enum.map(fields, &Map.get(event, &1))
    end)
    |> Enum.flat_map(&List.wrap/1)
    |> Enum.map(&encode_value/1)
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp branch_station_reservation_conflict_unique_values(events, fields) do
    events
    |> Enum.filter(&station_reservation_conflict_event?/1)
    |> branch_event_unique_values(fields)
  end

  defp branch_station_reservation_conflict_match_statuses(events, fields) do
    events
    |> Enum.filter(&station_reservation_conflict_event?/1)
    |> branch_event_unique_values(fields)
    |> Enum.filter(&station_reservation_conflict_match_status?/1)
  end

  defp station_reservation_conflict_event?(event) do
    [event]
    |> branch_event_unique_values([
      "station_reservation_match_status",
      "reservation_match_status"
    ])
    |> Enum.any?(&station_reservation_conflict_match_status?/1)
  end

  defp station_reservation_conflict_match_status?(status) do
    status
    |> normalized_status_token()
    |> case do
      nil -> false
      "" -> false
      "matched" -> false
      "owner_matched" -> false
      "owned" -> false
      "owner" -> false
      _status -> true
    end
  end

  defp branch_event_requires_operator_review(events) do
    values =
      events
      |> Enum.map(&branch_event_operator_review_value/1)
      |> Enum.filter(&is_boolean/1)

    cond do
      Enum.any?(values, &(&1 == true)) -> true
      values != [] -> false
      true -> nil
    end
  end

  defp branch_event_operator_review_count(events) do
    count =
      events
      |> Enum.count(&(branch_event_operator_review_value(&1) == true))

    if count > 0, do: count
  end

  defp branch_event_transition_values(events, field) do
    events
    |> Enum.flat_map(fn event ->
      [Map.get(event, field), get_in(event, ["status_transition", field])]
    end)
    |> Enum.flat_map(&List.wrap/1)
    |> Enum.map(&encode_value/1)
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp branch_event_operator_review_value(event) do
    [
      Map.get(event, "requires_operator_review"),
      get_in(event, ["status_transition", "requires_operator_review"])
    ]
    |> Enum.map(&json_boolean_value/1)
    |> Enum.find(&is_boolean/1)
  end

  defp branch_event_station_availabilities(events) do
    events
    |> Enum.map(fn
      %{"station_availability" => availability} ->
        availability

      %{"availability" => availability} ->
        availability

      %{"type" => "ground_station_outage"} ->
        "unavailable"

      %{"type" => "ground_station_reserved"} ->
        "reserved"

      _event ->
        nil
    end)
    |> Enum.map(&encode_value/1)
    |> Enum.filter(&(is_binary(&1) and &1 != ""))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp maybe_put_combined_source_branch_ids(fields, []), do: fields

  defp maybe_put_combined_source_branch_ids(fields, source_branch_ids) do
    Map.put(fields, "combined_source_branch_ids", source_branch_ids)
  end

  defp maybe_put_nonempty(fields, key) do
    case Map.get(fields, key) do
      value when value in [%{}, [], nil] -> Map.delete(fields, key)
      _value -> fields
    end
  end

  defp branch_ranking_comparison_report(input_order_branches, score_ranked_branches) do
    Optimizer.ranking_comparison_report(
      Enum.map(input_order_branches, &branch_ranking_row/1),
      Enum.map(score_ranked_branches, &branch_ranking_row/1),
      source: "campaign_strategy.branch_comparison_report",
      objective: "strategy_branch_score",
      objective_direction: "maximize",
      left_label: "normalized_branch_order",
      right_label: "score_ranked_branches"
    )
  end

  defp branch_ranking_row(branch) do
    %{
      scenario_id: branch.id,
      objective: "strategy_branch_score",
      value: branch.score
    }
  end

  defp branch_pareto_frontier_report(%{"rows" => rows}) do
    rows
    |> Enum.map(&branch_pareto_objective_row/1)
    |> Optimizer.pareto_frontier_report(
      source: "campaign_strategy.branch_comparison_report",
      objective_directions: branch_pareto_objective_directions()
    )
  end

  defp branch_pareto_objective_row(%{} = row) do
    branch_id = Map.get(row, "branch_id")

    %{
      "id" => branch_id,
      "scenario_id" => branch_id,
      "objectives" =>
        row
        |> Map.take(Map.keys(branch_pareto_objective_directions()))
        |> Enum.filter(fn {_key, value} -> is_number(value) end)
        |> Map.new()
    }
  end

  defp branch_pareto_objective_directions do
    %{
      "score" => "maximize",
      "raw_score" => "maximize",
      "expected_score" => "maximize",
      "risk_count" => "minimize",
      "approval_requirement_count" => "minimize",
      "repair_delta_count" => "minimize",
      "collection_latency_ratio" => "maximize",
      "collection_latency_unsatisfied_observation_count" => "minimize",
      "projected_storage_margin" => "maximize",
      "projected_storage_remaining_mb" => "maximize",
      "projected_downlink_margin" => "maximize",
      "projected_downlink_remaining_mb" => "maximize",
      "projected_power_margin" => "maximize",
      "projected_battery_overuse_wh" => "minimize",
      "resource_projection_peak_storage_overflow_mb" => "minimize",
      "resource_projection_peak_downlink_shortfall_mb" => "minimize",
      "resource_projection_peak_battery_overuse_wh" => "minimize",
      "resource_projection_peak_unused_downlink_capacity_mb" => "minimize",
      "downlink_completion_ratio" => "maximize",
      "priority_commitment_satisfied_target_count" => "maximize",
      "priority_commitment_missed_target_count" => "minimize",
      "coverage_observed_target_count" => "maximize",
      "revisit_count" => "maximize",
      "repair_constraint_warning_count" => "minimize",
      "repair_constraint_fail_count" => "minimize"
