      "repair_constraint_warning_ids" => constraint_ids_for_status(constraint_report, "warning")
    }
    |> compact_map()
  end

  defp constraint_status_count(report, status) do
    report
    |> Map.get("rows", [])
    |> Enum.count(&(Map.get(&1, "status") == status))
  end

  defp constraint_ids_for_status(report, status) do
    report
    |> Map.get("rows", [])
    |> Enum.filter(&(Map.get(&1, "status") == status))
    |> Enum.map(&Map.get(&1, "constraint_id"))
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp branch_comparison_resource_projection_fields(nil), do: %{}

  defp branch_comparison_resource_projection_fields(report) do
    rows = Map.get(report, "projected_resources", [])
    unavailable_spacecraft_ids = resource_projection_unavailable_spacecraft_ids(rows)

    payload_unavailable_ids =
      resource_projection_availability_pressure_spacecraft_ids(rows, "payload_unavailable")

    degraded_payload_unavailable_ids =
      resource_projection_availability_pressure_spacecraft_ids(
        rows,
        "spacecraft_degraded_payload_unavailable"
      )

    antenna_unavailable_ids =
      resource_projection_availability_pressure_spacecraft_ids(rows, "antenna_unavailable")

    activity_type_suppressed_ids =
      resource_projection_availability_pressure_spacecraft_ids(
        rows,
        "activity_type_suppressed_by_resource_summary"
      )

    activity_type_incompatible_ids =
      resource_projection_availability_pressure_spacecraft_ids(
        rows,
        "activity_type_incompatible_with_resource_summary"
      )

    availability_pressure_types = resource_projection_availability_pressure_types(rows)
    first_pressure = first_resource_projection_pressure(rows)

    if rows == [] do
      %{}
    else
      %{
        "resource_projection_spacecraft_count" => length(rows),
        "resource_projection_unavailable_spacecraft_count" => length(unavailable_spacecraft_ids),
        "resource_projection_unavailable_spacecraft_ids" => unavailable_spacecraft_ids,
        "resource_projection_payload_unavailable_count" => length(payload_unavailable_ids),
        "resource_projection_payload_unavailable_spacecraft_ids" => payload_unavailable_ids,
        "resource_projection_degraded_payload_unavailable_count" =>
          length(degraded_payload_unavailable_ids),
        "resource_projection_degraded_payload_unavailable_spacecraft_ids" =>
          degraded_payload_unavailable_ids,
        "resource_projection_antenna_unavailable_count" => length(antenna_unavailable_ids),
        "resource_projection_antenna_unavailable_spacecraft_ids" => antenna_unavailable_ids,
        "resource_projection_activity_type_suppressed_count" =>
          length(activity_type_suppressed_ids),
        "resource_projection_activity_type_suppressed_spacecraft_ids" =>
          activity_type_suppressed_ids,
        "resource_projection_activity_type_incompatible_count" =>
          length(activity_type_incompatible_ids),
        "resource_projection_activity_type_incompatible_spacecraft_ids" =>
          activity_type_incompatible_ids,
        "resource_projection_availability_pressure_types" => availability_pressure_types,
        "projected_storage_margin" => minimum_present(rows, "projected_storage_margin"),
        "projected_storage_remaining_mb" =>
          minimum_projected_remaining(
            rows,
            "projected_storage_remaining_mb",
            "storage_capacity_mb",
            "projected_storage_used_mb"
          ),
        "projected_downlink_margin" => minimum_present(rows, "projected_downlink_margin"),
        "projected_downlink_remaining_mb" =>
          minimum_projected_remaining(
            rows,
            "projected_downlink_remaining_mb",
            "downlink_capacity_mb",
            "estimated_downlink_mb"
          ),
        "projected_power_margin" => minimum_present(rows, "projected_power_margin"),
        "projected_storage_overflow_mb" => maximum_present(rows, "projected_storage_overflow_mb"),
        "projected_downlink_shortfall_mb" =>
          maximum_present(rows, "projected_downlink_shortfall_mb"),
        "projected_battery_overuse_wh" => maximum_present(rows, "projected_battery_overuse_wh"),
        "storage_limited_downlinked_mb" => maximum_present(rows, "storage_limited_downlinked_mb"),
        "unused_downlink_capacity_mb" => maximum_present(rows, "unused_downlink_capacity_mb"),
        "resource_projection_flow_count" => resource_projection_flow_count(rows),
        "resource_projection_peak_storage_overflow_mb" =>
          peak_resource_projection_flow_value(rows, "storage_overflow_mb"),
        "resource_projection_peak_downlink_shortfall_mb" =>
          peak_resource_projection_flow_value(rows, "downlink_shortfall_mb"),
        "resource_projection_peak_battery_overuse_wh" =>
          peak_resource_projection_flow_value(rows, "battery_overuse_wh"),
        "resource_projection_peak_unused_downlink_capacity_mb" =>
          peak_resource_projection_flow_value(rows, "unused_downlink_capacity_mb"),
        "resource_source_quality_counts" => Map.get(report, "resource_source_quality_counts"),
        "resource_trust_boundary_status_counts" =>
          Map.get(report, "resource_trust_boundary_status_counts"),
        "first_resource_pressure_activity_id" => first_pressure["activity_id"],
        "first_resource_pressure_activity_type" => first_pressure["activity_type"],
        "first_resource_pressure_kind" => resource_projection_pressure_kind(first_pressure),
        "first_resource_pressure_starts_at_s" => first_pressure["starts_at_s"],
        "first_resource_pressure_direction" => first_pressure["direction"],
        "first_resource_pressure_ground_station_id" => first_pressure["ground_station_id"],
        "first_resource_pressure_station_calendar_entry_id" =>
          first_pressure["station_calendar_entry_id"],
        "first_resource_pressure_station_calendar_provider_id" =>
          first_pressure["station_calendar_provider_id"],
        "first_resource_pressure_station_calendar_provider_entry_id" =>
          first_pressure["station_calendar_provider_entry_id"],
        "first_resource_pressure_station_calendar_directions" =>
          first_pressure["station_calendar_directions"],
        "resource_projection_warning_count" => length(Map.get(report, "warnings", []))
      }
      |> compact_map()
    end
  end

  defp resource_projection_unavailable_spacecraft_ids(rows) do
    rows
    |> Enum.filter(&(&1["spacecraft_available"] == false))
    |> Enum.map(& &1["spacecraft_id"])
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp resource_projection_availability_pressure_spacecraft_ids(rows, pressure_type) do
    rows
    |> Enum.filter(fn row ->
      pressure_type in List.wrap(Map.get(row, "resource_pressure_types", []))
    end)
    |> Enum.map(&(Map.get(&1, "spacecraft_id") || Map.get(&1, "scenario_id")))
    |> Enum.filter(&stable_id_string?/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp resource_projection_availability_pressure_types(rows) do
    rows
    |> Enum.flat_map(&(Map.get(&1, "resource_pressure_types", []) |> List.wrap()))
    |> Enum.filter(&(&1 in resource_projection_availability_pressure_types()))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp resource_projection_flow_count(rows) do
    rows
    |> Enum.flat_map(&resource_projection_flow_rows/1)
    |> length()
  end

  defp peak_resource_projection_flow_value(rows, field) do
    rows
    |> Enum.flat_map(&resource_projection_flow_rows/1)
    |> Enum.map(&Map.get(&1, field))
    |> Enum.filter(&is_number/1)
    |> case do
      [] -> nil
      values -> Enum.max(values)
    end
  end

  defp first_resource_projection_pressure(rows) do
    rows
    |> Enum.flat_map(&resource_projection_flow_rows/1)
    |> Enum.find(%{}, fn row ->
      positive_number?(row["storage_overflow_mb"]) or
        positive_number?(row["downlink_shortfall_mb"]) or
        positive_number?(row["battery_overuse_wh"]) or
        Map.get(row, "resource_effect_reason") in resource_projection_availability_pressure_types()
    end)
  end

  defp first_resource_projection_pressure(rows, "storage_overflow") do
    rows
    |> Enum.flat_map(&resource_projection_flow_rows/1)
    |> Enum.find(%{}, &positive_number?(&1["storage_overflow_mb"]))
  end

  defp first_resource_projection_pressure(rows, "downlink_shortfall") do
    rows
    |> Enum.flat_map(&resource_projection_flow_rows/1)
    |> Enum.find(%{}, &positive_number?(&1["downlink_shortfall_mb"]))
  end

  defp first_resource_projection_pressure(rows, "battery_depletion") do
    rows
    |> Enum.flat_map(&resource_projection_flow_rows/1)
    |> Enum.find(%{}, &positive_number?(&1["battery_overuse_wh"]))
  end

  defp first_resource_projection_pressure(rows, type)
       when type in [
              "spacecraft_unavailable",
              "payload_unavailable",
              "spacecraft_degraded_payload_unavailable",
              "activity_type_suppressed_by_resource_summary",
              "activity_type_incompatible_with_resource_summary",
              "antenna_unavailable"
            ] do
    rows
    |> Enum.flat_map(&resource_projection_flow_rows/1)
    |> Enum.find(%{}, &(Map.get(&1, "resource_effect_reason") == type))
  end

  defp first_resource_projection_pressure(rows, _type),
    do: first_resource_projection_pressure(rows)

  defp first_resource_projection_spacecraft_unavailable(rows) do
    Enum.find(rows, &(&1["spacecraft_available"] == false))
  end

  defp resource_projection_flow_rows(%{"activity_resource_flow" => rows}) when is_list(rows),
    do: rows

  defp resource_projection_flow_rows(_row), do: []

  defp resource_projection_pressure_kind(%{"storage_overflow_mb" => value})
       when is_number(value) and value > 0.0,
       do: "storage_overflow"

  defp resource_projection_pressure_kind(%{"downlink_shortfall_mb" => value})
       when is_number(value) and value > 0.0,
       do: "downlink_shortfall"

  defp resource_projection_pressure_kind(%{"battery_overuse_wh" => value})
       when is_number(value) and value > 0.0,
       do: "battery_depletion"

  defp resource_projection_pressure_kind(%{"resource_effect_reason" => reason})
       when reason in [
              "spacecraft_unavailable",
              "payload_unavailable",
              "spacecraft_degraded_payload_unavailable",
              "activity_type_suppressed_by_resource_summary",
              "activity_type_incompatible_with_resource_summary",
              "antenna_unavailable"
            ],
       do: reason

  defp resource_projection_pressure_kind(_row), do: nil

  defp resource_projection_availability_pressure_types do
    resource_projection_boolean_availability_pressure_types() ++
      resource_projection_activity_type_constraint_pressure_types()
  end

  defp resource_projection_boolean_availability_pressure_types do
    ~w(spacecraft_unavailable payload_unavailable spacecraft_degraded_payload_unavailable antenna_unavailable)
  end

  defp resource_projection_activity_type_constraint_pressure_types do
    ~w(activity_type_suppressed_by_resource_summary activity_type_incompatible_with_resource_summary)
  end

  defp positive_number?(value), do: is_number(value) and value > 0.0

  defp minimum_present(rows, field) do
    rows
    |> Enum.map(&Map.get(&1, field))
    |> Enum.filter(&is_number/1)
    |> case do
      [] -> nil
      values -> Enum.min(values)
    end
  end

  defp minimum_projected_remaining(rows, remaining_field, capacity_field, used_or_demand_field) do
    rows
    |> Enum.flat_map(fn row ->
      cond do
        is_number(Map.get(row, remaining_field)) ->
          [Map.get(row, remaining_field)]

        is_number(Map.get(row, capacity_field)) and is_number(Map.get(row, used_or_demand_field)) ->
          [max(Map.get(row, capacity_field) - Map.get(row, used_or_demand_field), 0.0)]

        true ->
          []
      end
    end)
    |> case do
      [] -> nil
      values -> Enum.min(values)
    end
  end

  defp maximum_present(rows, field) do
    rows
    |> Enum.map(&Map.get(&1, field))
    |> Enum.filter(&is_number/1)
    |> case do
      [] -> nil
      values -> Enum.max(values)
    end
  end

  defp sum_present(rows, field) do
    values =
      rows
      |> Enum.map(&Map.get(&1, field))
      |> Enum.filter(&is_number/1)

    case values do
      [] -> nil
      values -> Enum.sum(values)
    end
  end

  defp strategy_assumptions(request) do
    %{
      "strategy_model" => "explicit_what_if_branch_comparison_over_v2_repair",
      "branch_evaluator" => "deterministic_event_overlay_then_repair",
      "candidate_plan_model" => "v2_repaired_plan_plus_strategic_additions",
      "branch_generation_policy" => request.branch_generation_policy,
      "resource_model" => "thin_mission_state_resource_summary",
      "feedback_model" => "deterministic_success_rate_and_throughput_adjustment",
      "mission_state_assumptions" => Map.get(request.mission_state, "assumptions", %{}),
      "approval_boundary" => "recommendations_only_no_command_execution",
      "cadence_integration" => "future_source_of_realized_operations_no_api_or_database_writes"
    }
  end

  defp strategy_provenance(prior_plan) do
    %{
      "source_plan_id" => source_plan_id(prior_plan),
      "source_planner" => Map.get(prior_plan, "planner"),
      "source_plan_generated_at" => Map.get(prior_plan, "generated_at"),
      "source_provenance" => Map.get(prior_plan, "provenance", %{})
    }
  end

  defp branch_candidate_refresh(branch, request, candidate_refresh_request) do
    cond do
      Map.get(branch, "candidate_refresh") ->
        Map.get(branch, "candidate_refresh")

      candidate_refresh_request ->
        branch
        |> Map.put("candidate_refresh_request", candidate_refresh_request)
        |> execute_branch_candidate_refresh(request)

      true ->
        request.candidate_refresh
    end
  end

  defp branch_candidate_refresh_request(branch, request) do
    cond do
      Map.get(branch, "candidate_refresh_request") ->
        Map.get(branch, "candidate_refresh_request")

      Map.get(branch, "candidate_refresh") ->
        nil

      true ->
        derive_branch_candidate_refresh_request(branch, request)
    end
  end

  defp branch_candidate_source(branch, request, repair_result) do
    base_source =
      repair_result
      |> get_in(["assumptions", "candidate_source"])
      |> Kernel.||(%{})

    candidate_refresh_request =
      Map.get(branch, "candidate_refresh_request") ||
        if generated_branch_candidate_source?(base_source, request) do
          derive_branch_candidate_refresh_request(branch, request)
        end

    source =
      base_source
      |> maybe_put_candidate_source_report_inputs(candidate_refresh_request)
      |> maybe_put_candidate_source_request_result_artifact_report_inputs(request)
      |> maybe_put_candidate_source_event_report_inputs(branch)

    scope =
      cond do
        Map.get(branch, "candidate_refresh") -> "branch"
        Map.get(branch, "candidate_refresh_request") -> "branch_generated"
        generated_branch_candidate_source?(source, request) -> "branch_generated"
        request.candidate_refresh -> "strategy_request"
        true -> "prior_plan"
      end

    Map.put(source, "scope", scope)
  end

  defp execute_branch_candidate_refresh(branch, request) do
    manifest_source =
      branch["candidate_refresh_request"]
      |> candidate_refresh_request_manifest(
        "branch_refresh_#{branch["id"]}",
        branch_refresh_metadata(branch, request)
      )

    with {:ok, manifest} <- Manifest.from_map(manifest_source),
         {:ok, result_set} <- StudyRunner.run(manifest.study, manifest.run_opts) do
      CandidateRefresh.build(result_set,
        candidate_refresh: manifest.study.metadata["candidate_refresh"],
        generated_at: request.generated_at
      )
    else
      {:error, reason} ->
        raise ArgumentError,
              "invalid branch candidate_refresh_request for #{branch["id"]}: #{inspect(reason)}"
    end
  end

  defp candidate_refresh_request_manifest(refresh_request, study_id, metadata) do
    refresh_request = stringify_keys(refresh_request || %{})

    manifest =
      if Map.has_key?(refresh_request, "candidate_refresh") do
        refresh_request
      else
        %{"candidate_refresh" => refresh_request}
      end

    manifest
    |> ensure_candidate_refresh_request_trust_boundaries()
    |> Map.put_new("schema_version", 1)
    |> Map.put_new("study_id", study_id)
    |> Map.put_new("outputs", ["access_windows", "target_visibility", "eclipses"])
    |> Map.put_new("propagator", "two_body")
    |> put_in(["metadata"], Map.merge(Map.get(manifest, "metadata", %{}), metadata))
  end

  defp ensure_candidate_refresh_request_trust_boundaries(manifest) do
    case get_in(manifest, ["candidate_refresh", "accepted_planning_state"]) do
      %{} = accepted_state ->
        put_in(
          manifest,
          ["candidate_refresh", "accepted_planning_state"],
          ensure_accepted_planning_state_estimate_trust_boundaries(accepted_state)
        )

      _missing ->
        manifest
    end
  end

  defp branch_refresh_metadata(branch, request) do
    %{
      "strategy_branch_id" => branch["id"],
      "strategy_source_plan_id" => source_plan_id(request.prior_plan),
      "strategy_branch_events" => branch["events"]
    }
  end

  defp derive_branch_candidate_refresh_request(%{"id" => "baseline"}, _request), do: nil

  defp derive_branch_candidate_refresh_request(%{"events" => []}, _request), do: nil

  defp derive_branch_candidate_refresh_request(branch, request) do
    with %{} = accepted_state <-
           branch_accepted_planning_state(branch, request.mission_state, request.prior_plan) do
      defaults = Map.get(request.mission_state, "candidate_refresh_defaults", %{})

      operational_feedback =
        branch_refresh_operational_feedback(branch, request.operational_feedback)

      targets =
        mission_state_refresh_targets(
          branch,
          request.mission_state,
          operational_feedback
        )

      ground_stations = mission_state_refresh_ground_stations(branch, request.mission_state)
      outputs = branch_refresh_outputs(targets, ground_stations)

      candidate_refresh =
        %{
          "accepted_planning_state" => accepted_state,
          "current_epoch_s" => request.current_epoch_s,
          "remaining_horizon" => branch_refresh_horizon(request, defaults),
          "targets" => targets,
          "ground_network" =>
            branch_refresh_ground_network(
              branch,
              request.mission_state,
              operational_feedback
            ),
          "constraints" => branch_refresh_constraints(request, defaults),
          "resource_filter_policy" => branch_refresh_resource_filter_policy(branch, defaults),
          "candidate_limit_policy" => branch_refresh_candidate_limit_policy(branch, defaults),
          "source_timeline_feedback_report" =>
            mission_state_timeline_feedback_source_report(request.mission_state),
          "timeline_feedback_report" =>
            mission_state_timeline_feedback_report_input(request.mission_state),
          "source_operational_timeline_report" =>
            mission_state_operational_timeline_source_report(request.mission_state),
          "operational_timeline_report" =>
            mission_state_operational_timeline_report_input(request.mission_state),
          "mission_state" =>
            mission_state_candidate_refresh_source_reports(request.mission_state),
          "operational_feedback" => operational_feedback,
          "scoring_policy" => branch_refresh_scoring_policy(request, defaults),
          "model_assumptions" =>
            Map.merge(Map.get(defaults, "model_assumptions", %{}), %{
              "candidate_refresh_level" => "branch_event_derived_v1",
              "derived_from_branch_id" => branch["id"]
            }),
          "resource_summaries" =>
            branch_refresh_resource_summaries(branch, request.mission_state),
          "prior_candidate_activities" => prior_plan_candidate_activities(request.prior_plan),
          "approval_policy" => branch_refresh_approval_policy(request)
        }
        |> compact_map()

      %{
        "schema_version" => 1,
        "study_id" => "branch_refresh_#{branch["id"]}",
        "central_body" => Map.get(defaults, "central_body", "earth"),
        "propagator" => Map.get(defaults, "propagator", "two_body"),
        "propagator_opts" => Map.get(defaults, "propagator_opts", %{"max_step_s" => 10.0}),
        "outputs" => outputs,
        "ground_stations" => ground_stations,
        "candidate_refresh" => candidate_refresh
      }
    else
      _missing -> nil
    end
  end

  defp branch_refresh_operational_feedback(branch, operational_feedback) do
    events =
      branch
      |> Map.get("events", [])
      |> Enum.map(&stringify_keys/1)

    events
    |> Enum.reduce(
      operational_feedback
      |> Kernel.||(%{})
      |> normalize_operational_feedback()
      |> prune_branch_downlink_gap_source_feedback(events),
      &apply_branch_feedback_event/2
    )
    |> put_branch_event_feedback_trust_boundary(events)
  end

  defp prune_branch_downlink_gap_source_feedback(feedback, events) do
    events
    |> Enum.reduce(feedback, fn event, feedback ->
      if event["type"] == "downlink_completion_gap" and event["feedback_source"] not in [nil, ""] do
        key = station_feedback_key(event)

        if get_in(feedback, ["downlink_demand_context", key, "feedback_source"]) ==
             event["feedback_source"] do
          feedback
          |> update_in(["downlink_demand_mb"], &Map.delete(&1 || %{}, key))
          |> update_in(["downlink_demand_sources"], &Map.delete(&1 || %{}, key))
          |> update_in(["downlink_demand_context"], &Map.delete(&1 || %{}, key))
        else
          feedback
        end
      else
        feedback
      end
    end)
  end

  defp put_branch_event_feedback_trust_boundary(feedback, events) do
    trust_boundaries =
      events
      |> Enum.map(
        &(Map.get(&1, "trust_boundary") || get_in(&1, ["provenance", "trust_boundary"]))
      )
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.uniq()

    case {Map.get(feedback, "trust_boundary"), trust_boundaries} do
      {existing, _trust_boundaries} when existing not in [nil, ""] -> feedback
      {_missing, [trust_boundary]} -> Map.put(feedback, "trust_boundary", trust_boundary)
      _other -> feedback
    end
  end

  defp apply_branch_feedback_event(%{"type" => "station_throughput_feedback"} = event, feedback) do
    put_branch_feedback_factor(
      feedback,
      "station_throughput_factor",
      station_feedback_key(event),
      branch_event_weighted_unit_feedback_value(event, "station_throughput_factor")
    )
  end

  defp apply_branch_feedback_event(%{"type" => "contact_success_feedback"} = event, feedback) do
    put_branch_feedback_factor(
      feedback,
      "contact_success_rate",
      station_feedback_key(event),
      branch_event_weighted_unit_feedback_value(event, "contact_success_factor")
    )
  end

  defp apply_branch_feedback_event(%{"type" => "observation_success_feedback"} = event, feedback) do
    feedback
    |> put_branch_feedback_factor(
      "observation_success_rate",
      event["target_id"],
      branch_event_weighted_unit_feedback_value(event, "observation_success_factor")
    )
    |> put_branch_feedback_factor(
      "image_quality_score",
      event["target_id"],
      branch_event_weighted_unit_feedback_value(event, "image_quality_score")
    )
    |> put_branch_feedback_string(
      "image_quality_status",
      event["target_id"],
      event["image_quality_status"]
    )
    |> put_branch_feedback_string(
      "image_quality_source",
      event["target_id"],
      event["image_quality_source"]
    )
    |> put_branch_feedback_factor(
      "cloud_cover_fraction",
      event["target_id"],
      branch_event_weighted_unit_feedback_value(event, "cloud_cover_fraction")
    )
    |> put_branch_feedback_factor(
      "blur_score",
      event["target_id"],
      branch_event_weighted_unit_feedback_value(event, "blur_score")
    )
  end

  defp apply_branch_feedback_event(%{"type" => "target_priority_feedback"} = event, feedback) do
    put_branch_feedback_factor(
      feedback,
      "target_priority_overrides",
      event["target_id"],
      branch_event_weighted_nonnegative_feedback_value(event, "priority")
    )
  end

  defp apply_branch_feedback_event(%{"type" => "maneuver_success_feedback"} = event, feedback) do
    feedback
    |> put_branch_feedback_factor(
      "maneuver_success_rate",
      maneuver_feedback_event_key(event),
      branch_event_weighted_unit_feedback_value(event, "maneuver_success_factor")
    )
    |> put_branch_feedback_factor(
      "maneuver_success_rate",
      event["activity_id"],
      branch_event_weighted_unit_feedback_value(event, "maneuver_success_factor")
    )
  end

  defp apply_branch_feedback_event(
         %{"type" => "maneuver_execution_uncertainty_feedback"} = event,
         feedback
       ) do
    feedback
    |> put_branch_feedback_entry(
      "maneuver_execution_uncertainty",
      maneuver_feedback_event_key(event),
      maneuver_execution_uncertainty_event_feedback(event)
    )
    |> put_branch_feedback_entry(
      "maneuver_execution_uncertainty",
      event["activity_id"],
      maneuver_execution_uncertainty_event_feedback(event)
    )
  end

  defp apply_branch_feedback_event(%{"type" => "command_success_feedback"} = event, feedback) do
    feedback
    |> put_branch_feedback_factor(
      "command_success_rate",
      command_feedback_event_key(event),
      branch_event_weighted_unit_feedback_value(event, "command_success_factor")
    )
    |> put_branch_feedback_factor(
      "command_success_rate",
      event["activity_id"],
      branch_event_weighted_unit_feedback_value(event, "command_success_factor")
    )
  end

  defp apply_branch_feedback_event(%{"type" => "downlink_demand_feedback"} = event, feedback) do
    feedback
    |> put_branch_feedback_override(
      "downlink_demand_mb",
      station_feedback_key(event),
      branch_event_weighted_nonnegative_feedback_value(event, "required_downlink_mb")
    )
    |> put_branch_feedback_downlink_sources(event)
  end

  defp apply_branch_feedback_event(%{"type" => "downlink_completion_gap"} = event, feedback) do
    feedback
    |> put_branch_feedback_factor(
      "downlink_demand_mb",
      station_feedback_key(event),
      branch_event_weighted_nonnegative_feedback_value(event, "required_downlink_mb")
    )
    |> put_branch_feedback_downlink_sources(event)
    |> put_branch_feedback_downlink_context(event)
  end

  defp apply_branch_feedback_event(%{"type" => "resource_margin_pressure"} = event, feedback) do
    spacecraft_id = branch_event_spacecraft_id(event)
    field = event["resource_field"]

    if spacecraft_id in [nil, ""] or
         field not in [
           "fuel_margin",
           "power_margin",
           "storage_margin",
           "downlink_margin",
           "thermal_margin_c"
         ] or
         not is_number(Map.get(event, field)) do
      feedback
    else
      entry =
        event
        |> Map.take(resource_margin_feedback_fields())
        |> Map.put(field, Map.get(event, field))
        |> normalize_resource_margin_aliases()
        |> compact_map()

      merge_branch_feedback_entry(feedback, "resource_margin_overrides", spacecraft_id, entry)
    end
  end

  defp apply_branch_feedback_event(
         %{"type" => "resource_availability_constraint"} = event,
         feedback
       ) do
    spacecraft_id = branch_event_spacecraft_id(event)
    field = event["resource_field"]

    if spacecraft_id in [nil, ""] or
         field not in ["spacecraft_available", "payload_available", "antenna_available"] or
         event["available"] != false do
      feedback
    else
      entry =
        event
        |> Map.take(resource_availability_feedback_fields())
        |> Map.put(field, false)
        |> normalize_resource_availability_aliases()
        |> compact_map()

      merge_branch_feedback_entry(
        feedback,
        "resource_availability_overrides",
        spacecraft_id,
        entry
      )
    end
  end

  defp apply_branch_feedback_event(%{"type" => "degraded_spacecraft"} = event, feedback) do
    spacecraft_id = branch_event_spacecraft_id(event)

    if spacecraft_id in [nil, ""] do
      feedback
    else
      entry =
        event
        |> degraded_spacecraft_feedback_entry()
        |> compact_map()

      merge_branch_feedback_entry(
        feedback,
        "resource_availability_overrides",
        spacecraft_id,
        entry
      )
    end
  end

  defp apply_branch_feedback_event(_event, feedback), do: feedback

  defp branch_event_weighted_unit_feedback_value(event, field) do
    value = Map.get(event, field)

    case branch_event_feedback_confidence_weight(event) do
      weight when is_number(value) and is_number(weight) ->
        1.0 - (1.0 - clamp_unit_interval(value)) * weight

      _weight ->
        value
    end
  end

  defp branch_event_weighted_nonnegative_feedback_value(event, field) do
    value = Map.get(event, field)

    case branch_event_feedback_confidence_weight(event) do
      weight when is_number(value) and is_number(weight) ->
        max(value, 0.0) * weight

      _weight ->
        value
    end
  end

  defp branch_event_feedback_confidence_weight(event) do
    [
      event["feedback_weight"],
      event["feedback_sample_weight"],
      event["sample_weight"],
      event["confidence_weight"]
    ]
    |> Enum.find(&is_number/1)
    |> case do
      value when is_number(value) -> clamp_unit_interval(value)
      _value -> nil
    end
  end

  defp resource_margin_feedback_fields do
    [
      "fuel_margin",
      "power_margin",
      "storage_margin",
      "downlink_margin",
      "thermal_margin_c",
      "battery_capacity_wh",
      "battery_energy_used_wh",
      "battery_state_of_charge"
    ]
  end

  defp resource_availability_feedback_fields do
    [
      "spacecraft_available",
      "payload_available",
      "antenna_available",
      "degraded",
      "mode",
      "incompatible_activity_types"
    ]
  end

  defp degraded_spacecraft_feedback_entry(event) do
    incompatible_types =
      (Map.get(event, "incompatible_activity_types") ||
         Map.get(event, "suppressed_activity_types") || ["observe"])
      |> normalize_incompatible_activity_types()

    %{
      "mode" => degraded_event_mode(event),
      "degraded" => true,
      "spacecraft_available" =>
        if(
          "spacecraft_available_feedback_false" in Map.get(event, "derivation_reasons", []) or
            "spacecraft_availability_feedback_false" in Map.get(event, "derivation_reasons", []),
          do: false
        ),
      "payload_available" => not Enum.member?(incompatible_types, "observe"),
      "antenna_available" =>
        not Enum.any?(incompatible_types, &(&1 in ["downlink", "planned_contact"])),
      "incompatible_activity_types" => incompatible_types
    }
  end

  defp normalize_incompatible_activity_types(values) when is_list(values) do
    values
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp normalize_incompatible_activity_types(value) when is_binary(value) or is_atom(value) do
    case encode_value(value) do
      value when value in [nil, ""] -> ["observe"]
      value -> [value]
    end
  end

  defp normalize_incompatible_activity_types(_values), do: ["observe"]

  defp put_branch_feedback_factor(feedback, _field, key, _value) when key in [nil, ""],
    do: feedback

  defp put_branch_feedback_factor(feedback, field, key, value) when is_number(value) do
    factors =
      case Map.get(feedback, field) do
        %{} = existing -> existing
        _other -> %{}
      end

    Map.put(
      feedback,
      field,
      put_branch_feedback_value(factors, field, encode_value(key), value)
    )
  end

  defp put_branch_feedback_factor(feedback, _field, _key, _value), do: feedback

  defp put_branch_feedback_downlink_sources(feedback, event) do
    key = station_feedback_key(event)
    sources = branch_feedback_downlink_sources(event)

    if key in [nil, ""] or sources == [] do
      feedback
    else
      source_map =
        feedback
        |> Map.get("downlink_demand_sources", %{})
        |> case do
          %{} = existing -> existing
          _existing -> %{}
        end
        |> Map.update(key, sources, fn existing ->
          existing
          |> List.wrap()
          |> Kernel.++(sources)
          |> Enum.map(&encode_value/1)
          |> Enum.reject(&(&1 in [nil, ""]))
          |> Enum.uniq()
          |> Enum.sort()
        end)

      Map.put(feedback, "downlink_demand_sources", source_map)
    end
  end

  defp put_branch_feedback_downlink_context(feedback, event) do
    key = station_feedback_key(event)

    context =
      event
      |> Map.take([
        "collection_id",
        "product_id",
        "product_ids",
        "payload_id",
        "instrument_id",
        "target_id",
        "source_activity_id",
        "source_activity_ids",
        "missed_downlink_activity_id",
        "missed_downlink_activity_ids",
        "objective_id",
        "objective_type",
        "latency_objective",
        "max_latency_s",
        "planned_latency_s",
        "feedback_source",
        "feedback_scope",
        "trust_boundary"
      ])
      |> compact_map()

    if key in [nil, ""] or context == %{} do
      feedback
    else
      context_map =
        feedback
        |> Map.get("downlink_demand_context", %{})
        |> stringify_keys()
        |> Map.put(key, context)

      Map.put(feedback, "downlink_demand_context", context_map)
    end
  end

  defp branch_feedback_downlink_sources(event) do
    [
      event["downlink_demand_source"],
      event["downlink_demand_sources"],
      event["downlink_completion_source"],
      event["downlink_completion_sources"]
    ]
    |> List.flatten()
    |> Enum.map(&encode_value/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp put_branch_feedback_entry(feedback, _field, key, _entry) when key in [nil, ""],
    do: feedback

  defp put_branch_feedback_entry(feedback, field, key, %{} = entry) do
    entries =
      case Map.get(feedback, field) do
        %{} = existing -> existing
        _other -> %{}
      end

    Map.put(feedback, field, Map.put(entries, encode_value(key), entry))
  end

  defp put_branch_feedback_entry(feedback, _field, _key, _entry), do: feedback

  defp put_branch_feedback_string(feedback, _field, key, _value) when key in [nil, ""],
    do: feedback

  defp put_branch_feedback_string(feedback, field, key, value) do
    case encode_value(value) do
      value when is_binary(value) and value != "" ->
        entries =
          case Map.get(feedback, field) do
            %{} = existing -> existing
            _other -> %{}
          end

        Map.put(feedback, field, Map.put(entries, encode_value(key), value))

      _value ->
        feedback
    end
  end

  defp merge_branch_feedback_entry(feedback, _field, key, _entry) when key in [nil, ""],
    do: feedback

  defp merge_branch_feedback_entry(feedback, field, key, %{} = entry) do
    entries =
      case Map.get(feedback, field) do
        %{} = existing -> existing
        _other -> %{}
      end

    Map.put(
      feedback,
      field,
      Map.update(entries, encode_value(key), entry, fn
        %{} = existing -> Map.merge(existing, entry)
        _existing -> entry
      end)
    )
  end

  defp merge_branch_feedback_entry(feedback, _field, _key, _entry), do: feedback

  defp maneuver_execution_uncertainty_event_feedback(event) do
    %{
      "execution_uncertainty_status" => event["execution_uncertainty_status"],
      "execution_uncertainty" => event["execution_uncertainty"],
      "timing_3sigma_s" => event["timing_3sigma_s"],
      "delta_v_3sigma_km_s" => event["delta_v_3sigma_km_s"],
      "delta_v_3sigma_magnitude_km_s" => event["delta_v_3sigma_magnitude_km_s"],
      "execution_uncertainty_source" => event["execution_uncertainty_source"]
    }
    |> compact_map()
  end

  defp put_branch_feedback_override(feedback, _field, key, _value) when key in [nil, ""],
    do: feedback

  defp put_branch_feedback_override(feedback, field, key, value) when is_number(value) do
    factors =
      case Map.get(feedback, field) do
        %{} = existing -> existing
        _other -> %{}
      end

    Map.put(
      feedback,
      field,
      Map.put(factors, encode_value(key), branch_feedback_value(field, value))
    )
  end

  defp put_branch_feedback_override(feedback, _field, _key, _value), do: feedback

  defp put_branch_feedback_value(factors, "downlink_demand_mb", key, value) do
    demand = branch_feedback_value("downlink_demand_mb", value)

    Map.update(factors, key, demand, fn
      existing when is_number(existing) -> max(existing, 0.0) + demand
      _existing -> demand
    end)
  end

  defp put_branch_feedback_value(factors, field, key, value) do
    Map.put(factors, key, branch_feedback_value(field, value))
  end

  defp branch_feedback_value(field, value)
       when field in [
              "station_throughput_factor",
              "contact_success_rate",
              "observation_success_rate",
              "image_quality_score",
              "cloud_cover_fraction",
              "blur_score",
              "maneuver_success_rate",
              "command_success_rate"
            ] do
    value
    |> max(0.0)
    |> min(1.0)
  end

  defp branch_feedback_value(_field, value), do: max(value, 0.0)

  defp station_feedback_key(%{"feedback_scope" => "default"}), do: "default"

  defp station_feedback_key(event) do
    event_ground_station_id(event) || "default"
  end

  defp command_feedback_event_key(%{"feedback_scope" => "default"}), do: "default"

  defp command_feedback_event_key(event) do
    Map.get(event, "feedback_key") || Map.get(event, "activity_id") || "default"
  end

  defp maneuver_feedback_event_key(%{"feedback_scope" => "default"}), do: "default"

  defp maneuver_feedback_event_key(event) do
    Map.get(event, "feedback_key") || Map.get(event, "activity_id") || "default"
  end

  defp branch_refresh_approval_policy(%{
         approval_policy_supplied?: true,
         approval_policy_source: policy
       }) do
    policy
  end

  defp branch_refresh_approval_policy(_request), do: nil

  defp mission_state_accepted_planning_state(
         %{"accepted_planning_state" => %{} = state} = mission_state,
         prior_plan
       ) do
    state
    |> ensure_accepted_planning_state_estimate_trust_boundaries()
    |> append_realized_maneuver_execution_deltas(mission_state, prior_plan)
  end

  defp mission_state_accepted_planning_state(mission_state, prior_plan) do
    spacecraft_states =
      mission_state
      |> Map.get("spacecraft_states", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.filter(&planning_state_estimate?/1)
      |> Enum.map(&complete_planning_state_estimate/1)

    if spacecraft_states == [] do
      nil
    else
      %{
        "schema_version" => 1,
        "artifact_type" => "accepted_planning_state",
        "snapshot_id" => Map.get(mission_state, "snapshot_id", "mission-state"),
        "accepted_at" =>
          Map.get(mission_state, "captured_at") || DateTime.to_iso8601(DateTime.utc_now()),
        "spacecraft_states" => spacecraft_states,
        "maneuver_execution_deltas" =>
          maneuver_execution_deltas_from_mission_state(mission_state, %{}, prior_plan),
        "source" => %{"system" => "mission_state"},
        "quality" => %{"level" => "planning_accepted"},
        "provenance" => %{
          "created_by" => "CampaignPlanner.strategy",
          "trust_boundary" => "strategy_candidate_refresh_input"
        }
      }
      |> ensure_accepted_planning_state_estimate_trust_boundaries()
    end
  end

  defp append_realized_maneuver_execution_deltas(accepted_state, mission_state, prior_plan) do
    Map.put(
      accepted_state,
      "maneuver_execution_deltas",
      maneuver_execution_deltas_from_mission_state(mission_state, accepted_state, prior_plan)
    )
  end

  defp maneuver_execution_deltas_from_mission_state(mission_state, accepted_state, prior_plan) do
    existing =
      Map.get(accepted_state, "maneuver_execution_deltas") ||
        Map.get(mission_state, "maneuver_execution_deltas", [])

    (existing ++ realized_maneuver_execution_deltas(mission_state, prior_plan))
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(&ensure_maneuver_execution_delta_trust_boundary(&1, accepted_state))
    |> unique_maneuver_execution_deltas()
  end

  defp realized_maneuver_execution_deltas(mission_state, prior_plan) do
    mission_state
    |> Map.get("realized_activities", [])
    |> Enum.map(&stringify_keys/1)
    |> enrich_realized_activities_with_planned_context(prior_plan)
    |> Enum.flat_map(&realized_maneuver_execution_delta/1)
  end

  defp realized_maneuver_execution_delta(%{"status" => status} = activity)
       when status in @realized_failure_statuses or status in ["delayed", "partial"] do
    type = Map.get(activity, "type") || Map.get(activity, "activity_type")
    activity_id = Map.get(activity, "id") || Map.get(activity, "activity_id")

    if type in ["maneuver", "impulsive_burn"] and activity_id not in [nil, ""] do
      [
        %{
          "activity_id" => activity_id,
          "status" => status,
          "source" => %{
            "system" => "mission_state.realized_activities",
            "source_id" => activity_id,
            "realized_status" => status
          },
          "quality" => %{"level" => "operator_reported"},
          "provenance" => %{
            "trust_boundary" => "mission_state_realized_activity",
            "source" => "mission_state.realized_activities"
          }
        }
        |> maybe_put_actual_epoch(activity)
        |> maybe_put_delta_epoch(activity)
      ]
    else
      []
    end
  end

  defp realized_maneuver_execution_delta(_activity), do: []

  defp maybe_put_delta_epoch(delta, %{"starts_at_s" => starts_at_s}) when is_number(starts_at_s),
    do: Map.put(delta, "epoch_s", starts_at_s * 1.0)

  defp maybe_put_delta_epoch(delta, %{"epoch_s" => epoch_s}) when is_number(epoch_s),
    do: Map.put(delta, "epoch_s", epoch_s * 1.0)

  defp maybe_put_delta_epoch(delta, _activity), do: delta

  defp unique_maneuver_execution_deltas(deltas) do
    deltas
    |> Enum.reduce({MapSet.new(), []}, fn delta, {seen, kept} ->
      key = {
        delta["activity_id"],
        delta["status"],
        get_in(delta, ["actual_epoch", "seconds_since_j2000"]),
        delta["epoch_s"],
        get_in(delta, ["source", "system"]),
        get_in(delta, ["source", "source_id"])
      }

      if MapSet.member?(seen, key) do
        {seen, kept}
      else
        {MapSet.put(seen, key), [delta | kept]}
      end
    end)
    |> elem(1)
    |> Enum.reverse()
  end

  defp branch_accepted_planning_state(branch, mission_state, prior_plan) do
    case mission_state_accepted_planning_state(mission_state, prior_plan) do
      %{} = accepted_state ->
        branch_deltas = branch_maneuver_execution_deltas(branch)

        if branch_deltas == [] do
          ensure_accepted_planning_state_estimate_trust_boundaries(accepted_state)
        else
          existing_deltas = Map.get(accepted_state, "maneuver_execution_deltas", [])

          accepted_state
          |> Map.put("maneuver_execution_deltas", existing_deltas ++ branch_deltas)
          |> ensure_accepted_planning_state_estimate_trust_boundaries()
        end

      missing ->
        missing
    end
  end

  defp branch_maneuver_execution_deltas(branch) do
    branch
    |> Map.get("events", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.flat_map(&branch_maneuver_execution_delta/1)
  end

  defp branch_maneuver_execution_delta(%{"type" => type, "activity_id" => activity_id} = event)
       when type in ["missed_maneuver", "delayed_maneuver"] and activity_id not in [nil, ""] do
    [
      %{
        "activity_id" => activity_id,
        "status" => maneuver_delta_status(type),
        "source" => %{
          "system" => "strategy_branch_event",
          "event_type" => type,
          "branch_event_id" => Map.get(event, "id")
        },
        "quality" => %{"level" => "branch_assumption"},
        "provenance" => %{
          "trust_boundary" => "strategy_branch_assumption",
          "source" => "strategy_branch.events"
        }
      }
      |> maybe_put_actual_epoch(event)
    ]
  end

  defp branch_maneuver_execution_delta(_event), do: []

  defp ensure_maneuver_execution_delta_trust_boundary(delta, accepted_state) do
    case Map.get(delta, "trust_boundary") || get_in(delta, ["provenance", "trust_boundary"]) do
      boundary when is_binary(boundary) and boundary != "" ->
        delta

      _missing ->
        provenance =
          delta
          |> Map.get("provenance", %{})
          |> Map.put("trust_boundary", inherited_maneuver_delta_trust_boundary(accepted_state))
          |> Map.put_new("source", "accepted_planning_state.maneuver_execution_deltas")

        Map.put(delta, "provenance", provenance)
    end
  end

  defp inherited_maneuver_delta_trust_boundary(%{"provenance" => %{"trust_boundary" => boundary}})
       when is_binary(boundary) and boundary != "" do
    boundary
  end

  defp inherited_maneuver_delta_trust_boundary(_accepted_state),
    do: "strategy_candidate_refresh_input"

  defp ensure_accepted_planning_state_estimate_trust_boundaries(%{} = accepted_state) do
    states = Map.get(accepted_state, "spacecraft_states", [])
    boundary = inherited_state_estimate_trust_boundary(accepted_state)

    Map.put(
      accepted_state,
      "spacecraft_states",
      Enum.map(states, &ensure_spacecraft_state_estimate_trust_boundary(&1, boundary))
    )
  end

  defp ensure_spacecraft_state_estimate_trust_boundary(%{} = state, boundary) do
    case Map.get(state, "trust_boundary") || get_in(state, ["provenance", "trust_boundary"]) do
      value when is_binary(value) and value != "" ->
        state

      _missing ->
        provenance =
          state
          |> Map.get("provenance", %{})
          |> Map.put("trust_boundary", boundary)
          |> Map.put_new("source", "accepted_planning_state.provenance")

        Map.put(state, "provenance", provenance)
    end
  end

  defp ensure_spacecraft_state_estimate_trust_boundary(state, _boundary), do: state

  defp inherited_state_estimate_trust_boundary(%{"provenance" => %{"trust_boundary" => boundary}})
       when is_binary(boundary) and boundary != "" do
    boundary
  end

  defp inherited_state_estimate_trust_boundary(_accepted_state),
    do: "strategy_candidate_refresh_input"

  defp maneuver_delta_status("missed_maneuver"), do: "missed"
  defp maneuver_delta_status("delayed_maneuver"), do: "delayed"

  defp maybe_put_actual_epoch(delta, %{"actual_starts_at_s" => actual_starts_at_s})
       when is_number(actual_starts_at_s) do
    Map.put(delta, "actual_epoch", %{
      "seconds_since_j2000" => actual_starts_at_s * 1.0,
      "time_scale" => "tdb"
    })
  end

  defp maybe_put_actual_epoch(delta, _event), do: delta

  defp planning_state_estimate?(state) do
    is_map(Map.get(state, "epoch")) and is_map(Map.get(state, "state_vector")) and
      not is_nil(Map.get(state, "frame")) and
      not is_nil(Map.get(state, "spacecraft_id") || Map.get(state, "scenario_id"))
  end

  defp complete_planning_state_estimate(state) do
    state
    |> Map.put_new("spacecraft_id", Map.get(state, "scenario_id"))
    |> Map.put_new("scenario_id", Map.get(state, "spacecraft_id"))
    |> Map.put_new("source", %{"system" => "mission_state.spacecraft_states"})
    |> Map.put_new("quality", %{"level" => "planning_accepted"})
  end

  defp mission_state_refresh_targets(branch, mission_state, operational_feedback) do
    catalog_targets =
      mission_state
      |> Map.get("targets", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&normalize_target_spec/1)
      |> unique_items_by_id()

    objective_targets =
      mission_state
      |> Map.get("objectives", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(fn objective ->
        objective
        |> Map.take([
          "id",
          "target_id",
          "latitude_deg",
          "longitude_deg",
          "minimum_elevation_deg",
          "priority"
        ])
        |> Map.put_new("id", Map.get(objective, "target_id"))
      end)
      |> Enum.map(&normalize_target_spec/1)
      |> Enum.filter(&target_spec?/1)
      |> unique_items_by_id()

    event_targets =
      branch
      |> Map.get("events", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(fn event ->
        event
        |> Map.take([
          "id",
          "target_id",
          "latitude_deg",
          "longitude_deg",
          "minimum_elevation_deg",
          "priority"
        ])
        |> Map.put_new("id", Map.get(event, "target_id"))
      end)
      |> Enum.map(&normalize_target_spec/1)
      |> Enum.filter(&target_spec?/1)
      |> unique_items_by_id()

    (catalog_targets ++ objective_targets ++ event_targets)
    |> Enum.filter(&target_spec?/1)
    |> Enum.map(fn target ->
      target
      |> Map.put_new("minimum_elevation_deg", 10.0)
      |> Map.put_new("priority", 1.0)
      |> Map.delete("target_id")
    end)
    |> dedupe_by_id()
    |> apply_target_priority_feedback(operational_feedback)
    |> apply_observation_success_feedback(operational_feedback)
    |> apply_observation_quality_feedback(operational_feedback)
  end

  defp target_spec?(target) do
    target_id = Map.get(target, "id") || Map.get(target, "target_id")

    target_id not in [nil, ""] and is_number(Map.get(target, "latitude_deg")) and
      is_number(Map.get(target, "longitude_deg"))
  end

  defp normalize_target_spec(target) do
    target
    |> Map.put_new("id", Map.get(target, "target_id"))
    |> normalize_target_spec_number("latitude_deg")
    |> normalize_target_spec_number("longitude_deg")
    |> normalize_target_spec_number("minimum_elevation_deg")
    |> normalize_target_spec_number("priority")
  end

  defp normalize_target_spec_number(target, field) do
    case numeric_or_nil(Map.get(target, field)) do
      value when is_number(value) -> Map.put(target, field, value)
      _value -> Map.delete(target, field)
    end
  end

  defp apply_target_priority_feedback(targets, %{"target_priority_overrides" => priorities})
       when is_map(priorities) do
    Enum.map(targets, fn target ->
      target_id = Map.get(target, "id")
      priority = numeric_or_nil(Map.get(priorities, target_id))

      if is_number(priority) do
        target
        |> Map.put("priority", max(priority, 0.0))
        |> Map.put("priority_override_source", "operational_feedback")
      else
        target
      end
    end)
  end

  defp apply_target_priority_feedback(targets, _operational_feedback), do: targets

  defp apply_observation_success_feedback(targets, %{"observation_success_rate" => rates})
       when is_map(rates) do
    Enum.map(targets, fn target ->
      target_id = Map.get(target, "id")
      factor = Map.get(rates, target_id) || Map.get(rates, "default")

      if is_number(factor) do
        priority =
          target
          |> Map.get("priority", 1.0)
          |> numeric_or_nil()
          |> Kernel.||(1.0)
          |> Kernel.*(factor)
          |> max(0.0)

        target
        |> Map.put("priority", priority)
        |> Map.put("observation_success_factor", factor)
      else
        target
      end
    end)
  end

  defp apply_observation_success_feedback(targets, _operational_feedback), do: targets

  defp apply_observation_quality_feedback(targets, %{} = operational_feedback) do
    Enum.map(targets, fn target ->
      target_id = Map.get(target, "id")

      target
      |> put_observation_quality_feedback_value(
        "image_quality_score",
        feedback_target_number(operational_feedback, "image_quality_score", target_id)
      )
      |> put_observation_quality_feedback_value(
        "image_quality_status",
        feedback_target_string(operational_feedback, "image_quality_status", target_id)
      )
      |> put_observation_quality_feedback_value(
        "image_quality_source",
        feedback_target_string(operational_feedback, "image_quality_source", target_id)
      )
      |> put_observation_quality_feedback_value(
        "cloud_cover_fraction",
        feedback_target_number(operational_feedback, "cloud_cover_fraction", target_id)
      )
      |> put_observation_quality_feedback_value(
        "blur_score",
        feedback_target_number(operational_feedback, "blur_score", target_id)
      )
    end)
  end

  defp apply_observation_quality_feedback(targets, _operational_feedback), do: targets

  defp feedback_target_number(feedback, field, target_id) do
    case Map.get(feedback, field) do
      %{} = values ->
        Enum.find_value([target_id, "default"], fn key ->
          case Map.get(values, key) do
            value when is_number(value) -> value
            _value -> nil
          end
        end)

      _values ->
        nil
    end
  end

  defp feedback_target_string(feedback, field, target_id) do
    case Map.get(feedback, field) do
      %{} = values ->
        Enum.find_value([target_id, "default"], fn key ->
          case encode_value(Map.get(values, key)) do
            value when is_binary(value) and value != "" -> value
            _value -> nil
          end
        end)

      _values ->
        nil
    end
  end

  defp put_observation_quality_feedback_value(target, _field, nil), do: target

  defp put_observation_quality_feedback_value(target, field, value),
    do: Map.put(target, field, value)

  defp mission_state_refresh_ground_stations(_branch, mission_state) do
    station_defaults =
      mission_state
      |> Map.get("ground_stations", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&normalize_ground_station_spec/1)
      |> unique_items_by_id()

    network_stations =
      mission_state
      |> Map.get("ground_network", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&normalize_ground_station_spec/1)
      |> unique_items_by_id()

    (station_defaults ++ network_stations)
    |> Enum.filter(fn station ->
      station["id"] not in [nil, ""] and is_number(station["latitude_deg"]) and
        is_number(station["longitude_deg"])
    end)
    |> dedupe_by_id_preserving_first()
  end

  defp normalize_ground_station_spec(station) do
    station
    |> Map.put_new("id", Map.get(station, "ground_station_id"))
    |> Map.put_new("minimum_elevation_deg", 5.0)
    |> Map.delete("ground_station_id")
  end

  defp branch_refresh_ground_network(branch, mission_state, operational_feedback) do
    base_entries =
      mission_state
      |> base_ground_network_entries()
      |> Enum.map(&stringify_keys/1)
      |> apply_station_throughput_feedback(operational_feedback)

    station_ids =
      base_entries
      |> Enum.map(&ground_network_station_id/1)
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.uniq()

    event_entries =
      branch
      |> Map.get("events", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.flat_map(&branch_ground_network_event_entries(&1, station_ids))

    merge_branch_ground_network_entries(base_entries, event_entries)
  end

  defp merge_branch_ground_network_entries(base_entries, []), do: base_entries

  defp merge_branch_ground_network_entries(base_entries, event_entries) do
    base_entries
    |> Enum.reject(fn base_entry ->
      Enum.any?(
        event_entries,
        &(same_branch_ground_network_state?(base_entry, &1) ||
            catalog_ground_station_default_shadowed?(base_entry, &1))
      )
    end)
    |> Kernel.++(event_entries)
  end

  defp catalog_ground_station_default_shadowed?(base_entry, event_entry) do
    get_in(base_entry, ["provenance", "source"]) == "mission_state.ground_stations" and
      ground_network_station_id(base_entry) == ground_network_station_id(event_entry) and
      ground_network_entries_overlap?(base_entry, event_entry)
  end

  defp same_branch_ground_network_state?(left, right) do
    ground_network_station_id(left) == ground_network_station_id(right) and
      ground_network_state_kind(left) == ground_network_state_kind(right) and
      ground_network_entries_overlap?(left, right)
  end

  defp ground_network_state_kind(entry) do
    status =
      normalized_station_availability_token(
        Map.get(entry, "status") || Map.get(entry, "availability")
      )

    capacity_fraction = ground_network_capacity_fraction(entry, nil)

    cond do
      status in @unavailable_station_tokens -> :unavailable
      status == "reserved" -> :reserved
      is_number(capacity_fraction) and capacity_fraction <= 0.0 -> :unavailable
      is_number(capacity_fraction) and capacity_fraction < 1.0 -> :reduced_capacity
      true -> :available
    end
  end

  defp ground_network_entries_overlap?(left, right) do
    left_start = Map.get(left, "starts_at_s")
    left_end = Map.get(left, "ends_at_s")
    right_start = Map.get(right, "starts_at_s")
    right_end = Map.get(right, "ends_at_s")

    cond do
      is_nil(left_start) or is_nil(left_end) or is_nil(right_start) or is_nil(right_end) ->
        true

      is_number(left_start) and is_number(left_end) and is_number(right_start) and
          is_number(right_end) ->
        left_start < right_end and right_start < left_end

      true ->
        false
    end
  end

  defp apply_station_throughput_feedback(entries, %{"station_throughput_factor" => factors})
       when is_map(factors) do
    Enum.map(entries, fn entry ->
      station_id = ground_network_station_id(entry)
      factor = numeric_or_nil(Map.get(factors, station_id) || Map.get(factors, "default"))

      if is_number(factor) do
        capacity_fraction =
          entry
          |> ground_network_capacity_fraction()
          |> Kernel.*(factor)
          |> max(0.0)
          |> min(1.0)

        entry
        |> Map.put("capacity_fraction", capacity_fraction)
        |> Map.put_new("status", "available")
        |> Map.update("provenance", %{}, fn
          %{} = provenance -> provenance
          _other -> %{}
        end)
        |> put_in(
          ["provenance", "station_throughput_factor_source"],
          "operational_feedback"
        )
      else
        entry
      end
    end)
  end

  defp apply_station_throughput_feedback(entries, _operational_feedback), do: entries

  defp base_ground_network_entries(mission_state) do
    station_defaults =
      mission_state
      |> Map.get("ground_stations", [])
      |> Enum.map(fn station ->
        station = stringify_keys(station)

        %{
          "ground_station_id" => ground_network_station_id(station),
          "status" => Map.get(station, "status", "available"),
          "capacity_fraction" => ground_network_capacity_fraction(station),
          "provenance" => %{"source" => "mission_state.ground_stations"}
        }
        |> normalize_ground_network_entry()
        |> compact_map()
      end)

    ground_network =
      mission_state
      |> Map.get("ground_network", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&normalize_ground_network_entry/1)

    station_defaults ++ ground_network
  end

  defp branch_ground_network_event_entries(
         %{"type" => "ground_station_outage"} = event,
         station_ids
       ) do
    event
    |> event_station_ids(station_ids)
    |> Enum.map(fn station_id ->
      compact_map(%{
        "id" => event["station_calendar_entry_id"],
        "station_calendar_entry_id" => event["station_calendar_entry_id"],
        "station_calendar_provider_id" => event["station_calendar_provider_id"],
        "station_calendar_provider_entry_id" => event["station_calendar_provider_entry_id"],
        "station_calendar_directions" => event["station_calendar_directions"],
        "station_calendar_status" => event["station_calendar_status"],
        "station_calendar_trust_boundary_status" =>
          event["station_calendar_trust_boundary_status"],
        "ground_station_id" => station_id,
        "status" => "unavailable",
        "capacity_fraction" => 0.0,
        "starts_at_s" => event["starts_at_s"],
        "ends_at_s" => event["ends_at_s"],
        "provenance" => branch_ground_network_event_provenance(event, "ground_station_outage")
      })
    end)
  end

  defp branch_ground_network_event_entries(
         %{"type" => "reduced_downlink_capacity"} = event,
         station_ids
       ) do
    event
    |> event_station_ids(station_ids)
    |> Enum.map(fn station_id ->
      compact_map(%{
        "id" => event["station_calendar_entry_id"],
        "station_calendar_entry_id" => event["station_calendar_entry_id"],
        "station_calendar_provider_id" => event["station_calendar_provider_id"],
        "station_calendar_provider_entry_id" => event["station_calendar_provider_entry_id"],
        "station_calendar_directions" => event["station_calendar_directions"],
        "station_calendar_status" => event["station_calendar_status"],
        "station_calendar_trust_boundary_status" =>
          event["station_calendar_trust_boundary_status"],
        "ground_station_id" => station_id,
        "status" => "available",
        "capacity_fraction" => ground_network_capacity_fraction(event),
        "starts_at_s" => event["starts_at_s"],
        "ends_at_s" => event["ends_at_s"],
        "provenance" => branch_ground_network_event_provenance(event, "reduced_downlink_capacity")
      })
    end)
  end

  defp branch_ground_network_event_entries(
         %{"type" => "ground_station_reserved"} = event,
         station_ids
       ) do
    event
    |> event_station_ids(station_ids)
    |> Enum.map(fn station_id ->
      compact_map(%{
        "id" => event["station_calendar_entry_id"],
        "station_calendar_entry_id" => event["station_calendar_entry_id"],
        "station_calendar_provider_id" => event["station_calendar_provider_id"],
        "station_calendar_provider_entry_id" => event["station_calendar_provider_entry_id"],
        "station_calendar_directions" => event["station_calendar_directions"],
        "station_calendar_status" => event["station_calendar_status"],
        "station_calendar_trust_boundary_status" =>
          event["station_calendar_trust_boundary_status"],
        "ground_station_id" => station_id,
        "status" => "reserved",
        "capacity_fraction" => ground_network_capacity_fraction(event),
        "starts_at_s" => event["starts_at_s"],
        "ends_at_s" => event["ends_at_s"],
        "reservation_id" => Map.get(event, "reservation_id") || Map.get(event, "id"),
        "reserved_by" => event["reserved_by"],
        "reservation_status" => Map.get(event, "reservation_status", "reserved"),
        "station_reservation_match_status" => event["station_reservation_match_status"],
        "provenance" => branch_ground_network_event_provenance(event, "ground_station_reserved")
      })
    end)
  end

  defp branch_ground_network_event_entries(_event, _station_ids), do: []

  defp normalize_ground_network_entry(entry) do
    entry
    |> maybe_put_ground_network_capacity_fraction()
    |> normalize_ground_network_time_field("starts_at_s", "start_s")
    |> normalize_ground_network_time_field("ends_at_s", "end_s")
  end

  defp maybe_put_ground_network_capacity_fraction(entry) do
    case ground_network_capacity_fraction(entry, nil) do
      value when is_number(value) -> Map.put(entry, "capacity_fraction", value)
      _value -> entry
    end
  end

  defp normalize_ground_network_time_field(entry, field, alias_field) do
    value = numeric_or_nil(Map.get(entry, field)) || numeric_or_nil(Map.get(entry, alias_field))
    entry = Map.delete(entry, alias_field)

    if is_number(value) do
      Map.put(entry, field, value)
    else
      Map.delete(entry, field)
    end
  end

  defp ground_network_capacity_fraction(entry, default \\ 1.0) do
    capacity_fraction =
      numeric_or_nil(Map.get(entry, "capacity_fraction")) ||
        numeric_or_nil(Map.get(entry, "availability"))

    case capacity_fraction do
      value when is_number(value) -> clamp_unit_interval(value)
      _value -> default
    end
  end

  defp ground_network_time(entry, field, default) do
    alias_field =
      case field do
        "starts_at_s" -> "start_s"
        "ends_at_s" -> "end_s"
        _field -> nil
      end

    numeric_or_nil(Map.get(entry, field)) ||
      (alias_field && numeric_or_nil(Map.get(entry, alias_field))) ||
      default
  end

  defp branch_ground_network_event_provenance(event, event_type) do
    %{
      "source" => "strategy_branch_event",
      "event_type" => event_type,
      "trust_boundary" =>
        Map.get(event, "trust_boundary") || get_in(event, ["provenance", "trust_boundary"]),
      "source_event_provenance" => Map.get(event, "provenance")
    }
    |> compact_map()
  end

  defp ground_network_station_id(station) do
    Map.get(station, "ground_station_id") || Map.get(station, "station_id") ||
      Map.get(station, "id")
  end

  defp event_station_ids(event, station_ids) do
    case event_ground_station_id(event) do
      nil -> station_ids
      station_id -> [station_id]
    end
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
  end

  defp branch_ground_station_event_reason("ground_station_reserved"),
    do: "branch_ground_station_reserved"

  defp branch_ground_station_event_reason(_type), do: "branch_ground_station_outage"

  defp branch_ground_station_realized_context(event, type) do
    %{
      "ground_station_id" => event_ground_station_id(event),
      "station_availability" => branch_ground_station_event_availability(type),
      "station_calendar_entry_id" => event["station_calendar_entry_id"],
      "station_calendar_provider_id" => event["station_calendar_provider_id"],
      "station_calendar_provider_entry_id" => event["station_calendar_provider_entry_id"],
      "station_calendar_directions" => event["station_calendar_directions"],
      "station_calendar_status" => event["station_calendar_status"],
      "station_contention_status" =>
        if(type == "ground_station_reserved", do: "reserved_overlap"),
      "station_reservation_id" => event["station_reservation_id"] || event["reservation_id"],
      "station_reserved_by" => event["station_reserved_by"] || event["reserved_by"],
      "station_reservation_status" =>
        event["station_reservation_status"] || event["reservation_status"],
      "station_reservation_match_status" => event["station_reservation_match_status"],
      "station_calendar_trust_boundary_status" => event["station_calendar_trust_boundary_status"],
      "trust_boundary" => event["trust_boundary"],
      "provenance" => event["provenance"]
    }
    |> compact_map()
  end

  defp branch_ground_station_event_availability("ground_station_reserved"), do: "reserved"
  defp branch_ground_station_event_availability(_type), do: "unavailable"

  defp branch_refresh_outputs(targets, ground_stations) do
    ["eclipses"]
    |> maybe_append_output(ground_stations != [], "access_windows")
    |> maybe_append_output(targets != [], "target_visibility")
    |> Enum.reverse()
  end

  defp maybe_append_output(outputs, true, output), do: [output | outputs]
  defp maybe_append_output(outputs, false, _output), do: outputs

  defp branch_refresh_horizon(request, defaults) do
    request.remaining_horizon
    |> Map.take(["starts_at_s", "ends_at_s", "duration_s"])
    |> Map.put("output_step_s", branch_refresh_output_step_s(request, defaults))
  end

  defp branch_refresh_output_step_s(request, defaults) do
    numeric_or_nil(Map.get(request.remaining_horizon, "output_step_s")) ||
      numeric_or_nil(get_in(request.prior_plan, ["planning_horizon", "output_step_s"])) ||
      numeric_or_nil(Map.get(defaults, "output_step_s")) ||
      60.0
  end

  defp branch_refresh_constraints(request, defaults) do
    source_constraints =
      get_in(request.prior_plan, ["assumptions", "constraints"]) || %{}

    source_constraints
    |> Map.merge(Map.get(defaults, "constraints", %{}))
    |> Map.put_new("avoid_eclipse", false)
    |> Map.put_new("min_activity_duration_s", 0.0)
  end

  defp branch_refresh_scoring_policy(request, defaults) do
    source_policy =
      get_in(request.prior_plan, ["ranking_explanation", "policy"]) || %{}

    source_policy
    |> Map.merge(Map.get(defaults, "scoring_policy", %{}))
    |> Map.put_new("downlink_rate_mb_s", 1.0)
  end

  defp branch_refresh_resource_filter_policy(branch, defaults) do
    branch
    |> Map.get("events", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.reduce(Map.get(defaults, "resource_filter_policy", %{}), fn
      %{"type" => "resource_margin_pressure", "resource_field" => "thermal_margin_c"} = event,
      policy ->
        put_numeric_policy_threshold(
          policy,
          "min_activity_thermal_margin_c",
          event["thermal_margin_c_threshold"]
        )

      _event, policy ->
        policy
    end)
  end

  defp branch_refresh_candidate_limit_policy(branch, defaults) do
    base_policy = Map.get(defaults, "candidate_limit_policy", %{})

    branch
    |> Map.get("events", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.reduce(base_policy, fn
      %{"type" => "refresh_budget_pressure"} = event, policy ->
        case numeric_or_nil(event["relaxed_max_candidate_activities"]) do
          value when is_number(value) and value > 0 ->
            relaxed_limit = ceil_count(value)
            current_limit = numeric_or_nil(Map.get(policy, "max_candidate_activities"))

            if is_number(current_limit) and current_limit >= relaxed_limit do
              policy
            else
              Map.put(policy, "max_candidate_activities", relaxed_limit)
            end

          _value ->
            policy
        end

      _event, policy ->
        policy
    end)
  end

  defp put_numeric_policy_threshold(policy, key, value) do
    case numeric_or_nil(value) do
      threshold when is_number(threshold) -> Map.put(policy, key, threshold)
      _value -> policy
    end
  end

  defp branch_refresh_resource_summaries(branch, mission_state) do
    base_summaries =
      case Map.get(mission_state, "resource_summaries") do
        summaries when is_list(summaries) and summaries != [] ->
          summaries

        _other ->
          mission_state_resource_summaries(mission_state)
      end
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&normalize_spacecraft_state_booleans/1)

    branch
    |> Map.get("events", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.reduce(base_summaries, &apply_resource_event_summary/2)
    |> Enum.sort_by(& &1["spacecraft_id"])
  end

  defp mission_state_resource_summaries(mission_state) do
    resources =
      mission_state
      |> Map.get("resources", %{})
      |> stringify_keys()

    resources
    |> mission_state_resource_summary_sources(mission_state)
    |> ResourceSummary.to_maps()
  end

  defp mission_state_resource_summary_inputs(mission_state) do
    case Map.get(mission_state, "resource_summaries") do
      summaries when is_list(summaries) and summaries != [] ->
        summaries

      _other ->
        mission_state_resource_summaries(mission_state)
    end
    |> Enum.map(&stringify_keys/1)
  end

  defp explicit_mission_state_resource_summaries?(mission_state) do
    case Map.get(mission_state, "resource_summaries") do
      summaries when is_list(summaries) and summaries != [] -> true
      _other -> false
    end
  end

  defp mission_state_resource_source_path(mission_state, field) do
    if explicit_mission_state_resource_summaries?(mission_state) do
      "mission_state.resource_summaries.#{field}"
    else
      "mission_state.resources.#{field}"
    end
  end

  defp mission_state_resource_unavailable_sources(mission_state, field) do
    mission_state
    |> mission_state_resource_summary_inputs()
    |> Enum.map(&normalize_resource_availability_source(&1, mission_state))
    |> Enum.filter(&(&1[field] == false and &1["spacecraft_id"] not in [nil, ""]))
    |> Enum.sort_by(& &1["spacecraft_id"])
  end

  defp normalize_resource_availability_source(summary, mission_state) do
    summary
    |> normalize_resource_metric_source(mission_state)
    |> normalize_resource_availability_aliases()
  end

  defp mission_state_lowest_resource_margin_source(mission_state, field) do
    source =
      mission_state
      |> mission_state_resource_margin_sources(field)
      |> List.first()

    source || mission_state_raw_resource_margin_source(mission_state, field)
  end

  defp mission_state_resource_margin_sources(mission_state, field) do
    mission_state
    |> mission_state_resource_metric_sources()
    |> Enum.filter(&(is_number(&1[field]) and &1["spacecraft_id"] not in [nil, ""]))
    |> Enum.sort_by(&{&1[field], &1["spacecraft_id"]})
    |> case do
      [] ->
        case mission_state_raw_resource_margin_source(mission_state, field) do
          nil -> []
          source -> [source]
        end

      sources ->
        sources
    end
  end

  defp mission_state_resource_metric_sources(mission_state) do
    mission_state
    |> mission_state_resource_summary_inputs()
    |> Enum.map(&normalize_resource_metric_source(&1, mission_state))
  end

  defp normalize_resource_metric_source(summary, mission_state) do
    summary =
      summary
      |> stringify_keys()
      |> Map.put_new(
        "spacecraft_id",
        Map.get(stringify_keys(summary), "scenario_id") ||
          mission_state_resource_spacecraft_id(mission_state)
      )

    summary
    |> List.wrap()
    |> ResourceSummary.to_maps()
    |> List.first()
  rescue
    ArgumentError ->
      summary
  end

  defp mission_state_raw_resource_margin_source(mission_state, field) do
    if explicit_mission_state_resource_summaries?(mission_state) do
      nil
    else
      resources =
        mission_state
        |> Map.get("resources", %{})
        |> stringify_keys()

      value =
        Map.get(resources, field) ||
          if(field == "downlink_margin", do: Map.get(resources, "downlink_capacity_margin"))

      case numeric_or_nil(value) do
        margin when is_number(margin) ->
          %{
            "spacecraft_id" => mission_state_resource_spacecraft_id(mission_state),
            field => margin,
            "source_quality" => "operator_supplied",
            "provenance" => %{"source" => "mission_state.resources"}
          }

        _value ->
          nil
      end
    end
  end

  defp mission_state_resource_summary_sources(resources, mission_state) when is_list(resources) do
    resources
    |> Enum.map(
      &mission_state_resource_summary_source(&1, mission_state, "mission_state.resources")
    )
    |> Enum.reject(&is_nil/1)
  end

  defp mission_state_resource_summary_sources(resources, mission_state) when is_map(resources) do
    nested_sources =
      resources
      |> mission_state_nested_resource_sources()
      |> Enum.map(
        &mission_state_resource_summary_source(&1, mission_state, "mission_state.resources")
      )
      |> Enum.reject(&is_nil/1)

    case {nested_sources, resource_summary_source?(resources)} do
      {[], true} ->
        [
          mission_state_resource_summary_source(
            resources,
            mission_state,
            "mission_state.resources"
          )
        ]
        |> Enum.reject(&is_nil/1)

      {sources, _single_source?} ->
        sources
    end
  end

  defp mission_state_resource_summary_sources(_resources, _mission_state), do: []

  defp mission_state_nested_resource_sources(resources) do
    [
      Map.get(resources, "spacecraft"),
      Map.get(resources, "spacecraft_resources")
    ]
    |> Enum.flat_map(fn
      values when is_list(values) -> values
      %{} = value -> [value]
      _other -> []
    end)
  end

  defp mission_state_resource_summary_source(source, mission_state, provenance_source) do
    source =
      source
      |> stringify_keys()
      |> normalize_resource_margin_aliases()
      |> normalize_resource_availability_aliases()

    if resource_summary_source?(source) do
      source
      |> Map.take(resource_summary_source_fields())
      |> Map.put_new(
        "spacecraft_id",
        Map.get(source, "scenario_id") ||
          Map.get(source, "id") ||
          mission_state_resource_spacecraft_id(mission_state)
      )
      |> Map.delete("scenario_id")
      |> Map.put("source_quality", "operator_supplied")
      |> Map.put("assumptions", %{"model" => "mission_state_resources_summary"})
      |> Map.put("provenance", %{"source" => provenance_source})
    end
  end

  defp resource_summary_source_fields do
    [
      "spacecraft_id",
      "scenario_id",
      "mode",
      "fuel_margin",
      "power_margin",
      "battery_capacity_wh",
      "battery_energy_used_wh",
      "battery_state_of_charge",
      "storage_capacity_mb",
      "storage_used_mb",
      "storage_margin",
      "downlink_capacity_mb",
      "downlink_margin",
      "thermal_margin_c",
      "spacecraft_available",
      "payload_available",
      "antenna_available",
      "degraded"
    ]
  end

  defp resource_summary_source?(resources) when is_map(resources) do
    resources
    |> normalize_resource_margin_aliases()
    |> normalize_resource_availability_aliases()
    |> Map.take(resource_summary_value_fields())
    |> map_size()
    |> Kernel.>(0)
  end

  defp resource_summary_source?(_resources), do: false

  defp resource_summary_value_fields do
    resource_summary_source_fields() -- ["spacecraft_id", "scenario_id"]
  end

  defp mission_state_resource_spacecraft_id(mission_state) do
    mission_state
    |> Map.get("spacecraft_states", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.find_value(fn state ->
      Map.get(state, "scenario_id") || Map.get(state, "spacecraft_id") || Map.get(state, "id")
    end) || "mission_state_resources"
  end

  defp apply_resource_event_summary(%{"type" => "degraded_spacecraft"} = event, summaries) do
    spacecraft_id = branch_event_spacecraft_id(event)

    if spacecraft_id in [nil, ""] do
      summaries
    else
      incompatible_types =
        (Map.get(event, "incompatible_activity_types") ||
           Map.get(event, "suppressed_activity_types") || ["observe"])
        |> normalize_incompatible_activity_types()

      spacecraft_unavailable? =
        event["spacecraft_available"] == false or
          event
          |> Map.get("derivation_reasons", [])
          |> Enum.any?(
            &(&1 in [
                "spacecraft_available_feedback_false",
                "spacecraft_availability_feedback_false"
              ])
          )

      overlay =
        %{
          "spacecraft_id" => spacecraft_id,
          "mode" => degraded_event_mode(event),
          "degraded" => true,
          "spacecraft_available" => if(spacecraft_unavailable?, do: false),
          "payload_available" => not Enum.member?(incompatible_types, "observe"),
          "antenna_available" =>
            not Enum.any?(incompatible_types, &(&1 in ["downlink", "planned_contact"])),
          "assumptions" =>
            %{
              "model" => "strategy_branch_event_resource_overlay",
              "incompatible_activity_types" => incompatible_types,
              "derivation_reasons" => Map.get(event, "derivation_reasons", []),
              "feedback_source" => Map.get(event, "feedback_source")
            }
            |> compact_map(),
          "provenance" =>
            %{
              "source" => "strategy_branch_event",
              "event_type" => "degraded_spacecraft",
              "trust_boundary" => resource_event_trust_boundary(event)
            }
            |> compact_map()
        }

      upsert_resource_summary(summaries, overlay)
    end
  end

  defp apply_resource_event_summary(%{"type" => "resource_margin_pressure"} = event, summaries) do
    spacecraft_id = branch_event_spacecraft_id(event)
    field = event["resource_field"]
    value = field && Map.get(event, field)

    if spacecraft_id in [nil, ""] or
         field not in [
           "fuel_margin",
           "power_margin",
           "storage_margin",
           "downlink_margin",
           "thermal_margin_c"
         ] or
         not is_number(value) do
      summaries
    else
      overlay =
        %{
          "spacecraft_id" => spacecraft_id,
          field => value,
          "assumptions" =>
            %{
              "model" => "strategy_branch_event_resource_overlay",
              "resource_field" => field,
              "derivation_reasons" => Map.get(event, "derivation_reasons", []),
              "resource_id" => event["resource_id"],
              "planned_resource_id" => event["planned_resource_id"],
              "realized_resource_id" => event["realized_resource_id"],
              "resource_match_status" => event["resource_match_status"]
            }
            |> compact_map(),
          "provenance" =>
            %{
              "source" => "strategy_branch_event",
              "event_type" => "resource_margin_pressure",
              "trust_boundary" => resource_event_trust_boundary(event)
            }
            |> compact_map()
        }

      upsert_resource_summary(summaries, overlay)
    end
  end

  defp apply_resource_event_summary(
         %{"type" => "resource_availability_constraint"} = event,
         summaries
       ) do
    spacecraft_id = branch_event_spacecraft_id(event)
    field = event["resource_field"]

    if spacecraft_id in [nil, ""] or
         field not in ["antenna_available", "payload_available", "spacecraft_available"] or
         event["available"] != false do
      summaries
    else
      overlay =
        %{
          "spacecraft_id" => spacecraft_id,
          field => false,
          "assumptions" =>
            %{
              "model" => "strategy_branch_event_resource_overlay",
              "resource_field" => field,
              "derivation_reasons" => Map.get(event, "derivation_reasons", []),
              "resource_id" => event["resource_id"],
              "planned_resource_id" => event["planned_resource_id"],
              "realized_resource_id" => event["realized_resource_id"],
              "resource_match_status" => event["resource_match_status"]
            }
            |> compact_map(),
          "provenance" =>
            %{
              "source" => "strategy_branch_event",
              "event_type" => "resource_availability_constraint",
              "trust_boundary" => resource_event_trust_boundary(event)
            }
            |> compact_map()
        }

      upsert_resource_summary(summaries, overlay)
    end
  end

  defp apply_resource_event_summary(_event, summaries), do: summaries

  defp resource_event_trust_boundary(%{"trust_boundary" => trust_boundary})
       when is_binary(trust_boundary) and trust_boundary != "",
       do: trust_boundary

  defp resource_event_trust_boundary(%{"provenance" => %{"trust_boundary" => trust_boundary}})
       when is_binary(trust_boundary) and trust_boundary != "",
       do: trust_boundary

  defp resource_event_trust_boundary(_event), do: nil

  defp upsert_resource_summary(summaries, overlay) do
    key = overlay["spacecraft_id"]

    {matched, rest} =
      Enum.split_with(summaries, fn summary -> summary["spacecraft_id"] == key end)

    base = List.first(matched, %{"spacecraft_id" => key})

    merged =
      base
      |> Map.merge(overlay)
      |> Map.put(
        "provenance",
        merge_resource_summary_provenance(base["provenance"], overlay["provenance"])
      )

    [merged | rest]
  end

  defp merge_resource_summary_provenance(base, overlay) do
    base =
      case base do
        %{} = provenance -> provenance
        _provenance -> %{}
      end

    overlay =
      case overlay do
        %{} = provenance -> provenance
        _provenance -> %{}
      end

    Map.merge(base, overlay)
    |> compact_map()
  end

  defp dedupe_by_id(items) do
    items
    |> Map.new(&{&1["id"], &1})
    |> Map.values()
    |> Enum.sort_by(& &1["id"])
  end

  defp dedupe_by_id_preserving_first(items) do
    {items, _seen_ids} =
      Enum.reduce(items, {[], MapSet.new()}, fn item, {items, seen_ids} ->
        id = item["id"]

        if MapSet.member?(seen_ids, id) do
          {items, seen_ids}
        else
          {[item | items], MapSet.put(seen_ids, id)}
        end
      end)

    items
    |> Enum.reverse()
    |> Enum.sort_by(& &1["id"])
  end

  defp unique_items_by_id(items) do
    items
    |> Enum.group_by(&Map.get(&1, "id"))
    |> Enum.reject(fn {id, _items} -> id in [nil, ""] end)
    |> Enum.flat_map(fn
      {_id, [item]} -> [item]
      {_id, _duplicates} -> []
    end)
    |> Enum.sort_by(& &1["id"])
  end

  defp generated_branch_candidate_source?(%{"type" => "candidate_refresh.v1"} = source, request) do
    is_nil(request.candidate_refresh) or
      Map.get(source, "refresh_id") != Map.get(request.candidate_refresh || %{}, "refresh_id")
  end

  defp generated_branch_candidate_source?(_source, _request), do: false

  defp branch_assumptions(branch, request, repair_policy, scoring_policy, candidate_source) do
    %{
      "branch_id" => branch["id"],
      "what_if_events" => branch["events"],
      "repair_policy" => repair_policy_to_map(repair_policy),
      "repair_scoring_policy" => scoring_policy,
      "strategy_policy" => strategy_policy_to_map(request.strategy_policy),
      "candidate_source" => candidate_source,
      "model_limits" => [
        "thin_resource_summary_only",
        "no_autonomous_execution",
        "no_external_astrodynamics_backend"
      ]
    }
  end

  defp branch_provenance(prior_plan, branch, candidate_source) do
    %{
      "source_plan_id" => source_plan_id(prior_plan),
      "branch_id" => branch["id"],
      "branch_metadata" => branch["metadata"],
      "candidate_source" => candidate_source
    }
  end

  defp strategy_id(request, branch_maps) do
    :crypto.hash(
      :sha256,
      :erlang.term_to_binary({
        source_plan_id(request.prior_plan),
        strip_realized_snapshot_model_limits(request.mission_state),
        request.strategy_policy,
        request.approval_policy,
        strip_realized_snapshot_model_limits(branch_maps)
      })
    )
    |> Base.encode16(case: :lower)
  end

  defp strip_realized_snapshot_model_limits(
         %{"schema_contract" => "realized_state_snapshot.v1"} = snapshot
       ) do
    snapshot
    |> Map.delete("model_limits")
    |> Map.new(fn {key, value} -> {key, strip_realized_snapshot_model_limits(value)} end)
  end

  defp strip_realized_snapshot_model_limits(value) when is_map(value) do
    value
    |> Map.new(fn {key, nested_value} ->
      {key, strip_realized_snapshot_model_limits(nested_value)}
    end)
  end

  defp strip_realized_snapshot_model_limits(values) when is_list(values) do
    Enum.map(values, &strip_realized_snapshot_model_limits/1)
  end

  defp strip_realized_snapshot_model_limits(value), do: value

  defp baseline_branch_id(branch_maps) do
    case Enum.find(branch_maps, &(&1["branch_id"] == "baseline")) do
      nil -> nil
      branch -> branch["branch_id"]
    end
  end

  defp update_candidate_activities(plan, fun) do
    Map.update(plan, "candidate_activities", [], fn activities ->
      activities
      |> Enum.map(&stringify_keys/1)
      |> fun.()
    end)
  end

  defp apply_downlink_capacity(activity, event) do
    activity = stringify_keys(activity)

    if downlink_activity?(activity) and branch_event_activity_match?(activity, event) and
         event_overlap?(activity, event) do
      fraction = ground_network_capacity_fraction(event)
      score = candidate_score(activity) * fraction

      activity
      |> Map.put("score", score)
      |> Map.put("capacity_fraction", fraction)
      |> put_station_capacity(fraction)
      |> Map.update("score_terms", %{}, fn terms ->
        Map.put(terms, "capacity_factor", fraction)
      end)
    else
      activity
    end
  end

  defp put_station_capacity(activity, 1.0), do: activity

  defp put_station_capacity(activity, capacity_fraction) do
    activity
    |> Map.put("station_capacity_fraction", capacity_fraction)
    |> Map.update(
      "throughput_model",
      %{"station_capacity_fraction" => capacity_fraction},
      fn model ->
        Map.put(model, "station_capacity_fraction", capacity_fraction)
      end
    )
  end

  defp ground_station_event_match?(activity, event) do
    activity = stringify_keys(activity)

    station_event_suppressed_activity?(activity) and branch_event_activity_match?(activity, event) and
      event_overlap?(activity, event)
  end

  defp station_event_suppressed_activity?(activity) do
    type = Map.get(activity, "type") || Map.get(activity, "activity_type")
    direction = activity_direction(activity)

    downlink_activity?(activity) or
      type in ["tracking", "health_check"] or
      (type in ["planned_contact", "contact"] and direction in ["tracking", "health_check"])
  end

  defp branch_event_activity_match?(activity, event) do
    event_station_id = event_ground_station_id(event)

    station_match? =
      is_nil(event_station_id) or activity_ground_station_id(activity) == event_station_id

    scenario_match? =
      is_nil(event["scenario_id"]) or activity["scenario_id"] == event["scenario_id"]

    station_match? and scenario_match?
  end

  defp event_ground_station_id(event) do
    case encode_value(
           Map.get(event, "ground_station_id") || Map.get(event, "station_id") ||
             nested_ground_station_id(event)
         ) do
      value when is_binary(value) and value != "" -> value
      _value -> nil
    end
  end

  defp event_overlap?(activity, event) do
    event_start = Map.get(event, "starts_at_s", activity_start(activity))
    event_end = Map.get(event, "ends_at_s", activity_end(activity))
    activity_start(activity) < event_end and event_start < activity_end(activity)
  end

  defp merge_realized_state(realized_state, overrides) do
    overrides = normalize_realized_state(overrides || %{})

    %{
      "activities" =>
        merge_by_id(
          Map.get(realized_state, "activities", []),
          Map.get(overrides, "activities", [])
        ),
      "spacecraft_states" =>
        merge_spacecraft_states(
          Map.get(realized_state, "spacecraft_states", []),
          Map.get(overrides, "spacecraft_states", [])
        ),
      "metadata" =>
        Map.merge(Map.get(realized_state, "metadata", %{}), Map.get(overrides, "metadata", %{}))
    }
  end

  defp mission_state_repair_state(mission_state) do
    %{
      "activities" => Map.get(mission_state, "realized_activities", []),
      "spacecraft_states" => degraded_spacecraft_states(mission_state),
      "metadata" => %{
        "mission_state_snapshot_id" => Map.get(mission_state, "snapshot_id")
      }
    }
  end

  defp degraded_spacecraft_states(mission_state) do
    mission_state
    |> degraded_spacecraft_branch_states()
    |> merge_spacecraft_states([])
  end

  defp degraded_spacecraft_branch_states(mission_state) do
    spacecraft_states =
      mission_state
      |> Map.get("spacecraft_states", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(&normalize_degraded_spacecraft_state/1)
      |> Enum.filter(fn state ->
        Map.get(state, "mode") in ["degraded", "degraded_mode", "safe"] or
          truthy?(Map.get(state, "degraded")) or
          not is_nil(Map.get(state, "incompatible_activity_types"))
      end)

    degradation_states =
      mission_state
      |> Map.get("degradations", [])
      |> Enum.map(&stringify_keys/1)
      |> Enum.map(fn degradation ->
        %{
          "scenario_id" => degraded_state_identity(degradation),
          "mode" => degraded_state_mode(degradation, "degraded"),
          "incompatible_activity_types" =>
            degradation
            |> degradation_activity_types()
            |> normalize_incompatible_activity_types(),
          "source" => "mission_state.degradations"
        }
      end)

    resource_degradation_states = resource_summary_degradation_states(mission_state)

    (spacecraft_states ++ degradation_states ++ resource_degradation_states)
    |> Enum.reject(&(Map.get(&1, "scenario_id") in [nil, ""]))
  end

  defp degradation_activity_types(degradation) do
    explicit =
      Map.get(degradation, "incompatible_activity_types") ||
        Map.get(degradation, "suppressed_activity_types")

    cond do
      explicit not in [nil, []] ->
        explicit

      Map.get(degradation, "spacecraft_available") == false or
          Map.get(degradation, "spacecraft_availability") == false ->
        ["downlink", "observe", "planned_contact"]

      true ->
        ["observe"]
    end
  end

  defp degraded_event_mode(event) do
    case encode_value(Map.get(event, "mode", "degraded")) do
      value when value in [nil, ""] -> "degraded"
      value -> value
    end
  end

  defp branch_event_spacecraft_id(event) do
    case encode_value(Map.get(event, "spacecraft_id") || Map.get(event, "scenario_id")) do
      value when value in [nil, ""] -> nil
      value -> value
    end
  end

  defp normalize_degraded_spacecraft_state(state) do
    explicit =
      Map.get(state, "incompatible_activity_types") ||
        Map.get(state, "suppressed_activity_types")

    normalized =
      state
      |> normalize_resource_availability_aliases()
      |> copy_resource_availability_status_alias("spacecraft_available", "status")
      |> normalize_spacecraft_state_booleans()
      |> normalize_degraded_spacecraft_state_identity()
      |> put_degraded_state_mode(state)

    normalized
    |> put_normalized_degraded_activity_types(
      explicit || inferred_degraded_state_activity_types(normalized)
    )
  end

  defp inferred_degraded_state_activity_types(state) do
    cond do
      Map.get(state, "spacecraft_available") == false or
          Map.get(state, "spacecraft_availability") == false ->
        ["downlink", "observe", "planned_contact"]

      Map.get(state, "payload_available") == false or Map.get(state, "antenna_available") == false ->
        []
        |> maybe_append_branch_event(Map.get(state, "payload_available") == false, "observe")
        |> maybe_append_branch_event(Map.get(state, "antenna_available") == false, "downlink")
        |> maybe_append_branch_event(
          Map.get(state, "antenna_available") == false,
          "planned_contact"
        )

      true ->
        nil
    end
  end

  defp normalize_degraded_spacecraft_state_identity(state) do
    ["scenario_id", "spacecraft_id", "id"]
    |> Enum.reduce(state, fn field, acc ->
      case encode_value(Map.get(acc, field)) do
        value when value in [nil, ""] -> acc
        value -> Map.put(acc, field, value)
      end
    end)
  end

  defp put_normalized_degraded_activity_types(state, explicit) when explicit in [nil, []],
    do: state

  defp put_normalized_degraded_activity_types(state, explicit) do
    Map.put(state, "incompatible_activity_types", normalize_incompatible_activity_types(explicit))
  end

  defp put_degraded_state_mode(state, source_state) do
    case degraded_state_mode(source_state, Map.get(source_state, "mode")) do
      nil -> Map.delete(state, "mode")
      mode -> Map.put(state, "mode", mode)
    end
  end

  defp degraded_state_identity(state) do
    case encode_value(
           Map.get(state, "scenario_id") || Map.get(state, "spacecraft_id") ||
             Map.get(state, "id")
         ) do
      value when value in [nil, ""] -> nil
      value -> value
    end
  end

  defp degraded_state_mode(state, default) do
    case encode_value(Map.get(state, "mode", default)) do
      value when value in [nil, ""] -> default
      value -> value
    end
  end

  defp resource_summary_degradation_states(mission_state) do
    mission_state
    |> mission_state_resource_summary_inputs()
    |> Enum.map(&stringify_keys/1)
    |> Enum.map(&normalize_resource_availability_aliases/1)
    |> Enum.map(&normalize_spacecraft_state_booleans/1)
    |> Enum.filter(fn summary ->
      Map.get(summary, "mode") in ["degraded", "degraded_mode", "safe"] or
        truthy?(Map.get(summary, "degraded")) or
        Map.get(summary, "spacecraft_available") == false or
        Map.get(summary, "spacecraft_availability") == false or
        not is_nil(Map.get(summary, "incompatible_activity_types"))
    end)
    |> Enum.map(fn summary ->
      %{
        "scenario_id" =>
          Map.get(summary, "scenario_id") || Map.get(summary, "spacecraft_id") ||
            Map.get(summary, "id"),
        "mode" => Map.get(summary, "mode", "degraded"),
        "degraded" => Map.get(summary, "degraded", true),
        "spacecraft_available" => Map.get(summary, "spacecraft_available"),
        "payload_available" => Map.get(summary, "payload_available"),
        "antenna_available" => Map.get(summary, "antenna_available"),
        "incompatible_activity_types" => degradation_incompatible_activity_types(summary),
        "source" => mission_state_resource_source_path(mission_state, "degraded")
      }
    end)
  end

  defp degradation_incompatible_activity_types(state) do
    explicit =
      Map.get(state, "incompatible_activity_types") ||
        Map.get(state, "suppressed_activity_types")

    cond do
      explicit not in [nil, []] ->
        normalize_incompatible_activity_types(explicit)

      Map.get(state, "spacecraft_available") == false or
          Map.get(state, "spacecraft_availability") == false ->
        ["downlink", "observe", "planned_contact"]

      Map.get(state, "payload_available") == false or Map.get(state, "antenna_available") == false ->
        []
        |> maybe_append_branch_event(Map.get(state, "payload_available") == false, "observe")
        |> maybe_append_branch_event(Map.get(state, "antenna_available") == false, "downlink")
        |> maybe_append_branch_event(
          Map.get(state, "antenna_available") == false,
          "planned_contact"
        )
        |> Enum.reverse()

      true ->
        ["observe"]
    end
  end

  defp merge_by_id(left, right) do
    (left ++ right)
    |> Enum.map(&stringify_keys/1)
    |> Enum.sort_by(&{&1["id"], &1["status"] || "", &1["reason"] || ""})
  end

  defp merge_spacecraft_states(left, right) do
    (left ++ right)
    |> normalize_realized_spacecraft_states()
    |> elem(0)
    |> Map.new(fn item -> {Map.get(item, "scenario_id"), item} end)
    |> Map.values()
    |> Enum.sort_by(& &1["scenario_id"])
  end

  defp add_realized_activity(realized_state, activity) do
    activity = normalize_realized_activity(activity)

    Map.update!(realized_state, "activities", fn activities ->
      merge_by_id(activities, [activity])
    end)
  end

  defp add_spacecraft_state(realized_state, spacecraft_state) do
    spacecraft_state = stringify_keys(spacecraft_state)

    Map.update!(realized_state, "spacecraft_states", fn states ->
      merge_spacecraft_states(states, [spacecraft_state])
    end)
  end

  defp default_strategy_horizon(request) do
    remaining_horizon(request.prior_plan, request.remaining_horizon, request.current_epoch_s)
  end

  defp first_scenario_id(request) do
    request.prior_plan
    |> Map.get("activities", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.find_value(& &1["scenario_id"]) || "unspecified_spacecraft"
  end

  defp maybe_add_no_downlink_risk(risks, candidate_plan, request) do
    requires_downlink? =
      request.mission_state
      |> Map.get("objectives", [])
      |> Enum.any?(&(Map.get(&1, "type") == "downlink_completion"))

    has_downlink? = Enum.any?(candidate_plan["activities"], &downlink_activity?/1)

    if requires_downlink? and not has_downlink? do
      [
        %{
          "type" => "no_viable_downlink",
          "severity" => "high",
          "reason" => "branch has no downlink activity"
        }
        | risks
      ]
    else
      risks
    end
  end

  defp maybe_add_unmet_priority_commitment_risk(risks, candidate_plan, request) do
    request.mission_state
    |> priority_commitment_satisfaction_rows(Map.get(candidate_plan, "activities", []))
    |> Enum.reject(&(&1["status"] == "satisfied"))
    |> Enum.reduce(risks, fn row, acc ->
      [
        %{
          "type" => "priority_commitment_unmet",
          "severity" => "medium",
          "reason" =>
            "target #{row["target_id"]} planned observations #{row["planned_observations"]} below required #{row["required_observations"]}",
          "target_id" => row["target_id"],
          "objective_id" => row["objective_id"],
          "required_observations" => row["required_observations"],
          "planned_observations" => row["planned_observations"],
          "missing_observations" => row["missing_observations"]
        }
        |> compact_map()
        | acc
      ]
    end)
  end

  defp target_count(activities) do
    activities
    |> Enum.filter(&(&1["type"] == "observe"))
    |> Enum.map(& &1["target_id"])
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> length()
  end

  defp revisit_count(activities) do
    activities
    |> Enum.filter(&(&1["type"] == "observe"))
    |> Enum.map(& &1["target_id"])
    |> Enum.frequencies()
    |> Map.values()
    |> Enum.map(&max(&1 - 1, 0))
    |> Enum.sum()
  end

  defp collection_latency_s(activities) do
    observations = Enum.filter(activities, &(&1["type"] == "observe"))
    downlinks = Enum.filter(activities, &downlink_activity?/1)

    observations
    |> Enum.map(fn observation ->
      downlinks
      |> Enum.filter(fn downlink ->
        downlink["scenario_id"] == observation["scenario_id"] and
          activity_start(downlink) >= activity_end(observation)
      end)
      |> Enum.map(&(activity_start(&1) - activity_end(observation)))
      |> Enum.min(fn -> 0.0 end)
    end)
    |> Enum.sum()
  end

  defp downlink_completion_ratio(activities, request) do
    activities
    |> downlink_completion_satisfaction(request)
    |> Map.get("ratio", 0.0)
  end

  defp required_downlink_contacts(objective, prior_plan) do
    case objective do
      %{"objectives" => _objectives} = mission_state ->
        case downlink_completion_objectives(mission_state) do
          [] ->
            max(1, planned_downlink_count(prior_plan))

          objectives ->
            objectives
            |> Enum.map(&required_downlink_contacts(&1, prior_plan))
            |> Enum.sum()
        end

      %{} = objective ->
        case objective_required_downlink_contact_count(objective) do
          value when is_number(value) -> normalize_required_contact_count(value)
          _value -> max(1, planned_downlink_count(prior_plan))
        end

      _objective ->
        max(1, planned_downlink_count(prior_plan))
    end
  end

  defp objective_required_downlink_contact_count(objective) do
    explicit =
      objective
      |> objective_number_from_fields([
        "required_contacts",
        "required_contact_count",
        "expected_contact_count",
        "required_downlink_contacts",
        "required_downlink_contact_count",
        "target_contact_count",
        "target_downlink_contact_count",
        "min_contact_count",
        "minimum_contact_count"
      ])

    cond do
      is_number(explicit) ->
        explicit

      contact_count = objective_required_downlink_contact_identity_count(objective) ->
        contact_count

      true ->
        nil
    end
  end

  defp objective_required_downlink_contact_identity_count(objective) do
    [
      objective["required_downlink_contact_ids"],
      objective["required_downlink_contact_id"],
      objective["required_contact_ids"],
      objective["required_contact_id"],
      objective["expected_contact_ids"],
      objective["expected_contact_id"],
      objective["contacts"],
      objective["downlink_contacts"]
    ]
    |> Enum.flat_map(&objective_required_downlink_contact_identities/1)
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> case do
      [] -> nil
      contacts -> length(contacts)
    end
  end

  defp objective_required_downlink_contact_identities(values) when is_list(values) do
    Enum.flat_map(values, &objective_required_downlink_contact_identities/1)
  end

  defp objective_required_downlink_contact_identities(%{} = contact) do
    contact = stringify_keys(contact)

    [
      contact["contact_id"],
      contact["downlink_activity_id"],
      contact["activity_id"],
      contact["id"]
    ]
  end

  defp objective_required_downlink_contact_identities(value), do: [encode_value(value)]

  defp objective_required_downlink_mb(%{} = objective) do
    objective
    |> objective_number_from_fields([
      "required_downlink_mb",
      "target_downlink_mb",
      "downlink_requirement_mb",
      "required_throughput_mb",
      "required_volume_mb",
      "required_data_volume_mb",
      "target_volume_mb",
      "target_data_volume_mb",
      "min_downlink_mb"
    ])
    |> case do
      value when is_number(value) -> max(value * 1.0, 0.0)
      _value -> nil
    end
  end

  defp objective_required_downlink_mb(_objective), do: nil

  defp normalize_required_contact_count(count) when is_number(count) do
    if count == trunc(count), do: trunc(count), else: count
  end

  defp downlink_completion_objectives(mission_state) do
    mission_state
    |> Map.get("objectives", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(fn
      %{"type" => type} when type in ["downlink_completion", "required_downlink_completion"] ->
        true

      _objective ->
        false
    end)
  end

  defp downlink_objective?(mission_state) do
    mission_state
    |> Map.get("objectives", [])
    |> Enum.any?(fn
      %{"type" => type} when type in ["downlink_completion", "required_downlink_completion"] ->
        true

      _objective ->
        false
    end)
  end

  defp planned_downlink_count(prior_plan, objective \\ nil) do
    prior_plan_activities(prior_plan)
    |> Enum.map(&stringify_keys/1)
    |> Enum.count(
      &(downlink_activity?(&1) and downlink_completion_event_match?(&1, objective || %{}))
    )
  end

  defp planned_downlink_mb(prior_plan_or_activities, objective) do
    prior_plan_or_activities
    |> prior_plan_activities()
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(
      &(downlink_activity?(&1) and downlink_completion_event_match?(&1, objective || %{}))
    )
    |> Enum.map(&downlink_activity_mb/1)
    |> Enum.sum()
  end

  defp prior_plan_activities(activities) when is_list(activities), do: activities

  defp prior_plan_activities(%{} = prior_plan) do
    prior_plan = stringify_keys(prior_plan)

    case activity_rows(Map.get(prior_plan, "activities")) do
      [] -> prior_plan_result_artifact_activity_rows(prior_plan)
      rows -> normalize_activity_rows(rows)
    end
  end

  defp prior_plan_activities(_prior_plan), do: []

  defp prior_plan_result_artifact_activity_rows(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, _source_path} ->
      artifact
      |> Map.get("activities")
      |> activity_rows()
      |> normalize_activity_rows()
      |> Enum.map(&put_inherited_result_artifact_trust_boundary(&1, artifact))
    end)
  end

  defp activity_rows(rows) when is_list(rows), do: rows
  defp activity_rows(_rows), do: []

  defp normalize_activity_rows(rows) do
    Enum.map(rows, &stringify_keys/1)
  end

  defp prior_plan_proposed_contacts(%{} = prior_plan) do
    prior_plan = stringify_keys(prior_plan)

    case proposed_contact_rows(Map.get(prior_plan, "proposed_contacts")) do
      [] -> prior_plan_result_artifact_proposed_contact_rows(prior_plan)
      rows -> normalize_activity_rows(rows)
    end
  end

  defp prior_plan_proposed_contacts(_prior_plan), do: []

  defp prior_plan_result_artifact_proposed_contact_rows(prior_plan) do
    prior_plan
    |> prior_plan_result_artifacts_with_source()
    |> Enum.flat_map(fn {artifact, _source_path} ->
      artifact
      |> Map.get("proposed_contacts")
      |> proposed_contact_rows()
      |> normalize_activity_rows()
      |> Enum.map(&put_inherited_result_artifact_trust_boundary(&1, artifact))
    end)
  end

  defp proposed_contact_rows(rows) when is_list(rows), do: rows
  defp proposed_contact_rows(_rows), do: []

  defp downlink_completion_satisfaction(activities, request) do
    objectives =
      case downlink_completion_objectives(request.mission_state) do
        [] -> [nil]
        objectives -> objectives
      end

    objectives
    |> Enum.map(&downlink_completion_objective_satisfaction(activities, request, &1))
    |> aggregate_downlink_completion_satisfaction()
  end

  defp downlink_completion_objective_satisfaction(activities, request, objective) do
    required_contacts =
      if is_nil(objective) do
        required_downlink_contacts(request.mission_state, request.prior_plan)
      else
        required_downlink_contacts(objective, request.prior_plan)
      end

    required_downlink_mb = objective_required_downlink_mb(objective || %{})
    planned_contacts = planned_downlink_count(activities, objective)
    planned_downlink_mb = planned_downlink_mb(activities, objective)

    ratio =
      downlink_completion_objective_ratio(
        planned_contacts,
        required_contacts,
        planned_downlink_mb,
        required_downlink_mb,
        objective
      )

    %{
      "required_contacts" => required_contacts,
      "planned_contacts" => planned_contacts,
      "required_downlink_mb" => required_downlink_mb,
      "planned_downlink_mb" => planned_downlink_mb,
      "ratio" => ratio
    }
    |> compact_map()
  end

  defp aggregate_downlink_completion_satisfaction(rows) do
    required_downlink_mbs =
      rows
      |> Enum.map(&Map.get(&1, "required_downlink_mb"))
      |> Enum.filter(&is_number/1)

    %{
      "required_contacts" => sum_number_field(rows, "required_contacts"),
      "planned_contacts" => sum_number_field(rows, "planned_contacts"),
      "required_downlink_mb" =>
        if(required_downlink_mbs == [], do: nil, else: Enum.sum(required_downlink_mbs)),
      "planned_downlink_mb" => sum_number_field(rows, "planned_downlink_mb"),
      "ratio" =>
        rows
        |> Enum.map(&Map.get(&1, "ratio", 0.0))
        |> average_ratio()
    }
    |> compact_map()
  end

  defp sum_number_field(rows, field) do
    rows
    |> Enum.map(&Map.get(&1, field, 0))
    |> Enum.filter(&is_number/1)
    |> Enum.sum()
  end

  defp average_ratio([]), do: 0.0

  defp average_ratio(values) do
    Enum.sum(values) / length(values)
  end

  defp downlink_completion_objective_ratio(
         planned_contacts,
         required_contacts,
         planned_downlink_mb,
         required_downlink_mb,
         objective
       ) do
    contact_ratio =
      if downlink_contact_requirement_declared?(objective) or
           not (is_number(required_downlink_mb) and required_downlink_mb > 0.0) do
        min(planned_contacts / max(required_contacts, 1), 1.0)
      end

    mb_ratio =
      if is_number(required_downlink_mb) and required_downlink_mb > 0.0 do
        min(planned_downlink_mb / required_downlink_mb, 1.0)
      end

    [contact_ratio, mb_ratio]
    |> Enum.reject(&is_nil/1)
    |> Enum.min(fn -> 0.0 end)
  end

  defp downlink_contact_requirement_declared?(%{} = objective),
    do: is_number(numeric_or_nil(Map.get(objective, "required_contacts")))

  defp downlink_contact_requirement_declared?(_objective), do: true

  defp downlink_activity_mb(activity) do
    activity_capacity = numeric_or_nil(Map.get(activity, "capacity_adjusted_throughput_mb"))

    model_capacity =
      numeric_or_nil(get_in(activity, ["throughput_model", "capacity_adjusted_throughput_mb"]))

    cond do
      is_number(activity_capacity) ->
        activity_capacity * 1.0

      is_number(model_capacity) ->
        model_capacity * 1.0

      true ->
        throughput_mb =
          numeric_or_nil(Map.get(activity, "estimated_throughput_mb")) ||
            numeric_or_nil(Map.get(activity, "planned_throughput_mb")) || 0.0

        station_capacity_fraction =
          numeric_or_nil(get_in(activity, ["throughput_model", "station_capacity_fraction"])) ||
            numeric_or_nil(Map.get(activity, "station_capacity_fraction")) || 1.0

        throughput_mb * station_capacity_fraction
    end
  end

  defp candidate_score(candidate), do: numeric_or_nil(Map.get(candidate, "score")) || 0.0

  defp event_priority(event, default), do: numeric_or_nil(Map.get(event, "priority")) || default

  defp fuel_preservation_score(branch, request) do
    fuel_mode? = Enum.any?(branch["events"], &(&1["type"] == "fuel_preservation_mode"))

    fuel_margin =
      request.mission_state
      |> get_in(["resources", "fuel_margin"])
      |> case do
        nil -> 1.0
        value -> value
      end

    if fuel_mode?, do: fuel_margin, else: fuel_margin * 0.25
  end

  defp branch_resource_impacts(candidate_plan, branch, request) do
    resources =
      request.mission_state
      |> Map.get("resources", %{})
      |> stringify_keys()

    activities = Map.get(candidate_plan, "activities", [])
    downlinks = Enum.filter(activities, &downlink_activity?/1)
    observations = Enum.filter(activities, &(&1["type"] == "observe"))

    fuel_margin_source =
      mission_state_lowest_resource_margin_source(request.mission_state, "fuel_margin")

    power_margin_source =
      mission_state_lowest_resource_margin_source(request.mission_state, "power_margin")

    storage_margin_source =
      mission_state_lowest_resource_margin_source(request.mission_state, "storage_margin")

    downlink_margin_source =
      mission_state_lowest_resource_margin_source(request.mission_state, "downlink_margin")

    thermal_margin_source =
      mission_state_lowest_resource_margin_source(request.mission_state, "thermal_margin_c")

    fuel_margin =
      branch_resource_margin(branch, "fuel_margin") ||
        resource_source_margin(fuel_margin_source, "fuel_margin") ||
        resource_margin(resources, "fuel_margin")

    power_margin =
      branch_resource_margin(branch, "power_margin") ||
        resource_source_margin(power_margin_source, "power_margin") ||
        resource_margin(resources, "power_margin")

    storage_margin =
      branch_resource_margin(branch, "storage_margin") ||
        resource_source_margin(storage_margin_source, "storage_margin") ||
        storage_margin(resources, observations)

    downlink_margin =
      branch_resource_margin(branch, "downlink_margin") ||
        resource_source_margin(downlink_margin_source, "downlink_margin") ||
        downlink_margin(resources, downlinks, request)

    thermal_margin =
      branch_resource_margin(branch, "thermal_margin_c") ||
        resource_source_margin(thermal_margin_source, "thermal_margin_c") ||
        resource_margin(resources, "thermal_margin_c")

    thermal_margin_threshold =
      branch_resource_margin_threshold(branch, "thermal_margin_c") ||
        request.mission_state
        |> get_in([
          "candidate_refresh_defaults",
          "resource_filter_policy",
          "min_activity_thermal_margin_c"
        ])
        |> numeric_or_nil()

    spacecraft_availability =
      branch_spacecraft_availability(branch) ||
        resource_spacecraft_availability(request.mission_state) ||
        spacecraft_availability(request.mission_state)

    payload_availability =
      branch_resource_availability(branch, "payload_available") ||
        resource_boolean_availability(request.mission_state, "payload_available") ||
        payload_availability(request.mission_state)

    antenna_availability =
      branch_resource_availability(branch, "antenna_available") ||
        resource_boolean_availability(request.mission_state, "antenna_available") ||
        antenna_availability(request.mission_state)

    risk_indicators =
      []
      |> maybe_resource_risk(
        "fuel_margin_low",
        fuel_margin,
        0.25,
        "fuel margin below thin-model threshold"
      )
      |> maybe_resource_risk(
        "power_margin_low",
        power_margin,
        0.2,
        "power margin below thin-model threshold"
      )
      |> maybe_resource_risk(
        "storage_margin_low",
        storage_margin,
        0.2,
        "onboard storage margin below thin-model threshold"
      )
      |> maybe_resource_risk(
        "downlink_capacity_low",
        downlink_margin,
        0.75,
        "downlink capacity margin below required completion target"
      )
      |> maybe_resource_risk(
        "thermal_margin_low",
        thermal_margin,
        thermal_margin_threshold,
        "thermal margin below externally supplied policy threshold"
      )
      |> maybe_resource_risk(
        "spacecraft_availability_low",
        spacecraft_availability,
        1.0,
        "one or more spacecraft unavailable or degraded"
      )
      |> maybe_resource_risk(
        "payload_availability_low",
        payload_availability,
        1.0,
        "payload availability reduced by mission state"
      )
      |> maybe_resource_risk(
        "antenna_availability_low",
        antenna_availability,
        1.0,
        "antenna availability reduced by mission state"
      )

    score_adjustment =
      resource_margin_score(fuel_margin, 0.25) +
        resource_margin_score(power_margin, 0.2) +
        resource_margin_score(storage_margin, 0.2) +
        resource_margin_score(downlink_margin, 0.75) +
        resource_margin_score(thermal_margin, thermal_margin_threshold) +
        resource_margin_score(spacecraft_availability, 1.0) +
        resource_margin_score(payload_availability, 1.0) +
        resource_margin_score(antenna_availability, 1.0)

    warnings =
      Enum.map(risk_indicators, fn risk -> risk["reason"] end)

    %{
      "model" => "thin_mission_state_resource_summary",
      "fuel_margin" => fuel_margin,
      "power_margin" => power_margin,
      "storage_margin" => storage_margin,
      "downlink_capacity_margin" => downlink_margin,
      "thermal_margin_c" => thermal_margin,
      "spacecraft_availability" => spacecraft_availability,
      "payload_availability" => payload_availability,
      "antenna_availability" => antenna_availability,
      "fuel_preservation_mode" =>
        Enum.any?(branch["events"], &(&1["type"] == "fuel_preservation_mode")),
      "score_adjustment" => score_adjustment,
      "risk_indicators" => risk_indicators,
      "warnings" => warnings
    }
  end

  defp resource_margin(resources, key) do
    case numeric_or_nil(Map.get(resources, key)) do
      value when is_number(value) -> value
      _value -> nil
    end
  end

  defp resource_source_margin(nil, _field), do: nil

  defp resource_source_margin(source, field) do
    case numeric_or_nil(Map.get(source, field)) do
      value when is_number(value) -> value
      _value -> nil
    end
  end

  defp branch_resource_margin(branch, field) do
    branch
    |> Map.get("events", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.find_value(fn event ->
      if event["type"] == "resource_margin_pressure" and event["resource_field"] == field do
        numeric_or_nil(event[field])
      end
    end)
  end

  defp branch_resource_margin_threshold(branch, field) do
    branch
    |> Map.get("events", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.find_value(fn event ->
      if event["type"] == "resource_margin_pressure" and event["resource_field"] == field do
        numeric_or_nil(event["#{field}_threshold"])
      end
    end)
  end

  defp branch_spacecraft_availability(branch) do
    branch
    |> Map.get("events", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.any?(fn event ->
      event["type"] == "degraded_spacecraft" or
        (event["type"] == "resource_availability_constraint" and
           event["resource_field"] in ["spacecraft_available", "spacecraft_availability"] and
           event["available"] == false)
    end)
    |> case do
      true -> 0.0
      false -> nil
    end
  end

  defp storage_margin(resources, observations) do
    storage_capacity_mb = numeric_or_nil(Map.get(resources, "storage_capacity_mb"))
    storage_used_mb = numeric_or_nil(Map.get(resources, "storage_used_mb"))

    cond do
      is_number(numeric_or_nil(Map.get(resources, "storage_margin"))) ->
        numeric_or_nil(Map.get(resources, "storage_margin"))

      is_number(storage_capacity_mb) and storage_capacity_mb > 0.0 and is_number(storage_used_mb) ->
        produced_mb =
          observations
          |> Enum.map(
            &(get_in(&1, ["metadata", "estimated_storage_mb"]) ||
                Map.get(&1, "estimated_storage_mb", 0.0))
          )
          |> Enum.sum()

        max(
          (storage_capacity_mb - storage_used_mb - produced_mb) /
            storage_capacity_mb,
          0.0
        )

      true ->
        nil
    end
  end

  defp downlink_margin(resources, downlinks, request) do
    downlink_capacity_mb = numeric_or_nil(Map.get(resources, "downlink_capacity_mb"))

    cond do
      is_number(numeric_or_nil(Map.get(resources, "downlink_margin"))) ->
        numeric_or_nil(Map.get(resources, "downlink_margin"))

      is_number(downlink_capacity_mb) and downlink_objective?(request.mission_state) ->
        required_contacts =
          max(required_downlink_contacts(request.mission_state, request.prior_plan), 1)

        planned_contacts = max(length(downlinks), 1)
        min(downlink_capacity_mb / required_contacts / planned_contacts, 1.0)

      downlink_objective?(request.mission_state) ->
        downlink_completion_ratio(downlinks, request)

      true ->
        nil
    end
  end

  defp resource_spacecraft_availability(mission_state) do
    if resource_availability_source_present?(mission_state, "degraded") or
         resource_availability_source_present?(mission_state, "mode") or
         resource_availability_source_present?(mission_state, "spacecraft_available") do
      source_inputs =
        mission_state
        |> mission_state_resource_summary_inputs()
        |> Enum.map(&normalize_resource_availability_aliases/1)

      summaries =
        mission_state
        |> mission_state_resource_metric_sources()
        |> Enum.map(&normalize_resource_availability_aliases/1)
        |> Enum.zip(source_inputs)
        |> Enum.filter(fn {_summary, source_input} ->
          resource_spacecraft_availability_summary?(source_input)
        end)
        |> Enum.map(fn {summary, _source_input} -> summary end)

      if summaries == [] do
        nil
      else
        available =
          Enum.count(summaries, fn summary ->
            summary = stringify_keys(summary)

            Map.get(summary, "spacecraft_available", true) != false and
              Map.get(summary, "mode", "nominal") not in ["degraded", "degraded_mode", "safe"] and
              not truthy?(Map.get(summary, "degraded"))
          end)

        available / length(summaries)
      end
    end
  end

  defp resource_spacecraft_availability_summary?(summary) do
    Map.has_key?(summary, "spacecraft_available") or Map.has_key?(summary, "degraded") or
      Map.has_key?(summary, "mode")
  end

  defp resource_boolean_availability(mission_state, field) do
    if resource_availability_source_present?(mission_state, field) do
      values =
        mission_state
        |> mission_state_resource_metric_sources()
        |> Enum.map(&normalize_resource_availability_aliases/1)
        |> Enum.map(&Map.get(&1, field))
        |> Enum.filter(&is_boolean/1)

      if values == [] do
        nil
      else
        Enum.count(values, & &1) / length(values)
      end
    end
  end

  defp resource_availability_source_present?(mission_state, field) do
    explicit_mission_state_resource_summaries?(mission_state) or
      mission_state
      |> Map.get("resources", %{})
      |> stringify_keys()
      |> resource_source_has_field?(field)
  end

  defp resource_source_has_field?(resources, field) when is_map(resources) do
    normalized_resources = normalize_resource_availability_aliases(resources)

    Map.has_key?(normalized_resources, field) or
      resources
      |> mission_state_nested_resource_sources()
      |> Enum.any?(fn
        %{} = source ->
          source
          |> normalize_resource_availability_aliases()
          |> Map.has_key?(field)

        _source ->
          false
      end)
  end

  defp resource_source_has_field?(_resources, _field), do: false

  defp branch_resource_availability(branch, field) do
    branch
    |> Map.get("events", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.any?(fn event ->
      branch_resource_unavailable_event?(event, field)
    end)
    |> case do
      true -> 0.0
      false -> nil
    end
  end

  defp branch_resource_unavailable_event?(
         %{"type" => "resource_availability_constraint"} = event,
         field
       ) do
    event["resource_field"] == field and event["available"] == false
  end

  defp branch_resource_unavailable_event?(%{"type" => "degraded_spacecraft"} = event, field) do
    incompatible_types =
      (Map.get(event, "incompatible_activity_types") ||
         Map.get(event, "suppressed_activity_types") || [])
      |> normalize_incompatible_activity_types()

    case field do
      "payload_available" ->
        "observe" in incompatible_types

      "antenna_available" ->
        Enum.any?(incompatible_types, &(&1 in ["downlink", "planned_contact"]))

      _field ->
        false
    end
  end

  defp branch_resource_unavailable_event?(_event, _field), do: false

  defp spacecraft_availability(mission_state) do
    states = Map.get(mission_state, "spacecraft_states", [])

    if states == [] do
      1.0
    else
      available =
        Enum.count(states, fn state ->
          state =
            state
            |> stringify_keys()
            |> normalize_resource_availability_aliases()
            |> copy_resource_availability_status_alias("spacecraft_available", "status")

          Map.get(state, "spacecraft_available", true) != false and
            Map.get(state, "mode", "nominal") not in ["degraded", "degraded_mode", "safe"] and
            not truthy?(Map.get(state, "degraded"))
        end)

      available / length(states)
    end
  end

  defp payload_availability(mission_state) do
    states = Map.get(mission_state, "spacecraft_states", [])

    if states == [] do
      1.0
    else
      available =
        Enum.count(states, fn state ->
          state =
            state
            |> stringify_keys()
            |> normalize_resource_availability_aliases()

          Map.get(state, "payload_available", true) != false and
            not truthy?(Map.get(state, "payload_degraded"))
        end)

      available / length(states)
    end
  end

  defp antenna_availability(mission_state) do
    states = Map.get(mission_state, "spacecraft_states", [])

    if states == [] do
      1.0
    else
      available =
        Enum.count(states, fn state ->
          state =
            state
            |> stringify_keys()
            |> normalize_resource_availability_aliases()

          Map.get(state, "antenna_available", true) != false and
            not truthy?(Map.get(state, "antenna_degraded"))
        end)

      available / length(states)
    end
  end

  defp maybe_resource_risk(risks, _type, nil, _threshold, _reason), do: risks
  defp maybe_resource_risk(risks, _type, _value, nil, _reason), do: risks

  defp maybe_resource_risk(risks, type, value, threshold, reason) when value < threshold do
    [%{"type" => type, "severity" => "medium", "reason" => reason, "value" => value} | risks]
  end

  defp maybe_resource_risk(risks, _type, _value, _threshold, _reason), do: risks

  defp resource_margin_score(nil, _threshold), do: 0.0
  defp resource_margin_score(_value, nil), do: 0.0

  defp resource_margin_score(value, threshold) when value < threshold,
    do: -(threshold - value) * 100.0

  defp resource_margin_score(value, threshold), do: min(value - threshold, 1.0) * 10.0

  defp branch_feedback_adjustments(candidate_plan, repair_result, branch, request) do
    feedback = branch_refresh_operational_feedback(branch, request.operational_feedback)
    activities = branch_feedback_plan_activities(candidate_plan)
    source_candidate_activities = Map.get(repair_result, "source_candidate_activities", [])

    {downlink_activities, downlink_activity_source} =
      branch_feedback_activities(activities, source_candidate_activities, :downlink)

    {observation_activities, observation_activity_source} =
      branch_feedback_activities(activities, source_candidate_activities, :observe)

    contact_factor =
      average_downlink_activity_factor(
        downlink_activities,
        feedback["contact_success_rate"],
        "ground_station_id"
      )

    observation_factor =
      average_activity_factor(
        observation_activities,
        "observe",
        feedback["observation_success_rate"],
        "target_id"
      )

    image_quality_score =
      average_activity_optional_feedback_factor(
        observation_activities,
        "observe",
        feedback["image_quality_score"],
        "target_id"
      )

    image_quality_statuses =
      activity_feedback_text_values(
        observation_activities,
        "observe",
        feedback["image_quality_status"],
        "target_id"
      )

    image_quality_sources =
      activity_feedback_text_values(
        observation_activities,
        "observe",
        feedback["image_quality_source"],
        "target_id"
      )

    cloud_cover_fraction =
      average_activity_optional_feedback_factor(
        observation_activities,
        "observe",
        feedback["cloud_cover_fraction"],
        "target_id"
      )

    blur_score =
      average_activity_optional_feedback_factor(
        observation_activities,
        "observe",
        feedback["blur_score"],
        "target_id"
      )

    maneuver_factor =
      maneuver_success_factor(
        activities,
        branch,
        feedback["maneuver_success_rate"]
      )

    command_factor =
      command_success_factor(
        activities,
        feedback["command_success_rate"]
      )

    station_throughput =
      average_downlink_activity_factor(
        downlink_activities,
        feedback["station_throughput_factor"],
        "ground_station_id"
      )

    factors = [
      {"contact_success_rate", contact_factor},
      {"observation_success_rate", observation_factor},
      {"maneuver_success_rate", maneuver_factor},
      {"command_success_rate", command_factor},
      {"station_throughput_factor", station_throughput}
    ]

    risk_indicators =
      factors
      |> Enum.filter(fn {_key, value} -> is_number(value) and value < 0.8 end)
      |> Enum.map(fn {key, value} ->
        %{
          "type" => key <> "_low",
          "severity" => "medium",
          "reason" => "#{key} feedback factor #{value} reduces branch confidence",
          "value" => value
        }
      end)

    score_adjustment =
      factors
      |> Enum.map(fn {_key, value} ->
        if is_number(value), do: (value - 1.0) * 50.0, else: 0.0
      end)
      |> Enum.sum()

    feedback_weight_sources = branch_event_feedback_weight_sources(branch["events"])

    adjustments = %{
      "model" => "deterministic_success_rate_and_throughput_adjustment",
      "contact_success_factor" => contact_factor,
      "contact_success_factor_source" =>
        branch_feedback_factor_source(contact_factor, "operational_feedback.contact_success_rate"),
      "contact_success_factor_activity_source" =>
        branch_feedback_factor_source(contact_factor, downlink_activity_source),
      "observation_success_factor" => observation_factor,
      "observation_success_factor_source" =>
        branch_feedback_factor_source(
          observation_factor,
          "operational_feedback.observation_success_rate"
        ),
      "observation_success_factor_activity_source" =>
        branch_feedback_factor_source(observation_factor, observation_activity_source),
      "image_quality_score" => image_quality_score,
      "image_quality_score_source" =>
        branch_feedback_factor_source(
          image_quality_score,
          "operational_feedback.image_quality_score"
        ),
      "image_quality_statuses" => image_quality_statuses,
      "image_quality_sources" => image_quality_sources,
      "cloud_cover_fraction" => cloud_cover_fraction,
      "cloud_cover_fraction_source" =>
        branch_feedback_factor_source(
          cloud_cover_fraction,
          "operational_feedback.cloud_cover_fraction"
        ),
      "blur_score" => blur_score,
      "blur_score_source" =>
        branch_feedback_factor_source(blur_score, "operational_feedback.blur_score"),
      "maneuver_success_factor" => maneuver_factor,
      "maneuver_success_factor_source" =>
        branch_feedback_factor_source(
          maneuver_factor,
          "operational_feedback.maneuver_success_rate"
        ),
      "command_success_factor" => command_factor,
      "command_success_factor_source" =>
        branch_feedback_factor_source(command_factor, "operational_feedback.command_success_rate"),
      "station_throughput_factor" => station_throughput,
      "station_throughput_factor_source" =>
        branch_feedback_factor_source(
          station_throughput,
          "operational_feedback.station_throughput_factor"
        ),
      "station_throughput_factor_activity_source" =>
        branch_feedback_factor_source(station_throughput, downlink_activity_source),
      "score_adjustment" => score_adjustment,
      "risk_indicators" => risk_indicators,
      "branch_event_count" => length(branch["events"])
    }

    if feedback_weight_sources == [] do
      adjustments
    else
      Map.put(adjustments, "feedback_weight_sources", feedback_weight_sources)
    end
  end

  defp branch_feedback_factor_source(value, source) when is_number(value), do: source
  defp branch_feedback_factor_source(_value, _source), do: nil

  defp branch_event_feedback_weight_sources(events) when is_list(events) do
    events
    |> Enum.flat_map(&branch_event_feedback_weight_source/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp branch_event_feedback_weight_sources(_events), do: []

  defp branch_event_feedback_weight_source(%{} = event) do
    case branch_event_feedback_confidence_weight(event) do
      weight when is_number(weight) ->
        [
          event["feedback_weight_source"],
          event["feedback_sample_weight_source"],
          event["sample_weight_source"],
          event["confidence_weight_source"]
        ]
        |> Enum.map(&encode_value/1)
        |> Enum.filter(&(is_binary(&1) and &1 != ""))

      _weight ->
        []
    end
  end

  defp branch_event_feedback_weight_source(_event), do: []

  defp branch_feedback_plan_activities(candidate_plan) do
    Map.get(candidate_plan, "activities", []) ++
      Map.get(candidate_plan, "strategic_additions", [])
  end

  defp branch_feedback_activities(activities, source_candidate_activities, :downlink) do
    if Enum.any?(activities, &downlink_activity?/1) do
      {activities, "candidate_plan_activities"}
    else
      {source_candidate_activities, "branch_generated_source_candidates"}
    end
  end

  defp branch_feedback_activities(activities, source_candidate_activities, :observe) do
    if Enum.any?(activities, &(&1["type"] == "observe")) do
      {activities, "candidate_plan_activities"}
    else
      {source_candidate_activities, "branch_generated_source_candidates"}
    end
  end

  defp average_activity_factor(activities, type, rates, key) when is_map(rates) do
    matching = Enum.filter(activities, &(&1["type"] == type))

    if matching == [] do
      nil
    else
      matching
      |> Enum.map(fn activity ->
        feedback_factor(rates, [activity[key]])
      end)
      |> Enum.sum()
      |> Kernel./(length(matching))
    end
  end

  defp average_activity_factor(_activities, _type, _rates, _key), do: nil

  defp average_activity_optional_feedback_factor(activities, type, values, key)
       when is_map(values) do
    feedback_values =
      activities
      |> Enum.filter(&(&1["type"] == type))
      |> Enum.map(&optional_feedback_factor(values, &1[key]))
      |> Enum.reject(&is_nil/1)

    case feedback_values do
      [] -> nil
      values -> Enum.sum(values) / length(values)
    end
  end

  defp average_activity_optional_feedback_factor(_activities, _type, _values, _key), do: nil

  defp optional_feedback_factor(values, key) do
    cond do
      key not in [nil, ""] and is_number(Map.get(values, key)) -> Map.get(values, key)
      is_number(Map.get(values, "default")) -> Map.get(values, "default")
      true -> nil
    end
  end

  defp activity_feedback_text_values(activities, type, values, key) when is_map(values) do
    activities
    |> Enum.filter(&(&1["type"] == type))
    |> Enum.map(&feedback_text_value(values, &1[key]))
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
    |> case do
      [] -> nil
      values -> values
    end
  end

  defp activity_feedback_text_values(_activities, _type, _values, _key), do: nil

  defp feedback_text_value(values, key) do
    value =
      cond do
        key not in [nil, ""] -> Map.get(values, key) || Map.get(values, "default")
        true -> Map.get(values, "default")
      end

    case encode_value(value) do
      value when is_binary(value) and value != "" -> value
      _value -> nil
    end
  end

  defp average_downlink_activity_factor(activities, rates, key) when is_map(rates) do
    activities
    |> Enum.filter(&downlink_activity?/1)
    |> average_activity_feedback_factor(rates, key)
  end

  defp average_downlink_activity_factor(_activities, _rates, _key), do: nil

  defp average_activity_feedback_factor([], _rates, _key), do: nil

  defp average_activity_feedback_factor(activities, rates, key) do
    activities
    |> Enum.map(fn activity ->
      feedback_factor(rates, [activity[key]])
    end)
    |> Enum.sum()
    |> Kernel./(length(activities))
  end

  defp maneuver_success_factor(activities, branch, rates) when is_map(rates) do
    activity_keys =
      activities
      |> Enum.filter(&maneuver_activity?/1)
      |> Enum.map(fn activity ->
        [
          activity_id(activity),
          activity["activity_id"],
          activity["planned_activity_id"],
          explicit_timeline_id(activity),
          activity["scenario_id"]
        ]
      end)

    event_keys =
      branch
      |> Map.get("events", [])
      |> Enum.filter(
        &(Map.get(&1, "type") in [
            "missed_maneuver",
            "delayed_maneuver",
            "maneuver_success_feedback"
          ])
      )
      |> Enum.map(fn event ->
        [event["activity_id"], event["feedback_key"], event["scenario_id"]]
      end)

    case activity_keys ++ event_keys do
      [] ->
        nil

      keys ->
        keys
        |> Enum.map(&feedback_factor(rates, &1))
        |> Enum.sum()
        |> Kernel./(length(keys))
    end
  end

  defp maneuver_success_factor(_activities, _branch, _rates), do: nil

  defp command_success_factor(activities, rates) when is_map(rates) do
    activities
    |> Enum.filter(&command_activity?/1)
    |> case do
      [] ->
        nil

      command_activities ->
        command_activities
        |> Enum.map(fn activity ->
          feedback_factor(rates, [
            activity_id(activity),
            activity["activity_id"],
            activity["planned_activity_id"],
            explicit_timeline_id(activity),
            activity["scenario_id"]
          ])
        end)
        |> Enum.sum()
        |> Kernel./(length(command_activities))
    end
  end

  defp command_success_factor(_activities, _rates), do: nil

  defp feedback_factor(rates, keys) do
    keys
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.find_value(fn key ->
      value = Map.get(rates, key)
      if is_number(value), do: value
    end)
    |> case do
      nil ->
        default = Map.get(rates, "default")
        if is_number(default), do: default, else: 1.0

      value ->
        value
    end
  end

  defp branch_objective_satisfaction(candidate_plan, request) do
    activities = Map.get(candidate_plan, "activities", [])
    priority_commitments = priority_commitment_satisfaction(request.mission_state, activities)

    %{
      "priority_commitments" => priority_commitments,
      "downlink_completion" => downlink_completion_satisfaction(activities, request),
      "coverage" => %{"observed_target_count" => target_count(activities)},
      "revisit" => %{"revisit_count" => revisit_count(activities)}
    }
    |> maybe_put_collection_latency_satisfaction(activities, request.mission_state)
  end

  defp priority_commitment_satisfaction(mission_state, activities) do
    rows = priority_commitment_satisfaction_rows(mission_state, activities)

    required_target_ids =
      rows
      |> Enum.map(& &1["target_id"])
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.uniq()
      |> Enum.sort()

    satisfied_target_ids =
      rows
      |> Enum.filter(&(&1["status"] == "satisfied"))
      |> Enum.map(& &1["target_id"])
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.uniq()
      |> Enum.sort()

    missed_target_ids =
      rows
      |> Enum.reject(&(&1["status"] == "satisfied"))
      |> Enum.map(& &1["target_id"])
      |> Enum.reject(&(&1 in [nil, ""]))
      |> Enum.uniq()
      |> Enum.sort()

    required_observation_count = sum_number_field(rows, "required_observations")
    planned_observation_count = sum_number_field(rows, "planned_observations")
    missing_observation_count = sum_number_field(rows, "missing_observations")

    %{
      "required_target_ids" => required_target_ids,
      "satisfied_target_ids" => satisfied_target_ids,
      "missed_target_ids" => missed_target_ids,
      "required_observation_count" => required_observation_count,
      "planned_observation_count" => planned_observation_count,
      "missing_observation_count" => missing_observation_count,
      "ratio" =>
        if(required_observation_count > 0,
          do: min(planned_observation_count / required_observation_count, 1.0),
          else: 1.0
        ),
      "rows" => rows
    }
  end

  defp priority_commitment_satisfaction_rows(mission_state, activities) do
    mission_state
    |> priority_commitment_objectives()
    |> Enum.map(fn objective ->
      target_id = Map.get(objective, "target_id") || Map.get(objective, "id")
      required_observations = urgent_target_required_observations(objective)
      planned_observations = scoped_target_observation_count(activities, objective)
      missing_observations = max(required_observations - planned_observations, 0)

      %{
        "objective_id" => Map.get(objective, "objective_id") || Map.get(objective, "id"),
        "commitment_id" => Map.get(objective, "commitment_id"),
        "target_id" => target_id,
        "required_observations" => required_observations,
        "planned_observations" => planned_observations,
        "missing_observations" => missing_observations,
        "status" => if(missing_observations == 0, do: "satisfied", else: "unmet")
      }
      |> compact_map()
    end)
    |> Enum.sort_by(&{&1["target_id"], &1["objective_id"] || "", &1["commitment_id"] || ""})
  end

  defp priority_commitment_objectives(mission_state) do
    mission_state
    |> Map.get("objectives", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(&(Map.get(&1, "type") == "priority_commitment"))
    |> Enum.flat_map(&expand_target_selector_objective/1)
    |> Enum.map(fn objective ->
      objective
      |> maybe_put_objective_id()
      |> maybe_put_commitment_id()
    end)
  end

  defp maybe_put_collection_latency_satisfaction(satisfaction, activities, mission_state) do
    objectives = collection_latency_objectives(mission_state)

    if objectives == [] do
      satisfaction
    else
      rows =
        objectives
        |> Enum.flat_map(&collection_latency_satisfaction_rows(activities, &1))
        |> Enum.sort_by(&{&1["source_activity_id"], &1["objective_id"] || ""})

      satisfied_count = Enum.count(rows, &(&1["status"] == "satisfied"))
      total_count = length(rows)

      Map.put(satisfaction, "collection_latency", %{
        "objective_count" => length(objectives),
        "observation_count" => total_count,
        "satisfied_observation_count" => satisfied_count,
        "unsatisfied_observation_count" => total_count - satisfied_count,
        "ratio" => if(total_count > 0, do: satisfied_count / total_count, else: 1.0),
        "rows" => rows
      })
    end
  end

  defp collection_latency_objectives(mission_state) do
    mission_state
    |> Map.get("objectives", [])
    |> Enum.map(&stringify_keys/1)
    |> Enum.filter(&collection_latency_objective?/1)
  end

  defp collection_latency_satisfaction_rows(activities, objective) do
    max_latency_s = collection_latency_limit_s(objective)
    required_downlink_mb = objective_required_downlink_mb(objective)
    observations = Enum.filter(activities, &collection_latency_observation_match?(&1, objective))
    downlinks = Enum.filter(activities, &downlink_activity?/1)

    observations
    |> Enum.map(fn observation ->
      latency_s = next_downlink_latency_s(observation, downlinks, objective)

      planned_downlinks =
        collection_latency_planned_downlinks(observation, downlinks, objective, max_latency_s)

      planned_downlink_mb =
        planned_downlinks
        |> Enum.map(&downlink_activity_mb/1)
        |> Enum.sum()

      latency_met? = is_number(latency_s) and latency_s <= max_latency_s

      volume_met? =
        not collection_latency_downlink_volume_gap?(planned_downlink_mb, required_downlink_mb)

      %{
        "objective_id" => Map.get(objective, "id"),
        "source_activity_id" => observation["id"],
        "target_id" => observation["target_id"],
        "scenario_id" => observation["scenario_id"],
        "collection_id" =>
          collection_latency_identity_value(objective, observation, "collection_id"),
        "product_id" => collection_latency_identity_value(objective, observation, "product_id"),
        "product_ids" => collection_latency_product_ids(objective, observation),
        "payload_id" => collection_latency_identity_value(objective, observation, "payload_id"),
        "instrument_id" =>
          collection_latency_identity_value(objective, observation, "instrument_id"),
        "status" => if(latency_met? and volume_met?, do: "satisfied", else: "unsatisfied"),
        "max_latency_s" => max_latency_s,
        "planned_latency_s" => latency_s,
        "required_downlink_mb" => required_downlink_mb,
        "planned_downlink_mb" => planned_downlink_mb,
        "planned_contacts" => length(planned_downlinks)
      }
      |> compact_map()
    end)
  end

  defp branch_feasibility_summary(candidate_plan) do
    additions = Map.get(candidate_plan, "strategic_additions", [])

    %{
      "strategic_additions" =>
        Enum.map(additions, fn activity ->
          Map.get(activity, "feasibility", %{
            "status" => "not_applicable",
            "target_id" => activity["target_id"],
            "requires_approval" => get_in(activity, ["repair", "requires_approval"]) || false
          })
        end)
    }
  end

  defp schedule_stability_penalty(repair_score_terms) do
    Map.get(repair_score_terms, "schedule_churn_penalty", 0.0) +
      Map.get(repair_score_terms, "schedule_move_penalty", 0.0)
  end

  defp asset_balance_score([]), do: 0.0

  defp asset_balance_score(activities) do
    counts =
      activities
      |> Enum.map(& &1["scenario_id"])
      |> Enum.reject(&is_nil/1)
      |> Enum.frequencies()
      |> Map.values()

    case counts do
      [] -> 0.0
      [_single] -> 1.0
      values -> 1.0 / (1.0 + Enum.max(values) - Enum.min(values))
    end
  end

  defp priority_commitment_score(activities, request) do
    satisfaction = priority_commitment_satisfaction(request.mission_state, activities)

    if satisfaction["required_target_ids"] == [] do
      0.0
    else
      satisfaction["ratio"]
    end
  end

  defp repair_activity(activity, acc, context) do
    activity = stringify_keys(activity)
    activity_id = activity_id(activity)

    case realized_activity_match(context.realized_by_id, activity_id) do
      {:ambiguous, realized_rows} ->
        review_ambiguous_realized_activity(activity, realized_rows, acc)

      {:ok, realized} ->
        status = realized_status(activity, realized, context.current_epoch_s)

        repair_activity_with_status(activity, realized, status, acc, context)
    end
  end

  defp repair_activity_with_status(activity, realized, status, acc, context) do
    cond do
      status in @realized_preserved_executed_statuses and
          context.repair_policy.preserve_executed? ->
        preserve_executed_activity(activity, realized, status, acc)

      preserve_locked_before_repair?(activity, status, context) ->
        preserve_locked_activity(activity, realized, status, acc)

      degraded_incompatible?(activity, context.degraded_modes, context.repair_policy) ->
        suppress_degraded_activity(activity, realized, status, acc)

      status == "missed" and downlink_activity?(activity) ->
        move_missed_downlink(activity, realized, acc, context)

      status == "failed" and activity["type"] == "observe" ->
        replace_failed_observation(activity, realized, acc, context)

      status == "delayed" and maneuver_activity?(activity) ->
        move_delayed_maneuver(activity, realized, acc)

      status in @terminal_realized_statuses ->
        cancel_activity(activity, realized, status, acc)

      within_remaining_horizon?(activity, context.remaining_horizon) ->
        preserve_activity(activity, realized, status, acc)

      true ->
        acc
    end
  end

  defp review_ambiguous_realized_activity(activity, realized_rows, acc) do
    reason = "ambiguous_realized_activity_feedback"

    activity =
      put_repair_metadata(activity, %{
        "action" => "review_realized_feedback",
        "reason" => reason,
        "realized_status" => "ambiguous",
        "realized_feedback_count" => length(realized_rows),
        "realized_feedback_statuses" => realized_feedback_statuses(realized_rows),
        "requires_approval" => true
      })

    acc
    |> add_activity(activity)
    |> add_ambiguous_realized_delta(activity, realized_rows, reason)
    |> add_approval_requirement(activity, "review_realized_feedback", reason)
    |> add_warning(
      "ambiguous realized feedback for #{activity_id(activity)} requires operator review"
    )
  end

  defp suppress_degraded_activity(activity, realized, status, acc) do
    reason = "spacecraft_degraded_mode_suppressed_incompatible_payload_activity"

    acc
    |> add_delta(activity, realized, status, "suppressed", reason, nil, true)
    |> add_approval_requirement(activity, "cancel", reason)
    |> add_warning("spacecraft degraded mode suppressed #{activity_id(activity)}")
  end

  defp preserve_executed_activity(activity, realized, status, acc) do
    activity =
      put_repair_metadata(
        activity,
        %{
          "action" => "preserved_executed",
          "reason" => "activity_already_#{status}",
          "realized_status" => status,
          "completed_fraction" => Map.get(realized || %{}, "completed_fraction"),
          "actual_starts_at_s" => Map.get(realized || %{}, "actual_starts_at_s"),
          "actual_ends_at_s" => Map.get(realized || %{}, "actual_ends_at_s"),
          "requires_approval" => false
        }
        |> compact_map()
      )

    acc
    |> add_activity(activity)
    |> add_delta(
      activity,
      realized,
      status,
      "preserved_executed",
      "already_#{status}",
      nil,
      false
    )
  end

  defp preserve_locked_before_repair?(activity, status, context) do
    decision =
      Timeline.protection_decision(activity,
        realized_status: status,
        preserve_approved?: context.repair_policy.preserve_approved?,
        preserve_executed?: context.repair_policy.preserve_executed?,
        allow_locked_changes?: context.repair_policy.allow_locked_changes?
      )

    decision["protection_decision"] == "preserve" and
      decision["protection_category"] == "locked_or_approved" and
      status not in @terminal_realized_statuses
  end

  defp move_missed_downlink(activity, realized, acc, context) do
    case downlink_replacement_candidate(activity, acc, context) do
      nil ->
        reason = "missed_contact_no_viable_later_access_window"

        acc
        |> add_delta(activity, realized, "missed", "canceled", reason, nil, true)
        |> add_approval_requirement(activity, "cancel", reason)
        |> add_warning("missed downlink #{activity_id(activity)} could not be repaired")

      replacement ->
        reason = "missed_contact_rescheduled_to_next_viable_access_window"
        candidate_diff = replacement_candidate_diff(activity, replacement, context)

        replacement =
          put_repair_metadata(
            replacement,
            %{
              "action" => "moved",
              "source_activity_id" => activity_id(activity),
              "source_timeline_id" => activity_timeline_id(activity),
              "replacement_timeline_id" => activity_timeline_id(replacement),
              "timeline_link" => timeline_link(activity, replacement),
              "source_activity_context" => operational_activity_context(activity),
              "reason" => reason,
              "requires_approval" => true,
              "schedule_churn_s" => abs(activity_start(replacement) - activity_start(activity))
            }
            |> maybe_put_candidate_diff(candidate_diff)
          )

        acc
        |> add_activity(replacement)
        |> use_replacement(replacement)
        |> add_delta(
          activity,
          realized,
          "missed",
          "moved",
          reason,
          activity_id(replacement),
          true,
          replacement
        )
        |> add_approval_requirement(replacement, "approve_moved_contact", reason)
    end
  end

  defp replace_failed_observation(activity, realized, acc, context) do
    case replacement_candidate(activity, "observe", acc, context) do
      nil ->
        reason = "failed_observation_no_viable_replacement_window"

        acc
        |> add_delta(activity, realized, "failed", "canceled", reason, nil, true)
        |> add_approval_requirement(activity, "cancel", reason)
        |> add_warning("failed observation #{activity_id(activity)} could not be reassigned")

      replacement ->
        reason = "failed_observation_reassigned_to_viable_spacecraft_or_later_window"
        candidate_diff = replacement_candidate_diff(activity, replacement, context)

        replacement =
          put_repair_metadata(
            replacement,
            %{
              "action" => "replaced",
              "source_activity_id" => activity_id(activity),
              "source_timeline_id" => activity_timeline_id(activity),
              "replacement_timeline_id" => activity_timeline_id(replacement),
              "timeline_link" => timeline_link(activity, replacement),
              "source_activity_context" => operational_activity_context(activity),
              "reason" => reason,
              "requires_approval" => true,
              "schedule_churn_s" => abs(activity_start(replacement) - activity_start(activity))
            }
            |> maybe_put_candidate_diff(candidate_diff)
          )

        acc
        |> add_activity(replacement)
        |> use_replacement(replacement)
        |> add_delta(
          activity,
          realized,
          "failed",
          "replaced",
          reason,
          activity_id(replacement),
          true,
          replacement
        )
        |> add_approval_requirement(replacement, "approve_reassigned_observation", reason)
    end
  end

  defp move_delayed_maneuver(activity, realized, acc) do
    actual_start = realized["actual_starts_at_s"] || realized["actual_start_s"]
    delay_s = max(0.0, numeric!(actual_start, "actual_starts_at_s") - activity_start(activity))
    reason = "delayed_maneuver_shifted_and_downstream_windows_marked_affected"

    moved =
      activity
      |> shift_activity(delay_s)
      |> put_repair_metadata(%{
        "action" => "moved",
        "reason" => reason,
        "realized_status" => "delayed",
        "requires_approval" => true,
        "schedule_churn_s" => delay_s
      })

    acc
    |> add_activity(moved)
    |> add_delta(activity, realized, "delayed", "moved", reason, activity_id(moved), true, moved)
    |> add_approval_requirement(moved, "approve_delayed_maneuver", reason)
    |> Map.update!(:delayed_maneuvers, fn maneuvers ->
      [%{"activity" => activity, "delay_s" => delay_s} | maneuvers]
    end)
  end

  defp cancel_activity(activity, realized, status, acc) do
    reason = "realized_status_#{status}_removed_from_remaining_plan"

    acc
    |> add_delta(activity, realized, status, "canceled", reason, nil, true)
    |> add_approval_requirement(activity, "cancel", reason)
  end

  defp preserve_locked_activity(activity, realized, status, acc) do
    activity =
      put_repair_metadata(activity, %{
        "action" => "preserved",
        "reason" => "activity_locked_or_approved",
        "realized_status" => status,
        "requires_approval" => false
      })

    acc
    |> add_activity(activity)
    |> add_delta(
      activity,
      realized,
      status,
      "preserved",
      "activity_locked_or_approved",
      nil,
      false
    )
  end

  defp preserve_activity(activity, realized, status, acc) do
    activity =
      put_repair_metadata(activity, %{
        "action" => "preserved",
        "reason" => "still_viable_in_remaining_horizon",
        "realized_status" => status,
        "requires_approval" => false
      })

    acc
    |> add_activity(activity)
    |> add_delta(
      activity,
      realized,
      status,
      "preserved",
      "still_viable_in_remaining_horizon",
      nil,
      false
    )
  end

  defp mark_downstream_maneuver_effects(%{delayed_maneuvers: []} = acc, _request), do: acc

  defp mark_downstream_maneuver_effects(acc, _request) do
    affected =
      acc.delayed_maneuvers
      |> Enum.flat_map(fn %{"activity" => maneuver} ->
        acc.activities
        |> Enum.reject(&(activity_id(&1) == activity_id(maneuver)))
        |> Enum.filter(fn activity ->
          same_scenario?(activity, maneuver) and
            activity_start(activity) > activity_start(maneuver)
        end)
        |> Enum.map(&{maneuver, &1})
      end)

    Enum.reduce(affected, acc, fn {_maneuver, activity}, repaired ->
      reason = "affected_by_delayed_maneuver_requires_operator_review"

      activities =
        Enum.map(repaired.activities, fn existing ->
          if activity_id(existing) == activity_id(activity) do
            put_repair_metadata(existing, %{
              "action" => get_in(existing, ["repair", "action"]) || "preserved",
              "reason" => reason,
              "affected_by_delayed_maneuver" => true,
              "requires_approval" => true
            })
          else
            existing
          end
        end)

      repaired
      |> Map.put(:activities, activities)
      |> add_approval_requirement(activity, "review_downstream_window", reason)
      |> add_warning("#{activity_id(activity)} affected by delayed maneuver")
    end)
  end

  defp candidate_activities(event_results, campaign, constraints, policy) do
    event_results = canonical_event_results(event_results)
    eclipse_intervals_by_scenario = eclipse_intervals_by_scenario(event_results)
    min_duration_s = numeric_policy_value(constraints, "min_activity_duration_s", 0.0)
    avoid_eclipse? = boolean_policy_value(constraints, "avoid_eclipse", true)

    event_results
    |> Enum.flat_map(fn
      %{event_type: :target_visibility} = result ->
        eclipse_intervals =
          Map.get(eclipse_intervals_by_scenario, encode_value(result.scenario_id), [])

        result.events
        |> Enum.with_index(1)
        |> Enum.map(&observe_candidate(result, &1, campaign, eclipse_intervals, policy))
        |> Enum.reject(fn activity ->
          activity["duration_s"] < min_duration_s or
            (avoid_eclipse? and activity["eclipse_overlap_s"] > 0.0)
        end)

      %{event_type: :ground_station_access} = result ->
        result.events
        |> Enum.with_index(1)
        |> Enum.map(&downlink_candidate(result, &1, policy))
        |> Enum.reject(&(&1["duration_s"] < min_duration_s))

      _result ->
        []
    end)
  end

  defp canonical_event_results(event_results) do
    event_results
    |> Enum.map(&canonical_event_result/1)
    |> Enum.sort_by(&event_result_sort_key/1)
  end

  defp canonical_event_result(%{events: events} = result) when is_list(events) do
    %{result | events: Enum.sort_by(events, &event_sort_key/1)}
  end

  defp canonical_event_result(result), do: result

  defp event_result_sort_key(result) do
    {
      encode_value(Map.get(result, :scenario_id)),
      encode_value(Map.get(result, :event_type)),
      map_sort_key(Map.get(result, :source, %{}))
    }
  end

  defp event_sort_key(event) when is_map(event) do
    metadata = Map.get(event, :metadata, %{})

    {
      event_epoch_seconds(Map.get(event, :starts_at)),
      event_epoch_seconds(Map.get(event, :ends_at)),
      encode_value(Map.get(event, :type)),
      map_sort_key(Map.take(metadata, [:ground_station_id, :target_id, :source_window_id]))
    }
  end

  defp event_sort_key(event), do: inspect(event)

  defp event_epoch_seconds(%{seconds_since_j2000: seconds}), do: seconds
  defp event_epoch_seconds(_epoch), do: nil

  defp map_sort_key(%{} = map) do
    map
    |> encode_value()
    |> Enum.sort_by(fn {key, value} -> {key, inspect(value)} end)
  end

  defp map_sort_key(value), do: encode_value(value)

  defp contact_filter_report(candidates) do
    ContactFilter.report(candidates, [],
      policy: %{
        "ground_network_source" => "study_access_windows",
        "station_availability" => "available_from_detected_access_window",
        "schedule_conflict_status" => "not_evaluated"
      }
    )
  end

  defp apply_station_calendar(candidates, campaign),
    do: apply_station_calendar(candidates, campaign, "campaign.ground_network")

  defp apply_station_calendar(candidates, campaign, source) do
    station_calendar = get_key(campaign, "ground_network") || []
    approval_policy = Map.get(campaign, "approval_policy") || Map.get(campaign, :approval_policy)

    StationCalendar.overlay_contacts(candidates, station_calendar,
      source: source,
      approval_policy: approval_policy
    )
  end

  defp apply_repair_station_calendar(candidates, %{ground_network: nil}), do: {candidates, nil}

  defp apply_repair_station_calendar(candidates, %{ground_network: ground_network} = request) do
    apply_station_calendar(
      candidates,
      %{
        "ground_network" => ground_network,
        "approval_policy" => Map.get(request, :approval_policy)
      },
      "repair.ground_network"
    )
  end

  defp apply_campaign_resource_filters(candidates, campaign) do
    summaries =
      campaign
      |> Map.get("resource_summaries", [])
      |> List.wrap()
      |> Enum.map(&stringify_keys/1)

    if summaries == [] do
      {candidates, nil}
    else
      ResourceFilter.filter_candidates(candidates, summaries,
        policy: campaign_resource_filter_policy(campaign),
        approval_policy:
          Map.get(campaign, "approval_policy") || Map.get(campaign, :approval_policy)
      )
    end
  end

  defp campaign_resource_filter_policy(campaign) do
    campaign
    |> Map.get("resource_filter_policy", %{})
    |> ResourceFilter.resource_filter_policy()
  end

  defp annotate_contact_contention(candidates) do
    ContactContention.annotate_contacts(candidates, source: "campaign_plan.candidate_activities")
  end

  defp contact_contention_resolution_report(candidates, contention_report, campaign) do
    ContactContention.resolution_report(candidates, contention_report,
      policy: contact_contention_resolution_policy(campaign)
    )
  end

  defp contact_contention_resolution_policy(campaign) do
    policy =
      campaign
      |> get_key("contact_contention_resolution_policy")
      |> case do
        %{} = policy -> stringify_keys(policy)
        _policy -> %{}
      end

    Map.merge(
      %{
        "selection_rule" => Map.get(policy, "selection_rule", "highest_score_earliest_start"),
        "tie_breakers" => Map.get(policy, "tie_breakers", ["starts_at_s", "id"]),
        "action" => Map.get(policy, "action", "recommend_preferred_contact_for_operator_review")
      },
      policy
    )
  end

  defp contact_allocation_report(candidates, campaign) do
    ContactAllocation.report(candidates, Map.get(campaign, "ground_network", []),
      source: "campaign_plan.candidate_activities",
      policy: contact_contention_resolution_policy(campaign),
      approval_policy: Map.get(campaign, "approval_policy") || Map.get(campaign, :approval_policy)
    )
  end

  defp link_capacity_report(
         candidates,
         selected_activities,
         policy,
         source,
         approval_policy
       ) do
    LinkCapacity.report(candidates, selected_activities,
      policy: policy,
      source: source,
      approval_policy: approval_policy
    )
  end

  defp campaign_link_capacity_policy(campaign, policy) do
    policy = stringify_keys(policy || %{})

    case campaign_required_downlink_mb(campaign) do
      value when is_number(value) ->
        Map.put_new(policy, "required_downlink_mb", value)

      _value ->
        policy
    end
  end

  defp repair_link_capacity_policy(request) do
    policy = stringify_keys(request.scoring_policy || %{})

    request.mission_state
    |> mission_required_downlink_mb()
    |> case do
      value when is_number(value) -> Map.put_new(policy, "required_downlink_mb", value)
      _value -> policy
    end
  end

  defp mission_required_downlink_mb(mission_state) do
    mission_state
    |> downlink_completion_objectives()
    |> Enum.map(&objective_required_downlink_mb/1)
    |> Enum.filter(&is_number/1)
    |> case do
      [] -> nil
      values -> Enum.sum(values)
    end
  end

  defp target_commitments(campaign, candidates, selected_activities) do
    campaign
    |> campaign_targets()
    |> Enum.map(&encode_value/1)
    |> Enum.sort_by(&(Map.get(&1, "id") || ""))
    |> Enum.map(fn target ->
      target_id = Map.get(target, "id")
      candidate_rows = target_activity_rows(candidates, target_id)
      selected_rows = target_activity_rows(selected_activities, target_id)

      %{
        "target_id" => target_id,
        "priority" => Map.get(target, "priority"),
        "candidate_activity_count" => length(candidate_rows),
        "candidate_duration_s" => activity_duration_sum(candidate_rows),
        "selected_activity_count" => length(selected_rows),
        "selected_duration_s" => activity_duration_sum(selected_rows),
        "selected_activity_ids" => Enum.map(selected_rows, & &1["id"]),
        "status" => target_commitment_status(candidate_rows, selected_rows)
      }
      |> Enum.reject(fn {_key, value} -> is_nil(value) end)
      |> Map.new()
    end)
  end

  defp target_activity_rows(activities, target_id) do
    activities
    |> Enum.map(&encode_value/1)
    |> Enum.filter(&(&1["type"] == "observe" and &1["target_id"] == target_id))
  end

  defp activity_duration_sum(activities) do
    activities
    |> Enum.map(&(Map.get(&1, "duration_s") || 0.0))
    |> Enum.sum()
  end

  defp target_commitment_status(_candidates, selected) when selected != [], do: "selected"

  defp target_commitment_status(candidates, _selected) when candidates != [],
    do: "candidate_available"

  defp target_commitment_status(_candidates, _selected), do: "no_candidate_window"

  defp objective_satisfaction_report(campaign, candidates, selected_activities) do
    rows =
      [
        coverage_objective_row(campaign, candidates, selected_activities),
        downlink_completion_objective_row(campaign, candidates, selected_activities)
      ] ++ target_commitment_objective_rows(campaign, candidates, selected_activities)

    %{
      "schema_contract" => "objective_satisfaction_report.v1",
      "model" => "campaign_v1_selected_activity_objective_summary",
      "model_limits" => @objective_satisfaction_model_limits,
      "source" => "campaign_plan.activities",
      "objective_count" => length(rows),
      "rows" => rows,
      "assumptions" => %{
        "selection" => "best_ranked_timeline_is_selected",
        "coverage_model" => "selected_observe_activity_targets",
        "downlink_completion_model" => "selected_downlink_activity_count_or_data_volume",
        "execution_status" => "planned_not_executed"
      }
    }
  end

  defp operational_timeline_report(selected_activities) do
    Timeline.operational_report(selected_activities,
      source: "campaign_plan.activities",
      source_assumption: "selected campaign_plan.activities"
    )
  end

  defp timeline_activity_precondition_summaries(selected_activities) do
    selected_activities
    |> Enum.map(&Timeline.activity_precondition_summary/1)
    |> Enum.map(&Map.put(&1, "source", "campaign_plan.activities"))
  end

  defp timeline_integrity_report(selected_activities) do
    Timeline.integrity_report(selected_activities,
      source: "campaign_plan.activities",
      validate_missing_dependencies?: false
    )
  end

  defp repair_timeline_transition_application_report(planned_activities, repaired_activities) do
    Timeline.transition_application_report(planned_activities, repaired_activities,
      source: "campaign_repair.timeline_transition_application",
      source_assumption: "source campaign activities compared with repaired campaign activities"
    )
  end

  defp coverage_objective_row(campaign, candidates, selected_activities) do
    target_ids =
      campaign
      |> campaign_targets()
      |> Enum.map(&(Map.get(&1, "id") || Map.get(&1, :id)))
      |> Enum.map(&encode_value/1)
      |> Enum.reject(&is_nil/1)
      |> Enum.uniq()
      |> Enum.sort()

    candidate_target_ids = observed_target_ids(candidates)
    selected_target_ids = observed_target_ids(selected_activities)
    required_count = length(target_ids)
    selected_count = length(selected_target_ids)

    %{
      "id" => "objective:target_coverage",
      "objective" => "target_coverage",
      "status" => coverage_status(required_count, selected_count),
      "required_count" => required_count,
      "candidate_count" => length(candidate_target_ids),
      "selected_count" => selected_count,
      "satisfied_count" => selected_count,
      "candidate_target_ids" => candidate_target_ids,
      "selected_target_ids" => selected_target_ids
    }
  end

  defp downlink_completion_objective_row(campaign, candidates, selected_activities) do
    objectives = downlink_completion_objectives(campaign)

    objective_rows =
      campaign_downlink_objective_summaries(objectives, candidates, selected_activities)

    required_count = downlink_required_contact_count(campaign)
    required_downlink_mb = campaign_required_downlink_mb(campaign)
    candidate_count = sum_number_field(objective_rows, "candidate_count")
    selected_count = sum_number_field(objective_rows, "selected_count")
    satisfied_count = sum_number_field(objective_rows, "satisfied_count")
    candidate_downlink_mb = sum_number_field(objective_rows, "candidate_downlink_mb")
    selected_downlink_mb = sum_number_field(objective_rows, "selected_downlink_mb")
    satisfied_downlink_mb = sum_number_field(objective_rows, "satisfied_downlink_mb")

    %{
      "id" => "objective:downlink_completion",
      "objective" => "downlink_completion",
      "status" =>
        downlink_completion_status(
          required_count,
          selected_count,
          required_downlink_mb,
          selected_downlink_mb
        ),
      "required_count" => required_count,
      "required_downlink_mb" => required_downlink_mb,
      "candidate_count" => candidate_count,
      "selected_count" => selected_count,
      "satisfied_count" => satisfied_count,
      "candidate_downlink_mb" => candidate_downlink_mb,
      "selected_downlink_mb" => selected_downlink_mb,
      "satisfied_downlink_mb" => satisfied_downlink_mb,
      "selected_contact_ids" =>
        campaign_downlink_selected_contact_ids(objectives, selected_activities)
    }
    |> compact_map()
  end

  defp target_commitment_objective_rows(campaign, candidates, selected_activities) do
    campaign
    |> target_commitments(candidates, selected_activities)
    |> Enum.map(fn commitment ->
      %{
        "id" => "objective:target_commitment:#{commitment["target_id"]}",
        "objective" => "target_commitment",
        "target_id" => commitment["target_id"],
        "status" => commitment["status"],
        "required_count" => 1,
        "candidate_count" => commitment["candidate_activity_count"],
        "selected_count" => commitment["selected_activity_count"],
        "satisfied_count" => if(commitment["status"] == "selected", do: 1, else: 0),
        "selected_activity_ids" => commitment["selected_activity_ids"]
      }
    end)
  end

  defp observed_target_ids(activities) do
    activities
    |> Enum.filter(&(&1["type"] == "observe"))
    |> Enum.map(& &1["target_id"])
    |> Enum.reject(&is_nil/1)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp downlink_required_contact_count(campaign) do
    campaign
    |> downlink_completion_objectives()
    |> Enum.map(&Map.get(&1, "required_contacts"))
    |> Enum.filter(&is_number/1)
    |> case do
      [] -> nil
      counts -> Enum.sum(counts)
    end
  end

  defp campaign_required_downlink_mb(campaign) do
    campaign
    |> downlink_completion_objectives()
    |> Enum.map(&objective_required_downlink_mb/1)
    |> Enum.filter(&is_number/1)
    |> case do
      [] -> nil
      values -> Enum.sum(values)
    end
  end

  defp campaign_downlink_objective_summaries([], candidates, selected_activities) do
    [campaign_downlink_objective_summary(%{}, candidates, selected_activities, nil, nil)]
  end

  defp campaign_downlink_objective_summaries(objectives, candidates, selected_activities) do
    Enum.map(objectives, fn objective ->
      campaign_downlink_objective_summary(
        objective,
        candidates,
        selected_activities,
        Map.get(objective, "required_contacts"),
        objective_required_downlink_mb(objective)
      )
    end)
  end

  defp campaign_downlink_selected_contact_ids([], selected_activities) do
    selected_activities
    |> Enum.filter(&downlink_activity?/1)
    |> Enum.map(& &1["id"])
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp campaign_downlink_selected_contact_ids(objectives, selected_activities) do
    selected_activities
    |> Enum.filter(fn activity ->
      downlink_activity?(activity) and
        Enum.any?(objectives, &downlink_completion_event_match?(activity, &1))
    end)
    |> Enum.map(& &1["id"])
    |> Enum.reject(&(&1 in [nil, ""]))
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp campaign_downlink_objective_summary(
         objective,
         candidates,
         selected_activities,
         required_count,
         required_downlink_mb
       ) do
    candidate_downlinks =
      Enum.filter(
        candidates,
        &(downlink_activity?(&1) and downlink_completion_event_match?(&1, objective))
      )

    selected_downlinks =
      Enum.filter(
        selected_activities,
        &(downlink_activity?(&1) and downlink_completion_event_match?(&1, objective))
      )

    selected_count = length(selected_downlinks)
    selected_downlink_mb = planned_downlink_mb(selected_downlinks, objective)

    %{
      "required_count" => required_count,
      "required_downlink_mb" => required_downlink_mb,
      "candidate_count" => length(candidate_downlinks),
      "selected_count" => selected_count,
      "satisfied_count" => min(selected_count, required_count || selected_count),
      "candidate_downlink_mb" => planned_downlink_mb(candidate_downlinks, objective),
      "selected_downlink_mb" => selected_downlink_mb,
      "satisfied_downlink_mb" =>
        if(is_number(required_downlink_mb),
          do: min(selected_downlink_mb, required_downlink_mb),
          else: selected_downlink_mb
        )
    }
    |> compact_map()
  end

  defp coverage_status(0, _selected_count), do: "no_requirement"

  defp coverage_status(required_count, selected_count) when selected_count >= required_count,
    do: "met"

  defp coverage_status(_required_count, 0), do: "unmet"
  defp coverage_status(_required_count, _selected_count), do: "partial"

  defp downlink_completion_status(nil, _selected_count), do: "no_requirement"

  defp downlink_completion_status(required_count, selected_count)
       when selected_count >= required_count, do: "met"

  defp downlink_completion_status(_required_count, 0), do: "unmet"
  defp downlink_completion_status(_required_count, _selected_count), do: "partial"

  defp downlink_completion_status(
         required_count,
         selected_count,
         required_downlink_mb,
         selected_mb
       )
       when is_number(required_downlink_mb) do
    cond do
      selected_mb >= required_downlink_mb and
          (not is_number(required_count) or selected_count >= required_count) ->
        "met"

      selected_mb == 0.0 and selected_count == 0 ->
        "unmet"

      is_number(required_count) and selected_count < required_count ->
        "partial"

      true ->
        "partial"
    end
  end

  defp downlink_completion_status(
         required_count,
         selected_count,
         _required_downlink_mb,
         _selected_mb
       ),
       do: downlink_completion_status(required_count, selected_count)

  defp observe_candidate(result, {event, index}, campaign, eclipse_intervals, policy) do
    starts_at_s = event.starts_at.seconds_since_j2000
    ends_at_s = event.ends_at.seconds_since_j2000
    target_id = event.metadata.target_id
    target = target_by_id(campaign, target_id)

    priority =
      numeric_or_nil(Map.get(target || %{}, "priority")) ||
        numeric_or_nil(event.metadata.target_priority) || 1.0

    duration_s = ends_at_s - starts_at_s
    eclipse_overlap_s = overlap_duration({starts_at_s, ends_at_s}, eclipse_intervals)
    lighting_summary = Eclipses.lighting_summary(duration_s, eclipse_overlap_s)
    id = activity_id(result.scenario_id, "observe", target_id, index)
    source_window_id = window_id(result.scenario_id, "target_visibility", target_id, index)

    score_terms = %{
      "target_value" =>
        priority * duration_s * numeric_policy_value(policy, "target_value_weight", 1.0),
      "eclipse_penalty" =>
        eclipse_overlap_s * numeric_policy_value(policy, "eclipse_penalty_weight", 1.0) * -1.0
    }

    %{
      "id" => id,
      "type" => "observe",
      "scenario_id" => encode_value(result.scenario_id),
      "target_id" => encode_value(target_id),
      "starts_at_s" => starts_at_s,
      "ends_at_s" => ends_at_s,
      "duration_s" => duration_s,
      "score" => score(score_terms),
      "score_terms" => score_terms,
      "eclipse_overlap_s" => eclipse_overlap_s,
      "source_window_id" => source_window_id,
      "source_window" =>
        %{
          "id" => source_window_id,
          "type" => "target_visibility",
          "max_elevation_deg" => event.metadata.max_elevation_deg,
          "minimum_elevation_deg" => event.metadata.minimum_elevation_deg
        }
        |> Map.merge(event_timing_metadata(event.metadata)),
      "cadence_import" => %{
        "activity_type" => "observation",
        "external_id" => id
      }
    }
    |> Map.merge(lighting_summary)
  end

  defp downlink_candidate(result, {event, index}, policy) do
    starts_at_s = event.starts_at.seconds_since_j2000
    ends_at_s = event.ends_at.seconds_since_j2000
    ground_station_id = result.source.ground_station_id
    duration_s = ends_at_s - starts_at_s
    downlink_rate_mb_s = numeric_policy_value(policy, "downlink_rate_mb_s", 1.0)
    id = activity_id(result.scenario_id, "downlink", ground_station_id, index)

    source_window_id =
      window_id(result.scenario_id, "ground_station_access", ground_station_id, index)

    score_terms = %{
      "contact_value" => duration_s * numeric_policy_value(policy, "contact_value_weight", 0.1)
    }

    %{
      "id" => id,
      "type" => "downlink",
      "direction" => "downlink",
      "scenario_id" => encode_value(result.scenario_id),
      "ground_station_id" => encode_value(ground_station_id),
      "starts_at_s" => starts_at_s,
      "ends_at_s" => ends_at_s,
      "duration_s" => duration_s,
      "estimated_throughput_mb" => duration_s * downlink_rate_mb_s,
      "throughput_model" => %{
        "model" => "fixed_rate_from_campaign_policy",
        "downlink_rate_mb_s" => downlink_rate_mb_s
      },
      "station_availability" => "available",
      "schedule_conflict_status" => "not_evaluated",
      "score" => score(score_terms),
      "score_terms" => score_terms,
      "source_window_id" => source_window_id,
      "source_window" =>
        %{
          "id" => source_window_id,
          "type" => "ground_station_access",
          "max_elevation_deg" => event.metadata.max_elevation_deg,
          "minimum_elevation_deg" => event.metadata.minimum_elevation_deg
        }
        |> Map.merge(event_timing_metadata(event.metadata)),
      "cadence_import" => %{
        "activity_type" => "contact",
        "external_id" => id,
        "schema_contract" => "proposed_contact.v1"
      }
    }
  end

  defp ranked_timeline(scenario_id, candidates, constraints, policy) do
    max_activities =
      policy_count_value(constraints, "max_timeline_activities", length(candidates))

    activity_count_penalty = numeric_policy_value(policy, "activity_count_penalty", 0.0)

    activities =
      candidates
      |> Enum.sort_by(&{-candidate_score(&1), activity_start(&1), &1["id"]})
      |> Enum.reduce([], fn candidate, selected ->
        cond do
          length(selected) >= max_activities -> selected
          Enum.any?(selected, &overlaps?(candidate, &1)) -> selected
          true -> [candidate | selected]
        end
      end)
      |> Enum.sort_by(&{&1["starts_at_s"], &1["id"]})

    gross_score = activities |> Enum.map(&candidate_score/1) |> Enum.sum()
    penalty = length(activities) * activity_count_penalty
    score = gross_score - penalty
    component_terms = timeline_component_score_terms(activities)

    %{
      "scenario_id" => encode_value(scenario_id),
      "score" => score,
      "score_terms" =>
        Map.merge(component_terms, %{
          "activity_score" => gross_score,
          "activity_count_penalty" => -penalty,
          "selected_observation_count" => Enum.count(activities, &(&1["type"] == "observe")),
          "selected_contact_count" => Enum.count(activities, &downlink_activity?/1)
        }),
      "activity_count" => length(activities),
      "activities" => activities
    }
  end

  defp timeline_component_score_terms(activities) do
    Enum.reduce(
      activities,
      %{"target_value" => 0.0, "contact_value" => 0.0, "eclipse_penalty" => 0.0},
      fn activity, acc ->
        terms = Map.get(activity, "score_terms", %{})

        Map.merge(acc, terms, fn _key, left, right ->
          numeric_or_zero(left) + numeric_or_zero(right)
        end)
      end
    )
  end

  defp campaign_constraint_report(
         candidates,
         timelines,
         constraints,
         resource_projection_report,
         link_capacity_report
       ) do
    CampaignLocalConstraint.report(
      candidates,
      timelines,
      constraints,
      resource_projection_report,
      link_capacity_report
    )
  end

  defp repair_constraint_report(
         activities,
         repair_score_timeline,
         request,
         source_resource_projection_report,
         link_capacity_report
       ) do
    CampaignLocalConstraint.report(
      activities,
      [repair_score_timeline],
      request.constraints,
      source_resource_projection_report,
      link_capacity_report,
      model: "campaign_repair_local_constraint_summary",
      source: "campaign_repair.assumptions.constraints",
      constraint_model: "campaign_repair_v2_planner_local_constraints"
    )
  end

  defp objective_tradeoff_report(timelines, policy) do
    best_score =
      timelines
      |> List.first()
      |> case do
        %{"score" => score} when is_number(score) -> score
        _timeline -> 0.0
      end

    tradeoffs =
      timelines
      |> Enum.with_index(1)
      |> Enum.map(fn {timeline, rank} -> objective_tradeoff_row(timeline, rank, best_score) end)

    %{
      "schema_contract" => "objective_tradeoff_report.v1",
      "model" => "ranked_timeline_score_term_tradeoffs",
      "objective" => "maximize weighted observation value and contact value",
      "ranking_count" => length(timelines),
      "score_term_keys" => objective_score_term_keys(timelines),
      "policy" => policy,
      "model_limits" => @score_report_model_limits,
      "tradeoffs" => tradeoffs,
      "assumptions" => %{
        "source" => "campaign_plan.ranked_timelines",
        "selection" => "best_ranked_timeline_is_selected",
        "score_delta_from_selected" => "row_score_minus_selected_score"
      }
    }
  end

  defp objective_tradeoff_row(timeline, rank, best_score) do
    score = candidate_score(timeline)
    score_terms = Map.get(timeline, "score_terms", %{})
    activities = Map.get(timeline, "activities", [])

    %{
      "rank" => rank,
      "scenario_id" => Map.get(timeline, "scenario_id"),
      "score" => score,
      "score_delta_from_selected" => score - best_score,
      "activity_count" => Map.get(timeline, "activity_count", length(activities)),
      "selected_observation_count" => Map.get(score_terms, "selected_observation_count", 0),
      "selected_contact_count" => Map.get(score_terms, "selected_contact_count", 0),
      "score_terms" => score_terms,
      "activity_ids" => Enum.map(activities, & &1["id"])
    }
  end

  defp objective_score_term_keys(timelines) do
    timelines
    |> Enum.flat_map(fn timeline ->
      timeline
      |> Map.get("score_terms", %{})
      |> Map.keys()
    end)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp repair_score_timeline(prior_plan, activities, score_terms, score) do
    %{
      "scenario_id" => source_plan_id(prior_plan),
      "score" => score,
      "score_terms" => score_terms,
      "activities" => activities,
      "activity_count" => length(activities)
    }
  end

  defp repair_objective_tradeoff_report(timeline, policy) do
    %{
      "schema_contract" => "objective_tradeoff_report.v1",
      "model" => "repair_score_term_tradeoffs",
      "objective" =>
        "maximize repaired activity value while minimizing churn and schedule movement",
      "ranking_count" => 1,
      "score_term_keys" => objective_score_term_keys([timeline]),
      "policy" => policy,
      "model_limits" => @score_report_model_limits,
      "tradeoffs" => [objective_tradeoff_row(timeline, 1, candidate_score(timeline))],
      "assumptions" => %{
        "source" => "campaign_repair.score_terms",
        "selection" => "single_repaired_timeline",
        "score_delta_from_selected" => "row_score_minus_repaired_score"
      }
    }
  end

  defp score_term_report(timelines, policy) do
    rows =
      timelines
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {timeline, rank} -> score_term_rows(timeline, rank) end)
      |> Enum.sort_by(&{&1["rank"], &1["scenario_id"], &1["term_key"]})

    %{
      "schema_contract" => "score_term_report.v1",
      "model" => "ranked_timeline_score_terms",
      "source" => "campaign_plan.ranked_timelines",
      "row_count" => length(rows),
      "score_term_keys" => objective_score_term_keys(timelines),
      "model_limits" => @score_report_model_limits,
      "rows" => rows,
      "assumptions" => %{
        "score_term_source" => "ranked_timeline.score_terms",
        "policy" => policy
      }
    }
  end

  defp repair_score_term_report(timeline, policy) do
    rows =
      timeline
      |> score_term_rows(1)
      |> Enum.sort_by(&{&1["rank"], &1["scenario_id"], &1["term_key"]})

    %{
      "schema_contract" => "score_term_report.v1",
      "model" => "repair_score_terms",
      "source" => "campaign_repair.score_terms",
      "row_count" => length(rows),
      "score_term_keys" => objective_score_term_keys([timeline]),
      "model_limits" => @score_report_model_limits,
      "rows" => rows,
      "assumptions" => %{
        "score_term_source" => "campaign_repair.score_terms",
        "policy" => policy
      }
    }
  end

  defp strategy_score_term_report(branches, recommendation, policy) do
    rows =
      branches
      |> Enum.with_index(1)
      |> Enum.flat_map(fn {branch, rank} ->
        strategy_score_term_rows(branch, rank, recommendation.recommended_branch_id)
      end)
      |> Enum.sort_by(&{&1["rank"], &1["branch_id"], &1["term_key"]})

    %{
      "schema_contract" => "score_term_report.v1",
      "model" => "strategy_branch_score_terms",
      "source" => "campaign_strategy.branches.score_terms",
      "row_count" => length(rows),
      "score_term_keys" => strategy_score_term_keys(branches),
      "model_limits" => @score_report_model_limits,
      "rows" => rows,
      "assumptions" => %{
        "score_term_source" => "campaign_strategy.branches.score_terms",
        "scenario_id_represents" => "branch_id",
        "policy" => strategy_policy_to_map(policy)
      }
    }
  end

  defp strategy_score_term_rows(%PlanBranch{} = branch, rank, recommended_branch_id) do
    branch.score_terms
    |> Enum.map(fn {term_key, value} ->
      %{
        "id" => score_term_row_id(branch.id, rank, term_key),
        "rank" => rank,
        "scenario_id" => branch.id,
        "branch_id" => branch.id,
        "term_key" => term_key,
        "value" => value,
        "timeline_score" => branch.score,
        "selected" => branch.id == recommended_branch_id
      }
    end)
  end

  defp strategy_score_term_keys(branches) do
    branches
    |> Enum.flat_map(fn %PlanBranch{} = branch -> Map.keys(branch.score_terms) end)
    |> Enum.uniq()
    |> Enum.sort()
  end

  defp strategy_objective_tradeoff_report(branches, recommendation, policy) do
    selected_score =
      branches
      |> Enum.find(&(&1.id == recommendation.recommended_branch_id))
      |> case do
        nil -> 0.0
        branch -> branch.score
      end

    tradeoffs =
      branches
      |> Enum.with_index(1)
      |> Enum.map(fn {branch, rank} ->
        strategy_objective_tradeoff_row(
          branch,
          rank,
          selected_score,
          recommendation.recommended_branch_id
        )
      end)

    %{
      "schema_contract" => "objective_tradeoff_report.v1",
      "model" => "strategy_branch_score_term_tradeoffs",
      "objective" => "compare strategy branch scores and score-term contributions",
      "ranking_count" => length(tradeoffs),
      "score_term_keys" => strategy_score_term_keys(branches),
      "policy" => strategy_policy_to_map(policy),
      "model_limits" => @score_report_model_limits,
      "tradeoffs" => tradeoffs,
      "assumptions" => %{
        "source" => "campaign_strategy.branches.score_terms",
        "scenario_id_represents" => "branch_id",
        "score_delta_from_selected" => "branch_score_minus_recommended_branch_score"
      }
    }
  end

  defp strategy_objective_tradeoff_row(
         %PlanBranch{} = branch,
         rank,
         selected_score,
         recommended_branch_id
       ) do
    activities = get_in(branch.repair_result, ["activities"]) || []

    %{
      "rank" => rank,
      "scenario_id" => branch.id,
      "branch_id" => branch.id,
      "score" => branch.score,
      "score_delta_from_selected" => branch.score - selected_score,
      "activity_count" => length(activities),
      "selected_observation_count" => Enum.count(activities, &(&1["type"] == "observation")),
      "selected_contact_count" => Enum.count(activities, &downlink_activity?/1),
      "score_terms" => branch.score_terms,
      "activity_ids" => Enum.map(activities, &activity_id/1),
      "selected" => branch.id == recommended_branch_id
    }
  end

  defp score_term_rows(timeline, rank) do
    scenario_id = Map.get(timeline, "scenario_id")
    timeline_score = candidate_score(timeline)

    timeline
    |> Map.get("score_terms", %{})
    |> Enum.map(fn {term_key, value} ->
      %{
        "id" => score_term_row_id(scenario_id, rank, term_key),
        "rank" => rank,
        "scenario_id" => scenario_id,
        "term_key" => term_key,
        "value" => value,
        "timeline_score" => timeline_score,
        "selected" => rank == 1
      }
    end)
  end

  defp score_term_row_id(scenario_id, rank, term_key) do
    ["score_term", scenario_id, rank, term_key]
    |> Enum.map(&encode_value/1)
    |> Enum.join(":")
  end

  defp warnings(campaign, candidates, timelines, result_set, resource_filter_report) do
    []
    |> maybe_warn(campaign_targets(campaign) == [], "campaign has no targets")
    |> maybe_warn(candidates == [], "no candidate activities were generated")
    |> maybe_warn(timelines == [], "no candidate timelines were ranked")
    |> maybe_warn(
      not Enum.any?(candidates, &(&1["type"] == "downlink")),
      "no contact activities proposed"
    )
    |> maybe_warn(
      Map.get(resource_filter_report || %{}, "suppressed_candidate_count", 0) > 0,
      "resource summary filters suppressed campaign candidates"
    )
    |> maybe_warn(result_set.errors != [], "study completed with propagation or event errors")
    |> Enum.reverse()
  end

  defp assumptions(campaign) do
    %{
      "activity_builder" => "windows_to_observe_and_downlink_candidates",
      "timeline_selector" => "per_spacecraft_greedy_non_overlapping",
      "resource_filter" => "resource_summary_availability_and_margin_filter",
      "cadence_integration" => "artifact_only_no_api_or_database_writes",
      "constraints" => Map.get(campaign, "constraints", %{}),
      "scoring_policy" => Map.get(campaign, "scoring_policy", %{})
    }
  end

  defp provenance(%ResultSet{} = result_set) do
    run = Map.get(result_set.metadata, :run) || Map.get(result_set.metadata, "run") || %{}
    run_metadata = Map.get(run, "metadata") || Map.get(run, :metadata) || %{}

    %{
      "run_id" => encode_value(Map.get(run, "id") || Map.get(run, :id)),
      "manifest" =>
        encode_value(Map.get(run_metadata, "manifest") || Map.get(run_metadata, :manifest)),
      "git_revision" =>
        encode_value(
          Map.get(run_metadata, "git_revision") || Map.get(run_metadata, :git_revision)
        ),
      "propagator" => encode_value(get_in(result_set.assumptions, [:propagator])),
      "propagator_opts" => encode_value(get_in(result_set.assumptions, [:propagator_opts]))
    }
  end

  defp ranking_explanation(policy) do
    %{
      "objective" => "maximize weighted observation value and contact value",
      "formula" =>
        "sum(target_priority * duration_s * target_value_weight) + sum(contact_duration_s * contact_value_weight) - eclipse_overlap_s * eclipse_penalty_weight - activity_count * activity_count_penalty",
      "policy" => policy
    }
  end

  defp eclipse_intervals_by_scenario(event_results) do
    event_results
    |> Enum.filter(&(&1.event_type == :eclipse))
    |> Enum.group_by(
      &encode_value(&1.scenario_id),
      fn result ->
        Enum.map(result.events, fn event ->
          {event.starts_at.seconds_since_j2000, event.ends_at.seconds_since_j2000}
        end)
      end
    )
    |> Map.new(fn {scenario_id, grouped_intervals} ->
      {scenario_id, List.flatten(grouped_intervals)}
    end)
  end

  defp target_by_id(campaign, target_id) do
    campaign
    |> campaign_targets()
    |> Enum.find(&(Map.get(&1, "id") == encode_value(target_id)))
  end

  defp replacement_candidate(activity, type, acc, context) do
    replacement_candidate(activity, &(&1["type"] == type), type, acc, context)
  end

  defp downlink_replacement_candidate(activity, acc, context) do
    replacement_candidate(activity, &downlink_activity?/1, "downlink", acc, context)
  end

  defp replacement_candidate(activity, candidate_filter, intent_type, acc, context) do
    context.candidates
    |> Enum.map(&stringify_keys/1)
    |> Enum.reject(&(activity_id(&1) == activity_id(activity)))
    |> Enum.reject(&MapSet.member?(context.selected_activity_ids, activity_id(&1)))
    |> Enum.reject(&MapSet.member?(acc.used_replacement_ids, activity_id(&1)))
    |> Enum.filter(candidate_filter)
    |> Enum.filter(&within_remaining_horizon?(&1, context.remaining_horizon))
    |> Enum.filter(&(activity_start(&1) >= context.current_epoch_s))
    |> Enum.reject(&degraded_incompatible?(&1, context.degraded_modes, context.repair_policy))
    |> Enum.reject(
      &MapSet.member?(
        Map.get(context, :rejected_replacement_candidate_ids, MapSet.new()),
        activity_id(&1)
      )
    )
    |> Enum.reject(fn candidate -> Enum.any?(acc.activities, &overlaps?(candidate, &1)) end)
    |> Enum.filter(&matches_repair_intent?(activity, &1, intent_type))
    |> reject_duplicate_replacement_candidate_ids()
    |> Enum.sort_by(fn candidate ->
      diff_priority =
        case replacement_candidate_diff(activity, candidate, context) do
          nil -> 1
          _diff -> 0
        end

      churn_s = abs(activity_start(candidate) - activity_start(activity))

      churn_cost =
        numeric_policy_value(context.scoring_policy, "schedule_churn_cost_weight", 100.0)

      move_cost = numeric_policy_value(context.scoring_policy, "schedule_move_cost_weight", 0.01)

      {diff_priority, -(candidate_score(candidate) - churn_cost - churn_s * move_cost), churn_s,
       activity_start(candidate), activity_id(candidate)}
    end)
    |> List.first()
  end

  defp reject_duplicate_replacement_candidate_ids(candidates) do
    candidates
    |> Enum.group_by(&activity_id/1)
    |> Enum.flat_map(fn
      {_candidate_id, [candidate]} -> [candidate]
      {_candidate_id, _duplicates} -> []
    end)
  end

  defp replacement_candidate_diff(source, candidate, context) do
    context
    |> Map.get(:candidate_diff_replacements, %{})
    |> candidate_diff_replacement_map_rows()
    |> Enum.filter(&candidate_diff_row_matches?(&1, source, candidate))
    |> candidate_diff_match("source")
  end

  defp candidate_diff_row_matches?(row, source, candidate) do
    source_window_id = activity_source_window_id(source)

    row["replacement_candidate_id"] == activity_id(candidate) and
      (row["id"] == activity_id(source) or
         (not is_nil(source_window_id) and row["source_window_id"] == source_window_id))
  end

  defp maybe_put_candidate_diff(metadata, nil), do: metadata

  defp maybe_put_candidate_diff(metadata, row) do
    Map.put(metadata, "candidate_diff", candidate_diff_metadata(row))
  end

  defp candidate_diff_metadata(row) do
    %{
      "invalidated_candidate_id" => row["invalidated_candidate_id"] || row["id"],
      "invalidated_candidate_ids" => row["invalidated_candidate_ids"],
      "replacement_candidate_id" => row["replacement_candidate_id"],
      "invalidated_reason" => row["invalidated_reason"],
      "semantic_change_reasons" => Map.get(row, "semantic_change_reasons", []),
      "semantic_change_details" => Map.get(row, "semantic_change_details", []),
      "changed_fields" => Map.get(row, "changed_fields", []),
      "candidate_diff_changed_fields" => Map.get(row, "candidate_diff_changed_fields", []),
      "candidate_diff_changed_field_count" => row["candidate_diff_changed_field_count"],
      "source_target_id" => row["source_target_id"],
      "source_target" => row["source_target"],
      "target_latitude_deg" => row["target_latitude_deg"],
      "target_longitude_deg" => row["target_longitude_deg"],
      "target_minimum_elevation_deg" => row["target_minimum_elevation_deg"],
      "target_priority" => row["target_priority"],
      "target_priority_source" => row["target_priority_source"],
      "target_priority_objective_ids" => row["target_priority_objective_ids"],
      "target_priority_objective_type" => row["target_priority_objective_type"],
      "candidate_diff_match_status" => row["candidate_diff_match_status"],
      "candidate_diff_match_count" => row["candidate_diff_match_count"],
      "semantic_match_status" => row["semantic_match_status"],
      "semantic_match_candidate_count" => row["semantic_match_candidate_count"],
      "semantic_match_candidate_ids" => row["semantic_match_candidate_ids"],
      "candidate_budget_match_status" => row["candidate_budget_match_status"],
      "candidate_budget_match_count" => row["candidate_budget_match_count"],
      "budget_dropped_candidate_ids" => row["budget_dropped_candidate_ids"]
    }
    |> Map.merge(candidate_diff_scoped_context(row))
    |> compact_map()
  end

  defp candidate_diff_for_replacement(candidate, context) do
    context
    |> Map.get("candidate_diff_by_replacement_id", %{})
    |> Map.get(activity_id(candidate))
    |> candidate_diff_match("replacement")
  end

  defp matches_repair_intent?(source, candidate, "downlink") do
    source_station_id = activity_ground_station_id(source)

    same_scenario?(source, candidate) and
      (is_nil(source_station_id) or source_station_id == activity_ground_station_id(candidate))
  end

  defp matches_repair_intent?(source, candidate, "observe") do
    source["target_id"] == candidate["target_id"]
  end

  defp matches_repair_intent?(_source, _candidate, _type), do: true

  defp add_activity(acc, activity), do: Map.update!(acc, :activities, &[activity | &1])

  defp use_replacement(acc, activity) do
    Map.update!(acc, :used_replacement_ids, &MapSet.put(&1, activity_id(activity)))
  end

  defp add_delta(
         acc,
         activity,
         realized,
         status,
         action,
         reason,
         replacement_id,
         requires_approval?,
         replacement_activity \\ nil
       ) do
    delta = %PlanDelta{
      activity_id: activity_id(activity),
      activity_type: activity["type"],
      status: status,
      planned: planned_snapshot(activity),
      realized: realized,
      repair_action: action,
      reason: reason,
      replacement_activity_id: replacement_id,
      source_timeline_id: activity_timeline_id(activity),
      replacement_timeline_id: replacement_timeline_id(replacement_activity),
      timeline_link: optional_timeline_link(activity, replacement_activity),
      source_activity_context: operational_activity_context(activity),
      replacement_activity_context: optional_operational_activity_context(replacement_activity),
      requires_approval: requires_approval?
    }

    Map.update!(acc, :deltas, &[delta | &1])
  end

  defp add_ambiguous_realized_delta(acc, activity, realized_rows, reason) do
    delta = %PlanDelta{
      activity_id: activity_id(activity),
      activity_type: activity["type"],
      status: "ambiguous_realized_feedback",
      planned: planned_snapshot(activity),
      repair_action: "review_realized_feedback",
      reason: reason,
      source_timeline_id: activity_timeline_id(activity),
      source_activity_context: operational_activity_context(activity),
      realized_feedback_rows: realized_rows,
      realized_feedback_count: length(realized_rows),
      requires_approval: true
    }

    Map.update!(acc, :deltas, &[delta | &1])
  end

  defp add_approval_requirement(acc, activity, action, reason) do
    requirement =
      %{
        "schema_contract" => "approval_requirement.v1",
        "activity_id" => activity_id(activity),
        "activity_type" => activity["type"],
        "requirement_type" => approval_requirement_type(action, activity),
        "action" => action,
        "reason" => reason,
        "activity_context" => operational_activity_context(activity)
      }
      |> drop_empty_activity_context()

    Map.update!(acc, :approval_requirements, &[requirement | &1])
  end

  defp approval_requirement_type("approve_moved_contact", _activity),
    do: "contact_schedule_change"

  defp approval_requirement_type("approve_reassigned_observation", _activity),
    do: "observation_reassignment"

  defp approval_requirement_type("approve_delayed_maneuver", _activity),
    do: "maneuver_timing_change"

  defp approval_requirement_type("review_downstream_window", _activity),
    do: "downstream_window_review"

  defp approval_requirement_type("review_realized_feedback", _activity),
    do: "realized_feedback_review"

  defp approval_requirement_type("approve_strategic_addition", _activity),
    do: "strategic_addition"

  defp approval_requirement_type("cancel", _activity), do: "cancellation"
  defp approval_requirement_type(_action, %{"type" => "command"}), do: "command_review"
  defp approval_requirement_type(_action, %{"type" => "health_check"}), do: "health_check_review"
  defp approval_requirement_type(_action, _activity), do: "operator_review"

  defp add_warning(acc, warning), do: Map.update!(acc, :warnings, &[warning | &1])

  defp planned_snapshot(activity) do
    Map.take(activity, [
      "id",
      "type",
      "scenario_id",
      "target_id",
      "ground_station_id",
      "starts_at_s",
      "ends_at_s",
      "duration_s",
      "score"
    ])
    |> Map.merge(operational_activity_context(activity))
  end

  defp operational_activity_context(activity) do
    Timeline.activity_context(activity)
  end

  defp timeline_link(source_activity, replacement_activity) do
    Timeline.timeline_link(source_activity, replacement_activity)
  end

  defp optional_timeline_link(_source_activity, nil), do: nil

  defp optional_timeline_link(source_activity, replacement_activity),
    do: timeline_link(source_activity, replacement_activity)

  defp optional_operational_activity_context(nil), do: nil

  defp optional_operational_activity_context(activity),
    do: operational_activity_context(activity)

  defp replacement_timeline_id(nil), do: nil
  defp replacement_timeline_id(activity), do: activity_timeline_id(activity)

  defp activity_timeline_id(activity) do
    activity["timeline_id"] ||
      activity["persistent_id"] ||
      get_in(activity, ["metadata", "timeline_id"]) ||
      get_in(activity, ["metadata", "persistent_id"]) ||
      derived_timeline_id(activity)
  end

  defp derived_timeline_id(activity) do
    [
      "timeline",
      activity["scenario_id"],
      activity["type"],
      activity_subject_id(activity),
      activity_source_window_id(activity) || activity_start(activity)
    ]
    |> Enum.reject(&is_nil/1)
    |> Enum.map(&encode_value/1)
    |> Enum.join(":")
  end

  defp activity_subject_id(activity) do
    activity["target_id"] ||
      activity_ground_station_id(activity) ||
      activity["spacecraft_id"] ||
      activity["resource_id"]
  end

  defp objective_ground_station_id(objective), do: activity_ground_station_id(objective)

  defp activity_ground_station_id(activity) do
    Map.get(activity, "ground_station_id") || Map.get(activity, "station_id") ||
      nested_ground_station_id(activity)
  end

  defp activity_source_window_id(activity) do
    activity["source_window_id"] ||
      get_in(activity, ["source_window", "id"]) ||
      get_in(activity, ["metadata", "source_window_id"])
  end

  defp drop_empty_activity_context(%{"activity_context" => context} = requirement)
       when map_size(context) == 0 do
    Map.delete(requirement, "activity_context")
  end

  defp drop_empty_activity_context(requirement), do: requirement

  defp plan_delta_to_map(%PlanDelta{} = delta) do
    %{
      "schema_contract" => "plan_delta.v1",
      "activity_id" => delta.activity_id,
      "activity_type" => delta.activity_type,
      "status" => delta.status,
      "planned" => delta.planned,
      "realized" => delta.realized,
      "repair_action" => delta.repair_action,
      "reason" => delta.reason,
      "replacement_activity_id" => delta.replacement_activity_id,
      "source_timeline_id" => delta.source_timeline_id,
      "replacement_timeline_id" => delta.replacement_timeline_id,
      "timeline_link" => delta.timeline_link,
      "source_activity_context" => delta.source_activity_context,
      "replacement_activity_context" => delta.replacement_activity_context,
      "realized_feedback_rows" => delta.realized_feedback_rows,
      "realized_feedback_count" => delta.realized_feedback_count,
      "requires_approval" => delta.requires_approval
    }
    |> Enum.reject(fn {_key, value} -> is_nil(value) end)
    |> Map.new()
  end

  defp preserved_activities(activities) do
    Enum.filter(activities, fn activity ->
      get_in(activity, ["repair", "action"]) in ["preserved", "preserved_executed"]
    end)
  end

  defp change_summary(deltas) do
    deltas
    |> Enum.group_by(& &1.repair_action)
    |> Map.new(fn {action, rows} -> {action, length(rows)} end)
  end

  defp timeline_protection_summary(activities, deltas) do
    preserved_locked_ids =
      activities
      |> Enum.filter(&(get_in(&1, ["repair", "reason"]) == "activity_locked_or_approved"))
      |> Enum.map(&activity_id/1)
      |> Enum.sort()

    preserved_executed_ids =
      activities
      |> Enum.filter(&(get_in(&1, ["repair", "action"]) == "preserved_executed"))
      |> Enum.map(&activity_id/1)
      |> Enum.sort()

    changed_locked_ids =
      deltas
      |> Enum.reject(&(&1.repair_action in ["preserved", "preserved_executed"]))
      |> Enum.filter(&locked_or_approved?(&1.planned || %{}))
      |> Enum.map(& &1.activity_id)
      |> Enum.sort()

    changed_executed_ids =
      deltas
      |> Enum.reject(&(&1.repair_action in ["preserved", "preserved_executed"]))
      |> Enum.filter(&(&1.status in @realized_preserved_executed_statuses))
      |> Enum.map(& &1.activity_id)
      |> Enum.sort()

    %{
      "preserved_locked_or_approved_count" => length(preserved_locked_ids),
      "preserved_executed_count" => length(preserved_executed_ids),
      "changed_locked_or_approved_count" => length(changed_locked_ids),
      "changed_executed_count" => length(changed_executed_ids),
      "preserved_locked_or_approved_activity_ids" => preserved_locked_ids,
      "preserved_executed_activity_ids" => preserved_executed_ids,
      "changed_locked_or_approved_activity_ids" => changed_locked_ids,
      "changed_executed_activity_ids" => changed_executed_ids
    }
  end

  defp repair_score_terms(activities, deltas, scoring_policy) do
    activity_score = activities |> Enum.map(&candidate_score/1) |> Enum.sum()

    churn_count =
      Enum.count(deltas, &(&1.repair_action in ["moved", "replaced", "canceled", "suppressed"]))

    moved_seconds =
      activities
      |> Enum.map(&(get_in(&1, ["repair", "schedule_churn_s"]) || 0.0))
      |> Enum.sum()

    churn_penalty =
      churn_count * numeric_policy_value(scoring_policy, "schedule_churn_cost_weight", 100.0)

    move_penalty =
      moved_seconds * numeric_policy_value(scoring_policy, "schedule_move_cost_weight", 0.01)

    %{
      "activity_score" => activity_score,
      "schedule_churn_penalty" => -churn_penalty,
      "schedule_move_penalty" => -move_penalty
    }
  end

  defp normalize_candidate_refresh(nil), do: nil

  defp normalize_candidate_refresh(candidate_refresh) do
    candidate_refresh = stringify_keys(candidate_refresh || %{})

    candidate_refresh =
      case candidate_refresh do
        %{"candidate_refresh" => %{} = nested} -> nested
        %{} -> candidate_refresh
      end
      |> normalize_candidate_refresh_freshness_report()

    case Schema.validate_artifact(candidate_refresh, schema_contract: "candidate_refresh.v1") do
      {:ok, _report} ->
        candidate_refresh

      {:error, report} ->
        raise ArgumentError, "invalid candidate_refresh.v1 artifact: #{inspect(report)}"
    end
  end

  defp normalize_candidate_refresh_request(nil), do: nil

  defp normalize_candidate_refresh_request(%{} = request), do: stringify_keys(request)

  defp normalize_candidate_refresh_request(_request) do
    raise ArgumentError, "candidate_refresh_request must be an object"
  end

  defp normalize_candidate_refresh_freshness_report(
         %{"freshness_report" => %{} = report} = refresh
       ) do
    Map.put(refresh, "freshness_report", normalize_freshness_report(report))
  end

  defp normalize_candidate_refresh_freshness_report(refresh), do: refresh

  defp normalize_freshness_report(report) do
    report = stringify_keys(report)
    state_quality_status = freshness_state_quality_status(report)
    stale_reasons = freshness_stale_reasons(report, state_quality_status)
    unknown_reasons = freshness_unknown_reasons(report, state_quality_status)

    report
    |> Map.put("stale_reasons", stale_reasons)
    |> Map.put("unknown_reasons", unknown_reasons)
    |> Map.put("status", freshness_status(stale_reasons, unknown_reasons))
    |> Map.put("state_quality_status", state_quality_status)
    |> Map.put_new("allowed_state_quality_levels", freshness_allowed_quality_levels(report))
    |> Map.put_new("model_limits", OrbitalDynamics.CandidateRefresh.model_limits())
  end

  defp freshness_stale_reasons(report, state_quality_status) do
    []
    |> maybe_append(freshness_snapshot_stale?(report), "accepted_snapshot_older_than_policy")
    |> maybe_append(
      freshness_horizon_stale?(report),
      "remaining_horizon_does_not_start_at_current_epoch"
    )
    |> maybe_append(
      state_quality_status == "not_accepted",
      "accepted_state_quality_below_policy"
    )
  end

  defp freshness_unknown_reasons(report, state_quality_status) do
    []
    |> maybe_append(
      not is_number(Map.get(report, "accepted_snapshot_age_s")),
      "accepted_snapshot_age_unknown"
    )
    |> maybe_append(
      not is_number(Map.get(report, "horizon_start_offset_s")),
      "horizon_alignment_unknown"
    )
    |> maybe_append(state_quality_status == "unknown", "accepted_state_quality_unknown")
  end

  defp freshness_snapshot_stale?(report) do
    age = Map.get(report, "accepted_snapshot_age_s")
    max_age = Map.get(report, "max_snapshot_age_s")

    is_number(age) and is_number(max_age) and age > max_age
  end

  defp freshness_horizon_stale?(report) do
    offset = Map.get(report, "horizon_start_offset_s")
    max_offset = Map.get(report, "max_horizon_start_offset_s")

    is_number(offset) and is_number(max_offset) and abs(offset) > max_offset
  end

  defp freshness_state_quality_status(report) do
    level = Map.get(report, "accepted_state_quality_level")
    allowed_levels = freshness_allowed_quality_levels(report)

    cond do
      not is_binary(level) -> "unknown"
      level in allowed_levels -> "accepted"
      true -> "not_accepted"
    end
  end

  defp freshness_allowed_quality_levels(%{"allowed_state_quality_levels" => levels})
       when is_list(levels) do
    levels
    |> Enum.filter(&is_binary/1)
    |> case do
      [] -> ["accepted", "planning_accepted"]
      values -> values
    end
  end

  defp freshness_allowed_quality_levels(_report), do: ["accepted", "planning_accepted"]

  defp freshness_status(stale_reasons, unknown_reasons) do
    cond do
      stale_reasons != [] -> "stale"
      unknown_reasons != [] -> "unknown"
      true -> "current"
    end
  end

  defp maybe_append(values, true, value), do: values ++ [value]
  defp maybe_append(values, false, _value), do: values

  defp inherit_candidate_refresh_approval_policy(nil, _approval_policy), do: nil

  defp inherit_candidate_refresh_approval_policy(request, nil), do: request

  defp inherit_candidate_refresh_approval_policy(
         %{"candidate_refresh" => %{} = refresh} = request,
         approval_policy
       ) do
    Map.put(
